# v1.18.6: 'collection' added so per-item API endpoints
# (manual-url, redownload, forget, info, etc.) accept the new
# media_type the user's v1.18.0 ship introduced. Pre-fix every
# /api/items/collection/<tmdb>/... POST returned 422 "Input
# should be 'movie' or 'tv'" because FastAPI's Literal
# validation rejected the URL path segment. Same Literal drives
# query-param validation on the few endpoints that accept
# media_type that way.
MediaType = Literal["movie", "tv", "collection"]


# v0.51.53: plex_items.media_type uses Plex's vocabulary {movie, show,
# collection}; every other table (themes / local_files / placements) uses
# motif's {movie, tv, collection}. The ONLY divergence is tv<->show; movie and
# collection are identical. Route plex_items.media_type -> motif conversions
# through this so a collection can never collapse to 'movie' (which orphans its
# theme from the media_type='collection'-keyed endpoints — the upload-theme mint
# bug the v0.51.47-49 forward sweep left standing in the reverse direction).
def _motif_media_type(plex_media_type: str) -> str:
    return "tv" if plex_media_type == "show" else plex_media_type


# ---- Helpers for /api/config PATCH ----
# Allow partial updates: caller sends a JSON dict whose structure mirrors
# MotifConfig. Only the leaf keys present get updated. The plex.token field
# has special semantics (empty string = leave alone; null = clear).

# v1.13.55: dashboard layout sanitizer. Extracted from the
# /api/dashboard/layout PUT endpoint so it's directly testable
# without scaffolding TestClient + auth. Drops malformed entries,
# coerces hidden to bool, dedupes by id, preserves order. Used by
# the PUT handler before persisting the JSON blob to
# runtime_settings.
def _clean_dashboard_sections(sections):
    cleaned: list[dict] = []
    seen_ids: set[str] = set()
    if not isinstance(sections, list):
        return cleaned
    for entry in sections:
        if not isinstance(entry, dict):
            continue
        sid = entry.get("id")
        if not isinstance(sid, str) or not sid or sid in seen_ids:
            continue
        seen_ids.add(sid)
        out = {
            "id": sid,
            "hidden": bool(entry.get("hidden", False)),
        }
        # v1.15.32: optional `cards` array per section. Each card
        # entry is {id, hidden}. Order is render order. Cards
        # belong to a section but may be moved between sections by
        # the user (the "id" is globally unique across the
        # dashboard — e.g. "user-provided" can sit under STORAGE
        # or get moved up to OPERATIONS). the user: "could reorder
        # and put user provided next to hardlinked or the row
        # above if I wanted." Same dedupe + bool-coerce shape as
        # the section list above.
        raw_cards = entry.get("cards")
        if isinstance(raw_cards, list):
            cards: list[dict] = []
            seen_card_ids: set[str] = set()
            for card in raw_cards:
                if not isinstance(card, dict):
                    continue
                cid = card.get("id")
                if (not isinstance(cid, str) or not cid
                        or cid in seen_card_ids):
                    continue
                seen_card_ids.add(cid)
                cards.append({
                    "id": cid,
                    "hidden": bool(card.get("hidden", False)),
                })
            if cards:
                out["cards"] = cards
        cleaned.append(out)
    return cleaned


_ALLOWED_TOP_LEVEL = {
    "paths", "plex", "downloads", "matching", "sync", "web", "runtime",
    # v1.13.26: "placement" was missing here. The settings page has a
    # PLACEMENT MODE block (// SAVE PLACEMENT button) but every save
    # returned 400 "unknown config section: placement", so users
    # couldn't actually disable auto_place from the UI even though
    # MotifConfig.placement: PlacementConfig has existed since
    # v1.5.3. Adding it here lights the toggle up end-to-end.
    "placement",
    # v1.17.0: NotificationsConfig — Apprise sinks + per-event toggles.
    # Persisted via /settings → NOTIFICATIONS tab.
    "notifications",
    # v1.23.16: DatabaseBackupConfig — scheduled backup cron + retention.
    # Persisted via /settings → DATABASE tab.
    "database_backup",
}


def _apply_partial_config(cfg, body: dict) -> None:
    """Mutate `cfg` in place from a partial JSON body. Raises ValueError
    on unknown sections or type mismatches."""
    for section_name, section_body in body.items():
        if section_name not in _ALLOWED_TOP_LEVEL:
            raise ValueError(f"unknown config section: {section_name}")
        if section_body is None:
            continue
        if not isinstance(section_body, dict):
            raise ValueError(f"section {section_name!r} must be an object")
        section = getattr(cfg, section_name)
        for k, v in section_body.items():
            if not hasattr(section, k):
                raise ValueError(f"unknown field: {section_name}.{k}")
            # Special: plex.token empty-string-or-mask = keep existing
            if section_name == "plex" and k == "token":
                if v == "" or v == "***":
                    continue
                if v is None:
                    setattr(section, k, "")
                    continue
            # Same for the optional API keys (legacy tvdb_api_key + new tmdb_api_key)
            if section_name == "plex" and k in ("tvdb_api_key", "tmdb_api_key"):
                if v == "" or v == "***":
                    continue
                if v is None:
                    setattr(section, k, "")
                    continue
            # v1.13.53: same mask semantics for downloads.proxy_url
            # (can carry inline credentials in the URL). Empty / "***"
            # = leave alone; null = clear.
            if section_name == "downloads" and k == "proxy_url":
                if v == "" or v == "***":
                    continue
                if v is None:
                    setattr(section, k, "")
                    continue
            # v1.21.15 (security M1): same mask semantics for
            # notifications.apprise_external_url (can carry basic-auth /
            # path token). Empty / "***" = keep existing; null = clear.
            if section_name == "notifications" and k == "apprise_external_url":
                if v == "" or v == "***":
                    continue
                if v is None:
                    setattr(section, k, "")
                    continue
            # v1.21.17 (security audit): sync.git_url / database_url are
            # masked-userinfo in GET (https://***@host/...). A round-tripped
            # value still carrying the `://***@` marker means "keep the
            # stored credential" — writing it back literally would corrupt
            # the PAT. Mirrors the plex.token '***' = keep contract.
            # v1.23.69 (audit): db_url is the 3rd credential-capable sync URL —
            # v1.23.62 added it to the GET mask but NOT here, so a standard SAVE
            # round-trip wrote the masked `https://***@host` back over a real
            # db_url credential (the GET masked it, the PATCH didn't keep-on-marker
            # it). Added so the keep-on-mask contract is symmetric across all three.
            if section_name == "sync" and k in ("git_url", "database_url", "db_url"):
                from ..core.config_file import _is_masked_url_credentials
                if isinstance(v, str) and _is_masked_url_credentials(v):
                    continue
            current = getattr(section, k)
            if isinstance(current, bool):
                if isinstance(v, str):
                    setattr(section, k, v.strip().lower() in ("1", "true", "yes", "on"))
                else:
                    setattr(section, k, bool(v))
            elif isinstance(current, int) and not isinstance(current, bool):
                setattr(section, k, int(v))
            elif isinstance(current, list):
                if not isinstance(v, list):
                    raise ValueError(f"{section_name}.{k} must be a list, got {type(v).__name__}")
                # v1.17.13: notifications.apprise_urls handles two
                # security concerns at PATCH time:
                #   1. Masked-form substitution — a "<scheme>://***"
                #      entry means "keep the existing URL at this
                #      position" (mirrors the plex.token / tmdb_api_key
                #      mask-equals-keep contract). Without this the
                #      GET-then-PATCH round-trip would overwrite
                #      every real URL with the masked placeholder
                #      string, deleting credentials silently.
                #   2. Scheme validation — apprise plugins accept a
                #      wide set of schemes; we reject obviously-
                #      dangerous ones (file://, ftp://, javascript:,
                #      etc.) so a malicious or careless paste can't
                #      route notifications anywhere apprise will dial.
                #      Security audit HIGH 2.
                if (section_name == "notifications"
                        and k == "apprise_urls"):
                    from ..core.config_file import (
                        _is_masked_apprise_url,
                        _validate_apprise_url_scheme,
                    )
                    new_list: list[str] = []
                    for i, item in enumerate(v):
                        s = str(item).strip()
                        if not s:
                            continue
                        if _is_masked_apprise_url(s):
                            if i < len(current):
                                new_list.append(current[i])
                            # else: client sent a masked entry beyond
                            # the existing list — drop silently
                            # (operator typed "***" by hand; no
                            # real URL to substitute).
                            continue
                        if not _validate_apprise_url_scheme(s):
                            raise ValueError(
                                f"notifications.apprise_urls[{i}]: "
                                f"scheme not allowed (got {s.split('://')[0] if '://' in s else s!r})"
                            )
                        new_list.append(s)
                    setattr(section, k, new_list)
                else:
                    setattr(section, k, [str(x) for x in v])
            elif isinstance(current, dict):
                # v1.17.0: NotificationsConfig.events is a dict of
                # bool keyed by event_kind. Merge partial updates
                # (don't replace wholesale — that would drop
                # event keys not in the partial body, breaking
                # forward-compatibility when new event kinds land
                # in newer versions). Coerce values to bool per
                # the same rules as scalar bool fields.
                #
                # v1.17.1: null = "leave alone" rather than 400 the
                # whole PATCH (a v1.17.x+ client may serialize the
                # dict as null to mean "no change"). Plus a closed-
                # set filter on `notifications.events` so unknown
                # event keys get dropped at PATCH time — pre-fix
                # `events: {"arbitrary_key": true}` landed in the
                # YAML permanently (same shape as the v1.14.60
                # silent-key-acceptance class).
                if v is None:
                    continue
                if not isinstance(v, dict):
                    raise ValueError(
                        f"{section_name}.{k} must be an object, "
                        f"got {type(v).__name__}")
                merged = dict(current)
                # v1.17.1: closed-set for notifications.events
                allowed_keys: set[str] | None = None
                if section_name == "notifications" and k == "events":
                    from ..core.config_file import _DEFAULT_NOTIFY_EVENTS
                    allowed_keys = set(_DEFAULT_NOTIFY_EVENTS.keys())
                for sub_k, sub_v in v.items():
                    if allowed_keys is not None and sub_k not in allowed_keys:
                        # v1.17.10: log.debug on dropped key.
                        # Pre-fix this was a fully silent drop —
                        # v1.17.4 added 6 UI toggles but forgot to
                        # extend _DEFAULT_NOTIFY_EVENTS; SAVE EVENTS
                        # auto-unchecked every one of them and there
                        # was no breadcrumb anywhere to explain why.
                        # Class-9. DEBUG (not WARNING) because a
                        # truly-bogus key from a stale client is
                        # expected to drop quietly; the breadcrumb
                        # exists so the next contract drift is
                        # diagnosable.
                        log.debug(
                            "_apply_partial_config: dropping unknown "
                            "events key %r (not in _DEFAULT_NOTIFY_EVENTS)",
                            sub_k,
                        )
                        continue
                    if isinstance(sub_v, str):
                        merged[sub_k] = sub_v.strip().lower() in (
                            "1", "true", "yes", "on")
                    else:
                        merged[sub_k] = bool(sub_v)
                setattr(section, k, merged)
            else:
                setattr(section, k, str(v) if v is not None else "")


# -------- Auth middleware --------

# v1.17.23: helpers for the forward-auth source-IP allowlist
# (Security HIGH 1) + the X-Authentik-Username sanitization
# (Security MED 6). Kept at module level so they're testable
# in isolation + easy to grep for.

_FORWARD_AUTH_USERNAME_MAX_LEN = 200

# Match any control character (C0 and C1) — strip them from
# usernames before logging / storing. Newlines are the most
# common log-injection vector but tab / NUL / DEL also have
# no business in a username.
_CONTROL_CHARS_RE = re.compile(r"[\x00-\x1f\x7f-\x9f]")


def _client_ip_in_allowlist(request: "Request", allowed: list[str]) -> bool:
    """v1.17.23: True if the request's client IP matches any
    entry in the forward-auth allowlist. Entries can be raw
    IPs ('172.17.0.5') or CIDR networks ('172.17.0.0/16').
    Malformed entries are skipped with a debug log breadcrumb;
    a single bad entry doesn't take down the allowlist.

    Fail-closed: if `request.client` is None (test harness,
    unusual proxy setup) we return False rather than implicit
    True — better to reject than mis-trust."""
    import ipaddress
    client = getattr(request, "client", None)
    if client is None or not getattr(client, "host", None):
        return False
    try:
        client_ip = ipaddress.ip_address(client.host)
    except (ValueError, TypeError):
        return False
    for entry in allowed:
        s = (entry or "").strip()
        if not s:
            continue
        try:
            net = ipaddress.ip_network(s, strict=False)
        except (ValueError, TypeError):
            log.debug(
                "forward_auth_allowed_ips: malformed entry %r — "
                "skipping. Use IPs (172.17.0.5) or CIDRs "
                "(172.17.0.0/16).", s,
            )
            continue
        if client_ip in net:
            return True
    return False


def _sanitize_forward_auth_username(value: str | None) -> str:
    """v1.17.23: defensive sanitization of the X-Authentik-
    Username / X-Forwarded-User header value before it flows
    into Principal.username, log lines, audit `updated_by`
    columns. Strips control chars + caps length + rejects
    empty / whitespace-only. Returns '' for unusable input
    (caller treats '' as "no forward-auth user")."""
    if not value:
        return ""
    s = str(value)
    # Strip control chars + collapse leading/trailing
    # whitespace. Pre-fix newlines / tabs / NULs in the header
    # would land verbatim in the events table.
    s = _CONTROL_CHARS_RE.sub("", s).strip()
    if len(s) > _FORWARD_AUTH_USERNAME_MAX_LEN:
        s = s[:_FORWARD_AUTH_USERNAME_MAX_LEN]
    return s


class AuthMiddleware(BaseHTTPMiddleware):
    """Resolve a Principal for every request and enforce auth on protected routes.

    Resolution order:
    1. Forward-auth header (when settings.trust_forward_auth) — admin scope
    2. API token (Authorization: Bearer or ?api_key=) — token's own scope
    3. Session cookie — admin scope (only one local user)
    4. Anonymous

    When admin setup hasn't run yet, every non-public request 302s to /setup.
    Otherwise, requests to protected routes without an authenticated Principal
    redirect to /login (for HTML) or return 401 (for JSON/API).
    """

    def __init__(self, app, *, settings: Settings):
        super().__init__(app)
        self.settings = settings

    def _is_public(self, path: str) -> bool:
        if path in PUBLIC_PATHS:
            return True
        return any(path.startswith(p) for p in PUBLIC_PREFIXES)

    def _resolve_principal(self, request: Request) -> Principal:
        # 1. Forward auth
        if self.settings.trust_forward_auth:
            # v1.17.23 (Security HIGH 1): restrict forward-auth trust to a
            # list of upstream proxy IPs.
            # v1.24.12 (Security): FAIL CLOSED on an empty allowlist. The old
            # behavior trusted X-Authentik-Username from ANY peer when
            # forward_auth_allowed_ips was empty ("legacy permissive") — an
            # admin-bypass footgun on a directly-reachable port (any LAN host
            # / container could send the header and be granted admin). Now the
            # header is trusted ONLY when the allowlist is set AND the client
            # IP matches; an empty allowlist OR a non-matching peer falls
            # through to API token / session / anonymous. main.py warns loudly
            # at boot when trust is on with an empty allowlist (forward-auth is
            # then a no-op until the operator sets the proxy IP).
            allowed = self.settings.forward_auth_allowed_ips
            if allowed and _client_ip_in_allowlist(request, allowed):
                user = (request.headers.get("X-Authentik-Username")
                        or request.headers.get("X-Forwarded-User"))
                # v1.17.23 (Security MED 6): sanitize the header value before
                # threading into Principal.username + logs + audit columns.
                # Pre-fix any control chars / newlines / >200-char garbage
                # landed verbatim in the events table.
                user = _sanitize_forward_auth_username(user)
                if user:
                    return Principal(username=user, scope="admin", auth_method="forward_auth")

        # 2. API token
        auth_header = request.headers.get("Authorization", "")
        token: str | None = None
        if auth_header.lower().startswith("bearer "):
            token = auth_header[7:].strip()
        elif "api_key" in request.query_params:
            token = request.query_params.get("api_key")
        if token:
            principal = authenticate_token(self.settings.db_path, token)
            if principal:
                return principal

        # 3. Session cookie
        sid = request.cookies.get(SESSION_COOKIE)
        if sid:
            username = lookup_session(self.settings.db_path, sid)
            if username:
                return Principal(username=username, scope="admin", auth_method="session")

        return ANONYMOUS

    async def dispatch(self, request: Request, call_next):
        path = request.url.path

        # Always resolve the principal first so handlers can read request.state.user
        request.state.principal = self._resolve_principal(request)
        request.state.user = request.state.principal.username

        # First-run gate: if no admin exists, force setup before anything else
        if not setup_complete(self.settings.db_path):
            if path == "/setup" or self._is_public(path):
                return await call_next(request)
            return RedirectResponse("/setup", status_code=302)

        if self._is_public(path):
            return await call_next(request)

        if request.state.principal.is_authenticated:
            return await call_next(request)

        # Not authenticated. JSON paths get 401, HTML paths get a redirect.
        wants_json = (
            path.startswith("/api/")
            or "application/json" in request.headers.get("accept", "")
        )
        if wants_json:
            return JSONResponse({"detail": "authentication required"}, status_code=401)
        # Preserve original URL so we can redirect back after login.
        # URL-encode so query strings with & or = don't bleed into our
        # own /login params (or open us up to redirect-injection via
        # crafted next= values).
        next_url = request.url.path
        if request.url.query:
            next_url += "?" + request.url.query
        return RedirectResponse(f"/login?next={quote(next_url, safe='/')}", status_code=302)


def _require_admin(request: Request) -> Principal:
    p: Principal = request.state.principal
    if not p.is_admin:
        raise HTTPException(status_code=403, detail="admin scope required")
    return p


def _capture_previous_url(
    conn, media_type: str, tmdb_id: int,
    *, section_id: str | None = None,
    on_purge: bool = False,
) -> None:
    """v1.12.37: snapshot the row's current canonical URL so REVERT
    can swap back one step. Called from any handler that's about to
    change the canonical URL (ACCEPT UPDATE, SET URL, UPLOAD MP3,
    REPLACE TDB, PURGE/UNMANAGE pre-drop).

    v1.12.86: writes to per-section previous_urls table (was the
    title-global themes.previous_youtube_url + previous_youtube_kind
    columns). Each section gets its own snapshot — pre-fix a PURGE
    in 4K then PURGE in standard overwrote 4K's slot, breaking
    RESTORE. Without section_id (legacy callers without row context)
    the snapshot lands at section_id='' which acts as a fallback for
    any section that doesn't have its own row.

    Resolution order for "current URL" (which we then snapshot):
      1. user_overrides.youtube_url for the given section_id (or
         '' global) — kind='user'.
      2. themes.youtube_url otherwise — kind='themerrdb'.
    A null URL produces a no-op (no INSERT). The library SQL hides
    REVERT/RESTORE on rows with no previous_urls entry.

    v1.12.102: on_purge=True triggers the 2-deep undo flow used by
    PURGE/UNMANAGE. Pre-fix the v1.12.99 user-kind preservation rule
    blocked these handlers from capturing the URL they were about to
    drop whenever a prior user-kind capture existed — RESTORE then
    brought back an older URL instead of the one just purged. New
    behavior: any existing previous_urls row is moved to the hidden_*
    slot (preserved for the post-RESTORE → REVERT step), then the
    just-dropped URL is written as the new previous_url regardless
    of kind. Non-purge captures (default) keep the old user-kind
    preservation rule and clear hidden_* on update — the hidden
    slot is only meaningful across a PURGE → RESTORE round-trip.
    """
    ovr = None
    if section_id is not None:
        ovr = conn.execute(
            "SELECT youtube_url FROM user_overrides "
            "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?",
            (media_type, tmdb_id, section_id),
        ).fetchone()
        if ovr is None or not ovr["youtube_url"]:
            ovr = conn.execute(
                "SELECT youtube_url FROM user_overrides "
                "WHERE media_type = ? AND tmdb_id = ? AND section_id = ''",
                (media_type, tmdb_id),
            ).fetchone()
    else:
        ovr = conn.execute(
            "SELECT youtube_url FROM user_overrides "
            "WHERE media_type = ? AND tmdb_id = ? AND section_id = ''",
            (media_type, tmdb_id),
        ).fetchone()
        if ovr is None or not ovr["youtube_url"]:
            ovr = conn.execute(
                "SELECT youtube_url FROM user_overrides "
                "WHERE media_type = ? AND tmdb_id = ? "
                "ORDER BY section_id LIMIT 1",
                (media_type, tmdb_id),
            ).fetchone()
    if ovr and ovr["youtube_url"]:
        prev_url = ovr["youtube_url"]
        prev_kind = "user"
    else:
        t = conn.execute(
            "SELECT youtube_url, upstream_source FROM themes "
            "WHERE media_type = ? AND tmdb_id = ?",
            (media_type, tmdb_id),
        ).fetchone()
        prev_url = t["youtube_url"] if t else None
        # v1.17.17: kind classification needs to respect
        # upstream_source. A `plex_orphan` row's youtube_url
        # is the URL captured during the original ADOPT — NOT a
        # ThemerrDB URL. Mis-labeling it 'themerrdb' caused the
        # v1.12.103 revert_redundant SQL branch to fire on
        # PURGE (it AND's kind='themerrdb' AND captured_url ==
        # themes.youtube_url), hiding RESTORE on orphan rows
        # post-PURGE — the user's screenshot, where RE-DOWNLOAD
        # TDB was the only visible recovery action despite the
        # row being plex_orphan (NO TDB). Calling orphan
        # captures 'user' is functionally correct: the worker
        # treats user-kind RESTORE as "write to user_overrides
        # + queue download from this URL," which is exactly the
        # right behavior for re-instating an adopted theme.
        if prev_url:
            if t and t["upstream_source"] == "plex_orphan":
                prev_kind = "user"
            else:
                prev_kind = "themerrdb"
        else:
            prev_kind = None
    if not prev_url or not prev_kind:
        return
    target_section = section_id if section_id is not None else ""
    existing = conn.execute(
        "SELECT youtube_url, kind, captured_at FROM previous_urls "
        "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?",
        (media_type, tmdb_id, target_section),
    ).fetchone()
    if on_purge:
        # v1.12.102: PURGE/UNMANAGE always captures the URL being
        # dropped. The prior previous_url (if any) moves into hidden_*
        # so REVERT after RESTORE walks back to it. The v1.12.99
        # user-kind preservation rule does NOT apply here — losing the
        # just-dropped URL would defeat RESTORE's whole purpose.
        # v1.12.105: if the existing previous_url already matches what
        # we're about to capture (same URL + same kind), the capture
        # is a no-op — the visible chain wouldn't change. Don't move
        # it to hidden either: that would create a degenerate
        # hidden==previous pair that still trips the
        # "hidden IS NOT NULL" gate in the redundancy check, hiding
        # RESTORE's correctly-redundant state. Early-return so the
        # existing row (and any pre-existing hidden slot it carries
        # from an earlier PURGE) survives untouched.
        if (existing
                and existing["youtube_url"] == prev_url
                and existing["kind"] == prev_kind):
            return
        hidden_url = existing["youtube_url"] if existing else None
        hidden_kind = existing["kind"] if existing else None
        hidden_captured_at = existing["captured_at"] if existing else None
        conn.execute(
            """INSERT INTO previous_urls
                 (media_type, tmdb_id, section_id, youtube_url, kind,
                  captured_at, hidden_url, hidden_kind, hidden_captured_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
               ON CONFLICT(media_type, tmdb_id, section_id) DO UPDATE SET
                   youtube_url = excluded.youtube_url,
                   kind = excluded.kind,
                   captured_at = excluded.captured_at,
                   hidden_url = excluded.hidden_url,
                   hidden_kind = excluded.hidden_kind,
                   hidden_captured_at = excluded.hidden_captured_at""",
            (media_type, tmdb_id, target_section, prev_url, prev_kind,
             now_iso(), hidden_url, hidden_kind, hidden_captured_at),
        )
        return
    # v1.12.99: don't overwrite a user-kind capture with a themerrdb-kind
    # one. Pre-fix the M*A*S*H scenario lost the user's URL through this
    # cascade:
    #   1. SET URL    → captures (no-op; orphan themes.youtube_url=NULL)
    #   2. ACCEPT URL → captures user override (kind=user) ✓
    #   3. PURGE      → user_overrides gone; capture falls to
    #                   themes.youtube_url (kind=themerrdb), OVERWRITING
    #                   step-2's user capture
    # User then has no RESTORE option (kind=themerrdb is functionally
    # DOWNLOAD TDB; revert_redundant=true). The user-kind URL they
    # explicitly set is gone forever.
    # New rule: themerrdb-kind captures don't clobber existing
    # user-kind captures. User-kind URLs are meaningful for one-step
    # undo; themerrdb URLs are always reachable via DOWNLOAD TDB
    # regardless of whether previous_urls knows about them.
    if prev_kind == "themerrdb" and existing and existing["kind"] == "user":
        return
    # v1.12.102: non-purge captures (SET URL, ACCEPT UPDATE, REPLACE
    # TDB, etc.) clear hidden_*. The hidden slot is meant to survive a
    # single PURGE → RESTORE round-trip; any other URL change
    # invalidates the chain (the user's not undoing the purge anymore).
    conn.execute(
        """INSERT INTO previous_urls
             (media_type, tmdb_id, section_id, youtube_url, kind,
              captured_at, hidden_url, hidden_kind, hidden_captured_at)
           VALUES (?, ?, ?, ?, ?, ?, NULL, NULL, NULL)
           ON CONFLICT(media_type, tmdb_id, section_id) DO UPDATE SET
               youtube_url = excluded.youtube_url,
               kind = excluded.kind,
               captured_at = excluded.captured_at,
               hidden_url = NULL,
               hidden_kind = NULL,
               hidden_captured_at = NULL""",
        (media_type, tmdb_id, target_section, prev_url, prev_kind, now_iso()),
    )


def _load_previous_url(
    conn, media_type: str, tmdb_id: int, *, section_id: str | None = None,
):
    """v1.12.86: read the one-step REVERT/RESTORE snapshot for a row.
    Returns the previous_urls row (youtube_url, kind, captured_at,
    plus the v1.12.102 hidden_* columns) or None when no snapshot
    exists. Resolution: section's own row first, then '' fallback —
    mirrors the user_overrides + worker URL-resolution pattern.
    """
    cols = ("youtube_url, kind, captured_at, "
            "hidden_url, hidden_kind, hidden_captured_at")
    if section_id is not None:
        row = conn.execute(
            f"SELECT {cols} FROM previous_urls "
            "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?",
            (media_type, tmdb_id, section_id),
        ).fetchone()
        if row:
            return row
    row = conn.execute(
        f"SELECT {cols} FROM previous_urls "
        "WHERE media_type = ? AND tmdb_id = ? AND section_id = ''",
        (media_type, tmdb_id),
    ).fetchone()
    return row


def _clear_previous_url(
    conn, media_type: str, tmdb_id: int, *, section_id: str | None = None,
) -> int:
    """v1.12.86: delete the previous_urls snapshot for a row. When
    section_id is provided, drops only that section's row (the ''
    fallback survives so other sections relying on it stay intact).
    Without section_id, drops every row for the title (matches the
    legacy semantics of clearing themes.previous_youtube_url).
    Returns rowcount for callers that want to log the result."""
    if section_id is not None:
        cur = conn.execute(
            "DELETE FROM previous_urls "
            "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?",
            (media_type, tmdb_id, section_id),
        )
    else:
        cur = conn.execute(
            "DELETE FROM previous_urls "
            "WHERE media_type = ? AND tmdb_id = ?",
            (media_type, tmdb_id),
        )
    return cur.rowcount


def _maybe_evict_empty_orphan(
    conn, media_type: str, tmdb_id: int,
) -> bool:
    """v1.18.15: drop a fully-empty orphan themes row + cascade
    children. Called from api_clear_url_override post-clear so the
    PURGE → CLEAR URL composition completes the cleanup that the
    removed DELETE button used to do in one step.

    Eviction conditions (ALL must hold):
      - themes row exists and has upstream_source = 'plex_orphan'
      - no remaining user_overrides for the (media_type, tmdb_id)
      - no remaining local_files for the (media_type, tmdb_id)
      - no remaining placements for the (media_type, tmdb_id)
      - no remaining previous_urls for the (media_type, tmdb_id)

    Returns True iff the row was evicted. Real TDB rows are never
    evicted: the next sync would just re-create them, and pruning
    them here would surprise the user. The check on each child
    table is across ALL sections — a sibling section's surviving
    state keeps the orphan alive even if THIS section's CLEAR URL
    drained its own slice. FK ON DELETE CASCADE on local_files /
    placements / pending_updates handles the children once the
    themes row drops; user_overrides has no FK so it's already
    been dropped explicitly by the upstream PURGE/UNMANAGE that
    led here. plex_items.theme_id is ON DELETE SET NULL.
    """
    theme = conn.execute(
        "SELECT id, upstream_source FROM themes "
        "WHERE media_type = ? AND tmdb_id = ?",
        (media_type, tmdb_id),
    ).fetchone()
    if theme is None:
        return False
    if theme["upstream_source"] != "plex_orphan":
        return False
    # All four guards must show zero remaining state. Each is a
    # cheap COUNT(*) on PK-indexed columns.
    for table in (
        "user_overrides", "local_files", "placements", "previous_urls",
    ):
        n = conn.execute(
            f"SELECT COUNT(*) AS n FROM {table} "
            f"WHERE media_type = ? AND tmdb_id = ?",
            (media_type, tmdb_id),
        ).fetchone()["n"]
        if n > 0:
            return False
    conn.execute(
        "DELETE FROM themes WHERE media_type = ? AND tmdb_id = ?",
        (media_type, tmdb_id),
    )
    return True


def _record_audit(
    conn, *, actor: str, action: str,
    media_type: str | None = None,
    tmdb_id: int | None = None,
    section_id: str | None = None,
    details: dict | None = None,
) -> None:
    """v1.12.80: append a row to audit_events — the long-lived
    provenance log for URL changes, override set/clear, accept/
    decline decisions, and destructive theme actions.

    Distinct from log_event (which uses the rolling `events`
    table). audit_events is intentionally not rotated: the goal
    is to be able to answer "who changed Willy Wonka's theme on
    2026-04-12, and what was it before?" months later.

    `details` is a free-form dict serialized to JSON. Each action
    documents its own keys; common ones include old_url, new_url,
    kind, scope.
    """
    payload = json.dumps(details, separators=(",", ":")) if details else None
    conn.execute(
        """INSERT INTO audit_events
             (occurred_at, actor, action, media_type, tmdb_id,
              section_id, details)
           VALUES (?, ?, ?, ?, ?, ?, ?)""",
        (now_iso(), actor, action, media_type, tmdb_id,
         section_id, payload),
    )


def _cancel_jobs_for_row(
    conn,
    *,
    media_type: str,
    tmdb_id: int,
    section_id: str | None = None,
) -> int:
    """v1.18.73 (HIGH-B audit): cancel any pending/running jobs
    for (media_type, tmdb_id[, section_id]) so a destructive
    endpoint can sweep the row's tracking without racing an
    in-flight worker that's about to write to it.

    Called from api_unplace_item, api_forget_item (both branches,
    v1.22.76), api_unmanage_item (v1.22.76), and api_delete_item
    before their DELETE FROM ... blocks fire.
    Worker `_mark_*` paths all guard on `WHERE status='running'`
    so a cancellation here propagates correctly even if the
    worker is mid-dispatch — by the time the worker tries to
    promote the job from 'running' to 'done' / 'pending' /
    'failed', the cancel UPDATE has already flipped it to
    'cancelled' and the worker's WHERE clause matches zero rows
    (logged as `_mark_failed no-op for job N (likely
    force-cancelled)` per v1.14.25 H1).

    Job kinds cancelled: place, download, refresh, relink,
    adopt, scan. Every per-row worker handler. Bulk ops
    (bulk_lps, bulk_probe_tdb, tvdb_bridge, plex_enum,
    tdb_sync) operate on op_progress rows, not per-row job
    queue rows — out of scope here.

    Returns the count of cancelled rows for the caller's
    logging.
    """
    PER_ROW_JOB_KINDS = (
        "place", "download", "refresh", "relink", "adopt", "scan",
    )
    qmarks = ",".join("?" for _ in PER_ROW_JOB_KINDS)
    if section_id:
        cur = conn.execute(
            f"""UPDATE jobs SET status = 'cancelled',
                                 finished_at = ?
                 WHERE job_type IN ({qmarks})
                   AND media_type = ? AND tmdb_id = ?
                   AND section_id = ?
                   AND status IN ('pending', 'running')""",
            (now_iso(), *PER_ROW_JOB_KINDS,
             media_type, tmdb_id, section_id),
        )
    else:
        cur = conn.execute(
            f"""UPDATE jobs SET status = 'cancelled',
                                 finished_at = ?
                 WHERE job_type IN ({qmarks})
                   AND media_type = ? AND tmdb_id = ?
                   AND status IN ('pending', 'running')""",
            (now_iso(), *PER_ROW_JOB_KINDS,
             media_type, tmdb_id),
        )
    if cur.rowcount:
        log.info(
            "_cancel_jobs_for_row: cancelled %d job(s) for "
            "%s/%s section_id=%s before destructive sweep",
            cur.rowcount, media_type, tmdb_id, section_id or "*",
        )
    return cur.rowcount


def _teardown_plex_api_artifacts_for_placements(
    db: Path, settings,
    media_type: str, tmdb_id: int,
    placements,
) -> int:
    """v1.18.60: shared helper — DELETE motif's API-uploaded theme
    entries from Plex for any placement_kind='plex_upload' row in
    the given list. Returns count of successful delete_theme calls.

    Mirrors the v1.18.36 SWITCH api→file teardown EXACTLY. Extracted
    to a shared helper because the v1.18.60 audit found three more
    callsites that hit the same end state ("motif is removing/
    transitioning away from a plex_upload placement") but never
    cleared Plex's selection:

      - api_forget_item (PURGE)  — drops DB row, leaves Plex serving
        motif's uploaded theme until something else clears it
      - api_delete_item (DELETE) — same shape as PURGE
      - api_replace_item with kind='file' on a prior plex_upload —
        new sidecar appears but Plex's theme resolution may still
        serve motif's API entry over the new sidecar

    Idempotent: plex.delete_theme returns False if the entry is
    already gone (404 from singular /theme). No-op when:
      - Plex isn't configured (no token / disabled)
      - No placements in the list have placement_kind='plex_upload'
      - The Plex client can't be constructed (network / config)

    Logs each operation at INFO so the cleanup is visible in
    docker logs alongside the existing SWITCH-path logs. Per-row
    failures log WARN and continue — best-effort cleanup, the
    orphan scan will surface anything that survives.
    """
    if not settings.plex_enabled or not settings.plex_token:
        return 0
    plex_upload_placements = [
        pr for pr in placements
        if (pr["placement_kind"] or "") == "plex_upload"
    ]
    if not plex_upload_placements:
        return 0
    from ..core.plex import PlexClient, PlexConfig
    cfg = PlexConfig(
        url=settings.plex_url, token=settings.plex_token,
        movie_section=settings.plex_movie_section,
        tv_section=settings.plex_tv_section, enabled=True,
    )
    # v1.18.61: map all three motif media_types to their
    # plex_items.media_type values. Pre-fix this defaulted to
    # 'movie' for any non-'tv' value — collections (media_type=
    # 'collection') got 'movie' lookups, so the fallback rk
    # query at the per-row level (`WHERE guid_tmdb=? AND
    # media_type='movie'`) silently missed every collection row
    # whose theme_id JOIN didn't return a hit (orphan promotion
    # races, pre-resolve windows, fresh installs). The primary
    # theme_id JOIN usually succeeded so the bug was rarely
    # visible, but the audit guard for v1.18.60 didn't catch it.
    _PLEX_MT_MAP = {"tv": "show", "collection": "collection"}
    plex_mt = _PLEX_MT_MAP.get(media_type, "movie")
    deleted_count = 0
    try:
        with PlexClient(
            cfg, plus_mode=settings.plus_equiv_mode,
        ) as plex, get_conn(db) as conn:
            tid_row = conn.execute(
                "SELECT id FROM themes "
                "WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            tid_pk = tid_row["id"] if tid_row else None
            for pr in plex_upload_placements:
                section = pr["section_id"]
                # v1.23.65 (audit #9): scope the rk lookup to THIS placement's
                # edition. Pre-fix both lookups resolved by (theme_id|guid,
                # section) only, so on a multi-edition title sharing a section
                # (the user's LotR/Watchmen — 3 distinct rks, distinct
                # plex_upload placements) fetchone() returned an ARBITRARY
                # sibling's rk → PURGE/DELETE on one edition ran delete_theme
                # against another edition's rk, clearing Plex's selection for the
                # wrong edition. The inline api_replace_item teardown got this
                # right in v1.21.69 (_repl_ed_clause); the shared helper was
                # missed. Each placement carries its own edition_key (PK), so the
                # match resolves the correct rk per edition.
                _pr_ed = (pr["edition_key"]
                          if "edition_key" in pr.keys() else "")
                rk_row = None
                if tid_pk is not None:
                    rk_row = conn.execute(
                        "SELECT rating_key FROM plex_items "
                        "WHERE theme_id = ? AND section_id = ? "
                        "  AND edition_key = ?",
                        (tid_pk, section, _pr_ed),
                    ).fetchone()
                if rk_row is None:
                    rk_row = conn.execute(
                        "SELECT rating_key FROM plex_items "
                        "WHERE guid_tmdb = ? AND media_type = ? "
                        "  AND section_id = ? AND edition_key = ?",
                        (str(tmdb_id), plex_mt, section, _pr_ed),
                    ).fetchone()
                if rk_row is None:
                    log.warning(
                        "teardown_plex_api[%s/%s]: no rating_key "
                        "for section_id=%s — skipping Plex API "
                        "delete_theme",
                        media_type, tmdb_id, section,
                    )
                    continue
                rk = rk_row["rating_key"]
                try:
                    ok = plex.delete_theme(rating_key=rk)
                except Exception as e:  # noqa: BLE001
                    log.warning(
                        "teardown_plex_api[%s/%s]: delete_theme "
                        "rk=%s raised: %s",
                        media_type, tmdb_id, rk, e,
                    )
                    continue
                if ok:
                    deleted_count += 1
                log.info(
                    "teardown_plex_api[%s/%s]: rk=%s "
                    "delete_theme=%s section_id=%s",
                    media_type, tmdb_id, rk, ok, section,
                )
    except Exception as e:  # noqa: BLE001
        log.warning(
            "teardown_plex_api[%s/%s]: client setup / outer "
            "loop failed: %s",
            media_type, tmdb_id, e,
        )
    return deleted_count


def _set_pending_update_decision(
    conn, *, media_type: str, tmdb_id: int,
    section_id: str | None, decision: str, decided_by: str,
    edition_key: str = "",
) -> int:
    """v1.12.99: record a user's accept/decline on the per-section
    pending_updates row for a (media_type, tmdb_id, section_id) tuple.

    Schema v31 made pending_updates per-section. The user's decision
    lives at section_id-specific rows so KEEP CURRENT on standard
    doesn't bleed to 4K. The title-global '' row written by sync
    survives as the "default" any section without its own decision
    inherits — the library SQL's pu_sec / pu_global LEFT JOIN with
    COALESCE picks per-section first, '' second.

    Implementation:
      1. Read the effective pending update for the requested section
         (per-section first, '' fallback) — this provides the values
         to copy (new_youtube_url, kind, etc.).
      2. UPSERT into the section-specific row with the new decision.
         The '' row stays untouched so other sections still see
         their inherited pending state.

    Returns 1 when a row was written, 0 when no pending_update
    existed for the (mt, tmdb) tuple to act on.
    """
    section = section_id if section_id is not None else ""
    # v1.21.81: the detection (kind/url) always lives at edition_key=''
    # (sync writes it edition-blind). Read it from '' so the decision row
    # we write for THIS edition copies the canonical detection data.
    src = conn.execute(
        """SELECT new_video_id, new_youtube_url, old_youtube_url,
                  upstream_edited_at, detected_at, kind
             FROM pending_updates
            WHERE media_type = ? AND tmdb_id = ?
              AND section_id IN (?, '') AND edition_key = ''
            ORDER BY (section_id = ?) DESC
            LIMIT 1""",
        (media_type, tmdb_id, section, section),
    ).fetchone()
    if src is None:
        return 0
    # v1.21.81: write the decision at THIS row's edition_key (default ''
    # = standard, the old per-section behavior). A non-standard edition
    # gets its own (section, edition) decision row copying the '' detection
    # data, so ACCEPT/DECLINE on one edition leaves siblings' pending state
    # untouched. The kind/url helpers + pu_sec/pu_global JOINs read the ''
    # detection, so the duplicated copy never confuses the pill render.
    conn.execute(
        """INSERT INTO pending_updates (
              media_type, tmdb_id, section_id, edition_key,
              new_video_id, new_youtube_url, old_youtube_url,
              upstream_edited_at, detected_at, decision,
              decision_at, decision_by, kind
           ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
           ON CONFLICT(media_type, tmdb_id, section_id, edition_key) DO UPDATE SET
               decision = excluded.decision,
               decision_at = excluded.decision_at,
               decision_by = excluded.decision_by""",
        (media_type, tmdb_id, section, edition_key,
         src["new_video_id"], src["new_youtube_url"], src["old_youtube_url"],
         src["upstream_edited_at"], src["detected_at"], decision,
         now_iso(), decided_by, src["kind"]),
    )
    return 1


# v1.20.10: the new_theme_available resolver moved to core.sync
# (resolve_new_theme_pending_update) and is now called from the worker's
# post-download success path (_record_local_file) — so the blue !UPD pill
# clears when motif actually HOLDS the TDB theme, not optimistically at
# click time. See the v1.20.10 journal + Finding 2 of the silent-bug audit.


def _drop_motif_tracking(conn, media_type: str, tmdb_id: int,
                         acted_edition: str | None = None) -> None:
    """v1.12.57: drop motif's tracking metadata for a title — the
    rows that aren't tied to actual files on disk but persist
    motif's "what should we do with this title" decisions:
      - user_overrides (manual URL override)
      - pending_updates (any decision: pending / accepted / declined)

    Called from PURGE, UNMANAGE, and DEL so those actions truly
    leave a clean slate. Pre-fix the rows survived even after the
    user destroyed every on-disk file: the next download or sync
    re-applied the stale override URL or re-surfaced the stale
    pending update, undoing the user's intent.

    Safe to call BEFORE the themes row is dropped — the FK
    CASCADE handles pending_updates, but user_overrides has no FK
    and would otherwise survive.

    v1.12.64: themes.previous_youtube_url + previous_youtube_kind
    are NO LONGER cleared here. Per user feedback, the previous-URL
    snapshot should survive PURGE/UNMANAGE so the user retains a
    one-step RESTORE path (REVERT button stays surfaced when
    revert_redundant is false). The user can still wipe the
    snapshot explicitly via CLEAR URL before destruction if they
    want a true clean slate. DEL drops the themes row anyway, so
    previous_* go with it via row deletion.
    """
    # v1.22.23 (edition audit): when an edition-scoped action (UNMANAGE /
    # FORGET with a rating_key) reaches its last_section, clear the title-
    # global '' decisions (the v1.12.57 clean-slate intent — a stale ''
    # override re-applies on the next download) PLUS the acted edition's, but
    # SPARE other editions' per-edition decisions. Pre-fix the title-wide wipe
    # took a sibling pure-P edition's own override/pending with it when the
    # last file-bearing edition was purged. acted_edition=None (DELETE, which
    # nukes the whole title, and the legacy global UNMANAGE/PURGE branches)
    # keeps the full title-wide wipe.
    if acted_edition is not None:
        ed_clause = " AND (edition_key = '' OR edition_key = ?)"
        ed_args: tuple = (acted_edition,)
    else:
        ed_clause = ""
        ed_args = ()
    conn.execute(
        "DELETE FROM user_overrides WHERE media_type = ? AND tmdb_id = ?"
        + ed_clause,
        (media_type, tmdb_id, *ed_args),
    )
    conn.execute(
        "DELETE FROM pending_updates WHERE media_type = ? AND tmdb_id = ?"
        + ed_clause,
        (media_type, tmdb_id, *ed_args),
    )


# v1.12.95: canonical SQL expression for the row's SRC letter. Mirrors
# JS computeSrcLetter exactly — same priority order, same fallthrough
# logic — so the pill filter, the SRC sort, and the row badge all
# agree on what SRC class a row belongs to. Pre-fix the pill SQL and
# sort SQL each had their own simpler heuristic (provenance-first)
# and could disagree with the JS render on rows where source_kind
# disagreed with placement.provenance.
#
# Ordering matches JS:
#   1. placed + source_kind=themerrdb → T
#   2. placed + source_kind=adopt     → A
#   3. placed + source_kind=url|upload → U
#   4. placed + provenance=auto        → T (legacy fallback for rows
#                                          without source_kind)
#   5. placed + provenance=manual:
#        non-orphan OR svid is empty OR svid length=11 → U
#                                          else        → A
#   6. !placed + plex_local_theme → M
#   7. !placed + has_theme        → P
#   8. else                       → '-'
#
# The length(svid)=11 check approximates the JS regex
# /^[A-Za-z0-9_-]{11}$/ — adopt's hash-based svids are not 11 chars,
# YouTube video IDs are exactly 11 chars. Empty svid handled
# separately via COALESCE.
#
# v1.19.40 doc: this SQL form uses `p.media_folder IS NOT NULL`
# to detect "placed" — and converges with the JS
# `!!media_folder || placement_kind === 'plex_upload'` shape
# ONLY because schema v55's `placements.media_folder TEXT NOT
# NULL` guarantees plex_upload rows store empty string `''`
# (never NULL). A future writer that bypasses the schema and
# inserts NULL would silently disagree with the JS — both
# branches would then misclassify the row. The SRC-axis
# mirror-drift guard tests (test_v1_19_38_src_axis_*.py) pin
# this contract on both sides.
def _src_letter_sql(
    media_folder: str = "p.media_folder",
    provenance: str = "p.provenance",
    source_kind: str = "lf.source_kind",
    source_video_id: str = "lf.source_video_id",
) -> str:
    """The SRC-letter CASE, parameterized over the placement/local_files
    column expressions (v1.21.57). Default args reproduce the pre-v1.21.57
    bare-alias SQL EXACTLY, so every existing call site stays byte-identical
    (guarded by test_v1_21_57). The per-edition library query (v1.21.58)
    passes edition-aware COALESCE(p_e.x, p_g.x) forms instead. pi.*/t.* refs
    aren't edition-split, so they stay fixed."""
    return (
        "CASE "
        f"WHEN {media_folder} IS NOT NULL AND {source_kind} = 'themerrdb' THEN 'T' "
        f"WHEN {media_folder} IS NOT NULL AND {source_kind} = 'adopt' THEN 'A' "
        f"WHEN {media_folder} IS NOT NULL AND {source_kind} IN ('url','upload') THEN 'U' "
        # v1.20.65: a PROMOTED cloud-backup row (placement_kind='plex_upload'
        # → media_folder='', source_kind='plex_cloud') is Plex's OWN cloud
        # theme re-deployed from motif's backup — no ThemerrDB, no user URL.
        # It rendered 'T' via the provenance='auto' fallback below; render
        # 'P' (the letter it showed pre-PROMOTE — PROMOTE changes placement
        # ownership, not content source). the user's call. Mirror in
        # computeSrcLetter. NOTE: this is the only PLACED row that renders P,
        # so SRC='P' here is a display choice; _not_p_row_sql (pure-P =
        # motif owns no placement) correctly still treats it as NOT pure-P.
        f"WHEN {media_folder} IS NOT NULL AND {source_kind} = 'plex_cloud' THEN 'P' "
        f"WHEN {media_folder} IS NOT NULL AND {provenance} = 'auto' THEN 'T' "
        f"WHEN {media_folder} IS NOT NULL AND {provenance} = 'manual' AND ("
            "t.upstream_source != 'plex_orphan' "
            f"OR COALESCE({source_video_id}, '') = '' "
            f"OR length({source_video_id}) = 11 "
            # v1.14.0: SoundCloud IDs are sc-<artist>-<slug>, longer
            # than 11 chars but recognizably non-adopt. Without this
            # branch SC user-URLs got tagged 'A' (adopt) instead of
            # 'U'. The sc- prefix is set by extract_video_id in
            # sync.py for any SoundCloud URL.
            # v1.20.42: ig-<shortcode> (Instagram, v1.20.26) needs the
            # same treatment — a manual IG override on an orphan row is a
            # user URL ('U'), not an adopt ('A'). Mirror in computeSrcLetter.
            # v1.22.90: fb-<id> (Facebook) joins the same family.
            f"OR {source_video_id} LIKE 'sc-%' "
            f"OR {source_video_id} LIKE 'ig-%' "
            f"OR {source_video_id} LIKE 'fb-%'"
        ") THEN 'U' "
        f"WHEN {media_folder} IS NOT NULL AND {provenance} = 'manual' THEN 'A' "
        f"WHEN {media_folder} IS NULL AND pi.local_theme_file = 1 THEN 'M' "
        # v1.12.112: 'P' = Plex actually serves a theme for this row.
        # has_theme=1 alone is just Plex's CLAIM (the `theme="..."` XML
        # attribute, which can come from themerr-plex embeds, Plex Pass
        # cloud themes, sidecars Plex saw at some point, OR a stale
        # metadata cache pointing at a file that's been deleted). The
        # plex_theme_verified_ok column is the source-of-truth: 1=HEAD
        # against /library/metadata/{rk}/theme returned 200, 0=404,
        # NULL=untested. We trust the claim optimistically when untested
        # (COALESCE to 1) so a fresh install / network blip doesn't drop
        # P's; only definitively-stale (verified_ok=0) falls through.
        # plex_enum runs the verification opportunistically for ambiguous
        # rows (has_theme=1 + local_theme_file=0) and resets it when
        # Plex's URI changes. Reverts v1.12.111's media_type='tv' gate —
        # that wrongly hid legitimate themerr-plex embeds on movies.
        f"WHEN {media_folder} IS NULL AND pi.has_theme = 1 "
            "AND COALESCE(pi.plex_theme_verified_ok, 1) = 1 THEN 'P' "
        "ELSE '-' END"
    )


_SRC_LETTER_SQL = _src_letter_sql()
# v1.24.28: a STALE plex_upload (its uploaded rating_key was destroyed by a Plex
# delete+re-add, stamped theme_present=0 by verify_placement_health) is no longer
# served by Plex — treat it as NOT placed. This effective-media_folder nulls it
# out so SRC falls through to '-' and the placed/PL reads everywhere that key off
# media_folder go false. The single source of truth for "stale plex_upload":
# placement_kind='plex_upload' AND theme_present=0. Mirrored in the SELECT's
# media_folder/placement_kind output + the needs_repush flag below.
_LIB_STALE_PU_SQL = (
    "COALESCE(p_e.placement_kind, p_g.placement_kind) = 'plex_upload' "
    "AND COALESCE(p_e.theme_present, p_g.theme_present) = 0 "
    # v1.24.40: require the uploaded rating_key is genuinely DEAD (no live
    # plex_items row). theme_present is a point-in-time stamp; when a placement
    # is re-linked to a now-live rk (reconcile / the v1.24.27 re-link) without
    # re-stamping, the stale 0 would falsely read RP until the next enum's
    # verify_placement_health re-stamps it to 1. Checking rk-liveness at READ
    # time self-corrects it — matching the v1.24.28 model (re-push = the upload's
    # rk was DESTROYED by a delete+re-add). the user's Two Towers: placement rk
    # 714913 is live with has_theme=1 → served, NOT re-push needed.
    # v1.24.41 (review #4): require a non-NULL stored rk. Without this a legacy
    # plex_upload that never stored a rating_key makes `rating_key = COALESCE(NULL,
    # NULL)` (which matches nothing) → NOT EXISTS vacuously TRUE → it would read
    # RP purely for being NULL, not for being genuinely stale. A NULL rk also has
    # nothing to re-push TO. Matches _REPUSH_COUNT's guard so count == render.
    "AND COALESCE(p_e.plex_rating_key, p_g.plex_rating_key) IS NOT NULL "
    "AND NOT EXISTS (SELECT 1 FROM plex_items pi_rp "
    "                WHERE pi_rp.rating_key "
    "                      = COALESCE(p_e.plex_rating_key, p_g.plex_rating_key))")
_LIB_EFF_MEDIA_FOLDER = (
    f"CASE WHEN {_LIB_STALE_PU_SQL} THEN NULL "
    "ELSE COALESCE(p_e.media_folder, p_g.media_folder) END")
# v1.24.40/.41: genuinely-dead-RP count for the topbar RE-PUSH badge + /api/stats.
# v1.24.41 (review #1/#2/#4): MUST mirror the render, not count bare placements.
# The v1.24.40 count was `FROM placements p`, but the library renders FROM
# plex_items (LEFT JOIN placements by edition) — so a stale plex_upload whose Plex
# item was REMOVED (no live plex_items row; the v1.18.89 reaper deletes plex_items
# but delete_superseded_sidecar_placement spares the plex_upload placement) was
# COUNTED yet never rendered → the badge lit a count the linked page couldn't
# surface. Anchor the count on the SAME plex_items + two-tier p_e/p_g shape the
# render uses, gated with the SAME _LIB_STALE_PU_SQL predicate, so count ==
# rendered RP rows by construction (the p_g `<=1` multi-edition gate also dedups
# a '' + per-edition double-upload). Aliases pi/t/p_e/p_g match what
# _LIB_STALE_PU_SQL interpolates; pi_rp (its rk-liveness subquery) doesn't collide
# with the anchor pi.
_REPUSH_COUNT_FROM = (
    "FROM plex_items pi "
    "INNER JOIN plex_sections ps "
    "  ON ps.section_id = pi.section_id AND ps.included = 1 "
    "LEFT JOIN themes t ON t.id = pi.theme_id "
    "LEFT JOIN placements p_e "
    "  ON p_e.media_type = t.media_type AND p_e.tmdb_id = t.tmdb_id "
    " AND p_e.section_id = pi.section_id AND p_e.edition_key = pi.edition_key "
    "LEFT JOIN placements p_g "
    "  ON p_g.media_type = t.media_type AND p_g.tmdb_id = t.tmdb_id "
    " AND p_g.section_id = pi.section_id AND p_g.edition_key = '' "
    " AND (SELECT COUNT(DISTINCT _ec.edition_key) FROM plex_items _ec "
    "      WHERE _ec.theme_id = pi.theme_id AND _ec.section_id = pi.section_id) <= 1")
_REPUSH_COUNT_SQL = f"SELECT COUNT(*) {_REPUSH_COUNT_FROM} WHERE {_LIB_STALE_PU_SQL}"
# v1.24.43: AWAIT topbar badge — a count of `!P` rows (a theme is DOWNLOADED but
# not deployed: canonical present, no placement, Plex not self-serving). the user
# wanted these surfaced like FAIL instead of having to filter to ATTN=!P.
# _LIB_AWAIT_SQL is the predicate behind the attn_pills=await FILTER and the
# PL=await row state — "downloaded but not placed" (canonical present, no
# placement, Plex not self-serving).
# v0.50.34: the topbar AWAIT badge that also consumed this (via a COUNT) was
# removed — it flickered in during the download→place handoff and duplicated
# RE-PUSH (the user). The filter + the PL=await row state stay; the badge's count
# + per-tab-breakdown SQL went with it.
# v1.24.46: exclude rows terminal-failed with plex_rejected:over_ceiling. Those
# are over-Plex-ceiling collection themes with no sidecar fallback — they show the
# red ⊘ "too large, can't place" row glyph (v1.24.45), so counting them as AWAIT
# ("downloaded, click to PLACE") double-surfaced one doomed row + re-enqueued the
# doomed upload on click. They're not actionable until the user shortens the theme,
# so they don't belong in the AWAIT filter. NULL-safe `IS NOT` keeps NULL +
# every other reason (incl. genuinely-retriable rows) in AWAIT.
_LIB_AWAIT_SQL = (
    "(COALESCE(lf_e.file_path, lf_g.file_path) IS NOT NULL "
    " AND COALESCE(p_e.media_folder, p_g.media_folder) IS NULL "
    " AND COALESCE(pi.plex_independent_theme, 0) = 0 "
    " AND COALESCE(lf_e.last_place_attempt_reason, lf_g.last_place_attempt_reason) "
    "     IS NOT 'plex_rejected:over_ceiling' "
    # v0.51.36 (the user): a backup-only row (DOWNLOAD TDB BACKUP → TB badge,
    # deferring to Plex) is terminal, not "downloaded, click to PLACE" — exclude
    # it like the over-ceiling reason above so it doesn't pollute the AWAIT
    # filter/attention. NULL-safe IS NOT keeps every other reason in AWAIT.
    " AND COALESCE(lf_e.last_place_attempt_reason, lf_g.last_place_attempt_reason) "
    "     IS NOT 'backup_only')")
# v1.24.44: per-(tab, fourk) breakdown for the RE-PUSH badge so the topbar pill
# CYCLES through every impacted section on successive clicks (incl. collections) —
# like FAIL/UPD. Same plex_items-anchored shape as the count.
_REPUSH_TAB_BREAKDOWN_SQL = (
    f"SELECT ps.type, ps.is_anime, ps.is_4k, pi.media_type AS item_media_type, "
    f"COUNT(*) AS n {_REPUSH_COUNT_FROM} WHERE {_LIB_STALE_PU_SQL} "
    f"GROUP BY ps.type, ps.is_anime, ps.is_4k, pi.media_type "
    f"ORDER BY ps.is_anime, ps.type, ps.is_4k")


def _breakdown_tabs(rows):
    # v1.24.47: map per-(section-type, anime, 4k, media_type) breakdown rows to the
    # {tab, fourk, count} list the topbar cycle badges iterate, DEDUPED by
    # (tab, fourk). The GROUP BY emits one row per (type, is_anime, is_4k,
    # media_type), but several collapse to one tab — an anime-section AND a
    # movie-section collection both route to 'collections' — so the cycle saw two
    # identical destinations and a click "advancing to the next" landed on the URL
    # you were already on (a dead click). Order-preserving (first occurrence keeps
    # the slot, so [0] stays the deterministic owner); collapsed counts sum. Shared
    # by the bindBadgeCycle family (drops / repush / await) — was hand-mirrored.
    merged: dict = {}
    for r in rows:
        tab = ("collections" if r["item_media_type"] == "collection"
               else "anime" if r["is_anime"]
               else "movies" if r["type"] == "movie"
               else "tv")
        fourk = bool(r["is_4k"])
        key = (tab, fourk)
        if key in merged:
            merged[key]["count"] += r["n"]
        else:
            merged[key] = {"tab": tab, "fourk": fourk, "count": r["n"]}
    return list(merged.values())


def _breakdown_tab_hint(rows):
    # v1.24.47: a badge's owning-tab href = the first breakdown tab. Rows are
    # ORDER BY is_anime, type, is_4k, so [0] is the deterministic owner (collection
    # rows win their tab via _breakdown_tabs' mapping). Folds the old separate
    # LIMIT-1 tab_hint query into the breakdown the badge already runs.
    tabs = _breakdown_tabs(rows)
    return tabs[0]["tab"] if tabs else None
# v1.21.59: edition-aware SRC for the per-edition library query —
# reads the two-tier COALESCE(p_e.x, p_g.x) / COALESCE(lf_e.x, lf_g.x)
# placement/local_files columns instead of the bare p./lf. aliases.
_LIB_SRC_LETTER_SQL = _src_letter_sql(
    media_folder=_LIB_EFF_MEDIA_FOLDER,
    provenance="COALESCE(p_e.provenance, p_g.provenance)",
    source_kind="COALESCE(lf_e.source_kind, lf_g.source_kind)",
    source_video_id="COALESCE(lf_e.source_video_id, lf_g.source_video_id)")

# v1.23.10: the previous-URL booleans, extracted from the library
# SELECT so the attn_pills=restore filter interpolates the SAME
# text — mirror principle (the v1.23.7 filter hand-copied only the
# has_previous_url shape and drifted from the SOURCE-menu gate).
# History for the predicate shapes stays at the SELECT site
# (v1.12.86/v1.13.4/v1.18.8 + v1.12.40/.53/.101/.103/.105).
# Aliases bound to the library query FROM: t/pi/pv_sec/pv_global/
# lf_e/lf_g (+ pending_updates/user_overrides via subqueries).
_PREV_URL_DIFFERS_SQL = """COALESCE(pv_sec.youtube_url, pv_global.youtube_url) IS NOT NULL
                          AND COALESCE(pv_sec.youtube_url, pv_global.youtube_url) IS NOT COALESCE(
                                (SELECT youtube_url FROM user_overrides uo
                                  WHERE uo.media_type = t.media_type
                                    AND uo.tmdb_id = t.tmdb_id
                                    AND uo.section_id = pi.section_id),
                                (SELECT youtube_url FROM user_overrides uo
                                  WHERE uo.media_type = t.media_type
                                    AND uo.tmdb_id = t.tmdb_id
                                    AND uo.section_id = ''),
                                t.youtube_url
                              )"""
_REVERT_REDUNDANT_SQL = """COALESCE(pv_sec.youtube_url, pv_global.youtube_url) IS NOT NULL
                      AND (
                        -- v1.12.101 branch: row HAS a canonical
                        -- (REVERT competes with the existing-state
                        -- actions — pending update accept, no-op
                        -- swap to the same URL).
                        -- v1.12.105: also require hidden_url IS NULL.
                        -- Pre-fix the PURGE → DOWNLOAD TDB sequence
                        -- left a hidden user URL in the chain but
                        -- this branch fired (previous == current
                        -- post-download), hiding RESTORE — making
                        -- the hidden chain unreachable. The hidden
                        -- slot is the only path back to a URL that
                        -- DOWNLOAD TDB doesn't surface, so RESTORE
                        -- must stay visible whenever it's set.
                        (COALESCE(lf_e.file_path, lf_g.file_path) IS NOT NULL
                         AND COALESCE(pv_sec.hidden_url, pv_global.hidden_url) IS NULL
                         AND (
                          (COALESCE(pv_sec.kind, pv_global.kind) = 'themerrdb'
                           AND EXISTS (
                             SELECT 1 FROM pending_updates pu
                              WHERE pu.media_type = t.media_type
                                AND pu.tmdb_id = t.tmdb_id
                                AND pu.decision IN ('pending', 'declined')
                                AND pu.new_youtube_url = COALESCE(pv_sec.youtube_url, pv_global.youtube_url)
                           ))
                          OR
                          COALESCE(pv_sec.youtube_url, pv_global.youtube_url) = COALESCE(
                            -- v1.12.72: prefer section-specific
                            -- override; fall back to global ('') row;
                            -- final fallback to themes.youtube_url.
                            -- Mirrors the worker's two-step fetch so
                            -- the row's "currently applied" URL is
                            -- the same value the worker would use.
                            (SELECT youtube_url FROM user_overrides uo
                              WHERE uo.media_type = t.media_type
                                AND uo.tmdb_id = t.tmdb_id
                                AND uo.section_id = pi.section_id),
                            (SELECT youtube_url FROM user_overrides uo
                              WHERE uo.media_type = t.media_type
                                AND uo.tmdb_id = t.tmdb_id
                                AND uo.section_id = ''),
                            t.youtube_url
                          )
                        ))
                        OR
                        -- v1.12.103 branch: post-PURGE/UNMANAGE
                        -- clean overlap. RESTORE and DOWNLOAD TDB
                        -- would fetch the same URL with no chain
                        -- to preserve, so RESTORE adds nothing.
                        -- All four conditions matter: no canonical
                        -- to revert against, kind=themerrdb (user
                        -- URLs aren't reachable via DOWNLOAD TDB),
                        -- no hidden chain (RESTORE would otherwise
                        -- be the only way to start the chain walk),
                        -- and TDB hasn't rolled the URL since the
                        -- capture (else RESTORE locks to the older
                        -- URL — meaningfully different).
                        (COALESCE(lf_e.file_path, lf_g.file_path) IS NULL
                         AND COALESCE(pv_sec.kind, pv_global.kind) = 'themerrdb'
                         AND COALESCE(pv_sec.hidden_url, pv_global.hidden_url) IS NULL
                         AND COALESCE(pv_sec.youtube_url, pv_global.youtube_url) = t.youtube_url)
                      )"""

# v1.19.4: SQL fragment for "this row is NOT a pure SRC=P row".
# Used by every pending-update gate that filters on
# `kind = 'urls_match'` — the synthetic "your override now matches
# TDB; convert U→T?" prompt. On P rows that prompt is never
# actionable (Plex serves, motif owns no placement → ACCEPT /
# KEEP CURRENT have no effect on the user-visible theme). the user's
# 2026-05-24 repro: a P row on Back to the Future (1985) showed
# the !UPD indicator because the user override happened to match
# the new TDB URL; the prompt was meaningless.
#
# The "is P" inline check (no JOIN to placements required):
#   pi.has_theme = 1
#   AND COALESCE(pi.plex_theme_verified_ok, 1) = 1
#   AND NOT EXISTS (placement for this row)
#
# `t_alias` / `pi_alias` parameterize for sites using `t`/`pi`
# (library main FROM) vs `t2`/`pi2` (count subqueries) — the only
# two alias patterns in the urls_match check sites.
def _not_p_row_sql(t: str = "t", pi: str = "pi") -> str:
    """Return SQL fragment evaluating TRUE when this row is NOT
    a pure SRC=P row. Used to gate the urls_match branch of the
    pending-update predicate. v1.19.4."""
    return (
        f"NOT ("
        f"{pi}.has_theme = 1 "
        f"AND COALESCE({pi}.plex_theme_verified_ok, 1) = 1 "
        f"AND NOT EXISTS ("
        f"SELECT 1 FROM placements p_pgate "
        f"WHERE p_pgate.media_type = {t}.media_type "
        f"AND p_pgate.tmdb_id = {t}.tmdb_id "
        f"AND p_pgate.section_id = {pi}.section_id"
        f")"
        f")"
    )


# v1.19.33: executable mirror of _not_p_row_sql. Returns True iff
# the (mt, tmdb, section_id) row is a pure SRC=P row RIGHT NOW —
# Plex claims a theme, the claim isn't verified-stale, and motif
# owns no placement on this section. Used by ACCEPT UPDATE,
# bulk ACCEPT ALL, and REVERT to suppress the legacy force_place
# branch on P-rows (otherwise the new download steals Plex's
# serving slot and the row flips P → T / U — the user's Bleach
# repro, v1.19.32 fix extended to all three callsites here).
#
# v1.19.32 introduced the predicate inline in api_accept_update
# with a `JOIN themes t ON t.id = pi.theme_id` shape. v1.19.33
# extracted it to a helper AND widened the join to also match
# via `pi.guid_tmdb` so fresh / orphan / pre-resolve_theme_ids
# rows are covered. The narrower v1.19.32 form silently returned
# False (→ force_place) for any row whose theme_id hadn't been
# stamped yet by plex_enum.resolve_theme_ids — exactly the rows
# that look most P-like from the UI.
#
# Mirror of _not_p_row_sql contract:
#   - pi.has_theme = 1
#   - COALESCE(pi.plex_theme_verified_ok, 1) = 1
#   - NOT EXISTS (placements for this mt/tmdb/section)
#
# v1.19.40 doc: this Python helper has a WIDER theme→plex_items
# linkage than the SQL fragment (_not_p_row_sql) — the helper
# matches via `pi.theme_id` OR `pi.guid_tmdb`, the SQL fragment
# matches via the outer INNER JOIN to themes only (which requires
# pi.theme_id to be set). Practically the two agree: the SQL
# fragment is only used to suppress the urls_match prompt, and
# urls_match pending_updates by definition require a themes row
# that resolve_theme_ids has linked. The asymmetry exists because
# this helper is called from ACCEPT UPDATE / REVERT / bulk ACCEPT
# ALL where fresh / orphan / anime/legacy-agent rows realistically appear (the
# urls_match prompt never fires on those by construction). Don't
# narrow this helper to match the SQL — you'd regress the v1.19.33
# fix. If you ever need the SQL form to also widen, mirror the
# OR-via-guid_tmdb branch here.
def _is_p_row_for_section(
    conn: sqlite3.Connection,
    *,
    media_type: str,
    tmdb_id: int,
    section_id: str,
    edition_key: str = "",
) -> bool:
    """Mirror of _not_p_row_sql in executable form (v1.19.33).
    True iff Plex serves the theme + motif owns no placement on
    this section/edition.
    v0.50.89: added edition_key scoping to both the plex_items match and
    the NOT EXISTS(placements) sub-check — pre-fix a sibling edition's
    placement masked a genuine P-row here, letting ACCEPT UPDATE/REVERT
    force-place over Plex's serving slot for the actually-P edition."""
    # v1.18.0: themes ↔ plex_items media_type alignment. tv → show;
    # collections share 'collection' on both sides.
    if media_type == "tv":
        plex_type = "show"
    elif media_type == "collection":
        plex_type = "collection"
    else:
        plex_type = "movie"
    row = conn.execute(
        """
        SELECT 1
          FROM plex_items pi
          LEFT JOIN themes t ON t.id = pi.theme_id
         WHERE pi.section_id = ?
           AND pi.media_type = ?
           AND pi.edition_key = ?
           AND (
               (t.media_type = ? AND t.tmdb_id = ?)
               OR (pi.guid_tmdb = ? AND pi.media_type = ?)
           )
           AND pi.has_theme = 1
           AND COALESCE(pi.plex_theme_verified_ok, 1) = 1
           AND NOT EXISTS (
               SELECT 1 FROM placements p
                WHERE p.media_type = ?
                  AND p.tmdb_id = ?
                  AND p.section_id = ?
                  AND p.edition_key = ?
           )
         LIMIT 1
        """,
        (section_id, plex_type, edition_key,
         media_type, tmdb_id,
         tmdb_id, plex_type,
         media_type, tmdb_id, section_id, edition_key),
    ).fetchone()
    return bool(row)


# v1.19.12: SQL fragment for "this row HAS a user_overrides row"
# — second gate added to the urls_match prompt predicate. The
# urls_match kind is BY DEFINITION a U→T conversion offer (the
# sync sees a user_override URL matches the new TDB URL → write
# a pending_updates row inviting the user to convert). If the
# user_override is gone (deleted by REPLACE TDB / ACCEPT UPDATE /
# PURGE / etc.), the prompt is meaningless even on non-P rows.
#
# the user's 2026-05-24 repro: T+PU row (Cowboys & Aliens) showed
# !UPD from an orphan kind='urls_match' pending_updates row whose
# user_overrides counterpart had been deleted. v1.19.4's P-row
# exclusion didn't catch it because the row has a placement.
# This gate is the broader fix: NO user_override → suppress the
# urls_match prompt regardless of source class.
#
# Defense in depth alongside the v1.19.12 schema trigger
# (`trg_user_overrides_cleanup_urls_match`): the trigger
# prevents NEW orphans by auto-cleaning when user_overrides is
# deleted; this gate hides any orphans that exist from before
# the trigger landed (or could otherwise slip through).
def _has_user_override_sql(t: str = "t", pi: str = "pi") -> str:
    """Return SQL fragment evaluating TRUE when a user_overrides row exists for
    this (mt, tmdb) at the row's section OR the global '' section. v1.19.12.

    v1.22.9: '' fallback. This helper gates ONLY the urls_match blue-↑ branch
    (all 11 call sites pair it with _not_p_row_sql + a kind='urls_match' check).
    A user override can be GLOBAL (section_id='') — the legacy/cross-section
    shape that SRC=U honors via its own COALESCE(per-section, '') fallback. The
    strict-section check missed it: a row in section N with its override at ''
    rendered a GREEN TDB pill (urls_match branch failed) while SRC said U and
    NEEDS WORK ranked it — sort/pill drift (the user's Berserk / Fate anime, where
    the U URL already equals TDB's). Mirror SRC=U's section-or-global scope so
    the 'you could swap U→T' blue ↑ surfaces accurately."""
    return (
        f"EXISTS ("
        f"SELECT 1 FROM user_overrides uo_chk "
        f"WHERE uo_chk.media_type = {t}.media_type "
        f"AND uo_chk.tmdb_id = {t}.tmdb_id "
        f"AND (uo_chk.section_id = {pi}.section_id OR uo_chk.section_id = '')"
        f")"
    )


# v1.19.60: TRUE iff the row has a local_files row with source_kind
# in ('upload', 'adopt', 'plex_cloud') — manual content with NO
# associated URL relationship. Drives the read-path !UPD gate's new
# "content-diverge" branch: when TDB rolls a URL on a row whose
# motif-managed content is an uploaded MP3, adopted sidecar, or
# Plex cloud-backup MP3, !UPD lights up so the user can choose to
# swap their manual content for the new TDB URL (ACCEPT) or keep
# what they have (KEEP CURRENT). Pre-v1.19.60 these rows were
# silently suppressed because the gate's URL-diff comparison hit
# the COALESCE → t.youtube_url fallback (sync atomically updated
# both that and pending_updates.new_youtube_url, so they always
# matched). the user's "Bastard!! (1992)" repro.
def _row_has_non_url_local_content_sql(
    t: str = "t", pi: str = "pi",
) -> str:
    """SQL fragment evaluating TRUE when the row has a local_files
    row with source_kind in ('upload', 'adopt', 'plex_cloud')."""
    return (
        f"EXISTS ("
        f"SELECT 1 FROM local_files lf_cd "
        f"WHERE lf_cd.media_type = {t}.media_type "
        f"AND lf_cd.tmdb_id = {t}.tmdb_id "
        f"AND lf_cd.section_id = {pi}.section_id "
        f"AND lf_cd.source_kind IN ('upload', 'adopt', 'plex_cloud')"
        f")"
    )


# v1.19.60: SQL fragment evaluating TRUE when the pending_updates
# row represents a real, displayable URL diff. Pre-v1.19.60 sync
# bound `None` to old_youtube_url on the INSERT (sync.py:992),
# leaving the column NULL — meaning the read-path gate couldn't
# discriminate "real change" from "URL was always X, just got
# re-stamped." v1.19.60 fixed the INSERT to bind the captured
# old URL. This helper checks both halves: old IS NOT NULL (i.e.,
# this is a post-v1.19.60 row with diff data captured) AND old
# differs from new (sanity — protects against any future sync
# regression that re-stamps without a change).
#
# Legacy rows (pre-v1.19.60 url_changed inserts with old_url=NULL)
# stay dark by design — no recoverable diff to show, surfacing
# !UPD on them would just confuse ("URL: X, pending update to: X").
# Cross-match rows (sync.py is_new branch, line ~893: old_vid=NULL
# AND old_url=NULL) also stay dark via this gate — but their
# "TDB just discovered this title" surface is the content-diverge
# branch when motif has non-URL content, or the urls_match
# synthetic walker when motif has a coincidentally-matching
# user_override.
def _pending_update_new_theme_kind_sql(
    t: str = "t", pi: str = "pi",
) -> str:
    """v1.19.71: SQL fragment — TRUE iff pending_updates has kind
    'new_theme_available' for this row. The kind itself is the
    gate (no diff check needed — by definition there IS no
    'old URL' since the theme is brand-new). Fires the blue !UPD
    glyph on every in-Plex row where sync just discovered a TDB
    theme, regardless of whether motif/Plex has existing content
    (the v1.19.71 widening — surfaces new themes for SRC=—/P/U/A/M
    uniformly).

    Mirrors `_pending_update_real_diff_sql`'s scalar-subquery
    shape for consistency across the 11 mirror-drift gate sites.
    The COALESCE(per-section, global '' row) follows the
    v1.12.99 per-section schema convention.

    v1.19.72 (M5 audit note): this helper is DECISION-BLIND — it
    returns TRUE for accepted/declined rows too. That's safe at
    every current call site because every outer query gates on
    `COALESCE(pu_dsec.decision, pu_dglobal.decision) = 'pending'`
    BEFORE evaluating this helper. If a new caller forgets the
    outer decision gate, this helper will match stale rows.
    Adding decision='pending' here would duplicate the gate
    everywhere and slow scans without functional benefit; keep
    the contract documented instead."""
    pu_kind_sec = (
        f"(SELECT pu.kind FROM pending_updates pu "
        f"WHERE pu.media_type = {t}.media_type "
        f"AND pu.tmdb_id = {t}.tmdb_id "
        f"AND pu.section_id = {pi}.section_id AND pu.edition_key = '')"
    )
    pu_kind_global = (
        f"(SELECT pu.kind FROM pending_updates pu "
        f"WHERE pu.media_type = {t}.media_type "
        f"AND pu.tmdb_id = {t}.tmdb_id "
        f"AND pu.section_id = '' AND pu.edition_key = '')"
    )
    return (
        f"(COALESCE({pu_kind_sec}, {pu_kind_global}) "
        f" = 'new_theme_available')"
    )


def _pending_update_real_diff_sql(
    t: str = "t", pi: str = "pi",
) -> str:
    """SQL fragment: TRUE iff pending_updates has an old→new URL
    diff worth showing. Uses scalar subqueries so the helper works
    in every site (library SQL has pu_sec/pu_global JOIN aliases
    available, but other sites don't). v1.19.60."""
    pu_o_url_sec = (
        f"(SELECT pu.old_youtube_url FROM pending_updates pu "
        f"WHERE pu.media_type = {t}.media_type "
        f"AND pu.tmdb_id = {t}.tmdb_id "
        f"AND pu.section_id = {pi}.section_id AND pu.edition_key = '')"
    )
    pu_o_url_global = (
        f"(SELECT pu.old_youtube_url FROM pending_updates pu "
        f"WHERE pu.media_type = {t}.media_type "
        f"AND pu.tmdb_id = {t}.tmdb_id "
        f"AND pu.section_id = '' AND pu.edition_key = '')"
    )
    pu_n_url_sec = (
        f"(SELECT pu.new_youtube_url FROM pending_updates pu "
        f"WHERE pu.media_type = {t}.media_type "
        f"AND pu.tmdb_id = {t}.tmdb_id "
        f"AND pu.section_id = {pi}.section_id AND pu.edition_key = '')"
    )
    pu_n_url_global = (
        f"(SELECT pu.new_youtube_url FROM pending_updates pu "
        f"WHERE pu.media_type = {t}.media_type "
        f"AND pu.tmdb_id = {t}.tmdb_id "
        f"AND pu.section_id = '' AND pu.edition_key = '')"
    )
    return (
        f"("
        f"COALESCE({pu_o_url_sec}, {pu_o_url_global}) IS NOT NULL "
        f"AND COALESCE({pu_o_url_sec}, {pu_o_url_global}) != '' "
        f"AND COALESCE({pu_o_url_sec}, {pu_o_url_global}) "
        f"    != COALESCE({pu_n_url_sec}, {pu_n_url_global})"
        f")"
    )


def _pending_update_actionable_sql(t: str = "t", pi: str = "pi") -> str:
    """v1.22.10: the 'is this pending worth surfacing' gate — the single source
    of truth shared by the pill `pending_update`/`actionable_update` columns,
    the tdb_pills=update/=tdb filters, the attn_pills=update filter, AND the
    NEEDS WORK attention sort. The gate was inlined identically at each surface;
    the attention sort (priority-2) had NONE of it — only a loose decision+
    detection+presence check — so a row whose pending is a no-op (e.g. an
    url-less upstream_changed: TDB still publishes the title but removed its
    youtube_url) showed a GREEN pill yet still ranked NEEDS WORK (the user's
    anime: The Beginning After the End, Witch Hat Atelier). Same sort-vs-pill
    drift class as v1.19.86 (priority-3 await). One helper so the sort can't
    drift from the pill again.

    A pending is ACTIONABLE iff: it's a urls_match convert offer on a non-P row
    that has a (section-or-global) override (v1.19.4 P-skip + v1.22.9 '' scope);
    OR the TDB URL really changed (old→new diff); OR the row carries non-url
    local content (upload/adopt/plex_cloud); OR it's a freshly-discovered
    new_theme_available ON A NON-P ROW. Kind uses the portable scalar-subquery
    form (COALESCE per-section, global '') — provably equal to the pu_sec/
    pu_global JOIN aliases the pill columns used (same media_type/tmdb/section/
    edition_key='' predicates), so it drops in at every site including the count
    subqueries.

    v1.22.12: the new_theme_available branch now gates on _not_p_row too.
    v1.19.71 surfaced "TDB just published a theme" uniformly across SRC=—/P/U/A/M
    so a pure SRC=P row (Plex serves its own theme, motif owns nothing) lit the
    blue ↑ pill / !UPD glyph / NEEDS WORK. the user: stop flagging P rows — anime
    is ~100% Plex-served and TDB's catalog keeps growing, so every sync flooded
    UPD/NEEDS WORK with rows motif doesn't manage, burying the ones it does. The
    theme stays discoverable + the operator can still DOWNLOAD TDB per-row from
    the SOURCE menu to take over (sync also stops WRITING new_theme for pure-P
    rows; this read gate also silences the rows already detected). SRC=—/U/A/M
    still surface (they pass _not_p_row)."""
    kind = (
        f"COALESCE("
        f"(SELECT pu.kind FROM pending_updates pu "
        f"WHERE pu.media_type = {t}.media_type AND pu.tmdb_id = {t}.tmdb_id "
        f"AND pu.section_id = {pi}.section_id AND pu.edition_key = ''), "
        f"(SELECT pu.kind FROM pending_updates pu "
        f"WHERE pu.media_type = {t}.media_type AND pu.tmdb_id = {t}.tmdb_id "
        f"AND pu.section_id = '' AND pu.edition_key = ''))"
    )
    return (
        f"(({kind} = 'urls_match' "
        f"AND {_not_p_row_sql(t, pi)} AND {_has_user_override_sql(t, pi)}) "
        f"OR {_pending_update_real_diff_sql(t, pi)} "
        f"OR {_row_has_non_url_local_content_sql(t, pi)} "
        f"OR ({_pending_update_new_theme_kind_sql(t, pi)} AND {_not_p_row_sql(t, pi)}))"
    )


def _pending_update_detected_sql(t: str = "t", pi: str = "pi") -> str:
    """v1.21.81: TRUE iff a sync DETECTION row exists at edition_key='' for
    this (section, '') or (title-global '') — `kind` is NOT NULL there.

    The decision column at '' gets FLIPPED when the standard ('' ) edition
    accepts/declines, but `kind` never flips — so this is the edition-flip-
    immune 'an update actually exists' signal. It gates the v1.21.81
    default-to-'pending' decision read: without it a row with non-url local
    content (U/A/M/upload) but NO detection would false-light the !UPD pill
    (decision NULL -> defaulted 'pending' AND the non_url_content branch of
    the meaningful-gate both pass). Mirrors the kind subqueries' '' pin."""
    kind_sec = (
        f"(SELECT pu.kind FROM pending_updates pu "
        f"WHERE pu.media_type = {t}.media_type "
        f"AND pu.tmdb_id = {t}.tmdb_id "
        f"AND pu.section_id = {pi}.section_id AND pu.edition_key = '')"
    )
    kind_global = (
        f"(SELECT pu.kind FROM pending_updates pu "
        f"WHERE pu.media_type = {t}.media_type "
        f"AND pu.tmdb_id = {t}.tmdb_id "
        f"AND pu.section_id = '' AND pu.edition_key = '')"
    )
    return f"(COALESCE({kind_sec}, {kind_global}) IS NOT NULL)"


# v1.14.30: canonical sfa-aware FROM/JOIN/WHERE for per-(title,
# section) failure counts — the SAME predicate /api/stats
# `failures_total` (the v1.14.8 rewrite) and the library filter
# (`attn_pills=fail`) use. Every secondary stats surface (public-
# stats, dashboard insights failure_kinds chart, FAIL kind sub-
# totals) MUST consume this fragment instead of writing its own
# `WHERE failure_kind IS NOT NULL` shape. Mirror-principle drift
# class P — pre-v1.14.30, four secondary surfaces had drifted
# back to the title-global form, disagreeing with the topbar
# FAIL pill by exactly the count of sfa-acked sections.
_FAILURES_SFA_FROM_SQL = (
    "FROM themes t "
    "JOIN plex_items pi "
    # v1.15.61 ORed (pi.guid_tmdb=tmdb_id+media_type) OR pi.theme_id=t.id
    # to catch orphan failures (orphans have pi.guid_tmdb=NULL so the
    # guid_tmdb branch alone missed them). v1.15.62 reverted to a single
    # theme_id join — SQLite's OR-join optimizer bailed on the CASE
    # expression in the guid_tmdb branch and degraded to ~cartesian
    # scans; with no idx_plex_items_theme_id either, every SSR call
    # (3+ scalar subqueries via _topbar_ssr_state) took 20+ seconds.
    # the user: "everything is very slow loading over a minute to load
    # in a fresh tab or switch between tabs." Single theme_id join
    # is fast (now indexed via v50 migration) AND catches both axes:
    # TDB-tracked rows have theme_id set post-resolve_theme_ids;
    # orphans have theme_id set when the synthetic theme is created
    # (api.py:8934 — UPDATE plex_items SET theme_id = ?). The
    # pre-resolve window where theme_id is NULL on fresh installs
    # mirrors the library filter's behavior (it also joins via
    # theme_id) — they agree even on that transient.
    "  ON pi.theme_id = t.id "
    "JOIN plex_sections ps "
    "  ON ps.section_id = pi.section_id AND ps.included = 1 "
    "LEFT JOIN section_failure_acks sfa "
    "  ON sfa.media_type = t.media_type "
    " AND sfa.tmdb_id = t.tmdb_id "
    " AND sfa.section_id = pi.section_id"
)
_FAILURES_SFA_WHERE_SQL = (
    "t.failure_kind IS NOT NULL "
    "AND t.failure_acked_at IS NULL "
    "AND sfa.acked_at IS NULL"
)

# v1.15.38: COOKIES count + filter share this predicate so they
# stay aligned. the user's report: "the yellow TDB Pill filter
# wasn't filtering properly" — pre-fix the COOKIES count used
# the canonical _FAILURES_SFA_WHERE_SQL (ack-aware) but the
# v1.15.38 filter had been broadened to drop ack predicates
# (matches the row-level yellow ⚿ pill which renders on
# `failure_kind = 'cookies_expired'` regardless of ack state).
# Result: chip count diverged from filter results. Now both
# use this constant + the per-(title, section) FROM clause via
# _FAILURES_SFA_FROM_SQL (ack-aware vs not is a WHERE concern,
# not a JOIN concern; the FROM is unchanged so the per-section
# multiplicity stays the canonical one).
_COOKIES_PILL_WHERE_SQL = "t.failure_kind = 'cookies_expired'"

# v1.10.15: column-sort whitelist. Each entry maps the ?sort= value
# accepted by /api/library to a SQL ORDER BY snippet for the main row
# query. Wrapping in a whitelist keeps the param SQL-injection-safe.
# 'src' uses _SRC_LETTER_SQL with a numeric remap so sort-by-source
# groups rows visually the same way the SRC column does (T → U → A →
# M → P → —).
_LIBRARY_SORTS_MAIN = {
    "title": "pi.title COLLATE NOCASE",
    "year":  "pi.year",
    "imdb":  "pi.guid_imdb",
    # v1.15.53: ED column sort. Extracts the substring after
    # '{edition-' from pi.folder_path so rows with the same
    # edition tag (Director's Cut / IMAX / Extended) group
    # together; rows without an edition sort last (empty string
    # sorts before any populated value with ASC, so flip:
    # CASE makes edition-having rows precede via has-edition=0
    # ordering ASC).
    "edition": (
        "CASE WHEN INSTR(pi.folder_path, '{edition-') > 0 THEN 0 ELSE 1 END, "
        "CASE WHEN INSTR(pi.folder_path, '{edition-') > 0 "
        "    THEN SUBSTR(pi.folder_path, INSTR(pi.folder_path, '{edition-') + 9) "
        "    ELSE '' END COLLATE NOCASE"
    ),
    "src": (
        f"CASE ({_LIB_SRC_LETTER_SQL}) "
        "WHEN 'T' THEN 1 "
        "WHEN 'U' THEN 2 "
        "WHEN 'A' THEN 3 "
        "WHEN 'M' THEN 4 "
        "WHEN 'P' THEN 5 "
        "ELSE 6 END"
    ),
    # v1.13.67: sort by TDB pill class. Priority mirrors the row-pill
    # render priority in JS computeTdbPill: pending update wins over
    # tracked-ok, then degrading-state pills (cookies / dead /
    # dropped), then "no TDB". Keeps actionable rows (TDB ↑ first)
    # near the top so a sort-by-TDB sweep surfaces work first.
    # Uses a simpler EXISTS check than PENDING_EXISTS (no per-section
    # gate) since sort tolerates a few extra "treated as pending"
    # rows much better than the strict filter does.
    "tdb": (
        "CASE "
        "WHEN EXISTS (SELECT 1 FROM pending_updates pu "
        "             WHERE pu.media_type = t.media_type "
        "               AND pu.tmdb_id = t.tmdb_id "
        "               AND pu.decision = 'pending') THEN 1 "
        "WHEN t.upstream_source IN ('imdb','themoviedb') "
        "     AND t.failure_kind IS NULL "
        "     AND t.tdb_dropped_at IS NULL THEN 2 "
        "WHEN t.failure_kind = 'cookies_expired' THEN 3 "
        "WHEN t.failure_kind IN ('video_private','video_removed',"
        "                        'video_age_restricted','geo_blocked') THEN 4 "
        "WHEN t.tdb_dropped_at IS NOT NULL THEN 5 "
        "ELSE 6 END"
    ),
    # v1.23.37: DL sort groups by the RENDERED dot, mirroring the v1.23.25 PL
    # fix. Pre-fix `file_path IS NOT NULL THEN 0 ELSE 1` lumped the red 'broken'
    # dot (canonical_present=0 — theme.mp3 gone from motif's storage, stamped by
    # verify_canonical_health) into bucket 0 with green 'on', so sorting by DL
    # interleaved them. Now broken → on → off; NULL (unverified) sorts as 'on'
    # until the next enum stamps it (same as PL's theme_present). The live red
    # dot still derives from the per-render canonical_missing stat.
    "dl": (
        "CASE "
        "WHEN COALESCE(lf_e.canonical_present, lf_g.canonical_present) = 0 THEN 0 "
        "WHEN COALESCE(lf_e.file_path, lf_g.file_path) IS NOT NULL THEN 1 "
        "ELSE 2 END"
    ),
    # v1.23.24: PL sort groups by the RENDERED dot color, not a flat
    # placed/not-placed 0/1. Pre-fix the key was `media_folder IS NOT NULL
    # THEN 0 ELSE 1`, but plex_upload placements carry media_folder='' (a
    # non-NULL empty-string sentinel) so cyan (pushed) and green (on) BOTH
    # landed in bucket 0 — sorting by PL interleaved cyan + green dots
    # (the user's report). Now each rendered state gets its own bucket,
    # mirroring the JS pl derivation (renderLibraryRow): green (real sidecar
    # folder) → cyan (plex_upload) → amber (await: canonical, no placement,
    # not LPS) → gray (off + LPS). The red 'broken' state isn't here — it's a
    # post-SQL stat (placement_missing); v1.23.25's stored placement-health
    # flag will prepend it.
    "pl": (
        "CASE "
        # v1.24.36 (review #4): a stale plex_upload (RP) renders PL='await'
        # (amber) — renderLibraryRow: not-placed (media_folder/placement_kind
        # nulled by _LIB_EFF_MEDIA_FOLDER) + has-canonical + not-LPS + not-PU →
        # awaitingApproval. Pin it to the await rank (3) FIRST so it doesn't fall
        # into the red 'broken' theme_present=0 bucket below (sort-vs-render
        # drift — the v1.23.24/.25 "rank by the dot you paint" invariant).
        f"WHEN {_LIB_STALE_PU_SQL} THEN 3 "
        # v1.23.25: red 'broken' (theme.mp3 verified gone) groups first —
        # stamped by plex_enum's verify_placement_health pass. =0 means
        # VERIFIED missing; a broken row HAS a real media_folder so this must
        # precede the green branch below. NULL/1 fall through to green.
        "WHEN COALESCE(p_e.theme_present, p_g.theme_present) = 0 THEN 0 "
        "WHEN COALESCE(p_e.media_folder, p_g.media_folder) IS NOT NULL "
        "     AND COALESCE(p_e.media_folder, p_g.media_folder) != '' THEN 1 "
        "WHEN COALESCE(p_e.placement_kind, p_g.placement_kind) = 'plex_upload' THEN 2 "
        "WHEN COALESCE(lf_e.file_path, lf_g.file_path) IS NOT NULL "
        "     AND COALESCE(pi.plex_independent_theme, 0) = 0 THEN 3 "
        "ELSE 4 END"
    ),
    # v1.23.35: rank by the SAME LINK chip the row paints, mirroring
    # the renderLibraryRow precedence (app.js): PB→TB→AB→UB→M→HL→C→
    # PU→—. Pre-fix the CASE only split hardlink/copy/else, so PU, the
    # four backups, M and "—" ALL collapsed to rank 2 → sorting by LINK
    # interleaved them by the title tiebreak instead of grouping by
    # chip (the user: "sorting by link does not properly … order"). Field
    # exprs match the link_pills filter branches so filter + sort agree.
    "link": (
        "CASE "
        # v1.24.36 (review #4): a stale plex_upload renders the orange RP badge
        # (the needs_repush branch is FIRST in renderLibraryRow), so it sorts
        # FIRST — its own group, NOT the PU bucket (7) it would otherwise match
        # on raw placement_kind. Matched first so a stale PU never reaches that
        # branch. -1 keeps the existing 0-8 ranks untouched.
        f"WHEN {_LIB_STALE_PU_SQL} THEN -1 "
        "WHEN COALESCE(lf_e.last_place_attempt_reason, lf_g.last_place_attempt_reason) = 'backup_only' "
        "     AND COALESCE(p_e.media_folder, p_g.media_folder) IS NULL THEN "
        "  CASE COALESCE(lf_e.source_kind, lf_g.source_kind) "
        "    WHEN 'plex_cloud' THEN 0 WHEN 'themerrdb' THEN 1 WHEN 'adopt' THEN 2 ELSE 3 END "
        "WHEN COALESCE(lf_e.mismatch_state, lf_g.mismatch_state) IS NOT NULL "
        "     AND COALESCE(p_e.media_folder, p_g.media_folder) IS NOT NULL THEN 4 "
        "WHEN COALESCE(p_e.placement_kind, p_g.placement_kind) = 'hardlink' THEN 5 "
        "WHEN COALESCE(p_e.placement_kind, p_g.placement_kind) = 'copy' THEN 6 "
        "WHEN COALESCE(p_e.placement_kind, p_g.placement_kind) = 'plex_upload' THEN 7 "
        "ELSE 8 END"
    ),
    # v1.12.68: 'attention' sort orders rows by what needs the
    # user's attention most. Lower priority numbers sort first
    # (asc) so the rows demanding action float to the top of the
    # list — failures, then pending updates, then post-DEL await
    # placements, then mismatches, then the rest. Pairs with the
    # frontend's // NEEDS WORK sort button. Title is the
    # secondary key (added in the SQL builder via _LIBRARY_SORT_TIE)
    # so equal-priority rows stay alphabetized.
    # v1.13.3: priorities 2 + 6 (pending and declined) now use the
    # per-section + '' fallback pattern that the row pill render
    # established in v1.12.99 / v1.12.119, plus the motif-tracking-
    # presence gate. Pre-fix a stale '' fallback row from an older
    # sync would float every section's copy of a multi-section
    # title to the top of // NEEDS WORK even if one section had
    # actually been ACCEPTed (its per-section decision='accepted'
    # got overshadowed by the legacy '' row's 'pending'). Now
    # priorities are evaluated against THIS section's effective
    # decision (per-section first, '' fallback second) and only
    # when motif actually tracks the row in this section.
    "attention": (
        "CASE "
        # v1.23.25: broken placement (theme.mp3 gone from the Plex folder) is
        # the MOST urgent. theme_present (=0 VERIFIED missing) is stamped by
        # plex_enum's verify_placement_health pass — the red PL dot is a
        # per-render stat the paginated SQL sort can't see. Pre-fix a broken
        # HL row fell to ELSE 7 and never surfaced under NEEDS WORK.
        # v1.23.30 (#3 code-review): gate on plex_independent_theme=0, same as
        # the await branch (v1.19.86). A row Plex serves itself (indep=1) with a
        # stale missing-sidecar record needs NO action — without this gate it
        # hoisted ABOVE genuine failures under NEEDS WORK (sort-vs-filter drift).
        # v1.24.41 (review #3): a plex_upload whose rk went LIVE again (re-linked,
        # theme_present not yet re-stamped) is rendered PLACED by the rk-liveness-
        # tightened _LIB_STALE_PU_SQL — so it must NOT top this most-urgent bucket
        # (it would head // NEEDS WORK looking fine: sort-vs-render drift, the same
        # invariant v1.24.36 fixed for the pl/link sorts). A broken SIDECAR (not
        # plex_upload) is still urgent; a GENUINELY-dead plex_upload (RP) is still
        # urgent via _LIB_STALE_PU_SQL; only the live-rk plex_upload drops out.
        f"WHEN COALESCE(p_e.theme_present, p_g.theme_present) = 0 "
        f"    AND COALESCE(pi.plex_independent_theme, 0) = 0 "
        f"    AND (COALESCE(p_e.placement_kind, p_g.placement_kind) != 'plex_upload' "
        f"         OR ({_LIB_STALE_PU_SQL})) THEN 0 "
        # Active failure (red TDB ✗ pill, not yet acked)
        # v1.13.54: per-section ack via sfa.acked_at also counts.
        "WHEN t.failure_kind IS NOT NULL "
        "    AND t.failure_acked_at IS NULL "
        "    AND sfa.acked_at IS NULL THEN 1 "
        # Pending upstream update (blue TDB ↑ pill, not yet decided)
        # — only when motif has presence in THIS section AND the URL
        # actually differs (no-op suppression).
        "WHEN COALESCE("
        "  (SELECT pu.decision FROM pending_updates pu "
        "    WHERE pu.media_type = t.media_type AND pu.tmdb_id = t.tmdb_id "
        "      AND pu.section_id = pi.section_id AND pu.edition_key = pi.edition_key),"
        "  (SELECT pu.decision FROM pending_updates pu "
        "    WHERE pu.media_type = t.media_type AND pu.tmdb_id = t.tmdb_id "
        "      AND pu.section_id = '' AND pu.edition_key = pi.edition_key)"
        ", 'pending') = 'pending' "
        f"  AND {_pending_update_detected_sql('t', 'pi')} "
        " AND ("
        "   EXISTS (SELECT 1 FROM local_files lf2 "
        "            WHERE lf2.media_type = t.media_type "
        "              AND lf2.tmdb_id = t.tmdb_id "
        "              AND lf2.section_id = pi.section_id)"
        "   OR EXISTS (SELECT 1 FROM user_overrides uo2 "
        "               WHERE uo2.media_type = t.media_type "
        "                 AND uo2.tmdb_id = t.tmdb_id "
        "                 AND uo2.section_id = pi.section_id)"
        "   OR EXISTS (SELECT 1 FROM placements p3 "
        "               WHERE p3.media_type = t.media_type "
        "                 AND p3.tmdb_id = t.tmdb_id "
        "                 AND p3.section_id = pi.section_id)"
        "   OR pi.local_theme_file = 1"
        # v1.22.14: + the new_theme_available escape, mirroring the presence gate
        # at the pill `pending_update`/`actionable_update` columns, PENDING_EXISTS,
        # and the attn_pills=update filter. Without it a SRC=— row that sync just
        # discovered a brand-new TDB theme for (no local_files/override/placement/
        # sidecar) renders the blue ↑ pill + UPD count + matches both update
        # filters but FAILS this presence gate → falls to ELSE 7 and sinks to the
        # bottom of NEEDS WORK instead of priority-2. v1.22.10 unified the
        # ACTIONABLE sub-gate onto the sort but left this PRESENCE sub-gate to
        # drift — the exact sort-vs-pill class v1.22.10 set out to kill (review).
        f"   OR {_pending_update_new_theme_kind_sql('t', 'pi')}"
        " ) "
        # v1.22.10: the no-op suppression the comment above always promised was
        # never actually implemented here — the sort ranked ANY detected pending
        # NEEDS WORK while the pill column gated on actionability. So a url-less
        # upstream_changed (TDB removed the theme URL → real_diff false → GREEN
        # pill) still floated to the top of NEEDS WORK (the user's anime: The
        # Beginning After the End, Witch Hat Atelier). Share the pill's gate so
        # the sort mirrors the pill — same drift class as v1.19.86 (priority-3).
        f"   AND {_pending_update_actionable_sql('t', 'pi')} THEN 2 "
        # Awaiting placement (canonical exists, no placement)
        # v1.19.86: gate on plex_independent_theme=0 to mirror the
        # v1.14.39 await ATTN *filter* (api.py ~2316). Pre-fix the
        # attention SORT lacked this exclusion, so backup rows
        # (PB/UB: Plex serves its own theme AND motif holds a
        # backup_only canonical with no placement — the intended
        # "BACKUP READY — DEFERRING TO PLEX" state) got ranked
        # priority-3 "awaiting placement" and floated to the top of
        # // NEEDS WORK despite needing zero action. The filter
        # already excluded them via plex_independent_theme=1; the
        # sort drifted. the user's repro: a TV-shows page of P-rows
        # with PB/UB badges hoisted on // NEEDS WORK.
        "WHEN COALESCE(lf_e.file_path, lf_g.file_path) IS NOT NULL AND COALESCE(p_e.media_folder, p_g.media_folder) IS NULL "
        "    AND COALESCE(pi.plex_independent_theme, 0) = 0 THEN 3 "
        # Mismatch (canonical and placement file diverged)
        "WHEN COALESCE(lf_e.mismatch_state, lf_g.mismatch_state) = 'pending' THEN 4 "
        # v1.13.3 (Issue 5): acked failures (priority 5 pre-fix)
        # are no longer prioritized in NEEDS WORK. The user
        # explicitly said "I dealt with it" by clicking ACK
        # FAILURE; pulling them back to the top of NEEDS WORK
        # contradicts that intent. The TDB ✗ pill stays on the
        # row so the broken upstream is still visible — only the
        # ranking changes. Same for KEEP-CURRENTed updates
        # (priority 6 pre-fix) — the user actively dismissed
        # them, so don't re-surface. Both fall to the default
        # priority 7 with the rest of the catalog.
        "ELSE 7 END"
    ),
}
_LIBRARY_SORTS_NOT_IN_PLEX = {
    "title": "t.title COLLATE NOCASE",
    "year":  "t.year",
    "imdb":  "t.imdb_id",
}


def _library_main_query(
    db: Path, *, tab: str, fourk: bool, q: str, status: str,
    page: int, per_page: int,
    # v0.51.21: the // ALL resolution chip. When True, union BOTH the
    # standard and 4K sections of a library type (movies/tv/anime) into
    # one view instead of the fourk binary picking exactly one. For the
    # collections tab it means "all managed sections' collections at once"
    # — the caller forces section_id='' in that case, which the existing
    # per-section filter below already treats as "no narrowing". Only
    # offered by the UI when both a standard AND a 4K section exist
    # (movies/tv/anime) or ≥2 collection sections exist.
    all_res: bool = False,
    # v1.18.1: per-section scope for the /collections tab (empty
    # string means "all included sections"). Honored only for
    # tab='collections'; the caller in api_library forces the
    # empty string for other tabs. Validated at the route layer
    # to be a non-negative integer string.
    section_id: str = "",
    sort: str = "title", sort_dir: str = "asc",
    tdb: str = "any",
    src_pills: set[str] | None = None,
    tdb_pills: set[str] | None = None,
    dl_pills: set[str] | None = None,
    pl_pills: set[str] | None = None,
    link_pills: set[str] | None = None,
    # v1.12.41: EDITION pill axis. Filters rows by whether the
    # Plex folder name carries an `{edition-...}` tag. 'has'
    # matches rows with an edition tag (Director's Cut,
    # Extended, IMAX, etc.); 'none' matches rows without one.
    # Lets the user scope themes to a specific edition family
    # without filtering by SRC/DL/PL.
    ed_pills: set[str] | None = None,
    # v1.13.68: ATTN pill axis. See api_library docstring above
    # for the full state list. Drives the new // ATTN chip row
    # below the SRC row and the topbar 5-FAIL click-through.
    attn_pills: set[str] | None = None,
    cookies_present: bool = False,
    themes_dir: Path | None = None,
) -> dict:
    """Sync helper for /api/library — runs all SQL in one threadpool call
    so the FastAPI event loop isn't blocked. v1.10.2 perf pass:
      - consolidated 3 metadata queries (plex_enumerated, last_plex_enum_at,
        last_sync_at) into one round trip.
      - skip the heavy LEFT JOIN themes/lf/p in the COUNT when status='all'
        and q is empty/title-only — the tab predicate alone is sufficient
        to count rows there.
      - heavy joins still happen for the rows query (we need theme/lf/p
        columns to render rows) and for status filters that reference
        them in WHERE.
    """
    import time as _t  # v1.23.70: diagnostic timer (tab-switch-lag investigation)
    _t0 = _t.monotonic()
    if tab == "movies":
        tab_where = "pi.media_type = 'movie' AND ps.is_anime = 0"
    elif tab == "tv":
        tab_where = "pi.media_type = 'show' AND ps.is_anime = 0"
    elif tab == "collections":
        # v1.18.0: collections tab lists every plex_items row with
        # media_type='collection' (populated by plex_enum's per-
        # section collection-enumeration pass). Collections live
        # within Plex's regular sections, so no anime/4K split
        # applies — render them all in one tab regardless of which
        # parent section type owns them.
        tab_where = "pi.media_type = 'collection'"
    else:  # anime — both movie- and show-typed anime sections allowed
        # v1.19.28: explicit media_type allowlist excludes collection
        # rows. Pre-fix anime tab was `ps.is_anime = 1` with no
        # media_type constraint, so collection-type plex_items in
        # anime sections ("Dragon Ball Collection", "My Hero
        # Academia Collection", etc.) rendered alongside actual
        # TV shows. The /movies + /tv tabs already constrained
        # media_type implicitly excluding collections; anime was
        # the lone outlier. Collections still surface on the
        # dedicated /collections tab.
        tab_where = (
            "ps.is_anime = 1 "
            "AND pi.media_type IN ('movie', 'show')"
        )
    # v1.18.0: collections aren't 4K-tagged at the Plex level, so
    # the fourk filter is meaningless for them — skip it and let
    # the tab return both 4K and non-4K parent sections' collections
    # together.
    # v0.51.21: the // ALL chip unions both resolutions — skip the is_4k
    # narrowing entirely so a title present in BOTH the standard and 4K
    # sections renders as its two (distinct rating_key) rows together.
    if tab != "collections" and not all_res:
        tab_where += " AND ps.is_4k = 1" if fourk else " AND ps.is_4k = 0"
    # v1.18.1: per-section narrowing for the /collections tab. The
    # caller (api_library) only forwards section_id when tab is
    # 'collections' AND the user picked a specific section chip;
    # empty string means "all included sections" → no filter.
    # Defensive INTEGER cast on substitution would be safer, but
    # the route-layer pattern `^[0-9]*$` already restricts the
    # value to digits-only — sufficient for SQL injection
    # avoidance.
    if tab == "collections" and section_id:
        # v1.24.12 (security, defense-in-depth): section_id is route-pinned to
        # `^[0-9]*$`, so it's not injectable today — but guard here too so a
        # future caller reaching this helper directly can't smuggle SQL. The
        # value compares against a TEXT column, so keep the quoted form (a
        # bound `?` would mean threading a param into the right slot of this
        # hand-assembled query; the digit guard is the lower-risk equivalent).
        if not section_id.isdigit():
            raise ValueError(f"section_id must be digits, got {section_id!r}")
        tab_where += f" AND pi.section_id = '{section_id}'"

    params: list = []
    where_extra = ""
    where_pi_only = ""
    if q:
        # v0.51.125: match a purely-numeric query against guid_tmdb too, so a
        # bare TMDB id — e.g. the "tv/4656" shown in a 💔 Theme lost notification
        # when the title couldn't resolve — locates its row from the search box.
        # Pre-fix only title + IMDb id matched, so the tmdb id in the alert was
        # un-searchable. Gated to all-digit queries so a text search can't
        # collide with a stray tmdb; guid_tmdb is INTEGER, the str bind coerces
        # via column affinity. The clause is identical in where_extra +
        # where_pi_only so the leading q-params stay aligned in every count path.
        if q.isdigit():
            # v0.51.126: also match the theme-linkage tmdb. A 💔 Theme lost alert
            # names a row by COALESCE(themes.tmdb_id, plex_items.guid_tmdb)
            # (plex_enum.py:2427), so a theme-linked row with a NULL guid_tmdb
            # (anime / non-TMDB agents) shows the THEMES tmdb_id — which the
            # guid_tmdb match alone misses. The pi.theme_id subquery references
            # only pi.* columns so it stays valid in the themes-less count FROM
            # (where_pi_only) too.
            clause = (" AND (pi.title LIKE ? OR pi.guid_imdb = ? "
                      "OR pi.guid_tmdb = ? "
                      "OR pi.theme_id IN "
                      "  (SELECT id FROM themes WHERE tmdb_id = ?))")
            where_extra += clause
            where_pi_only += clause
            params.extend([f"%{q}%", q, q, q])
        else:
            clause = " AND (pi.title LIKE ? OR pi.guid_imdb = ?)"
            where_extra += clause
            where_pi_only += clause
            params.extend([f"%{q}%", q])
    if status == "themed":
        where_extra += (" AND t.tmdb_id IS NOT NULL "
                        "AND t.upstream_source != 'plex_orphan'")
    elif status == "manual":
        where_extra += (
            " AND ("
            "  (COALESCE(lf_e.provenance, lf_g.provenance) = 'manual')"
            "  OR (pi.local_theme_file = 1 "
            "      AND COALESCE(lf_e.file_path, lf_g.file_path) IS NULL AND COALESCE(p_e.media_folder, p_g.media_folder) IS NULL)"
            ")"
        )
    elif status == "plex_agent":
        where_extra += (" AND pi.has_theme = 1 "
                        "AND pi.local_theme_file = 0 "
                        "AND COALESCE(lf_e.file_path, lf_g.file_path) IS NULL "
                        "AND COALESCE(p_e.media_folder, p_g.media_folder) IS NULL")
    elif status == "untracked":
        # v1.12.4: 'UNTHEMED' (renamed from UNTRACKED in v1.12.0) — no
        # theme content anywhere on this row. The TDB-coverage axis is
        # handled separately via the TDB MATCH chips so the user can
        # slice UNTHEMED into "TDB-tracked + no theme yet" (the
        # actionable list — motif can fetch from upstream) vs
        # "no TDB and no theme" (truly orphan). Pre-fix the t.* clause
        # was baked in here, which made TDB MATCH redundant on this
        # tab and the chip row was hidden.
        where_extra += (" AND pi.has_theme = 0 "
                        "AND pi.local_theme_file = 0 "
                        "AND COALESCE(lf_e.file_path, lf_g.file_path) IS NULL "
                        "AND COALESCE(p_e.media_folder, p_g.media_folder) IS NULL")
    elif status == "has_theme":
        # v1.12.118: THEMED = "actual theme applied to THIS row".
        # Pre-fix the filter included a `t.tmdb_id IS NOT NULL AND
        # t.upstream_source != 'plex_orphan'` OR-arm, which let any
        # row through that had TDB tracking — even if no theme was
        # actually applied to that row. Stacking with the ED pill
        # surfaced "every edition that ThemerrDB knows about" instead
        # of "every edition that has a theme". Now: strict inverse
        # of UNTHEMED — any of placement, canonical, sidecar, or
        # Plex-served theme present.
        where_extra += (" AND ("
                        "  pi.has_theme = 1"
                        "  OR pi.local_theme_file = 1"
                        "  OR COALESCE(lf_e.file_path, lf_g.file_path) IS NOT NULL"
                        "  OR COALESCE(p_e.media_folder, p_g.media_folder) IS NOT NULL"
                        ")")
    elif status == "downloaded":
        # motif has the theme file on disk (placed or not). Mirrors the
        # DL pill being lit in the row.
        where_extra += " AND COALESCE(lf_e.file_path, lf_g.file_path) IS NOT NULL"
    elif status == "placed":
        where_extra += " AND COALESCE(p_e.media_folder, p_g.media_folder) IS NOT NULL"
    elif status == "unplaced":
        where_extra += " AND COALESCE(lf_e.file_path, lf_g.file_path) IS NOT NULL AND COALESCE(p_e.media_folder, p_g.media_folder) IS NULL"
    elif status == "dl_missing":
        # v1.11.62: rows where motif HAS a local_files entry pointing
        # at a canonical that no longer exists on disk. The placement
        # in the Plex folder (hardlink / copy) survives, so the row
        # reads as "still in Plex, not downloaded". Filter is applied
        # post-SQL via the canonical_missing stat in _annotate_canonical_state
        # — SQL just narrows to candidate rows (must have COALESCE(lf_e.file_path, lf_g.file_path)
        # AND COALESCE(p_e.media_folder, p_g.media_folder), otherwise canonical_missing is irrelevant).
        where_extra += (" AND COALESCE(lf_e.file_path, lf_g.file_path) IS NOT NULL "
                        "AND COALESCE(p_e.media_folder, p_g.media_folder) IS NOT NULL")
    elif status == "failures":
        # v1.10.50: only un-acknowledged failures land in this filter.
        # Acked rows keep their red TDB pill but don't show up here —
        # they're 'I know, dealt with it' state.
        # v1.13.54: per-section ack via sfa.acked_at also counts.
        where_extra += (" AND t.failure_kind IS NOT NULL "
                        " AND t.failure_acked_at IS NULL "
                        " AND sfa.acked_at IS NULL")
    elif status == "updates":
        # v1.11.74: items where ThemerrDB upstream changed the YouTube
        # URL since motif's last download. The pending_updates table
        # carries the diff with decision='pending'; ACCEPT replaces
        # motif's copy with a fresh download from the new URL, KEEP
        # leaves the current one alone (decision='declined'). Topbar
        # 'N UPD' badge counts these globally; this filter narrows
        # the library page to just the rows that are eligible.
        where_extra += (" AND EXISTS ("
                        "  SELECT 1 FROM pending_updates pu"
                        "   WHERE pu.media_type = t.media_type"
                        "     AND pu.tmdb_id = t.tmdb_id"
                        "     AND pu.decision = 'pending'"
                        ")")

    # v1.10.20: secondary 'TDB MATCH' filter, stacks on top of `status`.
    # 'tracked' means ThemerrDB has the title (the row's joined themes
    # record is a real upstream entry, not a plex_orphan). 'untracked'
    # is the inverse — Plex has the item but ThemerrDB doesn't, OR the
    # joined themes row is an orphan motif made up itself.
    # Useful for slicing MANUAL into 'I can REPLACE w/ TDB' vs 'no TDB
    # alternative exists'. No-op for status=themed (already tracked) /
    # status=untracked (already untracked) — frontend hides the
    # secondary toggle in those cases.
    if tdb == "tracked":
        where_extra += (" AND t.tmdb_id IS NOT NULL "
                        "AND t.upstream_source != 'plex_orphan'")
    elif tdb == "untracked":
        where_extra += " AND (t.tmdb_id IS NULL OR t.upstream_source = 'plex_orphan')"

    # v1.12.23: server-side pill filters. Pre-fix SRC and TDB pill
    # filters ran client-side after the server returned a page —
    # which made counts and pagination lie ("THEMED + M = 3,336"
    # whether or not M was actually selected, because the count
    # was the THEMED total). Now each pill axis composes with
    # `status` and `tdb` server-side, so total/pagination/sort all
    # honor the pill state.
    #
    # Each pill axis is multi-select. Selections within an axis OR
    # together; axes AND together. Empty set = no filter on that
    # axis. Mirrors the client-side computeSrcLetter / computeTdbPill
    # taxonomy exactly so the same row classification drives both
    # the row pill render and the filter set.
    src_pills = src_pills or set()
    tdb_pills = tdb_pills or set()
    dl_pills = dl_pills or set()
    pl_pills = pl_pills or set()
    link_pills = link_pills or set()
    ed_pills = ed_pills or set()
    if src_pills:
        # v1.12.95: route through _SRC_LETTER_SQL — single source of
        # truth for the pill, the SRC sort, and the row badge. Pre-fix
        # each pill had its own provenance-first predicate that
        # diverged from JS computeSrcLetter on rows where source_kind
        # disagreed with placement.provenance.
        # v1.13.31: 'P' filter expanded to match `plex_present=1`
        # regardless of the primary SRC letter — composite rows like
        # M+P (motif sidecar AND Plex serves a theme) should appear
        # in the P filter so the user can see every row where Plex
        # has a fallback. Other letters keep their original behavior
        # (filter by letter, ignore plex_present). Multi-select OR
        # semantics carry over: P + M selected = letter=M OR
        # plex_present=1.
        valid_letters = {"T", "U", "A", "M", "P", "-"}
        # v1.14.10: `Pp` is the composite-+P-only token — filter to rows
        # where Plex also serves its own theme AND the primary SRC
        # letter is one of T/U/A/M (matches the yellow-dot indicator
        # rendered on the row chip via `link-badge-also-plex`). Wire
        # token uses `Pp` because URL form-encoding turns `+` into a
        # space, but the button label is rendered as `+P` (its visual
        # meaning in the row).
        valid_tokens = valid_letters | {"Pp"}
        wanted = sorted(p for p in src_pills if p in valid_tokens)
        if wanted:
            non_p = [w for w in wanted if w not in ("P", "Pp")]
            include_p_flag = "P" in wanted
            include_plus_p_only = "Pp" in wanted
            clauses: list[str] = []
            # v1.14.99: when Pp is selected ALONGSIDE primary letters
            # (T/U/A/M/-), Pp acts as a NARROWING modifier rather than
            # an OR-extension. Pre-fix Pp + M emitted `letter='M' OR
            # composite-+P (any letter)` which surfaced every composite
            # row regardless of primary letter — the user wanted "M rows
            # that are also +P." With Pp + non_p, fold the composite
            # requirement into the non_p IN-clause as an AND. Pp alone
            # (no primary letters) keeps the all-composite shape.
            #
            # P + Pp + others stays separate: P is mutually-exclusive
            # with composite at the row level (P = Plex-only no motif
            # source; +P = motif source AND Plex source), so they OR
            # naturally. the user's spec: "if you did A and M would only
            # be rows that are M or A +P rows".
            pp_modifies_non_p = include_plus_p_only and bool(non_p)
            if non_p:
                placeholders = ",".join("?" for _ in non_p)
                if pp_modifies_non_p:
                    clauses.append(
                        f"(({_LIB_SRC_LETTER_SQL}) IN ({placeholders}) "
                        "AND pi.plex_independent_theme = 1)"
                    )
                else:
                    clauses.append(
                        f"({_LIB_SRC_LETTER_SQL}) IN ({placeholders})"
                    )
                params.extend(non_p)
            if include_p_flag:
                # v1.13.43: pre-v1.14.13 the P pill was an OR
                # (pure-P OR composite-+P) because there was no
                # other surface for the composite case.
                # v1.14.13: now that the +P pill (wire token 'Pp',
                # added v1.14.10/v1.14.11) exclusively filters the
                # composite case, the plain P pill narrows to
                # PURE-P only — the rows where Plex serves the
                # theme AND motif owns nothing. Composite rows
                # have their own pill and shouldn't double-count
                # in P. Per the user: "since we have a +p filter now
                # can we remove yellow dot results from the P
                # filter".
                clauses.append("(" + _LIB_SRC_LETTER_SQL + ") = 'P'")
            if include_plus_p_only:
                # v1.14.99: skip the stand-alone composite clause when
                # Pp is already folded into the non_p AND-narrowed
                # clause above. OR-ing it back in would re-widen to
                # all composite rows and undo the user's narrowing intent.
                if not pp_modifies_non_p:
                    # v1.14.10: composite-+P only — exactly the rows
                    # the row pill renders with the yellow-dot
                    # indicator (link-badge-also-plex). The dot fires
                    # when plex_independent_theme=1 AND the primary
                    # SRC letter is in {T,U,A,M} — pure-P rows render
                    # as a plain P chip (no dot, no underlying
                    # placement to call composite), and src='-' rows
                    # have nothing to composite with. Same predicate
                    # as the JS render gate at app.js:5056.
                    clauses.append(
                        "(pi.plex_independent_theme = 1 "
                        f" AND ({_LIB_SRC_LETTER_SQL}) NOT IN ('P', '-'))"
                    )
            if clauses:
                where_extra += " AND (" + " OR ".join(clauses) + ")"
    if tdb_pills:
        DEAD_KINDS = "('video_private','video_removed','video_age_restricted','geo_blocked')"
        # Subquery snippet reused below — "this row has an actionable
        # pending update". Mirrors the v1.12.5 row-pill priority:
        # update wins over the green-tdb pill in the row render, so
        # the filter excludes update rows from the green-tdb match
        # set (and includes them in the blue-update match set, gated
        # on src != '-' per JS computeTdbPill).
        # v1.12.108: gate on per-section decision (pu_sec → pu_global
        # fallback) and motif tracking presence in this section, to
        # match the read path's pending_update field. CASE wrap
        # forces a 0/1 boolean — pre-fix the bare COALESCE = 'pending'
        # comparison returned NULL for rows with no pending_updates
        # row, and `NOT NULL` evaluated as NULL/false in the WHERE,
        # accidentally excluding clean TDB rows from the tdb_pills=tdb
        # filter.
        # v1.12.119: align PENDING_EXISTS exactly with the library SQL's
        # pending_update field so the tdb_pills=update filter and the
        # blue ↑ row pill match the same set of rows. Two changes
        # vs the prior version:
        # - decision IN ('pending','declined') (was just 'pending').
        #   The blue pill stays after KEEP CURRENT for filter/sort
        #   per v1.12.5; pre-fix the filter excluded declined rows
        #   even though they still showed the pill, so clicking the
        #   chip surfaced fewer rows than the user could see.
        # - no-op gate: kind='urls_match' OR new_url != applied.
        #   T rows where applied URL == TDB's URL render no pill
        #   (pending_update suppressed in v1.12.119); the filter
        #   matches that suppression.
        PENDING_EXISTS = (
            "(CASE WHEN COALESCE("
            "  (SELECT pu.decision FROM pending_updates pu "
            "    WHERE pu.media_type = t.media_type "
            "      AND pu.tmdb_id = t.tmdb_id "
            "      AND pu.section_id = pi.section_id AND pu.edition_key = pi.edition_key),"
            "  (SELECT pu.decision FROM pending_updates pu "
            "    WHERE pu.media_type = t.media_type "
            "      AND pu.tmdb_id = t.tmdb_id "
            "      AND pu.section_id = '' AND pu.edition_key = pi.edition_key)"
            ", 'pending') IN ('pending','declined')"
            f"  AND {_pending_update_detected_sql('t', 'pi')}"
            " AND ("
            "  EXISTS (SELECT 1 FROM local_files lf2 "
            "           WHERE lf2.media_type = t.media_type "
            "             AND lf2.tmdb_id = t.tmdb_id "
            "             AND lf2.section_id = pi.section_id)"
            "  OR EXISTS (SELECT 1 FROM user_overrides uo2 "
            "              WHERE uo2.media_type = t.media_type "
            "                AND uo2.tmdb_id = t.tmdb_id "
            "                AND uo2.section_id = pi.section_id)"
            "  OR EXISTS (SELECT 1 FROM placements p2 "
            "              WHERE p2.media_type = t.media_type "
            "                AND p2.tmdb_id = t.tmdb_id "
            "                AND p2.section_id = pi.section_id)"
            "  OR pi.local_theme_file = 1"
            # v1.20.11: SRC=— new_theme_available escape — mirror the
            # canonical pill-render presence gate (the `pending_update`
            # column, ~line 2620). Pre-fix PENDING_EXISTS had the escape
            # only in its KIND gate, not here, so a SRC=— new-theme row
            # (no local_files/override/placement/sidecar) fell out of the
            # blue TDB↑ `update` filter AND wrongly into the green `tdb`
            # filter (NOT PENDING_EXISTS) — even though the pill, the UPD
            # badge, and the attn_pills=update filter all surface it. A
            # v1.19.72 mirror-drift miss (the count-floor guard didn't pin
            # this site).
            f"  OR {_pending_update_new_theme_kind_sql('t', 'pi')}"
            ")"
            # v1.22.10: actionable-gate via the shared helper (was inlined);
            # the pill columns + attn filter + NEEDS WORK sort use the same one.
            f"  AND {_pending_update_actionable_sql('t', 'pi')}"
            " THEN 1 ELSE 0 END) = 1"
        )
        # JS computeSrcLetter returns '-' when nothing's themed
        # anywhere on the row — no placement, no sidecar, no Plex
        # agent, no canonical. The blue-update pill is hidden on
        # those rows because there's nothing to "update from"; the
        # `update` filter mirrors the gate.
        SRC_NOT_DASH = (
            "(COALESCE(p_e.media_folder, p_g.media_folder) IS NOT NULL"
            " OR pi.local_theme_file = 1"
            " OR pi.has_theme = 1"
            " OR COALESCE(lf_e.file_path, lf_g.file_path) IS NOT NULL"
            # v1.19.71: SRC=— exception for kind='new_theme_
            # available' so the `update` filter chip surfaces
            # unthemed rows where sync just discovered a brand-
            # new TDB theme. Mirrors the same exception in JS
            # computeTdbPill + the title-glyph cascade.
            f" OR {_pending_update_new_theme_kind_sql('t', 'pi')})"
        )
        branches = []
        for p in tdb_pills:
            if p == "tdb":
                # v1.12.95: green TDB pill render is the FALLTHROUGH
                # in JS computeTdbPill — wins only when none of
                # update / dead-failure / cookies-blocked match.
                # Strict alignment now: also exclude pending_update +
                # dead-failure (and cookies_expired when no cookies
                # present).
                # v1.13.1 (Phase C): also exclude dropped items so
                # they show as gray TDB◌ exclusively, not green.
                # v1.24.75: green TDB now requires a non-empty youtube_url —
                # a tracked-but-themeless record (upstream set, no URL) renders
                # the muted TDB ∅ pill (v1.24.73) + matches the new `empty`
                # branch below, NOT green. Keeps the axis a clean partition so
                # the green chip's "URL is healthy" gloss stays truthful.
                if cookies_present:
                    branches.append(
                        "(t.upstream_source IN ('imdb','themoviedb') "
                        "AND NULLIF(t.youtube_url, '') IS NOT NULL "
                        "AND (t.failure_kind IS NULL OR t.failure_kind = 'cookies_expired') "
                        f"AND NOT {PENDING_EXISTS} "
                        "AND t.tdb_dropped_at IS NULL)"
                    )
                else:
                    branches.append(
                        "(t.upstream_source IN ('imdb','themoviedb') "
                        "AND NULLIF(t.youtube_url, '') IS NOT NULL "
                        "AND t.failure_kind IS NULL "
                        f"AND NOT {PENDING_EXISTS} "
                        "AND t.tdb_dropped_at IS NULL)"
                    )
            elif p == "empty":
                # v1.24.75: tracked-but-themeless — ThemerrDB lists the title
                # (upstream_source set) but has no theme video (youtube_url
                # empty). Mirrors the TDB ∅ row-pill render gate (app.js): not
                # dropped, not a failure, no pending update. Disjoint from the
                # tightened green `tdb` branch above.
                branches.append(
                    "(t.upstream_source IN ('imdb','themoviedb') "
                    "AND NULLIF(t.youtube_url, '') IS NULL "
                    "AND t.failure_kind IS NULL "
                    f"AND NOT {PENDING_EXISTS} "
                    "AND t.tdb_dropped_at IS NULL)"
                )
            elif p == "update":
                # v1.12.48: scoped to decision='pending' (was IN
                # ('pending','declined')) so the filter matches the
                # topbar UPD count exactly. Clicking the UPD badge
                # now lands the user on a list with the same
                # cardinality the badge advertised. KEEP CURRENT
                # decisions still light up the row's blue pill but
                # are excluded from this filter — the user already
                # said they don't want to act on them.
                # v1.12.95: also gate on src != '-' to mirror JS
                # computeTdbPill. Pre-fix unthemed rows with stale
                # pending_updates lit up the update filter even
                # though their row-pill rendered green/none.
                branches.append(f"({PENDING_EXISTS} AND {SRC_NOT_DASH})")
            elif p == "cookies":
                # v1.15.58: dropped the `if not cookies_present:`
                # gate. Mirror-principle leak from v1.15.38 — that
                # tag fixed the same bug on the ATTN pill axis
                # (line ~1383) with the right rationale: "the row
                # remains in the cookies-expired state until a
                # probe / download runs against it with cookies
                # present to clear failure_kind, regardless of
                # whether cookies.txt is currently configured."
                # The TDB pill axis was overlooked in that pass.
                # Pre-fix: cookies_present=True (the user's setup —
                # has cookies.txt in /config) → branch never
                # appended → filter became a no-op → all rows
                # shown when user picked the yellow ⚿ chip.
                # the user: "filter not applying it appears."
                branches.append("(t.failure_kind = 'cookies_expired')")
            elif p == "dead":
                branches.append(f"(t.failure_kind IN {DEAD_KINDS})")
            elif p == "none":
                branches.append("(t.tmdb_id IS NULL OR t.upstream_source = 'plex_orphan')")
            elif p == "dropped":
                # v1.13.1 (Phase C): gray TDB◌ pill — TDB used to
                # publish this title, then stopped. Set by sync's
                # drop-detection sweep; cleared on re-add or via
                # ACK DROP. Independent of failure_kind (an item
                # can be dropped AND have a broken URL — both
                # surface to the user).
                branches.append("(t.tdb_dropped_at IS NOT NULL)")
        if branches:
            where_extra += " AND (" + " OR ".join(branches) + ")"
    # v1.13.68: ATTN (attention) pill axis. Mirrors the title-cell
    # `!`-glyph priority logic so the chip row makes the same rows
    # visible that the glyphs already advertise. 'broken' is handled
    # at the route level (effective_status='dl_missing') for sole-
    # broken selections.
    # v1.15.39: mixed-with-broken (broken + cookies, broken + fail,
    # etc.) used to silently drop the broken value because the SQL
    # attn loop has no branch for it. Now: when broken is in
    # attn_pills, skip the SQL attn_branches entirely + post-stat
    # OR-filter with a Python attn-matcher (same pattern as the
    # dl_pills / pl_pills broken handling). Trades a larger
    # unbounded SQL result for correct OR semantics.
    attn_needs_post_stat = (
        attn_pills is not None and "broken" in attn_pills
    )
    attn_pills = attn_pills or set()
    if attn_pills and not attn_needs_post_stat:
        attn_branches = []
        for p in attn_pills:
            if p == "fail":
                # Un-acked failure (red ⚠ glyph). title-cell logic at
                # ~line 4859: failure_kind set AND no ack on either
                # the global theme row OR the per-section sfa row.
                # v1.15.38: kept ack-aware (NOT broadened, unlike
                # the COOKIES branch below). The FAIL chip's
                # historical semantic is "needs-action count" —
                # acking a failure intentionally removes it from
                # the count (and from this filter). The count + the
                # filter remain aligned. v1.15.33's REPROBE
                # FAILURES broadening is a separate axis (re-probe
                # button intent ≠ filter intent). the user's
                # explicit complaint was COOKIES, not FAIL — left
                # FAIL untouched to avoid inadvertently breaking
                # the chip-count alignment users have built mental
                # models around.
                attn_branches.append(
                    "(t.failure_kind IS NOT NULL "
                    " AND t.failure_acked_at IS NULL "
                    " AND sfa.acked_at IS NULL)"
                )
            elif p == "update":
                # Actionable pending TDB update (blue ! glyph).
                # v1.13.86: tightened to match the badge-count
                # predicate (api.py:2869-2929). Pre-v1.13.86 the
                # filter was "permissive" (just EXISTS pending +
                # SRC != '-') which produced the surprising
                # "1 UPD badge → 28 matches in library" gap the user
                # hit — the count excludes pure-P rows (Plex
                # serves theme but motif owns nothing → nothing to
                # accept) and rows where the new URL already equals
                # the currently-applied URL (no-op urls_match
                # entries left over from prior accepts). The filter
                # now mirrors both: requires motif tracking presence
                # in this section AND a real URL diff.
                # v1.18.67: decision check is now section-scoped
                # (per-section first, '' fallback). Pre-fix the
                # EXISTS subquery walked pending_updates without
                # section_id filter, so a KEEP CURRENT on section
                # 3 (writes decision='declined' to pu_sec) left
                # the '' global row at decision='pending' →
                # filter still matched and the row stayed in the
                # // NEEDS WORK / status=! result set even though
                # the row's blue ! exclamation had cleared.
                # the user's repro: "selecting keep current removes
                # the blue ! at the start of the row but the
                # filter still tracks it as having the blue !
                # and doesn't go away." The row exclamation gates
                # on the SECTION-SCOPED actionable_update flag
                # (api.py:2155, uses COALESCE(pu_sec, pu_global)
                # = 'pending'), so the filter must mirror that
                # exact predicate. Class-9 mirror-drift sibling
                # of v1.18.65's TDB-pill priority fix.
                attn_branches.append(
                    "(COALESCE("
                    "    (SELECT pu.decision FROM pending_updates pu "
                    "      WHERE pu.media_type = t.media_type "
                    "        AND pu.tmdb_id = t.tmdb_id "
                    "        AND pu.section_id = pi.section_id AND pu.edition_key = pi.edition_key), "
                    "    (SELECT pu.decision FROM pending_updates pu "
                    "      WHERE pu.media_type = t.media_type "
                    "        AND pu.tmdb_id = t.tmdb_id "
                    "        AND pu.section_id = '' AND pu.edition_key = pi.edition_key)"
                    "  , 'pending') = 'pending' "
                    f"  AND {_pending_update_detected_sql('t', 'pi')} "
                    # v1.19.72: SRC=— exception for new_theme_available
                    # mirrors the JS computeTdbPill / title-glyph gates.
                    # Pre-v1.19.72 the attn_pills=update filter chip
                    # hid the very rows v1.19.71 surfaces — visible blue
                    # !UPD on the row, but clicking the ATTN!update
                    # chip filtered them out. Class-9 mirror-drift.
                    f"   AND (({_LIB_SRC_LETTER_SQL}) != '-'"
                    f"        OR {_pending_update_new_theme_kind_sql('t', 'pi')}) "
                    # Has-something check: motif must track this
                    # section's row, otherwise ACCEPT is a no-op
                    # (no canonical to update). v1.19.72: widened
                    # with the new kind so SRC=— rows pass.
                    "   AND ("
                    "     EXISTS (SELECT 1 FROM local_files lf2 "
                    "              WHERE lf2.media_type = t.media_type "
                    "                AND lf2.tmdb_id = t.tmdb_id "
                    "                AND lf2.section_id = pi.section_id) "
                    "     OR EXISTS (SELECT 1 FROM user_overrides uo2 "
                    "                 WHERE uo2.media_type = t.media_type "
                    "                   AND uo2.tmdb_id = t.tmdb_id "
                    "                   AND uo2.section_id = pi.section_id) "
                    "     OR COALESCE(p_e.media_folder, p_g.media_folder) IS NOT NULL "
                    "     OR pi.local_theme_file = 1"
                    f"    OR {_pending_update_new_theme_kind_sql('t', 'pi')}"
                    "   )"
                    # URL-diff check: the new TDB URL must actually
                    # differ from what's currently applied. Rows
                    # where they already match (legacy urls_match
                    # entries that weren't cleaned up) are no-ops.
                    # v1.22.10: actionable-gate via the shared helper (was
                    # inlined) so this attn_pills=update filter can't drift from
                    # the pill columns / tdb filters / NEEDS WORK sort.
                    f"   AND {_pending_update_actionable_sql('t', 'pi')}"
                    ")"
                )
            elif p == "cookies":
                # v1.15.17: cookies-needed STATUS pill. Filters to
                # rows whose failure_kind = 'cookies_expired'. NOT
                # gated on cookies_present — the row remains in the
                # cookies-expired state until a probe / download runs
                # against it with cookies present to clear
                # failure_kind, regardless of whether cookies.txt is
                # currently configured.
                # v1.15.38: dropped the ack predicates (same fix as
                # the FAIL branch above). the user: "the yellow TDB
                # Pill filter wasn't filtering properly." Pre-fix
                # the row's yellow ⚿ pill rendered on
                # `failure_kind === 'cookies_expired'` (no ack
                # check) but the filter SQL gated on the ack
                # predicates → click pill → fewer rows than visible
                # yellow pills. Mirrors v1.15.33's REPROBE FAILURES
                # broadening logic.
                attn_branches.append(
                    "(t.failure_kind = 'cookies_expired')"
                )
            elif p == "mismatch":
                # Canonical content diverged from the placement file
                # (amber ! M glyph). title-cell line ~4892.
                attn_branches.append("(COALESCE(lf_e.mismatch_state, lf_g.mismatch_state) = 'pending')")
            elif p == "await":
                # Downloaded canonical, no placement (amber ! P glyph).
                # title-cell line ~4898 (awaitingApproval). The
                # 'no job_in_flight' part of the gate is cosmetic;
                # excluding it here keeps the SQL simple and lets
                # in-flight rows show in the filter (they'll drain).
                # v1.14.39: exclude LPS state (Let-Plex-Serve) —
                # rows where Plex is serving its own theme AND motif
                # has a canonical (intentional post-LET-PLEX-SERVE
                # state, not "needs placement"). Discriminator is
                # plex_independent_theme=1, set by plex_enum + the
                # REPROBE PLEX THEMES sweep. The row gets a new BLUE
                # PL chip + blue title glyph in the renderer (JS
                # mirror at app.js `lpsState`), distinguishing
                # "intentional, recoverable" from "actually awaiting
                # placement". the user's repro: post-v1.14.27 LET PLEX
                # SERVE rows polluted the // NEEDS WORK count.
                # v1.24.43: the attn_pills=await filter — "downloaded but not
                # placed" (_LIB_AWAIT_SQL). v0.50.34: the topbar AWAIT badge that
                # shared this predicate was removed; the filter + PL=await stay.
                attn_branches.append(_LIB_AWAIT_SQL)
            elif p == "restore":
                # v1.23.7: restorable previous-URL snapshot — the
                # post-PURGE zombie state (v1.12.64 keeps the
                # snapshot through PURGE/UNMANAGE; v1.17.24 zombies
                # the orphan row so the join survives). the user: "I
                # don't think we have a way to filter find rows that
                # are in this state."
                # v1.23.10: mirror the FULL SOURCE-menu gate, not just
                # the snapshot-differs check. the user's repro: dozens of
                # U-rows matched whose snapshot is a themerrdb-kind
                # capture (SET URL stashed the old TDB URL) — the menu
                # suppresses REVERT for those (v1.12.65: DOWNLOAD TDB
                # covers them) and revert_redundant suppresses no-op
                # reverts, so the pill surfaced rows with no RESTORE/
                # REVERT action anywhere.
                # v1.23.11: narrow to the RESTORE-labeled subset.
                # Round 2 of the user's repro: themed T/P rows whose
                # user-kind snapshot came from ACCEPT UPDATE ("user
                # URL captured for revert") still matched — there the
                # menu offers REVERT as a plain undo on a healthy
                # row. ↩ means "theme destroyed but recoverable", and
                # the JS draws exactly that line with the button
                # label: `isRestore = srcLetter '-' or 'M'` (app.js
                # renderLibraryRow). So the pill is the menu gate
                # (`has_previous_url && !revert_redundant`) AND the
                # isRestore condition, via the shared SQL constants.
                attn_branches.append(
                    f"(({_PREV_URL_DIFFERS_SQL})\n"
                    f" AND NOT ({_REVERT_REDUNDANT_SQL})\n"
                    f" AND ({_LIB_SRC_LETTER_SQL}) IN ('-', 'M'))"
                )
            elif p == "repush":
                # v1.24.40: re-push needed (orange ⟳ title glyph + RP LINK
                # badge). Reuses _LIB_STALE_PU_SQL — the SAME single source of
                # truth the link_pills=rp filter, the needs_repush render flag,
                # and the topbar RE-PUSH badge all use — so the ATTN chip can't
                # drift from the LINK chip (they filter the identical row set, two
                # entry points). the user wanted RP discoverable on the attention
                # axis (like the FAIL indicator), not only via the LINK filter.
                attn_branches.append(f"({_LIB_STALE_PU_SQL})")
        if attn_branches:
            where_extra += " AND (" + " OR ".join(attn_branches) + ")"
    # v1.12.81: when 'broken' is in dl_pills or pl_pills the filter
    # needs a post-SQL stat-check (canonical_missing / placement_missing
    # don't live in any column). Skip the SQL branch in that case and
    # let the post-filter step downstream apply the full dl_pills /
    # pl_pills selection. Without 'broken' the SQL branches stay so
    # the page query narrows efficiently.
    # v1.12.95: 'on' selections also need post-stat filtering because
    # `COALESCE(lf_e.file_path, lf_g.file_path) IS NOT NULL` (DL=on SQL) matches both intact and
    # missing-on-disk rows — same for `COALESCE(p_e.media_folder, p_g.media_folder) IS NOT NULL`
    # (PL=on). Without the post-stat narrowing, filtering by ON
    # silently includes rows whose row-pill renders BROKEN (red).
    # When `on` is selected we route the entire dl_pills / pl_pills
    # filter through the post-stat path (same trigger as `broken`)
    # so `_row_matches_dl` / `_row_matches_pl` apply the strict
    # canonical_missing / placement_missing exclusion.
    dl_needs_post_stat = ("on" in dl_pills) or ("broken" in dl_pills)
    pl_needs_post_stat = ("on" in pl_pills) or ("broken" in pl_pills)
    if dl_pills and not dl_needs_post_stat:
        branches = []
        for p in dl_pills:
            if p == "off":
                branches.append("(COALESCE(lf_e.file_path, lf_g.file_path) IS NULL)")
            # 'mismatch' was retired in v1.12.81 — content divergence
            # is a LINK fact (link_pills 'm') and a row-title `!`
            # glyph; DL no longer doubles up.
        if branches:
            where_extra += " AND (" + " OR ".join(branches) + ")"
    if pl_pills and not pl_needs_post_stat:
        branches = []
        for p in pl_pills:
            if p == "off":
                # v1.18.25: 'off' excludes plex_upload placements
                # (they have placement_kind='plex_upload' even
                # though media_folder='' is technically the
                # empty-string sentinel). Pre-fix `media_folder
                # IS NULL` matched both NO placement AND
                # plex_upload's empty-string placement → off
                # over-included pushed rows.
                branches.append(
                    "(COALESCE(p_e.placement_kind, p_g.placement_kind) IS NULL)"
                )
            # v1.12.70: 'await' — canonical exists but no placement
            # row (typically post-DEL: the user removed the file from
            # the Plex folder but motif's canonical still lives in
            # /themes). Mirrors the JS computeSrcLetter awaitingApproval
            # gate; lets users find every row that needs a PLACE →
            # PUSH TO PLEX (or REMOVE → PURGE) without scrolling.
            elif p == "await":
                # v0.51.36 (the user): exclude backup_only (terminal TB state) —
                # mirrors the JS awaitingApproval + _LIB_AWAIT_SQL exclusion.
                # v0.51.68 (complexity audit): also exclude over_ceiling, matching
                # _LIB_AWAIT_SQL (v1.24.46) — this branch had drifted, keeping the
                # doomed-upload terminal rows in the pl=await filter.
                branches.append(
                    "(COALESCE(p_e.media_folder, p_g.media_folder) IS NULL "
                    " AND COALESCE(p_e.placement_kind, p_g.placement_kind) IS NULL "
                    " AND COALESCE(lf_e.file_path, lf_g.file_path) IS NOT NULL "
                    " AND COALESCE(lf_e.last_place_attempt_reason, lf_g.last_place_attempt_reason) "
                    "     IS NOT 'backup_only' "
                    " AND COALESCE(lf_e.last_place_attempt_reason, lf_g.last_place_attempt_reason) "
                    "     IS NOT 'plex_rejected:over_ceiling')"
                )
            # v1.18.30: removed the pl_pills='pushed' SQL branch.
            # Its predicate was the literal same SQL as
            # link_pills='pu' (placement_kind = 'plex_upload') so
            # the cyan PL filter chip and cyan PU LINK chip always
            # selected identical rows. The chip was retired; LINK=PU
            # is the canonical "filter to API-pushed rows" surface.
            # PL='on' was simultaneously widened back to cover
            # plex_upload rows (see _row_matches_pl below) so the
            # PL axis stays a pure health axis.
        if branches:
            where_extra += " AND (" + " OR ".join(branches) + ")"
    if link_pills:
        branches = []
        for p in link_pills:
            if p == "hl":
                branches.append("(COALESCE(p_e.placement_kind, p_g.placement_kind) = 'hardlink' AND COALESCE(lf_e.mismatch_state, lf_g.mismatch_state) IS NULL)")
            elif p == "c":
                branches.append("(COALESCE(p_e.placement_kind, p_g.placement_kind) = 'copy' AND COALESCE(lf_e.mismatch_state, lf_g.mismatch_state) IS NULL)")
            elif p == "m":
                # v1.12.95: gate on `placed` so the filter mirrors JS
                # `isMismatch && placed` — the M badge only paints
                # when there's a placement to be in mismatch with.
                # Pre-fix the SQL matched any mismatch_state row,
                # which could include orphan-placement edge cases.
                branches.append("(COALESCE(lf_e.mismatch_state, lf_g.mismatch_state) IS NOT NULL AND COALESCE(p_e.media_folder, p_g.media_folder) IS NOT NULL)")
            elif p == "ps":
                # v1.19.66: PS chip removed. The historical
                # `link_pills=ps` URL param is honored as a no-op
                # (matches nothing) to keep existing bookmarks
                # / deep-links from 500ing — they just return an
                # empty result set. To filter the equivalent
                # cohort post-v1.19.66, combine SRC=P chip with
                # LINK=— chip (the two-axis AND surfaces
                # "Plex source + no motif placement/backup").
                # Background: PS was rendered vestigial by the
                # v1.19.61 PS→BK unification (the LET-PLEX-SERVE
                # outcome now stamps backup_only → paints BU).
                # v1.19.64 widened PS to cover pure-P rows, which
                # produced 5,240 amber chips on the user's prod
                # library — visual chip-soup. Reverted.
                branches.append("(1 = 0)")
            elif p == "pu":
                # v1.18.22: PU = Pushed (placement_kind='plex_upload').
                # Matches rows where motif uploaded the audio to
                # Plex's metadata via the collection-theme API
                # instead of placing a sidecar. Mirrors the JS
                # link-glyph-pu render and the data-link-pill="pu"
                # filter chip in library.html. The +P composite
                # stamp is suppressed for these rows by plex_enum
                # (motif IS the source — no independent Plex theme).
                # v1.24.28: exclude STALE plex_uploads — those now read as the
                # RP (re-push) chip, not PU. A valid PU has theme_present NULL
                # (legacy/unchecked) or 1; a stale one is theme_present=0.
                branches.append(
                    "(COALESCE(p_e.placement_kind, p_g.placement_kind) = 'plex_upload' "
                    " AND COALESCE(p_e.theme_present, p_g.theme_present) IS NOT 0)"
                )
            elif p == "rp":
                # v1.24.28: RP = re-push needed — a plex_upload whose uploaded
                # rating_key was destroyed by a Plex delete+re-add
                # (verify_placement_health stamped theme_present=0). Mirrors the
                # _LIB_STALE_PU_SQL the SELECT uses to null media_folder + set
                # needs_repush, and the link-glyph-repush render.
                branches.append(f"({_LIB_STALE_PU_SQL})")
            elif p == "b":
                # v1.19.43: B = cloud-themes-backup. Matches rows
                # where the v1.19.42 walker staged Plex's own cloud
                # theme (source_kind='plex_cloud'). The
                # backup_only stamp + no-placement combo would
                # also match BK rows; the source_kind='plex_cloud'
                # discriminator narrows to ONLY walker-staged
                # cloud backups. Mirrors the JS link-glyph-b
                # render (isPlexCloudBackup predicate at app.js
                # ~8083) and the data-link-pill="b" chip in
                # library.html.
                branches.append(
                    "(COALESCE(lf_e.source_kind, lf_g.source_kind) = 'plex_cloud' "
                    " AND COALESCE(lf_e.last_place_attempt_reason, lf_g.last_place_attempt_reason) = 'backup_only' "
                    " AND COALESCE(p_e.media_folder, p_g.media_folder) IS NULL)"
                )
            elif p == "tb":
                # v1.19.90: TB = ThemerrDB Backup (source_kind=
                # 'themerrdb' + backup_only — the DOWNLOAD TDB BACKUP
                # flow). v1.20.20: comment refreshed for the v1.20.17 AB
                # split — backup chips now read by source four ways:
                # PB=plex_cloud, TB=themerrdb, AB=adopt, UB=user.
                # Mirrors the JS isTdbBackup predicate (app.js ~8062)
                # + the data-link-pill="tb" chip in library.html.
                branches.append(
                    "(COALESCE(lf_e.source_kind, lf_g.source_kind) = 'themerrdb' "
                    " AND COALESCE(lf_e.last_place_attempt_reason, lf_g.last_place_attempt_reason) = 'backup_only' "
                    " AND COALESCE(p_e.media_folder, p_g.media_folder) IS NULL)"
                )
            elif p == "ab":
                # v1.20.17: AB = Adopted Backup (source_kind='adopt' +
                # backup_only — an adopted sidecar staged as a backup,
                # motif owns the inode but left Plex serving). Split
                # out of BK/UB so the backup chips read by source:
                # PB=plex_cloud, TB=themerrdb, AB=adopt, UB=user.
                # Mirrors the JS isAdoptBackup predicate (app.js ~8107)
                # + the data-link-pill="ab" chip in library.html.
                branches.append(
                    "(COALESCE(lf_e.source_kind, lf_g.source_kind) = 'adopt' "
                    " AND COALESCE(lf_e.last_place_attempt_reason, lf_g.last_place_attempt_reason) = 'backup_only' "
                    " AND COALESCE(p_e.media_folder, p_g.media_folder) IS NULL)"
                )
            elif p == "bk":
                # v1.19.50: BK = user-explicit backup-only. Matches
                # rows with backup_only stamp but source_kind NOT
                # plex_cloud (the v1.19.43 B branch handles
                # plex_cloud explicitly). Complementary set: B + BK
                # together cover every backup_only row.
                # Mirrors the JS isBackupOnly predicate (app.js
                # ~8083, NOT the isPlexCloudBackup variant) and
                # the data-link-pill="bk" chip in library.html.
                # v1.19.90: also exclude 'themerrdb' — that's now the
                # TB branch above. v1.20.17: also exclude 'adopt' — now
                # the AB branch above. UB = user backup (url/upload +
                # NULL), B = plex_cloud, TB = themerrdb, AB = adopt.
                # The four partition every backup_only row.
                branches.append(
                    "(COALESCE(lf_e.last_place_attempt_reason, lf_g.last_place_attempt_reason) = 'backup_only' "
                    " AND (COALESCE(lf_e.source_kind, lf_g.source_kind) IS NULL "
                    "      OR COALESCE(lf_e.source_kind, lf_g.source_kind) NOT IN "
                    "         ('plex_cloud', 'themerrdb', 'adopt')) "
                    " AND COALESCE(p_e.media_folder, p_g.media_folder) IS NULL)"
                )
            elif p == "none":
                # v1.14.43: exclude LPS rows from the bare "no
                # placement" filter — they have their own PS chip
                # now. A row with no media_folder + LPS state
                # should match LINK=PS, not LINK=—. Without the
                # exclusion the same row would match both filters
                # and pollute the "—" result with intentional-LPS
                # rows. Discriminator: the same plex_independent_
                # theme=1 + has-canonical conditions as the ps
                # branch above.
                # v1.19.66: aligned with the post-PS-removal JS
                # render. Em-dash now paints on every row that
                # doesn't paint a more specific LINK chip
                # (HL/C/PU/M/BU/BP). SQL filter excludes:
                #   - placements with media_folder (HL/C/PU/M)
                #   - rows stamped backup_only (BU/BP)
                # Result: matches pure-P rows + truly-empty rows
                # + the rare lpsState case. Combine with SRC=P
                # chip to isolate the "Plex serves + no backup"
                # candidate cohort (the workflow PS used to
                # surface before v1.19.66 dropped it).
                # Earlier markers:
                #   v1.14.43 originally excluded LPS rows here.
                #   v1.19.65 widened to exclude every Plex-serving
                #   row to mirror the v1.19.64 PS widening.
                #   Both reverted in v1.19.66 along with PS chip
                #   removal.
                branches.append(
                    "(COALESCE(p_e.media_folder, p_g.media_folder) IS NULL "
                    " AND (COALESCE(lf_e.last_place_attempt_reason, lf_g.last_place_attempt_reason) IS NULL "
                    "      OR COALESCE(lf_e.last_place_attempt_reason, lf_g.last_place_attempt_reason) != 'backup_only'))"
                )
        if branches:
            where_extra += " AND (" + " OR ".join(branches) + ")"
    # v1.12.41: EDITION axis — match against the Plex folder
    # path's `{edition-...}` tag. SQL LIKE pattern is escape-safe
    # because the Plex folder convention is fixed (curly-brace
    # tags); no user-supplied substring lands in the pattern.
    if ed_pills:
        branches = []
        for p in ed_pills:
            if p == "has":
                branches.append("(pi.folder_path LIKE '%{edition-%')")
            elif p == "none":
                branches.append("(pi.folder_path IS NULL OR pi.folder_path NOT LIKE '%{edition-%')")
        if branches:
            where_extra += " AND (" + " OR ".join(branches) + ")"

    # v1.19.4: f-string so the urls_match gates below can interpolate
    # `_not_p_row_sql()` for the P-row exclusion. Body has no other
    # `{}` so f-string conversion is safe (verified at edit time).
    sql_select = f"""
        SELECT pi.rating_key, pi.section_id, pi.media_type AS plex_media_type,
               pi.title AS plex_title, pi.year, pi.guid_imdb, pi.guid_tmdb,
               pi.folder_path, pi.edition_key, pi.plex_edition_title,
               pi.has_theme AS plex_has_theme,
               pi.local_theme_file AS plex_local_theme,
               -- v1.12.112: HEAD-verified Plex theme claim. JS
               -- computeSrcLetter mirrors the SRC SQL's gate so the
               -- row badge agrees with the server-side classification.
               pi.plex_theme_verified_ok,
               -- v1.13.42: persisted +P composite signal (schema v39).
               -- JS render gate reads `it.plex_independent_theme === 1`
               -- to draw the amber +P dot on T/U/A/M chips. Without
               -- this select the field is undefined client-side and
               -- the gate never fires, so REPROBE updates never
               -- surface — exactly what happened in v1.13.38–.41.
               pi.plex_independent_theme,
               ps.title AS section_title,
               -- v0.51.23: the row's library resolution, so the JS can draw an
               -- amber 4K badge next to the title. In the // ALL view a title
               -- present in both the standard AND 4K sections is otherwise
               -- indistinguishable at a glance (the user).
               ps.is_4k AS section_is_4k,
               t.tmdb_id AS theme_tmdb, t.media_type AS theme_media_type,
               t.title AS theme_title, t.youtube_url, t.youtube_video_id,
               -- v1.12.107: row's currently-applied URL — matches the
               -- worker's two-step fetch (per-section override → ''
               -- override → themes.youtube_url). Surfaces so the SET
               -- URL dialog can warn when the user is about to set
               -- the same URL that's already applied (no-op overlap
               -- with the existing v1.12.54 TDB-match warning, which
               -- only catches the U→T conversion case).
               -- v1.21.60 (C2): per-edition override tier. Prefer THIS
               -- edition's section override, then the section's shared ('')
               -- override, then the title-global override, then TDB. A
               -- standard row (edition_key='') hits the same shared row as
               -- before — behavior-preserving; an edition with its own SET
               -- URL no longer reads a sibling's URL.
               COALESCE(
                 (SELECT youtube_url FROM user_overrides uo
                   WHERE uo.media_type = t.media_type
                     AND uo.tmdb_id = t.tmdb_id
                     AND uo.section_id = pi.section_id
                     AND uo.edition_key = pi.edition_key),
                 (SELECT youtube_url FROM user_overrides uo
                   WHERE uo.media_type = t.media_type
                     AND uo.tmdb_id = t.tmdb_id
                     AND uo.section_id = pi.section_id
                     AND uo.edition_key = ''),
                 (SELECT youtube_url FROM user_overrides uo
                   WHERE uo.media_type = t.media_type
                     AND uo.tmdb_id = t.tmdb_id
                     AND uo.section_id = ''),
                 t.youtube_url
               ) AS applied_youtube_url,
               t.failure_kind, t.failure_message,
               -- v1.13.54: failure_acked_at exposed to the row
               -- payload reflects EITHER the title-global ack
               -- (themes.failure_acked_at) OR a section-scoped
               -- ack (section_failure_acks.acked_at). COALESCE
               -- prefers the section-scoped timestamp when both
               -- are set (typically the more recent one).
               COALESCE(sfa.acked_at, t.failure_acked_at) AS failure_acked_at,
               t.upstream_source,
               -- v1.13.1 (Phase C): tdb_dropped_at drives the gray
               -- TDB◌ pill render and the ACK DROP / CONVERT TO
               -- MANUAL items in the SOURCE menu.
               t.tdb_dropped_at,
               COALESCE(lf_e.file_path, lf_g.file_path) AS file_path, COALESCE(lf_e.source_video_id, lf_g.source_video_id) AS source_video_id, COALESCE(lf_e.provenance, lf_g.provenance) AS provenance, COALESCE(lf_e.source_kind, lf_g.source_kind) AS source_kind,
               -- v1.19.21: surface last_place_attempt_reason so the JS
               -- can render a BK link-badge for backup-only intent
               -- rows (worker stamps 'backup_only' after a
               -- bulk_backup download with auto_place=false; the
               -- retry sweep skips on this reason; UI shows BK to
               -- signal "motif has file ready, not placed by intent").
               COALESCE(lf_e.last_place_attempt_reason, lf_g.last_place_attempt_reason) AS last_place_attempt_reason,
               -- v1.11.99: mismatch state drives the DL=amber + LINK=≠
               -- visual on the row and the PUSH TO PLEX / ADOPT FROM
               -- PLEX / KEEP MISMATCH branches in the PLACE menu.
               COALESCE(lf_e.mismatch_state, lf_g.mismatch_state) AS mismatch_state,
               -- v1.24.28: null out media_folder + placement_kind for a STALE
               -- plex_upload (uploaded rk destroyed by a Plex re-add) so every
               -- placed/SRC/PL read treats it as not-placed; needs_repush=1
               -- drives the RE-PUSH badge + keeps the row re-pushable.
               {_LIB_EFF_MEDIA_FOLDER} AS media_folder, CASE WHEN {_LIB_STALE_PU_SQL} THEN NULL ELSE COALESCE(p_e.placement_kind, p_g.placement_kind) END AS placement_kind, CASE WHEN {_LIB_STALE_PU_SQL} THEN 1 ELSE 0 END AS needs_repush, COALESCE(p_e.provenance, p_g.provenance) AS placement_provenance,
               -- v1.21.74: scope the in-flight download/place indicator to
               -- THIS edition. jobs has no edition_key column (it lives in
               -- the payload JSON since v1.21.54+), so match it with
               -- json_extract. Pre-fix the (mt,tmdb,section) match lit the
               -- "downloading" dot on EVERY edition of the title when one
               -- edition had a job in flight (the user: DOWNLOAD TDB BACKUP on
               -- Extended made all three LotR editions look like they were
               -- downloading). A job with no edition_key in payload ('' /
               -- legacy / generic title download) maps to the '' edition.
               (SELECT j.job_type FROM jobs j
                WHERE j.media_type = t.media_type AND j.tmdb_id = t.tmdb_id
                  AND j.section_id = pi.section_id
                  AND COALESCE(CASE WHEN json_valid(j.payload)
                                    THEN json_extract(j.payload, '$.edition_key')
                               END, '') = pi.edition_key
                  AND j.job_type IN ('download', 'place')
                  AND j.status IN ('pending', 'running')
                ORDER BY CASE j.status WHEN 'running' THEN 0 ELSE 1 END,
                         j.id DESC
                LIMIT 1) AS job_in_flight,
               -- v1.11.74 / v1.12.5: pending_update drives the blue
               -- TDB ↑ pill on the row. v1.12.5 split this from
               -- 'actionable_update' below so KEEP CURRENT can
               -- decrement the topbar counter without removing the
               -- pill itself — declined updates stay visible for
               -- filtering and sorting but no longer prompt for
               -- action.
               -- v1.12.99: pending_update / actionable_update /
               -- pending_update_kind resolve via the per-section
               -- LEFT JOIN with '' fallback. COALESCE picks the
               -- section's own decision when present; otherwise
               -- inherits from the title-global '' row that sync
               -- writes. Pre-v1.12.99 the EXISTS subqueries hit
               -- pending_updates without section_id filter, so a
               -- KEEP CURRENT on standard cleared the blue pill on
               -- 4K and the topbar UPD count under-reported.
               -- v1.12.108: gate on this section having motif
               -- tracking presence — local_files, user_overrides,
               -- placements, or a Plex sidecar. Pre-fix the
               -- title-global '' fallback row (sync's only write
               -- target) lit up every section that owned the
               -- title, including post-PURGE / pure-P / pure-'-'
               -- rows where motif has nothing to "update". Now
               -- the read path filters out those rows on the spot;
               -- the v1.12.49 sweep continues to delete pending_
               -- updates rows when the title has no presence in
               -- ANY section, but per-section read gating handles
               -- the partial-presence case (only one of N sections
               -- owns the title).
               -- v1.12.119: also gate on new_youtube_url differing
               -- from the row's current applied URL. Sync writes
               -- pending_updates whenever TDB has a URL and motif
               -- has tracking for the title — but for T rows where
               -- current = TDB URL, accepting would just re-download
               -- the same URL. No-op prompt. Suppress at read time.
               -- For U rows where override == TDB URL the existing
               -- 'urls_match' kind covers a different surface (U→T
               -- conversion); both predicates can fire simultaneously
               -- and we let urls_match through since it's a
               -- meaningful classification flip.
               (CASE WHEN COALESCE(pu_dsec.decision, pu_dglobal.decision, 'pending')
                          IN ('pending', 'declined')
                      AND COALESCE(pu_sec.kind, pu_global.kind) IS NOT NULL
                      AND (
                        EXISTS (SELECT 1 FROM local_files lf2
                                 WHERE lf2.media_type = t.media_type
                                   AND lf2.tmdb_id = t.tmdb_id
                                   AND lf2.section_id = pi.section_id)
                        OR EXISTS (SELECT 1 FROM user_overrides uo2
                                    WHERE uo2.media_type = t.media_type
                                      AND uo2.tmdb_id = t.tmdb_id
                                      AND uo2.section_id = pi.section_id)
                        OR EXISTS (SELECT 1 FROM placements p2
                                    WHERE p2.media_type = t.media_type
                                      AND p2.tmdb_id = t.tmdb_id
                                      AND p2.section_id = pi.section_id)
                        OR pi.local_theme_file = 1
                        OR {_pending_update_new_theme_kind_sql('t', 'pi')}
                      )
                      AND {_pending_update_actionable_sql('t', 'pi')}
                     THEN 1 ELSE 0 END) AS pending_update,
               COALESCE(pu_sec.kind, pu_global.kind) AS pending_update_kind,
               (CASE WHEN COALESCE(pu_dsec.decision, pu_dglobal.decision, 'pending') = 'pending'
                      AND COALESCE(pu_sec.kind, pu_global.kind) IS NOT NULL
                      AND (
                        EXISTS (SELECT 1 FROM local_files lf2
                                 WHERE lf2.media_type = t.media_type
                                   AND lf2.tmdb_id = t.tmdb_id
                                   AND lf2.section_id = pi.section_id)
                        OR EXISTS (SELECT 1 FROM user_overrides uo2
                                    WHERE uo2.media_type = t.media_type
                                      AND uo2.tmdb_id = t.tmdb_id
                                      AND uo2.section_id = pi.section_id)
                        OR EXISTS (SELECT 1 FROM placements p2
                                    WHERE p2.media_type = t.media_type
                                      AND p2.tmdb_id = t.tmdb_id
                                      AND p2.section_id = pi.section_id)
                        OR pi.local_theme_file = 1
                        OR {_pending_update_new_theme_kind_sql('t', 'pi')}
                      )
                      AND {_pending_update_actionable_sql('t', 'pi')}
                     THEN 1 ELSE 0 END) AS actionable_update,
               -- v1.12.86: previous-URL fields resolve from the
               -- previous_urls JOINs (pv_sec + pv_global). Each
               -- column's value comes from the section-specific row
               -- when present, falling back to the '' global row.
               -- Pre-v1.12.86 these came from title-global columns
               -- on the themes table; per-section keying eliminates
               -- cross-section bleed (PURGE in section A no longer
               -- overwrites the snapshot for section B).
               -- v1.13.4 (Issue 2): also require the previous URL to
               -- DIFFER from what's currently applied. If they match
               -- (commonly: a recent ACCEPT UPDATE captured the user's
               -- old URL into prev, but it was identical to the TDB
               -- URL), CLEAR URL would be a no-op and REVERT would
               -- just re-create the override at the same URL the row
               -- already has. Suppress has_previous_url=1 in that
               -- case so the SOURCE menu's CLEAR URL / REVERT items
               -- and the INFO card's "previous url" row hide.
               -- v1.18.8: NULL-safe inequality via `IS NOT` (SQLite
               -- extension). Pre-fix the `!=` comparison evaluated as
               -- UNKNOWN whenever the inner COALESCE returned NULL —
               -- which is exactly the post-PURGE zombie-orphan state
               -- (themes.youtube_url=NULL, no override row, no
               -- canonical). UNKNOWN treated as FALSE in CASE →
               -- has_previous_url=0 → RESTORE button never showed
               -- even though previous_urls had the captured URL.
               -- the user's exact symptom: "post PURGE only purge again
               -- shows, no RESTORE." `IS NOT` returns TRUE when
               -- captured-URL != NULL-current, exposing RESTORE.
               -- v1.23.10: boolean extracted to _PREV_URL_DIFFERS_SQL so the
               -- attn_pills=restore filter shares this exact text.
               (CASE WHEN {_PREV_URL_DIFFERS_SQL}
                     THEN 1 ELSE 0 END) AS has_previous_url,
               COALESCE(pv_sec.kind, pv_global.kind) AS previous_youtube_kind,
               -- v1.12.40: revert_redundant = the previous URL is
               -- a TDB URL AND it exactly matches the
               -- pending_updates.new_youtube_url that ACCEPT
               -- UPDATE would fetch. Reverting and accepting
               -- would download the same file, so REVERT is
               -- suppressed in the SOURCE menu to avoid two
               -- buttons that fire identical actions. Only
               -- triggers for previous_kind='themerrdb' — a
               -- user-kind previous URL stays revertible since
               -- it represents a meaningfully different state
               -- (the row would flip back to U).
               -- v1.12.53: also redundant when the previous URL
               -- equals the row's CURRENT canonical URL (the
               -- override URL when present, else themes.youtube_url).
               -- Covers the post-accept URL-match case: SET URL
               -- captured previous=TDB-URL, then ACCEPT UPDATE
               -- ran with url_match=True (override URL == TDB URL),
               -- decision flipped to 'accepted' so the original
               -- pending-updates clause no longer matches —
               -- but REVERT would just re-create the override
               -- pointing back at the current TDB URL, a no-op
               -- with extra UI churn. Suppress.
               -- v1.12.101: redundant only when there's a CURRENT
               -- canonical (COALESCE(lf_e.file_path, lf_g.file_path) IS NOT NULL). After PURGE
               -- or UNMANAGE the row has no canonical file but
               -- themes.youtube_url survives — the URL-equality
               -- check above would otherwise fire for the
               -- common case "previous_url captured at PURGE
               -- == themes.youtube_url" and hide RESTORE even
               -- though the row genuinely has no theme to
               -- play. Gating the redundancy check on
               -- "canonical exists" keeps RESTORE available
               -- whenever there's something to actually restore.
               -- v1.12.103: post-PURGE clean-overlap case —
               -- when the row has no canonical AND the captured
               -- URL is themerrdb-kind AND equals themes.youtube_url
               -- AND there's no hidden chain to preserve, RESTORE
               -- and DOWNLOAD TDB are functionally identical:
               -- both fetch the same URL into the canonical, no
               -- prior state to walk back to. Hide RESTORE in
               -- that exact case so the SOURCE menu doesn't
               -- carry two buttons with the same effect. The
               -- hidden_url IS NULL gate is load-bearing: a
               -- captured chain (PURGE on a row with a prior
               -- user URL) makes RESTORE → REVERT walk back to
               -- a URL DOWNLOAD TDB can't reach, so RESTORE is
               -- the unique way to start that walk. User-kind
               -- captures stay visible regardless (DOWNLOAD TDB
               -- can't reach a user URL). And if TDB has rolled
               -- the URL since the PURGE (themes.youtube_url
               -- changed), the URLs don't match and RESTORE
               -- locks to the captured URL — meaningfully
               -- different from DOWNLOAD TDB.
               -- v1.23.10: boolean (incl. branch history) extracted to
               -- _REVERT_REDUNDANT_SQL so the attn_pills=restore filter
               -- shares this exact text.
               (CASE WHEN {_REVERT_REDUNDANT_SQL}
                     THEN 1 ELSE 0 END) AS revert_redundant,
               -- v1.12.35: accepted_update = the row's pending
               -- update was ACCEPTed previously. Suppresses
               -- REPLACE TDB in the SOURCE menu since the
               -- canonical was just downloaded from the current
               -- TDB URL — re-running would just download the
               -- same file.
               -- v1.12.99: per-section via the COALESCE-of-LEFT-JOIN
               -- pattern (pu_sec wins, '' fallback otherwise).
               (CASE WHEN COALESCE(pu_dsec.decision, pu_dglobal.decision) = 'accepted'
                     THEN 1 ELSE 0 END) AS accepted_update
    """
    # v1.11.0: every per-row JOIN to placements / local_files matches
    # by section_id = pi.section_id, so a row on the standard library
    # never sees the 4K library's placement / file (and vice versa).
    # The pre-v1.11.0 v1.10.48 / v1.10.52 gymnastics that simulated
    # per-section keying via media_folder + EXISTS subqueries are gone;
    # the schema now genuinely keys these rows per-section.
    sql_from = """
        FROM plex_items pi
        INNER JOIN plex_sections ps
          ON ps.section_id = pi.section_id AND ps.included = 1
        -- v1.11.26: themes match comes from the denormalized
        -- pi.theme_id column (populated by plex_enum + sync via
        -- resolve_theme_ids). Pre-fix this was a per-row correlated
        -- subquery with 3-OR clauses + NOT EXISTS + ORDER BY + LIMIT
        -- 1 that ran ×N for every page render, taking 20+ seconds on
        -- a 4K-item library. The lookup is now a single PK touch per
        -- row.
        LEFT JOIN themes t ON t.id = pi.theme_id
        -- v1.21.59 (C1 dup-proof): two-tier per-edition join. p_e = THIS
        -- edition's placement, p_g = the shared '' one; the SELECT/WHERE
        -- read COALESCE(p_e.x, p_g.x) — prefer the edition's own row, fall
        -- back to shared. Two LEFT JOINs (each matches <=1) can't row-
        -- multiply the way `OR edition_key=''` could once a 2nd edition
        -- placement coexists (post-C2). Mirrors the pv_sec/pv_global +
        -- pu_sec/pu_global two-tier shape already used below.
        LEFT JOIN placements p_e
          ON p_e.media_type = t.media_type AND p_e.tmdb_id = t.tmdb_id
         AND p_e.section_id = pi.section_id
         AND p_e.edition_key = pi.edition_key
        LEFT JOIN placements p_g
          ON p_g.media_type = t.media_type AND p_g.tmdb_id = t.tmdb_id
         AND p_g.section_id = pi.section_id AND p_g.edition_key = ''
         -- v1.23.87: no '' placement fallback on a MULTI-edition title — an
         -- unplaced sibling (1408 Director's Cut) must not inherit the standard's
         -- placement. Mirrors the card's _info_single_edition gate (v1.21.95).
         AND (SELECT COUNT(DISTINCT _ec.edition_key) FROM plex_items _ec
              WHERE _ec.theme_id = pi.theme_id
                AND _ec.section_id = pi.section_id) <= 1
        LEFT JOIN local_files lf_e
          ON lf_e.media_type = t.media_type AND lf_e.tmdb_id = t.tmdb_id
         AND lf_e.section_id = pi.section_id
         AND lf_e.edition_key = pi.edition_key
        LEFT JOIN local_files lf_g
          ON lf_g.media_type = t.media_type AND lf_g.tmdb_id = t.tmdb_id
         AND lf_g.section_id = pi.section_id AND lf_g.edition_key = ''
         -- v1.23.87: keep the '' DOWNLOAD fallback when THIS edition has its own
         -- placement (p_e) — a placed edition sharing the '' download (v1.21.58
         -- transitional shape) still shows it; only an unplaced multi-edition
         -- sibling loses it.
         AND (p_e.media_folder IS NOT NULL
              OR (SELECT COUNT(DISTINCT _ec.edition_key) FROM plex_items _ec
                  WHERE _ec.theme_id = pi.theme_id
                    AND _ec.section_id = pi.section_id) <= 1)
        -- v1.12.86: per-section REVERT/RESTORE snapshot. Two
        -- LEFT JOINs (section-specific + '' fallback) so the SELECT
        -- can resolve the row's effective previous URL with one
        -- COALESCE rather than a per-row correlated subquery. The
        -- '' fallback row is populated by legacy callers that
        -- captured before per-section keying existed (or by future
        -- callers that genuinely want title-global semantics).
        LEFT JOIN previous_urls pv_sec
          ON pv_sec.media_type = t.media_type
         AND pv_sec.tmdb_id = t.tmdb_id
         AND pv_sec.section_id = pi.section_id
        LEFT JOIN previous_urls pv_global
          ON pv_global.media_type = t.media_type
         AND pv_global.tmdb_id = t.tmdb_id
         AND pv_global.section_id = ''
        -- v1.12.99: pending_updates is per-section as of schema v31.
        -- Two LEFT JOINs (section-specific + '' global fallback)
        -- mirror the previous_urls pattern. Library-row pending /
        -- actionable / kind columns resolve via COALESCE so each
        -- section's row reflects its own decision (KEEP CURRENT on
        -- standard doesn't bleed to 4K) and the '' row from sync
        -- still drives sections that haven't been independently
        -- accepted/declined.
        -- v1.21.81: pu_sec/pu_global are now DETECTION joins — pinned
        -- to edition_key='' (sync writes the kind/url detection there,
        -- edition-blind). Their .kind reads stay correct for every
        -- edition row. The .decision reads moved to the edition-filtered
        -- pu_dsec/pu_dglobal below so accepting one edition can't clear a
        -- sibling's blue !UPD pill (the user's 3-edition LotR repro).
        LEFT JOIN pending_updates pu_sec
          ON pu_sec.media_type = t.media_type
         AND pu_sec.tmdb_id = t.tmdb_id
         AND pu_sec.section_id = pi.section_id
         AND pu_sec.edition_key = ''
        LEFT JOIN pending_updates pu_global
          ON pu_global.media_type = t.media_type
         AND pu_global.tmdb_id = t.tmdb_id
         AND pu_global.section_id = ''
         AND pu_global.edition_key = ''
        -- v1.21.81: per-edition DECISION joins. edition_key=pi.edition_key
        -- filters the accept/decline to THIS row's edition (standard rows
        -- key '' = the old per-section behavior; non-standard editions read
        -- only their own decision, no cross-edition fallback). Mirrors the
        -- _pending_update scalar-subquery decision reads at the non-library
        -- sites (every `SELECT pu.decision` carries AND edition_key=pi*).
        LEFT JOIN pending_updates pu_dsec
          ON pu_dsec.media_type = t.media_type
         AND pu_dsec.tmdb_id = t.tmdb_id
         AND pu_dsec.section_id = pi.section_id
         AND pu_dsec.edition_key = pi.edition_key
        LEFT JOIN pending_updates pu_dglobal
          ON pu_dglobal.media_type = t.media_type
         AND pu_dglobal.tmdb_id = t.tmdb_id
         AND pu_dglobal.section_id = ''
         AND pu_dglobal.edition_key = pi.edition_key
        -- v1.13.54: per-section failure ack JOIN. sfa.acked_at is
        -- non-NULL when the user has explicitly dismissed the
        -- failure for THIS section (via info-card adopt-and-ack /
        -- purge-and-ack / clear-failure with section_id). Used
        -- alongside themes.failure_acked_at (title-global) so a
        -- row counts as acked when EITHER axis is set.
        LEFT JOIN section_failure_acks sfa
          ON sfa.media_type = t.media_type
         AND sfa.tmdb_id = t.tmdb_id
         AND sfa.section_id = pi.section_id
    """
    sql_from_pi_only = """
        FROM plex_items pi
        INNER JOIN plex_sections ps
          ON ps.section_id = pi.section_id AND ps.included = 1
    """
    sql_where = f"WHERE {tab_where}{where_extra}"
    # v1.11.14: COUNT path now picks the minimum FROM for the requested
    # filter. The heavy LEFT JOIN themes correlated subquery (×N rows on
    # an N-item library) was firing for every filter chip click in
    # v1.11.0+, making "downloaded", "manual", "placed", etc. take
    # 30+ seconds on a 10K-item library. Filters that don't reference
    # t.* in the WHERE skip the themes JOIN; lf and p use pi.guid_tmdb
    # directly (loses orphan-adopted matches in COUNT only — the row
    # query keeps the full themes JOIN for accuracy).
    # v1.12.23: pill axes also need their relevant table JOINs in
    # the slim count path. tdb_pills references t; src_pills /
    # dl_pills / link_pills reference lf and p; pl_pills references
    # p. Without these flags the count query would 500 on missing
    # column references.
    needs_themes_for_count = (
        status in ("themed", "untracked", "has_theme", "failures", "updates")
        or tdb != "any"
        or bool(tdb_pills)
        # v1.12.100: src_pills now route through _SRC_LETTER_SQL which
        # references t.upstream_source for the orphan/svid branch. The
        # slim count path's lf+p joins aren't enough; we also need t.
        # Pre-fix selecting any SRC pill 500'd with
        # "no such column: t.upstream_source" because the count query
        # was assembled without the themes JOIN.
        or bool(src_pills)
        # v1.13.85: attn_pills predicates reference t.failure_kind,
        # t.failure_acked_at, sfa.acked_at, EXISTS(pending_updates),
        # _SRC_LETTER_SQL — none reachable from sql_from_pi_only or
        # the slim path. Route attn_pills through the full FROM so
        # the count agrees with the row select. Pre-fix the slim
        # path silently dropped the predicate and returned the
        # unfiltered section total ("28 MATCHES" with 0 rendered
        # rows under ?attn_pills=update — the user's repro).
        or bool(attn_pills)
    )
    needs_lf_for_count = (
        status in (
            "manual", "plex_agent", "untracked", "has_theme",
            "downloaded", "unplaced",
        )
        # v1.13.32: pl_pills "await" branch references COALESCE(lf_e.file_path, lf_g.file_path)
        # ("COALESCE(p_e.media_folder, p_g.media_folder) IS NULL AND COALESCE(lf_e.file_path, lf_g.file_path) IS NOT NULL", see
        # ~line 1098). The slim count path was missing this trigger,
        # so a filter combo that landed only on PL=await (no
        # tdb_pills, no src_pills, etc. → not needs_themes_for_count)
        # produced sql_count without lf joined and 500'd with
        # "no such column: COALESCE(lf_e.file_path, lf_g.file_path)". Added bool(pl_pills) so
        # the count joins lf whenever PL is filtering. The rows
        # query already uses the full sql_from with lf joined.
        or bool(src_pills) or bool(dl_pills) or bool(link_pills)
        or bool(pl_pills)
    )
    needs_p_for_count = (
        status in (
            "manual", "plex_agent", "untracked", "has_theme",
            "placed", "unplaced",
        )
        or bool(src_pills) or bool(pl_pills) or bool(link_pills)
    )
    # v1.13.85: include attn_pills in the no_pills check so the
    # COUNT fast-path (sql_from_pi_only — no themes/lf/p/sfa
    # joins) is NOT taken when attn_pills is the only active
    # filter. Pre-fix the count returned the unfiltered section
    # total (e.g. "28 MATCHES" on a section with 28 items even
    # when ?attn_pills=update filtered the row list to 0) because
    # the slim FROM couldn't evaluate the EXISTS pending_updates +
    # SRC predicates the attn_pills branch needs. The body's
    # SELECT used the full FROM and rendered 0 rows correctly,
    # producing the visible mismatch between header count and
    # body count the user reported.
    no_pills = not (src_pills or tdb_pills or dl_pills or pl_pills
                    or link_pills or ed_pills or attn_pills)
    if status == "all" and tdb == "any" and no_pills:
        sql_count = (f"SELECT COUNT(*) {sql_from_pi_only} "
                     f"WHERE {tab_where}{where_pi_only}")
        count_params = params
    elif needs_themes_for_count:
        # Filter references t.* (themed, untracked, has_theme, failures,
        # or any tdb!='any') — fall back to the full FROM with the
        # correlated subquery.
        sql_count = f"SELECT COUNT(*) {sql_from} {sql_where}"
        count_params = params
    else:
        # Build a slim FROM with only the JOINs the WHERE references.
        # lf / p use pi.guid_tmdb directly (good enough for COUNT;
        # orphan-adopted items are rare and miscount slightly here).
        slim_parts = [sql_from_pi_only.strip()]
        if needs_p_for_count:
            # v1.21.59 (dup-proof): two-tier split mirrors the row query so
            # the header count agrees with the rendered rows.
            _slim_mt = ("(CASE pi.media_type WHEN 'show' THEN 'tv' "
                        "ELSE pi.media_type END)")
            slim_parts.append(
                f"LEFT JOIN placements p_e\n"
                f"  ON p_e.media_type = {_slim_mt}\n"
                f" AND p_e.tmdb_id = pi.guid_tmdb AND p_e.section_id = pi.section_id\n"
                f" AND p_e.edition_key = pi.edition_key\n"
                f"LEFT JOIN placements p_g\n"
                f"  ON p_g.media_type = {_slim_mt}\n"
                f" AND p_g.tmdb_id = pi.guid_tmdb AND p_g.section_id = pi.section_id\n"
                f" AND p_g.edition_key = ''\n"
                # v1.23.87: gate the '' placement fallback on single-edition
                # (guid_tmdb key) so the filter-pill COUNTS match the rows.
                f" AND (SELECT COUNT(DISTINCT _ec.edition_key) FROM plex_items _ec"
                f"      WHERE _ec.guid_tmdb = pi.guid_tmdb"
                f"        AND _ec.section_id = pi.section_id) <= 1"
            )
        if needs_lf_for_count:
            # v1.21.59 (dup-proof): two-tier split mirrors the row query.
            _slim_mt2 = ("(CASE pi.media_type WHEN 'show' THEN 'tv' "
                         "ELSE pi.media_type END)")
            slim_parts.append(
                f"LEFT JOIN local_files lf_e\n"
                f"  ON lf_e.media_type = {_slim_mt2}\n"
                f" AND lf_e.tmdb_id = pi.guid_tmdb AND lf_e.section_id = pi.section_id\n"
                f" AND lf_e.edition_key = pi.edition_key\n"
                f"LEFT JOIN local_files lf_g\n"
                f"  ON lf_g.media_type = {_slim_mt2}\n"
                f" AND lf_g.tmdb_id = pi.guid_tmdb AND lf_g.section_id = pi.section_id\n"
                f" AND lf_g.edition_key = ''\n"
                # v1.23.87: gate the '' download fallback on single-edition here —
                # the slim count joins p_e conditionally, so the p_e-present escape
                # the row query uses isn't available; a placed sibling sharing a ''
                # download is a rare transitional shape a distinct-folder library
                # doesn't have, so single-edition is close enough for the count.
                f" AND (SELECT COUNT(DISTINCT _ec.edition_key) FROM plex_items _ec"
                f"      WHERE _ec.guid_tmdb = pi.guid_tmdb"
                f"        AND _ec.section_id = pi.section_id) <= 1"
            )
        slim_from = "\n        ".join(slim_parts)
        sql_count = f"SELECT COUNT(*) {slim_from} {sql_where}"
        count_params = params

    # v1.22.93: the themes join accepts the theme_id linkage too —
    # Plex collections (and guid-less legacy-agent items) carry
    # NULL guid_tmdb and link via plex_items.theme_id (the v1.18.2
    # title_norm resolve), so the guid-only join made them invisible
    # to the missing-themes banner (the Collections tab always read
    # 0 missing even with TDB themes available). Same OR shape as
    # worker.py's new-themes-visibility check. COUNT(DISTINCT
    # pi.rating_key) dup-proofs the OR fan-out (a pathological row
    # whose guid and theme_id point at different themes rows would
    # otherwise count twice).
    sql_missing_count = f"""
        SELECT COUNT(DISTINCT pi.rating_key)
        FROM plex_items pi
        INNER JOIN plex_sections ps
          ON ps.section_id = pi.section_id AND ps.included = 1
        INNER JOIN themes t
          ON (t.id = pi.theme_id
              OR (t.tmdb_id = pi.guid_tmdb
                  AND t.media_type = (CASE pi.media_type WHEN 'show' THEN 'tv' ELSE pi.media_type END)))
        LEFT JOIN local_files lf
          ON lf.media_type = t.media_type AND lf.tmdb_id = t.tmdb_id
        WHERE {tab_where}
          AND lf.file_path IS NULL
          AND t.upstream_source != 'plex_orphan'
    """
    order_expr = _LIBRARY_SORTS_MAIN.get(sort, _LIBRARY_SORTS_MAIN["title"])
    direction = "DESC" if sort_dir == "desc" else "ASC"
    # Stable secondary sort by title so equal primary keys (lots of NULLs
    # in src/link) don't shuffle on every render.
    order_clause = f"ORDER BY {order_expr} {direction}, pi.title COLLATE NOCASE ASC"
    sql_rows = f"{sql_select} {sql_from} {sql_where} {order_clause} LIMIT ? OFFSET ?"
    # Single round-trip for the three banner-meta scalars added in v1.10.0.
    # Was three separate queries per request — now one. Each scalar is
    # already independently indexed; combining is purely a round-trip win.
    # v1.11.44: plex_enumerated is now scoped to the tab+fourk variant so
    # the "no Plex scan on record" banner stays visible per-library.
    # Pre-fix it asked "has *any* plex_items row ever been written?" —
    # so refreshing one library hid the prompt on every other untouched
    # library, leaving the user to wonder why their TV tab was blank.
    sql_meta = f"""
        SELECT
            EXISTS(SELECT 1 FROM plex_items pi
                    INNER JOIN plex_sections ps
                      ON ps.section_id = pi.section_id AND ps.included = 1
                    WHERE {tab_where})                               AS plex_enumerated,
            (SELECT MAX(finished_at) FROM jobs
              WHERE job_type = 'plex_enum' AND status = 'success') AS last_plex_enum_at,
            (SELECT MAX(finished_at) FROM sync_runs
              WHERE status = 'success')                            AS last_sync_at
    """
    offset = (page - 1) * per_page
    # v1.11.62: dl_missing requires post-SQL stat-check, which means
    # SQL pagination would lie about the total. For that filter,
    # fetch every candidate (no LIMIT) and paginate in Python below.
    # v1.12.81: DL=broken / PL=broken pills are also stat-driven —
    # SQL pagination would slice off broken candidates that happen
    # to fall outside the current page's window. Treat them like
    # status=dl_missing: load unbounded, post-filter, then paginate
    # in Python.
    needs_post_stat_pagination = (
        status == "dl_missing"
        or (dl_pills and ("broken" in dl_pills or "on" in dl_pills))
        or (pl_pills and ("broken" in pl_pills or "on" in pl_pills))
        # v1.15.39: attn_pills broken needs post-stat too — the
        # canonical_missing predicate isn't a column the SQL can
        # filter on. Mirrors the dl_pills / pl_pills broken case.
        or attn_needs_post_stat
    )
    sql_rows_unbounded = f"{sql_select} {sql_from} {sql_where} {order_clause}"
    with get_conn(db) as conn:
        if needs_post_stat_pagination:
            total = -1  # filled in after stat-check
            missing_count = conn.execute(sql_missing_count).fetchone()[0]
            all_rows = conn.execute(sql_rows_unbounded, params).fetchall()
            rows = all_rows  # paginate later
        else:
            total = conn.execute(sql_count, count_params).fetchone()[0]
            missing_count = conn.execute(sql_missing_count).fetchone()[0]
            rows = conn.execute(sql_rows, params + [per_page, offset]).fetchall()
        meta = conn.execute(sql_meta).fetchone()
    plex_enumerated = bool(meta["plex_enumerated"])
    last_plex_enum_at = meta["last_plex_enum_at"]
    last_sync_at = meta["last_sync_at"]
    plex_scan_stale = bool(
        plex_enumerated
        and last_sync_at
        and (not last_plex_enum_at or last_sync_at > last_plex_enum_at)
    )
    items = [dict(r) for r in rows]
    # v1.11.62: stat the canonical for each row that has a local_files
    # entry, so the UI can render a 'DL broken' state when motif's
    # canonical was deleted out from under it but the placement
    # survives. Cheap (one stat per row, current page only); skipped
    # entirely when themes_dir isn't configured.
    items = _annotate_canonical_state(items, themes_dir=themes_dir)
    if status == "dl_missing":
        items = [it for it in items if it.get("canonical_missing")]
        total = len(items)
        items = items[offset:offset + per_page]

    # v1.12.81: post-SQL filter for DL=broken / PL=broken. Both
    # require a stat-check that doesn't live in any column. When
    # 'broken' is in dl_pills or pl_pills the SQL skipped the
    # corresponding branch (see the dl_pills / pl_pills processing
    # earlier); we apply the full pill selection here so the result
    # honors all selected states (broken alone, broken + on, etc.).
    def _row_matches_dl(it, pills):
        for p in pills:
            if p == "on" and it.get("file_path") and not it.get("canonical_missing"):
                return True
            if p == "off" and not it.get("file_path"):
                return True
            if p == "broken" and it.get("canonical_missing"):
                return True
        return False

    def _row_matches_pl(it, pills):
        # v1.14.39: LPS state (Let-Plex-Serve) discriminator —
        # post-v1.14.27 LET PLEX SERVE leaves rows with canonical
        # but no placement, which would otherwise match `await`
        # (or `broken` once the placements row drops). Plex serves
        # its own theme (plex_independent_theme=1), so the gap is
        # intentional, not attention-needing. Both filter values
        # exclude LPS; the renderer surfaces them via a distinct
        # blue chip + title glyph. Mirror of the SQL exclusion in
        # the attn_pills="await" branch (see api.py ~1290).
        # v1.18.27: same plex_upload exclusion as the JS lpsState
        # derivation. Live plex_upload placement = motif IS
        # actively pushing → not LPS (which requires WITHDRAWAL).
        is_lps = (
            it.get("file_path")
            and not it.get("media_folder")
            and it.get("plex_independent_theme") == 1
            and it.get("placement_kind") != "plex_upload"
        )
        # v1.18.16: a plex_upload placement (collections — POST to
        # /library/metadata/{rk}/themes) has media_folder='' so
        # `not media_folder` is truthy in Python, but the row IS
        # placed via the API path. Exclude it from the await/off
        # matchers + count it as placed for `on`. Pre-fix the user's
        # collections rendered amber PL after a successful upload
        # because this matcher treated empty-string media_folder
        # as "no placement."
        is_plex_upload = it.get("placement_kind") == "plex_upload"
        # v1.18.30: 'on' covers BOTH sidecar AND plex_upload — back
        # to the v1.18.22 unified shape. The v1.18.25 split was
        # introduced to give the cyan PL=pushed FILTER chip a
        # distinct matcher; that chip was removed in v1.18.30 as
        # redundant with LINK=PU (literally same predicate). With
        # the chip gone the PL axis returns to a pure health axis:
        # any healthy placement matches 'on'. To filter to API-
        # pushed rows specifically: LINK=PU.
        for p in pills:
            if p == "on" and not it.get("placement_missing") and (
                it.get("media_folder") or is_plex_upload
            ):
                return True
            if p == "off" and not it.get("media_folder") and not it.get("file_path") and not is_plex_upload:
                return True
            # v0.51.68 (complexity audit): exclude the terminal reasons (backup_only,
            # over_ceiling) like _LIB_AWAIT_SQL — this pl post-stat copy had NEITHER,
            # so both terminal states leaked into pl=await under the await+on/broken
            # multi-select (the post-stat path).
            if (p == "await" and not it.get("media_folder") and it.get("file_path")
                    and not is_lps and not is_plex_upload
                    and it.get("last_place_attempt_reason")
                        not in ("backup_only", "plex_rejected:over_ceiling")):
                return True
            if p == "broken" and it.get("placement_missing") and not is_lps:
                return True
        return False

    # v1.12.95: post-stat pagination triggers on either 'on' or
    # 'broken' in the pill set — `on` was leaking broken rows
    # because the SQL `lf.file_path IS NOT NULL` (or
    # `p.media_folder IS NOT NULL`) doesn't know about disk state.
    # _row_matches_dl / _row_matches_pl apply the strict
    # canonical_missing / placement_missing exclusion so the
    # filter result mirrors the row-pill display exactly.
    # v1.22.82: filter-only blocks + ONE shared pagination epilogue.
    # Pre-fix each post-stat block re-sliced the PREVIOUS block's page:
    # combining two axes (e.g. DL=ON + PL=BROKEN) made page 2 always
    # empty and collapsed `total` to a single page's count.
    _post_stat_filtered = False
    if dl_pills and ("broken" in dl_pills or "on" in dl_pills):
        items = [it for it in items if _row_matches_dl(it, dl_pills)]
        _post_stat_filtered = True
    if pl_pills and ("broken" in pl_pills or "on" in pl_pills):
        items = [it for it in items if _row_matches_pl(it, pl_pills)]
        _post_stat_filtered = True
    # v1.15.39: attn_pills mixed-with-broken — OR every selected
    # attn pill (including broken = canonical_missing). When this
    # path runs the SQL attn_branches was skipped so `items` is
    # the unbounded match-other-filters set; this OR-narrows to
    # rows matching at least one selected attn pill. Mirrors the
    # SQL semantics for each non-broken pill (see api.py:1269 and
    # below for the canonical predicate per value).
    if attn_needs_post_stat:
        def _row_matches_attn(it):
            for p in attn_pills:
                if p == "broken":
                    if it.get("canonical_missing"):
                        return True
                elif p == "fail":
                    # SQL: failure_kind NOT NULL + not acked (the
                    # row's failure_acked_at field is COALESCE
                    # over title + sfa per-section, so the single
                    # check covers both ack axes).
                    if (it.get("failure_kind")
                            and not it.get("failure_acked_at")):
                        return True
                elif p == "cookies":
                    # SQL (v1.15.38): cookies_expired, no ack.
                    if it.get("failure_kind") == "cookies_expired":
                        return True
                elif p == "update":
                    # SQL: actionable_update (decision='pending' AND
                    # src!='-' AND has-something AND URL-diff).
                    # Row already carries actionable_update flag.
                    if it.get("actionable_update"):
                        return True
                elif p == "mismatch":
                    if it.get("mismatch_state") == "pending":
                        return True
                elif p == "await":
                    # SQL: file_path NOT NULL AND media_folder NULL
                    # AND NOT lpsState. Same lps gate as the
                    # _row_matches_pl helper above.
                    # v1.18.16: also exclude plex_upload placements
                    # (collections) — `not media_folder` is true for
                    # empty-string but the row IS placed via API.
                    # v1.18.27: same plex_upload exclusion as the
                    # JS lpsState + _row_matches_pl is_lps.
                    is_plex_upload = (
                        it.get("placement_kind") == "plex_upload"
                    )
                    is_lps = (
                        it.get("file_path")
                        and not it.get("media_folder")
                        and it.get("plex_independent_theme") == 1
                        and not is_plex_upload
                    )
                    # v0.51.36 (the user): backup_only (terminal TB) is not AWAIT —
                    # mirror the JS awaitingApproval + _LIB_AWAIT_SQL exclusion.
                    # v0.51.68 (complexity audit): also exclude over_ceiling. This
                    # post-stat copy (fires on attn=await+broken multi-select) drifted
                    # from _LIB_AWAIT_SQL, which excludes BOTH terminal reasons since
                    # v1.24.46 — so an over-ceiling row re-appeared as AWAIT here and
                    # re-enqueued a doomed upload on click.
                    if (it.get("file_path")
                            and not it.get("media_folder")
                            and not is_lps
                            and not is_plex_upload
                            and it.get("last_place_attempt_reason")
                                not in ("backup_only", "plex_rejected:over_ceiling")):
                        return True
            return False

        items = [it for it in items if _row_matches_attn(it)]
        _post_stat_filtered = True
    if _post_stat_filtered:
        # v1.22.82: the single pagination pass (see above).
        total = len(items)
        items = items[offset:offset + per_page]
    # v1.23.70: diagnostic timing for the tab-switch-lag investigation (the user:
    # "switching between library tabs / collections sometimes feels slow"). Logs
    # a WARNING when this subquery-heavy browse query crosses the threshold, and
    # echoes query_ms in the response so it's visible PER-REQUEST in devtools'
    # Network tab during a real tab switch. Read-only instrumentation — once the
    # bottleneck is characterized (is it the query, or full-nav app.js re-parse?)
    # this comes back out. WAL is on, so this is NOT reader-vs-writer lock wait;
    # a slow value points at subquery cost or sync/enum CPU contention.
    _q_ms = round((_t.monotonic() - _t0) * 1000.0, 1)
    if _q_ms >= 750:
        log.warning(
            "slow /api/library query: %sms tab=%s fourk=%s section=%s status=%s "
            "rows=%d total=%d (subquery cost or sync/enum CPU contention?)",
            _q_ms, tab, fourk, section_id or "-", status, len(items), total)
    return {"total": total, "missing_count": missing_count,
            "page": page, "per_page": per_page,
            "tab": tab, "fourk": fourk, "items": items,
            "query_ms": _q_ms,
            "plex_enumerated": plex_enumerated,
            "plex_scan_stale": plex_scan_stale,
            "last_plex_enum_at": last_plex_enum_at,
            "last_sync_at": last_sync_at}


# v1.20.63 (class-9 hot-path): _annotate_canonical_state runs a
# per-row is_file() on every /api/library render. A swallowed OSError
# (flaky NFS, perm error on /data) silently paints the row *_missing=
# True even when the file is fine — a wrong UI badge with no log
# signal. First occurrence warns (operator sees it at boot); the rest
# drop to debug so a genuinely-flaky mount can't spam the log.
_CANON_FS_OSERROR_WARNED = False


def _warn_canon_fs(which: str, path, e) -> None:
    global _CANON_FS_OSERROR_WARNED
    msg = ("_annotate_canonical_state: %s is_file() OSError on %s "
           "(treating as missing): %s")
    if not _CANON_FS_OSERROR_WARNED:
        _CANON_FS_OSERROR_WARNED = True
        log.warning(msg, which, path, e)
    else:
        log.debug(msg, which, path, e)


def _annotate_canonical_state(items: list[dict], *, themes_dir: Path | None) -> list[dict]:
    """Add canonical_missing=True to each row whose lf.file_path points
    at a file that no longer exists under themes_dir. Best-effort —
    OSError on stat (permissions, dead mount) treats as missing.

    v1.12.81: also annotates placement_missing — placements row has a
    media_folder but theme.mp3 isn't actually there. Parallel concept
    to canonical_missing on the Plex-folder side; surfaces as PL=broken
    in the library row UI so the user can spot a placement that fell
    out of sync (Plex deleted it, file moved manually, etc.) without
    motif noticing yet.
    """
    if not themes_dir:
        for it in items:
            it["canonical_missing"] = False
            it["placement_missing"] = False
        return items
    for it in items:
        rel = it.get("file_path")
        if not rel:
            it["canonical_missing"] = False
        else:
            try:
                cpath = themes_dir / rel
                # v0.51.167: a 0-byte theme.mp3 is a corrupt/failed download
                # (downloader.py:589 removes + re-downloads one), functionally
                # missing. Mirror verify_canonical_health's zero-byte check so the
                # live red DL dot + dl_pills=broken filter agree with the stored
                # canonical_present flag (the two paths MUST match — CLAUDE.md).
                it["canonical_missing"] = (
                    not cpath.is_file() or cpath.stat().st_size == 0)
            except OSError as e:
                it["canonical_missing"] = True
                _warn_canon_fs("canonical", themes_dir / rel, e)
        media_folder = it.get("media_folder")
        if not media_folder:
            it["placement_missing"] = False
        else:
            try:
                it["placement_missing"] = not (Path(media_folder) / "theme.mp3").is_file()
            except OSError as e:
                it["placement_missing"] = True
                _warn_canon_fs("placement", Path(media_folder) / "theme.mp3", e)
    return items


def _library_not_in_plex(
    db: Path, *, tab: str, fourk: bool,
    q: str, page: int, per_page: int,
    sort: str = "title", sort_dir: str = "asc",
) -> dict:
    """Return ThemerrDB rows whose tmdb_id has no matching plex_items
    in the requested tab. Synthesizes plex-shaped fields so the frontend
    renderer treats them as just-another-row, with not_in_plex=1 driving
    the distinct visual treatment.

    v1.12.10: anime tab now mirrors the TV path. ThemerrDB doesn't
    distinguish anime from regular TV (it tracks the same TVDB/TMDB
    show records), so the TDB-only browse for anime IS the TDB-only
    browse for TV. The "exists in any Plex section" check at the
    bottom naturally excludes shows the user already owns under
    their anime section, so the user sees a curated "anime/TV TDB
    has but I don't" list. Pre-fix the anime tab early-returned
    empty, which made the v1.12.6 faded-T pill useless on /anime.

    v1.18.17: explicit collections branch. Pre-fix tab='collections'
    fell through to `else` → queried media_type='tv' → returned TV
    shows ThemerrDB has but Plex doesn't, regardless of the tab the
    user was viewing. the user's repro: Collections tab + TDB-only
    star showed "16bit Sensation", "2 Stupid Dogs", "4 Blocks" —
    none of which are collections. Now queries
    `t.media_type='collection'` AND `pi.media_type='collection'`,
    surfacing the ThemerrDB collections (from movie_collections/
    themoviedb/) the user doesn't yet have a Plex collection for.
    """
    if tab == "movies":
        media_type = "movie"
        plex_media_type = "movie"
    elif tab == "collections":
        media_type = "collection"
        plex_media_type = "collection"
    else:  # tv + anime
        media_type = "tv"
        plex_media_type = "show"
    # v1.10.55: drop the per-tab section-flag filter (is_anime/is_4k)
    # on the 'exists in Plex' check. Pre-1.10.55 a tab's not_in_plex
    # only counted plex_items in sections matching that tab's flags,
    # so an anime show registered as 'not in Plex' on the TV tab
    # even though the user has it in their anime section. Now we
    # check whether ANY managed plex_items row covers the title;
    # the media_type match stays since TMDB id namespaces are
    # disjoint per media_type (movie 999 ≠ show 999).
    params: list = [media_type, plex_media_type]
    q_where = ""
    if q:
        q_where = " AND (t.title LIKE ? OR t.imdb_id = ?)"
        params.extend([f"%{q}%", q])
    # v1.22.91: a guid match is NOT the only way a title can be "in
    # Plex". Plex collections carry no tmdb:// guid (guid_tmdb stays
    # NULL), so the v1.18.2 resolve links them to their TDB record via
    # plex_items.theme_id (title_norm match) — the same linkage the
    # main library rows, the worker's place skip, and the cloud-backup
    # walker all use. This check was guid-only, so every title-linked
    # Plex collection ALSO rendered as "(not in your Plex library)" in
    # the TDB-only list (the user's 28 Days/Addams repro: both had B/TB
    # themes staged against live Plex rks while listed as not-in-Plex).
    # Same fix covers guid-less legacy-agent movie/tv rows. The
    # theme_id clause needs no media_type predicate — the resolve only
    # links matching types, and any included-section row pointing at
    # this themes row means the title is in the library.
    base_where = f"""
        WHERE t.media_type = ?
          AND t.upstream_source != 'plex_orphan'
          AND NOT EXISTS (
              SELECT 1 FROM plex_items pi2
              INNER JOIN plex_sections ps2
                ON ps2.section_id = pi2.section_id AND ps2.included = 1
              WHERE pi2.guid_tmdb = t.tmdb_id
                AND pi2.media_type = ?
          )
          AND NOT EXISTS (
              SELECT 1 FROM plex_items pi3
              INNER JOIN plex_sections ps3
                ON ps3.section_id = pi3.section_id AND ps3.included = 1
              WHERE pi3.theme_id = t.id
          )
          {q_where}
    """
    sql_count = f"SELECT COUNT(*) FROM themes t {base_where}"
    order_expr = _LIBRARY_SORTS_NOT_IN_PLEX.get(
        sort, _LIBRARY_SORTS_NOT_IN_PLEX["title"],
    )
    direction = "DESC" if sort_dir == "desc" else "ASC"
    order_clause = f"ORDER BY {order_expr} {direction}, t.title COLLATE NOCASE ASC"
    sql_rows = f"""
        SELECT
            ('themerrdb-' || t.media_type || '-' || t.tmdb_id) AS rating_key,
            NULL AS section_id,
            (CASE t.media_type WHEN 'tv' THEN 'show' ELSE t.media_type END) AS plex_media_type,
            t.title AS plex_title,
            t.year, t.imdb_id AS guid_imdb, t.tmdb_id AS guid_tmdb,
            NULL AS folder_path,
            '' AS plex_edition_title,
            NULL AS plex_has_theme,
            NULL AS plex_local_theme,
            NULL AS plex_theme_verified_ok,
            NULL AS plex_independent_theme,
            NULL AS section_title,
            t.tmdb_id AS theme_tmdb, t.media_type AS theme_media_type,
            t.title AS theme_title, t.youtube_url, t.youtube_video_id,
            t.failure_kind, t.failure_message, t.failure_acked_at, t.upstream_source,
            t.tdb_dropped_at,
            lf.file_path, lf.source_video_id, lf.provenance, lf.source_kind,
            lf.mismatch_state,
            p.media_folder, p.placement_kind, p.provenance AS placement_provenance,
            (SELECT j.job_type FROM jobs j
             WHERE j.media_type = t.media_type AND j.tmdb_id = t.tmdb_id
               AND j.job_type IN ('download', 'place')
               AND j.status IN ('pending', 'running')
             ORDER BY CASE j.status WHEN 'running' THEN 0 ELSE 1 END,
                      j.id DESC
             LIMIT 1) AS job_in_flight,
            1 AS not_in_plex
        FROM themes t
        LEFT JOIN local_files lf
          ON lf.media_type = t.media_type AND lf.tmdb_id = t.tmdb_id
        LEFT JOIN placements p
          ON p.media_type = t.media_type AND p.tmdb_id = t.tmdb_id
        {base_where}
        {order_clause}
        LIMIT ? OFFSET ?
    """
    offset = (page - 1) * per_page
    with get_conn(db) as conn:
        total = conn.execute(sql_count, params).fetchone()[0]
        rows = conn.execute(sql_rows, params + [per_page, offset]).fetchall()
        last_plex_enum_at = conn.execute(
            """SELECT MAX(finished_at) FROM jobs
               WHERE job_type = 'plex_enum' AND status = 'success'"""
        ).fetchone()[0]
        last_sync_at = conn.execute(
            """SELECT MAX(finished_at) FROM sync_runs
               WHERE status = 'success'"""
        ).fetchone()[0]
    items = [dict(r) for r in rows]
    return {"total": total, "missing_count": 0,
            "page": page, "per_page": per_page,
            "tab": tab, "fourk": fourk, "items": items,
            "plex_enumerated": True,
            "plex_scan_stale": False,
            "last_plex_enum_at": last_plex_enum_at,
            "last_sync_at": last_sync_at}


# v1.13.40: REPROBE PLEX THEMES worker — non-destructive prefix-byte
# probe. Earlier versions (v1.13.38–.39) renamed each sidecar to
# theme.mp3.motif-probing, asked Plex to refresh, HEAD-probed, then
# restored. That worked but was slow (Plex's metadata cache lag
# dominated, ~10s/row) and carried a small but real catastrophic
# failure mode (mid-loop crash → sidecar stranded under the .motif-
# probing suffix). The replacement reads only what Plex already
# serves: a 2 KB Range-GET against /library/metadata/{rk}/theme,
# compared byte-for-byte to the same prefix of motif's local
# sidecar at local_files.file_path. Match → Plex serves the
# sidecar (plex_independent_theme=0). Mismatch → Plex serves an
# independent theme (=1). No file touches, no Plex refresh wait,
# parallelizable across worker threads.
PROBE_PREFIX_BYTES = 2048
PROBE_MAX_WORKERS = 6

# v1.14.29: bulk TDB-URL probe runs yt-dlp --simulate per row, which
# is far heavier than REPROBE's HTTP Range-GET against Plex. Keep the
# pool small so YouTube doesn't rate-limit motif's IP. 24h cooldown
# (BULK_PROBE_COOLDOWN_HOURS) prevents back-to-back full sweeps from
# DOSing the same URLs.
# v1.15.12: dropped 3 → 2. the user's v1.15.11 REPROBE FAILURES run
# averaged 2.9 probes/s with 3 workers — over YouTube's unauth
# throughput threshold. The classifier fix maps the resulting
# rate-limit error to NETWORK_ERROR (no failure_kind write), but
# the better fix is to not trigger the throttle.
# v1.15.14: dropped 2 → 1. The v1.15.12 run with 2 workers STILL
# triggered the throttle — the user's docker logs showed thousands
# of "session has been rate-limited by YouTube" responses, with
# 1534 of 2127 probes returning "other" (transient). 1 worker
# averages ~1 probe/s which should sit under YouTube's threshold
# even on cookied requests. Combined with the early-bail logic
# (BULK_PROBE_RATE_LIMIT_BAIL_THRESHOLD below), wasted-probe
# time is bounded even if the throttle does still fire.
BULK_PROBE_MAX_WORKERS = 1
BULK_PROBE_COOLDOWN_HOURS = 24
# v1.15.14: if N consecutive probes return a transient kind
# (NETWORK_ERROR / UNKNOWN / COOKIES_EXPIRED), bail the run early.
# YouTube's rate-limit message says "...up to an hour" — once
# we're throttled, every subsequent probe in this session is
# wasted. The threshold is generous enough to not bail on a brief
# network blip (a handful of consecutive transients is normal in a
# 2000-row sweep) but tight enough to catch a sustained throttle
# within ~15s of it kicking in.
BULK_PROBE_RATE_LIMIT_BAIL_THRESHOLD = 15


def _bulk_probe_tdb_run(
    db_path: Path, settings,
    *,
    scope_items: list[tuple[str, int]] | None = None,
    scope_failures_only: bool = False,
) -> None:
    """v1.14.29: bulk-probe every row's TDB URL.

    Mirrors `_reprobe_plex_themes_run`'s shape:
      • op_progress lifecycle (start / update / finish)
      • single OP_ID gate enforced by the route handler
      • cancellable mid-run via op_progress.is_cancelled
      • thread-pool parallelism (BULK_PROBE_MAX_WORKERS)
      • batched verdict writes inside one transaction per flush

    Per the user's design (v1.14.28 § design decisions):
      • cookies_expired = indeterminate (don't change row state)
      • dead URLs (needs_manual_override) get failure_kind written
        preemptively so the row turns red BEFORE LET PLEX SERVE
      • last_probed_at always stamped (drives the 24h cooldown SQL)
      • 24h cooldown — rows probed within the window are skipped
        so back-to-back sweeps don't DOS YouTube

    v1.14.33: targets the TDB URL only — NOT the override.
    Same fix as the single-row /probe-tdb endpoint. The bulk
    probe answers "which TDB URLs are dead?" so the operator can
    fix or ignore them; an override URL's freshness is the
    user's concern, not motif's bulk-sweep job.

    v1.15.1: optional `scope_items` narrows the probe to an
    explicit list of (media_type, tmdb_id) pairs. The settings
    PROBE TDB URLS button still calls global (None); the LET
    PLEX SERVE pre-flight passes the user's selection so the
    probe stays scoped to "the rows about to be LPS'd" instead
    of walking the entire library and burning the 24h cooldown
    on rows the user doesn't intend to touch right now.
    the user: "when doing a bulk let server it starts a probe
    themerdb which probes every themerrdb url not just the url
    of the bulk let plex serve action."

    v1.15.10: optional `scope_failures_only=True` swaps the
    cooldown filter for `failure_kind IS NOT NULL`. Powers the
    new // REPROBE FAILURES button so an operator can recover
    rows from a previous bad-config probe (e.g. cookies missing,
    rate-limit hammered, network blip) WITHOUT waiting out the
    24h cooldown. the user: "I'm seeing currently 1842 fails …
    from a previous probe gone bad … reprobing manually from
    the info card brings them back alive but I have no way to
    bulk reprobe from settings because of the 24hr cooldown".
    The cooldown still applies to the unscoped global path —
    REPROBE FAILURES is for explicit recovery only.
    """
    from concurrent.futures import ThreadPoolExecutor, as_completed
    from ..core import progress as op_progress
    from ..core.downloader import probe_youtube_url, FailureKind
    OP_ID = "bulk-probe-tdb"
    if scope_failures_only:
        scope_label = "(failures only)"
    elif scope_items:
        scope_label = f"({len(scope_items)} selected)"
    else:
        scope_label = "(all rows)"
    def _cancel() -> bool:
        return op_progress.is_cancelled(db_path, OP_ID)

    cookies = settings.cookies_file if settings.cookies_file else None

    n_alive = 0
    n_alive_cleared = 0  # v1.14.51: subset of n_alive whose stale failure was cleared
    n_dead = 0
    n_indet = 0
    n_other = 0  # transient (network/unknown)
    error_count = 0
    try:
        # v1.22.82: start INSIDE the try — a failed start (e.g.
        # database-is-locked past the busy timeout) used to kill
        # the runner thread with the try_acquire'd 'pending' row
        # stuck forever: every re-run 409'd and op_progress_running
        # pinned anyMutatingOpActive until container restart.
        # Mirror of _cloud_themes_backup_run's shape.
        op_progress.start_progress(
            db_path, op_id=OP_ID, kind="bulk_probe_tdb",
            stage="probe", stage_label=f"Probing TDB URLs {scope_label}",
            stage_total=0, processed_est=0,
        )
        # v1.14.33: pull every theme row that has a TDB URL AND
        # hasn't been probed in the last BULK_PROBE_COOLDOWN_HOURS
        # hours. Pre-fix the SQL did COALESCE(override_url, tdb_url)
        # — wrong: we want to probe the TDB URL specifically (the
        # safety-net case is "user has override + dead TDB URL").
        # plex_orphan rows with no TDB URL fall out via the
        # NULLIF(t.youtube_url, '') IS NOT NULL filter.
        # v1.15.1: when scope_items is provided, narrow the SELECT
        # via an additional `(t.media_type, t.tmdb_id) IN (...)`
        # clause. The 24h cooldown filter is preserved either way
        # so a re-run within the window still no-ops correctly.
        with get_conn(db_path) as conn:
            scope_clause = ""
            scope_params: list = []
            if scope_items:
                # Build a placeholder pair list for the IN-tuples
                # filter. Limit to ~500 to stay inside SQLite's
                # parameter cap (999 default ≈ 499 pairs).
                # Selections larger than that fall through to a
                # global probe — uncommon for LPS bulk actions
                # which target a small visible subset.
                if len(scope_items) <= 499:
                    placeholders = ",".join(
                        "(?, ?)" for _ in scope_items
                    )
                    scope_clause = (
                        f"   AND (t.media_type, t.tmdb_id) IN ({placeholders})"
                    )
                    for mt, tid in scope_items:
                        scope_params.extend([mt, tid])
                else:
                    # v1.22.68: WARNING (was info) — the degradation is
                    # consequential (whole-library probe instead of the
                    # selection) and the cooldown-bypass gate below now
                    # keys on scope_clause so this path keeps the 24h
                    # cooldown instead of hammering YouTube.
                    log.warning(
                        "BULK PROBE TDB: %d scope items exceeds the 499 "
                        "param cap; degrading to a GLOBAL probe with the "
                        "24h cooldown applied",
                        len(scope_items),
                    )
            # v1.15.10: scope_failures_only swaps the cooldown filter
            # for `failure_kind IS NOT NULL`. The two filters are
            # mutually exclusive — REPROBE FAILURES is explicitly for
            # rechecking known-bad rows that the cooldown would
            # otherwise block (typical case: a previous probe ran with
            # a bad config — missing cookies, rate-limit hammered —
            # and red-pilled rows that are actually fine).
            # v1.15.15: align the failures-only filter with the
            # canonical FAIL chip predicate. Pre-fix the filter was
            # just `failure_kind IS NOT NULL` per theme, which
            # included rows the FAIL chip excluded.
            # v1.15.33: BROADEN back. the user: "make it so reprobe
            # failure reprobes all red pill TDB not just unack
            # failure rows." The TDB pill goes red on
            # `failure_kind IS NOT NULL` regardless of ack state;
            # the v1.15.15 narrowing matched the FAIL CHIP count
            # (which excluded acked rows) but the user's mental
            # model is the per-row TDB pill (which doesn't). An
            # acked failure may be stale — re-probing might find
            # the URL is alive again, which clears the failure
            # naturally. Drop the title-ack + sfa-ack predicates;
            # keep the visibility filter (managed Plex section
            # required) so we don't burn yt-dlp calls on themes
            # for items no longer in any tracked library.
            if scope_failures_only:
                # v1.22.91: accept the theme_id linkage too — guid-less
                # rows (collections, legacy-agent items) are
                # title-linked via plex_items.theme_id, and their
                # failures are just as re-probeable.
                row_filter = (
                    "AND t.failure_kind IS NOT NULL "
                    "AND EXISTS ("
                    "  SELECT 1 FROM plex_items pi "
                    "    JOIN plex_sections ps "
                    "      ON ps.section_id = pi.section_id "
                    "     AND ps.included = 1 "
                    "   WHERE (pi.theme_id = t.id "
                    "          OR (pi.guid_tmdb = t.tmdb_id "
                    "              AND pi.media_type = ("
                    "       CASE t.media_type WHEN 'tv' THEN 'show' ELSE t.media_type END))) "
                    ")"
                )
                activity_note = "(all red-pill failures, cooldown bypassed)"
            elif scope_clause:
                # v1.15.20: explicit user selection bypasses the
                # cooldown. Pre-fix the LET PLEX SERVE pre-flight
                # probe (which posts the user's selection as
                # scope_items) silently no-op'd whenever the
                # selected rows had been probed in the last 24h —
                # the cooldown filter intersected with the IN-
                # tuples filter to produce total=0, the early-
                # return below fired, and the operator never saw
                # any progress in LIVE OPS. the user: "attempted a
                # bulk let plex server and it stated it would
                # probe 2 urls but ... never saw any probe or
                # change in the status bar". The cooldown is
                # designed to prevent back-to-back full sweeps;
                # an explicit user-selected probe shouldn't
                # honor it (the user has made a deliberate
                # choice to re-probe).
                # v1.22.68 (audit round 2): condition is scope_CLAUSE,
                # not scope_items — a >499 selection falls through to a
                # GLOBAL probe (scope_clause stays ''), and pre-fix this
                # branch still bypassed the cooldown for it: select-all
                # + PROBE silently hammered the ENTIRE library
                # back-to-back (the "probe gone bad → 1842 red rows"
                # incident class). The bypass now applies only when the
                # selection was actually applied to the SQL.
                row_filter = ""
                activity_note = "(selected rows, cooldown bypassed)"
            elif scope_items:
                # v1.22.68: the degraded >499 path — global probe WITH
                # the cooldown honored, loudly labeled so the operator
                # knows the selection didn't narrow anything.
                row_filter = (
                    "AND (t.last_probed_at IS NULL"
                    "     OR julianday(t.last_probed_at)"
                    f"        < julianday('now', '-{BULK_PROBE_COOLDOWN_HOURS} hours'))"
                )
                activity_note = (
                    f"(selection of {len(scope_items)} exceeds the 499 "
                    "scope cap — degraded to a GLOBAL probe, 24h "
                    "cooldown applied)"
                )
            else:
                row_filter = (
                    "AND (t.last_probed_at IS NULL"
                    "     OR julianday(t.last_probed_at)"
                    f"        < julianday('now', '-{BULK_PROBE_COOLDOWN_HOURS} hours'))"
                )
                activity_note = "(24h cooldown applied)"
            rows = conn.execute(
                f"""
                SELECT t.media_type AS media_type,
                       t.tmdb_id AS tmdb_id,
                       t.youtube_url AS target_url,
                       t.last_probed_at AS last_probed_at
                  FROM themes t
                 WHERE NULLIF(t.youtube_url, '') IS NOT NULL
                   {row_filter}
                {scope_clause}
                 ORDER BY t.last_probed_at IS NULL DESC,
                          t.last_probed_at ASC
                """,
                scope_params,
            ).fetchall()
        total = len(rows)
        op_progress.update_progress(
            db_path, OP_ID,
            stage_total=total,
            processed_est=total,
            activity=f"Found {total} URL(s) to probe {activity_note}",
        )
        if total == 0:
            # v1.15.20: log an INFO event on the empty early-return
            # so the operator sees the result in /queue events +
            # docker logs. Pre-fix the function returned silently
            # — no log_event, no follow-up activity update — so a
            # user who clicked PROBE / LET PLEX SERVE pre-flight
            # had no signal that the run completed (it appeared
            # for ~50ms in LIVE OPS then disappeared, looking
            # like nothing happened).
            log_event(
                db_path, level="INFO", component="bulk-probe",
                message=(
                    f"BULK PROBE TDB done: 0/0 probed {scope_label} "
                    f"{activity_note} — nothing to do"
                ),
            )
            op_progress.finish_progress(db_path, OP_ID, status="done")
            return

        def _probe_one(idx_row):
            _, r = idx_row
            mt = r["media_type"]
            tid = r["tmdb_id"]
            url = r["target_url"]
            # v1.15.11: snapshot cookies to a per-call tempfile so
            # the 3 concurrent probe workers don't race on yt-dlp's
            # writeback against a shared /config/cookies.txt. Pre-fix
            # repro (the user v1.15.10): "ERROR: '/config/cookies.txt'
            # does not look like a Netscape format cookies file"
            # appeared intermittently in the bulk-probe docker logs
            # — process A truncates the file to write back updated
            # session cookies while processes B/C try to read it,
            # see a partial file, reject it as malformed. Affected
            # rows fell into the indeterminate bucket and didn't
            # get their failure_kind cleared even when the URL was
            # alive. Per-call snapshot eliminates the shared state:
            # each yt-dlp instance gets its own private file, the
            # writeback succeeds locally, the snapshot gets unlinked.
            # File is ~5 KB on tmpfs so the copy + unlink is sub-ms.
            per_call_cookies = None
            snap_owned = False
            if cookies:
                try:
                    import os as _os
                    import shutil as _shutil
                    import tempfile as _tempfile
                    fd, snap_path = _tempfile.mkstemp(
                        prefix="motif-probe-cookies-", suffix=".txt"
                    )
                    _os.close(fd)
                    _shutil.copy2(str(cookies), snap_path)
                    per_call_cookies = Path(snap_path)
                    snap_owned = True
                except Exception as e:
                    # v1.15.34: log + skip the row instead of
                    # falling back to the shared cookies file. The
                    # pre-v1.15.34 fallback re-introduced exactly
                    # the v1.15.11 race condition (multiple workers
                    # reading the same cookies file concurrently)
                    # silently — the operator saw "probe error"
                    # results that were actually thread-safety
                    # artifacts, not real probe failures. Bail
                    # this row's probe with a clear error string
                    # the caller surfaces in op_progress.
                    log.warning(
                        "BULK PROBE TDB: cookies snapshot failed "
                        "for %s/%s — skipping (no shared-file "
                        "fallback to avoid v1.15.11 race): %s",
                        mt, tid, e,
                    )
                    return (
                        mt, tid, url, None,
                        f"cookies snapshot failed: {e}",
                    )
            try:
                result = probe_youtube_url(url, cookies_file=per_call_cookies)
            except Exception as e:
                return mt, tid, url, None, f"probe error: {e}"
            finally:
                if snap_owned and per_call_cookies is not None:
                    try:
                        per_call_cookies.unlink()
                    except Exception as e:
                        # v1.15.34: log unlink failures so /tmp
                        # snapshot leaks don't accumulate silently
                        # over weeks of operation. Was previously
                        # bare `pass` — disk pressure built up
                        # invisibly until /tmp filled.
                        log.warning(
                            "BULK PROBE TDB: cookies snapshot "
                            "unlink failed at %s: %s",
                            per_call_cookies, e,
                        )
            return mt, tid, url, result, None

        # Batched DB writes — one transaction per flush.
        BATCH_SIZE = 50
        pending_stamps: list[tuple] = []  # (now_iso, mt, tid)
        pending_dead: list[tuple] = []    # (kind_value, message, now_iso, mt, tid)
        # v1.14.51: alive batch — mirrors the v1.14.49 single-row
        # /probe-tdb alive-clear. Pre-fix the bulk path only stamped
        # last_probed_at on alive results, so stale failure_kind
        # lingered on rows whose URL had since been resurrected
        # (network blip / privated-then-unprivated). Operators run
        # bulk-probe specifically to RECONCILE the library — having
        # the bulk path do less reconciliation than the single-row
        # path is a mirror-principle drift (CLAUDE.md class P).
        pending_alive: list[tuple] = []   # (mt, tid) — bound to UPDATE + DELETE pair

        def _flush_batch():
            nonlocal pending_stamps, pending_dead, pending_alive
            nonlocal n_alive_cleared
            if not pending_stamps and not pending_dead and not pending_alive:
                return
            with get_conn(db_path) as conn:
                with transaction(conn):
                    if pending_stamps:
                        conn.executemany(
                            "UPDATE themes SET last_probed_at = ? "
                            "WHERE media_type = ? AND tmdb_id = ?",
                            pending_stamps,
                        )
                    if pending_dead:
                        # Same write the single-row /probe-tdb endpoint
                        # uses for needs_manual_override results.
                        conn.executemany(
                            "UPDATE themes SET failure_kind = ?, "
                            "                  failure_message = ?, "
                            "                  failure_at = ?, "
                            "                  failure_acked_at = NULL "
                            "WHERE media_type = ? AND tmdb_id = ?",
                            pending_dead,
                        )
                    if pending_alive:
                        # v1.14.51: mirror the v1.14.49 single-row
                        # alive-clear. Two writes per affected row,
                        # gated on `failure_kind IS NOT NULL` so
                        # rows that were already clean stay no-ops
                        # (rowcount tracks the actual transitions
                        # for the operator-visible counter).
                        # Worker.py:1217-1235 establishes the
                        # title-global pattern (sfa rows are "current
                        # acks for current failure_kind" — when the
                        # failure clears, sfa orphans must be deleted
                        # or the FAIL pill silently excludes affected
                        # sections; v1.13.81 audit P0 #1).
                        for (mt, tid) in pending_alive:
                            cur = conn.execute(
                                """UPDATE themes
                                      SET failure_kind = NULL,
                                          failure_message = NULL,
                                          failure_at = NULL,
                                          failure_acked_at = NULL
                                    WHERE media_type = ?
                                      AND tmdb_id = ?
                                      AND failure_kind IS NOT NULL""",
                                (mt, tid),
                            )
                            if cur.rowcount > 0:
                                n_alive_cleared += 1
                                conn.execute(
                                    """DELETE FROM section_failure_acks
                                        WHERE media_type = ?
                                          AND tmdb_id = ?""",
                                    (mt, tid),
                                )
            pending_stamps = []
            pending_dead = []
            pending_alive = []

        # v1.15.14: track consecutive transient results (errors,
        # network failures, cookies-expired). When the count exceeds
        # BULK_PROBE_RATE_LIMIT_BAIL_THRESHOLD, bail the run early —
        # the most likely cause is YouTube rate-limiting the IP and
        # every subsequent probe in this session is wasted (the
        # throttle persists "up to an hour" per yt-dlp's message).
        consecutive_transient = 0
        rate_limit_bail = False
        cancelled_early = False
        # v1.15.23: post-flush activity helper. Pre-fix the cancel
        # path called _flush_batch but never posted a follow-up
        # activity update — the LIVE OPS card kept showing the
        # last in-loop activity message (e.g. "10/447 probed —
        # alive=10 (cleared=0)") even after the flush had updated
        # the DB to set n_alive_cleared=10. the user: "wouldn't
        # cleared be also 10 if i was doing a reprobe of failed
        # so the 10 alive were most likely also failed before?"
        # The natural-end path had the same gap. The helper closes
        # over the local counters so each call reads the current
        # post-flush state.
        def _post_terminal_activity():
            prefix = ""
            suffix = ""
            if cancelled_early:
                prefix = f"Cancelled at {done}/{total} — "
            elif rate_limit_bail:
                prefix = f"Bailed at {done}/{total} — "
                suffix = " — likely rate-limited; wait ~1h before re-running"
            msg = (
                f"{prefix}"
                f"alive={n_alive} (cleared={n_alive_cleared}), "
                f"dead={n_dead}, indeterminate={n_indet}, "
                f"other={n_other}{suffix}"
            )
            try:
                op_progress.update_progress(
                    db_path, OP_ID,
                    stage_current=done, processed_total=done,
                    error_count=error_count,
                    activity=msg,
                )
            except Exception as e:
                log.warning(
                    "BULK PROBE TDB post-terminal activity failed: %s", e)
        with ThreadPoolExecutor(
            max_workers=BULK_PROBE_MAX_WORKERS,
        ) as pool:
            futures = {
                pool.submit(_probe_one, (i, r)): i
                for i, r in enumerate(rows)
            }
            done = 0
            for fut in as_completed(futures):
                if _cancel():
                    cancelled_early = True
                    pool.shutdown(wait=False, cancel_futures=True)
                    try:
                        _flush_batch()
                    except Exception as e:
                        log.warning(
                            "BULK PROBE TDB flush on cancel failed: %s", e)
                    _post_terminal_activity()
                    op_progress.finish_progress(
                        db_path, OP_ID, status="cancelled")
                    return
                mt, tid, url, result, err = fut.result()
                done += 1
                stamp = now_iso()
                pending_stamps.append((stamp, mt, tid))
                # v1.15.14: classify result for the consecutive-
                # transient counter. Definitive verdicts (alive,
                # dead) reset the counter; transient verdicts
                # (errors, network, cookies-expired) increment it.
                is_transient_result = False
                if err is not None:
                    error_count += 1
                    n_other += 1
                    is_transient_result = True
                    log_event(
                        db_path, level="WARNING", component="bulk-probe",
                        message=f"BULK PROBE error {mt}/{tid}: {err}",
                        detail={"media_type": mt, "tmdb_id": tid,
                                "url": url, "reason": err},
                    )
                elif result is None:
                    n_alive += 1
                    # v1.14.51: queue the clear write — _flush_batch
                    # bumps n_alive_cleared on the rowcount transition.
                    pending_alive.append((mt, tid))
                elif result.needs_manual_override:
                    n_dead += 1
                    pending_dead.append(
                        (result.value, f"probe: {result.human}",
                         stamp, mt, tid),
                    )
                elif result == FailureKind.COOKIES_EXPIRED:
                    n_indet += 1
                    is_transient_result = True
                else:
                    # network_error / unknown — transient, don't
                    # change row state.
                    n_other += 1
                    is_transient_result = True
                if is_transient_result:
                    consecutive_transient += 1
                else:
                    consecutive_transient = 0
                if (len(pending_stamps) + len(pending_dead)
                        + len(pending_alive)) >= BATCH_SIZE:
                    _flush_batch()
                # v1.15.14: bail early if we've hit the threshold.
                # Most-likely cause is YouTube rate-limiting; either
                # way, continuing wastes time. Surface the bail in the
                # activity log so the operator sees it in LIVE OPS
                # without checking docker logs.
                if consecutive_transient >= BULK_PROBE_RATE_LIMIT_BAIL_THRESHOLD:
                    rate_limit_bail = True
                    pool.shutdown(wait=False, cancel_futures=True)
                    log_event(
                        db_path, level="WARNING", component="bulk-probe",
                        message=(
                            f"BULK PROBE TDB bailing at {done}/{total} — "
                            f"{consecutive_transient} consecutive transient "
                            f"results (likely YouTube rate-limit; throttle "
                            f"persists up to an hour, retry then)"
                        ),
                    )
                    op_progress.update_progress(
                        db_path, OP_ID,
                        activity=(
                            f"Bailed at {done}/{total} — likely rate-limited "
                            f"by YouTube. Wait ~1h before re-running."
                        ),
                    )
                    break
                if done % 10 == 0 or done == total:
                    op_progress.update_progress(
                        db_path, OP_ID,
                        stage_current=done, processed_total=done,
                        error_count=error_count,
                        activity=(
                            f"{done}/{total} probed — alive={n_alive}"
                            f" (cleared={n_alive_cleared}), "
                            f"dead={n_dead}, indeterminate={n_indet}, "
                            f"other={n_other}"
                        ),
                    )
            _flush_batch()
            # v1.15.23: post-flush activity update so the LIVE OPS
            # card reflects the actual cleared count (rather than
            # the last in-loop snapshot from before the final
            # _flush_batch wrote n_alive_cleared). Covers both
            # natural completion and the bail break-out (which
            # falls through to this point). The helper handles
            # cancel/bail/natural prefixes via the closure flags.
            _post_terminal_activity()

        # v1.15.14: include rate-limit bail status in the summary so
        # the LIVE OPS LAST OPS card + the events log both reflect
        # WHY the run finished early. Status stays "done" (the run
        # completed gracefully) — partial work + a clear next-step
        # is more useful than a "failed" status that suggests motif
        # crashed.
        # v1.21.25: uniform done_summary (see _doneHeadline in ops.js).
        op_progress.set_detail_field(
            db_path, OP_ID, "done_summary",
            [
                {"l": "probed", "v": total},
                {"l": "alive", "v": n_alive},
                {"l": "dead", "v": n_dead},
            ],
        )
        op_progress.finish_progress(db_path, OP_ID, status="done")
        bail_suffix = (
            " — bailed early on suspected YouTube rate-limit, "
            "retry in ~1h"
            if rate_limit_bail else ""
        )
        _bulk_probe_summary = (
            f"BULK PROBE TDB done: {done}/{total} probed, alive={n_alive}"
            f" (cleared={n_alive_cleared}), "
            f"dead={n_dead}, indeterminate={n_indet}, "
            f"other={n_other}, errors={error_count}{bail_suffix}"
        )
        log_event(
            db_path, level="INFO", component="bulk-probe",
            message=_bulk_probe_summary,
        )
        # v1.17.0: bulk_action_completed notification.
        # v1.17.1 (M4): gate on done > 0 so an empty-target sweep
        # (selection cleared between click + worker pickup, or
        # every row dropped at preflight) doesn't ping users with
        # "0 targets processed" noise.
        if done > 0:
            try:
                from ..core import notify as _notify
                _notify.dispatch(
                    db_path, settings.cfg.notifications,
                    event_kind="bulk_action_completed",
                    # v1.17.19: ✅ emoji prefix + drop "motif:".
                    title=f"✅ Bulk PROBE TDB done — {done}/{total}",
                    # v1.19.92: notification body drops the "BULK PROBE
                    # TDB done: {done}/{total} probed" headline (it
                    # restated the title verbatim) and keeps only the
                    # breakdown. The log_event above still records the
                    # full verbose summary for the events log.
                    body=(
                        f"alive={n_alive} (cleared={n_alive_cleared}), "
                        f"dead={n_dead}, indeterminate={n_indet}, "
                        f"other={n_other}, errors={error_count}"
                        f"{bail_suffix}"
                    ),
                )
            except Exception as e:
                # v1.17.1 (class 9): log breadcrumb on swallow.
                log.debug("notify dispatch (bulk-probe) suppressed: %s", e)
    except Exception as e:
        log.exception("BULK PROBE TDB failed")
        op_progress.finish_progress(
            db_path, OP_ID, status="failed", error_message=str(e))


def _cloud_themes_backup_run(
    db_path: Path, settings,
    *,
    rks_scope: list[str] | None,
    only_anime: bool,
    actor: str,
    allow_existing_local: bool = False,
    force: bool = False,
) -> None:
    """v1.19.45: background worker for the cloud-themes-backup
    endpoint. Walks plex_items.has_theme=1 P-rows, classifies each
    via Plex's /themes endpoint, downloads C1 hits, INSERTs into
    local_files with the v1.19.42 writer contract.

    Pre-fix this work ran INLINE in an async-def endpoint that
    contained synchronous Plex calls + sleeps + downloads. The
    async-def-with-sync-work pattern blocked the FastAPI event
    loop for the full duration (13+ min for a single-row scope
    pre-v1.19.45 push-down filter; 25+ min for a full catalog).
    the user's repro: clicked BACKUP THIS THEME → "Failed to fetch"
    + entire UI locked up. v1.19.45 moves to the canonical
    acquire-then-spawn-thread pattern bulk_lps / bulk_probe_tdb
    use.

    Three stages tracked via op_progress:
      1. walk — call /themes per candidate row, classify C1
      2. download — fetch bytes + INSERT local_files per target
      3. finish — final summary log_event

    Cancellable via op_progress.is_cancelled. The walker passes
    a cancel_check callback so it breaks at batch boundaries.
    """
    from ..core import progress as op_progress
    from ..core.plex import PlexClient, PlexConfig
    from ..core.cloud_theme_backup import (
        identify_c1_rows, backup_cloud_theme, unmint_stale_orphans,
    )
    OP_ID = "cloud-themes-backup"

    def _cancel() -> bool:
        return op_progress.is_cancelled(db_path, OP_ID)

    themes_dir = Path(settings.themes_dir)
    cfg = PlexConfig(
        url=settings.plex_url, token=settings.plex_token,
        movie_section=settings.plex_movie_section,
        tv_section=settings.plex_tv_section, enabled=True,
    )
    downloaded: list[dict] = []
    errors: list[dict] = []
    # v1.20.18: force captures that turn out byte-identical to the
    # row's existing canonical are skipped (no swap) — tracked
    # separately so they neither inflate the "backed up" count nor
    # register as errors.
    skipped_identical: list[dict] = []
    try:
        op_progress.start_progress(
            db_path, op_id=OP_ID, kind="cloud_themes_backup",
            stage="walk",
            stage_label=(
                f"Walking Plex /themes "
                f"({'all rows' if not rks_scope else f'{len(rks_scope)} row(s)'})"
            ),
            stage_total=0, processed_est=0,
        )
        with PlexClient(
            cfg, plus_mode=settings.plus_equiv_mode,
        ) as plex, get_conn(db_path) as conn:
            # v0.50.45: last walk processed count, carried into the download
            # stage's processed_total so the op-wide counter (+ RUN INSIGHT avg/s)
            # stays monotonic instead of resetting walk-count→0 at the boundary.
            walked_count = [0]

            def _on_walk_progress(evt: dict) -> None:
                phase = evt.get("phase")
                if phase == "start":
                    total = evt.get("total", 0)
                    op_progress.update_progress(
                        db_path, OP_ID,
                        stage_total=total,
                        processed_est=total,
                        activity=(
                            f"Walking {total} candidate row(s)"
                        ),
                    )
                elif phase == "batch":
                    processed = evt.get("processed", 0)
                    walked_count[0] = processed
                    c1 = evt.get("c1_count", 0)
                    op_progress.update_progress(
                        db_path, OP_ID,
                        stage_current=processed,
                        processed_total=processed,
                        activity=(
                            f"Walked {processed}/{evt.get('total', 0)} "
                            f"({c1} C1 hit(s) so far)"
                        ),
                    )

            # v1.19.79 (Opus-4.8 audit MED): activate the resumable
            # cursor ONLY for a true full-catalog sweep. Scoped runs
            # (single-row BACKUP THIS THEME, bulk selection, anime-only,
            # or the allow_existing_local "swap to Plex backup" variant)
            # must NOT consume the global cursor — they're not a full
            # walk and would leave a stale resume point. The full sweep
            # is the multi-minute path where a cancel/crash mid-walk
            # benefits from picking up where it left off.
            full_sweep = (
                rks_scope is None and not only_anime
                and not allow_existing_local and not force
            )
            targets = identify_c1_rows(
                conn, plex, only_anime=only_anime,
                use_cursor=full_sweep,
                rks_scope=rks_scope,
                on_progress=_on_walk_progress,
                cancel_check=_cancel,
                allow_existing_local=allow_existing_local,
                force=force,
            )
            if _cancel():
                # v0.51.16 (audit #26): the force walk minted plex_orphan
                # themes rows + theme_id stamps for its targets; nothing
                # downloaded yet, so unmint them or the rows stay linked-
                # but-empty (skipped by every theme_id-IS-NULL resolve).
                unmint_stale_orphans(conn, targets)
                op_progress.finish_progress(
                    db_path, OP_ID, status="cancelled",
                )
                log_event(
                    db_path, level="INFO", component="api",
                    message=(
                        "CLOUD THEMES BACKUP cancelled during walk"
                    ),
                )
                return
            # Stage 2: download.
            op_progress.update_progress(
                db_path, OP_ID,
                stage="download",
                stage_label=(
                    f"Downloading {len(targets)} cloud theme(s)"
                ),
                stage_current=0,
                stage_total=len(targets),
                # v0.50.45: carry the walk count forward (was a hard 0, which
                # jumped the op-wide counter backward walk-count→0 at the
                # walk→download boundary). stage_current stays per-stage.
                processed_total=walked_count[0],
                processed_est=walked_count[0] + len(targets),
                activity=(
                    f"Walk complete — {len(targets)} C1 target(s) "
                    f"to download"
                ),
            )
            log.info(
                "cloud_themes_backup: walk found %d C1 target(s) — "
                "starting download stage",
                len(targets),
            )
            for i, target in enumerate(targets, start=1):
                if _cancel():
                    log.info(
                        "cloud_themes_backup: cancelled at "
                        "target %d/%d (%s)",
                        i, len(targets), target.get("title", ""),
                    )
                    break
                result = backup_cloud_theme(
                    conn, target, themes_dir, plex,
                )
                if result.get("skipped_identical"):
                    # v1.20.18: Plex was serving bytes identical to the
                    # row's existing backup — nothing to swap. Not a
                    # download, not an error.
                    skipped_identical.append({
                        "rk": target["rating_key"],
                        "title": target["title"],
                    })
                    op_progress.update_progress(
                        db_path, OP_ID,
                        stage_current=i,
                        processed_total=walked_count[0] + i,
                        activity=(
                            f"No swap needed: {target['title']!r} "
                            f"(identical to existing backup)"
                        ),
                    )
                elif result["ok"]:
                    downloaded.append({
                        "rk": target["rating_key"],
                        "title": target["title"],
                        "bytes": result["bytes_written"],
                        # v0.51.86: carry whether this download REPLACED a prior
                        # backup vs was a first capture (for the outcome message).
                        "replaced_prior": bool(result.get("replaced_prior")),
                    })
                    _record_audit(
                        conn, actor=actor,
                        action="cloud_theme_backup",
                        media_type=target["media_type"],
                        tmdb_id=int(target["guid_tmdb"]),
                        section_id=target["section_id"],
                        details={
                            "rk": target["rating_key"],
                            "title": target["title"],
                            "entry_uri": target["entry_uri"],
                            "sha1": result["sha1"],
                            "bytes_written": result["bytes_written"],
                        },
                    )
                    log_event(
                        db_path, level="INFO", component="api",
                        media_type=target["media_type"],
                        tmdb_id=int(target["guid_tmdb"]),
                        section_id=target["section_id"],
                        message=(
                            f"cloud_theme_backup: "
                            f"{target['title']!r} "
                            f"({result['bytes_written']} bytes, "
                            f"sha1={result['sha1'][:12]}, "
                            f"backup_only=true)"
                        ),
                    )
                    op_progress.update_progress(
                        db_path, OP_ID,
                        stage_current=i,
                        processed_total=walked_count[0] + i,
                        activity=(
                            f"Backed up {target['title']!r} "
                            f"({result['bytes_written']} bytes)"
                        ),
                    )
                else:
                    errors.append({
                        "rk": target["rating_key"],
                        "title": target["title"],
                        "error": result.get("error"),
                    })
                    op_progress.update_progress(
                        db_path, OP_ID,
                        stage_current=i,
                        processed_total=walked_count[0] + i,
                        error_count=len(errors),
                        activity=(
                            f"Failed: {target['title']!r} "
                            f"({result.get('error') or 'unknown'})"
                        ),
                    )
            # v0.51.16 (audit #26): compensate for force-walk mints whose
            # download never landed (fetch error, disk error, or the cancel
            # break above). Guarded — only deletes still-plex_orphan
            # synthetic rows with NO local_files, so successful backups are
            # untouched.
            _unminted = unmint_stale_orphans(conn, targets)
            if _unminted:
                log.info(
                    "cloud_themes_backup: unminted %d stale orphan mint(s) "
                    "whose backup did not complete", _unminted,
                )
        # Stage 3: summary.
        summary = (
            f"CLOUD THEMES BACKUP completed: "
            f"{len(downloaded)} backed up, "
            f"{len(skipped_identical)} unchanged (identical), "
            # v1.23.81: proper plural, matching the sync-summary fix.
            f"{len(errors)} {'error' if len(errors) == 1 else 'errors'}"
        )
        log.info(summary)
        log_event(
            db_path, level="INFO", component="api",
            message=summary,
        )
        # v1.20.19: stamp the per-run outcome breakdown into the op's
        # detail_json (surfaced via /api/progress -> finalOp.detail) so
        # the SOURCE-menu force-capture flow can give a DEFINITIVE
        # message — "captured" vs "byte-identical, nothing to swap" vs
        # "nothing to capture" — instead of the conditional that left
        # the user guessing which branch fired on 10,000 BC. Must precede
        # finish_progress so the detail is present when status flips to
        # done (waitForOp returns the moment status != running).
        op_progress.set_detail_field(
            db_path, OP_ID, "backup_outcome",
            {
                "downloaded": len(downloaded),
                # v0.51.86: of the downloads, how many REPLACED an existing
                # backup (vs a first-ever capture) — the UI branches its
                # "Updated" vs "Captured" message on this.
                "replaced": sum(
                    1 for d in downloaded if d.get("replaced_prior")),
                "skipped_identical": len(skipped_identical),
                "errors": len(errors),
            },
        )
        # v1.21.25: uniform done_summary (see _doneHeadline in ops.js).
        op_progress.set_detail_field(
            db_path, OP_ID, "done_summary",
            [
                {"l": "backed up", "v": len(downloaded)},
                {"l": "skipped", "v": len(skipped_identical)},
            ] + ([{"l": "err", "v": len(errors)}] if errors else []),
        )
        final_status = "cancelled" if _cancel() else "done"
        op_progress.finish_progress(
            db_path, OP_ID, status=final_status,
        )
    except Exception as e:
        log.exception("cloud_themes_backup worker failed")
        log_event(
            db_path, level="ERROR", component="api",
            message=(
                f"CLOUD THEMES BACKUP failed: "
                f"{type(e).__name__}: {e}"
            ),
        )
        op_progress.finish_progress(
            db_path, OP_ID, status="failed", error_message=str(e),
        )


def _bulk_lps_run(
    db_path: Path, settings,
    *,
    targets: list[dict],
) -> None:
    """v1.15.28: server-side bulk LET PLEX SERVE.

    the user (post-v1.15.25): "attempting a bulk action of let
    plex server doesn't do anything. it indicates it will
    reprobe the selected items but nothing ends up happening
    or is seen in the status bar." Plus: "if an item was probed
    in the last 24hrs then no need to probe again."

    Pre-fix the bulk LPS flow was a two-stage user dance:
      1. Click LPS → confirm "probe first?"
      2. Probe runs in background, user has to manually re-click
         LPS after it finishes
      3. Re-confirm destructive action, JS fires per-row
         /unplace calls

    The probe completion was invisible (sub-poll-cadence ops
    miss the topbar mini-bar) and the user typically gave up
    thinking nothing had happened. Plus the re-click incurred
    another 24h-cooldown bypass that the user didn't want.

    Post-fix: one click, one op, one stage transition the user
    can watch in LIVE OPS.

      1. PROBE stage — partition `targets` into "probed alive
         within 24h" (skip) vs "needs probe" (run). Reuses the
         exact probe machinery from `_bulk_probe_tdb_run`
         (concurrency, batched writes, cancellation, transient
         classification) inline.
      2. UNPLACE stage — for each target whose row currently
         has `failure_kind IS NULL` (alive — either fresh-
         probed alive OR fresh enough to skip), unlink its
         theme.mp3 from the Plex folder. Mirrors the per-row
         `/unplace` endpoint's logic.

    Single op_id `bulk-lps`, kind `bulk_lps`. Coexists with
    `bulk-probe-tdb` (different op_id) — a concurrent global
    probe + bulk LPS would just race on per-row stamps, which
    is harmless (last writer wins, both stamp valid verdicts).
    """
    from concurrent.futures import ThreadPoolExecutor, as_completed
    from ..core import progress as op_progress
    from ..core.downloader import probe_youtube_url, FailureKind
    OP_ID = "bulk-lps"
    n_targets = len(targets)
    def _cancel() -> bool:
        return op_progress.is_cancelled(db_path, OP_ID)

    cookies = settings.cookies_file if settings.cookies_file else None

    n_alive = 0
    n_alive_cleared = 0
    n_dead = 0
    n_indet = 0
    n_other = 0
    error_count = 0
    n_skipped_fresh = 0
    n_unplaced = 0
    n_unplace_failed = 0
    n_dead_skipped = 0
    cancelled_early = False

    try:
        # v1.22.82: start INSIDE the try — a failed start (e.g.
        # database-is-locked past the busy timeout) used to kill
        # the runner thread with the try_acquire'd 'pending' row
        # stuck forever: every re-run 409'd and op_progress_running
        # pinned anyMutatingOpActive until container restart.
        # Mirror of _cloud_themes_backup_run's shape.
        op_progress.start_progress(
            db_path, op_id=OP_ID, kind="bulk_lps",
            stage="probe",
            stage_label=f"Probing TDB URLs for LPS ({n_targets} target(s))",
            stage_total=0, processed_est=0,
        )
        # ── PROBE stage ───────────────────────────────────────
        # Partition targets: those with last_probed_at within
        # the cooldown window are skipped (the user's "if an item
        # was probed in the last 24hrs then no need to probe
        # again"). The rest get probed.
        target_keys = [(t["media_type"], t["tmdb_id"]) for t in targets]
        with get_conn(db_path) as conn:
            rows = []
            # v1.22.85: chunk the IN-tuples at 400 pairs (800 params) —
            # the unbounded build hit SQLite's parameter cap on a huge
            # select-all ("too many SQL variables" → the whole op
            # aborted). Sibling _bulk_probe_tdb_run caps at 499 pairs;
            # chunking here keeps full coverage instead of degrading.
            for _ck in range(0, len(target_keys), 400):
                chunk = target_keys[_ck:_ck + 400]
                placeholders = ",".join("(?, ?)" for _ in chunk)
                params: list = []
                for mt, tid in chunk:
                    params.append(mt)
                    params.append(tid)
                rows.extend(conn.execute(
                    f"""
                    SELECT t.media_type AS media_type,
                           t.tmdb_id AS tmdb_id,
                           t.youtube_url AS target_url
                      FROM themes t
                     WHERE NULLIF(t.youtube_url, '') IS NOT NULL
                       AND (t.last_probed_at IS NULL
                            OR julianday(t.last_probed_at)
                               < julianday('now', '-{BULK_PROBE_COOLDOWN_HOURS} hours'))
                       AND (t.media_type, t.tmdb_id) IN ({placeholders})
                    """,
                    params,
                ).fetchall())
        n_to_probe = len(rows)
        n_skipped_fresh = n_targets - n_to_probe

        op_progress.update_progress(
            db_path, OP_ID,
            stage_total=n_to_probe,
            processed_est=n_to_probe,
            activity=(
                f"{n_skipped_fresh} target(s) probed within {BULK_PROBE_COOLDOWN_HOURS}h "
                f"— skipping; probing remaining {n_to_probe}"
            ),
        )

        def _probe_one(item):
            i, r = item
            mt = r["media_type"]
            tid = r["tmdb_id"]
            url = r["target_url"]
            try:
                result = probe_youtube_url(url, cookies_file=cookies)
                return mt, tid, url, result, None
            except Exception as e:
                return mt, tid, url, None, str(e)

        BATCH_SIZE = 50
        pending_stamps: list[tuple] = []
        pending_dead: list[tuple] = []
        pending_alive: list[tuple] = []

        def _flush_batch():
            nonlocal pending_stamps, pending_dead, pending_alive
            nonlocal n_alive_cleared
            if not pending_stamps and not pending_dead and not pending_alive:
                return
            with get_conn(db_path) as conn:
                with transaction(conn):
                    if pending_stamps:
                        conn.executemany(
                            "UPDATE themes SET last_probed_at = ? "
                            "WHERE media_type = ? AND tmdb_id = ?",
                            pending_stamps,
                        )
                    if pending_dead:
                        conn.executemany(
                            "UPDATE themes SET failure_kind = ?, "
                            "                  failure_message = ?, "
                            "                  failure_at = ?, "
                            "                  failure_acked_at = NULL "
                            "WHERE media_type = ? AND tmdb_id = ?",
                            pending_dead,
                        )
                    if pending_alive:
                        for (mt, tid) in pending_alive:
                            cur = conn.execute(
                                """UPDATE themes
                                      SET failure_kind = NULL,
                                          failure_message = NULL,
                                          failure_at = NULL,
                                          failure_acked_at = NULL
                                    WHERE media_type = ?
                                      AND tmdb_id = ?
                                      AND failure_kind IS NOT NULL""",
                                (mt, tid),
                            )
                            if cur.rowcount > 0:
                                n_alive_cleared += 1
                                conn.execute(
                                    """DELETE FROM section_failure_acks
                                        WHERE media_type = ?
                                          AND tmdb_id = ?""",
                                    (mt, tid),
                                )
            pending_stamps = []
            pending_dead = []
            pending_alive = []

        if n_to_probe > 0:
            with ThreadPoolExecutor(
                max_workers=BULK_PROBE_MAX_WORKERS,
            ) as pool:
                futures = {
                    pool.submit(_probe_one, (i, r)): i
                    for i, r in enumerate(rows)
                }
                done = 0
                for fut in as_completed(futures):
                    if _cancel():
                        cancelled_early = True
                        pool.shutdown(wait=False, cancel_futures=True)
                        try:
                            _flush_batch()
                        except Exception as e:
                            log.warning(
                                "BULK LPS flush on cancel failed: %s", e)
                        op_progress.update_progress(
                            db_path, OP_ID,
                            activity=(
                                f"Cancelled at {done}/{n_to_probe} probed — "
                                f"alive={n_alive}, dead={n_dead}; "
                                f"skipping unplace stage"
                            ),
                        )
                        op_progress.finish_progress(
                            db_path, OP_ID, status="cancelled")
                        return
                    mt, tid, url, result, err = fut.result()
                    done += 1
                    stamp = now_iso()
                    pending_stamps.append((stamp, mt, tid))
                    if err is not None:
                        error_count += 1
                        n_other += 1
                        log_event(
                            db_path, level="WARNING", component="bulk-lps",
                            message=f"BULK LPS probe error {mt}/{tid}: {err}",
                            detail={"media_type": mt, "tmdb_id": tid,
                                    "url": url, "reason": err},
                        )
                    elif result is None:
                        n_alive += 1
                        pending_alive.append((mt, tid))
                    elif result.needs_manual_override:
                        n_dead += 1
                        pending_dead.append(
                            (result.value, f"probe: {result.human}",
                             stamp, mt, tid),
                        )
                    elif result == FailureKind.COOKIES_EXPIRED:
                        n_indet += 1
                    else:
                        n_other += 1
                    if (len(pending_stamps) + len(pending_dead)
                            + len(pending_alive)) >= BATCH_SIZE:
                        _flush_batch()
                    if done % 5 == 0 or done == n_to_probe:
                        op_progress.update_progress(
                            db_path, OP_ID,
                            stage_current=done, processed_total=done,
                            error_count=error_count,
                            activity=(
                                f"{done}/{n_to_probe} probed — alive={n_alive}, "
                                f"dead={n_dead}, indeterminate={n_indet}, "
                                f"other={n_other}"
                            ),
                        )
                _flush_batch()

        # ── UNPLACE stage ─────────────────────────────────────
        # For each target whose theme row is currently alive
        # (failure_kind IS NULL), unlink its theme.mp3 from the
        # specified Plex folder. Targets that came back dead from
        # the probe (or were already dead pre-probe) get skipped
        # — that's the safety gate the v1.14.29 probe-first flow
        # was designed to enforce.
        op_progress.update_progress(
            db_path, OP_ID,
            stage="unplace",
            stage_label=(
                f"Unplacing themes (targets with verified-alive recovery URL)"
            ),
            stage_total=n_targets,
            processed_est=n_targets,
            activity=(
                f"Probe stage done: {n_alive} alive, {n_dead} dead, "
                f"{n_skipped_fresh} skipped (fresh). Starting unplace…"
            ),
        )

        # v1.15.95: gate on "motif has a canonical to fall back to"
        # instead of "TDB URL alive". Pre-fix the gate was
        # `themes.failure_kind IS NULL` which checks the TDB URL's
        # health. For T-source rows that made sense — motif's
        # canonical was downloaded from TDB, so if TDB is dead,
        # re-download isn't possible. But for U-source rows (user
        # provided their own URL) and A-source rows (adopted
        # sidecar), motif's canonical came from a NON-TDB source
        # and is preserved in themes_dir regardless of TDB health.
        # PUSH TO PLEX recovery hardlinks from themes_dir, so the
        # recovery path is intact.
        #
        # the user's repro: BULK LPS on 4 U+P rows with red-pill
        # TDB → `probed=0 (skipped-fresh=4), skipped-dead=4,
        # unplaced=0`. All 4 rows had failure_kind set (TDB
        # dead) so the gate skipped them. But each row had a
        # working user-URL canonical in themes_dir — LPS was
        # safe to proceed.
        #
        # New gate: motif has a local_files row for this
        # (mt, tmdb, section_id?). The canonical's source
        # (themerrdb / url / upload / adopt) doesn't matter —
        # only its existence does. Per-row query inside the
        # loop; n_targets is bounded by the JS selection so the
        # N+1 cost is acceptable.

        u_done = 0
        for t in targets:
            if _cancel():
                cancelled_early = True
                op_progress.finish_progress(
                    db_path, OP_ID, status="cancelled")
                return
            mt = t["media_type"]
            tid = t["tmdb_id"]
            section_id = t.get("section_id") or None
            # v1.21.97: edition-scope bulk LPS the same way the per-row
            # /unplace endpoint does (v1.21.67). The JS sends the row's
            # edition_key per item; absent (None) = legacy title-wide
            # behavior. Without this, BULK LET PLEX SERVE on one edition
            # of a multi-edition title deleted EVERY edition's placement
            # in that section (LotR Theatrical select → Extended's
            # separate theme unlinked too). '' here matches the standard
            # edition / shared placement; a tagged edition with no own
            # placement (Watchmen metadata edition) finds nothing → no-op.
            # v1.22.0 (line-close audit): bulk LPS does NOT carry the per-row
            # /unplace '' fallback (v1.21.93/95) — a mis-keyed single-edition
            # row (plex_items tagged, placement/local_files at '') no-ops here
            # by design; the per-row LET PLEX SERVE is the recovery for those.
            _ed = t.get("edition_key")
            _ed_sql = " AND edition_key = ?" if _ed is not None else ""
            _ed_args = (_ed,) if _ed is not None else ()
            with get_conn(db_path) as conn:
                if section_id:
                    has_canonical = conn.execute(
                        "SELECT 1 FROM local_files "
                        "WHERE media_type = ? AND tmdb_id = ? "
                        "  AND section_id = ?" + _ed_sql + " LIMIT 1",
                        (mt, tid, section_id) + _ed_args,
                    ).fetchone() is not None
                else:
                    has_canonical = conn.execute(
                        "SELECT 1 FROM local_files "
                        "WHERE media_type = ? AND tmdb_id = ?"
                        + _ed_sql + " LIMIT 1",
                        (mt, tid) + _ed_args,
                    ).fetchone() is not None
            if not has_canonical:
                # v1.15.95: counter name kept for log-format
                # backwards-compat. Semantic is now "no motif
                # canonical to fall back to" — if PUSH TO PLEX
                # can't recover, refuse to unplace and protect
                # the user from a dead-end state. Title-source
                # health (TDB / user URL) is no longer gating.
                n_dead_skipped += 1
                u_done += 1
                continue
            try:
                with get_conn(db_path) as conn:
                    # v1.18.73 (HIGH-C audit): widened SELECT to
                    # include placement_kind + section_id so the
                    # plex_upload teardown helper has the fields
                    # it needs. Pre-fix bulk LPS read only
                    # media_folder; plex_upload placements have
                    # media_folder='' so the Path-based unlink
                    # below silently no-op'd — the placements row
                    # got deleted but motif's API-uploaded theme
                    # stayed serving in Plex.
                    if section_id:
                        placements = conn.execute(
                            "SELECT media_folder, placement_kind, "
                            "       section_id "
                            "  FROM placements "
                            " WHERE media_type = ? AND tmdb_id = ? "
                            "   AND section_id = ?" + _ed_sql,
                            (mt, tid, section_id) + _ed_args,
                        ).fetchall()
                    else:
                        placements = conn.execute(
                            "SELECT media_folder, placement_kind, "
                            "       section_id "
                            "  FROM placements "
                            " WHERE media_type = ? AND tmdb_id = ?" + _ed_sql,
                            (mt, tid) + _ed_args,
                        ).fetchall()
                # v1.18.73 (HIGH-C audit): tear down Plex API
                # entries for plex_upload placements before the
                # sidecar unlink loop. Mirrors api_unplace_item's
                # v1.18.36 / v1.18.38 LPS restore path via the
                # shared v1.18.60 helper.
                plex_upload_placements = [
                    pr for pr in placements
                    if (pr["placement_kind"] or "") == "plex_upload"
                ]
                if plex_upload_placements:
                    try:
                        _teardown_plex_api_artifacts_for_placements(
                            db_path, settings, mt, tid,
                            plex_upload_placements,
                        )
                    except Exception as e:  # noqa: BLE001
                        log.warning(
                            "BULK LPS: plex API teardown failed "
                            "for %s/%s: %s — sidecar sweep "
                            "continuing", mt, tid, e,
                        )
                unlinked_any = False
                for pr in placements:
                    # v1.18.73 (HIGH-C audit): plex_upload rows
                    # were handled by the API teardown above; the
                    # sidecar loop's Path('')/'theme.mp3' check
                    # was a silent no-op for them. Explicit skip
                    # here makes the intent visible + counts the
                    # row as "unlinked_any" for the downstream
                    # placements DELETE.
                    if (pr["placement_kind"] or "") == "plex_upload":
                        unlinked_any = True
                        continue
                    p = Path(pr["media_folder"]) / "theme.mp3"
                    try:
                        if p.is_file():
                            p.unlink()
                            unlinked_any = True
                    except Exception as e:
                        log.warning(
                            "BULK LPS unplace failed for %s/%s at %s: %s",
                            mt, tid, p, e)
                if unlinked_any or placements:
                    # v1.15.106: mirror api_unplace_item's plex_items
                    # update — pre-fix BULK LPS deleted the placements
                    # row but left pi.local_theme_file=1 stale. The
                    # SRC SQL then read `p.media_folder IS NULL AND
                    # pi.local_theme_file = 1` and rendered as M (a
                    # phantom "manual sidecar" classification), even
                    # though the row was actually U+P (user override
                    # canonical + Plex-serving). Adopting the phantom
                    # M then failed with `no theme.mp3 at <content
                    # folder>` because the file was at themes_dir,
                    # not the content folder. Natural-key lookup
                    # mirrors v1.15.90's api_unplace_item pattern:
                    # theme_id FK preferred, guid_tmdb+media_type
                    # fallback for orphan rows.
                    # v0.51.49: else mt (was "movie") so bulk LET PLEX SERVE on a
                    # themed collection matches its plex_items rows (media_type=
                    # 'collection'); the mt-keyed sibling of the v0.51.48 sweep.
                    plex_media_type = (
                        "show" if mt == "tv" else mt)
                    with get_conn(db_path) as conn:
                        with transaction(conn):
                            if section_id:
                                conn.execute(
                                    "DELETE FROM placements WHERE "
                                    "media_type = ? AND tmdb_id = ? "
                                    "AND section_id = ?" + _ed_sql,
                                    (mt, tid, section_id) + _ed_args,
                                )
                            else:
                                conn.execute(
                                    "DELETE FROM placements WHERE "
                                    "media_type = ? AND tmdb_id = ?" + _ed_sql,
                                    (mt, tid) + _ed_args,
                                )
                            # v1.16.12: stamp local_files.last_place_
                            # attempt_reason = 'plex_has_theme' so the
                            # v1.13.76 retry sweep skips these rows.
                            # Mirrors api_unplace_item — same fix, same
                            # reason. the user's bulk-LPS of 121 M+P rows
                            # produced 121 "Skipped placement" INFO
                            # lines on the next hourly sweep because
                            # this stamp was missing.
                            if section_id:
                                conn.execute(
                                    "UPDATE local_files SET "
                                    "    last_place_attempt_at = ?, "
                                    "    last_place_attempt_reason = 'backup_only' "
                                    "WHERE media_type = ? AND tmdb_id = ? "
                                    "AND section_id = ?" + _ed_sql,
                                    (now_iso(), mt, tid, section_id) + _ed_args,
                                )
                            else:
                                conn.execute(
                                    "UPDATE local_files SET "
                                    "    last_place_attempt_at = ?, "
                                    "    last_place_attempt_reason = 'backup_only' "
                                    "WHERE media_type = ? AND tmdb_id = ?" + _ed_sql,
                                    (now_iso(), mt, tid) + _ed_args,
                                )
                            theme_row = conn.execute(
                                "SELECT id FROM themes "
                                "WHERE media_type = ? AND tmdb_id = ?",
                                (mt, tid),
                            ).fetchone()
                            theme_id_pk = (
                                theme_row["id"] if theme_row else None)
                            pi_where_parts = []
                            pi_where_args: list = []
                            if theme_id_pk is not None:
                                pi_where_parts.append("theme_id = ?")
                                pi_where_args.append(theme_id_pk)
                            pi_where_parts.append(
                                "(guid_tmdb = ? AND media_type = ?)")
                            pi_where_args.extend(
                                [str(tid), plex_media_type])
                            pi_where = " OR ".join(pi_where_parts)
                            if section_id:
                                pi_where = (
                                    f"({pi_where}) AND section_id = ?")
                                pi_where_args.append(section_id)
                            # v1.21.97: scope the local_theme_file clear to the
                            # unplaced edition so a sibling edition's PL/SRC
                            # state isn't reset by a bulk LPS on this edition.
                            if _ed is not None:
                                pi_where = f"({pi_where}) AND edition_key = ?"
                                pi_where_args.append(_ed)
                            conn.execute(
                                "UPDATE plex_items SET "
                                "    local_theme_file = 0, "
                                "    plex_theme_verified_ok = NULL "
                                f"WHERE {pi_where}",
                                pi_where_args,
                            )
                    n_unplaced += 1
                else:
                    # No placement file existed — treat as already-served-by-Plex.
                    # v1.17.1 (L3 class-P): mirror api_unplace_item's
                    # unconditional stamp. Pre-fix the v1.16.12 stamp
                    # only ran when placements were non-empty — a row
                    # that had no placement (already Plex-served from
                    # a prior LPS that ran before v1.16.12 landed, or
                    # an out-of-band cleanup) carried its prior
                    # `last_place_attempt_reason='placed'` value and
                    # got re-enqueued by the v1.13.76 retry sweep.
                    # Stamp here so the no-placement branch also
                    # short-circuits the sweep.
                    with get_conn(db_path) as conn:
                        with transaction(conn):
                            if section_id:
                                conn.execute(
                                    "UPDATE local_files SET "
                                    "    last_place_attempt_at = ?, "
                                    "    last_place_attempt_reason = 'backup_only' "
                                    "WHERE media_type = ? AND tmdb_id = ? "
                                    "AND section_id = ?" + _ed_sql,
                                    (now_iso(), mt, tid, section_id) + _ed_args,
                                )
                            else:
                                conn.execute(
                                    "UPDATE local_files SET "
                                    "    last_place_attempt_at = ?, "
                                    "    last_place_attempt_reason = 'backup_only' "
                                    "WHERE media_type = ? AND tmdb_id = ?" + _ed_sql,
                                    (now_iso(), mt, tid) + _ed_args,
                                )
                    n_unplaced += 1
            except Exception as e:
                n_unplace_failed += 1
                log_event(
                    db_path, level="WARNING", component="bulk-lps",
                    message=f"BULK LPS unplace error {mt}/{tid}: {e}",
                    detail={"media_type": mt, "tmdb_id": tid,
                            "section_id": section_id, "reason": str(e)},
                )
            u_done += 1
            if u_done % 5 == 0 or u_done == n_targets:
                op_progress.update_progress(
                    db_path, OP_ID,
                    # v0.50.41: carry the probe stage's count forward so the op-wide
                    # 'items processed' counter (+ RUN INSIGHT avg/s) stays monotonic
                    # — was processed_total=u_done, which jumped backward n_to_probe→0
                    # at the probe→unplace boundary. stage_current stays per-stage.
                    stage_current=u_done, processed_total=n_to_probe + u_done,
                    activity=(
                        f"{u_done}/{n_targets} unplace processed — "
                        f"unplaced={n_unplaced}, "
                        f"skipped-dead={n_dead_skipped}, "
                        f"failed={n_unplace_failed}"
                    ),
                )

        # v1.21.25: uniform done_summary (see _doneHeadline in ops.js).
        _lps_ds = [
            {"l": "probed", "v": n_to_probe},
            {"l": "unplaced", "v": n_unplaced},
        ]
        if n_unplace_failed:
            _lps_ds.append({"l": "failed", "v": n_unplace_failed})
        op_progress.set_detail_field(db_path, OP_ID, "done_summary", _lps_ds)
        op_progress.finish_progress(db_path, OP_ID, status="done")
        _bulk_lps_summary = (
            f"BULK LPS done: {n_targets} target(s) — "
            f"probed={n_to_probe} (skipped-fresh={n_skipped_fresh}), "
            f"alive={n_alive}, dead={n_dead}, "
            f"unplaced={n_unplaced}, "
            f"skipped-dead={n_dead_skipped}, "
            f"unplace-failed={n_unplace_failed}"
        )
        log_event(
            db_path, level="INFO", component="bulk-lps",
            message=_bulk_lps_summary,
        )
        # v1.17.0: bulk_action_completed notification.
        # v1.17.1 (M4): gate on n_targets > 0 so an empty-selection
        # invocation doesn't ping the operator with "0 targets" noise.
        if n_targets > 0:
            try:
                from ..core import notify as _notify
                _notify.dispatch(
                    db_path, settings.cfg.notifications,
                    event_kind="bulk_action_completed",
                    # v1.17.19: ✅ emoji prefix + drop "motif:".
                    title=f"✅ Bulk LPS done — {n_targets}",
                    # v1.19.92: notification body drops the "BULK LPS
                    # done: {n_targets} target(s)" headline (restated
                    # the title) and keeps only the breakdown. The
                    # log_event above keeps the full verbose summary.
                    body=(
                        f"probed={n_to_probe} "
                        f"(skipped-fresh={n_skipped_fresh}), "
                        f"alive={n_alive}, dead={n_dead}, "
                        f"unplaced={n_unplaced}, "
                        f"skipped-dead={n_dead_skipped}, "
                        f"unplace-failed={n_unplace_failed}"
                    ),
                )
            except Exception as e:
                # v1.17.1 (class 9): log breadcrumb on swallow.
                log.debug("notify dispatch (bulk-lps) suppressed: %s", e)
    except Exception as e:
        log.exception("BULK LPS failed")
        op_progress.finish_progress(
            db_path, OP_ID, status="failed", error_message=str(e))


def _reprobe_plex_themes_run(db_path: Path, settings) -> None:
    from concurrent.futures import ThreadPoolExecutor, as_completed
    from ..core import progress as op_progress
    from ..core.plex import PlexClient, PlexConfig
    OP_ID = "reprobe-plex-themes"
    def _cancel() -> bool:
        return op_progress.is_cancelled(db_path, OP_ID)

    cfg = PlexConfig(
        url=settings.plex_url, token=settings.plex_token,
        movie_section=settings.plex_movie_section,
        tv_section=settings.plex_tv_section, enabled=True,
    )

    set_indep = 0
    set_clean = 0
    skipped = 0
    error_count = 0
    # v1.21.8 (audit MED): defined before the try so the finally net
    # below can always close them — the in-body close loops only run on
    # the cancel + success paths, so any exception mid-run leaked
    # PROBE_MAX_WORKERS httpx clients.
    clients: list = []
    try:
        # v1.22.82: start INSIDE the try — a failed start (e.g.
        # database-is-locked past the busy timeout) used to kill
        # the runner thread with the try_acquire'd 'pending' row
        # stuck forever: every re-run 409'd and op_progress_running
        # pinned anyMutatingOpActive until container restart.
        # Mirror of _cloud_themes_backup_run's shape.
        op_progress.start_progress(
            db_path, op_id=OP_ID, kind="reprobe_plex_themes",
            stage="probe", stage_label="Reprobing Plex themes",
            stage_total=0, processed_est=0,
        )
        with get_conn(db_path) as conn:
            # v1.13.43: source the sidecar path from `pi.folder_path`
            # (Plex's reported folder for the item) instead of joining
            # to motif's `placements` table. The placements join was a
            # silent gap: it only matched motif-placed rows (T/U/A
            # primary SRC), missing manual sidecars (M letter — files
            # someone else dropped at the Plex folder that Plex sees
            # but motif didn't place) and any row in TV/Anime libraries
            # whose placements row hadn't been backfilled. Using
            # folder_path covers every sidecar-bearing row Plex enum
            # can see, regardless of who put the file there.
            # v1.14.82: pull theme.media_type / theme.tmdb_id /
            # theme.title via LEFT JOIN so the per-rk REPROBE
            # error events can be enriched with row context.
            # The /queue events log uses these to render inline
            # OPEN ROW buttons that deep-link the user into the
            # INFO dialog for the failing row, where the
            # existing PURGE/UNPLACE actions can resolve the
            # underlying issue. Pre-fix the events log only
            # carried `rating_key + reason`, which forced the
            # operator to manually map rk → row via /api/items
            # before they could act. LEFT JOIN handles the
            # plex-orphan case (theme_id NULL) by falling back
            # to plex_items.title in the enrichment below.
            # v1.14.90: also pull is_4k from plex_sections so the
            # event-detail enrichment below can include it. The
            # /queue OPEN ROW button uses is_4k to deep-link into
            # the right library variant — pre-fix the navigation
            # routed to whichever fourk the user last visited on
            # that tab, so a row that lives in standard movies
            # would show a blank library when last-visited was
            # 4K. the user's repro: clicked OPEN ROW for Terminator
            # 2 (standard), landed on /movies?fourk=1 (last
            # visited), saw 0 matches.
            rows = conn.execute(
                "SELECT pi.rating_key, pi.section_id, "
                "       pi.folder_path, pi.title AS plex_title, "
                "       t.media_type, t.tmdb_id, "
                "       t.title AS theme_title, "
                "       ps.is_4k AS section_is_4k "
                "  FROM plex_items pi "
                "  LEFT JOIN themes t ON t.id = pi.theme_id "
                "  LEFT JOIN plex_sections ps "
                "    ON ps.section_id = pi.section_id "
                " WHERE pi.plex_independent_theme IS NULL "
                "   AND COALESCE(pi.has_theme, 0) = 1 "
                "   AND COALESCE(pi.local_theme_file, 0) = 1 "
                "   AND pi.folder_path != '' "
                " ORDER BY pi.section_id, pi.rating_key"
            ).fetchall()
            # v1.14.82: index for the error-log enrichment below.
            # _probe_one's tuple only carries (rk, verdict, err);
            # we look the original row back up by rk to grab
            # media_type/tmdb_id/section_id/title without
            # threading them through every probe call.
            row_by_rk = {r["rating_key"]: r for r in rows}
        total = len(rows)
        op_progress.update_progress(
            db_path, OP_ID,
            stage_total=total,
            processed_est=total,
            activity=f"Found {total} sidecar-bearing rows to probe",
        )
        if total == 0:
            op_progress.finish_progress(db_path, OP_ID, status="done")
            return

        # One PlexClient per worker THREAD via threading.local.
        # v1.22.82: the old submission-index round-robin
        # (clients[idx % N]) let two threads drive ONE client whenever
        # completion order diverged from submission order (task 0 slow,
        # a freed thread picks task N: N % N = 0) — the exact unsafe
        # sharing this pool was built to prevent, and the canonical
        # template CLAUDE.md tells multi-item work to mirror.
        import threading as _threading
        _probe_tl = _threading.local()
        clients: list[PlexClient] = []
        _clients_lock = _threading.Lock()

        def _client_for_thread() -> PlexClient:
            c = getattr(_probe_tl, "client", None)
            if c is None:
                c = PlexClient(cfg, plus_mode=settings.plus_equiv_mode)
                _probe_tl.client = c
                with _clients_lock:
                    clients.append(c)
            return c

        def _probe_one(idx_row):
            idx, r = idx_row
            rk = r["rating_key"]
            folder_path = r["folder_path"]
            client = _client_for_thread()
            try:
                p = Path(folder_path) / "theme.mp3"
                if not p.is_file():
                    return rk, None, "sidecar missing"
                with p.open("rb") as f:
                    local_prefix = f.read(PROBE_PREFIX_BYTES)
                if not local_prefix:
                    return rk, None, "sidecar empty"
                plex_prefix = client.fetch_theme_prefix(
                    rk, n_bytes=PROBE_PREFIX_BYTES,
                )
                if plex_prefix is None:
                    return rk, None, "plex range-GET failed"
                # Equal length compare: trailing bytes Plex didn't
                # serve (smaller theme than 2 KB) shouldn't false-
                # positive. Truncate both to the shorter length.
                n = min(len(local_prefix), len(plex_prefix))
                if n == 0:
                    return rk, None, "empty response"
                if local_prefix[:n] == plex_prefix[:n]:
                    return rk, 0, None  # Plex serves the sidecar
                return rk, 1, None  # Plex serves something else
            except Exception as e:
                return rk, None, f"probe error: {e}"

        # v1.13.54: batch verdict writes. Pre-fix every probe result
        # opened a fresh `with get_conn(db_path)` and ran one UPDATE
        # — on a 1K-sidecar library that's 1K connection opens + 1K
        # BEGIN IMMEDIATE waits, all racing the worker's writer lock.
        # Buffer verdicts in pending lists keyed by the value to
        # write (1 / 0) and flush to the DB every BATCH_SIZE results
        # (or at the end of the run / on cancel) inside one
        # transaction per flush.
        BATCH_SIZE = 100
        pending_indep: list[str] = []
        pending_clean: list[str] = []

        def _flush_batch():
            nonlocal pending_indep, pending_clean
            if not pending_indep and not pending_clean:
                return
            with get_conn(db_path) as conn:
                with transaction(conn):
                    if pending_indep:
                        conn.executemany(
                            "UPDATE plex_items SET plex_independent_theme = 1 "
                            "WHERE rating_key = ?",
                            [(rk,) for rk in pending_indep],
                        )
                    if pending_clean:
                        conn.executemany(
                            "UPDATE plex_items SET plex_independent_theme = 0 "
                            "WHERE rating_key = ?",
                            [(rk,) for rk in pending_clean],
                        )
            pending_indep = []
            pending_clean = []

        with ThreadPoolExecutor(max_workers=PROBE_MAX_WORKERS) as pool:
            futures = {
                pool.submit(_probe_one, (i, r)): i
                for i, r in enumerate(rows)
            }
            done = 0
            for fut in as_completed(futures):
                if _cancel():
                    pool.shutdown(wait=False, cancel_futures=True)
                    # Flush whatever's already queued so partial
                    # progress isn't lost on cancel.
                    try:
                        _flush_batch()
                    except Exception as e:
                        log.warning("REPROBE flush on cancel failed: %s", e)
                    op_progress.finish_progress(
                        db_path, OP_ID, status="cancelled")
                    for c in clients:
                        try:
                            c.close()
                        except Exception as e:
                            # v1.15.0: log at DEBUG so a recurring
                            # client-leak surfaces in verbose logs.
                            # Pre-fix this swallowed every exception
                            # silently — same shape as the v1.14.93
                            # bulk-probe-tdb thread death that hid for
                            # 3 releases. Cleanup-error on cancel
                            # path doesn't merit WARN, but a
                            # breadcrumb is cheap.
                            log.debug(
                                "REPROBE PlexClient close failed on cancel: %s",
                                e,
                            )
                    return
                rk, verdict, err = fut.result()
                done += 1
                if verdict == 1:
                    pending_indep.append(rk)
                    set_indep += 1
                elif verdict == 0:
                    pending_clean.append(rk)
                    set_clean += 1
                else:
                    skipped += 1
                    # v1.13.50: every verdict-is-None outcome is a
                    # case where we couldn't classify the row —
                    # treat them all as errors so the topbar +
                    # drawer surface the count.
                    error_count += 1
                    # v1.13.89: log the reason at WARNING so the
                    # operator can diagnose. Pre-fix the err string
                    # was captured but discarded; the only signal
                    # was the bare "errors=N" in the summary log.
                    # Reasons are one of: sidecar missing, sidecar
                    # empty, plex range-GET failed, empty response,
                    # or "probe error: <exception>".
                    # v1.14.82: enrich the detail with row context
                    # (media_type/tmdb_id/section_id/title) resolved
                    # via plex_items LEFT JOIN themes at row-fetch
                    # time. /queue's events log uses these to render
                    # an inline OPEN ROW button that deep-links the
                    # operator into the INFO dialog where the
                    # existing PURGE/UNPLACE actions can resolve the
                    # underlying issue. theme_title falls back to
                    # plex_title for plex-orphan rows (theme_id
                    # NULL); media_type/tmdb_id will be NULL for
                    # those — the client renders the button in a
                    # disabled state with a tooltip in that case.
                    r_orig = row_by_rk.get(rk, {})
                    log_event(
                        db_path, level="WARNING", component="reprobe",
                        message=f"REPROBE error rk={rk}: {err or 'unknown'}",
                        detail={
                            "rating_key": rk,
                            "reason": err or "unknown",
                            "media_type": (
                                r_orig["media_type"]
                                if r_orig else None
                            ),
                            "tmdb_id": (
                                r_orig["tmdb_id"]
                                if r_orig else None
                            ),
                            "section_id": (
                                r_orig["section_id"]
                                if r_orig else None
                            ),
                            # v1.14.90: is_4k drives the OPEN ROW
                            # navigation's ?fourk= URL param so
                            # the row's actual library variant
                            # wins over last-visited.
                            "is_4k": (
                                int(r_orig["section_is_4k"] or 0)
                                if r_orig else 0
                            ),
                            "title": (
                                (r_orig["theme_title"]
                                 or r_orig["plex_title"])
                                if r_orig else None
                            ),
                        },
                    )
                if (len(pending_indep) + len(pending_clean)) >= BATCH_SIZE:
                    _flush_batch()
                if done % 25 == 0 or done == total:
                    op_progress.update_progress(
                        db_path, OP_ID,
                        stage_current=done, processed_total=done,
                        error_count=error_count,
                        activity=(
                            f"{done}/{total} probed — "
                            f"+P found: {set_indep}, "
                            f"sidecar-only: {set_clean}, "
                            f"skipped: {skipped}"
                        ),
                    )
            # Final flush after the loop drains.
            _flush_batch()

        for c in clients:
            try:
                c.close()
            except Exception as e:
                # v1.15.0: log at DEBUG — see the matching cancel-path
                # comment above for rationale.
                log.debug(
                    "REPROBE PlexClient close failed on success: %s", e,
                )
        # v1.21.25: uniform done_summary (see _doneHeadline in ops.js).
        op_progress.set_detail_field(
            db_path, OP_ID, "done_summary",
            [
                {"l": "probed", "v": total},
                {"l": "Plex-served", "v": set_indep},
                {"l": "sidecar", "v": set_clean},
            ],
        )
        op_progress.finish_progress(db_path, OP_ID, status="done")
        log_event(
            db_path, level="INFO", component="reprobe",
            message=(
                f"REPROBE done: {total} probed, +P={set_indep}, "
                f"sidecar-only={set_clean}, skipped={skipped}, "
                f"errors={error_count}"
            ),
        )
    except Exception as e:
        log.exception("REPROBE PLEX THEMES failed")
        op_progress.finish_progress(
            db_path, OP_ID, status="failed", error_message=str(e))
    finally:
        # v1.21.8 (audit MED): guarantee the httpx clients close on
        # EVERY exit path. The in-body close loops only run on the
        # cancel + success branches, so any mid-run exception leaked
        # them. Double-close is a safe no-op on httpx clients.
        for c in clients:
            try:
                c.close()
            except Exception as _ce:
                log.debug(
                    "REPROBE PlexClient close failed (finally): %s", _ce)


# v1.21.18 (security audit): magic-byte gate for the UPLOAD MP3 path.
# Pre-fix any bytes were accepted and written as theme.mp3 (format was only
# sniffed later at serve time). An admin could store an HTML/script/binary
# blob under a .mp3 name. We accept the common audio container signatures
# (lenient on container so a legitimate non-MP3 theme isn't rejected) and
# reject everything else. Mirrors the serve-time sniff at the theme.mp3 GET.
def _looks_like_audio(head: bytes) -> bool:
    if not head or len(head) < 4:
        return False
    if head[:3] == b"ID3":            # ID3v2-tagged MP3
        return True
    if head[0] == 0xFF and (head[1] & 0xE0) == 0xE0:  # MPEG audio frame sync
        return True
    if head[:4] == b"OggS":           # Ogg (Vorbis/Opus)
        return True
    if head[:4] == b"fLaC":           # FLAC
        return True
    if head[:4] == b"RIFF" and head[8:12] == b"WAVE":  # WAV
        return True
    if head[:4] == b"FORM" and head[8:12] in (b"AIFF", b"AIFC"):  # AIFF
        return True
    if head[4:8] == b"ftyp":          # MP4/M4A container
        return True
    return False


# v1.21.24: orphan scan is a page-scoped background op. It runs in a daemon
# thread (not the HTTP request) so it survives the operator navigating away,
# and reports live progress + the final findings via this in-process state
# dict — the orphans page polls /api/admin/orphan-scan/status. In-memory by
# design: a read-only diagnostic doesn't need to survive a container restart,
# only a page reload (which process-shared state does). Single uvicorn worker
# → one dict is authoritative. Replaced the old synchronous GET, which ran
# the whole per-row Plex walk inside the request: no progress, and the
# browser aborted it the moment you left the page.
_ORPHAN_SCAN_LOCK = threading.Lock()
_ORPHAN_SCAN_STATE: dict = {"status": "idle"}


def _orphan_scan_run(settings: "Settings", db_path: Path) -> None:
    from ..core.plex import PlexClient, PlexConfig
    from ..core.orphan_scan import scan_plex_upload_placements, summarize

    def _cb(done: int, total: int) -> None:
        with _ORPHAN_SCAN_LOCK:
            _ORPHAN_SCAN_STATE["done"] = done
            _ORPHAN_SCAN_STATE["total"] = total

    try:
        cfg = PlexConfig(
            url=settings.plex_url, token=settings.plex_token,
            movie_section=settings.plex_movie_section,
            tv_section=settings.plex_tv_section, enabled=True,
        )
        with PlexClient(cfg, plus_mode=settings.plus_equiv_mode) as plex:
            findings = scan_plex_upload_placements(
                db_path, plex, themes_dir=settings.themes_dir,
                progress_cb=_cb,
            )
        with _ORPHAN_SCAN_LOCK:
            _ORPHAN_SCAN_STATE.update(
                status="done", findings=findings,
                summary=summarize(findings), total=len(findings),
                done=len(findings), scanned_at=now_iso(), error=None,
            )
    except Exception as e:  # noqa: BLE001
        log.exception("orphan scan failed")
        with _ORPHAN_SCAN_LOCK:
            _ORPHAN_SCAN_STATE.update(status="failed", error=str(e))


# v0.51.158: LOUDNESS AUDIT — the same page-scoped in-memory background-op shape as
# orphan scan (read-only diagnostic, survives a page reload not a container restart,
# single uvicorn worker → one authoritative dict). Deliberately NOT an op_progress
# kind: that would need the op_progress.kind CHECK-widen migration (CLAUDE.md flags
# _widen_check_constraint as the most dangerous op — the v1.18.0 data-loss class) for
# zero benefit here (a read-only measure mutates no library-row chip state).
_LOUDNESS_AUDIT_LOCK = threading.Lock()
_LOUDNESS_AUDIT_STATE: dict = {"status": "idle"}


def _loudness_audit_run(settings: "Settings", db_path: Path) -> None:
    from ..core.loudness_audit import run_loudness_audit

    def _cb(done: int, total: int) -> None:
        with _LOUDNESS_AUDIT_LOCK:
            _LOUDNESS_AUDIT_STATE["done"] = done
            _LOUDNESS_AUDIT_STATE["total"] = total

    try:
        summary = run_loudness_audit(
            db_path, themes_dir=settings.themes_dir, progress_cb=_cb,
        )
        with _LOUDNESS_AUDIT_LOCK:
            _LOUDNESS_AUDIT_STATE.update(
                status="done", summary=summary,
                total=summary["to_measure"], done=summary["to_measure"],
                scanned_at=now_iso(), error=None,
            )
    except Exception as e:  # noqa: BLE001
        log.exception("loudness audit failed")
        with _LOUDNESS_AUDIT_LOCK:
            _LOUDNESS_AUDIT_STATE.update(status="failed", error=str(e))


# -------- App factory --------

# v0.51.173: Plex's metadata refresh is async — poll the measurement instead of
# sleeping once and guessing whether the agent got there.
_CONTROL_SAMPLE = 6   # v0.51.179: one row can't answer a library-wide question
_REREAD_POLLS = 4
_REREAD_POLL_S = 5


def _lock_verdict(control_locked, working_shape) -> str:
    """v0.51.178: the CONTROL row's natural lock state decides whether unlock+refresh is
    still a live propagation candidate. Never let an unread flag (None) read as a pass."""
    if control_locked is None:
        return ("could not read the control row's theme lock — NO verdict. Without that "
                "flag nothing here is decided; do not read this as a pass.")
    if control_locked:
        return ("sidecar rows ARE theme-locked by default — so the field was locked when "
                "v0.51.173's refresh failed to re-read the changed sidecar, and the lock "
                "is a live explanation for it. UNLOCK + REFRESH is untested and worth the "
                "next tag: it would be ceiling-free and reach all 2,821 themes."
                + ("" if working_shape else
                   " Fix the unlock first — neither shape moved the flag here."))
    return ("sidecar rows are NOT theme-locked — the field was already unlocked when "
            "v0.51.173's refresh ran, and it still did not re-read the sidecar. The lock "
            "was never the blocker, so unlock+refresh cannot be the answer either. "
            "RE-UPLOAD is the propagation mechanism."
            + ("" if working_shape is None else
               f" (The {working_shape} shape does move the flag.)"))


def _measure_plex_serving(settings, *, rk: str, canonical_i, norm_gain_db=None) -> dict:
    """v0.51.171: what is Plex ACTUALLY serving for this item's theme?

    v0.51.168 assumed a hardlinked sidecar meant Plex played the new bytes live. It
    doesn't: Local Media Assets INGESTS theme.mp3 into Plex's own store at scan time
    (hence metadata://themes/<sha1>, keyed by CONTENT hash), so mutating the sidecar
    changes nothing Plex plays. Measured on the real library: canonical -18.7 LUFS,
    Plex still serving -5.15 — a 13.5 dB gap the operator could hear (or rather,
    couldn't). This fetches the SELECTED entry's bytes and measures them, so the
    question is answered with a number instead of an ear.

    Shared by // WHAT IS PLEX SERVING? and the re-read probe. Blocking (HTTP + ffmpeg)
    — call from a thread (class-12). Never raises."""
    import tempfile
    from ..core.loudness import measure_loudness

    if not settings.plex_url or not settings.plex_token:
        return {"ok": False, "error": "Plex is not configured"}
    cfg = PlexConfig(
        url=settings.plex_url, token=settings.plex_token,
        movie_section=settings.plex_movie_section,
        tv_section=settings.plex_tv_section, enabled=True,
    )
    entry_uri = None
    with PlexClient(cfg, plus_mode=settings.plus_equiv_mode) as plex:
        entries = plex.get_themes(rating_key=rk)
        if not entries.get("ok"):
            return {"ok": False, "rating_key": rk,
                    "error": f"Plex /themes failed: "
                             f"{entries.get('error') or entries.get('http_status')}"}
        meta = []
        b = entries.get("body")
        if isinstance(b, dict):
            meta = (b.get("MediaContainer") or {}).get("Metadata") or []
        if not meta:
            return {"ok": False, "rating_key": rk,
                    "error": "Plex lists no theme entries for this item"}
        # the SELECTED entry is what Plex actually plays (CLAUDE.md: singular /theme is
        # the association; plural /themes is the collection).
        sel = next((m for m in meta if m.get("selected")), meta[0])
        entry_uri = sel.get("ratingKey") or sel.get("key")
        fetched = plex.fetch_theme_bytes(item_rating_key=rk, entry_uri=str(entry_uri))
    if not fetched.get("ok") or not fetched.get("bytes"):
        return {"ok": False, "rating_key": rk, "entry_uri": entry_uri,
                "error": f"could not fetch Plex's bytes: {fetched.get('error')}"}

    with tempfile.TemporaryDirectory() as td:
        tmp = Path(td) / "plex_theme.mp3"
        tmp.write_bytes(fetched["bytes"])
        m = measure_loudness(tmp)
    if m is None:
        return {"ok": False, "rating_key": rk, "entry_uri": entry_uri,
                "error": "ffmpeg could not measure Plex's bytes"}

    plex_i = m["loudness_i"]
    # within half an mp3gain step ⇒ Plex is serving what motif has on disk.
    serving_normalized = (canonical_i is not None and abs(plex_i - canonical_i) < 0.75)
    return {
        "ok": True, "rating_key": rk, "entry_uri": entry_uri, "entries": len(meta),
        "canonical_loudness_i": canonical_i,
        "plex_loudness_i": plex_i, "plex_true_peak": m["true_peak"],
        "norm_gain_db": norm_gain_db,
        "serving_normalized": serving_normalized,
        "verdict": ("Plex is serving the NORMALIZED theme"
                    if serving_normalized else
                    "Plex is serving the PRE-normalize theme — the sidecar changed but "
                    "Plex still plays its ingested copy (needs a metadata refresh to "
                    "re-read it)"),
    }


def create_app(settings: Settings | None = None) -> FastAPI:
    settings = settings or get_settings()
    app = FastAPI(title="Motif", docs_url=None, redoc_url=None)

    static_dir = Path(__file__).parent / "static"
    template_dir = Path(__file__).parent / "templates"
    static_dir.mkdir(parents=True, exist_ok=True)
    template_dir.mkdir(parents=True, exist_ok=True)
    app.mount("/static", StaticFiles(directory=str(static_dir)), name="static")
    templates = Jinja2Templates(directory=str(template_dir))

    # Make __version__ available to every template (rendered into the brand
    # badge at top-left). Centralising here means individual route handlers
    # don't need to remember to pass it.
    from .. import __version__ as motif_version
    templates.env.globals["motif_version"] = motif_version

    # v1.15.21: SSR tab availability for the nav. Pre-fix base.html
    # hardcoded `style="display:none"` on the MOVIES / TV SHOWS /
    # ANIME nav links and JS revealed them via /api/stats data after
    # first paint. Even with the v1.11.33 localStorage cache the
    # restore ran inside the defer-loaded app.js — by the time it
    # executed the user had already seen the hidden state on tab
    # switch ("the libraries section disappear briefly"). Computing
    # availability at template-render time delivers HTML with the
    # right initial visibility so there's no flash and no JS
    # dependency for first paint. Cheap single-row EXISTS query;
    # any DB read failure falls through to all-hidden (safe default,
    # JS still recovers from /api/stats on a working install).
    def _tab_availability_for_nav() -> dict:
        try:
            with get_conn(settings.db_path) as conn:
                row = conn.execute("""
                    SELECT
                      EXISTS (SELECT 1 FROM plex_sections
                              WHERE included=1 AND type='movie' AND is_anime=0) AS movies,
                      EXISTS (SELECT 1 FROM plex_sections
                              WHERE included=1 AND type='show'  AND is_anime=0) AS tv,
                      EXISTS (SELECT 1 FROM plex_sections
                              WHERE included=1 AND is_anime=1) AS anime
                """).fetchone()
            return {
                "movies": bool(row["movies"]),
                "tv":     bool(row["tv"]),
                "anime":  bool(row["anime"]),
            }
        except Exception as e:  # noqa: BLE001
            # v1.18.73 (HIGH-F audit): pre-fix bare
            # `except Exception: return {all-False}` masked DB
            # connection errors, schema mismatch, plex_sections
            # query failures. Operator would see "no tabs in
            # nav" with no idea why. log.warning so the failure
            # surfaces in docker logs; the all-False fallback
            # still lets the page render (degraded — nav links
            # disappear instead of pointing at empty tabs).
            log.warning(
                "_tab_availability_for_nav: plex_sections query "
                "failed (%s) — falling back to all-False, nav "
                "tabs may disappear until query recovers", e,
            )
            return {"movies": False, "tv": False, "anime": False}

    templates.env.globals["nav_tab_availability"] = _tab_availability_for_nav

    # v1.15.22: SSR state for the topbar chips + page banners — same
    # flash-bug class as v1.15.21 (nav availability), broader sweep.
    # Pre-fix the FAIL / COOKIES / DROP / DISK chips were `hidden`
    # by default in base.html and revealed by JS after /api/stats
    # landed. Same for #dry-run-banner and #paths-banner. Visible
    # flash on every cross-page navigation for any user with
    # un-acked failures / cookies-needed rows / dropped themes /
    # low disk / dry-run-on / paths-unconfigured. Computing at
    # template-render time delivers the right initial visibility +
    # counts; JS continues to update on the next /api/stats poll
    # and is a no-op when SSR matched.
    #
    # NOT included in this pass: the UPD chip (updates_pending SQL
    # is a much larger query with per-section gating + URL-diff —
    # extraction left for a follow-up tag). The op-mini /
    # op-mini-overflow + op-status-idle pills are also JS-driven
    # but those reflect live op state, not steady-state DB counts
    # — different problem shape, JS reveal there is correct.
    def _topbar_ssr_state() -> dict:
        state = {
            "failures_count": 0,
            "cookies_count": 0,
            "drops_count": 0,
            "repush_count": 0,  # v1.24.40: topbar RE-PUSH badge
            "disk_low": False,
            "disk_free_mb": None,
            "dry_run": False,
            "paths_ready": settings.is_paths_ready(),
            # v1.15.55: SSR the op-mini bar so the topbar live-ops
            # status persists across tab navs. Pre-fix the
            # <a class="op-mini" hidden> in base.html stayed
            # hidden until the first ops.js poll landed (~50ms
            # to 1s depending on page-init latency); on every
            # nav to /movies, /tv, /anime, /settings the bar
            # disappeared then reappeared. the user: "Also going
            # to the libraries and settings the status bar
            # flickers and reloads vs dash and logs it appears
            # to stay the whole time I want it to remain
            # consistant on changing to different tabs in
            # motif." JS still owns the live updates — SSR
            # just provides a non-flashing starting frame.
            "op_running": False,
            "op_tone": "tdb",
            "op_label": "",
        }
        try:
            with get_conn(settings.db_path) as conn:
                row = conn.execute(f"""
                    SELECT
                      (SELECT COUNT(*) {_FAILURES_SFA_FROM_SQL}
                       WHERE {_FAILURES_SFA_WHERE_SQL}) AS failures_count,
                      -- v1.15.38: cookies_count uses the broadened
                      -- _COOKIES_PILL_WHERE_SQL (no ack predicates)
                      -- so it matches the v1.15.38 attn_pills=cookies
                      -- filter + the row-level yellow ⚿ pill.
                      (SELECT COUNT(*) {_FAILURES_SFA_FROM_SQL}
                       WHERE {_COOKIES_PILL_WHERE_SQL}) AS cookies_count,
                      -- v1.23.78: library-scope the DROP count (mirror the UPD
                      -- count's plex_items+included join) so a dropped theme for
                      -- a title NOT in your library — the whole TDB catalog is
                      -- mirrored in `themes` — doesn't light an un-findable badge.
                      (SELECT COUNT(*) FROM themes t
                        JOIN plex_items pi ON pi.theme_id = t.id
                        JOIN plex_sections ps
                          ON ps.section_id = pi.section_id AND ps.included = 1
                        WHERE t.tdb_dropped_at IS NOT NULL
                          AND t.upstream_source != 'plex_orphan') AS drops_count,
                      -- v1.24.40: genuinely-dead re-push count for the topbar
                      -- RE-PUSH badge (proactive RP discovery, like FAIL/UPD).
                      ({_REPUSH_COUNT_SQL}) AS repush_count
                """).fetchone()
            state["failures_count"] = int(row["failures_count"] or 0)
            state["cookies_count"] = int(row["cookies_count"] or 0)
            state["drops_count"] = int(row["drops_count"] or 0)
            state["repush_count"] = int(row["repush_count"] or 0)
            # v1.15.55: op-mini SSR — pick the most-recently-
            # updated running/cancelling op_progress row + map
            # kind → tone (mirrors TONE_BY_KIND in ops.js).
            # Label prefers stage_label (the human-readable
            # in-flight phase, e.g. "APPLYING 9717 CHANGED
            # PATHS"); falls back to a kind-based default
            # mirroring KIND_LABEL in ops.js.
            # v1.15.82: priority-ordered picker mirrors ops.js's
            # OP_MINI_PRIORITY so SSR + JS agree on which op the
            # mini-bar shows. Pre-fix updated_at DESC made the bar
            # visibly flip between two concurrent real-running ops
            # — whichever ticked last won. the user: "Let's have
            # download take prio followed by refresh, sync
            # themerrdb, prob url, probe plex sidecar." downloads
            # are a JS-only synth (no op_progress row); SSR can
            # only rank the kinds it sees in op_progress, so a
            # one-tick mismatch can happen on a download+refresh
            # nav (SSR paints refresh; JS swaps to download). The
            # main complaint — steady-state flipping — is fixed.
            # v0.51.46 (the user): tdb_sync now ranks ABOVE plex_enum (was below)
            # so SYNC THEMERRDB holds the slot over a concurrent REFRESH PLEX —
            # kept in lockstep with ops.js OP_MINI_PRIORITY.
            with get_conn(settings.db_path) as conn:
                op_row = conn.execute("""
                    SELECT kind, stage_label
                    FROM op_progress
                    WHERE status IN ('running', 'cancelling')
                    ORDER BY
                      CASE kind
                        WHEN 'tdb_sync'            THEN 1
                        WHEN 'tdb_sync_pending'    THEN 1
                        WHEN 'plex_enum'           THEN 2
                        WHEN 'plex_enum_pending'   THEN 2
                        WHEN 'bulk_probe_tdb'      THEN 3
                        WHEN 'bulk_lps'            THEN 3
                        WHEN 'cloud_themes_backup' THEN 3
                        WHEN 'reprobe_plex_themes' THEN 4
                        WHEN 'tvdb_bridge'         THEN 4
                        ELSE 99
                      END,
                      updated_at DESC
                    LIMIT 1
                """).fetchone()
            if op_row is not None:
                kind = op_row["kind"]
                # v0.50.89: mirror TONE_BY_KIND / KIND_LABEL in ops.js
                # for ALL real op_progress kinds. bulk_lps, tvdb_bridge,
                # and cloud_themes_backup were missing here, so an SSR
                # paint while one of them ran alone showed a generic
                # tone + "…" label until the first ops.js poll landed.
                tone_by_kind = {
                    "tdb_sync": "tdb",
                    "plex_enum": "plex",
                    "reprobe_plex_themes": "plex",
                    "bulk_probe_tdb": "tdb",
                    "bulk_lps": "plex",
                    "tvdb_bridge": "tdb",
                    "cloud_themes_backup": "plex",
                }
                kind_label = {
                    "tdb_sync": "THEMERRDB SYNC",
                    "plex_enum": "PLEX REFRESH",
                    "reprobe_plex_themes": "REPROBE PLEX THEMES",
                    "bulk_probe_tdb": "BULK PROBE TDB",
                    "bulk_lps": "BULK LET PLEX SERVE",
                    "tvdb_bridge": "TVDB BRIDGE",
                    "cloud_themes_backup": "DOWNLOAD PLEX BACKUP",
                }
                state["op_running"] = True
                state["op_tone"] = tone_by_kind.get(kind, "tdb")
                state["op_label"] = (
                    op_row["stage_label"] or kind_label.get(kind, "…")
                )
            state["dry_run"] = is_dry_run(
                settings.db_path, default=settings.dry_run_default)
            disk = _disk_status_for_stats(settings)
            state["disk_low"] = bool(disk and disk.get("low"))
            free = disk.get("free_mb") if disk else None
            state["disk_free_mb"] = int(free) if free is not None else None
        except Exception as e:
            # All defaults remain (counts=0, banners hidden) on any
            # DB / runtime error — JS will recover from /api/stats on
            # the next poll. Same safe-fallback shape as
            # _tab_availability_for_nav.
            # v1.15.34: log the exception at WARNING. Pre-fix the
            # bare `pass` meant DB hiccups during topbar SSR
            # silently hid the FAIL / COOKIES / DISK LOW banners
            # on every page-load with zero operator visibility —
            # the operator only noticed when something went wrong
            # and the banner that should've been screaming was
            # missing.
            log.warning("topbar_ssr_state failed: %s", e)
        return state

    templates.env.globals["topbar_ssr_state"] = _topbar_ssr_state

    # v1.15.45: dashboard-card SSR. v1.15.27's journal flagged
    # ~10 dashboard stat cards still flashing "—" → value on
    # first paint; v1.15.42 + v1.15.44 made several of them
    # clickable, which made the flash more annoying (you see "—"
    # then it becomes a number you want to click). This helper
    # SSR-bakes 11 of the most prominent stat-num values so the
    # first paint shows real numbers. JS polling still runs and
    # overwrites with the live value on the next /api/stats tick
    # (1s TTL cache), idempotent when SSR matched. Mirrors the
    # _topbar_ssr_state shape: safe-fallback dict on any DB error,
    # WARNING log so silent SSR failures don't go unnoticed.
    #
    # NOT included (deferred to a follow-up):
    #   * The 4 COVERAGE footer values (tdb-movies-in-library,
    #     tdb-movies-themed, tdb-tv-in-library, tdb-tv-themed) —
    #     sourced from /api/sections/coverage per-section
    #     aggregates, not /api/stats. Bigger SQL lift.
    #   * INSIGHT charts + SECTION COVERAGE table — those are
    #     JS-rendered SVG/HTML and don't benefit as much from a
    #     pre-baked numeric value.
    def _dashboard_ssr_state() -> dict:
        state = {
            "movies_tdb_total": None,
            "tv_tdb_total": None,
            "queue_pending": None,
            "queue_running": None,
            "queue_failed": None,
            # v0.51.98: hero-button SSR busy states (no ~1s click-flash on
            # nav). Safe default False — a briefly-idle button the poll
            # locks beats a wrongly-disabled one on a DB error.
            "sync_btn_busy": False,
            "refresh_plex_btn_busy": False,
            "placements_today": None,
            "placements_week": None,
            "storage_hardlinks": None,
            "storage_copies": None,
            "storage_wasted_pretty": None,
            "orphans": None,
            # v1.15.50: phase-2 SSR — PLEX MOVIES/TV/ANIME card
            # totals + coverage footer values + the four TDB
            # card foots (tdb-{movies,tv}-{in-library,themed}).
            # the user noticed v1.15.45 left 13 stat slots still
            # showing "—" on first paint while their /api/
            # coverage/plex + /api/sections/coverage fetches
            # were in flight. Phase 2 bakes those values too so
            # the dashboard renders fully-populated on first paint.
            "plex_movies_total": None,
            "plex_movies_with_theme": None,
            "plex_movies_motif_avail": None,
            # v1.23.41: PLEX cards now show ThemerrDB reach (in-TDB vs
            # not-in-TDB) instead of restating the top card's "themed".
            "plex_movies_not_in_tdb": None,
            "plex_tv_total": None,
            "plex_tv_with_theme": None,
            "plex_tv_motif_avail": None,
            "plex_tv_not_in_tdb": None,
            "plex_anime_total": None,
            "plex_anime_with_theme": None,
            "plex_anime_motif_avail": None,
            "plex_anime_not_in_tdb": None,
            # v1.18.20: dashboard collections support. Mirrors the
            # movies/tv/anime card shapes — plex_collections_total
            # is the count of plex_items rows with
            # media_type='collection' under managed sections;
            # with_theme is the count where pi.has_theme=1 (post-
            # upload Plex acknowledges its own theme); motif_avail
            # is the TDB-tracked subset. tdb_collections_* drives
            # the TDB Collections card foot.
            "plex_collections_total": None,
            "plex_collections_with_theme": None,
            "plex_collections_motif_avail": None,
            "plex_collections_not_in_tdb": None,
            "collections_tdb_total": None,
            "tdb_collections_in_library": None,
            "tdb_collections_themed": None,
            # TDB card foots: combines tv+anime per v1.15.47's
            # "TDB doesn't distinguish anime from TV" semantic.
            # "themed" = motif_available AND has_theme (TDB-
            # tracked subset of themed, strictly ≤ in-library).
            "tdb_movies_in_library": None,
            "tdb_movies_themed": None,
            "tdb_tv_in_library": None,
            "tdb_tv_themed": None,
            # v1.23.34: reworked COVERAGE cards. pct/foot are derived
            # from the plex_* aggregates above — these are the "ready
            # to add" (TDB-available, not yet themed) counts + the
            # combined tv+anime totals the TV card now spans.
            "plex_movies_ready": None,
            "plex_tv_ready": None,
            "plex_anime_ready": None,
            "plex_collections_ready": None,
            # v1.15.64: insight-block visibility flags. Each block
            # starts display:none in dashboard.html; JS reveals it
            # once data arrives. Pre-fix every nav showed a brief
            # hidden→visible flash on installs with data. SSR-bake
            # the visibility decision so the block renders correct
            # on first paint.
            "has_insight_failures": False,
            "has_insight_syncs": False,
            "has_insight_downloads": False,
            "has_source_breakdown": False,
        }
        try:
            # SQL predicates here MUST match _stats_sync (above) so
            # the SSR-baked numbers agree with the post-poll /api/stats
            # render. Divergence = visible flicker. Specifically:
            #   * media_type='tv' (NOT 'show' — schema uses 'tv')
            #   * failed gates on acked_at IS NULL (matches /queue's
            #     FAILED chip count)
            #   * orphans counts plex_orphan THEMES (not placement
            #     rows with NULL rating_key)
            #   * storage_wasted_bytes JOINs through local_files.
            #     file_size with the v1.14.36 section_id predicate
            #     to avoid cartesian-product inflation
            #   * tdb_total queries match line 4493 — NO
            #     tdb_dropped_at filter (the /api/stats count
            #     includes dropped rows; matching that keeps SSR
            #     and post-poll in agreement)
            # v1.15.65: single connection for all 3 query groups
            # (was 3 separate `with get_conn` blocks pre-fix). Saves
            # 2 sqlite3.connect calls per dashboard page load —
            # noticeable on a cold-cache base.html SSR where
            # _topbar_ssr_state also opens its own connection.
            with get_conn(settings.db_path) as conn:
                row = conn.execute("""
                    SELECT
                      (SELECT COUNT(*) FROM themes
                        WHERE media_type = 'movie'
                          AND upstream_source IN ('imdb','themoviedb'))
                          AS movies_tdb_total,
                      (SELECT COUNT(*) FROM themes
                        WHERE media_type = 'tv'
                          AND upstream_source IN ('imdb','themoviedb'))
                          AS tv_tdb_total,
                      -- v1.18.20: collections TDB catalog count.
                      -- Mirrors movies/tv: count of themes rows
                      -- the ThemerrDB sync imported under
                      -- media_type='collection' from the
                      -- movie_collections/themoviedb tree.
                      (SELECT COUNT(*) FROM themes
                        WHERE media_type = 'collection'
                          AND upstream_source IN ('imdb','themoviedb'))
                          AS collections_tdb_total,
                      (SELECT COUNT(*) FROM jobs WHERE status='pending')
                          AS queue_pending,
                      (SELECT COUNT(*) FROM jobs WHERE status='running')
                          AS queue_running,
                      (SELECT COUNT(*) FROM jobs
                        WHERE status='failed' AND acked_at IS NULL)
                          AS queue_failed,
                      (SELECT COUNT(*) FROM placements
                        WHERE datetime(placed_at) >= datetime('now', '-1 day'))
                          AS placements_today,
                      (SELECT COUNT(*) FROM placements
                        WHERE datetime(placed_at) >= datetime('now', '-7 day'))
                          AS placements_week,
                      (SELECT COUNT(*) FROM placements
                        WHERE placement_kind='hardlink')
                          AS storage_hardlinks,
                      (SELECT COUNT(*) FROM placements
                        WHERE placement_kind='copy')
                          AS storage_copies,
                      (SELECT COALESCE(SUM(lf.file_size), 0)
                         FROM placements p
                         JOIN local_files lf
                           ON lf.media_type = p.media_type
                          AND lf.tmdb_id = p.tmdb_id
                          AND lf.section_id = p.section_id
                        WHERE p.placement_kind='copy')
                          AS storage_wasted_bytes,
                      (SELECT COUNT(*) FROM themes
                        WHERE upstream_source = 'plex_orphan')
                          AS orphans,
                      -- v0.51.98: two in-flight counts feeding the hero-button
                      -- SSR busy states (derivation below mirrors app.js
                      -- bindDashboard's page-load probe). Pre-fix the buttons
                      -- rendered plain-clickable until the first ~1s poll.
                      (SELECT COUNT(*) FROM jobs
                        WHERE job_type = 'sync'
                          AND status IN ('pending','running'))
                          AS themerrdb_sync_in_flight,
                      (SELECT COUNT(*) FROM jobs
                        WHERE job_type = 'plex_enum'
                          AND status IN ('pending','running'))
                          AS plex_enum_in_flight
                """).fetchone()
                # v1.15.50: phase-2 SSR — plex_items aggregates by
                # section type (movie / non-anime tv / anime). Mirrors
                # the /api/coverage/plex SQL shape (line ~13125): same
                # JOIN through plex_sections WHERE included=1 + LEFT
                # JOIN themes for motif_available + has_theme. Single
                # SELECT with conditional aggregation so SQLite scans
                # plex_items once.
                #
                # motif_available predicate must mirror line 13163-13166
                # (t.tmdb_id IS NOT NULL AND t.upstream_source !=
                # 'plex_orphan') — otherwise SSR-baked numbers
                # disagree with the post-poll render = visible flicker.
                cov = conn.execute("""
                    SELECT
                      -- v1.23.90: movies aggregates gate is_anime=0 so anime-
                      -- section films count on the ANIME card (+ match the
                      -- MOVIES library tab), not here. Partition preserved.
                      SUM(CASE WHEN pi.media_type='movie' AND ps.is_anime=0 THEN 1 ELSE 0 END)
                          AS plex_movies_total,
                      SUM(CASE WHEN pi.media_type='movie' AND ps.is_anime=0 AND pi.has_theme=1 THEN 1 ELSE 0 END)
                          AS plex_movies_with_theme,
                      SUM(CASE WHEN pi.media_type='movie' AND ps.is_anime=0
                                AND t.tmdb_id IS NOT NULL
                                AND t.upstream_source != 'plex_orphan' THEN 1 ELSE 0 END)
                          AS plex_movies_motif_avail,
                      SUM(CASE WHEN pi.media_type='show' AND ps.is_anime=0 THEN 1 ELSE 0 END)
                          AS plex_tv_total,
                      SUM(CASE WHEN pi.media_type='show' AND ps.is_anime=0 AND pi.has_theme=1 THEN 1 ELSE 0 END)
                          AS plex_tv_with_theme,
                      SUM(CASE WHEN pi.media_type='show' AND ps.is_anime=0
                                AND t.tmdb_id IS NOT NULL
                                AND t.upstream_source != 'plex_orphan' THEN 1 ELSE 0 END)
                          AS plex_tv_motif_avail,
                      SUM(CASE WHEN pi.media_type IN ('show', 'movie') AND ps.is_anime=1 THEN 1 ELSE 0 END)
                          AS plex_anime_total,
                      SUM(CASE WHEN pi.media_type IN ('show', 'movie') AND ps.is_anime=1 AND pi.has_theme=1 THEN 1 ELSE 0 END)
                          AS plex_anime_with_theme,
                      SUM(CASE WHEN pi.media_type IN ('show', 'movie') AND ps.is_anime=1
                                AND t.tmdb_id IS NOT NULL
                                AND t.upstream_source != 'plex_orphan' THEN 1 ELSE 0 END)
                          AS plex_anime_motif_avail,
                      -- v1.18.20: collections plex_items aggregates.
                      -- collections don't carry is_anime/is_4k flags
                      -- (they're per-section but section-flag-agnostic
                      -- from a counting POV), so no anime/4K split
                      -- — one card aggregates across every section.
                      SUM(CASE WHEN pi.media_type='collection' THEN 1 ELSE 0 END)
                          AS plex_collections_total,
                      SUM(CASE WHEN pi.media_type='collection' AND pi.has_theme=1 THEN 1 ELSE 0 END)
                          AS plex_collections_with_theme,
                      SUM(CASE WHEN pi.media_type='collection'
                                AND t.tmdb_id IS NOT NULL
                                AND t.upstream_source != 'plex_orphan' THEN 1 ELSE 0 END)
                          AS plex_collections_motif_avail,
                      -- v1.15.47 TDB card foot: themed = motif_avail
                      -- AND has_theme. For TV, combines anime + non-
                      -- anime since TDB doesn't distinguish.
                      SUM(CASE WHEN pi.media_type='movie'
                                AND pi.has_theme=1
                                AND t.tmdb_id IS NOT NULL
                                AND t.upstream_source != 'plex_orphan' THEN 1 ELSE 0 END)
                          AS tdb_movies_themed,
                      SUM(CASE WHEN pi.media_type='show'
                                AND pi.has_theme=1
                                AND t.tmdb_id IS NOT NULL
                                AND t.upstream_source != 'plex_orphan' THEN 1 ELSE 0 END)
                          AS tdb_tv_themed,
                      -- v1.18.20: TDB Collections card foot mirrors
                      -- the movies/tv shape — themed = motif_avail AND
                      -- has_theme for collections.
                      SUM(CASE WHEN pi.media_type='collection'
                                AND pi.has_theme=1
                                AND t.tmdb_id IS NOT NULL
                                AND t.upstream_source != 'plex_orphan' THEN 1 ELSE 0 END)
                          AS tdb_collections_themed,
                      -- v1.23.36: "ready to add" must EXCLUDE rows motif has
                      -- already placed. pi.has_theme is Plex's metadata flag
                      -- and lags a fresh placement, so motif_avail AND
                      -- !has_theme counted rows whose theme.mp3 is already in
                      -- the folder (the user: dash said 16 movies "ready" but 13
                      -- were placed, Plex just hadn't re-scanned). ready =
                      -- TDB-available AND Plex-unthemed AND no motif placement
                      -- — matches the library's "unthemed" (SRC=—) view.
                      -- placements use 'tv' for shows. v1.23.40: TV and ANIME
                      -- are SEPARATE cards now (one per library tab), so TV ready
                      -- gates is_anime=0 and a parallel anime aggregate gates
                      -- is_anime=1 (was one combined show count).
                      SUM(CASE WHEN pi.media_type='movie' AND ps.is_anime=0
                                AND pi.has_theme=0
                                AND t.tmdb_id IS NOT NULL
                                AND t.upstream_source != 'plex_orphan'
                                AND COALESCE(t.failure_kind, '') NOT IN
                                    ('video_private', 'video_removed',
                                     'video_age_restricted', 'geo_blocked')
                                -- v0.51.95: scope the placed-check to THIS edition
                                -- (mirror /api/coverage/plex's `placed` EXISTS) — a
                                -- placement on ONE edition otherwise made every sibling
                                -- edition of the same title+section read "not ready", so
                                -- the SSR count undershot the coverage page + the library's
                                -- per-row unthemed (SRC=—) view for multi-edition titles.
                                AND NOT EXISTS (SELECT 1 FROM placements p
                                                WHERE p.media_type='movie'
                                                  AND p.tmdb_id=t.tmdb_id
                                                  AND p.section_id=pi.section_id
                                                  AND p.edition_key=pi.edition_key)
                               THEN 1 ELSE 0 END)
                          AS plex_movies_ready,
                      SUM(CASE WHEN pi.media_type='show' AND ps.is_anime=0
                                AND pi.has_theme=0
                                AND t.tmdb_id IS NOT NULL
                                AND t.upstream_source != 'plex_orphan'
                                AND COALESCE(t.failure_kind, '') NOT IN
                                    ('video_private', 'video_removed',
                                     'video_age_restricted', 'geo_blocked')
                                AND NOT EXISTS (SELECT 1 FROM placements p
                                                WHERE p.media_type='tv'
                                                  AND p.tmdb_id=t.tmdb_id
                                                  AND p.section_id=pi.section_id
                                                  AND p.edition_key=pi.edition_key)  -- v0.51.95: per-edition (see plex_movies_ready)
                               THEN 1 ELSE 0 END)
                          AS plex_tv_ready,
                      SUM(CASE WHEN pi.media_type IN ('show', 'movie') AND ps.is_anime=1
                                AND pi.has_theme=0
                                AND t.tmdb_id IS NOT NULL
                                AND t.upstream_source != 'plex_orphan'
                                AND COALESCE(t.failure_kind, '') NOT IN
                                    ('video_private', 'video_removed',
                                     'video_age_restricted', 'geo_blocked')
                                AND NOT EXISTS (SELECT 1 FROM placements p
                                                WHERE p.media_type = CASE WHEN pi.media_type='movie'
                                                                          THEN 'movie' ELSE 'tv' END
                                                  AND p.tmdb_id=t.tmdb_id
                                                  AND p.section_id=pi.section_id
                                                  AND p.edition_key=pi.edition_key)  -- v0.51.95: per-edition (see plex_movies_ready)
                               THEN 1 ELSE 0 END)
                          AS plex_anime_ready,
                      SUM(CASE WHEN pi.media_type='collection' AND pi.has_theme=0
                                AND t.tmdb_id IS NOT NULL
                                AND t.upstream_source != 'plex_orphan'
                                AND COALESCE(t.failure_kind, '') NOT IN
                                    ('video_private', 'video_removed',
                                     'video_age_restricted', 'geo_blocked')
                                AND NOT EXISTS (SELECT 1 FROM placements p
                                                WHERE p.media_type='collection'
                                                  AND p.tmdb_id=t.tmdb_id
                                                  AND p.section_id=pi.section_id
                                                  AND p.edition_key=pi.edition_key)  -- v0.51.95: per-edition (see plex_movies_ready)
                               THEN 1 ELSE 0 END)
                          AS plex_collections_ready
                    FROM plex_items pi
                    INNER JOIN plex_sections ps
                      ON ps.section_id = pi.section_id AND ps.included = 1
                    LEFT JOIN themes t ON t.id = pi.theme_id
                """).fetchone()
                # v1.15.65: insight-block visibility predicates. Tightened
                # vs v1.15.64's EXISTS-only check to mirror the JS gate
                # exactly so post-paint reveal/hide can't disagree with
                # SSR. Mirror-principle drift class P:
                #
                # * has_insight_failures: uses _FAILURES_SFA_* (the same
                #   FROM + WHERE that drives the failure_kinds chart's
                #   GROUP BY). A theme with failure_kind unacked but the
                #   section sfa-acked would have tripped a naive EXISTS
                #   check while the chart returns zero rows → JS hides
                #   block post-paint = visible flash.
                # * has_insight_syncs: JS gates `rows.length < 2` so we
                #   need >= 2 sync_runs with finished_at IS NOT NULL.
                #   Subquery LIMIT 2 caps the scan cost.
                # * has_insight_downloads: JS gates on >= 1 row but
                #   per-day-bucket; need >= 1 distinct DATE in the 30-
                #   day window. Subquery LIMIT 1 short-circuits.
                # * has_source_breakdown: EXISTS (plex_items) is fine —
                #   the JS gate hides only when grand <= 0, which
                #   essentially requires zero plex_items.
                vis = conn.execute(f"""
                    SELECT
                      EXISTS (SELECT 1 {_FAILURES_SFA_FROM_SQL}
                              WHERE {_FAILURES_SFA_WHERE_SQL})
                          AS has_insight_failures,
                      (SELECT COUNT(*) FROM (
                          SELECT 1 FROM sync_runs
                          WHERE finished_at IS NOT NULL
                          LIMIT 2)) >= 2
                          AS has_insight_syncs,
                      EXISTS (SELECT 1 FROM jobs
                              WHERE job_type = 'download'
                                AND datetime(created_at) >= datetime('now', '-30 days'))
                          AS has_insight_downloads,
                      EXISTS (SELECT 1 FROM plex_items)
                          AS has_source_breakdown
                """).fetchone()
            state["movies_tdb_total"] = int(row["movies_tdb_total"] or 0)
            state["tv_tdb_total"] = int(row["tv_tdb_total"] or 0)
            # v1.18.20: collection TDB catalog size.
            state["collections_tdb_total"] = int(row["collections_tdb_total"] or 0)
            state["queue_pending"] = int(row["queue_pending"] or 0)
            state["queue_running"] = int(row["queue_running"] or 0)
            state["queue_failed"] = int(row["queue_failed"] or 0)
            state["placements_today"] = int(row["placements_today"] or 0)
            state["placements_week"] = int(row["placements_week"] or 0)
            state["storage_hardlinks"] = int(row["storage_hardlinks"] or 0)
            state["storage_copies"] = int(row["storage_copies"] or 0)
            state["orphans"] = int(row["orphans"] or 0)
            # v0.51.98: SYNC lock mirrors app.js bindDashboard's page-load
            # probe EXACTLY — `initialBusy = autoEnum ? (tdb+enum) : tdb` —
            # since that probe arms the sync watcher on nav and a live
            # watcher blocks refreshTopbarStatus's unlock, so it (not the
            # cascade-only steady-state predicate) governs the settled
            # first-view. auto_enum OFF (both buttons visible) → the two agree.
            _tdb_if = int(row["themerrdb_sync_in_flight"] or 0)
            _enum_if = int(row["plex_enum_in_flight"] or 0)
            _auto_enum = bool(settings.sync_auto_enum_after_sync)
            state["sync_btn_busy"] = (_tdb_if > 0) or (_auto_enum and _enum_if > 0)
            state["refresh_plex_btn_busy"] = _enum_if > 0
            # Mirror fmtBytes() in app.js so SSR + JS post-poll
            # agree on the formatted string and there's no
            # "1234567 → 1.2 MB" textual flash.
            n = int(row["storage_wasted_bytes"] or 0)
            units = ["B", "KB", "MB", "GB", "TB"]
            i = 0
            v = float(n)
            while v >= 1024 and i < len(units) - 1:
                v /= 1024
                i += 1
            if n == 0:
                state["storage_wasted_pretty"] = "0 B"
            else:
                digits = 0 if v >= 100 else 1 if v >= 10 else 2
                state["storage_wasted_pretty"] = f"{v:.{digits}f} {units[i]}"
            state["plex_movies_total"] = int(cov["plex_movies_total"] or 0)
            state["plex_movies_with_theme"] = int(cov["plex_movies_with_theme"] or 0)
            state["plex_movies_motif_avail"] = int(cov["plex_movies_motif_avail"] or 0)
            # v1.23.41: not-in-TDB = library total minus the TDB-tracked
            # subset (the PLEX-card reach foot). max(0, …) guards any
            # transient over-count where motif_avail briefly exceeds total.
            state["plex_movies_not_in_tdb"] = max(
                0, state["plex_movies_total"] - state["plex_movies_motif_avail"])
            state["plex_tv_total"] = int(cov["plex_tv_total"] or 0)
            state["plex_tv_with_theme"] = int(cov["plex_tv_with_theme"] or 0)
            state["plex_tv_motif_avail"] = int(cov["plex_tv_motif_avail"] or 0)
            state["plex_tv_not_in_tdb"] = max(
                0, state["plex_tv_total"] - state["plex_tv_motif_avail"])
            state["plex_anime_total"] = int(cov["plex_anime_total"] or 0)
            state["plex_anime_with_theme"] = int(cov["plex_anime_with_theme"] or 0)
            state["plex_anime_motif_avail"] = int(cov["plex_anime_motif_avail"] or 0)
            state["plex_anime_not_in_tdb"] = max(
                0, state["plex_anime_total"] - state["plex_anime_motif_avail"])
            # v1.18.20: Plex Collections card aggregates +
            # TDB Collections card foot.
            state["plex_collections_total"] = int(cov["plex_collections_total"] or 0)
            state["plex_collections_with_theme"] = int(cov["plex_collections_with_theme"] or 0)
            state["plex_collections_motif_avail"] = int(cov["plex_collections_motif_avail"] or 0)
            state["plex_collections_not_in_tdb"] = max(
                0, state["plex_collections_total"] - state["plex_collections_motif_avail"])
            state["tdb_collections_in_library"] = state["plex_collections_motif_avail"]
            state["tdb_collections_themed"] = int(cov["tdb_collections_themed"] or 0)
            # TDB card foots: in-library = motif_available count
            # (TV combines tv+anime per v1.15.47); themed = the
            # TDB-tracked subset of themed (strict subset of
            # in-library by construction).
            state["tdb_movies_in_library"] = state["plex_movies_motif_avail"]
            state["tdb_movies_themed"] = int(cov["tdb_movies_themed"] or 0)
            state["tdb_tv_in_library"] = (
                state["plex_tv_motif_avail"] + state["plex_anime_motif_avail"]
            )
            state["tdb_tv_themed"] = int(cov["tdb_tv_themed"] or 0)
            # v1.23.34/36: reworked COVERAGE cards; "ready to add" reads the
            # placement-aware aggregate (TDB-available AND Plex-unthemed AND not
            # placed AND not dead-URL). v1.23.40: TV and ANIME are SEPARATE cards
            # now (one per library tab) — TV ready gates is_anime=0, anime ready
            # is_anime=1; the old combined tv+anime totals are retired.
            state["plex_movies_ready"] = int(cov["plex_movies_ready"] or 0)
            state["plex_tv_ready"] = int(cov["plex_tv_ready"] or 0)
            state["plex_anime_ready"] = int(cov["plex_anime_ready"] or 0)
            state["plex_collections_ready"] = int(cov["plex_collections_ready"] or 0)
            state["has_insight_failures"] = bool(vis["has_insight_failures"])
            state["has_insight_syncs"] = bool(vis["has_insight_syncs"])
            state["has_insight_downloads"] = bool(vis["has_insight_downloads"])
            state["has_source_breakdown"] = bool(vis["has_source_breakdown"])
        except Exception as e:
            # All defaults remain (None → template renders "—") on
            # any DB / runtime error. Matches _topbar_ssr_state's
            # safe-fallback contract — JS recovers from /api/stats
            # on the next poll, so a one-tick "—" flash on SSR
            # failure beats a 500 on /.
            log.warning("dashboard_ssr_state failed: %s", e)
        return state

    templates.env.globals["dashboard_ssr_state"] = _dashboard_ssr_state

    # v1.15.24: hide the SECTION INCLUDE / SECTION EXCLUDE inputs
    # in Settings → PLEX → LIBRARY SCOPE unless an env override is
    # actually active. the user: "whats the point to these since
    # they're set in the libraries section below?" — for an
    # interactive operator who's already enumerated their sections
    # and toggled MGD per-section, the comma-separated text fields
    # are dead UI (sections.py:177 explicitly notes the env-var
    # rules apply only on FIRST DISCOVERY of a section). Their
    # remaining purpose is surfacing the corresponding env vars
    # (MOTIF_PLEX_SECTION_INCLUDE / _EXCLUDE) so headless
    # deploys can see "yes, this env var is locking my scope".
    # Auto-hide preserves that visibility for env-driven users
    # while removing the noise for everyone else.
    def _library_scope_inputs_visible() -> bool:
        try:
            overrides = settings.env_overrides()
            return ("plex.section_include" in overrides
                    or "plex.section_exclude" in overrides)
        except Exception:
            return False

    templates.env.globals["library_scope_inputs_visible"] = _library_scope_inputs_visible

    # v1.15.25: SSR env-override badges in settings.html. Pre-fix
    # every // ENV OVERRIDE chip carried `style="display:none"`
    # and JS revealed it after /api/config landed (~50-200ms post-
    # paint). For env-heavy deploys (the user's startup log shows 8
    # env overrides active) the chips visibly flickered into view
    # on every /settings load. Same flash class as v1.15.21/22 nav
    # + topbar fixes. The dict shape matches what settings.env_
    # overrides() returns: {dotted.path: ENV_VAR_NAME}; templates
    # check key presence.
    def _env_overrides_for_template() -> dict:
        try:
            return settings.env_overrides()
        except Exception:
            return {}

    templates.env.globals["env_overrides"] = _env_overrides_for_template

    # v1.15.25: SSR the library page's STANDARD/4K resolution
    # toggle. Pre-fix the chip set was hardcoded `style="display:
    # none"` in library.html and adaptLibraryFourkToggle revealed
    # it after /api/stats landed — flash on every library page
    # navigation. This helper returns per-variant existence flags
    # for a given tab; the template uses Jinja conditionals to
    # hide-when-neither-variant-exists + hide-individual-chip-
    # when-that-variant-doesn't-exist + mark the chip-active
    # class on the variant matching the ?fourk URL param.
    def _library_resolution_state(tab: str) -> dict:
        try:
            with get_conn(settings.db_path) as conn:
                if tab == "anime":
                    row = conn.execute("""
                        SELECT
                          EXISTS (SELECT 1 FROM plex_sections
                                  WHERE included=1 AND is_anime=1 AND is_4k=0) AS std,
                          EXISTS (SELECT 1 FROM plex_sections
                                  WHERE included=1 AND is_anime=1 AND is_4k=1) AS fourk
                    """).fetchone()
                else:
                    plex_type = "show" if tab == "tv" else "movie"
                    row = conn.execute(
                        "SELECT EXISTS (SELECT 1 FROM plex_sections "
                        "WHERE included=1 AND type=? AND is_anime=0 AND is_4k=0) AS std, "
                        "EXISTS (SELECT 1 FROM plex_sections "
                        "WHERE included=1 AND type=? AND is_anime=0 AND is_4k=1) AS fourk",
                        (plex_type, plex_type),
                    ).fetchone()
            return {
                "has_standard": bool(row["std"]),
                "has_fourk": bool(row["fourk"]),
                "show_chips": bool(row["std"]) or bool(row["fourk"]),
                # v0.51.21: the // ALL chip is only meaningful when BOTH a
                # standard and a 4K section exist — otherwise "combined" is
                # identical to the single section that does exist.
                "has_both": bool(row["std"]) and bool(row["fourk"]),
            }
        except Exception as e:
            # v1.15.35: log at WARNING. Pre-fix bare `except:` hid
            # DB hiccups during library-resolution-state lookup —
            # the 4K / Standard chips would silently disappear on
            # every page-load with zero operator visibility.
            log.warning("library_resolution_state(%s) failed: %s", tab, e)
            return {"has_standard": False, "has_fourk": False,
                    "show_chips": False, "has_both": False}

    templates.env.globals["library_resolution_state"] = _library_resolution_state

    def _library_section_state(tab: str) -> dict:
        """v1.18.1: per-section chip list for the /collections tab.

        Plex collections span every managed section (Movies, 4K
        Movies, TV Shows, 4K TV Shows, Anime, Anime 4K, etc.) — the
        binary STANDARD/4K toggle is meaningless for them. Instead
        the /collections page renders one chip per managed section
        so the user can scope to "show me Movies collections only"
        or "TV Shows collections only," etc.

        Returns:
          {
            "show_chips": bool,         # show the section row at all?
            "sections": [               # ordered chip list
              {"section_id": "1", "label": "Movies"},
              {"section_id": "5", "label": "4K Movies"},
              ...
            ],
          }

        Only invoked when tab='collections' — other tabs use the
        v1.10.5 STANDARD/4K resolution chips via
        _library_resolution_state.
        """
        if tab != "collections":
            return {"show_chips": False, "sections": []}
        try:
            with get_conn(settings.db_path) as conn:
                # v1.18.1: only show sections that actually have at
                # least one collection enumerated — sections without
                # collections (e.g. Music libraries, or fresh installs
                # before the first plex_enum collections-pass) would
                # produce a chip that returns 0 rows.
                rows = conn.execute("""
                    SELECT ps.section_id, ps.title, ps.type, ps.is_4k, ps.is_anime
                      FROM plex_sections ps
                      WHERE ps.included = 1
                        AND EXISTS (
                          SELECT 1 FROM plex_items pi
                          WHERE pi.section_id = ps.section_id
                            AND pi.media_type = 'collection'
                        )
                      ORDER BY ps.is_anime ASC,
                               ps.type ASC,
                               ps.is_4k ASC,
                               ps.title ASC
                """).fetchall()
            sections = [
                {
                    "section_id": str(r["section_id"]),
                    "label": (r["title"] or f"section {r['section_id']}"),
                }
                for r in rows
            ]
            return {
                "show_chips": len(sections) > 0,
                "sections": sections,
            }
        except Exception as e:
            log.warning("library_section_state(%s) failed: %s", tab, e)
            return {"show_chips": False, "sections": []}

    templates.env.globals["library_section_state"] = _library_section_state

    app.add_middleware(AuthMiddleware, settings=settings)

    # v1.21.17 (security audit): set baseline security response headers on
    # every response. Deliberately conservative — these can't break a legit
    # request: nosniff (stop MIME-sniffing), no-referrer (also closes the
    # ?api_key= referer-leak path, since API tokens can ride the query
    # string), a restrictive Permissions-Policy for features motif never
    # uses, and HSTS ONLY when the request is already HTTPS (so a plain-HTTP
    # LAN box isn't pinned to a scheme it can't serve). NOT set here:
    # Content-Security-Policy + X-Frame-Options — deferred, because a strict
    # CSP needs the 2 inline-script templates nonced (can't live-test
    # headlessly) and anti-framing would break a cross-origin dashboard
    # embed. setdefault() lets a specific endpoint override if it ever needs to.
    @app.middleware("http")
    async def _security_headers(request: Request, call_next):
        resp = await call_next(request)
        resp.headers.setdefault("X-Content-Type-Options", "nosniff")
        resp.headers.setdefault("Referrer-Policy", "no-referrer")
        resp.headers.setdefault(
            "Permissions-Policy",
            "geolocation=(), camera=(), microphone=(), payment=(), usb=()",
        )
        proto = (request.headers.get("x-forwarded-proto", "").lower()
                 or request.url.scheme)
        if proto == "https":
            resp.headers.setdefault(
                "Strict-Transport-Security",
                "max-age=63072000; includeSubDomains",
            )
        return resp

    def get_db_path() -> Path:
        return settings.db_path

    # --- HTML routes ---

    @app.get("/", response_class=HTMLResponse)
    async def dashboard(request: Request):
        # v1.13.63: surface auto_enum_after_sync to the template so
        # the dash hero conditionally renders a // SYNC PLEX button
        # when the user has opted out of the post-sync enum cascade.
        # When auto_enum_after_sync is true, // SYNC THEMERRDB
        # already triggers a global Plex enum behind it; the extra
        # button would be redundant.
        return templates.TemplateResponse(request, "dashboard.html", {
            "auto_enum_after_sync": bool(settings.sync_auto_enum_after_sync),
        })

    # v1.13.69: peek at ?fourk= on the URL so the template can
    # pre-render the // SYNC <NAME> button with the correct scope-
    # aware label. Pre-fix the static template carried `// SYNC`
    # and JS swapped to `// SYNC <NAME>` after the first
    # refreshTopbarStatus tick — visible flicker on every navigate.
    # When the URL carries fourk explicitly (FAIL-pill click,
    # bookmark, deep-link), this eliminates the flicker. The
    # localStorage-driven flip (no fourk in URL but persisted
    # variant says 4K) still produces a brief mismatch, but that
    # path is rarer and the flicker is shorter-lived since JS
    # reads localStorage synchronously on init.
    def _fourk_from_query(request: Request) -> bool:
        v = (request.query_params.get("fourk") or "").lower()
        return v in ("true", "1", "yes")

    def _all_res_from_query(request: Request) -> bool:
        # v0.51.21: the // ALL resolution/section chip. Threaded into the
        # library template for the SSR chip-active state so the first paint
        # matches the URL (JS hydrateLibraryStateForTab keeps it in sync).
        v = (request.query_params.get("all_res") or "").lower()
        return v in ("true", "1", "yes")

    def _default_all_res(request: Request, tab: str) -> bool:
        # v0.51.22 (the user: "lets make all be the default"): // ALL is now
        # the DEFAULT view whenever it's available — both a standard AND a 4K
        # section (movies/tv/anime) or ≥2 collection sections. An explicit
        # ?all_res=/?fourk=/?section_id= in the URL still wins (deep-links,
        # bookmarks, the topbar badges that carry ?fourk=). This is the SSR
        # first-paint state; the JS hydration applies the same rule and lets a
        # persisted per-tab choice (localStorage) override for return visits.
        qp = request.query_params
        if "all_res" in qp:
            return _all_res_from_query(request)
        if tab == "collections":
            if qp.get("section_id"):
                return False  # explicit section pick
            return len(_library_section_state(tab).get("sections", [])) > 1
        if "fourk" in qp:
            return False  # explicit STANDARD / 4K pick
        return bool(_library_resolution_state(tab).get("has_both"))

    def _pipeline_in_flight(db: Path) -> bool:
        """v1.13.77: true when ANY scope-tagged plex_enum job is
        pending or running (cascade or scan_all). Threaded into the
        library template so the // REFRESH <NAME> button starts
        disabled on initial paint when a global refresh is already
        in flight — closes the gap where a user clicked dashboard
        // REFRESH PLEX and then navigated to /movies before the
        first /api/stats poll could lock the per-tab button.
        Cheap single-row count; same predicate the SQL in /api/stats
        uses for plex_enum_pipeline_in_flight."""
        try:
            with get_conn(db) as conn:
                row = conn.execute(
                    "SELECT COUNT(*) AS n FROM jobs "
                    "WHERE job_type = 'plex_enum' "
                    "  AND status IN ('pending','running') "
                    "  AND json_extract(payload, '$.scope') "
                    "      IN ('cascade','scan_all')"
                ).fetchone()
                return bool(row and row["n"])
        except Exception as e:
            # v1.15.35: log at WARNING. Pre-fix bare `except:`
            # silently returned False — operator could see a
            # clickable // REFRESH <NAME> button when one was
            # actually in flight, which would queue duplicate
            # jobs. Surfacing the failure lets the operator
            # correlate "duplicate refresh" reports with the
            # underlying DB error.
            log.warning("_pipeline_in_flight failed: %s", e)
            return False

    def _lib_refresh_in_flight(db: Path, tab: str, fourk: bool) -> bool:
        """v0.51.100: full SSR mirror of app.js
        `libRefreshBusy = myTabBusy || globalEnumPipeline` so the
        // REFRESH <NAME> button paints locked on a nav while ITS enum is in
        flight. _pipeline_in_flight (v1.13.77) only covered the cascade/scan_all
        pipeline term — a per-tab scope=<tab> refresh, or the pre-cascade
        tdb-sync phase, slipped through and flashed clickable for ~1s until the
        first refreshTopbarStatus poll locked it. Predicates mirror /api/stats:
        section→(tab,variant) via ps.is_anime/type/is_4k (api.py:8817)."""
        # globalEnumPipeline term 1: cascade / scan_all pipeline (v1.13.77).
        if _pipeline_in_flight(db):
            return True
        try:
            with get_conn(db) as conn:
                # term 2: a tdb sync running with auto_enum on guarantees a
                # cascade plex_enum follows — lock every tab through the sync.
                if settings.sync_auto_enum_after_sync:
                    r = conn.execute(
                        "SELECT COUNT(*) AS n FROM jobs WHERE job_type='sync' "
                        "AND status IN ('pending','running')").fetchone()
                    if r and r["n"]:
                        return True
                # term 3: ≥2 movie/tv/anime tabs with a RUNNING enum
                # (running-only, mirroring enumActive → enumTabsActive > 1).
                running = conn.execute(
                    "SELECT DISTINCT ps.type, ps.is_anime FROM jobs j "
                    "INNER JOIN plex_sections ps "
                    "  ON ps.section_id = json_extract(j.payload, '$.section_id') "
                    "WHERE j.job_type='plex_enum' AND j.status='running'"
                ).fetchall()
                tabs = set()
                for r in running:
                    tabs.add("anime" if r["is_anime"]
                             else ("movies" if r["type"] == "movie" else "tv"))
                if len(tabs) > 1:
                    return True
                # myTabBusy: collections lock on the collections-scoped enum;
                # movies/tv/anime lock on THIS tab+variant's own enum
                # (running OR pending — v1.14.73 same-tab pending awareness).
                if tab == "collections":
                    r = conn.execute(
                        "SELECT COUNT(*) AS n FROM jobs "
                        "WHERE job_type='plex_enum' "
                        "AND status IN ('pending','running') "
                        "AND json_extract(payload, '$.scope')='collections'"
                    ).fetchone()
                    return bool(r and r["n"])
                if tab == "movies":
                    tab_pred = "ps.is_anime=0 AND ps.type='movie'"
                elif tab == "anime":
                    tab_pred = "ps.is_anime=1"
                else:  # tv
                    tab_pred = "ps.is_anime=0 AND ps.type!='movie'"
                r = conn.execute(
                    "SELECT COUNT(*) AS n FROM jobs j "
                    "INNER JOIN plex_sections ps "
                    "  ON ps.section_id = json_extract(j.payload, '$.section_id') "
                    "WHERE j.job_type='plex_enum' "
                    "  AND j.status IN ('pending','running') "
                    f"  AND {tab_pred} AND ps.is_4k = ?",
                    (1 if fourk else 0,)).fetchone()
                return bool(r and r["n"])
        except Exception as e:
            # Same safe-fallback shape as _pipeline_in_flight: on any DB error
            # render the button clickable (the first poll re-locks it) rather
            # than wrongly-disabled, and log so duplicate-refresh reports
            # correlate with the underlying failure.
            log.warning("_lib_refresh_in_flight failed: %s", e)
            return False

