    @app.get("/queue", response_class=HTMLResponse)
    async def queue_page(request: Request):
        # v1.22.56: the LOGS page now toggles between JOBS and EVENT
        # STREAM (one full-width panel at a time) instead of the
        # side-by-side split. SSR the initial panel from the deep-link
        # params so dashboard links land on the right view with no
        # one-frame flash (mirrors the settings data-settings-tab SSR):
        #   ?status=… (OPERATIONS cards)            -> jobs
        #   ?since=… / ?level=… / ?component=…      -> events
        #   (none)                                   -> jobs
        qp = request.query_params
        # v0.50.72: explicit ?view=events deep-link (the dashboard Recent Activity
        # "// all events →" link) — pre-fix it hit bare /queue and landed on JOBS,
        # not the Events Log the label promises (the user).
        if qp.get("view") == "events":
            initial_logview = "events"
        elif qp.get("view") == "jobs":
            initial_logview = "jobs"
        elif "status" in qp:
            initial_logview = "jobs"
        elif "since" in qp or "level" in qp or "component" in qp:
            initial_logview = "events"
        else:
            initial_logview = "jobs"
        # v1.22.89: SSR the jobs FILTER chip too — the panel choice was
        # SSR'd in v1.22.56 but ?status=failed deep-links still painted
        # the hardcoded ALL chip active until the JS consumer flipped
        # it (the same one-frame-flash class). Allowlist mirrors the
        # app.js bindQueue initialStatus check.
        _status = qp.get("status", "")
        initial_jobfilter = (
            _status if _status in
            ("pending", "running", "failed", "cancelled", "done")
            else "all"
        )
        return templates.TemplateResponse(
            request, "queue.html", {
                "initial_logview": initial_logview,
                "initial_jobfilter": initial_jobfilter,
            })

