    @app.post("/api/admin/delete-orphan-sidecar")
    async def api_admin_delete_orphan_sidecar(
        request: Request,
        media_type: MediaType = Query(...),
        tmdb_id: int = Query(...),
        section_id: str = Query(...),
        db: Path = Depends(get_db_path),
    ):
        """v1.18.43: targeted deletion of orphan theme.<ext>
        sidecars at Plex media folders. Wired to the orphan
        dashboard's DELETE SIDECAR button for rows classified
        as `orphan_sidecar_on_disk`.

        Looks up the row's plex_items.folder_path, walks the
        host→container path candidates via
        `find_theme_sidecar_path`, and unlinks the file if
        found. Read-only DB — only touches the filesystem.

        Targets the same drift surface as the orphan scanner:
        plex_upload placements with a leftover theme.<ext>
        from pre-v1.18.36 SWITCH file→api operations.
        """
        _require_admin(request)
        with get_conn(db) as conn:
            # Re-derive folder_path from plex_items rather than
            # trusting a client-supplied path (defense-in-depth
            # against a malformed bookmark targeting the wrong
            # file).
            tid_row = conn.execute(
                "SELECT id FROM themes "
                "WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            tid_pk = tid_row["id"] if tid_row else None
            plex_mt = (
                "show" if media_type == "tv"
                else ("collection" if media_type == "collection"
                      else "movie")
            )
            row = None
            if tid_pk is not None:
                row = conn.execute(
                    "SELECT folder_path FROM plex_items "
                    "WHERE theme_id = ? AND section_id = ?",
                    (tid_pk, section_id),
                ).fetchone()
            if row is None:
                row = conn.execute(
                    "SELECT folder_path FROM plex_items "
                    "WHERE guid_tmdb = ? AND media_type = ? "
                    "  AND section_id = ?",
                    (str(tmdb_id), plex_mt, section_id),
                ).fetchone()
        if row is None or not row["folder_path"]:
            raise HTTPException(
                status_code=404,
                detail="no plex_items.folder_path for this row",
            )
        from ..core.plex_enum import find_theme_sidecar_path
        # v1.24.13 (holistic review): offload the sidecar SCAN too. v1.23.96
        # offloaded the unlink below but left this multi-candidate /data
        # directory walk on the event loop — the more expensive of the two.
        sp = await run_in_threadpool(find_theme_sidecar_path, row["folder_path"])
        if sp is None:
            return {
                "ok": True,
                "deleted": False,
                "reason": "no sidecar found at folder",
                "folder_path": row["folder_path"],
            }
        try:
            # v1.23.96 (audit): offload the unlink — it hits the /data mount and
            # was blocking the event loop directly in the async handler body.
            await run_in_threadpool(sp.unlink)
        except OSError as e:
            raise HTTPException(
                status_code=500,
                detail=f"unlink failed: {e}",
            )
        log.info(
            "delete_orphan_sidecar: removed %s for %s/%s "
            "section_id=%s",
            sp, media_type, tmdb_id, section_id,
        )
        return {
            "ok": True,
            "deleted": True,
            "path": str(sp),
            "folder_path": row["folder_path"],
        }

