    @app.post("/setup")
    async def setup_post(
        request: Request,
        username: Annotated[str, Form()],
        password: Annotated[str, Form()],
        password_confirm: Annotated[str, Form()],
    ):
        if setup_complete(settings.db_path):
            return RedirectResponse("/", status_code=302)
        try:
            if password != password_confirm:
                raise ValueError("Passwords do not match")
            create_admin(settings.db_path, username=username, password=password)
        except (ValueError, RuntimeError) as e:
            return templates.TemplateResponse(
                request, "setup.html", {"error": str(e)}, status_code=400,
            )
        # Auto-login
        sid = create_session(
            settings.db_path, username=username,
            user_agent=request.headers.get("User-Agent"),
        )
        log_event(settings.db_path, level="INFO", component="auth",
                  message=f"Initial admin '{username}' created and logged in")
        resp = RedirectResponse("/", status_code=302)
        _set_session_cookie(resp, sid, request)
        return resp

    @app.get("/login", response_class=HTMLResponse)
    async def login_get(request: Request, next: str = "/"):
        # v1.15.37: validate `next` BEFORE feeding it to RedirectResponse
        # to close an open-redirect vector. Pre-fix `RedirectResponse(next)`
        # accepted `//attacker.com` (browser interprets as a protocol-
        # relative URL → cross-origin redirect). Mirrors the validation
        # already present in the POST handler at the bottom of this
        # block: must start with "/" AND not "//". Falls back to "/"
        # on anything else. Also passes the SANITIZED value through to
        # the template so a hostile crafted link can't survive a
        # round-trip through the form.
        safe_next = (
            next if (next and next.startswith("/")
                     and not next.startswith("//"))
            else "/"
        )
        # v0.51.78 (security audit): removed the `if settings.trust_forward_auth:
        # redirect` — it bounced EVERY visitor away from the login page when
        # forward-auth was merely ENABLED, but AuthMiddleware only trusts the header
        # when forward_auth_allowed_ips is set AND the IP matches (v1.24.12 fail-
        # closed). Flipping trust on WITHOUT the allowlist → anonymous → GET /login
        # → RedirectResponse('/') → (anonymous on non-public '/') → back to /login:
        # an infinite loop that locked the operator out of the local-login fallback.
        # The is_authenticated check below is the correct gate — the middleware always
        # resolves the principal (see dispatch()), so a genuinely forward-authed
        # visitor is already is_authenticated=True and is redirected home here, while
        # everyone else correctly sees the local login form.
        if request.state.principal.is_authenticated:
            return RedirectResponse(safe_next, status_code=302)
        return templates.TemplateResponse(
            request, "login.html",
            {"error": None, "next": safe_next},
        )

    @app.post("/login")
    async def login_post(
        request: Request,
        username: Annotated[str, Form()],
        password: Annotated[str, Form()],
        next: Annotated[str, Form()] = "/",
    ):
        # v1.21.18 (security audit): per-IP brute-force throttle. After
        # LOGIN_MAX_FAILURES failures in the rolling window, refuse with 429
        # WITHOUT checking the password until they age out.
        client_ip = request.client.host if request.client else ""
        if login_rate_limited(client_ip):
            log_event(settings.db_path, level="WARNING", component="auth",
                      message="Login throttled — too many failed attempts")
            return templates.TemplateResponse(
                request, "login.html",
                {"error": "Too many attempts. Try again later.",
                 "next": next or "/"},
                status_code=429,
            )
        ok = authenticate_password(
            settings.db_path, username=username, password=password,
        )
        if not ok:
            record_login_failure(client_ip)
            log_event(settings.db_path, level="WARNING", component="auth",
                      message=f"Failed login attempt for '{username}'")
            return templates.TemplateResponse(
                request, "login.html",
                {"error": "Invalid username or password", "next": next or "/"},
                status_code=401,
            )
        clear_login_failures(client_ip)
        sid = create_session(
            settings.db_path, username=username,
            user_agent=request.headers.get("User-Agent"),
        )
        log_event(settings.db_path, level="INFO", component="auth",
                  message=f"User '{username}' logged in")
        # Validate `next` to avoid open-redirect — must be a same-origin path
        target = next if (next and next.startswith("/") and not next.startswith("//")) else "/"
        resp = RedirectResponse(target, status_code=302)
        _set_session_cookie(resp, sid, request)
        return resp

    @app.post("/logout")
    @app.get("/logout")
    async def logout(request: Request):
        sid = request.cookies.get(SESSION_COOKIE)
        if sid:
            destroy_session(settings.db_path, sid)
        resp = RedirectResponse("/login", status_code=302)
        resp.delete_cookie(SESSION_COOKIE, path="/")
        return resp

