    @app.get("/api/library")
    async def api_library(
        # v1.18.0: 'collections' added — fourth tab parallel to
        # movies/tv/anime. Collections live within Plex's movie/show
        # sections (not their own section type), so the section
        # filter is media_type-only (no anime/4K split).
        tab: str = Query(..., pattern="^(movies|tv|anime|collections)$"),
        fourk: bool = Query(False),
        # v1.18.1: per-section scope for the /collections tab.
        # Plex collections span every managed section, so a binary
        # STANDARD/4K toggle isn't meaningful for them — instead the
        # collections page lets the user pick a specific section to
        # narrow to. Empty / unset means "all included sections."
        # Honored only for tab='collections'; other tabs use fourk.
        # Validated as a non-negative integer string (Plex section
        # IDs are integers serialized as strings throughout motif).
        section_id: str = Query("", pattern="^[0-9]*$"),
        # v0.51.21: the // ALL resolution chip. For movies/tv/anime it
        # unions the standard AND 4K sections into one view (instead of
        # fourk picking exactly one); for collections it means "all
        # managed sections' collections" (equivalent to section_id='').
        # When true, fourk / section_id are ignored.
        all_res: bool = Query(False),
        q: str = Query(""),
        status: str = Query("all", pattern="^(all|has_theme|themed|manual|plex_agent|untracked|downloaded|placed|unplaced|dl_missing|failures|updates|not_in_plex)$"),
        tdb: str = Query("any", pattern="^(any|tracked|untracked)$"),
        # v1.12.23: server-side multi-select pill filters. Each axis
        # accepts a comma-separated list. Empty = no filter on that
        # axis. Selections within an axis OR; axes AND.
        src_pills: str = Query(""),
        tdb_pills: str = Query(""),
        dl_pills: str = Query(""),
        pl_pills: str = Query(""),
        link_pills: str = Query(""),
        # v1.12.41: EDITION axis. Empty = no filter; 'has' /
        # 'none' / 'has,none' control whether to surface only
        # rows with / without an `{edition-...}` Plex folder tag.
        ed_pills: str = Query(""),
        # v1.13.68: ATTN (attention) axis. Mirrors the title-cell
        # `!`-glyph priority logic so the chip row makes the same
        # rows visible that the glyphs already advertise. Each value
        # corresponds to one un-acked attention state:
        #   fail     — un-acked failure (red ⚠ glyph)
        #   update   — actionable pending TDB update (blue !)
        #   mismatch — canonical diverged from placement (amber ! M)
        #   await    — downloaded, no placement (amber ! P)
        #   broken   — canonical missing on disk, Plex copy intact (red ↺)
        # Multi-select OR within axis, AND with other axes. Topbar's
        # 5-FAIL pill click-through routes to ?attn_pills=fail.
        attn_pills: str = Query(""),
        page: int = Query(1, ge=1),
        per_page: int = Query(50, ge=1, le=200),
        # v1.14.95: 'tdb' added to the regex. The TDB column header
        # has carried `data-sort="tdb"` since v1.13.67 and the SQL
        # dispatch table _LIBRARY_SORTS_MAIN has a 'tdb' branch
        # (priority CASE: pending update → tracked-ok → cookies →
        # dead → dropped → no-TDB), but the regex pattern was
        # never widened — every TDB-header click 422'd before the
        # sort even reached the SQL layer. Mirror-principle leak
        # between the route enum and the SQL dispatch table.
        sort: str = Query("title", pattern="^(title|year|tdb|src|dl|pl|link|imdb|attention|edition)$"),
        sort_dir: str = Query("asc", pattern="^(asc|desc)$"),
        db: Path = Depends(get_db_path),
    ):
        """Unified browse: every item Plex sees in the requested tab/sub-tab,
        joined to themes / local_files / placements so the UI can show the
        full theme-status picture in one row.

        v1.10.1: status=not_in_plex switches to a different query shape that
        returns ThemerrDB rows whose tmdb_id has no matching plex_items in
        this tab. Rows are synthesized into the plex-shaped schema so the
        frontend renderer can handle them uniformly (with not_in_plex=1
        distinguishing them visually). Skipped on anime tab — themes table
        has no anime signal.
        """
        if status == "not_in_plex":
            # tdb sub-filter is redundant for not_in_plex (everything in
            # that view is tracked), so it's not threaded through.
            return await run_in_threadpool(
                _library_not_in_plex, db, tab=tab, fourk=fourk,
                q=q, page=page, per_page=per_page,
                sort=sort, sort_dir=sort_dir,
            )
        # v1.12.23: parse the comma-separated pill axes once.
        def _pset(s: str, valid: set[str]) -> set[str]:
            if not s:
                return set()
            return {p for p in (x.strip() for x in s.split(",")) if p in valid}
        # v1.14.11: include the v1.14.10 'Pp' composite-+P token in the
        # _pset validation set. Pre-fix the inner SQL gate (api.py:957)
        # accepted 'Pp' as a valid token and emitted the right WHERE
        # clause, but the outer query-param parser silently dropped it
        # at this _pset call — leaving src_set empty and the request
        # falling through to the unfiltered code path. Mirror-principle
        # leak: every place that lists the valid src tokens must
        # include 'Pp' or the new pill no-ops with no error surface.
        src_set = _pset(src_pills, {"T", "U", "A", "M", "P", "Pp", "-"})
        tdb_set = _pset(tdb_pills, {"tdb", "update", "cookies", "dead", "none", "dropped", "empty"})
        dl_set = _pset(dl_pills, {"on", "off", "broken"})
        # v1.18.30: 'pushed' dropped from the whitelist alongside the
        # cyan PL filter chip's removal. PL is a pure health axis;
        # mechanism filtering lives on the LINK axis (LINK=PU).
        pl_set = _pset(pl_pills, {"on", "await", "off", "broken"})
        link_set = _pset(link_pills, {"hl", "c", "m", "none", "ps", "pu", "rp", "b", "bk", "tb", "ab"})
        ed_set = _pset(ed_pills, {"has", "none"})
        # v1.15.23: 'cookies' added to the valid set. v1.15.17
        # introduced the cookies STATUS pill + topbar chip and added
        # the SQL branch (api.py: ~line 1310) but missed THIS valid
        # set — _pset silently drops any value not in the set, so
        # ?attn_pills=cookies became an empty set, no filter ran,
        # and the user saw every row instead of the filtered subset.
        # Same mirror-principle leak class the v1.14.11 comment
        # ~line 7295 documented. Cross-ref test
        # (test_v1_15_23_attn_pills_token_cross_reference) catches
        # any future axis-token addition that misses one surface.
        attn_set = _pset(attn_pills,
                         {"fail", "cookies", "update", "mismatch", "await",
                          "broken", "restore", "repush"})
        # v1.12.23: 'broken' DL pill alone routes through the existing
        # dl_missing path (post-SQL stat-check). Combined with on/off
        # selections it's ignored for now — would require refactoring
        # the post-SQL annotator to OR with the SQL pre-filter.
        # v1.14.91: also fire the routing for status='has_theme' (the
        # THEMED chip). dl_missing semantically implies has_theme —
        # a tracked canonical that's missing on disk is by definition
        # a themed row. Pre-fix the user reported THEMED + ↺ (broken)
        # showed every themed row (the broken pill silently dropped
        # because the routing only triggered for status=='all'), since
        # there's no SQL branch for broken in the attn_pills loop and
        # the override was the only path that narrowed the result set.
        effective_status = status
        if dl_set == {"broken"} and status in ("all", "has_theme"):
            effective_status = "dl_missing"
            dl_set = set()  # consumed by status routing
        # v1.13.68: 'broken' attn pill alone — same shape as the
        # dl_pills broken case. canonical_missing isn't a column,
        # so route through dl_missing for the SQL pre-filter then
        # let _annotate_canonical_state apply the stat. Mixed
        # selections (broken + others) fall through and get
        # post-stat narrowing in the same path that dl_pills uses.
        # v1.14.91: also fire for status='has_theme' (see the
        # dl_set comment above for the equivalence rationale).
        if attn_set == {"broken"} and status in ("all", "has_theme"):
            effective_status = "dl_missing"
            attn_set = set()
        cookies_present = bool(settings.cookies_file
                               and settings.cookies_file.exists())
        return await run_in_threadpool(
            _library_main_query, db, tab=tab, fourk=fourk,
            all_res=all_res,
            # v1.18.1: section_id is collections-only; the helper
            # ignores it for other tabs (where it falls through to
            # the existing tab_where dispatch).
            # v0.51.21: // ALL forces section_id='' (collections → every
            # section) — the helper's per-section filter then no-ops.
            section_id=("" if all_res
                        else (section_id if tab == "collections" else "")),
            q=q, status=effective_status, tdb=tdb,
            page=page, per_page=per_page,
            sort=sort, sort_dir=sort_dir,
            src_pills=src_set, tdb_pills=tdb_set,
            dl_pills=dl_set, pl_pills=pl_set, link_pills=link_set,
            ed_pills=ed_set, attn_pills=attn_set,
            cookies_present=cookies_present,
            themes_dir=settings.themes_dir if settings.is_paths_ready() else None,
        )

    @app.post("/api/library/download-batch")
    async def api_library_download_batch(
        request: Request, db: Path = Depends(get_db_path),
    ):
        """Enqueue download jobs for an explicit list of items. Body:
        {"items": [{"media_type": "...", "tmdb_id": ...}, ...],
         "place": true|false (optional, default true)}.
        Skips items already downloaded or already enqueued. Returns
        {ok, enqueued, skipped}.

        v1.15.4: optional `place` body flag. When false, the
        downloaded canonical lands in /themes/ but does NOT get
        hardlinked into the Plex folder — pure backup mode for
        P-only rows where Plex serves its own theme + the user
        wants a motif-side fallback without changing what Plex
        currently plays. the user: "I would like to make it so
        movies that are just P have a bulk action when there is
        a themerrdb source also available so we can bulk
        download TDB Backup as right now have to go one by one."
        """
        _require_admin(request)
        # v1.15.34: raise on JSON parse failure rather than coercing
        # to {} — silent coercion let a malformed body fall through
        # to the items-validation check, returning the same 400 as a
        # legitimately empty list. The operator couldn't tell whether
        # the request body was bad or the items array was empty.
        try:
            body = await request.json()
        except Exception as e:
            raise HTTPException(
                status_code=400,
                detail=f"invalid JSON body: {e}",
            )
        items = body.get("items") if isinstance(body, dict) else None
        if not isinstance(items, list) or not items:
            raise HTTPException(status_code=400, detail="items must be a non-empty list")
        # v1.15.4: place flag. Defaults to True so existing
        # callers (// DOWNLOAD FROM TDB / // DOWNLOAD & REPLACE
        # FROM TDB) keep their auto-place behavior unchanged.
        place_canonical = (
            isinstance(body, dict) and body.get("place", True) is not False
        )
        enqueued = 0
        skipped = 0
        from ..core.sync import _enqueue_download
        with get_conn(db) as conn:
            for it in items:
                if not isinstance(it, dict):
                    skipped += 1
                    continue
                mt = str(it.get("media_type", ""))
                tid = it.get("tmdb_id")
                # v1.20.25: include 'collection'. Pre-fix the bulk
                # download silently SKIPPED every collection row (mt
                # not in movie/tv) → the user selected 5 TDB-tracked
                # collections, got "enqueued:0, skipped:5" with no
                # explanation. _enqueue_download + the place worker
                # (_do_place_collection) fully support collections; the
                # gate just never got extended past movie/tv.
                if mt not in ("movie", "tv", "collection") \
                        or not isinstance(tid, int):
                    skipped += 1
                    continue
                # v1.19.8: honor per-item section_id if the
                # frontend provided it (it should — the row was
                # selected from a specific tab/section). Pre-fix
                # the endpoint dropped section context entirely
                # and `_enqueue_download` fanned out to EVERY
                # section containing the (mt, tid), so a bulk on
                # 4K-tab selections ALSO touched the standard
                # section's library state. the user's 2026-05-24
                # repro: selected 4 items on /4K, got "+7 QUEUED"
                # (4 4K-section downloads + 4 std-section
                # downloads − 1 running). Legacy callers without
                # section_id fall through to the old fan-out
                # behavior (frontend bumps to v1.19.8 too — same
                # image deploy — so this fallback is a safety
                # net, not the expected path).
                only_section_id = it.get("section_id")
                if not isinstance(only_section_id, str) or not only_section_id:
                    only_section_id = None
                # v1.21.85: per-item rating_key -> edition, so a bulk
                # download/replace of a tagged edition stages + places into
                # THAT edition's folder (pre-fix the omitted edition_key
                # defaulted '' and bulk-downloaded the standard edition for
                # multi-edition titles). Legacy callers without rating_key
                # fall through to '' (standard) as before.
                _dl_rk = it.get("rating_key")
                _dl_edition = (edition_key_for_rating_key(conn, _dl_rk)
                               if isinstance(_dl_rk, str) and _dl_rk else "")
                # Verify the theme actually exists
                theme = conn.execute(
                    "SELECT 1 FROM themes WHERE media_type = ? AND tmdb_id = ?",
                    (mt, tid),
                ).fetchone()
                if not theme:
                    skipped += 1
                    continue
                # _enqueue_download fans out per-section + dedupes per-section.
                # v1.13.31: force_place=True so the auto-place job that
                # follows each download bypasses the plex_has_theme guard.
                # Pre-fix bulk DOWNLOAD on M-source rows (manual sidecar +
                # Plex agent has its own theme, the composite M+P state)
                # would download the TDB theme but the place worker
                # logged "Skipped placement: plex_has_theme" because the
                # row had has_theme=1 — so the download succeeded but
                # nothing landed in Plex's folder. The user's bulk-select
                # action is an explicit "yes, replace what's there"
                # intent, just like single-row Replace-with-ThemerrDB.
                # v1.15.4: when place=false, pass auto_place=False so
                # the worker skips the chained place job entirely.
                # No place → no Plex-folder change → backup-mode
                # semantics. force_place becomes irrelevant in that
                # branch (no place job runs to gate).
                # v1.23.63 (audit #16): per-item BEGIN IMMEDIATE around the
                # enqueue's dedup-SELECT + INSERT so two concurrent batches can't
                # both pass the per-section dedup and double-insert; per-ITEM (not
                # whole-batch) keeps the write lock held only briefly so the worker
                # isn't starved across a large bulk.
                with transaction(conn):
                    if place_canonical:
                        n = _enqueue_download(
                            conn, media_type=mt, tmdb_id=tid,
                            reason="bulk_select",
                            force_place=True,
                            only_section_id=only_section_id,
                            edition_key=_dl_edition,
                            bulk=True,  # v1.23.46: bulk DOWNLOAD → one list
                        )
                    else:
                        n = _enqueue_download(
                            conn, media_type=mt, tmdb_id=tid,
                            reason="bulk_backup",
                            auto_place=False,
                            only_section_id=only_section_id,
                            edition_key=_dl_edition,
                            bulk=True,  # v1.23.46: bulk BACKUP → one list
                        )
                if n == 0:
                    skipped += 1
                else:
                    enqueued += n
        log_event(
            db, level="INFO", component="api",
            message=(
                f"Bulk download-batch by {request.state.user} "
                f"({'with place' if place_canonical else 'backup-only'})"
            ),
            detail={
                "enqueued": enqueued, "skipped": skipped,
                "requested": len(items),
                "place": place_canonical,
            },
        )
        return {"ok": True, "enqueued": enqueued, "skipped": skipped}

    @app.post("/api/library/download-missing")
    async def api_library_download_missing(
        request: Request, db: Path = Depends(get_db_path),
    ):
        """Enqueue a download job for every plex_item in the requested tab
        whose ThemerrDB theme exists but motif hasn't downloaded yet.
        Body: {tab, fourk}."""
        _require_admin(request)
        # v1.15.34: raise on JSON parse failure rather than coercing
        # to {} — pre-fix a malformed body would silently default to
        # tab=movies + fourk=false, enqueueing jobs against the wrong
        # tab/fourk with a 200 success the caller can't distinguish
        # from a legit "no missing themes on this tab" result.
        try:
            body = await request.json()
        except Exception as e:
            raise HTTPException(
                status_code=400,
                detail=f"invalid JSON body: {e}",
            )
        tab = body.get("tab", "movies")
        fourk = bool(body.get("fourk", False))
        if tab not in ("movies", "tv", "anime", "collections"):
            raise HTTPException(status_code=400, detail="invalid tab")
        if tab == "movies":
            tab_where = "pi.media_type = 'movie' AND ps.is_anime = 0"
        elif tab == "tv":
            tab_where = "pi.media_type = 'show' AND ps.is_anime = 0"
        elif tab == "collections":
            # v1.18.0: same parallel as the /api/library route's
            # collections branch — media_type filter only, no
            # anime/4K split.
            tab_where = "pi.media_type = 'collection'"
        else:
            # v1.19.28: parallel to /api/library's anime branch —
            # explicit media_type allowlist excludes collection rows
            # in anime sections (e.g. "Dragon Ball Collection"). The
            # bulk download endpoint follows whatever the user sees
            # in the library tab, so the filters must agree.
            tab_where = (
                "ps.is_anime = 1 "
                "AND pi.media_type IN ('movie', 'show')"
            )
        if tab != "collections":
            tab_where += " AND ps.is_4k = 1" if fourk else " AND ps.is_4k = 0"

        enqueued = 0
        from ..core.sync import _enqueue_download
        with get_conn(db) as conn:
            # v1.11.0: missing = (theme exists) AND (this row's section
            # has no local_files row). Per-section local_files match
            # cleanly via lf.section_id = pi.section_id, so the LEFT JOIN
            # nulls out exactly the (item, section) pairs we still need
            # to download.
            # v1.22.93: accept the theme_id linkage too (mirror of the
            # sql_missing_count widen) — DOWNLOAD MISSING on the
            # Collections tab enqueued nothing because Plex collections
            # are guid-less; they link via theme_id. SELECT DISTINCT
            # already dup-proofs the OR fan-out.
            # v1.23.65 (audit #4): edition-AWARE. local_files is tracked per
            # edition (PK includes edition_key), but the LEFT JOIN omitted it, so
            # for a multi-edition title sharing a section where the standard
            # edition is themed but a sibling is themeless, the join matched the
            # standard's row → file_path NOT NULL → the whole tuple dropped and
            # the genuinely-missing sibling edition was never enqueued. Carry
            # pi.edition_key into the DISTINCT + the local_files join + the
            # enqueue so each missing edition is detected + staged into its own
            # folder (mirrors the v1.21.85 per-rk download-batch path).
            rows = conn.execute(f"""
                SELECT DISTINCT t.media_type, t.tmdb_id, pi.edition_key
                FROM plex_items pi
                INNER JOIN plex_sections ps
                  ON ps.section_id = pi.section_id AND ps.included = 1
                INNER JOIN themes t
                  ON (t.id = pi.theme_id
                      OR (t.tmdb_id = pi.guid_tmdb
                          AND t.media_type = (CASE pi.media_type WHEN 'show' THEN 'tv' ELSE pi.media_type END)))
                LEFT JOIN local_files lf
                  ON lf.media_type = t.media_type
                 AND lf.tmdb_id = t.tmdb_id
                 AND lf.section_id = pi.section_id
                 AND lf.edition_key = pi.edition_key
                WHERE {tab_where}
                  AND lf.file_path IS NULL
                  AND t.upstream_source != 'plex_orphan'
            """).fetchall()
            for r in rows:
                # _enqueue_download dedupes per-section internally; v1.23.63
                # (audit #16) wraps each in a per-row BEGIN IMMEDIATE so the
                # dedup-SELECT + INSERT is atomic (no duplicate jobs under a
                # concurrent batch) without holding the write lock for the whole
                # sweep.
                with transaction(conn):
                    enqueued += _enqueue_download(
                        conn, media_type=r["media_type"], tmdb_id=r["tmdb_id"],
                        reason="bulk_missing",
                        edition_key=r["edition_key"],  # v1.23.65: per-edition
                        bulk=True,  # v1.23.46: bulk DOWNLOAD MISSING → one list
                    )
        log_event(db, level="INFO", component="api",
                  message=f"Bulk download-missing by {request.state.user}",
                  detail={"tab": tab, "fourk": fourk, "enqueued": enqueued})
        return {"ok": True, "enqueued": enqueued, "tab": tab, "fourk": fourk}

    @app.post("/api/plex_items/{rating_key}/adopt-sidecar")
    async def api_adopt_sidecar(
        request: Request, rating_key: str,
        db: Path = Depends(get_db_path),
    ):
        """v1.10.9: take ownership of an existing theme.mp3 sidecar at a
        Plex item's folder. Hardlinks the file into motif's themes_dir
        and records local_files + placement rows so the row flips from
        unmanaged-sidecar (M) to motif-adopted (A).

        Uses adopt_folder() which reuses _do_adopt for the actual file
        and DB work (same path the /scans page uses for orphan_resolvable
        findings) — but no scan_findings row is required.
        """
        _require_admin(request)
        if not settings.is_paths_ready():
            raise HTTPException(status_code=409,
                                detail="themes_dir not configured; visit /settings")
        with get_conn(db) as conn:
            pi = conn.execute(
                "SELECT * FROM plex_items WHERE rating_key = ?",
                (rating_key,),
            ).fetchone()
            if pi is None:
                raise HTTPException(status_code=404,
                                    detail="plex_items row not found")
            if not pi["folder_path"]:
                raise HTTPException(status_code=409,
                                    detail="Plex item has no folder path")
            if not pi["local_theme_file"]:
                raise HTTPException(status_code=409,
                                    detail="no theme.mp3 sidecar at this folder")
        from ..core.adopt import adopt_folder, AdoptError
        media_type = _motif_media_type(pi["media_type"])
        try:
            outcome = await run_in_threadpool(
                adopt_folder, db,
                settings=settings,
                folder_path=pi["folder_path"],
                media_type=media_type,
                title=pi["title"],
                year=str(pi["year"] or ""),
                section_id=pi["section_id"],
                imdb_id=pi["guid_imdb"],
                tmdb_id=int(pi["guid_tmdb"]) if pi["guid_tmdb"] else None,
                decided_by=request.state.principal.username,
            )
        except AdoptError as e:
            raise HTTPException(status_code=409, detail=str(e))
        return {"ok": True, "outcome": outcome}

    @app.post("/api/plex_items/{rating_key}/replace-with-themerrdb")
    async def api_replace_with_themerrdb(
        request: Request, rating_key: str,
        db: Path = Depends(get_db_path),
    ):
        """v1.10.9: sidecar-only Plex row whose tmdb_id is tracked by
        ThemerrDB — fetch motif's authoritative download and overwrite
        the existing sidecar. Cancels any in-flight jobs for the item
        and enqueues a fresh download with force_place=true so the
        place worker overwrites without the plex_has_theme guard.
        """
        _require_admin(request)
        with get_conn(db) as conn:
            pi = conn.execute(
                "SELECT * FROM plex_items WHERE rating_key = ?",
                (rating_key,),
            ).fetchone()
            if pi is None:
                raise HTTPException(status_code=404,
                                    detail="plex_items row not found")
            if not pi["guid_tmdb"]:
                raise HTTPException(status_code=409,
                                    detail="Plex item has no tmdb GUID")
        from ..core.adopt import replace_with_themerrdb, AdoptError
        media_type = _motif_media_type(pi["media_type"])
        # v1.21.66: resolve the edition from this row's folder so the
        # replace targets ONLY this edition (per-edition theme isolation).
        # Pre-fix REPLACE TDB on "Sam Takes a Step" enqueued an edition-less
        # download whose chained place resolved an arbitrary sibling rk and
        # uploaded into the Theatrical folder.
        _edition_key = edition_key_for_folder(pi["folder_path"])
        try:
            outcome = await run_in_threadpool(
                replace_with_themerrdb, db,
                media_type=media_type,
                tmdb_id=int(pi["guid_tmdb"]),
                decided_by=request.state.principal.username,
                section_id=pi["section_id"],
                edition_key=_edition_key,
            )
        except AdoptError as e:
            raise HTTPException(status_code=409, detail=str(e))
        # v1.20.10: REPLACE TDB enqueues a fresh TDB download (force_place);
        # the worker resolves the pending new_theme_available update on that
        # download's SUCCESS (_record_local_file), so the blue !UPD pill
        # clears when motif actually holds the theme — not optimistically
        # here (which left it cleared after a failed re-download).
        return {"ok": True, "outcome": outcome}

    @app.post("/api/plex_items/{rating_key}/upload-theme")
    async def api_upload_theme(
        request: Request, rating_key: str,
        db: Path = Depends(get_db_path),
    ):
        """Manual MP3 upload for a Plex item that ThemerrDB doesn't cover.
        Creates a plex_orphan themes row if one doesn't exist for this Plex
        item, writes the file to the canonical layout, and enqueues placement.
        """
        _require_admin(request)
        if not settings.is_paths_ready():
            raise HTTPException(status_code=409, detail="themes_dir not configured; visit /settings")

        form = await request.form()
        upload = form.get("file")
        if upload is None or not hasattr(upload, "read"):
            raise HTTPException(status_code=400, detail="multipart 'file' required")
        # v0.51.13 (audit #11): read in chunks with a running cap so an oversized
        # upload is rejected BEFORE it's fully resident — the identical
        # OOM-before-cap shape v1.23.18 fixed at database-restore/upload. Pre-fix
        # `await upload.read()` materialized a multi-GB mistake in RAM and only
        # THEN checked the 50 MiB cap.
        _CAP = 50 * 1024 * 1024
        _buf = bytearray()
        while True:
            chunk = await upload.read(4 * 1024 * 1024)
            if not chunk:
                break
            _buf += chunk
            if len(_buf) > _CAP:
                raise HTTPException(status_code=413, detail="file > 50 MiB")
        data = bytes(_buf)
        if not data:
            raise HTTPException(status_code=400, detail="empty file")
        # v1.21.18 (security audit): reject non-audio before it's stored as
        # theme.mp3. Lenient on container (MP3/Ogg/FLAC/WAV/AIFF/MP4) so a
        # real theme isn't blocked; rejects HTML/script/image/binary blobs.
        if not _looks_like_audio(data[:16]):
            raise HTTPException(
                status_code=415,
                detail="not a recognized audio file (expected MP3 or audio)")

        # Look up the Plex item
        with get_conn(db) as conn, transaction(conn):
            pi = conn.execute(
                "SELECT * FROM plex_items WHERE rating_key = ?",
                (rating_key,),
            ).fetchone()
            if pi is None:
                raise HTTPException(status_code=404,
                                    detail="plex_items row not found; refresh /libraries")
            # v0.51.53: was `else "movie"` — a collection (pi.media_type=
            # 'collection') mis-minted its theme row at media_type='movie',
            # orphaning it from the /api/items/collection endpoints. Reverse of
            # the v0.51.48 forward sweep; now collection-safe via the helper.
            theme_media_type = _motif_media_type(pi["media_type"])
            # v1.21.78: UPLOAD MP3 is per-edition — resolve the clicked
            # row's edition so the canonical lands in ITS folder and the
            # local_files / mismatch write key to it. Pre-fix the upload
            # went to the standard ('') canonical + local_files row, and
            # the two-join COALESCE(lf_e.mismatch_state, lf_g.mismatch_state)
            # bled that '' mismatch onto EVERY edition (the user: uploading to
            # "Sam Takes a Step" amber-! all three LotR editions).
            _upl_edition = edition_key_for_folder(pi["folder_path"])
            # Match an existing themes row by tmdb GUID, else allocate orphan.
            # v1.15.57: prefer pi.theme_id over guid_tmdb so plex_orphan
            # rows reuse the synthetic theme across UPLOAD MP3 + SET URL
            # calls (mirror of the SET URL fix at line ~8898). Pre-fix
            # uploading a second MP3 on an orphan row created a NEW
            # synthetic tmdb_id every time, orphaning the user_overrides
            # chain.
            theme = None
            if pi["theme_id"]:
                theme = conn.execute(
                    "SELECT * FROM themes WHERE id = ?",
                    (pi["theme_id"],),
                ).fetchone()
            if theme is None and pi["guid_tmdb"]:
                theme = conn.execute(
                    "SELECT * FROM themes WHERE media_type = ? AND tmdb_id = ?",
                    (theme_media_type, pi["guid_tmdb"]),
                ).fetchone()
            tmdb_id: int
            theme_id_pk: int
            if theme is None:
                # Allocate synthetic negative tmdb_id (consistent with orphan adopt)
                row = conn.execute(
                    "SELECT MIN(tmdb_id) AS lo FROM themes "
                    "WHERE media_type = ? AND tmdb_id < 0",
                    (theme_media_type,),
                ).fetchone()
                min_tmdb = row["lo"] if row and row["lo"] is not None else 0
                tmdb_id = min(min_tmdb, 0) - 1
                cur = conn.execute(
                    """INSERT INTO themes
                         (media_type, tmdb_id, imdb_id, title, year,
                          upstream_source, last_seen_sync_at, first_seen_sync_at)
                       VALUES (?, ?, ?, ?, ?, 'plex_orphan', ?, ?)""",
                    (theme_media_type, tmdb_id, pi["guid_imdb"],
                     pi["title"], pi["year"], now_iso(), now_iso()),
                )
                theme_id_pk = cur.lastrowid
            else:
                tmdb_id = theme["tmdb_id"]
                theme_id_pk = theme["id"]
            # v1.11.64: stamp pi.theme_id immediately. See manual-url
            # endpoint for the long-form rationale; without this the
            # library JOIN doesn't pick up the new orphan + uploaded
            # file until the next plex_enum runs resolve_theme_ids.
            conn.execute(
                "UPDATE plex_items SET theme_id = ? WHERE rating_key = ?",
                (theme_id_pk, rating_key),
            )

        # v1.11.0: write the upload under the section's themes_subdir.
        from ..core.canonical import canonical_theme_subdir
        section_id = pi["section_id"]
        with get_conn(db) as conn:
            sec = conn.execute(
                "SELECT themes_subdir FROM plex_sections WHERE section_id = ?",
                (section_id,),
            ).fetchone()
        if sec is None or not sec["themes_subdir"]:
            raise HTTPException(status_code=409,
                                detail=f"section {section_id} has no themes_subdir")
        media_root = settings.section_themes_dir_by_subdir(sec["themes_subdir"])
        # v1.21.78: stage into THIS edition's {edition-X} canonical folder.
        out_dir = media_root / canonical_theme_subdir(
            pi["title"], pi["year"], _upl_edition)
        out_dir.mkdir(parents=True, exist_ok=True)
        target = out_dir / "theme.mp3"

        # v1.11.99: detect existing placement → mismatch flow.
        # If a placement row exists for this (mt, tmdb, section) the
        # canonical and the placement file are likely hardlinked to
        # the same inode. Writing new bytes via target.write_bytes()
        # would mutate that shared inode and silently overwrite the
        # placement too — defeating the user-visible distinction
        # between "user uploaded new content" and "Plex is now
        # playing the new content". Break the hardlink first
        # (target.unlink()) so the placement file keeps its original
        # inode, then write the new canonical content into a fresh
        # inode at the same path.
        with get_conn(db) as conn:
            existing_placement = conn.execute(
                """SELECT 1 FROM placements
                    WHERE media_type = ? AND tmdb_id = ? AND section_id = ?
                      AND edition_key = ?""",
                (theme_media_type, tmdb_id, section_id, _upl_edition),
            ).fetchone()
        is_mismatch = bool(existing_placement)
        if is_mismatch:
            try:
                if target.exists():
                    target.unlink()
            except OSError as e:
                log.warning("upload: could not unlink canonical for mismatch: %s", e)
        # v1.22.69: multi-MB write + sha256 froze the event loop — offload.
        import hashlib

        def _write_and_hash() -> str:
            target.write_bytes(data)
            return hashlib.sha256(data).hexdigest()

        sha = await run_in_threadpool(_write_and_hash)
        rel_path = str(target.relative_to(settings.themes_dir))
        mismatch_value = "pending" if is_mismatch else None

        with get_conn(db) as conn, transaction(conn):
            conn.execute(
                """INSERT INTO local_files
                     (media_type, tmdb_id, section_id, edition_key, file_path,
                      file_sha256, file_size, downloaded_at, source_video_id,
                      provenance, source_kind, mismatch_state)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, '', 'manual', 'upload', ?)
                   ON CONFLICT(media_type, tmdb_id, section_id, edition_key) DO UPDATE SET
                       file_path = excluded.file_path,
                       file_sha256 = excluded.file_sha256,
                       file_size = excluded.file_size,
                       downloaded_at = excluded.downloaded_at,
                       provenance = excluded.provenance,
                       source_kind = excluded.source_kind,
                       mismatch_state = excluded.mismatch_state""",
                (theme_media_type, tmdb_id, section_id, _upl_edition, rel_path,
                 sha, len(data), now_iso(), mismatch_value),
            )
            # v1.10.50: implicit ack on a manual upload — the user is
            # routing around the broken TDB URL. Stamp acked_at so the
            # ! glyph + FAILURES filter exclude the row, but keep
            # failure_kind so the TDB pill stays red.
            # v1.14.24: per-section sfa write instead of title-global
            # `themes.failure_acked_at`. Pre-fix the title-global ack
            # instantly dismissed the FAIL glyph + N FAIL count for
            # EVERY section that owns the title — even though only
            # this section got an upload. Same cross-section bleed
            # pattern (CLAUDE.md class K) v1.14.8 closed for the
            # worker download path. See api_manual_url for the full
            # rationale; this is the matching upload-theme fix.
            if section_id:
                conn.execute(
                    """INSERT INTO section_failure_acks
                       (media_type, tmdb_id, section_id, acked_at, acked_by)
                       SELECT ?, ?, ?, ?, 'auto:upload'
                       WHERE EXISTS (
                           SELECT 1 FROM themes t
                           WHERE t.media_type = ?
                             AND t.tmdb_id = ?
                             AND t.failure_kind IS NOT NULL
                       )
                       ON CONFLICT(media_type, tmdb_id, section_id) DO NOTHING""",
                    (theme_media_type, tmdb_id, section_id,
                     now_iso(), theme_media_type, tmdb_id),
                )
            # v1.11.99: only enqueue placement on the no-mismatch path.
            # Mismatch rows wait for explicit PUSH TO PLEX / ADOPT FROM
            # PLEX / KEEP MISMATCH from /pending or the row's PLACE menu.
            # v1.15.75: download_only flag (from the upload form) skips
            # the place enqueue entirely. the user's intent for P rows:
            # the file lands in local_files as a backup, Plex keeps
            # serving its own theme, the user can later PUSH TO PLEX
            # to promote motif's copy.
            download_only_form = (form.get("download_only") or "").lower()
            download_only = download_only_form in ("1", "true", "yes", "on")
            if not is_mismatch and not download_only:
                # v1.21.78: carry edition_key so the place lands in THIS
                # edition's folder/rk (cached_rk lookup edition-scoped).
                _upl_place_payload = (
                    json.dumps({"edition_key": _upl_edition})
                    if _upl_edition else "{}")
                conn.execute(
                    "INSERT INTO jobs (job_type, media_type, tmdb_id, section_id, "
                    "                  payload, status, created_at, next_run_at) "
                    "VALUES ('place', ?, ?, ?, ?, 'pending', ?, ?)",
                    (theme_media_type, tmdb_id, section_id,
                     _upl_place_payload, now_iso(), now_iso()),
                )
            elif download_only:
                # v1.19.37: stamp last_place_attempt_reason='backup_only'
                # so the BK badge (app.js:isBackupOnly) surfaces AND
                # the hourly retry sweep (scheduler.py) skips this row.
                # api_upload_theme writes local_files directly (above)
                # — bypasses worker._record_local_file where the
                # v1.19.21/.33 whitelist normally lands the stamp. Same
                # one-conceptual-surface-multiple-writers sub-pattern
                # the v1.19.33 audit caught for SET URL + DOWNLOAD TDB
                # BACKUP; this is the matching upload-theme fix. Pre-
                # fix the user clicked KEEP AS BACKUP, expected to see
                # BK + PROMOTE TO ACTIVE in the recovery card, got
                # neither — see the v1.19.37 audit's UPLOAD MP3
                # finding for the full repro.
                conn.execute(
                    "UPDATE local_files SET "
                    "  last_place_attempt_at = ?, "
                    "  last_place_attempt_reason = 'backup_only' "
                    "WHERE media_type = ? AND tmdb_id = ? "
                    "  AND section_id = ? AND edition_key = ?",
                    (now_iso(), theme_media_type, tmdb_id, section_id,
                     _upl_edition),
                )

        log_event(db, level="INFO", component="api",
                  media_type=theme_media_type, tmdb_id=tmdb_id,
                  section_id=section_id,
                  message=f"Manual upload by {request.state.user}: {len(data)} bytes",
                  detail={"rating_key": rating_key, "title": pi["title"]})
        return {"ok": True, "media_type": theme_media_type, "tmdb_id": tmdb_id,
                "file_path": rel_path, "size": len(data)}

    @app.post("/api/plex_items/{rating_key}/manual-url")
    async def api_manual_url(
        request: Request, rating_key: str,
        db: Path = Depends(get_db_path),
    ):
        """Assign a YouTube URL to a Plex item as a manual theme source.

        Creates a plex_orphan themes row if no themes row exists for this
        Plex item (matched via guid_tmdb), writes a user_overrides row, and
        enqueues a download. The URL becomes the authoritative source for
        the item — ThemerrDB syncs won't overwrite it (per v1.5.4 sync
        guard).
        """
        _require_admin(request)
        try:
            body = await request.json()
        except Exception:
            raise HTTPException(status_code=400, detail="invalid JSON body")
        url = (body or {}).get("youtube_url", "")
        if not url:
            raise HTTPException(status_code=400, detail="youtube_url required")
        # v1.14.9: route canonicalization by source. Pre-fix this
        # path called extract_video_id() and reconstructed the URL
        # as `https://www.youtube.com/watch?v={vid}` unconditionally.
        # On a SoundCloud URL extract_video_id returns
        # `sc-<artist>-<slug>` (the synthetic ID used as the
        # source_video_id sentinel), which then got wrapped as
        # `youtube.com/watch?v=sc-stevecomposer-...` — a URL
        # yt-dlp dutifully tried as a YouTube video and failed
        # with `[youtube] sc-stevecom: Video unavailable`. the user's
        # repro: SET URL with a real SC URL → live preview detected
        # SoundCloud → save → download immediately failed.
        src = url_source(url)
        if src == "unknown":
            raise HTTPException(
                status_code=400,
                detail=("URL must be a YouTube, SoundCloud, Instagram, "
                        "or Facebook link"),
            )
        vid = extract_video_id(url)
        if not vid:
            raise HTTPException(status_code=400, detail="could not parse URL")
        if src == "youtube":
            # YouTube canonicalization: strip tracking params,
            # normalize youtu.be / shorts → watch?v= shape.
            canonical_url = f"https://www.youtube.com/watch?v={vid}"
        else:
            # SoundCloud: store as-is. yt-dlp's SC extractor reads
            # the URL not an ID, and the URL is already in canonical
            # `soundcloud.com/{artist}/{slug}` shape — reconstructing
            # it would require remembering the host, which is just
            # what the original input already gives us.
            canonical_url = url

        with get_conn(db) as conn, transaction(conn):
            pi = conn.execute(
                "SELECT * FROM plex_items WHERE rating_key = ?",
                (rating_key,),
            ).fetchone()
            if pi is None:
                raise HTTPException(status_code=404,
                                    detail="plex_items row not found; refresh from plex")
            # v1.21.60 (C2): scope the override to THIS edition. SET URL on
            # the Extended row writes an 'extended' override that the
            # v1.21.60 read tier surfaces only on Extended — no longer bleeds
            # to the standard/sibling editions. '' for a standard folder =
            # today's behavior.
            _edition_key = edition_key_for_folder(pi["folder_path"])
            # v1.18.6: 'collection' added to the plex_items →
            # themes media_type mapping. Pre-fix the user's SET URL
            # on Willy Wonka Collection created an orphan as
            # `movie/-27` (the fall-through branch) instead of
            # `collection/-27`, so the placement worker dispatched
            # to _do_place (movie path) instead of
            # _do_place_collection (HTTP upload). Result: "Skipped
            # placement: no_match" because the FolderIndex
            # couldn't find a media folder for the collection.
            if pi["media_type"] == "show":
                theme_media_type = "tv"
            elif pi["media_type"] == "collection":
                theme_media_type = "collection"
            else:
                theme_media_type = "movie"
            theme = None
            # v1.15.57: prefer the cached pi.theme_id lookup so
            # plex_orphan rows reuse their existing synthetic theme
            # across multiple SET URL calls. Pre-fix the lookup only
            # checked pi.guid_tmdb (NULL for orphans, since Plex
            # didn't supply an IMDB/TMDB id), so the `if theme is
            # None` branch below created a NEW synthetic tmdb_id on
            # every SET URL — orphaning the user_overrides +
            # previous_urls chain. the user: "if a user provides a
            # url and a row is U and then a different user provided
            # url is added to replace the existing the original user
            # provided url should be become the previous url
            # currently it goes away entirely." The chain naturally
            # works on second+ SET URL once the synthetic theme is
            # reused — _capture_previous_url sees the existing
            # user_override and rolls it into previous_urls.
            if pi["theme_id"]:
                theme = conn.execute(
                    "SELECT * FROM themes WHERE id = ?",
                    (pi["theme_id"],),
                ).fetchone()
            if theme is None and pi["guid_tmdb"]:
                theme = conn.execute(
                    "SELECT * FROM themes WHERE media_type = ? AND tmdb_id = ?",
                    (theme_media_type, pi["guid_tmdb"]),
                ).fetchone()
            if theme is None:
                row = conn.execute(
                    "SELECT MIN(tmdb_id) AS lo FROM themes "
                    "WHERE media_type = ? AND tmdb_id < 0",
                    (theme_media_type,),
                ).fetchone()
                min_tmdb = row["lo"] if row and row["lo"] is not None else 0
                tmdb_id = min(min_tmdb, 0) - 1
                # v1.18.19: populate title_norm on the orphan
                # themes row. Pre-fix the INSERT omitted this
                # column → orphans had title_norm=NULL → the
                # resolve_theme_ids sql_collection_title pass
                # silently skipped them on subsequent enums (the
                # JOIN gate `t.title_norm = pi.title_norm`
                # against NULL evaluates UNKNOWN) → the v1.18.16
                # relink backfill couldn't match either. the user's
                # Wonka + 101 Dalmatians collections sat at
                # SRC=P + PL=amber forever.
                # v1.18.21: class-9 fix — log the fallback. The
                # `.lower()` fallback disagrees with every other
                # normalize_title call site (sync.py + plex_enum
                # both use the real implementation), so a row that
                # hits this branch silently won't match in the
                # sql_collection_title JOIN → SRC stuck at P with
                # no breadcrumb. Pre-fix the bare except: pass
                # masked the failure entirely.
                try:
                    from ..core.normalize import normalize_title
                    title_norm = normalize_title(pi["title"] or "")
                except Exception as _norm_err:  # noqa: BLE001
                    log.warning(
                        "manual_url: normalize_title(%r) raised %s "
                        "— falling back to .lower(). May cause "
                        "sql_collection_title JOIN miss.",
                        pi["title"], _norm_err,
                    )
                    title_norm = (pi["title"] or "").lower()
                cur = conn.execute(
                    """INSERT INTO themes
                         (media_type, tmdb_id, imdb_id, title, year,
                          upstream_source, last_seen_sync_at,
                          first_seen_sync_at, title_norm)
                       VALUES (?, ?, ?, ?, ?, 'plex_orphan', ?, ?, ?)""",
                    (theme_media_type, tmdb_id, pi["guid_imdb"],
                     pi["title"], pi["year"], now_iso(), now_iso(),
                     title_norm),
                )
                theme_id_pk = cur.lastrowid
            else:
                tmdb_id = theme["tmdb_id"]
                theme_id_pk = theme["id"]

            # v1.11.64: stamp pi.theme_id immediately so the library JOIN
            # picks up the new orphan on the very next /api/library
            # refresh — the lib query joins through pi.theme_id (the
            # v1.11.26 denormalized cache) and won't see local_files /
            # placements rows under a synthetic-negative tmdb_id until
            # the next plex_enum's resolve_theme_ids re-stamps the
            # column. Same fix v1.11.43 added for adopt; missed here
            # for SET URL / UPLOAD MP3, so manual URL + upload on
            # P-source rows looked like the action did nothing.
            conn.execute(
                "UPDATE plex_items SET theme_id = ? WHERE rating_key = ?",
                (theme_id_pk, rating_key),
            )

            # v1.12.37: snapshot the prior canonical URL into
            # themes.previous_youtube_url BEFORE the override
            # upsert overwrites the current state. Lets REVERT
            # round-trip back to the URL that was active before
            # this SET URL call.
            # v1.12.105: scope the capture to the row's section.
            # Pre-fix the call passed no section_id so the capture
            # read user_overrides via ORDER BY section_id LIMIT 1
            # (right URL by accident if only one section owned the
            # title) but always WROTE to section_id='' — the
            # section-scoped previous_urls row stayed stale forever.
            # User saw "previous=oldest" instead of "previous=URL
            # I just replaced". Library SQL prefers pv_sec over
            # pv_global so the global-fallback write was invisible.
            section_id_for_override = pi["section_id"] or ""
            _capture_previous_url(conn, theme_media_type, tmdb_id,
                                  section_id=section_id_for_override)

            # v1.12.72: SET URL writes a per-section override scoped
            # to the rating_key's plex_items.section_id. Pre-fix, all
            # SET URL writes overwrote the same global (media_type,
            # tmdb_id) row across every section that owned the title
            # — users with separately-themed editions (4K + standard)
            # couldn't pin different sources per edition. PK is now
            # (media_type, tmdb_id, section_id) so different sections
            # coexist; ON CONFLICT clause updates only the matching
            # section's row, leaving sibling-section overrides
            # untouched.
            # section_id_for_override defined above (v1.12.105).
            # v1.18.81: widened SELECT to include `intent` so the audit
            # details below can record the intent transition (old →
            # new). Same anti-pattern that hid v1.18.77/.78 — without
            # provenance recording, a future SET URL with a different
            # intent leaves no breadcrumb.
            prior_override = conn.execute(
                "SELECT youtube_url, intent FROM user_overrides "
                "WHERE media_type = ? AND tmdb_id = ? AND section_id = ? "
                "  AND edition_key = ?",
                (theme_media_type, tmdb_id, section_id_for_override,
                 _edition_key),
            ).fetchone()
            # v1.18.77: persist the user's backup-vs-replace intent
            # on the override row. download_only=True → 'backup'
            # (defer to Plex; URL is a safety net), else 'replace'
            # (motif's URL should win; force placement past
            # plex_has_theme). Disambiguates the post-fact state
            # that was previously indistinguishable. See migration
            # _migrate_v55_to_v56 for the schema rationale.
            _intent = (
                "backup"
                if bool((body or {}).get("download_only"))
                else "replace"
            )
            conn.execute(
                """INSERT INTO user_overrides (media_type, tmdb_id, youtube_url,
                                               set_at, set_by, note,
                                               section_id, edition_key, intent)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                   ON CONFLICT(media_type, tmdb_id, section_id, edition_key) DO UPDATE SET
                       youtube_url = excluded.youtube_url,
                       set_at = excluded.set_at,
                       set_by = excluded.set_by,
                       note = excluded.note,
                       intent = excluded.intent""",
                (theme_media_type, tmdb_id, canonical_url, now_iso(),
                 request.state.user, f"manual url for plex rk={rating_key}",
                 section_id_for_override, _edition_key, _intent),
            )
            # v1.18.81: include `intent` in the audit details. v1.18.77
            # added the intent column but the SET URL audit never
            # recorded which intent was written — every SET URL audit
            # entry looked identical regardless of whether KEEP AS
            # BACKUP was checked. The provenance gap is what made the
            # v1.18.81 root-cause analysis hard: post-fact there was
            # no way to confirm what intent each SET URL had requested.
            # Now the audit details name it, so future debugging has
            # the trail.
            _prior_intent = (
                prior_override["intent"]
                if prior_override and "intent" in prior_override.keys()
                else None
            )
            _record_audit(
                conn, actor=request.state.user, action="set_url",
                media_type=theme_media_type, tmdb_id=tmdb_id,
                section_id=section_id_for_override,
                details={
                    "old_url": prior_override["youtube_url"] if prior_override else None,
                    "new_url": canonical_url,
                    "rating_key": rating_key,
                    "old_intent": _prior_intent,
                    "new_intent": _intent,
                },
            )
            # v1.12.62: eager synthetic urls_match detection. If the
            # URL the user just set exactly matches the row's current
            # TDB URL, surface the "convert U → T" prompt immediately
            # — pre-fix the user had to wait until the next sync for
            # the v1.12.53 sweep to write the synthetic pending_update,
            # which felt like the action menu had no path to swap to T.
            # v1.12.81: drop stale pending_updates (any decision) for
            # this title BEFORE re-inserting. Pre-fix the original
            # NOT EXISTS guard blocked insertion whenever ANY row
            # existed, so the SET URL → ACCEPT (urls_match) → SET URL
            # again with the same URL flow silently produced a U row
            # with no re-prompt — the prior decision='accepted' row
            # vetoed the synthetic insert. Treat each fresh SET URL
            # match as a clean prompt: clear prior decisions and
            # insert a new pending row. Still idempotent because the
            # SET URL writes are user-initiated, not automatic.
            existing_theme_yt = (theme["youtube_url"]
                                 if theme and "youtube_url" in theme.keys()
                                 else None)
            if (existing_theme_yt
                    and canonical_url
                    and existing_theme_yt.strip() == canonical_url.strip()):
                # v1.12.99: schema v31 added section_id to the PK.
                # SET URL is per-section (rk-driven), so the eager
                # urls_match insert lands on the row's section_id —
                # not the title-global '' row. Other sections see
                # whatever was already there (or nothing).
                # v1.22.22 (edition audit): scope the clear + re-insert to the
                # clicked edition. Pre-fix a SET URL on one edition's row wiped
                # EVERY edition's pending_updates in the section — including a
                # sibling edition's accepted/declined per-edition decision
                # (v1.21.81) — and re-inserted the urls_match prompt at '' for
                # all of them. Now it only re-prompts the edition the user set.
                conn.execute(
                    "DELETE FROM pending_updates "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ? "
                    "  AND edition_key = ?",
                    (theme_media_type, tmdb_id, section_id_for_override,
                     _edition_key),
                )
                # v1.13.55: only re-insert the urls_match prompt when
                # a successful canonical exists for this section.
                # Pre-fix a SET URL with the same URL TDB serves, on a
                # row with no canonical (failed downloads / never
                # downloaded), would write a stuck urls_match
                # pending_update. The prompt's purpose is "you have a
                # U row sourced from a manual URL that matches what
                # TDB now serves — ACCEPT UPDATE will convert U → T",
                # but with no canonical there's no U row to convert.
                # The user couldn't ACCEPT (would create a T row
                # pointing at nothing) and KEEP CURRENT was awkward
                # (nothing to keep). Now we leave pending_updates
                # empty in that case — the row stays in its real
                # state (failed-download with manual override) and
                # the topbar UPD count doesn't lie.
                has_canonical = conn.execute(
                    "SELECT 1 FROM local_files "
                    "WHERE media_type = ? AND tmdb_id = ? "
                    "  AND section_id = ? AND file_path IS NOT NULL "
                    "LIMIT 1",
                    (theme_media_type, tmdb_id, section_id_for_override),
                ).fetchone() is not None
                if has_canonical:
                    conn.execute(
                        """
                        INSERT INTO pending_updates (
                            media_type, tmdb_id, section_id, edition_key,
                            old_video_id, new_video_id,
                            old_youtube_url, new_youtube_url,
                            upstream_edited_at, detected_at, decision, kind
                        )
                        SELECT t.media_type, t.tmdb_id, ?, ?,
                               t.youtube_video_id, t.youtube_video_id,
                               NULL, t.youtube_url,
                               t.youtube_edited_at, ?, 'pending', 'urls_match'
                          FROM themes t
                         WHERE t.media_type = ?
                           AND t.tmdb_id = ?
                        """,
                        (section_id_for_override, _edition_key, now_iso(),
                         theme_media_type, tmdb_id),
                    )
            # v1.10.50: implicit ack on manual URL — same reasoning as
            # upload-theme. The user has provided a working source, so
            # stop alerting; keep failure_kind so the TDB pill stays red.
            # v1.14.24: per-section sfa write instead of title-global
            # `themes.failure_acked_at`. Pre-fix the title-global ack
            # instantly dismissed the FAIL glyph + N FAIL count for
            # EVERY section that owns the title — even though the user
            # only added an override on this one section. Same cross-
            # section bleed pattern (CLAUDE.md class K) that v1.13.54
            # closed for explicit ACK + v1.14.8 closed for the worker
            # download-success path. The API path was the last bleed
            # site for U-resolved acks.
            #
            # Belt-and-suspenders: the worker also writes sfa on
            # download success (worker.py:1201, v1.14.8). The API
            # write here is the immediate UX response (glyph clears
            # for THIS section before the download lands); the worker
            # write is the durable confirmation.
            section_id_for_ack = pi["section_id"] or ""
            if section_id_for_ack:
                conn.execute(
                    """INSERT INTO section_failure_acks
                       (media_type, tmdb_id, section_id, acked_at, acked_by)
                       SELECT ?, ?, ?, ?, 'auto:set_url'
                       WHERE EXISTS (
                           SELECT 1 FROM themes t
                           WHERE t.media_type = ?
                             AND t.tmdb_id = ?
                             AND t.failure_kind IS NOT NULL
                       )
                       ON CONFLICT(media_type, tmdb_id, section_id) DO NOTHING""",
                    (theme_media_type, tmdb_id, section_id_for_ack,
                     now_iso(), theme_media_type, tmdb_id),
                )
            # v1.11.0: cancel any in-flight download before re-enqueuing.
            # v1.22.1 (code-review): scope to THIS row's section + edition,
            # mirroring the re-download cancel (v1.12.73 section + v1.21.82
            # edition). Pre-fix the cancel was title-wide (media_type+tmdb_id
            # only) while the enqueue below is per-edition (v1.22.0 payload
            # edition_key) — a SET URL on one edition (or the same title in a
            # sibling section) silently flipped another edition's pending
            # download to 'cancelled'. jobs has no edition_key column; read it
            # off the payload (json_valid guard), '' for a standard job — the
            # same COALESCE shape the re-download cancel uses.
            _su_sec = pi["section_id"]
            if _su_sec:
                conn.execute(
                    """UPDATE jobs SET status = 'cancelled', finished_at = ?
                       WHERE job_type = 'download' AND media_type = ? AND tmdb_id = ?
                         AND section_id = ?
                         AND COALESCE(CASE WHEN json_valid(payload)
                             THEN json_extract(payload, '$.edition_key') END, '') = ?
                         AND status IN ('pending', 'failed')""",
                    (now_iso(), theme_media_type, tmdb_id, _su_sec, _edition_key),
                )
            else:
                conn.execute(
                    """UPDATE jobs SET status = 'cancelled', finished_at = ?
                       WHERE job_type = 'download' AND media_type = ? AND tmdb_id = ?
                         AND COALESCE(CASE WHEN json_valid(payload)
                             THEN json_extract(payload, '$.edition_key') END, '') = ?
                         AND status IN ('pending', 'failed')""",
                    (now_iso(), theme_media_type, tmdb_id, _edition_key),
                )
            # v1.11.15: enqueue the download directly with the rating_key's
            # section. _enqueue_download looks up sections via plex_items.
            # guid_tmdb, which never matches for plex_orphan rows (tmdb_id
            # is a synthetic negative). Pre-fix the manual-url flow on an
            # orphan logged 'no included Plex section owns (...)' and
            # silently skipped — the URL persisted but no download fired.
            section_id = pi["section_id"]
            # v1.12.81: SET URL now auto-places over the existing
            # placement (force_place=True in the payload, no
            # user_initiated_mismatch). Pre-fix the v1.11.99 mismatch
            # flow preserved the old placement file and marked
            # mismatch_state='pending' so the user could choose
            # between PUSH / ADOPT FROM PLEX / KEEP MISMATCH — but
            # per user feedback, clicking SET URL is already an
            # explicit "use this URL" decision; landing in a yellow
            # mismatch state and needing a follow-up PLACE action
            # felt like the action didn't take. Force-place mirrors
            # the /override endpoint's behavior so the two SET URL
            # paths produce the same outcome. UPLOAD MP3 still uses
            # the mismatch flow since uploaded content is locally
            # crafted — there the "preserve until user confirms
            # overwrite" gate matches user intent better.
            #
            # Direct INSERT (rather than _enqueue_download) is
            # preserved per v1.11.15 — _enqueue_download looks up
            # sections via plex_items.guid_tmdb which doesn't match
            # for plex_orphan rows (synthetic-negative tmdb_id),
            # so manual-url on an orphan would silently skip.
            # v1.15.75: optional download_only flag. the user's intent
            # for P rows: "create a backup file in DL but allow plex
            # to continue to server the theme but gives the option
            # to push that theme later if wanted and have a local
            # downloaded copy." When download_only=true, the worker
            # downloads + lands in local_files but does NOT place
            # over Plex's theme. The user can PUSH TO PLEX later to
            # promote motif's file.
            # v1.16.4: switched from `force_place=False` to
            # `auto_place=False` on the download_only branch.
            # the user: "when checking this and allowing it to
            # download only we see in the status bar it mention
            # placing as well as the amber PL blinking. it doesn't
            # place it but it animates as it were going to."
            # Root cause: the worker's post-download gate in
            # _handle_download (worker.py:1445-1467) reads
            # `auto_place` (falling back to settings.auto_place_
            # default = True for typical configs) AND `force_place`
            # SEPARATELY. force_place=False doesn't suppress
            # enqueueing — only auto_place=False does. Pre-fix the
            # worker enqueued a non-forcing place job that then
            # skipped at runtime with "plex_has_theme" — but
            # during the brief pending/running window, the row's
            # job_in_flight=='place' painted the amber PL pulse,
            # misleading the user into thinking a placement was
            # being attempted. Setting auto_place=False prevents
            # the place job from being created at all.
            # v1.16.5: gate the force_place override on `pi.has_theme`.
            # the user: "this will still respect the the setting for
            # autoplace on or off in settings right? If autoplace
            # is unchecked I don't want this to force it
            # unintentionally this is only for the P rows we want
            # to get into a PS link state via a url or upload."
            #
            # v1.16.4 set force_place=True on every non-download_only
            # SET URL, which forces auto_place=True in the worker
            # gate — overriding the user's global auto_place setting
            # for ALL rows. That's only correct for P rows (where
            # the force is needed to override Plex's plex_has_theme
            # skip). For non-P rows there's no Plex theme to
            # override, so force_place is a redundant flag that
            # unintentionally bypasses the global preference.
            #
            # Three branches now:
            #   download_only=True     → auto_place=False
            #     (explicit opt-out; honored regardless of P state)
            #   P-row + !download_only → force_place=True
            #     (canonical "replace Plex's theme" — needs force +
            #     this IS the intentional global-setting override)
            #   non-P row              → neutral payload
            #     (worker honors settings.auto_place_default; if
            #     globally off, no auto-place; if on, place runs
            #     normally without the force flag)
            download_only = bool((body or {}).get("download_only"))
            is_p_row = bool(pi["has_theme"])
            payload: dict = {"reason": "manual_url"}
            if download_only:
                payload["auto_place"] = False
            elif is_p_row:
                # Force placement past Plex's plex_has_theme skip.
                # The worker reads force_place=True and sets
                # force=True on the chained place job. This IS an
                # intentional global-auto_place override — SET URL
                # without download_only on a P row IS the user
                # explicitly asking to replace Plex's theme.
                payload["force_place"] = True
            # else: neutral payload. Worker honors the global
            # auto_place setting. No force needed on non-P rows
            # since there's no Plex theme to override.
            # v1.22.0 (line-close audit): thread the edition_key so the
            # worker's edition-scoped override resolution (v1.21.92) matches
            # the override we just wrote at this edition. Pre-fix SET URL on a
            # TAGGED edition wrote the override at _edition_key but enqueued an
            # edition-LESS download → worker resolved the override at '' → no
            # match → ignored the user's URL (downloaded TDB, or "no URL").
            if _edition_key:
                payload["edition_key"] = _edition_key
            conn.execute(
                "INSERT INTO jobs (job_type, media_type, tmdb_id, section_id, "
                "                  payload, status, created_at, next_run_at) "
                "VALUES ('download', ?, ?, ?, ?, 'pending', ?, ?)",
                (theme_media_type, tmdb_id, section_id,
                 json.dumps(payload),
                 now_iso(), now_iso()),
            )

        log_event(db, level="INFO", component="api",
                  media_type=theme_media_type, tmdb_id=tmdb_id,
                  section_id=section_id,
                  message=f"Manual URL set by {request.state.user}: {canonical_url}",
                  detail={"rating_key": rating_key, "title": pi["title"]})
        return {"ok": True, "media_type": theme_media_type, "tmdb_id": tmdb_id,
                "youtube_url": canonical_url}

    # v1.15.66: bulk user-URL import — preview + apply pair.
    #
    # Pairs with the per-library // EXPORT CSV button (3-col format:
    # Title,IMDB,Youtube_URL). Workflow:
    #
    #   /preview  → parse + match + categorize each row → JSON
    #   /apply    → accept resolved decisions → write user_overrides
    #
    # Preview categories:
    #   * "clean"     — current src ∈ {T, –} OR row already has
    #                   matching user URL (no-op); safe to bulk apply
    #   * "conflict"  — current src ∈ {A, M, P, U-with-different-url};
    #                   needs explicit per-row decision before apply
    #   * "no_match"  — IMDB not in library AND title+year fallback
    #                   missed; preview shows row read-only
    #   * "skipped"   — empty Youtube_URL cell (round-trip no-op for
    #                   non-U rows the user didn't touch)
    #
    # Match strategy: IMDB exact first; title+year (case-insensitive,
    # trimmed) fallback flagged with verify=True so the user can
    # spot-check. No fuzzy/normalized matching — applying a YouTube
    # URL to the wrong movie is a much worse UX than a NO MATCH.
    #
    # Apply writes user_overrides at section_id='' (the title-global
    # row), letting the COALESCE fallback in /api/library serve it
    # to every section without its own per-section override. Per-
    # section overrides are left untouched; they show up in the
    # preview as conflicts so the user picks per-row.

    _IMPORT_HEADER_TITLE = "title"
    _IMPORT_HEADER_IMDB = "imdb"
    _IMPORT_HEADER_YT = "youtube_url"

    def _parse_import_csv(raw_bytes: bytes) -> list[dict]:
        """Return a list of {title, imdb, youtube_url} dicts from the
        uploaded CSV. Tolerates UTF-8 BOM, UTF-16 LE BOM (the export's
        v1.14.26 encoding), and common header casings."""
        # Detect + strip BOM. Export emits UTF-16 LE with BOM (v1.14.26);
        # accept UTF-8 BOM too in case the user re-saved as Excel CSV.
        if raw_bytes[:2] == b"\xff\xfe":
            text = raw_bytes.decode("utf-16")
        elif raw_bytes[:3] == b"\xef\xbb\xbf":
            text = raw_bytes[3:].decode("utf-8")
        else:
            text = raw_bytes.decode("utf-8", errors="replace")
        # v1.21.49: the export now emits TAB-delimited (the UTF-16
        # "Unicode Text" convention spreadsheet apps split into columns;
        # comma-in-UTF-16 dumped every field into column A). Auto-detect
        # off the header line so a user who re-saved as a comma CSV in
        # Excel still round-trips. A tab in the header means tab-delimited;
        # a comma header has no tab (the column names never contain one).
        first_line = text.split("\n", 1)[0] if text else ""
        delimiter = "\t" if "\t" in first_line else ","
        reader = csv.DictReader(io.StringIO(text), delimiter=delimiter)
        if not reader.fieldnames:
            return []
        # Build a header→field map; accept any of "Title"/"title"/
        # "TITLE" etc. and synonyms like "IMDB"/"imdb_id".
        field_aliases = {
            _IMPORT_HEADER_TITLE: ("title",),
            _IMPORT_HEADER_IMDB: ("imdb", "imdb_id", "imdbid"),
            _IMPORT_HEADER_YT: ("youtube_url", "youtube url", "url", "yt"),
        }
        col_map = {}
        for canonical, aliases in field_aliases.items():
            for fn in reader.fieldnames:
                if (fn or "").strip().lower().replace("_", " ") in aliases or \
                   (fn or "").strip().lower() in aliases:
                    col_map[canonical] = fn
                    break
        if _IMPORT_HEADER_IMDB not in col_map:
            return []
        rows = []
        for r in reader:
            title = (r.get(col_map.get(_IMPORT_HEADER_TITLE, ""), "") or "").strip()
            imdb = (r.get(col_map.get(_IMPORT_HEADER_IMDB, ""), "") or "").strip()
            yt = (r.get(col_map.get(_IMPORT_HEADER_YT, ""), "") or "").strip()
            if not imdb and not title:
                continue  # fully blank row
            rows.append({
                "title": title,
                "imdb": imdb,
                "youtube_url": yt,
            })
        return rows

    # v1.15.66: split "Title (Year)" into (title, year). The export
    # emits this combined format; the import accepts it OR a bare
    # title (for hand-written CSVs).
    _IMPORT_TITLE_YEAR_RE = re.compile(r"^(?P<t>.+?)\s*\((?P<y>\d{4})\)\s*$")

    def _import_split_title_year(combined: str) -> tuple[str, Optional[int]]:
        m = _IMPORT_TITLE_YEAR_RE.match(combined)
        if not m:
            return combined.strip(), None
        try:
            return m.group("t").strip(), int(m.group("y"))
        except ValueError:
            return combined.strip(), None

    def _import_match(conn, imdb: str, title: str,
                       year: Optional[int]) -> tuple[str, Optional[dict], bool]:
        """Resolve a CSV row to an apply target. Returns (kind, payload,
        verify) where kind is:

          * "theme"          — payload is the themes row dict, apply
                                writes user_override against it
          * "orphan_pending" — payload is {media_type, imdb_id,
                                plex_items: [...]} for a row that exists
                                in plex_items but has no themes row yet
                                (the NO TDB case — apply must synthesize
                                a plex_orphan theme like manual-url does
                                at api.py:9018-9034)
          * "no_match"       — payload is None

        v1.15.67: the user's test surfaced that 7/9 of his anime CSV
        rows came back NO MATCH — every NO TDB row exports a valid
        IMDB from plex_items but has no themes row to match against.
        The fix mirrors manual-url's two-stage lookup: prefer existing
        themes (TDB-tracked or already-synthetic) but also resolve
        unmatched IMDBs against plex_items so the bulk import can
        create the synthetic theme on apply.

        verify=True means the match came from the title+year fallback
        (user should spot-check); False means exact IMDB."""
        imdb_norm = ""
        if imdb:
            # Strip optional 'tt' prefix sloppiness — IMDB IDs are
            # tt-prefixed; some exports / hand edits may strip it.
            imdb_norm = imdb if imdb.startswith("tt") else f"tt{imdb}"
            # Direct themes match (TDB-tracked or already-synthetic).
            row = conn.execute(
                "SELECT * FROM themes WHERE imdb_id = ? LIMIT 1",
                (imdb_norm,),
            ).fetchone()
            if row:
                return ("theme", dict(row), False)
        if title:
            # Case-insensitive title + year exact match against themes.
            if year is not None:
                row = conn.execute(
                    "SELECT * FROM themes "
                    "WHERE LOWER(TRIM(title)) = LOWER(TRIM(?)) AND year = ? "
                    "LIMIT 1",
                    (title, year),
                ).fetchone()
            else:
                row = conn.execute(
                    "SELECT * FROM themes "
                    "WHERE LOWER(TRIM(title)) = LOWER(TRIM(?)) "
                    "LIMIT 1",
                    (title,),
                ).fetchone()
            if row:
                return ("theme", dict(row), True)
        # No themes match — look in plex_items for the orphan-pending
        # path. By IMDB first, then title+year.
        if imdb_norm:
            pis = conn.execute(
                "SELECT * FROM plex_items WHERE guid_imdb = ?",
                (imdb_norm,),
            ).fetchall()
            if pis:
                pi_rows = [dict(r) for r in pis]
                # plex_items.media_type uses 'show' for TV — translate
                # to the themes-canonical 'tv' so downstream lookups
                # agree. Movies pass through unchanged.
                mt = _motif_media_type(pi_rows[0]["media_type"])
                return ("orphan_pending", {
                    "media_type": mt,
                    "imdb_id": imdb_norm,
                    "plex_items": pi_rows,
                    "title": pi_rows[0]["title"],
                    "year": pi_rows[0]["year"],
                }, False)
        if title:
            if year is not None:
                pis = conn.execute(
                    "SELECT * FROM plex_items "
                    "WHERE LOWER(TRIM(title)) = LOWER(TRIM(?)) AND year = ?",
                    (title, year),
                ).fetchall()
            else:
                pis = conn.execute(
                    "SELECT * FROM plex_items "
                    "WHERE LOWER(TRIM(title)) = LOWER(TRIM(?))",
                    (title,),
                ).fetchall()
            if pis:
                pi_rows = [dict(r) for r in pis]
                mt = _motif_media_type(pi_rows[0]["media_type"])
                # Use the first row's guid_imdb if available (it's the
                # canonical key for synthetic theme creation); else
                # synthesize without imdb_id (manual-url accepts NULL).
                imdb_for_orphan = pi_rows[0].get("guid_imdb") or ""
                return ("orphan_pending", {
                    "media_type": mt,
                    "imdb_id": imdb_for_orphan,
                    "plex_items": pi_rows,
                    "title": pi_rows[0]["title"],
                    "year": pi_rows[0]["year"],
                }, True)
        return ("no_match", None, False)

    def _import_orphan_pending_state(conn, pi_rows: list[dict]) -> dict:
        """Current-state signature for the orphan-pending case (plex_items
        rows exist but no themes row). Mirrors _import_row_current_state's
        per-theme logic but walks plex_items directly since there's no
        theme_id to join through yet. Returns the same shape so the
        categorizer can treat both cases uniformly."""
        any_m = any(
            r.get("local_theme_file") == 1 for r in pi_rows
        )
        any_p = any(
            r.get("has_theme") == 1
            and (r.get("plex_theme_verified_ok") in (None, 1))
            and r.get("local_theme_file") != 1
            for r in pi_rows
        )
        # Orphan-pending means no themes row, so by definition no
        # user_overrides exist (overrides FK on theme tmdb_id, and a
        # synthetic theme hasn't been minted yet). Skip the override
        # lookup.
        # v1.21.34: orphan-pending rows have no themes row yet → no
        # overrides → no staged backup; backup_urls is always [] here
        # (shape parity with _import_row_current_state).
        if any_p:
            return {"current_url": None, "current_src": "P",
                    "override_kind": None, "backup_urls": []}
        if any_m:
            return {"current_url": None, "current_src": "M",
                    "override_kind": None, "backup_urls": []}
        # No M, no P → dash. Bulk apply is clean.
        return {"current_url": None, "current_src": "-",
                "override_kind": None, "backup_urls": []}

    def _import_row_current_state(conn, theme: dict) -> dict:
        """Return {current_url, current_src, override_kind} where
        override_kind ∈ {'global', 'per_section', None}. The src
        letter is computed via the same predicates _SRC_LETTER_SQL
        uses — but per-theme rather than per-row — to avoid having
        to pick a section. If ANY section's row would render as M
        or P, we flag the theme conflict-side; that matches the user's
        "purple !" intent: any user-managed surface in conflict
        means the user should confirm before bulk-overwrite."""
        # v1.21.37: one query for all overrides, partitioned in Python —
        # replaces the prior THREE per-row queries (ovr_bk + ovr_section +
        # ovr_global). Active override (intent != 'backup'): per-section
        # beats global, matching _SRC_LETTER_SQL. ALL backup URLs
        # (intent='backup', ANY section) are collected as a set so the
        # duplicate check matches against any staged backup; the prior
        # single-LIMIT-1 ovr_bk picked an arbitrary backup and ignored
        # per-section ones. The staged backups stay SEPARATE from the
        # active source so a backup never masquerades as the active 'U'
        # (the active stays P/T/A/M/– underneath — the backup is a UB
        # badge, not the served theme), and so a re-import of the same CSV
        # reads DUPLICATE when the row already carries that URL as a backup.
        ov_rows = conn.execute(
            "SELECT youtube_url, intent, section_id FROM user_overrides "
            "WHERE media_type = ? AND tmdb_id = ?",
            (theme["media_type"], theme["tmdb_id"]),
        ).fetchall()
        has_active_section = has_active_global = False
        active_section = active_global = None
        backup_urls: list = []
        for o in ov_rows:
            if (o["intent"] or "replace") == "backup":
                if o["youtube_url"]:
                    backup_urls.append(o["youtube_url"])
            elif o["section_id"] != "":
                if not has_active_section:
                    has_active_section = True
                    active_section = o["youtube_url"]
            else:
                has_active_global = True
                active_global = o["youtube_url"]
        if has_active_section:
            return {
                "current_url": active_section,
                "current_src": "U",
                "override_kind": "per_section",
                "backup_urls": backup_urls,
            }
        if has_active_global:
            return {
                "current_url": active_global,
                "current_src": "U",
                "override_kind": "global",
                "backup_urls": backup_urls,
            }
        # No override → check if any plex_items row would render
        # as M (local_theme_file=1 + no placement) or P (Plex
        # serves a verified theme). The theme is per-(mt, tmdb)
        # so we look up plex_items via pi.theme_id = theme["id"].
        sig = conn.execute(
            """SELECT
                 MAX(CASE WHEN pi.local_theme_file = 1
                       AND COALESCE(p.media_folder, '') = ''
                       THEN 1 ELSE 0 END) AS any_m,
                 MAX(CASE WHEN COALESCE(p.media_folder, '') = ''
                       AND pi.has_theme = 1
                       AND COALESCE(pi.plex_theme_verified_ok, 1) = 1
                       AND pi.local_theme_file != 1
                       THEN 1 ELSE 0 END) AS any_p,
                 MAX(CASE WHEN p.media_folder IS NOT NULL THEN 1 ELSE 0 END) AS any_placed
               FROM plex_items pi
               LEFT JOIN placements p
                 ON p.media_type = ?
                AND p.tmdb_id = ?
                AND p.section_id = pi.section_id
               WHERE pi.theme_id = ?""",
            (theme["media_type"], theme["tmdb_id"], theme["id"]),
        ).fetchone()
        any_m = bool(sig and sig["any_m"])
        any_p = bool(sig and sig["any_p"])
        any_placed = bool(sig and sig["any_placed"])
        # Conflict precedence: P > M > placed (A/T) > none. the user's
        # intent: anything user-managed → conflict (purple !).
        if any_p:
            return {"current_url": None, "current_src": "P",
                    "override_kind": None, "backup_urls": backup_urls}
        if any_m:
            return {"current_url": None, "current_src": "M",
                    "override_kind": None, "backup_urls": backup_urls}
        if any_placed:
            # Could be T or A. We treat T as clean (TDB-managed,
            # safe to override with user URL) and A as conflict
            # (someone adopted a sidecar — needs user confirmation
            # to overwrite). Distinguish by source_kind.
            srcs = conn.execute(
                """SELECT DISTINCT lf.source_kind
                   FROM placements p
                   JOIN plex_items pi
                     ON pi.section_id = p.section_id
                    AND pi.theme_id = ?
                   LEFT JOIN local_files lf
                     ON lf.media_type = p.media_type
                    AND lf.tmdb_id = p.tmdb_id
                    AND lf.section_id = p.section_id
                   WHERE p.media_type = ?
                     AND p.tmdb_id = ?
                     AND p.media_folder IS NOT NULL""",
                (theme["id"], theme["media_type"], theme["tmdb_id"]),
            ).fetchall()
            kinds = {(r["source_kind"] or "") for r in srcs}
            if "adopt" in kinds:
                return {"current_url": theme.get("youtube_url"),
                        "current_src": "A", "override_kind": None,
                        "backup_urls": backup_urls}
            return {"current_url": theme.get("youtube_url"),
                    "current_src": "T", "override_kind": None,
                    "backup_urls": backup_urls}
        # No placement, no Plex theme, no override → dash.
        return {"current_url": theme.get("youtube_url"),
                "current_src": "-", "override_kind": None,
                "backup_urls": backup_urls}

    @app.post("/api/import/preview")
    async def api_import_preview(
        request: Request,
        file: UploadFile = File(...),
        db: Path = Depends(get_db_path),
    ):
        """Parse an uploaded CSV and return categorized preview rows.
        Doesn't write anything — all decisions deferred to /apply."""
        _require_admin(request)
        raw = await file.read()
        if not raw:
            raise HTTPException(status_code=400, detail="empty file")
        if len(raw) > 5 * 1024 * 1024:
            # Bulk import scale: a 200K-row Plex library is a ~10MB
            # CSV; cap at 5MB to keep parse fast and surface obvious
            # mistakes (wrong file type).
            raise HTTPException(status_code=400,
                                detail="file too large (5MB max)")
        # v1.21.50: offload the parse + the per-row categorization (N DB
        # queries) to a worker thread so a large import never blocks the
        # event loop and freezes the WHOLE app. v1.21.49 exposed this —
        # a tab-delimited export now parses into N rows (it returned []
        # + a 400 "no rows" before, so this blocking loop never ran).
        return await run_in_threadpool(_import_preview_work, db, raw)

    def _import_preview_work(db: Path, raw: bytes) -> dict:
        rows = _parse_import_csv(raw)
        if not rows:
            raise HTTPException(
                status_code=400,
                detail="no rows parsed — expected Title,IMDB,Youtube_URL header",
            )

        preview = []
        with get_conn(db) as conn:
            for r in rows:
                title_combined = r["title"]
                imdb = r["imdb"]
                imported_url = r["youtube_url"]
                # v1.15.68: empty Youtube_URL still runs the match
                # so the SKIPPED row can surface its current state.
                # Pre-fix the user saw "Übel Blatt — SKIPPED" with no
                # current_src and asked "we're not matching" — the
                # row WAS being skipped correctly (empty URL = no-op)
                # but the UI couldn't distinguish "matched but no
                # URL" from "didn't match at all." Now matched-but-
                # empty rows show the current src letter; truly-
                # unmatched empty rows fall through to NO MATCH.
                if not imported_url:
                    title_only, year = _import_split_title_year(title_combined)
                    kind, payload, _verify = _import_match(
                        conn, imdb, title_only, year
                    )
                    if kind == "no_match":
                        preview.append({
                            "status": "no_match",
                            "title": title_combined,
                            "imdb": imdb,
                            "imported_url": "",
                            "current_url": None,
                            "current_src": None,
                            "theme_media_type": None,
                            "theme_tmdb_id": None,
                            "imdb_id_for_orphan": None,
                            "verify": False,
                            "default_action": "skip",
                        })
                        continue
                    if kind == "theme":
                        cur = _import_row_current_state(conn, payload)
                    else:  # orphan_pending
                        cur = _import_orphan_pending_state(
                            conn, payload["plex_items"]
                        )
                    preview.append({
                        "status": "skipped",
                        "title": title_combined,
                        "imdb": imdb,
                        "imported_url": "",
                        # Surface current state so the row reads
                        # "this is in your library, no URL to import"
                        # — not "we can't find this row" (NO MATCH).
                        "current_url": cur["current_url"],
                        "current_src": cur["current_src"],
                        "theme_media_type": (
                            payload["media_type"] if kind == "theme"
                            else payload["media_type"]
                        ),
                        "theme_tmdb_id": (
                            payload["tmdb_id"] if kind == "theme" else None
                        ),
                        "imdb_id_for_orphan": (
                            None if kind == "theme" else payload["imdb_id"]
                        ),
                        "verify": False,
                        "default_action": "skip",
                    })
                    continue
                # Sanity-check the URL (yt-dlp will reject garbage).
                src = url_source(imported_url)
                if src == "unknown":
                    preview.append({
                        "status": "invalid_url",
                        "title": title_combined,
                        "imdb": imdb,
                        "imported_url": imported_url,
                        "current_url": None,
                        "current_src": None,
                        "theme_media_type": None,
                        "theme_tmdb_id": None,
                        "imdb_id_for_orphan": None,
                        "verify": False,
                        "default_action": "skip",
                    })
                    continue
                # Match by IMDB primary; title+year fallback. Falls
                # through to plex_items lookup (orphan_pending) for the
                # NO TDB case where Plex sees the row but TDB doesn't
                # have a theme — those need synthetic theme creation
                # on apply (the manual-url pattern at api.py:9018).
                title_only, year = _import_split_title_year(title_combined)
                kind, payload, verify = _import_match(
                    conn, imdb, title_only, year
                )
                if kind == "no_match":
                    preview.append({
                        "status": "no_match",
                        "title": title_combined,
                        "imdb": imdb,
                        "imported_url": imported_url,
                        "current_url": None,
                        "current_src": None,
                        "theme_media_type": None,
                        "theme_tmdb_id": None,
                        "imdb_id_for_orphan": None,
                        "verify": False,
                        "default_action": "skip",
                    })
                    continue
                # Resolve current state. Orphan-pending walks plex_items
                # directly; theme path walks via pi.theme_id.
                if kind == "theme":
                    cur = _import_row_current_state(conn, payload)
                    target_mt = payload["media_type"]
                    target_tmdb = payload["tmdb_id"]
                    target_imdb_for_orphan = None
                else:  # orphan_pending
                    cur = _import_orphan_pending_state(
                        conn, payload["plex_items"]
                    )
                    target_mt = payload["media_type"]
                    target_tmdb = None
                    target_imdb_for_orphan = payload["imdb_id"]
                # Categorize:
                #   * matched URL == current URL  → DUPLICATE (no-op)
                #   * current src is T or –       → CLEAN apply
                #   * current src is U with diff  → CONFLICT
                #   * current src is A/M/P        → CONFLICT
                # v1.15.73: split DUPLICATE out of CLEAN. Pre-fix,
                # rows where the imported URL exactly matched the
                # existing user URL rendered as "CLEAN — Skip
                # (no-op)" which the user flagged as confusing:
                # "when status is Clean and action is skip because
                # it's an identical import then status should be
                # something like duplicate or identical match or
                # something that shows that the same theme already
                # exists in motif." A distinct status makes the
                # no-op outcome legible at a glance.
                # v1.21.34: a row whose imported URL matches its ACTIVE
                # url OR its staged BACKUP url is a no-op DUPLICATE. The
                # backup arm makes re-importing the same CSV (after a
                # prior "download as backup") read DUPLICATE instead of
                # re-staging the same backup — the user's request.
                # v1.21.36: canonicalize the imported URL the SAME way
                # apply does BEFORE the match-compare, so re-importing the
                # same theme in a non-canonical form (youtu.be/VID, extra
                # params) still reads DUPLICATE against the stored
                # (canonical) url. Pre-fix dedup only worked for the
                # EXPORT-CSV round-trip (already canonical); a hand-
                # authored youtu.be CSV re-staged the backup every time.
                _imp_vid = extract_video_id(imported_url)
                imp = (
                    f"https://www.youtube.com/watch?v={_imp_vid}"
                    if src == "youtube" and _imp_vid
                    else imported_url
                ).strip()
                # v1.21.37: match against the SET of all staged backups
                # (any section), not a single arbitrary one.
                backup_set = {
                    (u or "").strip() for u in cur.get("backup_urls", [])
                }
                if (cur["current_url"]
                        and cur["current_url"].strip() == imp) \
                        or (imp in backup_set):
                    status_kind = "duplicate"
                    default_action = "skip"  # no-op
                elif cur["current_src"] in ("T", "-"):
                    status_kind = "clean"
                    default_action = "replace"
                elif cur["current_src"] == "P" and target_mt in ("movie", "tv"):
                    # v1.21.34: P-rows (Plex already serving its own
                    # theme) default to "download as backup" — stage the
                    # import as a UB backup, leave Plex serving. the user's
                    # call: only P-rows flip the default; U/A/M keep
                    # 'keep current' so an existing user-managed theme
                    # isn't silently shadowed.
                    # v1.21.36: gated on target_mt ∈ (movie,tv) — apply
                    # rejects other media_types, so a collection P-row
                    # (reachable via a title-collision theme match) must
                    # stay at the safe 'keep' no-op rather than offer an
                    # un-appliable download_only (dead-end → errors[]).
                    status_kind = "conflict"
                    default_action = "download_only"
                else:
                    status_kind = "conflict"
                    default_action = "keep"
                preview.append({
                    "status": status_kind,
                    "title": title_combined,
                    "imdb": imdb,
                    "imported_url": imported_url,
                    "current_url": cur["current_url"],
                    "current_src": cur["current_src"],
                    "theme_media_type": target_mt,
                    "theme_tmdb_id": target_tmdb,
                    "imdb_id_for_orphan": target_imdb_for_orphan,
                    "verify": verify,
                    "default_action": default_action,
                })

        # Summary counts so the UI can paint header chips.
        # v1.15.73: 'duplicate' joined the set when identical-URL
        # rows split out of CLEAN — keep all 6 zero-initialized so
        # the UI doesn't have to defensively-check for missing keys.
        counts = {"clean": 0, "conflict": 0, "duplicate": 0,
                  "no_match": 0, "skipped": 0, "invalid_url": 0}
        for p in preview:
            counts[p["status"]] = counts.get(p["status"], 0) + 1
        return {"rows": preview, "counts": counts}

    @app.post("/api/import/apply")
    async def api_import_apply(
        request: Request,
        db: Path = Depends(get_db_path),
    ):
        """Apply a resolved batch from the preview. Each decision must
        carry imported_url, action, theme_media_type, AND either
        theme_tmdb_id (for an existing theme) OR imdb_id_for_orphan
        (for the synthetic plex_orphan creation path — used by the
        NO TDB rows where Plex has the row but TDB doesn't have a
        theme yet). Action ∈ {'replace', 'keep', 'skip'}; keep + skip
        are no-ops at this layer.

        v1.15.67: orphan_pending support added — pre-fix, bulk-importing
        anime / TV-shows-not-in-TDB came back NO MATCH because the
        match path only walked themes. Now mirrors manual-url's
        synthesize-on-write pattern (api.py:9018) so the bulk path
        agrees with the per-row SET URL path for orphan rows."""
        _require_admin(request)
        try:
            body = await request.json()
        except Exception:
            raise HTTPException(status_code=400, detail="invalid JSON body")
        decisions = (body or {}).get("decisions") or []
        if not isinstance(decisions, list) or not decisions:
            raise HTTPException(status_code=400, detail="decisions[] required")
        if len(decisions) > 5000:
            # Same protective cap as preview's 5MB; 5000 decisions is
            # already a very large bulk action.
            raise HTTPException(status_code=400,
                                detail="too many decisions (5000 max)")

        applied = 0
        skipped = 0
        errors = []
        with get_conn(db) as conn, transaction(conn):
            for i, d in enumerate(decisions):
                action = (d or {}).get("action") or "skip"
                if action in ("keep", "skip"):
                    skipped += 1
                    continue
                if action != "replace":
                    errors.append({"index": i, "error": f"unknown action {action!r}"})
                    skipped += 1
                    continue
                mt = (d or {}).get("theme_media_type")
                tmdb_id = (d or {}).get("theme_tmdb_id")
                imdb_for_orphan = (d or {}).get("imdb_id_for_orphan") or ""
                url = (d or {}).get("imported_url") or ""
                if mt not in ("movie", "tv") or not url:
                    errors.append({"index": i,
                                   "error": "bad theme_media_type / url"})
                    skipped += 1
                    continue
                if tmdb_id is None and not imdb_for_orphan:
                    errors.append({"index": i,
                                   "error": "decision missing both theme_tmdb_id and imdb_id_for_orphan"})
                    skipped += 1
                    continue
                # Canonicalize the URL the same way manual-url does so
                # this import + manual-url produce identical user_overrides
                # entries (yt-dlp routing parity).
                src_of_url = url_source(url)
                if src_of_url == "unknown":
                    errors.append({"index": i, "error": "invalid URL"})
                    skipped += 1
                    continue
                vid = extract_video_id(url)
                if not vid:
                    errors.append({"index": i, "error": "could not parse URL"})
                    skipped += 1
                    continue
                if src_of_url == "youtube":
                    canonical_url = f"https://www.youtube.com/watch?v={vid}"
                else:
                    canonical_url = url
                # Two paths: existing theme (theme_tmdb_id set) or
                # synthesize on the fly (imdb_id_for_orphan set, no
                # themes row yet). Re-check both possibilities against
                # the live DB — a prior decision in this same batch
                # may have minted a theme that subsequent decisions
                # for the same IMDB can reuse.
                theme = None
                if isinstance(tmdb_id, int):
                    theme = conn.execute(
                        "SELECT id, tmdb_id FROM themes "
                        "WHERE media_type = ? AND tmdb_id = ?",
                        (mt, tmdb_id),
                    ).fetchone()
                if theme is None and imdb_for_orphan:
                    # See if a theme already exists for this IMDB (could
                    # be a stale preview, or another decision in this
                    # batch already created the synthetic).
                    theme = conn.execute(
                        "SELECT id, tmdb_id FROM themes WHERE imdb_id = ? LIMIT 1",
                        (imdb_for_orphan,),
                    ).fetchone()
                if theme is None and imdb_for_orphan:
                    # Synthesize a plex_orphan theme — mirrors manual-url
                    # at api.py:9018-9034. Find next-lower negative
                    # tmdb_id for this media_type so synthetic IDs
                    # don't collide with real ones (which are always
                    # positive).
                    pis = conn.execute(
                        "SELECT * FROM plex_items WHERE guid_imdb = ?",
                        (imdb_for_orphan,),
                    ).fetchall()
                    if not pis:
                        errors.append({
                            "index": i,
                            "error": f"orphan synth: no plex_items for {imdb_for_orphan}",
                        })
                        skipped += 1
                        continue
                    row = conn.execute(
                        "SELECT MIN(tmdb_id) AS lo FROM themes "
                        "WHERE media_type = ? AND tmdb_id < 0",
                        (mt,),
                    ).fetchone()
                    min_tmdb = row["lo"] if row and row["lo"] is not None else 0
                    new_tmdb = min(min_tmdb, 0) - 1
                    seed_pi = pis[0]
                    cur = conn.execute(
                        """INSERT INTO themes
                             (media_type, tmdb_id, imdb_id, title, year,
                              upstream_source, last_seen_sync_at, first_seen_sync_at)
                           VALUES (?, ?, ?, ?, ?, 'plex_orphan', ?, ?)""",
                        (mt, new_tmdb, imdb_for_orphan,
                         seed_pi["title"], seed_pi["year"],
                         now_iso(), now_iso()),
                    )
                    new_theme_id = cur.lastrowid
                    # Stamp pi.theme_id on every matching plex_items row
                    # so the library JOIN picks them up immediately (same
                    # v1.11.64 fix manual-url applies). Walk by IMDB so
                    # multi-section themes get linked too.
                    conn.execute(
                        "UPDATE plex_items SET theme_id = ? WHERE guid_imdb = ?",
                        (new_theme_id, imdb_for_orphan),
                    )
                    # Re-fetch the freshly-minted row in the canonical
                    # shape the rest of the loop expects.
                    theme = conn.execute(
                        "SELECT id, tmdb_id FROM themes WHERE id = ?",
                        (new_theme_id,),
                    ).fetchone()
                if theme is None:
                    errors.append({"index": i, "error": "theme not found"})
                    skipped += 1
                    continue
                # Reassign tmdb_id to whatever the (possibly newly-minted)
                # theme row uses, so the override write + audit + download
                # enqueue all reference the correct row.
                tmdb_id = theme["tmdb_id"]
                # Capture previous URL into previous_urls (section_id='')
                # BEFORE the override upsert overwrites current state.
                # Same mechanism as the manual-url endpoint, scoped to
                # the global section so REVERT works after a bulk import.
                # v1.21.34: derive the override INTENT from force_place.
                # force_place=false is the "download as backup" variant
                # (P-row default since v1.21.34): stage the URL as a UB
                # backup (intent='backup') + download without placing, so
                # the active theme (Plex's, on a P-row) keeps serving and
                # PROMOTE TO ACTIVE can deploy the backup later. Within
                # import, force_place=false ONLY comes from the
                # download_only action, so this mapping is unambiguous.
                force_place = (d or {}).get("force_place")
                if force_place is None:
                    force_place = True
                ovr_intent = "replace" if force_place else "backup"
                ovr_note = ("bulk-imported backup URL" if not force_place
                            else "bulk-imported user URL")
                _capture_previous_url(conn, mt, tmdb_id, section_id="")
                prior_override = conn.execute(
                    "SELECT youtube_url FROM user_overrides "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ''",
                    (mt, tmdb_id),
                ).fetchone()
                conn.execute(
                    """INSERT INTO user_overrides (media_type, tmdb_id, youtube_url,
                                                   set_at, set_by, note, intent, section_id)
                       VALUES (?, ?, ?, ?, ?, ?, ?, '')
                       ON CONFLICT(media_type, tmdb_id, section_id, edition_key) DO UPDATE SET
                           youtube_url = excluded.youtube_url,
                           set_at = excluded.set_at,
                           set_by = excluded.set_by,
                           note = excluded.note,
                           intent = excluded.intent""",
                    (mt, tmdb_id, canonical_url, now_iso(),
                     request.state.user, ovr_note, ovr_intent),
                )
                _record_audit(
                    conn, actor=request.state.user, action="set_url",
                    media_type=mt, tmdb_id=tmdb_id, section_id="",
                    details={
                        "old_url": prior_override["youtube_url"] if prior_override else None,
                        "new_url": canonical_url,
                        "intent": ovr_intent,
                        "source": "import",
                    },
                )
                # v1.18.83: also emit the canonical "Manual URL set
                # by admin" log_event so future cascade-recovery via
                # the v1.18.10 walker covers bulk imports too. Pre-
                # v1.18.83 the bulk path wrote ONLY to audit_events
                # (action='set_url', source='import') and v1.18.10's
                # walker (which scans `events` for "Manual URL set
                # by admin:%") missed them entirely — the user's 17
                # bulk-imported anime rows lost their U attribution
                # in the v1.18.0/.10 cascade and were unrecoverable
                # by the existing walker. Emitting the log_event
                # here gives belt-and-suspenders coverage: both
                # walkers (v1.18.10 events-based + v1.18.83 audit_
                # events-based) can recover the same row, idempotent
                # via the existing-row guard in each.
                log_event(
                    db, level="INFO", component="api",
                    media_type=mt, tmdb_id=tmdb_id, section_id="",
                    message=(
                        f"Manual URL set by {request.state.user}: "
                        f"{canonical_url}"
                    ),
                    detail={"source": "import",
                            "imdb_id": imdb_for_orphan or None},
                )
                # Cancel any in-flight downloads + enqueue a fresh one
                # per matching plex_items section. _enqueue_download
                # has section-resolution quirks for synthetic orphan
                # tmdb_ids (see v1.11.15 in manual-url) so we walk
                # plex_items.theme_id directly to find sections.
                conn.execute(
                    "UPDATE jobs SET status = 'cancelled', finished_at = ? "
                    "WHERE job_type = 'download' AND media_type = ? AND tmdb_id = ? "
                    "  AND status IN ('pending','failed')",
                    (now_iso(), mt, tmdb_id),
                )
                sections = conn.execute(
                    "SELECT DISTINCT pi.section_id FROM plex_items pi "
                    "WHERE pi.theme_id = ? AND pi.section_id IS NOT NULL",
                    (theme["id"],),
                ).fetchall()
                # v1.15.71: force_place defaults True (the standard
                # bulk-import behavior: download AND place over any
                # existing theme). When the preview row was a P-row
                # CONFLICT and the user picked "Download backup (Plex
                # stays)", the JS sends action=replace + force_place=
                # false so the user_overrides write + download fire
                # but the placement step is skipped — Plex keeps
                # serving its own theme, motif has the backup ready
                # for a manual PUSH later.
                # v1.21.34: force_place is derived once above (before the
                # override write) so intent='backup' can be stamped on
                # the UB row; reuse that value here for the job payload.
                # v1.21.36: the force_place=false (backup) variant uses a
                # DISTINCT reason 'bulk_import_backup' that the worker's
                # backup_only-stamp whitelist recognizes. Pre-fix the
                # generic 'bulk_import' reason was NOT whitelisted, so
                # when auto_place was off the download landed UNstamped —
                # no UB badge AND the hourly retry sweep re-enqueued place
                # jobs forever (defeating the P-preservation this feature
                # exists for). force_place=true keeps 'bulk_import' (it
                # forces auto_place=True → a real place job, never the
                # whitelist branch).
                payload = {
                    "reason": ("bulk_import_backup" if not force_place
                               else "bulk_import"),
                    "force_place": bool(force_place),
                    "bulk": True,  # v1.23.46: CSV import → one list
                }
                for s in sections:
                    conn.execute(
                        "INSERT INTO jobs (job_type, media_type, tmdb_id, section_id, "
                        "                  payload, status, created_at, next_run_at) "
                        "VALUES ('download', ?, ?, ?, ?, 'pending', ?, ?)",
                        (mt, tmdb_id, s["section_id"], json.dumps(payload),
                         now_iso(), now_iso()),
                    )
                applied += 1

        log_event(db, level="INFO", component="api",
                  message=f"Bulk import by {request.state.user}: "
                          f"{applied} applied, {skipped} skipped, "
                          f"{len(errors)} errors")
        return {"ok": True, "applied": applied, "skipped": skipped,
                "errors": errors}

    @app.post("/api/libraries/{section_id}/refresh")
    async def api_libraries_section_refresh(
        request: Request, section_id: str,
        db: Path = Depends(get_db_path),
    ):
        """Re-enumerate a single Plex section. Lighter than the global plex_enum
        (which walks every managed section). Useful when a particular library
        had recent additions and the user wants the unified view to reflect
        them without waiting for the next sync."""
        _require_admin(request)
        # v1.23.69 (audit): BEGIN IMMEDIATE around the per-section dedup SELECT +
        # INSERT so two // REFRESH clicks on the same section can't both miss the
        # in-flight plex_enum and double-enqueue — its twin api_library_refresh
        # was already wrapped (v1.13.23); this per-section sibling was missed.
        with get_conn(db) as conn, transaction(conn):
            row = conn.execute(
                "SELECT type, included FROM plex_sections WHERE section_id = ?",
                (section_id,),
            ).fetchone()
            if row is None:
                raise HTTPException(status_code=404, detail="section not found")
            if not row["included"]:
                raise HTTPException(status_code=409,
                                    detail="section is not managed (toggle MGD first)")
            # v1.13.23: scope dedupe to THIS section only. Pre-fix any
            # pending/running plex_enum (a /tv refresh, a sync cascade)
            # would silently no-op a /movies per-section refresh —
            # confusing now that the UI lets the user fire concurrent
            # per-tab scans (lock-scope split in app.js refreshTopbarStatus).
            existing = conn.execute(
                "SELECT id FROM jobs WHERE job_type = 'plex_enum' "
                "AND status IN ('pending','running') "
                "AND json_extract(payload, '$.section_id') = ?",
                (section_id,),
            ).fetchone()
            if existing:
                return {"ok": True, "job_id": existing["id"], "already_queued": True}
            cur = conn.execute(
                "INSERT INTO jobs (job_type, payload, status, created_at, next_run_at) "
                "VALUES ('plex_enum', ?, 'pending', ?, ?)",
                # v0.51.129: user-initiated refresh forces a full enum (bypass
                # the contentChangedAt-skip) so the v0.51.128 reaper can reap a
                # removed item + clear phantom-P on demand.
                (json.dumps({"section_id": section_id, "force": True}),
                 now_iso(), now_iso()),
            )
        log_event(db, level="INFO", component="api",
                  message=f"Per-section refresh ({section_id}) by {request.state.user}")
        return {"ok": True, "job_id": cur.lastrowid}

    @app.post("/api/library/refresh")
    async def api_library_refresh(request: Request, db: Path = Depends(get_db_path)):
        """Manually enqueue a plex_enum job (refresh the unified browse cache).

        v1.10.6: optional body {"tab": "movies|tv|anime|collections", "fourk": bool}
        narrows the refresh to sections that back the requested tab so the
        REFRESH FROM PLEX button on /movies?fourk=1 only re-enumerates
        movie+4k sections. Body absent → full refresh (legacy behavior).
        """
        _require_admin(request)
        # v1.15.35: raise on JSON parse failure rather than coercing
        # to {}. Pre-fix a malformed body silently fell through to
        # the legacy global-refresh branch — the user thought they
        # were narrowing the refresh by tab/fourk and got a full
        # rescan instead, with no error indication.
        try:
            body = await request.json() if (await request.body()) else {}
        except Exception as e:
            raise HTTPException(
                status_code=400,
                detail=f"invalid JSON body: {e}",
            )
        tab = body.get("tab")
        fourk = bool(body.get("fourk"))
        # v0.51.21: when the // ALL resolution chip is active the refresh must
        # re-enumerate BOTH the standard and 4K sections (not just one), so the
        # combined view is fully refreshed.
        all_res = bool(body.get("all_res"))
        # v1.13.28: validate `tab` up front. Pre-fix the body's tab
        # could be any value — non-None/non-allowlisted values fell
        # through both branches and hit the legacy global insert at
        # the bottom, bypassing dedupe and queueing duplicate global
        # plex_enum jobs even when one was already pending. The
        # legitimate "scan everything" path is body-absent (tab is
        # None); a body-present-but-wrong tab is a client bug worth
        # 400ing on.
        if tab is not None and tab not in ("movies", "tv", "anime", "collections"):
            raise HTTPException(
                status_code=400,
                detail=f"unknown tab {tab!r}; expected 'movies', 'tv', 'anime', 'collections', or omit",
            )

        with get_conn(db) as conn, transaction(conn):
            # v1.13.23: scope dedupe per-section. Pre-fix any
            # pending/running plex_enum globally short-circuited THIS
            # endpoint, so a /movies SYNC PLEX click during a /tv
            # enum silently returned already_queued and the user's
            # action did nothing. Now we let the per-tab branch below
            # filter out only the sections that already have an
            # in-flight job, mirroring /api/libraries/refresh.
            # Legacy global-refresh (no tab) keeps the old global
            # short-circuit since its purpose IS "scan everything".
            if tab is None:
                existing = conn.execute(
                    "SELECT id FROM jobs WHERE job_type = 'plex_enum' "
                    "AND status IN ('pending','running')"
                ).fetchone()
                if existing:
                    return {"ok": True, "job_id": existing["id"], "already_queued": True}

            if tab in ("movies", "tv", "anime", "collections"):
                # Map tab → section predicate, mirroring the /api/library
                # tab_where logic. Anime is purely flag-driven; Movies/TV
                # exclude anime-flagged sections.
                # v1.18.0: 'collections' enqueues plex_enum on every
                # included section since collections live within
                # parent movie/show sections; the enum-side
                # collection-walk loop discriminates by Plex's
                # /library/sections/{id}/collections response, so all
                # eligible sections get visited regardless of type.
                if tab == "movies":
                    sec_where = "type = 'movie' AND is_anime = 0"
                elif tab == "tv":
                    sec_where = "type = 'show' AND is_anime = 0"
                elif tab == "collections":
                    sec_where = "1=1"
                else:
                    sec_where = "is_anime = 1"
                # v1.12.1: try the requested variant first, then fall
                # back to the other one. Pre-fix a /movies tab with
                # only 4K Movies enabled (or only standard) returned
                # 'no managed sections' silently when REFRESH FROM
                # PLEX shipped fourk=false, leaving the user staring
                # at an empty page with a button that did nothing.
                # Now we route to whichever variant actually exists.
                requested_4k = 1 if fourk else 0
                fallback_4k = 0 if fourk else 1
                # v1.18.0: collections aren't 4K-tagged at the Plex
                # level, so the requested_4k filter is meaningless
                # for the collections tab — enqueue plex_enum across
                # every included section regardless of 4K flag.
                if tab == "collections" or all_res:
                    # v0.51.21: // ALL (or collections, which are never
                    # 4K-tagged) → every section for this tab regardless of
                    # the is_4k flag, so both resolutions get re-enumerated.
                    sections = conn.execute(
                        f"SELECT section_id FROM plex_sections "
                        f"WHERE included = 1 AND {sec_where}"
                    ).fetchall()
                    used_fallback = False
                else:
                    sections = conn.execute(
                        f"SELECT section_id FROM plex_sections "
                        f"WHERE included = 1 AND {sec_where} "
                        f"  AND is_4k = {requested_4k}"
                    ).fetchall()
                    used_fallback = False
                    if not sections:
                        sections = conn.execute(
                            f"SELECT section_id FROM plex_sections "
                            f"WHERE included = 1 AND {sec_where} "
                            f"  AND is_4k = {fallback_4k}"
                        ).fetchall()
                        used_fallback = bool(sections)
                if not sections:
                    return {"ok": True, "enqueued": 0,
                            "note": f"no managed Plex sections match the {tab} tab"}
                # v1.18.0: collections skip the 4K fallback entirely
                # (the requested_4k branch above never ran for them).
                if tab == "collections":
                    effective_fourk = False
                else:
                    effective_fourk = (
                        (fallback_4k == 1) if used_fallback else fourk
                    )
                # v1.13.23: skip sections that already have a
                # pending/running plex_enum so a click during another
                # tab's scan only queues the new sections, mirroring
                # /api/libraries/refresh's per-section dedupe.
                pending_section_ids = {
                    r["section_id"] for r in conn.execute(
                        "SELECT json_extract(payload, '$.section_id') AS section_id "
                        "FROM jobs WHERE job_type = 'plex_enum' "
                        "AND status IN ('pending','running')"
                    ).fetchall() if r["section_id"] is not None
                }
                ids: list[int] = []
                for s in sections:
                    sid = s["section_id"]
                    if sid in pending_section_ids:
                        continue
                    # v1.18.4: collections refresh enqueues plex_enum
                    # jobs with collections_only=true so the worker
                    # skips the /library/sections/{id}/all walk
                    # entirely and only refreshes the section's
                    # collection rows. Cuts wall-clock by ~10× on
                    # libraries with thousands of movies/shows but
                    # only hundreds of collections per section.
                    # v0.51.21: // ALL enumerates both sections — tag every
                    # job 'scope: <tab>-all' so the topbar reads
                    # "REFRESHING ALL MOVIES" for the whole combined refresh.
                    _scope = (
                        f"{tab}-all" if (all_res and tab != "collections")
                        else f"{tab}{'-4k' if effective_fourk else ''}"
                    )
                    job_payload: dict = {
                        "section_id": sid,
                        "scope": _scope,
                        # v0.51.129: REFRESH FROM PLEX forces a full enum so the
                        # v0.51.128 reaper miss-counter advances on demand.
                        "force": True,
                    }
                    if tab == "collections":
                        job_payload["collections_only"] = True
                    # v1.23.77: a library-tab refresh (movies/tv/anime REFRESH
                    # FROM PLEX) only re-enumerates that library's items, NOT
                    # its collections — the user: refreshing a library shouldn't
                    # also rescan its collections. Collections stay refreshable
                    # from the /collections tab (collections_only) and the full
                    # "scan everything" (no tab) + nightly cron still do both.
                    elif tab in ("movies", "tv", "anime"):
                        job_payload["skip_collections"] = True
                    cur = conn.execute(
                        "INSERT INTO jobs (job_type, payload, status, created_at, next_run_at) "
                        "VALUES ('plex_enum', ?, 'pending', ?, ?)",
                        (json.dumps(job_payload), now_iso(), now_iso()),
                    )
                    ids.append(cur.lastrowid)
                return {"ok": True, "enqueued": len(ids), "job_ids": ids,
                        "scope": f"{tab}{'-4k' if effective_fourk else ''}",
                        "fallback_used": used_fallback}

            # Legacy global refresh (no tab specified) — a full "scan
            # everything" incl. collections.
            # v0.51.65 (code-review): tag it scope='scan_all' (was an untagged
            # '{}' payload) so it's covered by the pipeline lock machinery, same
            # as /api/libraries/refresh. Pre-fix an untagged global job matched
            # NEITHER the collections-scoped count (v0.51.63) NOR the
            # scan_all/cascade pipeline signal, so a raw-API global refresh left
            # the /collections REFRESH button clickable mid-scan (the button no
            # longer locks on "any enum"). Not UI-reachable — the refresh button
            # always sends a concrete tab — but this closes the supported-endpoint
            # hole generically.
            cur = conn.execute(
                "INSERT INTO jobs (job_type, payload, status, created_at, next_run_at) "
                "VALUES ('plex_enum', ?, 'pending', ?, ?)",
                # v0.51.129: manual "scan everything" forces a full enum on every
                # section so the v0.51.128 reaper can reap removed items on demand.
                (json.dumps({"scope": "scan_all", "force": True}),
                 now_iso(), now_iso()),
            )
            return {"ok": True, "job_id": cur.lastrowid}

    # v1.14.41: removed `@app.get("/api/items")` LIST endpoint
    # (audit M1). Was the legacy "Browse" page's data source —
    # had a 4-query N+1 in its row loop (up to 800 queries per
    # 200-row page). The page itself (browse.html) was retired
    # when /movies, /tv, /anime took over the library view via
    # /api/library; the GET /api/items endpoint stayed orphaned.
    # Only caller was loadItems() in app.js, also dead. Both
    # deleted in this tag along with browse.html, browseState,
    # bindBrowse(). The single-item endpoint
    # `/api/items/{media_type}/{tmdb_id}` (just below) is alive
    # — INFO card depends on it.

    @app.get("/api/items/{media_type}/{tmdb_id}")
    async def api_item(
        media_type: MediaType, tmdb_id: int,
        # v1.12.72: optional section_id picks which section's
        # override to surface in the legacy `override` field.
        # Without it, the response uses the per-title query that
        # may return any matching row when multiple per-section
        # overrides exist. Pass section_id from row clicks so the
        # INFO card's "currently applied" matches what the worker
        # would use for that section.
        section_id: str | None = Query(None),
        # v1.21.68: the clicked row's rating_key resolves WHICH edition's
        # state the card shows. Pre-fix api_item scoped by section only, so
        # opening INFO on any edition of a multi-edition title surfaced an
        # ARBITRARY edition's downloaded/placed-in paths, applied URL, and
        # {edition-X} tag (the user: every card showed "edition: Sam Takes a
        # Step"). None = legacy section-only behavior (no rk sent).
        rating_key: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        # v1.23.19: the card's 39 indexed reads run off the
        # event loop (run_in_threadpool) so opening an INFO card
        # no longer waits behind — or contributes to — background
        # sync/enum/download work blocking the single loop
        # (class-12). The body is await-free + pure-DB, so the
        # wrap is mechanical; behaviour is identical.
        def _build():
            with get_conn(db) as conn:
                t = conn.execute(
                    "SELECT * FROM themes WHERE media_type = ? AND tmdb_id = ?",
                    (media_type, tmdb_id),
                ).fetchone()
                if t is None:
                    raise HTTPException(status_code=404, detail="not found")
                # v1.21.68: resolve the clicked edition once. '' = standard
                # edition (un-tagged folder); None = no rk sent → legacy
                # section-only reads (every narrowing below is gated on
                # `_info_edition is not None`, so legacy callers are unchanged).
                _info_edition = (
                    edition_key_for_rating_key(conn, rating_key)
                    if rating_key else None)
                # v1.22.7 (code-review): gate the '' read-fallbacks below on this
                # title+section having exactly ONE edition — mirrors the
                # api_unplace_item WRITE gate (v1.21.95). Pre-fix the INFO card fell
                # back to the shared '' local_files/placements on a tagged edition
                # with no own row even for MULTI-edition titles, so the card showed
                # "downloaded in … / placed: hardlink" for an edition that LPS then
                # WITHHOLDS (the v1.21.95 write gate) — the read claimed placed, the
                # write no-op'd (the user's Watchmen "card says placed, LPS does 0/0").
                _info_plex_type = "show" if media_type == "tv" else media_type
                _info_single_edition = bool(
                    section_id and _info_edition not in (None, "")
                    and conn.execute(
                        "SELECT COUNT(DISTINCT edition_key) FROM plex_items "
                        "WHERE guid_tmdb = ? AND section_id = ? AND media_type = ?",
                        (tmdb_id, section_id, _info_plex_type),
                    ).fetchone()[0] == 1)
                # v1.11.0: per-section local_files — return the list so the
                # UI can render one row per section. legacy `local_file`
                # field still emitted (first row, or null) for older callers.
                # v1.12.81: scope local_files + placements to the requested
                # section_id when provided. Pre-fix opening INFO on a
                # standard-section row whose 4K sibling still had a
                # canonical / placement showed the 4K paths in the
                # "downloaded" / "placed in" rows because the queries
                # returned all sections' files and the legacy `local_file`
                # field grabbed local_files[0]. Filtering here keeps the
                # card honest — the user sees exactly what's at this row's
                # section. Without section_id (legacy callers) the
                # unfiltered query stays.
                if section_id and _info_edition is not None:
                    # v1.21.68: scope to the clicked edition, preferring its own
                    # rows and falling back to the shared '' rows (mirrors the
                    # library two-join). Keeps "downloaded" / "placed in" honest
                    # per edition instead of showing a sibling's paths.
                    local_files = conn.execute(
                        "SELECT * FROM local_files "
                        "WHERE media_type = ? AND tmdb_id = ? AND section_id = ? "
                        "  AND edition_key = ?",
                        (media_type, tmdb_id, section_id, _info_edition),
                    ).fetchall()
                    if not local_files and _info_edition != "" and _info_single_edition:
                        local_files = conn.execute(
                            "SELECT * FROM local_files "
                            "WHERE media_type = ? AND tmdb_id = ? AND section_id = ? "
                            "  AND edition_key = ''",
                            (media_type, tmdb_id, section_id),
                        ).fetchall()
                    placements = conn.execute(
                        "SELECT * FROM placements "
                        "WHERE media_type = ? AND tmdb_id = ? AND section_id = ? "
                        "  AND edition_key = ? ORDER BY media_folder",
                        (media_type, tmdb_id, section_id, _info_edition),
                    ).fetchall()
                    if not placements and _info_edition != "" and _info_single_edition:
                        placements = conn.execute(
                            "SELECT * FROM placements "
                            "WHERE media_type = ? AND tmdb_id = ? AND section_id = ? "
                            "  AND edition_key = '' ORDER BY media_folder",
                            (media_type, tmdb_id, section_id),
                        ).fetchall()
                elif section_id:
                    local_files = conn.execute(
                        "SELECT * FROM local_files "
                        "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?",
                        (media_type, tmdb_id, section_id),
                    ).fetchall()
                    placements = conn.execute(
                        "SELECT * FROM placements "
                        "WHERE media_type = ? AND tmdb_id = ? AND section_id = ? "
                        "ORDER BY media_folder",
                        (media_type, tmdb_id, section_id),
                    ).fetchall()
                else:
                    local_files = conn.execute(
                        "SELECT * FROM local_files WHERE media_type = ? AND tmdb_id = ? "
                        "ORDER BY section_id",
                        (media_type, tmdb_id),
                    ).fetchall()
                    placements = conn.execute(
                        "SELECT * FROM placements WHERE media_type = ? AND tmdb_id = ? "
                        "ORDER BY section_id, media_folder",
                        (media_type, tmdb_id),
                    ).fetchall()
                # v1.12.72: prefer the section-specific override row when
                # section_id is provided; fall back to global ('') row.
                # v1.12.81: dropped the "any-section LIMIT 1" final
                # fallback when section_id is specified. Pre-fix, opening
                # INFO on a 4K row that has no override of its own surfaced
                # the standard section's override (or any sibling's),
                # making "currently applied" render in violet on a row
                # whose canonical was sourced from TDB. The worker never
                # cross-pollinates either — it only reads the row's own
                # section_id and the '' global. Mirror that here so
                # "currently applied" reflects what's actually applied.
                # The any-section fallback survives only when section_id
                # is NULL (legacy callers without row context).
                ovr = None
                if section_id and _info_edition is not None:
                    # v1.21.68: edition-first applied-override resolution,
                    # mirroring the library's applied_youtube_url tiers:
                    # (section, edition) → (section, '') → ('' global).
                    ovr = conn.execute(
                        "SELECT * FROM user_overrides "
                        "WHERE media_type = ? AND tmdb_id = ? AND section_id = ? "
                        "  AND edition_key = ?",
                        (media_type, tmdb_id, section_id, _info_edition),
                    ).fetchone()
                    if ovr is None and _info_edition != "":
                        ovr = conn.execute(
                            "SELECT * FROM user_overrides "
                            "WHERE media_type = ? AND tmdb_id = ? AND section_id = ? "
                            "  AND edition_key = ''",
                            (media_type, tmdb_id, section_id),
                        ).fetchone()
                    if ovr is None:
                        ovr = conn.execute(
                            "SELECT * FROM user_overrides "
                            "WHERE media_type = ? AND tmdb_id = ? AND section_id = '' "
                            "  AND edition_key = ''",
                            (media_type, tmdb_id),
                        ).fetchone()
                elif section_id:
                    ovr = conn.execute(
                        "SELECT * FROM user_overrides "
                        "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?",
                        (media_type, tmdb_id, section_id),
                    ).fetchone()
                    if ovr is None:
                        ovr = conn.execute(
                            "SELECT * FROM user_overrides "
                            "WHERE media_type = ? AND tmdb_id = ? AND section_id = ''",
                            (media_type, tmdb_id),
                        ).fetchone()
                else:
                    ovr = conn.execute(
                        "SELECT * FROM user_overrides "
                        "WHERE media_type = ? AND tmdb_id = ? AND section_id = ''",
                        (media_type, tmdb_id),
                    ).fetchone()
                    if ovr is None:
                        ovr = conn.execute(
                            "SELECT * FROM user_overrides "
                            "WHERE media_type = ? AND tmdb_id = ? "
                            "ORDER BY section_id LIMIT 1",
                            (media_type, tmdb_id),
                        ).fetchone()
                # Also surface the full per-section override list so the
                # frontend can show all overrides at once if it wants.
                all_overrides = conn.execute(
                    "SELECT * FROM user_overrides "
                    "WHERE media_type = ? AND tmdb_id = ? "
                    "ORDER BY section_id",
                    (media_type, tmdb_id),
                ).fetchall()
                # v1.12.34 / v1.12.37: include the pending_updates row
                # so the INFO dialog can render the upstream-update
                # state. The "previous URL" lives on themes.previous_*
                # (not pending_updates) since v1.12.37 generalized
                # REVERT beyond the post-accept-on-U flow.
                # v1.12.117: scope to the row's section (per-section
                # first, '' fallback) AND gate on motif tracking presence
                # for that section, mirroring the library SQL's
                # pending_update field added in v1.12.108. Pre-fix this
                # query returned ANY pending_update for the title — so
                # the standard row's INFO card rendered the 4K row's
                # PROPOSED CHANGE diff (or the legacy '' row's), bleeding
                # cross-section. Now post-PURGE / pure-P / no-motif-tracking
                # rows correctly show no pending update in INFO, just like
                # the row pill.
                pu = None
                if section_id is not None:
                    # Check motif tracking presence first; if the row
                    # has no motif state (no override / placement /
                    # canonical / sidecar), don't surface a pending
                    # update for it even if Plex has one for this title.
                    has_presence = conn.execute(
                        "SELECT 1 FROM plex_items pi "
                        "WHERE pi.section_id = ? "
                        "  AND ((CASE pi.media_type WHEN 'show' THEN 'tv' ELSE pi.media_type END) = ?) "
                        "  AND pi.guid_tmdb = ? "
                        "  AND ("
                        "       pi.local_theme_file = 1 "
                        "    OR EXISTS (SELECT 1 FROM local_files lf "
                        "                WHERE lf.media_type = ? AND lf.tmdb_id = ? "
                        "                  AND lf.section_id = pi.section_id) "
                        "    OR EXISTS (SELECT 1 FROM user_overrides uo "
                        "                WHERE uo.media_type = ? AND uo.tmdb_id = ? "
                        "                  AND uo.section_id = pi.section_id) "
                        "    OR EXISTS (SELECT 1 FROM placements p "
                        "                WHERE p.media_type = ? AND p.tmdb_id = ? "
                        "                  AND p.section_id = pi.section_id) "
                        "  ) "
                        "LIMIT 1",
                        (section_id, media_type, tmdb_id,
                         media_type, tmdb_id,
                         media_type, tmdb_id,
                         media_type, tmdb_id),
                    ).fetchone()
                    if has_presence and _info_edition is not None:
                        # v1.21.68: edition-first pending-update resolution so
                        # the PROPOSED CHANGE diff belongs to THIS edition, not
                        # a sibling. (section, edition) → (section, '') → global.
                        pu = conn.execute(
                            "SELECT old_youtube_url, new_youtube_url, decision, "
                            "       decision_at, decision_by, detected_at, kind "
                            "  FROM pending_updates "
                            " WHERE media_type = ? AND tmdb_id = ? AND section_id = ? "
                            "   AND edition_key = ?",
                            (media_type, tmdb_id, section_id, _info_edition),
                        ).fetchone()
                        if pu is None and _info_edition != "":
                            pu = conn.execute(
                                "SELECT old_youtube_url, new_youtube_url, decision, "
                                "       decision_at, decision_by, detected_at, kind "
                                "  FROM pending_updates "
                                " WHERE media_type = ? AND tmdb_id = ? AND section_id = ? "
                                "   AND edition_key = ''",
                                (media_type, tmdb_id, section_id),
                            ).fetchone()
                        if pu is None:
                            pu = conn.execute(
                                "SELECT old_youtube_url, new_youtube_url, decision, "
                                "       decision_at, decision_by, detected_at, kind "
                                "  FROM pending_updates "
                                " WHERE media_type = ? AND tmdb_id = ? AND section_id = '' "
                                "   AND edition_key = ''",
                                (media_type, tmdb_id),
                            ).fetchone()
                        # v1.22.19 (audit MED #7): mirror the v1.12.119 no-op
                        # suppression (below, in the section branch) into this
                        # v1.21.68 edition-first branch — it was added later and
                        # skipped the suppression, so an edition-resolved row
                        # whose pending new_youtube_url already == the applied
                        # URL surfaced a PROPOSED CHANGE in the INFO card that
                        # the row pill (the actionable gate) hides. Same
                        # contract-drift class as v1.17.10/.17.
                        if pu is not None and pu["kind"] != "urls_match":
                            applied = conn.execute(
                                "SELECT COALESCE("
                                "  (SELECT youtube_url FROM user_overrides "
                                "     WHERE media_type = ? AND tmdb_id = ? "
                                "       AND section_id = ?),"
                                "  (SELECT youtube_url FROM user_overrides "
                                "     WHERE media_type = ? AND tmdb_id = ? "
                                "       AND section_id = ''),"
                                "  (SELECT youtube_url FROM themes "
                                "     WHERE media_type = ? AND tmdb_id = ?)"
                                ") AS applied",
                                (media_type, tmdb_id, section_id,
                                 media_type, tmdb_id,
                                 media_type, tmdb_id),
                            ).fetchone()
                            applied_url = applied["applied"] if applied else None
                            if applied_url and pu["new_youtube_url"] == applied_url:
                                pu = None
                    elif has_presence:
                        pu = conn.execute(
                            "SELECT old_youtube_url, new_youtube_url, decision, "
                            "       decision_at, decision_by, detected_at, kind "
                            "  FROM pending_updates "
                            " WHERE media_type = ? AND tmdb_id = ? AND section_id = ?",
                            (media_type, tmdb_id, section_id),
                        ).fetchone()
                        if pu is None:
                            pu = conn.execute(
                                "SELECT old_youtube_url, new_youtube_url, decision, "
                                "       decision_at, decision_by, detected_at, kind "
                                "  FROM pending_updates "
                                " WHERE media_type = ? AND tmdb_id = ? AND section_id = ''",
                                (media_type, tmdb_id),
                            ).fetchone()
                        # v1.12.119: suppress no-op pending updates — when
                        # new_youtube_url == the row's currently-applied URL,
                        # accepting would just re-download the same URL. The
                        # 'urls_match' kind is the special case where
                        # accepting is meaningful (U→T classification flip)
                        # so we keep that one through.
                        if pu is not None and pu["kind"] != "urls_match":
                            applied = conn.execute(
                                "SELECT COALESCE("
                                "  (SELECT youtube_url FROM user_overrides "
                                "     WHERE media_type = ? AND tmdb_id = ? "
                                "       AND section_id = ?),"
                                "  (SELECT youtube_url FROM user_overrides "
                                "     WHERE media_type = ? AND tmdb_id = ? "
                                "       AND section_id = ''),"
                                "  (SELECT youtube_url FROM themes "
                                "     WHERE media_type = ? AND tmdb_id = ?)"
                                ") AS applied",
                                (media_type, tmdb_id, section_id,
                                 media_type, tmdb_id,
                                 media_type, tmdb_id),
                            ).fetchone()
                            applied_url = applied["applied"] if applied else None
                            if applied_url and pu["new_youtube_url"] == applied_url:
                                pu = None
                else:
                    # No section_id passed (legacy / orphan path). Fall
                    # back to the original any-row query so non-row INFO
                    # opens still surface the update.
                    pu = conn.execute(
                        "SELECT old_youtube_url, new_youtube_url, decision, "
                        "       decision_at, decision_by, detected_at "
                        "  FROM pending_updates "
                        " WHERE media_type = ? AND tmdb_id = ?",
                        (media_type, tmdb_id),
                    ).fetchone()
                # v1.12.84: scope events by section_id when provided, like
                # audit_events. Title-global entries (section_id IS NULL —
                # legacy pre-migration rows + sync/scan events that span
                # every section) stay visible so cross-section context
                # isn't lost. Pre-fix the unfiltered query rendered
                # standard's worker events on the 4K card and vice versa.
                if section_id is not None:
                    recent_events = conn.execute(
                        """SELECT * FROM events
                            WHERE media_type = ? AND tmdb_id = ?
                              AND (section_id = ? OR section_id IS NULL)
                            ORDER BY ts DESC LIMIT 25""",
                        (media_type, tmdb_id, section_id),
                    ).fetchall()
                else:
                    recent_events = conn.execute(
                        "SELECT * FROM events WHERE media_type = ? AND tmdb_id = ? "
                        "ORDER BY ts DESC LIMIT 25",
                        (media_type, tmdb_id),
                    ).fetchall()
            local_payloads: list[dict] = []
            for lf in local_files:
                d = dict(lf)
                if settings.is_paths_ready() and d.get("file_path"):
                    d["abs_path"] = str(settings.themes_dir / d["file_path"])
                local_payloads.append(d)
            # v1.12.86: surface per-section previous URL (replaces the
            # title-global themes.previous_youtube_url + previous_youtube_kind
            # columns). The INFO card reads previous_url.youtube_url +
            # previous_url.kind to render the "previous url" row with the
            # correct color + suffix.
            with get_conn(db) as conn:
                prev_row = _load_previous_url(
                    conn, media_type, tmdb_id, section_id=section_id,
                )
                # v1.12.93: per-row "motif touched this on" timestamps for
                # the INFO card. Distinct from themes.youtube_added_at /
                # youtube_edited_at which track ThemerrDB's record.
                #   motif_added_at  = oldest evidence motif acted on this
                #     row. audit_events covers post-v1.12.80 actions; falls
                #     back to local_files.downloaded_at for older installs.
                #   motif_edited_at = most recent evidence. Same fallback.
                # NULL when motif has never acted (e.g. M sidecar that
                # was never adopted, P-agent never replaced) — frontend
                # renders an em-dash.
                motif_added = None
                motif_edited = None
                if section_id is not None:
                    ae = conn.execute(
                        """SELECT MIN(occurred_at) AS first_at,
                                  MAX(occurred_at) AS last_at
                             FROM audit_events
                            WHERE media_type = ? AND tmdb_id = ?
                              AND (section_id = ? OR section_id IS NULL)""",
                        (media_type, tmdb_id, section_id),
                    ).fetchone()
                else:
                    ae = conn.execute(
                        """SELECT MIN(occurred_at) AS first_at,
                                  MAX(occurred_at) AS last_at
                             FROM audit_events
                            WHERE media_type = ? AND tmdb_id = ?""",
                        (media_type, tmdb_id),
                    ).fetchone()
                if ae:
                    motif_added = ae["first_at"]
                    motif_edited = ae["last_at"]
                # local_files.downloaded_at fallback when no audit row
                # exists (pre-v1.12.80 installs, or pure-T rows whose
                # initial sync-driven download never wrote an audit
                # entry). Per-section when section_id is provided so
                # the timestamp matches the row the user clicked.
                if not motif_added:
                    if section_id is not None:
                        lf_dl = conn.execute(
                            """SELECT MIN(downloaded_at) AS first_at,
                                      MAX(downloaded_at) AS last_at
                                 FROM local_files
                                WHERE media_type = ? AND tmdb_id = ?
                                  AND section_id = ?""",
                            (media_type, tmdb_id, section_id),
                        ).fetchone()
                    else:
                        lf_dl = conn.execute(
                            """SELECT MIN(downloaded_at) AS first_at,
                                      MAX(downloaded_at) AS last_at
                                 FROM local_files
                                WHERE media_type = ? AND tmdb_id = ?""",
                            (media_type, tmdb_id),
                        ).fetchone()
                    if lf_dl and lf_dl["first_at"]:
                        motif_added = lf_dl["first_at"]
                        motif_edited = lf_dl["last_at"]
            previous_url_payload = (
                {"youtube_url": prev_row["youtube_url"],
                 "kind": prev_row["kind"],
                 "captured_at": prev_row["captured_at"]}
                if prev_row else None
            )
            # v1.13.3 (Issue 4): explicit section + edition context so the
            # INFO card doesn't have to imply 4K-vs-Standard from the
            # placement folder path. Looks up the plex_section row for
            # the requested section_id (title, type, is_4k, is_anime),
            # plus extracts the {edition-X} tag from each placement's
            # media_folder if present. NULL when no section_id was
            # passed (legacy callers / orphan paths).
            section_context = None
            if section_id is not None:
                with get_conn(db) as conn:
                    sec = conn.execute(
                        "SELECT section_id, title, type, is_4k, is_anime "
                        "FROM plex_sections WHERE section_id = ?",
                        (section_id,),
                    ).fetchone()
                if sec is not None:
                    if sec["is_anime"]:
                        type_label = "Anime"
                    elif sec["type"] == "show":
                        type_label = "TV"
                    else:
                        type_label = "Movie"
                    variant_label = "4K" if sec["is_4k"] else "Standard"
                    section_context = {
                        "section_id": sec["section_id"],
                        "section_title": sec["title"],
                        "type": sec["type"],
                        "is_4k": bool(sec["is_4k"]),
                        "is_anime": bool(sec["is_anime"]),
                        "type_label": type_label,
                        "variant_label": variant_label,
                        # Compose the human label the INFO card renders:
                        # "4K Movie", "Standard TV", "Anime · Standard"
                        "scope_label": (
                            f"{variant_label} {type_label}"
                            if not sec["is_anime"]
                            else f"{type_label} · {variant_label}"
                        ),
                    }
            # Edition extraction from placement folders. Plex tags
            # editions with {edition-NAME} in the folder name; if any
            # placement carries one, surface it on the section_context
            # block so the user can see "edition: 4K" inline without
            # parsing the path themselves. We pick the first non-empty
            # match across this row's placements (typically only one).
            # v1.13.51: fall back to plex_items.folder_path when no
            # placement carries an edition tag. Pre-fix a row that had
            # a directors-cut Plex folder but no motif placement (e.g.
            # 1408's standard-movies row in the user screenshot —
            # DOWNLOAD pending, no canonical, but the row's edition
            # pill in the library table comes from pi.folder_path)
            # showed the edition pill on the row but no edition chip
            # in the info card, because the placement-only extraction
            # missed it. Now both surfaces parse the same source.
            if section_context is not None:
                # v1.21.76: parse the {edition-X} label via the editions.py
                # chokepoint (was a 3rd inline copy of the regex). Prefer a
                # placement folder's tag, then fall back to plex_items.
                edition_label = ""
                for p in placements:
                    mf = (p["media_folder"] if "media_folder" in p.keys()
                          else None)
                    edition_label = edition_label_for_folder(mf)
                    if edition_label:
                        break
                if not edition_label:
                    # Fallback: plex_items.folder_path. v1.21.68: when the
                    # clicked rating_key is known, read THAT row's folder so the
                    # label is this edition's (pre-fix the section+guid LIMIT 1
                    # returned an arbitrary sibling — every card showed the same
                    # edition tag).
                    with get_conn(db) as conn:
                        pi_row = None
                        if rating_key:
                            pi_row = conn.execute(
                                "SELECT folder_path FROM plex_items "
                                "WHERE rating_key = ?",
                                (rating_key,),
                            ).fetchone()
                        if pi_row is None:
                            pi_row = conn.execute(
                                "SELECT folder_path FROM plex_items "
                                "WHERE section_id = ? AND guid_tmdb = ? "
                                "  AND media_type = ? "
                                "LIMIT 1",
                                (section_id, str(tmdb_id), _info_plex_type),
                            ).fetchone()
                    if pi_row and pi_row["folder_path"]:
                        edition_label = edition_label_for_folder(
                            pi_row["folder_path"])
                # Preserve the prior contract: None (not '') when no edition tag.
                section_context["edition"] = edition_label or None

            # v1.22.71: surface the P-row discriminator for the playback-
            # source line. The JS read data.theme.plex_independent_theme (a
            # plex_items column — never on the themes dict) + is_plex_agent
            # (a field never returned), so every pure-P card showed "(none —
            # row has no theme staged)". rk-first, then section, then title.
            # v0.51.37 (the user): ALSO surface has_theme so the card can say
            # "Plex is serving a theme motif isn't managing" for a Plex-serving /
            # no-local row EVEN in the transient window after UNMANAGE of a
            # plex_upload row, before the next plex_enum sets plex_independent_
            # theme=1. Without it the card fell to "(none — no theme staged)"
            # while Plex was visibly still serving (the user's confusing state).
            _pi_independent = None
            _pi_has_theme = None
            with get_conn(db) as conn:
                if rating_key:
                    _pind = conn.execute(
                        "SELECT plex_independent_theme, has_theme FROM plex_items "
                        "WHERE rating_key = ?", (rating_key,)).fetchone()
                    if _pind:
                        _pi_independent = _pind["plex_independent_theme"]
                        _pi_has_theme = _pind["has_theme"]
                # v0.51.42 (code-review): resolve each flag INDEPENDENTLY. The
                # v0.51.37 gate `_pi_independent is None AND _pi_has_theme is None`
                # coupled them — has_theme is NOT NULL, so a tier-1 rk-hit always
                # set it, which then blocked the section/global fallback from
                # resolving a NULL plex_independent_theme (a sidecar row) off its
                # siblings (regressed the +P label to (none)). Run each tier if
                # EITHER is still unresolved, and fill only the column still None
                # so a resolved rk value is never clobbered by a sibling MAX.
                if (_pi_independent is None or _pi_has_theme is None) and section_id:
                    _pind = conn.execute(
                        "SELECT MAX(plex_independent_theme) AS v, MAX(has_theme) AS h "
                        "FROM plex_items "
                        "WHERE section_id = ? AND guid_tmdb = ? AND media_type = ?",
                        (section_id, str(tmdb_id), _info_plex_type)).fetchone()
                    if _pind:
                        if _pi_independent is None:
                            _pi_independent = _pind["v"]
                        if _pi_has_theme is None:
                            _pi_has_theme = _pind["h"]
                if _pi_independent is None or _pi_has_theme is None:
                    _pind = conn.execute(
                        "SELECT MAX(plex_independent_theme) AS v, MAX(has_theme) AS h "
                        "FROM plex_items "
                        "WHERE guid_tmdb = ? AND media_type = ?",
                        (str(tmdb_id), _info_plex_type)).fetchone()
                    if _pind:
                        if _pi_independent is None:
                            _pi_independent = _pind["v"]
                        if _pi_has_theme is None:
                            _pi_has_theme = _pind["h"]

            return {
                "theme": dict(t),
                # v1.22.71: P-row discriminator for the playback-source line.
                "plex_independent_theme": _pi_independent,
                # v0.51.37: Plex-is-serving flag so the card explains a
                # Plex-served / no-motif-theme row (incl. the transient window
                # after UNMANAGE of a plex_upload row) instead of "(none)".
                "plex_has_theme": _pi_has_theme,
                "local_file": local_payloads[0] if local_payloads else None,
                "local_files": local_payloads,
                "placements": [dict(p) for p in placements],
                "override": dict(ovr) if ovr else None,
                # v1.12.72: full per-section override list. Frontend
                # can render one row per section in the INFO card if
                # multiple overrides exist; legacy `override` field
                # still surfaces a single representative row for
                # back-compat with consumers that don't read this list.
                "overrides": [dict(o) for o in all_overrides],
                "pending_update": dict(pu) if pu else None,
                "previous_url": previous_url_payload,
                # v1.12.93: motif-side timestamps so the INFO card can
                # show when *motif* first/last acted on the row, distinct
                # from ThemerrDB's record on the theme.
                "motif_added_at": motif_added,
                "motif_edited_at": motif_edited,
                "events": [dict(e) for e in recent_events],
                "section_context": section_context,
            }
        return await run_in_threadpool(_build)

    def _trigger_plex_item_refresh(
        media_type: str, tmdb_id: int,
    ) -> int:
        """v1.10.28: ask Plex to re-run its metadata agent on each
        rating_key tracking this item, so the server-side has_theme
        cache reflects motif having just deleted the file. Returns
        the count of refresh requests fired.

        Without this, after PURGE/DEL on a T row our optimistic
        clear of plex_items.has_theme=0 survived only until the
        next plex_enum, which re-fetches from Plex's API. Plex
        was still reporting theme=true (its metadata cache hadn't
        re-scanned the now-empty folder), so the row came back as
        a phantom P (Plex agent / cloud). A targeted refresh kicks
        Plex to re-evaluate immediately.

        Best-effort — failures (Plex offline, auth issue) log and
        return without raising. The fallback path is the user
        clicking REFRESH FROM PLEX manually.
        """
        if not (settings.plex_enabled and settings.plex_token):
            return 0
        # v0.51.48: else media_type (was "movie") so PURGE/DEL on a themed
        # collection resolves its plex_items rows (media_type='collection'),
        # not a phantom 'movie' lookup that matches nothing.
        plex_mt = "show" if media_type == "tv" else media_type
        with get_conn(settings.db_path) as conn:
            rks = conn.execute(
                "SELECT rating_key FROM plex_items "
                "WHERE guid_tmdb = ? AND media_type = ?",
                (tmdb_id, plex_mt),
            ).fetchall()
        if not rks:
            return 0
        cfg = PlexConfig(
            url=settings.plex_url, token=settings.plex_token,
            movie_section=settings.plex_movie_section,
            tv_section=settings.plex_tv_section, enabled=True,
        )
        n = 0
        try:
            with PlexClient(cfg, plus_mode=settings.plus_equiv_mode) as plex:  # type: ignore[arg-type]
                for r in rks:
                    try:
                        if plex.refresh(r["rating_key"]):
                            n += 1
                    except Exception as e:
                        # v1.15.107: bumped log.debug → log.warning.
                        # _trigger_plex_item_refresh runs immediately
                        # after PURGE/DEL — its job is to flush Plex's
                        # stale theme cache so the row drops from
                        # phantom-P to '—' immediately. Per-rk
                        # failures are not the noisy polling kind;
                        # each one is "this destructive action didn't
                        # fully land in Plex's view," which is what
                        # the user wonders about when their PURGE
                        # row keeps coming back as P.
                        log.warning("plex refresh failed for rk=%s: %s",
                                    r["rating_key"], e)
        except Exception as e:
            log.warning("plex client init failed for refresh: %s", e)
        return n

    # v1.11.47: removed _enqueue_section_refresh_for_item. Each
    # destructive endpoint already optimistically updates
    # plex_items.local_theme_file from the post-mutation disk state,
    # so the confirmatory full-section plex_enum was scanning 10K+
    # items just to re-affirm one row's flag. The single remaining
    # caller (unmanage) was the only user.

    @app.post("/api/items/{media_type}/{tmdb_id}/unplace")
    async def api_unplace_item(
        request: Request, media_type: MediaType, tmdb_id: int,
        # v1.12.77: optional section_id scopes DEL (unplace) to one
        # section. Without it, every section's placement file gets
        # unlinked (legacy fan-out). Mirrors the v1.12.46/.47/.73
        # scoping for ACCEPT UPDATE / REVERT / RE-DOWNLOAD /
        # UNMANAGE.
        section_id: str | None = Query(None),
        # v1.21.61 (C2b): when the UI sends the row's rating_key, scope the
        # unplace to THAT edition (LET PLEX SERVE on Theatrical no longer
        # nukes Extended/Sam). Absent rk = legacy section-wide fan-out.
        rating_key: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        """Remove the placement of a theme (theme.mp3 in Plex's folder) but
        keep motif's canonical so the user can REPLACE it back later. The
        Plex side stops playing the motif theme; the file in themes_dir
        stays, allowing one-click re-placement without re-download.

        v1.12.77: when section_id is provided, only that section's
        placement gets unlinked. Sibling sections continue to play
        their motif theme.
        """
        _require_admin(request)
        with get_conn(db) as conn:
            theme = conn.execute(
                "SELECT title FROM themes WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            if theme is None:
                raise HTTPException(status_code=404, detail="theme not found")
            # v1.21.61 (C2b): rk-driven edition scope for the placement
            # delete below. None = legacy section-wide fan-out (no rk sent);
            # '' or a real key = scope to exactly that edition.
            _unplace_edition = (
                edition_key_for_rating_key(conn, rating_key)
                if rating_key else None)
            # v1.21.93: if the clicked edition has NO placement of its own
            # but a shared '' placement exists, operate on the '' row — the
            # historical/un-tagged placement the INFO card ALREADY SHOWS via
            # its v1.21.68 '' fallback. Without this mirror, LET PLEX SERVE
            # on a metadata-only edition (plex_items.folder_path carries
            # {edition-Minus Color} → edition_key='minus color', but the
            # placement/local_files were written un-tagged at '' before the
            # edition plumbing) found 0 placements and silently no-op'd while
            # the card showed "placed: hardlink" (the user's Godzilla "Minus
            # Color" + Watchmen +P rows). Reassigning here keeps the WORKLIST
            # SELECT, the DELETE, and the local_files stamp all consistent.
            # Transitional — removed in Phase D2 once the backfill walker
            # re-keys historical '' rows to their true edition.
            # v1.21.95: gate the fallback on this title+section having exactly
            # ONE edition. When MULTIPLE editions share a single '' placement
            # (the user's Watchmen: Theatrical Cut / Midnight / Director's Cut
            # are 3 Plex items sharing one folder + one theme.mp3 at
            # edition_key=''), falling back would unplace the SHARED placement
            # and bleed across all three (the v1.21.93 regression). The single-
            # edition case (Godzilla "Minus Color") stays fixed. True per-
            # edition independence for shared-folder editions is the separate
            # per-rk-upload arc.
            _plex_type = "show" if media_type == "tv" else media_type
            _edition_count = (conn.execute(
                "SELECT COUNT(DISTINCT edition_key) FROM plex_items "
                "WHERE guid_tmdb = ? AND section_id = ? AND media_type = ?",
                (tmdb_id, section_id, _plex_type),
            ).fetchone()[0] if (section_id and _unplace_edition) else 0)
            _has_own_pl = bool(section_id and _unplace_edition and conn.execute(
                "SELECT 1 FROM placements WHERE media_type = ? AND tmdb_id = ? "
                "AND section_id = ? AND edition_key = ? LIMIT 1",
                (media_type, tmdb_id, section_id, _unplace_edition),
            ).fetchone())
            _has_empty_pl = bool(section_id and _unplace_edition and conn.execute(
                "SELECT 1 FROM placements WHERE media_type = ? AND tmdb_id = ? "
                "AND section_id = ? AND edition_key = '' LIMIT 1",
                (media_type, tmdb_id, section_id),
            ).fetchone())
            if (_unplace_edition and _edition_count == 1
                    and not _has_own_pl and _has_empty_pl):
                _unplace_edition = ""
            elif (_unplace_edition and _edition_count > 1
                    and not _has_own_pl and _has_empty_pl):
                # v1.22.0 (line-close audit, cold-path rule): this edition has
                # no own placement but shares a '' placement with N editions —
                # the v1.21.95 gate withholds the '' fallback to avoid the
                # v1.21.93 cross-edition bleed, so LPS is a deliberate no-op.
                # Log WHY so it's not a silent "nothing happened".
                log.info(
                    "unplace: %s/%s section=%s edition=%r shares a '' "
                    "placement across %d editions — LPS withheld to avoid "
                    "sibling bleed (v1.21.95); per-edition isolation pending "
                    "the per-rk-upload arc",
                    media_type, tmdb_id, section_id, _unplace_edition,
                    _edition_count,
                )
            # v1.21.67: scope the physical-unlink WORKLIST to this edition
            # too — not just the DELETE below. Pre-fix the SELECT pulled
            # EVERY edition's placement for the section, so the unlink loop
            # removed sibling editions' theme.mp3 from disk while the
            # edition-scoped DELETE left their placements row intact —
            # leaving them pointing at a now-missing file (the user: LET PLEX
            # SERVE on Theatrical showed Sam's HL as missing). Mirror the
            # DELETE's (section_id, _unplace_edition) branching exactly.
            # v1.24.7: select edition_key too — the v1.22.76 per-edition
            # local_files lookup below reads pr["edition_key"], a column these
            # SELECTs never fetched → IndexError (sqlite3.Row) on a plex_upload
            # LPS/UNPLACE. The fix-read was dead on arrival.
            if section_id and _unplace_edition is not None:
                placements = conn.execute(
                    "SELECT media_folder, placement_kind, section_id, "
                    "       edition_key "
                    "FROM placements "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ? "
                    "  AND edition_key = ?",
                    (media_type, tmdb_id, section_id, _unplace_edition),
                ).fetchall()
            elif section_id:
                placements = conn.execute(
                    "SELECT media_folder, placement_kind, section_id, "
                    "       edition_key "
                    "FROM placements "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?",
                    (media_type, tmdb_id, section_id),
                ).fetchall()
            else:
                placements = conn.execute(
                    "SELECT media_folder, placement_kind, section_id, "
                    "       edition_key "
                    "FROM placements "
                    "WHERE media_type = ? AND tmdb_id = ?",
                    (media_type, tmdb_id),
                ).fetchall()
        # v1.18.36: split placements by kind so the new plex_upload
        # branch can fire its Plex API teardown (DELETE singular +
        # re-upload trick on fallback). Pre-v1.18.36 every placement
        # ran through the sidecar unlink path, which silently no-op'd
        # for plex_upload rows (media_folder='' sentinel → Path('') /
        # 'theme.mp3' is .theme.mp3 in cwd, .is_file() False, unlink
        # skipped). Latent bug since v1.18.0: motif's UNPLACE/LPS on
        # collection + opt-in API-push rows never actually removed
        # Plex's theme — UI marked unplaced, Plex kept serving.
        # v1.18.31-35 probe series confirmed the Plex API shape;
        # v1.18.36 wires the production fix.
        sidecar_placements = [
            pr for pr in placements
            if (pr["placement_kind"] or "") != "plex_upload"
        ]
        api_placements = [
            pr for pr in placements
            if (pr["placement_kind"] or "") == "plex_upload"
        ]
        # Sidecar branch (legacy code path, unchanged).
        unlinked = 0
        affected_folders: list[str] = []
        # v1.20.15: track which sections had a motif-owned sidecar
        # unlinked here so the inline HEAD-verify below can SKIP those
        # rks — Plex's /theme cache returns a stale 200 for several
        # seconds after motif unlinks the file, which would restore
        # has_theme=1/verified_ok=1 and render a phantom P. Mirrors the
        # PURGE rk_from_placement guard (audit MED-2 / class 1).
        sidecar_unlinked_sections: set[str] = set()

        # v0.51.13 (audit #12, class 12): offload the unlink loop — it hits the
        # /data mount; a spun-down disk blocks each syscall for seconds, serially,
        # freezing the event loop for every concurrent request (invisible to the
        # v1.22.58 AST lint, which covers network/subprocess only). Same offload
        # v1.23.96 gave the orphan-sidecar delete. No DB txn is open here.
        def _unlink_sidecars() -> int:
            n = 0
            for pr in sidecar_placements:
                sidecar_unlinked_sections.add(pr["section_id"] or "")
                try:
                    p = Path(pr["media_folder"]) / "theme.mp3"
                    if p.is_file():
                        p.unlink()
                        n += 1
                    affected_folders.append(pr["media_folder"])
                except OSError as e:
                    log.warning("unplace: could not unlink %s: %s", pr["media_folder"], e)
            return n
        unlinked = await run_in_threadpool(_unlink_sidecars)
        # v1.18.36 / v1.18.38: Plex-side LPS restore — clear motif's
        # active selection (when applicable) and re-select a non-motif
        # entry via the v1.18.35 re-upload trick so the row keeps
        # serving Plex's pre-motif theme.
        #
        # v1.18.36 ran this only when placement_kind='plex_upload'.
        # the user's 100% Wolf test on v1.18.36 revealed the gap:
        # after SWITCH api→file → LPS, the row went themeless with
        # SRC=`-` because by LPS time placement_kind was 'hardlink',
        # the v1.18.36 plex_upload branch didn't fire, and Plex's
        # /themes had two unselected entries (motif's API leftover +
        # themerr-plex's) with nothing serving.
        #
        # v1.18.38 fires the restore for EVERY placement, regardless
        # of kind. plex_upload rows need DELETE singular first
        # (clears motif's prior selection); sidecar rows skip that
        # (motif's sidecar was filesystem-served, not in Plex's
        # /themes selected state).
        api_handled = 0
        api_restored = 0
        # v1.20.66: per-rk PU outcome for the inline-verify below. A PU rk
        # (placement_kind='plex_upload', media_folder='') can't enter the
        # folder-based placement_owned_rks skip, so without this it hits
        # the stale-200 HEAD probe → phantom P (recurring bug class #1,
        # PU-shaped). The restore loop already determines, per rk, whether
        # Plex has a fallback theme to serve — capture it: a restored
        # fallback → keep P (optimistic, next plex_enum confirms); motif's
        # upload deleted with no fallback → nothing serving → zero to '-'.
        pu_kept_rks: set[str] = set()
        pu_zero_rks: set[str] = set()
        all_placements_for_restore = sidecar_placements + api_placements
        if all_placements_for_restore and settings.plex_enabled and settings.plex_token:
            from ..core.plex import PlexClient, PlexConfig
            cfg = PlexConfig(
                url=settings.plex_url, token=settings.plex_token,
                movie_section=settings.plex_movie_section,
                tv_section=settings.plex_tv_section, enabled=True,
            )
            plex_mt = "show" if media_type == "tv" else (
                "collection" if media_type == "collection" else "movie"
            )
            with PlexClient(cfg, plus_mode=settings.plus_equiv_mode) as plex, \
                    get_conn(db) as conn:  # type: ignore[arg-type]
                # Pre-fetch theme_id once for the rk lookup.
                tid_row = conn.execute(
                    "SELECT id FROM themes "
                    "WHERE media_type = ? AND tmdb_id = ?",
                    (media_type, tmdb_id),
                ).fetchone()
                tid_pk = tid_row["id"] if tid_row else None
                for pr in all_placements_for_restore:
                    # v1.18.38: was_plex_upload gates whether we
                    # DELETE singular first (clear motif's prior
                    # selection in Plex's /themes). Sidecar
                    # placements don't have motif's hash selected
                    # in /themes — their teardown is the
                    # filesystem unlink above.
                    was_plex_upload = (
                        (pr["placement_kind"] or "") == "plex_upload"
                    )
                    section = pr["section_id"]
                    # v1.21.67: when the unplace named a specific edition
                    # (rating_key sent), drive the Plex teardown on THAT
                    # exact rk. Pre-fix this re-resolved rk by (theme_id,
                    # section) LIMIT 1 — an arbitrary sibling edition — so
                    # the get_themes / delete / re-upload restore could act
                    # on the wrong edition's Plex item. The worklist above
                    # is now edition-scoped, so this loop runs once for the
                    # clicked edition; use its rk directly. Absent rk =
                    # legacy section-wide fan-out (per-section lookup).
                    if rating_key:
                        rk = rating_key
                    else:
                        rk_row = None
                        if tid_pk is not None:
                            rk_row = conn.execute(
                                "SELECT rating_key FROM plex_items "
                                "WHERE theme_id = ? AND section_id = ?",
                                (tid_pk, section),
                            ).fetchone()
                        if rk_row is None:
                            rk_row = conn.execute(
                                "SELECT rating_key FROM plex_items "
                                "WHERE guid_tmdb = ? AND media_type = ? "
                                "  AND section_id = ?",
                                (str(tmdb_id), plex_mt, section),
                            ).fetchone()
                        if rk_row is None:
                            log.warning(
                                "unplace[restore]: no rating_key for "
                                "%s/%s section_id=%s — skipping Plex API "
                                "teardown",
                                media_type, tmdb_id, section,
                            )
                            continue
                        rk = rk_row["rating_key"]
                    # Identify motif's own entry via SHA-1 of the
                    # canonical file. If the canonical's gone (rare
                    # — UNPLACE preserves it; race with PURGE could
                    # hit it), we fall back to "first non-motif by
                    # ratingKey scheme" heuristic.
                    # v1.18.37: section-scoped lookup didn't find a
                    # local_files row on the user's 12 Monkeys LPS
                    # test, so motif_hash came back None and the
                    # fallback picker leaned on positional luck (the
                    # themerr-plex entry happened to be first in
                    # Plex's enumeration). Add unscoped fallback +
                    # explicit failure-mode logging so future drift
                    # is diagnosable.
                    # v1.22.76: prefer THIS placement's edition row — the
                    # worklist + rk are edition-pinned (v1.21.67) but this
                    # lookup wasn't, so on a multi-edition section it could
                    # hash a SIBLING edition's file and the fallback picker
                    # then re-selected motif's own upload instead of
                    # restoring Plex's theme.
                    _pr_edition = pr["edition_key"] or ""
                    lf_row = conn.execute(
                        "SELECT file_path FROM local_files "
                        "WHERE media_type = ? AND tmdb_id = ? "
                        "  AND section_id = ? "
                        "  AND edition_key IN (?, '') "
                        "ORDER BY (edition_key = ?) DESC LIMIT 1",
                        (media_type, tmdb_id, section,
                         _pr_edition, _pr_edition),
                    ).fetchone()
                    if lf_row is None:
                        lf_row = conn.execute(
                            "SELECT file_path FROM local_files "
                            "WHERE media_type = ? AND tmdb_id = ? "
                            "LIMIT 1",
                            (media_type, tmdb_id),
                        ).fetchone()
                    motif_hash: str | None = None
                    hash_reason: str = "ok"
                    if lf_row is None:
                        hash_reason = "no local_files row"
                    elif not lf_row["file_path"]:
                        hash_reason = "empty file_path"
                    else:
                        # v1.18.39: local_files.file_path is stored
                        # RELATIVE to settings.themes_dir (see
                        # worker.py:1812, 2347). v1.18.36 treated
                        # it as absolute, so the hash compute
                        # always failed on the user's install where
                        # themes_dir=/data/media/themes — file
                        # lookup used the relative form and
                        # missed. Now: join with themes_dir.
                        rel = lf_row["file_path"]
                        canonical = (
                            settings.themes_dir / rel
                            if not Path(rel).is_absolute()
                            else Path(rel)
                        )
                        if not canonical.is_file():
                            hash_reason = (
                                f"file missing: {canonical}"
                            )
                        else:
                            # v1.22.69: chunked multi-MB hash froze the loop — offload.
                            def _sha1_file(p=canonical):
                                import hashlib
                                h = hashlib.sha1()
                                with p.open("rb") as fh:
                                    for chunk in iter(
                                        lambda: fh.read(65536), b"",
                                    ):
                                        h.update(chunk)
                                return h.hexdigest()
                            try:
                                motif_hash = await run_in_threadpool(_sha1_file)
                            except OSError as e:
                                hash_reason = f"io error: {e}"
                    if motif_hash is None:
                        log.warning(
                            "unplace[plex_upload]: motif_hash "
                            "unavailable for %s/%s section_id=%s — "
                            "reason: %s. Fallback heuristic may "
                            "pick motif's own entry if it's first "
                            "in Plex's enumeration.",
                            media_type, tmdb_id, section, hash_reason,
                        )
                    # GET Plex's current themes for the item.
                    # v1.22.42 (audit): this restore loop ran N placements ×
                    # (get_themes + delete + re-upload) synchronously on the
                    # event loop, freezing every concurrent request for the
                    # duration. Off-load each Plex round-trip to a thread (httpx
                    # is thread-safe). The conn here is read-only (writes commit
                    # in the separate txn below) so it's never touched off-thread.
                    themes_resp = await run_in_threadpool(
                        plex.get_themes, rating_key=rk,
                    )
                    entries = []
                    if themes_resp.get("ok"):
                        body = themes_resp.get("body") or {}
                        if isinstance(body, dict):
                            entries = (
                                body.get("MediaContainer", {})
                                .get("Metadata", [])
                            )
                    # Choose a fallback entry: prefer metadata://
                    # (Plex's own agent theme); fall back to first
                    # upload:// whose hash != motif's.
                    fallback_rk: str | None = None
                    for e in entries:
                        ratingKey = e.get("ratingKey", "")
                        if ratingKey.startswith("metadata://"):
                            fallback_rk = ratingKey
                            break
                    if fallback_rk is None:
                        for e in entries:
                            ratingKey = e.get("ratingKey", "")
                            if not ratingKey.startswith("upload://"):
                                continue
                            entry_hash = ratingKey.rsplit("/", 1)[-1]
                            if motif_hash is None or entry_hash != motif_hash:
                                fallback_rk = ratingKey
                                break
                    # v1.18.38: DELETE singular only for plex_upload
                    # rows (where motif's theme is selected in
                    # Plex's /themes). Sidecar rows have no motif
                    # selection to clear; the sidecar unlink above
                    # is the teardown for those.
                    deleted = False
                    restored = False
                    if was_plex_upload:
                        deleted = await run_in_threadpool(
                            plex.delete_theme, rating_key=rk,
                        )
                        if deleted:
                            api_handled += 1
                    # Re-upload trick on the fallback (if any) so
                    # Plex resumes serving SOMETHING. Fires for
                    # both kinds — sidecar rows benefit when a
                    # SWITCH-orphaned API upload or themerr-plex
                    # entry is sitting unselected in /themes.
                    if fallback_rk:
                        restored = await run_in_threadpool(
                            plex.set_active_theme_via_reupload,
                            rating_key=rk,
                            theme_rating_key=fallback_rk,
                        )
                        if restored:
                            api_restored += 1
                            log.info(
                                "unplace[restore]: rk=%s "
                                "placement_kind=%s restored fallback "
                                "theme %s",
                                rk,
                                pr["placement_kind"] or "sidecar",
                                fallback_rk,
                            )
                    # v1.20.66: record this PU rk's outcome for the
                    # inline-verify. restored → Plex serves a fallback
                    # (keep P). deleted-but-not-restored → motif's upload
                    # is gone with nothing behind it ('-'). NOT deleted
                    # (DELETE failed) → leave it for the HEAD probe, which
                    # will accurately see motif's still-present theme (no
                    # teardown happened → no stale-cache window).
                    if was_plex_upload:
                        if restored:
                            pu_kept_rks.add(rk)
                        elif deleted:
                            pu_zero_rks.add(rk)
                    log.info(
                        "unplace[restore]: rk=%s placement_kind=%s "
                        "deleted=%s fallback_rk=%s motif_hash=%s "
                        "entries=%d",
                        rk, pr["placement_kind"] or "sidecar",
                        deleted, fallback_rk,
                        (motif_hash[:8] + "…") if motif_hash else None,
                        len(entries),
                    )
        with get_conn(db) as conn, transaction(conn):
            # v1.18.73 (HIGH-B audit): cancel any pending/running
            # jobs for this row before the placements teardown
            # commits. Pre-fix a place/download/refresh job in
            # flight against (mt, tmdb) could land bytes into the
            # row mid-unplace — by the time the job's
            # transaction committed, the unplace's transaction
            # had already swept the placement away → ghost
            # placements row reborn, motif's tracking drifts
            # silently from on-disk state. The cancel marks
            # those jobs `cancelled` so the worker's WHERE
            # status='running' / 'pending' guard refuses to
            # re-enter the row.
            _cancel_jobs_for_row(
                conn, media_type=media_type, tmdb_id=tmdb_id,
                section_id=section_id,
            )
            if section_id and _unplace_edition is not None:
                # v1.21.61 (C2b): unplace ONLY this edition's placement.
                conn.execute(
                    "DELETE FROM placements "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ? "
                    "  AND edition_key = ?",
                    (media_type, tmdb_id, section_id, _unplace_edition),
                )
            elif section_id:
                conn.execute(
                    "DELETE FROM placements "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?",
                    (media_type, tmdb_id, section_id),
                )
            else:
                conn.execute(
                    "DELETE FROM placements WHERE media_type = ? AND tmdb_id = ?",
                    (media_type, tmdb_id),
                )
            # v1.16.12: stamp local_files.last_place_attempt_reason =
            # 'plex_has_theme' so the v1.13.76 retry-sweep filter
            # (scheduler.py:107-109) skips this row on its next pass.
            # Pre-fix the unplace endpoint deleted the placement but
            # left last_place_attempt_reason at its prior 'placed'
            # value, so the hourly sweep re-enqueued the row, the
            # place worker hit Plex's own theme, logged "Skipped
            # placement: plex_has_theme", and stamped the field
            # itself — burning one place-job round per LPS row.
            # the user's bulk-LPS of 121 M+P rows produced 121
            # "Skipped placement" INFO lines via this loop.
            # Stamping at unplace time short-circuits the cycle —
            # the user explicitly chose "let Plex serve," we know
            # the outcome, no need to relearn it via a no-op
            # place job. A subsequent PUSH TO PLEX overwrites the
            # stamp with 'placed' when the worker successfully
            # places — no permanent lock-out.
            if section_id and _unplace_edition is not None:
                conn.execute(
                    "UPDATE local_files SET last_place_attempt_at = ?, "
                    "                       last_place_attempt_reason = 'backup_only' "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ? "
                    "  AND edition_key = ?",
                    (now_iso(), media_type, tmdb_id, section_id,
                     _unplace_edition),
                )
            elif section_id:
                conn.execute(
                    "UPDATE local_files SET last_place_attempt_at = ?, "
                    "                       last_place_attempt_reason = 'backup_only' "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?",
                    (now_iso(), media_type, tmdb_id, section_id),
                )
            else:
                conn.execute(
                    "UPDATE local_files SET last_place_attempt_at = ?, "
                    "                       last_place_attempt_reason = 'backup_only' "
                    "WHERE media_type = ? AND tmdb_id = ?",
                    (now_iso(), media_type, tmdb_id),
                )
            # Clear local_theme_file (the file we just deleted) but
            # leave has_theme alone for now — the inline-verify
            # below decides its final state based on Plex's actual
            # response.
            # v1.14.27: pre-fix this UPDATE blindly set has_theme=0,
            # which on +P composite rows (motif placement + Plex
            # serves its own embed/cloud) made the chip wrongly drop
            # to '-' even though Plex's own theme survived. The new
            # LET PLEX SERVE flow (which routes here) needs the chip
            # to flip to P when Plex still has its own. Inline-verify
            # below mirrors api_forget_item's pattern.
            pre_has_theme: dict[str, int] = {}
            affected_rks: set[str] = set()
            # v1.20.15: rks whose section just had a motif sidecar
            # unlinked — skipped in the HEAD-verify below (phantom-P).
            placement_owned_rks: set[str] = set()
            # v1.15.90: switched from `WHERE folder_path = ?` to a
            # natural-key lookup (theme_id, fallback to guid_tmdb +
            # media_type). The folder_path-based match silently
            # failed on multi-volume setups where placements.
            # media_folder is the FolderIndex-resolved container
            # path (e.g. /data/media/movies/X) while plex_items.
            # folder_path is Plex's reported host path (e.g.
            # /mnt/user/movies/X). They're different strings for
            # the same logical folder — the placement worker at
            # placement.py:280+ already does host→container
            # translation via _candidate_local_paths, so placements
            # work — but unplace's UPDATE matched 0 plex_items
            # rows and left local_theme_file=1 from a prior
            # plex_enum stat. The row then rendered as SRC=M
            # post-LET-PLEX-SERVE even though the file was actually
            # unlinked. the user's repro: M+P+DL+PS state after
            # LET PLEX SERVE on an Unraid setup with
            # /mnt/user/movies/... ↔ /data/media/movies/... paths.
            # v0.51.48: else media_type (was "movie") so DEL/unplace on a themed
            # collection matches its plex_items rows (media_type='collection').
            plex_media_type = "show" if media_type == "tv" else media_type
            # Resolve theme_id once. Most rows have it set (post
            # resolve_theme_ids); the guid_tmdb fallback covers
            # the pre-resolve window + orphan rows where the
            # synthetic theme isn't joined via theme_id.
            theme_id_lookup = conn.execute(
                "SELECT id FROM themes WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            theme_id_pk = theme_id_lookup["id"] if theme_id_lookup else None
            # Build the plex_items lookup. Scope to section_id when
            # provided (per-section unplace) — otherwise gather every
            # section's plex_items rows for this title (legacy global
            # unplace fan-out).
            pi_where_parts = []
            pi_where_args: list = []
            if theme_id_pk is not None:
                pi_where_parts.append("theme_id = ?")
                pi_where_args.append(theme_id_pk)
            pi_where_parts.append(
                "(guid_tmdb = ? AND media_type = ?)"
            )
            pi_where_args.extend([str(tmdb_id), plex_media_type])
            pi_where = " OR ".join(pi_where_parts)
            if section_id:
                pi_where = f"({pi_where}) AND section_id = ?"
                pi_where_args.append(section_id)
            # v1.22.22 (edition audit): when the click carried a rating_key,
            # that rk IS the clicked edition — restrict the plex_items flag
            # flip (and the affected-rk gather feeding the inline verify) to
            # exactly it. Pre-fix the section-wide pi_where flipped
            # local_theme_file=0 + plex_theme_verified_ok=NULL on EVERY
            # edition's row in the section, so a sibling edition's SRC pill
            # wrongly dropped M/A→P/– until the next plex_enum re-stat. The
            # placements DELETE + local_files UPDATE in this handler were
            # already edition-scoped (v1.21.61/.67); this plex_items flip was
            # the one site left section-wide. rating_key is the plex_items PK,
            # so it's exact even for orphan rows (no theme_id/guid_tmdb match).
            if rating_key:
                pi_where = "rating_key = ?"
                pi_where_args = [rating_key]
            rows = conn.execute(
                f"SELECT rating_key, has_theme, section_id "
                f"FROM plex_items WHERE {pi_where}",
                pi_where_args,
            ).fetchall()
            for r in rows:
                affected_rks.add(r["rating_key"])
                pre_has_theme[r["rating_key"]] = r["has_theme"] or 0
                if (r["section_id"] or "") in sidecar_unlinked_sections:
                    placement_owned_rks.add(r["rating_key"])
            conn.execute(
                f"UPDATE plex_items SET local_theme_file = 0, "
                f"                      plex_theme_verified_ok = NULL "
                f"WHERE {pi_where}",
                pi_where_args,
            )
        try:
            # v1.22.69 (audit round 2): off the event loop — the helper
            # opens a PlexClient and fires one refresh round-trip per
            # matching plex_items row (title-wide); the sync call froze
            # every concurrent request while Plex was slow. The helper
            # indirection evaded the v1.22.58 lint (now covered via
            # BLOCKING_FUNCS).
            await run_in_threadpool(
                _trigger_plex_item_refresh, media_type, tmdb_id)
        except Exception as e:
            log.debug("plex item refresh skipped: %s", e)
        # v1.14.27: inline-verify Plex's theme for each affected rk.
        # Mirrors api_forget_item's pattern (api.py:8770+) so the chip
        # flips correctly:
        #   HEAD 200 → Plex has its own theme → has_theme stays 1,
        #              plex_theme_verified_ok=1 → SRC=P
        #   HEAD 404 → Plex has nothing → has_theme=0, verified_ok=0
        #              → SRC='-'
        #   transient → leave verified_ok=NULL → optimistic; the
        #              v1.12.113 TTL re-verifies later
        if affected_rks and settings.plex_enabled and settings.plex_token:
            try:
                from ..core.plex import PlexClient, PlexConfig
                cfg = PlexConfig(
                    url=settings.plex_url, token=settings.plex_token,
                    movie_section=settings.plex_movie_section,
                    tv_section=settings.plex_tv_section, enabled=True,
                )
                with PlexClient(cfg, plus_mode=settings.plus_equiv_mode) as plex, \
                        get_conn(db) as conn:  # type: ignore[arg-type]
                    for rk in affected_rks:
                        # Skip rks where motif owned the file we just
                        # deleted (placement-source) AND pre_has_theme
                        # was 0 — those rks have no Plex-side theme to
                        # verify. Setting has_theme=0 + verified_ok=0
                        # below covers them.
                        # For rks that HAD a theme pre-delete: Plex
                        # might be serving its own embed/cloud theme
                        # alongside motif's; HEAD probe finds out.
                        if not pre_has_theme.get(rk, 0):
                            conn.execute(
                                "UPDATE plex_items SET has_theme = 0, "
                                "                      plex_theme_verified_ok = 0 "
                                "WHERE rating_key = ?",
                                (rk,),
                            )
                            continue
                        # v1.20.15: skip the HEAD-verify for rks where
                        # motif just unlinked its own sidecar — Plex's
                        # /theme cache returns a stale 200 for seconds,
                        # which would restore has_theme=1/verified_ok=1
                        # and render a phantom P. Leave verified_ok=NULL;
                        # the v1.12.113 TTL + the next plex_enum reconcile
                        # with an accurate read (audit MED-2 / class 1;
                        # mirrors the PURGE rk_from_placement skip at the
                        # api_purge handler).
                        # v1.20.66: PU rks bypass the unreliable stale-200
                        # HEAD probe using the restore loop's per-rk
                        # outcome (they can't be in placement_owned_rks —
                        # that set is folder/sidecar-based).
                        if rk in pu_zero_rks:
                            conn.execute(
                                "UPDATE plex_items SET has_theme = 0, "
                                "                      plex_theme_verified_ok = 0 "
                                "WHERE rating_key = ?",
                                (rk,),
                            )
                            continue
                        if rk in pu_kept_rks:
                            # Fallback restored → Plex serves its own theme.
                            # Leave verified_ok=NULL (optimistic P); the
                            # next plex_enum confirms with an accurate read.
                            continue
                        if rk in placement_owned_rks:
                            continue
                        try:
                            # v1.21.39 (audit H2): use the TRISTATE
                            # verify_theme_claim (True/False/None), NOT the
                            # bool item_has_theme. item_has_theme collapses
                            # a transient error (network/timeout/5xx) to
                            # False — so a Plex hiccup mid-unplace wrongly
                            # wrote has_theme=0/verified_ok=0, and since
                            # _verify_theme_claims only re-checks has_theme=1
                            # rows, the row stayed falsely themeless (SRC off
                            # P) until the next FULL plex_enum. The
                            # None-branch below (leave verified_ok=NULL) was
                            # dead under item_has_theme; it's live now.
                            # v1.22.58: off the event loop (the inline-verify
                            # Plex round-trip was a missed v1.21.20-class block;
                            # the v1.22.42 pass offloaded the restore loop's
                            # calls but not this one).
                            verified = await run_in_threadpool(
                                plex.verify_theme_claim, rk)
                        except Exception as e:
                            log.debug(
                                "unplace inline-verify failed for rk=%s: %s",
                                rk, e,
                            )
                            continue  # leave verified_ok=NULL
                        if verified is True:
                            conn.execute(
                                "UPDATE plex_items SET has_theme = 1, "
                                "                      plex_theme_verified_ok = 1 "
                                "WHERE rating_key = ?",
                                (rk,),
                            )
                        elif verified is False:
                            conn.execute(
                                "UPDATE plex_items SET has_theme = 0, "
                                "                      plex_theme_verified_ok = 0 "
                                "WHERE rating_key = ?",
                                (rk,),
                            )
                        # None → transient; verified_ok stays NULL
            except Exception as e:
                log.warning("unplace inline-verify aborted: %s", e)
        with get_conn(db) as conn:
            _record_audit(
                conn, actor=request.state.user, action="unplace",
                media_type=media_type, tmdb_id=tmdb_id,
                section_id=section_id,
                details={"placements_unlinked": unlinked,
                         "placements_total": len(placements),
                         "api_handled": api_handled,
                         "api_restored": api_restored},
            )
        log_event(db, level="INFO", component="api",
                  media_type=media_type, tmdb_id=tmdb_id,
                  section_id=section_id,
                  message=f"Unplaced by {request.state.user}",
                  detail={"title": theme["title"],
                          "placements_unlinked": unlinked,
                          "placements_total": len(placements),
                          "api_handled": api_handled,
                          "api_restored": api_restored})
        return {"ok": True, "placements_unlinked": unlinked,
                "api_handled": api_handled,
                "api_restored": api_restored}

    @app.post("/api/items/{media_type}/{tmdb_id}/replace")
    async def api_replace_item(
        request: Request, media_type: MediaType, tmdb_id: int,
        # v1.21.69: the clicked row's rating_key scopes PUSH/REPLACE to
        # ONE edition. Pre-fix this deleted every edition's placements for
        # the title and enqueued edition-less place jobs whose cached_rk
        # resolved an arbitrary sibling (same class as the REPLACE TDB bug).
        # None = legacy title/section-wide replace (no rk sent).
        rating_key: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        """Re-place motif's existing canonical into the Plex media folder.
        Used after a DEL (unplace) when the user wants to push the
        downloaded theme back without re-fetching from YouTube. Force-
        overwrites any sidecar that has appeared in the meantime.

        v1.18.23: accepts a JSON body `{"kind": "file"|"api"}` that
        scopes the placement method for movie/TV rows. 'file' takes
        the legacy sidecar path (hardlink/copy at Plex folder);
        'api' POSTs audio bytes to /library/metadata/{rk}/themes
        (the same path collections use). Absent → worker uses the
        global `placement.default_method` setting. Before
        enqueuing the new place job, any existing placements row
        for the (media_type, tmdb_id, section_id) tuple is deleted
        so the transition is clean (no two placements of different
        kinds coexisting).
        """
        _require_admin(request)
        # v1.18.23: parse the optional kind body. Tolerates missing
        # body (legacy redownload callers send empty payload).
        kind: str | None = None
        try:
            body = await request.json()
            raw_kind = (body or {}).get("kind")
            if raw_kind in ("file", "api"):
                kind = raw_kind
        except Exception as e:  # noqa: BLE001
            # v1.18.72 (class 9): legacy callers send no body — that
            # path raises JSONDecodeError here, kind stays None, and
            # the worker uses the global default_placement_method.
            # Pre-fix bare `pass` swallowed both that (intended) and
            # malformed-body errors (unintended). Log at debug so
            # the legacy-empty case stays quiet but malformed-body
            # debugging has a thread to pull on.
            log.debug(
                "api_replace_item: body parse failed (kind stays "
                "default): %s", e,
            )
        with get_conn(db) as conn, transaction(conn):
            # v1.21.69: resolve the clicked edition once; every scope below
            # narrows to it when a rating_key was sent. '' = standard
            # edition; None = legacy (un-scoped) behavior, byte-identical.
            _repl_edition = (
                edition_key_for_rating_key(conn, rating_key)
                if rating_key else None)
            _repl_ed_clause = (
                " AND edition_key = ?" if _repl_edition is not None else "")
            _repl_ed_params = (
                (_repl_edition,) if _repl_edition is not None else ())
            # v1.11.0: enqueue one place job per section that has a
            # local_files row for this item. Sections without staged
            # content are skipped — re-download is a separate action.
            sections = conn.execute(
                "SELECT section_id FROM local_files "
                "WHERE media_type = ? AND tmdb_id = ?" + _repl_ed_clause,
                (media_type, tmdb_id) + _repl_ed_params,
            ).fetchall()
            if not sections:
                raise HTTPException(
                    status_code=409,
                    detail="no local file to replace from — re-download first",
                )
            # v1.18.23: when the caller specified a kind that differs
            # from the existing placement, drop the existing placement
            # row first so the worker writes the new kind cleanly.
            # Decision-locked: one placement per row (no coexistence).
            # v1.18.60: BEFORE dropping the placement row, also
            # tear down Plex's API entry for any prior plex_upload
            # placements when the new kind is 'file'. Mirrors the
            # v1.18.36 SWITCH api→file teardown — REPLACE with
            # kind='file' on a prior plex_upload row reached the
            # same end state (motif's API entry stale on Plex,
            # new sidecar appears, Plex may still serve the API
            # entry) but bypassed the SWITCH endpoint entirely.
            # The cleanup must happen BEFORE the DELETE FROM
            # placements row drop, otherwise the teardown helper
            # has nothing to look at.
            # v1.18.71: collect per-section rks for the api→file
            # transition INSTEAD of calling the synchronous
            # _teardown_plex_api_artifacts_for_placements helper.
            # Same atomic pattern as v1.18.71's SWITCH PLACEMENT
            # [api→file] fix: the worker calls plex.delete_theme()
            # ONLY after the new sidecar place succeeds, so a
            # hardlink failure leaves the Plex API selection
            # intact (row keeps playing the prior plex_upload
            # entry). The shared _teardown_* helper stays
            # SYNCHRONOUS for its destructive callers (PURGE /
            # FORGET / DELETE) — no async work follows them.
            repl_clear_rks_per_section: dict[str, list[str]] = {}
            if kind:
                existing_placements = conn.execute(
                    "SELECT placement_kind, section_id "
                    "FROM placements "
                    "WHERE media_type = ? AND tmdb_id = ?" + _repl_ed_clause,
                    (media_type, tmdb_id) + _repl_ed_params,
                ).fetchall()
                if kind == "file":
                    # v0.51.48: else media_type for convention uniformity —
                    # collections never take the kind='file' sidecar path (no
                    # media folder), so in practice this only sees movie/tv.
                    repl_plex_mt = (
                        "show" if media_type == "tv" else media_type
                    )
                    tid_row = conn.execute(
                        "SELECT id FROM themes "
                        "WHERE media_type = ? AND tmdb_id = ?",
                        (media_type, tmdb_id),
                    ).fetchone()
                    tid_pk = tid_row["id"] if tid_row else None
                    for pr in existing_placements:
                        if (pr["placement_kind"] or "") != "plex_upload":
                            continue
                        section = pr["section_id"]
                        # v1.21.69: scope the teardown rk to this edition
                        # so the api→file Plex DELETE doesn't clear a
                        # sibling edition's API theme.
                        rk_row = None
                        if tid_pk is not None:
                            rk_row = conn.execute(
                                "SELECT rating_key FROM plex_items "
                                "WHERE theme_id = ? AND section_id = ?"
                                + _repl_ed_clause,
                                (tid_pk, section) + _repl_ed_params,
                            ).fetchone()
                        if rk_row is None:
                            rk_row = conn.execute(
                                "SELECT rating_key FROM plex_items "
                                "WHERE guid_tmdb = ? AND media_type = ? "
                                "  AND section_id = ?" + _repl_ed_clause,
                                (str(tmdb_id), repl_plex_mt, section)
                                + _repl_ed_params,
                            ).fetchone()
                        if rk_row is None:
                            log.warning(
                                "replace[api→file]: no rating_key "
                                "for %s/%s section_id=%s — skipping "
                                "Plex API teardown",
                                media_type, tmdb_id, section,
                            )
                            continue
                        repl_clear_rks_per_section.setdefault(
                            str(section), []).append(
                                rk_row["rating_key"])
                conn.execute(
                    "DELETE FROM placements "
                    "WHERE media_type = ? AND tmdb_id = ?" + _repl_ed_clause,
                    (media_type, tmdb_id) + _repl_ed_params,
                )
            # v1.22.76: edition-scoped when the PUSH named an edition (the
            # v1.21.82 payload convention) — pre-fix this title-wide cancel
            # killed sibling editions' pending place jobs while the
            # re-enqueue below only re-covers THIS edition's sections.
            if _repl_edition is not None:
                conn.execute(
                    """UPDATE jobs SET status = 'cancelled', finished_at = ?
                       WHERE job_type = 'place' AND media_type = ? AND tmdb_id = ?
                         AND COALESCE(CASE WHEN json_valid(payload) THEN
                               json_extract(payload, '$.edition_key')
                             END, '') = ?
                         AND status IN ('pending','running')""",
                    (now_iso(), media_type, tmdb_id, _repl_edition),
                )
            else:
                conn.execute(
                    """UPDATE jobs SET status = 'cancelled', finished_at = ?
                       WHERE job_type = 'place' AND media_type = ? AND tmdb_id = ?
                         AND status IN ('pending','running')""",
                    (now_iso(), media_type, tmdb_id),
                )
            for s in sections:
                payload_obj = {"force": True, "reason": "user_replace"}
                if kind:
                    payload_obj["kind"] = kind
                # v1.21.69: carry edition_key so the place job lands in
                # THIS edition's folder/rk (the worker's cached_rk lookup
                # is edition-scoped since v1.21.66).
                if _repl_edition is not None:
                    payload_obj["edition_key"] = _repl_edition
                # v1.18.71: thread the per-section Plex API rks
                # the worker should clear AFTER its hardlink lands.
                # Only populated for kind='file' (the api→file
                # transition); for kind='api' or kind=None the
                # field is omitted entirely.
                repl_sec_rks = repl_clear_rks_per_section.get(
                    str(s["section_id"]), [])
                if repl_sec_rks:
                    payload_obj["clear_plex_api_rks"] = repl_sec_rks
                conn.execute(
                    """INSERT INTO jobs (job_type, media_type, tmdb_id, section_id,
                                         payload, status, created_at, next_run_at)
                       VALUES ('place', ?, ?, ?, ?,
                               'pending', ?, ?)""",
                    (media_type, tmdb_id, s["section_id"],
                     json.dumps(payload_obj),
                     now_iso(), now_iso()),
                )
            _record_audit(
                conn, actor=request.state.user,
                action="replace_with_themerrdb",
                media_type=media_type, tmdb_id=tmdb_id,
                details={"kind": kind} if kind else None,
            )
        log_event(db, level="INFO", component="api",
                  media_type=media_type, tmdb_id=tmdb_id,
                  message=(
                      f"Replace requested by {request.state.user}"
                      + (f" (kind={kind})" if kind else "")
                  ))
        return {"ok": True, "kind": kind}

    @app.post(
        "/api/items/{media_type}/{tmdb_id}/switch-placement"
    )
    async def api_switch_placement(
        request: Request, media_type: MediaType, tmdb_id: int,
        # v1.21.69: scope the file↔api flip to the clicked edition. Pre-fix
        # it DELETEd every edition's placements + enqueued edition-less
        # place jobs → arbitrary cached_rk (same class as REPLACE TDB).
        # None = legacy title/section-wide switch (no rk sent).
        rating_key: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        """v1.18.23: flip a placement between sidecar (file) and
        plex_upload (api). Mirrors /replace but inverts the
        current placement_kind automatically — convenience action
        so users don't have to compute the target kind themselves
        from the row state. Collections reject (no sidecar option).

        Returns 409 if the row has no existing placement to
        switch from."""
        _require_admin(request)
        if media_type == "collection":
            raise HTTPException(
                status_code=400,
                detail="collections always use API push — "
                       "no sidecar option to switch to",
            )
        with get_conn(db) as conn:
            # v1.21.69: resolve the clicked edition once; reused across the
            # later get_conn blocks (clause/params are conn-independent).
            _sw_edition = (
                edition_key_for_rating_key(conn, rating_key)
                if rating_key else None)
            _sw_ed_clause = (
                " AND edition_key = ?" if _sw_edition is not None else "")
            _sw_ed_params = (
                (_sw_edition,) if _sw_edition is not None else ())
            existing = conn.execute(
                "SELECT DISTINCT placement_kind FROM placements "
                "WHERE media_type = ? AND tmdb_id = ?" + _sw_ed_clause,
                (media_type, tmdb_id) + _sw_ed_params,
            ).fetchall()
        if not existing:
            raise HTTPException(
                status_code=409,
                detail="no existing placement to switch from",
            )
        kinds = {r["placement_kind"] for r in existing}
        # v1.18.23: target kind is the inverse of what's there.
        # Mixed-kind state shouldn't exist (the /replace path
        # cleans up before insert) but if it does, prefer the
        # safer fallback — switch to file (sidecar).
        if "plex_upload" in kinds and not (kinds - {"plex_upload"}):
            target_kind = "file"
        else:
            target_kind = "api"
        # v1.18.36: tear down the OUTGOING placement BEFORE queueing
        # the new place job. Pre-fix the SWITCH endpoint only
        # DELETEd the placement row and queued the new job —
        # leaving the prior placement's artifact orphaned:
        #   - file→api: theme.mp3 left at the Plex media folder
        #     (the user's M*A*S*H bug: cyan PL + PU LINK in motif
        #      but sidecar still on disk; sidecar may still win
        #      Plex's resolution race).
        #   - api→file: motif's prior Plex API upload entry
        #     stays in /themes (with selected:true potentially),
        #     and motif's new sidecar may not become active
        #     because the API upload still wins resolution.
        # v1.18.36 explicitly tears down the outgoing artifact.
        with get_conn(db) as conn:
            outgoing = conn.execute(
                "SELECT media_folder, placement_kind, section_id "
                "FROM placements "
                "WHERE media_type = ? AND tmdb_id = ?" + _sw_ed_clause,
                (media_type, tmdb_id) + _sw_ed_params,
            ).fetchall()
        # v1.18.68: collect sidecar paths for file→api WITHOUT
        # removing them yet. The place job that the endpoint
        # enqueues below now removes these AFTER a successful
        # Plex upload (worker.py `_do_place_collection`). Pre-fix
        # the unlink fired synchronously here — if the place
        # job then failed (Plex 500 on a large file, network
        # error, etc.), the row was left with NO sidecar AND
        # NO Plex upload → unthemed until manual recovery.
        # the user's repro: 27MB '100 Foot Wave' rejected with
        # HTTP 500, sidecar already gone, row stuck at M / amber.
        sidecar_paths_per_section: dict[str, list[str]] = {}
        if target_kind == "api":
            for pr in outgoing:
                if (pr["placement_kind"] or "") == "plex_upload":
                    continue
                side = Path(pr["media_folder"] or "") / "theme.mp3"
                if side.is_file():
                    section_key = str(pr["section_id"])
                    sidecar_paths_per_section.setdefault(
                        section_key, []).append(str(side))
        # v1.18.71: per-section rk collection for the api→file
        # direction. Same atomic-teardown pattern as v1.18.68 in
        # reverse — the endpoint stops calling plex.delete_theme()
        # synchronously and instead threads the rks through each
        # section's place job payload. The worker calls delete_theme
        # ONLY after the sidecar hardlink lands, so a hardlink
        # failure leaves the Plex API selection intact (row keeps
        # playing the prior plex_upload entry). Pre-fix: hardlink
        # could fail (cross-FS + disk-full) AFTER the Plex API
        # selection was already cleared → row themeless until
        # manual recovery.
        clear_rks_per_section: dict[str, list[str]] = {}
        if target_kind == "file" and outgoing:
            # v0.51.48: else media_type for uniformity — the endpoint 400s on
            # media_type=='collection' above, so this only ever sees movie/tv.
            plex_mt_for_lookup = "show" if media_type == "tv" else media_type
            with get_conn(db) as conn:
                tid_row = conn.execute(
                    "SELECT id FROM themes "
                    "WHERE media_type = ? AND tmdb_id = ?",
                    (media_type, tmdb_id),
                ).fetchone()
                tid_pk = tid_row["id"] if tid_row else None
                for pr in outgoing:
                    if (pr["placement_kind"] or "") != "plex_upload":
                        continue
                    section = pr["section_id"]
                    # v1.21.69: scope the teardown rk to this edition.
                    rk_row = None
                    if tid_pk is not None:
                        rk_row = conn.execute(
                            "SELECT rating_key FROM plex_items "
                            "WHERE theme_id = ? AND section_id = ?"
                            + _sw_ed_clause,
                            (tid_pk, section) + _sw_ed_params,
                        ).fetchone()
                    if rk_row is None:
                        rk_row = conn.execute(
                            "SELECT rating_key FROM plex_items "
                            "WHERE guid_tmdb = ? AND media_type = ? "
                            "  AND section_id = ?" + _sw_ed_clause,
                            (str(tmdb_id), plex_mt_for_lookup, section)
                            + _sw_ed_params,
                        ).fetchone()
                    if rk_row is None:
                        log.warning(
                            "switch_placement[api→file]: no "
                            "rating_key for %s/%s section_id=%s — "
                            "skipping Plex API teardown",
                            media_type, tmdb_id, section,
                        )
                        continue
                    clear_rks_per_section.setdefault(
                        str(section), []).append(rk_row["rating_key"])
        with get_conn(db) as conn, transaction(conn):
            sections = conn.execute(
                "SELECT section_id FROM local_files "
                "WHERE media_type = ? AND tmdb_id = ?" + _sw_ed_clause,
                (media_type, tmdb_id) + _sw_ed_params,
            ).fetchall()
            if not sections:
                raise HTTPException(
                    status_code=409,
                    detail="no local file — re-download first",
                )
            conn.execute(
                "DELETE FROM placements "
                "WHERE media_type = ? AND tmdb_id = ?" + _sw_ed_clause,
                (media_type, tmdb_id) + _sw_ed_params,
            )
            # v1.22.76: edition-scoped when SWITCH named an edition (mirror
            # the PUSH cancel above) — pre-fix it killed sibling editions'
            # pending place jobs the re-enqueue below never re-covers.
            if _sw_edition is not None:
                conn.execute(
                    """UPDATE jobs SET status = 'cancelled', finished_at = ?
                       WHERE job_type = 'place' AND media_type = ? AND tmdb_id = ?
                         AND COALESCE(CASE WHEN json_valid(payload) THEN
                               json_extract(payload, '$.edition_key')
                             END, '') = ?
                         AND status IN ('pending','running')""",
                    (now_iso(), media_type, tmdb_id, _sw_edition),
                )
            else:
                conn.execute(
                    """UPDATE jobs SET status = 'cancelled', finished_at = ?
                       WHERE job_type = 'place' AND media_type = ? AND tmdb_id = ?
                         AND status IN ('pending','running')""",
                    (now_iso(), media_type, tmdb_id),
                )
            for s in sections:
                # v1.18.68: thread the per-section sidecar paths
                # into the place job payload. _do_place_collection
                # removes them ONLY after a successful Plex upload
                # so a Plex-side failure leaves the sidecar intact.
                # v1.18.71: same atomic pattern in REVERSE for
                # api→file — pass the per-section rk(s) whose Plex
                # API selection needs clearing. Worker calls
                # plex.delete_theme(rk) ONLY after the sidecar
                # hardlink lands.
                sec_payload = {
                    "force": True,
                    "reason": "user_switch_placement",
                    "kind": target_kind,
                }
                # v1.21.69: place job carries edition_key → lands in THIS
                # edition's folder/rk (cached_rk lookup edition-scoped).
                if _sw_edition is not None:
                    sec_payload["edition_key"] = _sw_edition
                sec_sidecars = sidecar_paths_per_section.get(
                    str(s["section_id"]), []) if target_kind == "api" else []
                if sec_sidecars:
                    sec_payload["remove_sidecar_paths"] = sec_sidecars
                sec_clear_rks = clear_rks_per_section.get(
                    str(s["section_id"]), []) if target_kind == "file" else []
                if sec_clear_rks:
                    sec_payload["clear_plex_api_rks"] = sec_clear_rks
                conn.execute(
                    """INSERT INTO jobs (job_type, media_type, tmdb_id, section_id,
                                         payload, status, created_at, next_run_at)
                       VALUES ('place', ?, ?, ?, ?,
                               'pending', ?, ?)""",
                    (media_type, tmdb_id, s["section_id"],
                     json.dumps(sec_payload),
                     now_iso(), now_iso()),
                )
            _record_audit(
                conn, actor=request.state.user,
                action="switch_placement",
                media_type=media_type, tmdb_id=tmdb_id,
                details={"target_kind": target_kind,
                         "from_kinds": sorted(kinds)},
            )
        log_event(
            db, level="INFO", component="api",
            media_type=media_type, tmdb_id=tmdb_id,
            message=(
                f"Switch placement → {target_kind} requested by "
                f"{request.state.user}"
            ),
        )
        return {"ok": True, "target_kind": target_kind}

    # v1.11.99: mismatch-resolution endpoints. These complement the
    # existing /replace (PUSH TO PLEX) endpoint above:
    #
    #   PUSH TO PLEX     → /replace            — write canonical to placement
    #   ADOPT FROM PLEX  → /adopt-from-plex    — replace canonical with placement
    #   KEEP MISMATCH    → /keep-mismatch      — flip 'pending' → 'acked';
    #                                            stays in library as DL=amber
    #                                            + LINK=≠ but exits /pending
    #
    # The first two clear mismatch_state on success (place worker
    # handles PUSH; adopt-from-plex sets it directly). KEEP MISMATCH
    # is a state-only flip — no file mutation.

    @app.post("/api/items/{media_type}/{tmdb_id}/adopt-from-plex")
    async def api_adopt_from_plex(
        request: Request, media_type: MediaType, tmdb_id: int,
        db: Path = Depends(get_db_path),
    ):
        """v1.11.99: replace motif's canonical with the file currently at
        the placement (Plex folder) — the inverse of PUSH TO PLEX.

        Use case: user uploaded / set URL on a row that already had a
        placement, decides on review they want to keep what Plex is
        actually playing instead of the new download. We hardlink the
        placement file back into canonical (new inode for canonical,
        same inode as placement → matched again), discarding the
        rejected new download.
        """
        _require_admin(request)
        if not settings.is_paths_ready():
            raise HTTPException(
                status_code=409,
                detail="themes_dir not configured; visit /settings",
            )
        with get_conn(db) as conn:
            rows = conn.execute(
                # v1.21.72: join + carry edition_key so each mismatch row
                # re-adopts ITS OWN edition's placement file (the
                # (mt,tmdb,section) JOIN paired with an arbitrary sibling's
                # placement on a multi-edition title, and the UPDATEs below
                # cleared the wrong edition's mismatch / placement_kind).
                """SELECT lf.section_id, lf.edition_key,
                          lf.file_path AS canon_rel, p.media_folder
                     FROM local_files lf
                     JOIN placements p
                       ON p.media_type = lf.media_type
                      AND p.tmdb_id = lf.tmdb_id
                      AND p.section_id = lf.section_id
                      AND p.edition_key = lf.edition_key
                    WHERE lf.media_type = ? AND lf.tmdb_id = ?
                      AND lf.mismatch_state IS NOT NULL""",
                (media_type, tmdb_id),
            ).fetchall()
        if not rows:
            raise HTTPException(
                status_code=409,
                detail="no mismatch state to resolve",
            )
        import hashlib
        adopted = 0
        for r in rows:
            placement_file = Path(r["media_folder"]) / "theme.mp3"
            if not placement_file.is_file():
                log.warning(
                    "adopt-from-plex: placement file missing at %s — skipping",
                    placement_file,
                )
                continue
            canon_path = settings.themes_dir / r["canon_rel"]
            # v1.22.31 (audit): atomic replace. Pre-fix canon was unlinked
            # BEFORE the replacement was secured — if BOTH the hardlink and the
            # copy fell over (broken FS / disk-full / perms) the row was left
            # with NO canonical file (tracking → missing-on-disk drift),
            # recoverable only on a later retry. Link/copy placement → a temp
            # sibling first, then os.replace over canon: canon is never
            # destroyed until the new content is in place.
            tmp_canon = canon_path.with_name(canon_path.name + ".adopt.tmp")
            try:
                import os
                import shutil
                canon_path.parent.mkdir(parents=True, exist_ok=True)
                # v1.22.69: cross-FS copy is multi-MB blocking I/O — offload.
                def _stage_canon(tc=tmp_canon, src=placement_file, dst=canon_path):
                    if tc.exists():
                        tc.unlink()
                    try:
                        tc.hardlink_to(src)
                        kind = "hardlink"
                    except OSError:
                        # Cross-filesystem — fall back to copy.
                        shutil.copy2(src, tc)
                        kind = "copy"
                    os.replace(tc, dst)
                    return kind

                placement_kind = await run_in_threadpool(_stage_canon)
            except OSError as e:
                log.warning(
                    "adopt-from-plex: failed for %s: %s", placement_file, e,
                )
                try:
                    if tmp_canon.exists():
                        tmp_canon.unlink()
                except OSError:
                    pass
                continue
            # Re-read the now-canonical file to refresh sha + size,
            # clear mismatch_state, and align placement.placement_kind.
            # v1.22.69: multi-MB re-read + hash froze the loop — offload.
            def _rehash(p=canon_path):
                return hashlib.sha256(p.read_bytes()).hexdigest(), p.stat().st_size

            sha, size = await run_in_threadpool(_rehash)
            with get_conn(db) as conn, transaction(conn):
                conn.execute(
                    """UPDATE local_files SET file_sha256 = ?, file_size = ?,
                                              downloaded_at = ?,
                                              mismatch_state = NULL
                       WHERE media_type = ? AND tmdb_id = ? AND section_id = ?
                         AND edition_key = ?""",
                    (sha, size, now_iso(),
                     media_type, tmdb_id, r["section_id"], r["edition_key"]),
                )
                conn.execute(
                    """UPDATE placements SET placement_kind = ?
                       WHERE media_type = ? AND tmdb_id = ? AND section_id = ?
                         AND edition_key = ?""",
                    (placement_kind, media_type, tmdb_id, r["section_id"],
                     r["edition_key"]),
                )
            adopted += 1
        if adopted == 0:
            # v1.22.31 (audit): every candidate row was skipped (placement
            # file missing or a filesystem error — see the warnings above).
            # Returning ok:True below was a fake-success: the UI flashed
            # "adopted" while the mismatch stayed unresolved in /pending.
            raise HTTPException(
                status_code=409,
                detail="adopt failed: no sections could be adopted (placement "
                       "file missing or filesystem error — see logs)",
            )
        with get_conn(db) as conn:
            _record_audit(
                conn, actor=request.state.user, action="adopt",
                media_type=media_type, tmdb_id=tmdb_id,
                details={"sections_adopted": adopted},
            )
        log_event(db, level="INFO", component="api",
                  media_type=media_type, tmdb_id=tmdb_id,
                  message=f"Adopt from Plex by {request.state.user}",
                  detail={"sections_adopted": adopted})
        return {"ok": True, "sections_adopted": adopted}

    @app.post("/api/items/{media_type}/{tmdb_id}/keep-mismatch")
    async def api_keep_mismatch(
        request: Request, media_type: MediaType, tmdb_id: int,
        # v1.21.79: the clicked row's rating_key scopes the ack to THIS
        # edition (+ its section). Pre-fix the UPDATE acked EVERY edition's
        # and section's pending mismatch for the title at once. None =
        # legacy title-wide ack.
        rating_key: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        """v1.11.99: ack the mismatch — drop it out of /pending but
        keep the canonical / placement divergence intact. Library row
        continues to render DL=amber + LINK=≠ as a passive reminder
        that motif holds a download Plex isn't playing.
        """
        _require_admin(request)
        with get_conn(db) as conn:
            _km_clause = ""
            _km_params: list = [media_type, tmdb_id]
            if rating_key:
                _km_pi = conn.execute(
                    "SELECT section_id, folder_path FROM plex_items "
                    "WHERE rating_key = ?",
                    (rating_key,),
                ).fetchone()
                if _km_pi:
                    _km_clause = " AND section_id = ? AND edition_key = ?"
                    _km_params += [
                        _km_pi["section_id"],
                        edition_key_for_folder(_km_pi["folder_path"]),
                    ]
                else:
                    # v1.22.76: a stale rk (the v1.18.90 reaper re-minted
                    # it) used to fall through to a TITLE-WIDE ack with no
                    # breadcrumb — fail-open scope widening. Refuse instead;
                    # the page refresh picks up the new rk.
                    raise HTTPException(
                        status_code=409,
                        detail=("stale rating_key — Plex re-minted this "
                                "item; refresh the page and retry"),
                    )
            cur = conn.execute(
                "UPDATE local_files SET mismatch_state = 'acked' "
                "WHERE media_type = ? AND tmdb_id = ? "
                "  AND mismatch_state = 'pending'" + _km_clause,
                tuple(_km_params),
            )
            if cur.rowcount == 0:
                raise HTTPException(
                    status_code=409,
                    detail="no pending mismatch to ack",
                )
        log_event(db, level="INFO", component="api",
                  media_type=media_type, tmdb_id=tmdb_id,
                  message=f"Keep mismatch by {request.state.user}",
                  detail={"sections_acked": cur.rowcount})
        return {"ok": True, "sections_acked": cur.rowcount}

    @app.post("/api/items/{media_type}/{tmdb_id}/unmanage")
    async def api_unmanage_item(
        request: Request, media_type: MediaType, tmdb_id: int,
        # v1.12.73: optional section_id scopes UNMANAGE to one
        # section. Without it, every section that motif manages
        # for this title gets unmanaged at once (legacy fan-out).
        # Mirrors the v1.12.46 ACCEPT UPDATE / v1.12.47 REVERT
        # scoping; per-edition theming (v1.12.72) requires this
        # so unmanaging the 4K edition doesn't yank motif's
        # tracking from the standard edition too.
        section_id: str | None = Query(None),
        # v1.21.84: rating_key scopes UNMANAGE to ONE edition — editions of a
        # title can share a section, so section scope alone destroys siblings
        # (the v1.21.83 PURGE data-loss class, ported here).
        rating_key: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        """v1.10.18: drop motif's management of a theme without deleting
        the file at the Plex folder.

        Workflow:
          - Delete motif's canonical (/themes/<movies|tv>/<Title (Year)>/theme.mp3).
            For hardlink placements the file at the Plex folder shares the
            inode and survives; for copy placements the Plex copy is
            independent and likewise survives.
          - Drop local_files + placements rows.
          - For plex_orphan rows: drop the themes row too (FK CASCADE
            cleans children) so the orphan doesn't linger with no
            local_files. Real ThemerrDB rows keep the themes row so the
            row reappears as themed-but-unmanaged.

        Result: row flips back to M (unmanaged sidecar) and can be
        re-adopted, replaced with TDB, or otherwise re-managed via the
        normal row actions. Use case: testing, or temporarily
        disconnecting motif from a title without nuking the actual
        theme file.

        v1.20.57: for a plex_upload (PU) row there is NO sidecar — the
        theme lives in Plex's metadata store as motif's API upload, and
        UNMANAGE does NOT tear it down. So a PU row does not flip to M;
        it lands at P (Plex keeps serving motif's uploaded copy, motif
        just untracks it). The UI copy is branched accordingly.

        v1.12.73: when section_id is provided the action targets just
        that section's local_files + placement; sibling sections'
        management survives. The orphan-themes drop only fires when
        the unmanaged section is the LAST one for the title.
        """
        _require_admin(request)
        # v1.17.16: pre-op enrichment capture. notify_content.enrich_item
        # reads from `themes` / `user_overrides` / `local_files` /
        # `plex_sections` — all of which UNMANAGE may modify (and FORGET /
        # DELETE definitely drop). If enrich_item ran AFTER the txn, the
        # orphan path (last-section UNMANAGE of an upstream_source=
        # 'plex_orphan' row) would find nothing and fall back to the
        # bare-ID display "movie/-26" — the user's screenshot from
        # v1.17.14. Capturing here, outside the txn, keeps the
        # notification body human-readable.
        from ..core import notify_content as _nc
        _notify_ctx = _nc.enrich_item(
            db, media_type=media_type, tmdb_id=tmdb_id,
            section_id=section_id,
        )
        with get_conn(db) as conn, transaction(conn):
            theme = conn.execute(
                "SELECT upstream_source, title FROM themes "
                "WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            if theme is None:
                raise HTTPException(status_code=404, detail="theme not found")
            # v1.21.84: resolve the clicked edition once; _ed_sql/_ed_args
            # narrow every destructive query below to it ('' / legacy
            # whole-section behavior when no rating_key).
            _unm_edition = (edition_key_for_rating_key(conn, rating_key)
                            if rating_key else "")
            _ed_sql = " AND edition_key = ?" if rating_key else ""
            _ed_args = (_unm_edition,) if rating_key else ()
            # v1.11.0: walk every per-section local_files row for this
            # item — UNMANAGE drops motif from all of them at once.
            # v1.12.73: when section_id is provided, scope to that
            # section only.
            if section_id:
                locals_rows = conn.execute(
                    "SELECT section_id, file_path, file_sha256, source_kind, "
                    "       source_video_id "
                    "FROM local_files "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?"
                    + _ed_sql,
                    (media_type, tmdb_id, section_id, *_ed_args),
                ).fetchall()
            else:
                locals_rows = conn.execute(
                    "SELECT section_id, file_path, file_sha256, source_kind, "
                    "       source_video_id "
                    "FROM local_files "
                    "WHERE media_type = ? AND tmdb_id = ?"
                    + _ed_sql,
                    (media_type, tmdb_id, *_ed_args),
                ).fetchall()
            if not locals_rows:
                raise HTTPException(
                    status_code=409,
                    detail="not motif-managed (no local_files row)",
                )
            # v1.10.57: snapshot the youtube_url so a future re-adopt of
            # the same file content can restore the URL.
            # v1.14.35: user_overrides was made per-section (PK
            # includes section_id) in v1.12.72. Pre-fix this code
            # said "user_overrides / themes are section-agnostic"
            # (true for themes; FALSE for user_overrides post-
            # v1.12.72). The title-global SELECT picked an
            # arbitrary section's URL — wrong when a multi-section
            # title has different overrides per edition. Scope to
            # the requested section first; fall back to the global
            # '' row when no per-section override exists.
            if section_id:
                override_row = conn.execute(
                    "SELECT youtube_url FROM user_overrides "
                    "WHERE media_type = ? AND tmdb_id = ? "
                    "  AND section_id = ?",
                    (media_type, tmdb_id, section_id),
                ).fetchone()
                if override_row is None:
                    override_row = conn.execute(
                        "SELECT youtube_url FROM user_overrides "
                        "WHERE media_type = ? AND tmdb_id = ? "
                        "  AND section_id = ''",
                        (media_type, tmdb_id),
                    ).fetchone()
            else:
                override_row = conn.execute(
                    "SELECT youtube_url FROM user_overrides "
                    "WHERE media_type = ? AND tmdb_id = ?",
                    (media_type, tmdb_id),
                ).fetchone()
            theme_yt = conn.execute(
                "SELECT youtube_url FROM themes "
                "WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            saved_youtube_url = (
                (override_row and override_row["youtube_url"])
                or (theme_yt and theme_yt["youtube_url"])
            )
            for lr in locals_rows:
                if lr["file_sha256"]:
                    conn.execute(
                        """INSERT INTO local_files_history
                             (file_sha256, media_type, tmdb_id, source_kind,
                              source_video_id, youtube_url, saved_at, saved_reason)
                           VALUES (?, ?, ?, ?, ?, ?, ?, 'unmanage')""",
                        (lr["file_sha256"], media_type, tmdb_id,
                         lr["source_kind"], lr["source_video_id"],
                         saved_youtube_url, now_iso()),
                    )
            placements = conn.execute(
                "SELECT media_folder FROM placements "
                "WHERE media_type = ? AND tmdb_id = ?"
                + (" AND section_id = ?" if section_id else "")
                + _ed_sql,
                (media_type, tmdb_id,
                 *((section_id,) if section_id else ()), *_ed_args),
            ).fetchall()
            # v1.11.85: snapshot the plex_items rows we'll need to
            # re-stat AFTER the DELETE chain, before any of it runs.
            # Pre-fix the post-DELETE block looked up plex_items via
            # `themes WHERE media_type=? AND tmdb_id=?` to derive a
            # theme_id_pk and then matched pi.theme_id = ?. For the
            # orphan branch (adopted manual sidecars; upstream_source=
            # 'plex_orphan') this lookup fired AFTER `DELETE FROM themes`
            # — so theme_id_pk came back None, the loop skipped entirely,
            # and pi.local_theme_file stayed at whatever value it held
            # before unmanage. Result: row dropped to '—' instead of
            # falling back to M, and only a follow-up REFRESH FROM PLEX
            # would correct it. Capture the pi list here while themes
            # (and pi.theme_id) still exist.
            # v0.51.48: else media_type (was "movie") so UNMANAGE on a themed
            # collection re-stats its plex_items rows (media_type='collection').
            plex_type_for_restat = "show" if media_type == "tv" else media_type
            theme_id_pk_pre_row = conn.execute(
                "SELECT id FROM themes WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            theme_id_pk_pre = (
                theme_id_pk_pre_row["id"] if theme_id_pk_pre_row else None
            )
            pi_rows_to_restat = []
            if theme_id_pk_pre is not None:
                pi_rows_to_restat = [
                    dict(r) for r in conn.execute(
                        "SELECT rating_key, folder_path FROM plex_items "
                        "WHERE theme_id = ? AND media_type = ?"
                        + (" AND section_id = ?" if section_id else "")
                        + _ed_sql,
                        (theme_id_pk_pre, plex_type_for_restat,
                         *((section_id,) if section_id else ()), *_ed_args),
                    ).fetchall()
                ]

        # Delete the per-section canonicals — leave Plex-folder placements intact.
        # v0.51.13 (audit #12, class 12): offloaded — the loop hits the themes
        # mount; a spun-down disk blocks each syscall, freezing the event loop
        # (invisible to the v1.22.58 AST lint). No txn is open here.
        themes_dir = settings.themes_dir

        def _unlink_canonicals() -> None:
            if not themes_dir:
                return
            for lr in locals_rows:
                try:
                    p = themes_dir / lr["file_path"]
                    if p.is_file():
                        p.unlink()
                    # v1.14.57: log non-ENOTEMPTY OSErrors at warning
                    # level. Pre-fix the bare `except OSError: pass`
                    # silently swallowed permission errors / parent
                    # missing / unexpected FS state alongside the
                    # expected "directory not empty" no-op. Now we
                    # filter on errno: ENOTEMPTY / ENOENT are the
                    # benign races (something else wrote into the
                    # parent dir or the parent vanished); everything
                    # else gets a one-line warn so the operator can
                    # see persistent issues.
                    try:
                        parent = p.parent
                        if parent.is_dir() and not any(parent.iterdir()):
                            parent.rmdir()
                    except OSError as rmd_err:
                        import errno as _errno
                        if rmd_err.errno not in (_errno.ENOTEMPTY,
                                                  _errno.ENOENT):
                            log.warning(
                                "unmanage: parent rmdir %s failed "
                                "unexpectedly: %s", p.parent, rmd_err)
                except OSError as e:
                    log.warning("unmanage: could not unlink canonical %s: %s",
                                lr["file_path"], e)
        await run_in_threadpool(_unlink_canonicals)

        is_orphan = theme["upstream_source"] == "plex_orphan"
        # v1.24.13 (holistic review): compute the post-unmanage sidecar re-stat
        # OFF the event loop AND before the write txn below. Pre-fix the restat
        # loop called folder_has_theme_sidecar() (a /data directory walk) per
        # plex_items row INSIDE the BEGIN IMMEDIATE txn — holding the SQLite
        # write lock across N FS scans, which freezes the loop and blocks every
        # other writer (worker/sync/enum) for the walk's duration, badly so on a
        # stale NFS/shfs mount. Precompute {rating_key: sidecar_present} here.
        from ..core.plex_enum import folder_has_theme_sidecar

        def _restat_unmanage_sidecars():
            return {
                r["rating_key"]: folder_has_theme_sidecar(r["folder_path"] or "")
                for r in pi_rows_to_restat
            }
        _restat_present = await run_in_threadpool(_restat_unmanage_sidecars)
        with get_conn(db) as conn, transaction(conn):
            # v1.12.73: when section_id is provided, scope the
            # delete to that section. The orphan-themes drop only
            # fires when this is the LAST section for the title
            # (otherwise we'd nuke the themes row and orphan the
            # other sections' local_files). _drop_motif_tracking
            # also runs only at the last-section step so per-edition
            # overrides survive partial unmanages.
            if section_id:
                # v1.12.79: capture the section's override URL into
                # themes.previous_youtube_url before the override
                # delete so the row keeps a one-step RESTORE path
                # post-UNMANAGE. Mirrors the PURGE capture; the
                # snapshot survives _drop_motif_tracking via v1.12.64.
                # v1.12.102: on_purge=True so any prior previous_url
                # moves to the hidden slot — RESTORE brings the
                # just-dropped URL back, REVERT after RESTORE walks
                # the chain to whatever was previous before this.
                _capture_previous_url(conn, media_type, tmdb_id,
                                      section_id=section_id,
                                      on_purge=True)
                # v1.22.76 (v1.18.73 class gap): UNMANAGE never cancelled
                # in-flight jobs — a pending download/place completing after
                # the deletes below re-INSERTed local_files/placements
                # (ghost tracking reborn). FORGET/UNPLACE/DELETE all call
                # this; UNMANAGE was the straggler.
                _cancel_jobs_for_row(
                    conn, media_type=media_type, tmdb_id=tmdb_id,
                    section_id=section_id,
                )
                # v1.21.84: edition-scoped deletes — a sibling edition in
                # the same section keeps its placement / local_file /
                # override rows + its on-disk canonical (unlinked above only
                # for THIS edition's locals_rows).
                conn.execute(
                    "DELETE FROM placements "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?"
                    + _ed_sql,
                    (media_type, tmdb_id, section_id, *_ed_args),
                )
                conn.execute(
                    "DELETE FROM local_files "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?"
                    + _ed_sql,
                    (media_type, tmdb_id, section_id, *_ed_args),
                )
                # Drop the row's section-specific override (matches
                # the v1.12.72 per-section semantic). The global ''
                # override and sibling sections' overrides survive.
                conn.execute(
                    "DELETE FROM user_overrides "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?"
                    + _ed_sql,
                    (media_type, tmdb_id, section_id, *_ed_args),
                )
                # Last-section detection — drop themes (orphan only)
                # and tracking metadata only when this was the
                # final section.
                remaining = conn.execute(
                    "SELECT COUNT(*) AS n FROM local_files "
                    "WHERE media_type = ? AND tmdb_id = ?",
                    (media_type, tmdb_id),
                ).fetchone()
                last_section = remaining and remaining["n"] == 0
                if last_section:
                    # v1.22.23: spare sibling editions' decisions (see helper).
                    _drop_motif_tracking(
                        conn, media_type, tmdb_id,
                        acted_edition=_unm_edition if rating_key else None)
                    if is_orphan:
                        # v1.17.24: null out URLs instead of
                        # DROPping the themes row. The row stays
                        # as a tracker so the previous_urls JOIN
                        # (keyed on t.media_type/t.tmdb_id at
                        # api.py:1852) can resolve the captured
                        # URL post-UNMANAGE — RESTORE then
                        # surfaces. Pre-fix the DELETE took
                        # plex_items.theme_id with it (FK ON
                        # DELETE SET NULL → t.* NULL in the
                        # JOIN → pv_sec/pv_global unreachable);
                        # the v1.17.17 capture-as-kind='user'
                        # fix was correct but unreachable
                        # because the JOIN itself broke.
                        # the user's screenshot scenario: SET URL
                        # → DOWNLOAD/PLACE → PURGE → no
                        # RESTORE on the now-empty row.
                        # DELETE (api_delete_item) still hard-
                        # deletes for the "nuke this orphan"
                        # case.
                        conn.execute(
                            "UPDATE themes "
                            "SET youtube_url = NULL, "
                            "    youtube_video_id = NULL "
                            "WHERE media_type = ? AND tmdb_id = ?",
                            (media_type, tmdb_id),
                        )
            else:
                # Legacy global UNMANAGE — drops every section at once.
                # v1.12.57: drop motif's tracking metadata (override URL,
                # pending_updates, previous-URL snapshot). UNMANAGE means
                # motif walks away — the file stays at the Plex folder
                # but the metadata that drove motif's tracking should
                # leave too. Pre-fix the override URL lingered, so a
                # later re-adopt or re-download silently re-applied the
                # user's old URL.
                _drop_motif_tracking(conn, media_type, tmdb_id)
                if is_orphan:
                    # v1.17.24: zombie themes (see last-section
                    # branch above for full rationale).
                    conn.execute(
                        "UPDATE themes "
                        "SET youtube_url = NULL, "
                        "    youtube_video_id = NULL "
                        "WHERE media_type = ? AND tmdb_id = ?",
                        (media_type, tmdb_id),
                    )
                else:
                    conn.execute(
                        "DELETE FROM placements WHERE media_type = ? AND tmdb_id = ?",
                        (media_type, tmdb_id),
                    )
                    conn.execute(
                        "DELETE FROM local_files WHERE media_type = ? AND tmdb_id = ?",
                        (media_type, tmdb_id),
                    )
            # v1.10.31 / v1.11.62 / v1.11.78 / v1.11.85: re-stat the
            # sidecar at every Plex folder that pointed at this theme.
            # The sidecar still exists (we deleted only the canonical),
            # so local_theme_file should be 1 and the row should render
            # as M immediately. folder_has_theme_sidecar handles
            # host→container path translation (Unraid /mnt/user/data
            # → /data) and matches any theme.<audio-ext>.
            # v1.11.85: pi_rows_to_restat was captured BEFORE the
            # DELETE chain ran. Pre-fix this block re-queried via
            # `themes WHERE media_type=? AND tmdb_id=?` after the
            # delete; for the orphan branch (upstream_source=
            # 'plex_orphan' — i.e. adopted manual sidecars) the themes
            # row had already been cascade-removed, so the lookup
            # returned no theme_id_pk and the loop quietly skipped.
            # Result: pi.local_theme_file kept its pre-unmanage value
            # (often 0, because plex_enum hadn't re-stat'd post-adopt)
            # and the row dropped to '—' until the next REFRESH FROM
            # PLEX corrected it.
            # v1.24.13: FS scan precomputed above (off-loop, pre-txn) into
            # _restat_present — the loop now only does the cheap UPDATEs so the
            # write lock isn't held across /data directory walks.
            for pi_row in pi_rows_to_restat:
                conn.execute(
                    "UPDATE plex_items SET local_theme_file = ? "
                    "WHERE rating_key = ?",
                    (1 if _restat_present.get(pi_row["rating_key"]) else 0,
                     pi_row["rating_key"]),
                )
            # v1.11.47: dropped the post-unmanage _enqueue_section_refresh_for_item
            # call. The optimistic re-stat above already updates
            # plex_items.local_theme_file correctly per (folder, media_type),
            # so the confirmatory plex_enum was scanning all 10K+ items in
            # the section just to re-affirm one row. Net gain: one less
            # full-section enum per unmanage; pi.local_theme_file is
            # already truthful before this block exits.

        with get_conn(db) as conn:
            _record_audit(
                conn, actor=request.state.principal.username, action="unmanage",
                media_type=media_type, tmdb_id=tmdb_id,
                section_id=section_id,
                details={"orphan": is_orphan},
            )
        log_event(db, level="INFO", component="api",
                  media_type=media_type, tmdb_id=tmdb_id,
                  section_id=section_id,
                  message=f"Unmanage theme '{theme['title']}' "
                          f"by {request.state.principal.username}",
                  detail={"orphan": is_orphan})
        # v1.17.4: theme_deleted notification (per-row, OFF by default).
        # Fires on UNMANAGE — the most common "user-initiated theme
        # removal" path. Per-row, no dedupe (opt-in is the dedupe).
        # v1.17.12: rich body via notify_content. Drops the internal-
        # mechanics tail ("hardlink placements survive at Plex's
        # copy") — that's plumbing detail no operator needs in a
        # notification.
        # v1.17.16: uses the pre-op _notify_ctx captured before the
        # transaction. Post-op enrichment fails on orphan-drop
        # paths because the themes row is gone.
        try:
            from ..core import notify as _notify
            _notify.dispatch(
                db, settings.cfg.notifications,
                event_kind="theme_deleted",
                title=_nc.format_theme_deleted_title(
                    _notify_ctx, action="unmanaged"),
                body=_nc.format_theme_deleted_body(
                    _notify_ctx, action="unmanaged",
                    actor=request.state.principal.username,
                ),
                body_format="markdown",
                # v1.23.75: FB-sourced themes attach their thumb (v1.22.94).
                attach_url=_nc.attachment_thumb_url(_notify_ctx),
            )
        except Exception as e:
            log.debug("notify dispatch (theme_deleted/unmanage) "
                      "suppressed: %s", e)
        return {"ok": True, "title": theme["title"], "orphan": is_orphan}

    @app.post("/api/items/{media_type}/{tmdb_id}/forget")
    async def api_forget_item(
        request: Request, media_type: MediaType, tmdb_id: int,
        # v1.12.77: optional section_id scopes PURGE to one section.
        # Without it, every section that owns the title gets purged
        # at once (legacy fan-out). Mirrors the v1.12.46/.47/.73
        # scoping for ACCEPT UPDATE / REVERT / RE-DOWNLOAD /
        # UNMANAGE — per-edition theming requires this so PURGE
        # on the 4K row doesn't yank the standard edition's
        # theme too.
        section_id: str | None = Query(None),
        # v1.21.83: rating_key scopes PURGE to ONE edition. All editions of a
        # title can share a section (the user's 3 LotR editions in /movies), so
        # section scope alone destroys siblings. Resolve the edition from the
        # clicked row's folder and narrow every destructive query to it.
        rating_key: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        """PURGE: full destruction of motif's theme presence for an item.

        Deletes BOTH the canonical at /themes/<media>/<Title (Year)>/theme.mp3
        AND the placement file(s) at every Plex media folder. Drops
        local_files + placements rows. For plex_orphan rows, also drops
        the themes row (FK CASCADE clears children).

        After PURGE the row's source flips to '—' (no theme anywhere).
        - If ThemerrDB still has the title, DOWNLOAD becomes available
          via the SOURCE menu.
        - If the row was user-provided (URL / upload / adopt), the file
          is entirely gone — the user must SET URL / UPLOAD MP3 / drop
          a sidecar back at the Plex folder before ADOPT becomes
          available.

        v1.12.77: when section_id is provided the action targets just
        that section. Sibling sections' files + tracking survive.
        Per-section override drops, themes-row drop (orphan-only),
        and tracking-metadata drop only fire when this is the LAST
        section for the title.

        v1.10.38: reverted v1.10.27's source_kind=URL/upload/adopt
        preservation. Per user feedback, PURGE should always be the
        full-destruction action; UNMANAGE is the keep-the-file action.
        """
        _require_admin(request)
        # v1.17.16: pre-op enrichment capture. FORGET drops the
        # orphan themes row when this is the last managed section,
        # so post-op enrich_item finds nothing and falls back to
        # "movie/-26" in the notification — the user's screenshot.
        from ..core import notify_content as _nc
        _notify_ctx = _nc.enrich_item(
            db, media_type=media_type, tmdb_id=tmdb_id,
            section_id=section_id,
        )
        with get_conn(db) as conn:
            theme = conn.execute(
                "SELECT upstream_source, title FROM themes "
                "WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            if theme is None:
                raise HTTPException(status_code=404, detail="theme not found")
            # v1.21.83: resolve the clicked edition once; _ed_sql/_ed_args
            # narrow every destructive query below to it (empty when no
            # rating_key -> legacy whole-section behavior preserved).
            _forget_edition = (edition_key_for_rating_key(conn, rating_key)
                               if rating_key else "")
            _ed_sql = " AND edition_key = ?" if rating_key else ""
            _ed_args = (_forget_edition,) if rating_key else ()
            # v1.12.77: scope placements + locals_rows to the
            # requested section when one was provided.
            # v1.18.60: also read placement_kind + section_id so the
            # Plex API teardown below can fire for plex_upload rows.
            # Pre-fix PURGE on a plex_upload row dropped the
            # placements DB row + iterated `Path(media_folder)/
            # 'theme.mp3'` (which resolves to `theme.mp3` in cwd
            # for the empty-media_folder sentinel) — neither
            # touched Plex. Result: Plex kept serving motif's
            # API-uploaded theme.
            # v1.23.65 (audit #9): edition_key in the SELECT so the shared
            # teardown helper can resolve each plex_upload placement's rk by its
            # OWN edition (a sibling edition in the same section has a different
            # rk — tearing down the wrong one clears Plex's selection for an
            # edition the user didn't touch).
            if section_id:
                placements = conn.execute(
                    "SELECT media_folder, placement_kind, section_id, edition_key "
                    "FROM placements "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?"
                    + _ed_sql,
                    (media_type, tmdb_id, section_id, *_ed_args),
                ).fetchall()
            else:
                placements = conn.execute(
                    "SELECT media_folder, placement_kind, section_id, edition_key "
                    "FROM placements "
                    "WHERE media_type = ? AND tmdb_id = ?"
                    + _ed_sql,
                    (media_type, tmdb_id, *_ed_args),
                ).fetchall()
            if section_id:
                locals_rows = conn.execute(
                    "SELECT section_id, file_path, file_sha256, source_kind, "
                    "       source_video_id "
                    "FROM local_files "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?"
                    + _ed_sql,
                    (media_type, tmdb_id, section_id, *_ed_args),
                ).fetchall()
            else:
                locals_rows = conn.execute(
                    "SELECT section_id, file_path, file_sha256, source_kind, "
                    "       source_video_id "
                    "FROM local_files "
                    "WHERE media_type = ? AND tmdb_id = ?"
                    + _ed_sql,
                    (media_type, tmdb_id, *_ed_args),
                ).fetchall()
            # v1.12.1: collect every plex_items.rating_key pointing at
            # this theme BEFORE the delete cascade fires. The post-
            # delete flag clear at the bottom of this handler clears
            # by rating_key — that's the only stable identifier that
            # survives the delete and reliably covers all three
            # 'how the row reaches this theme' paths:
            #   1. pi.theme_id stamp (set by adopt/SET URL/UPLOAD MP3
            #      via v1.11.43 / v1.11.64; ON DELETE SET NULL would
            #      strip this once we drop the themes row, so we
            #      memo-ize before delete)
            #   2. pi.folder_path matches a placement we're about to
            #      unlink
            #   3. (pi.guid_tmdb, media_type) matches the theme's id
            #      (the only path that worked in v1.11.60 — broken
            #      for synthetic-negative orphan tmdb_ids)
            # Pre-fix: PURGE on an upload/URL/adopt row left
            # pi.local_theme_file=1 forever because the orphan's
            # synthetic tmdb_id never matched pi.guid_tmdb (which
            # holds Plex's real id), so the row kept rendering as
            # L (or M pre-v1.12.0) with ADOPT shown — confusing
            # since the user had just said 'destroy this'.
            theme_id_pk_for_clear = conn.execute(
                "SELECT id FROM themes WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            theme_id_pk_for_clear = (
                theme_id_pk_for_clear["id"] if theme_id_pk_for_clear else None
            )
            # v0.51.48: else media_type (was "movie") so PURGE (forget) on a
            # themed collection clears its plex_items rows (media_type=
            # 'collection'), not a phantom 'movie' lookup that matches nothing.
            plex_mt = "show" if media_type == "tv" else media_type
            placement_folders = [pr["media_folder"] for pr in placements]
            rk_clear: set[str] = set()
            # v1.12.77: when section_id is provided, scope the
            # rating_key collection to that section so plex_items
            # in sibling sections keep their local_theme_file +
            # has_theme flags. Otherwise the section-scoped PURGE
            # would delete the 4K placement file but ALSO clear
            # the standard section's plex_items has_theme flag,
            # which would silently flip the standard row to '-'
            # at the next render.
            # v1.21.83: edition-narrow the rating_key collection too, so the
            # plex_items has_theme/local_theme_file flag-clear below only
            # touches THIS edition's row (a sibling edition keeps its flags +
            # keeps rendering as themed). plex_items.edition_key exists (B3).
            section_filter_sql = (
                "AND section_id = ?" if section_id else ""
            ) + _ed_sql
            section_filter_args = (
                (section_id,) if section_id else ()
            ) + _ed_args
            # v1.13.21: separately track rks discovered via the
            # placement-folder match (path 2). Those are rows where
            # motif owned a sidecar that we just unlinked, so any
            # post-PURGE HEAD probe against /library/metadata/{rk}/
            # theme is asking Plex about a file we deleted seconds
            # ago — Plex's cache routinely answers 200 against that
            # for several seconds, falsely "verifying" a phantom P
            # claim. The inline-verify loop below skips these rks.
            # Multi-edition / multi-section purges where the same
            # title also has a Plex-served theme on a sibling
            # section are unaffected: that sibling's rk lives in a
            # different rating_key, lands via path 1 or 3 alone, and
            # remains eligible for verification.
            rk_from_placement: set[str] = set()
            # Path 1: theme_id stamp
            if theme_id_pk_for_clear is not None:
                for r in conn.execute(
                    f"SELECT rating_key FROM plex_items "
                    f"WHERE theme_id = ? {section_filter_sql}",
                    (theme_id_pk_for_clear, *section_filter_args),
                ).fetchall():
                    rk_clear.add(r["rating_key"])
            # Path 2: placement folder_path match
            if placement_folders:
                qmarks = ",".join("?" for _ in placement_folders)
                for r in conn.execute(
                    f"SELECT rating_key FROM plex_items "
                    f"WHERE folder_path IN ({qmarks}) AND media_type = ? "
                    f"{section_filter_sql}",
                    (*placement_folders, plex_mt, *section_filter_args),
                ).fetchall():
                    rk_clear.add(r["rating_key"])
                    rk_from_placement.add(r["rating_key"])
            # Path 3: real-tmdb match (covers the non-orphan case
            # where motif never had to allocate a synthetic id)
            for r in conn.execute(
                f"SELECT rating_key FROM plex_items "
                f"WHERE guid_tmdb = ? AND media_type = ? "
                f"{section_filter_sql}",
                (tmdb_id, plex_mt, *section_filter_args),
            ).fetchall():
                rk_clear.add(r["rating_key"])
            # v1.20.67: PU rks for the phantom-P guard. A plex_upload
            # placement (media_folder='') can't match Path 2's
            # `folder_path IN (placement_folders)` (its folder_path is a
            # real path, the sentinel is ''), so its rk never enters
            # rk_from_placement → the inline-verify HEAD probe hits Plex's
            # stale-200 cache → phantom P after a PURGE that destroyed
            # everything. Resolve the PU rks (by the plex_upload
            # placements' sections) so they're zeroed directly + skipped
            # in the verify loop. Pessimistic '-' matches PURGE's destroy
            # intent; if Plex still serves its OWN theme, the next
            # plex_enum re-detects it and flips the row back to P.
            plex_upload_rks: set[str] = set()
            pu_sections = [
                pr["section_id"] for pr in placements
                if (pr["placement_kind"] or "") == "plex_upload"
            ]
            # v1.22.75: + _ed_sql — the v1.21.83 narrowing covered the rk-
            # collection paths but missed this v1.20.67 block, so an
            # edition-scoped PURGE force-appended SIBLING editions' rks to
            # rk_zero (has_theme/verified falsely zeroed, verify-skipped).
            for pu_sec in pu_sections:
                if theme_id_pk_for_clear is not None:
                    for r in conn.execute(
                        "SELECT rating_key FROM plex_items "
                        "WHERE theme_id = ? AND section_id = ?" + _ed_sql,
                        (theme_id_pk_for_clear, pu_sec, *_ed_args),
                    ).fetchall():
                        plex_upload_rks.add(r["rating_key"])
                for r in conn.execute(
                    "SELECT rating_key FROM plex_items "
                    "WHERE guid_tmdb = ? AND media_type = ? AND section_id = ?"
                    + _ed_sql,
                    (tmdb_id, plex_mt, pu_sec, *_ed_args),
                ).fetchall():
                    plex_upload_rks.add(r["rating_key"])
            # v1.10.57: snapshot content-hash → URL mapping per section
            # so a future ADOPT (any section) can restore the URL.
            # v1.14.35: section-scoped override fetch — same fix
            # shape as api_unmanage_item. user_overrides went per-
            # section in v1.12.72; pre-fix the title-global SELECT
            # picked an arbitrary section's URL on multi-section
            # rows with separate per-edition overrides. Scope to
            # the row's section first; fall back to the title-
            # global '' row when no per-section override exists.
            if locals_rows:
                if section_id:
                    override_row = conn.execute(
                        "SELECT youtube_url FROM user_overrides "
                        "WHERE media_type = ? AND tmdb_id = ? "
                        "  AND section_id = ?",
                        (media_type, tmdb_id, section_id),
                    ).fetchone()
                    if override_row is None:
                        override_row = conn.execute(
                            "SELECT youtube_url FROM user_overrides "
                            "WHERE media_type = ? AND tmdb_id = ? "
                            "  AND section_id = ''",
                            (media_type, tmdb_id),
                        ).fetchone()
                else:
                    override_row = conn.execute(
                        "SELECT youtube_url FROM user_overrides "
                        "WHERE media_type = ? AND tmdb_id = ?",
                        (media_type, tmdb_id),
                    ).fetchone()
                theme_yt = conn.execute(
                    "SELECT youtube_url FROM themes "
                    "WHERE media_type = ? AND tmdb_id = ?",
                    (media_type, tmdb_id),
                ).fetchone()
                saved_youtube_url = (
                    (override_row and override_row["youtube_url"])
                    or (theme_yt and theme_yt["youtube_url"])
                )
                for lr in locals_rows:
                    if lr["file_sha256"]:
                        conn.execute(
                            """INSERT INTO local_files_history
                                 (file_sha256, media_type, tmdb_id, source_kind,
                                  source_video_id, youtube_url, saved_at, saved_reason)
                               VALUES (?, ?, ?, ?, ?, ?, ?, 'forget')""",
                            (lr["file_sha256"], media_type, tmdb_id,
                             lr["source_kind"], lr["source_video_id"],
                             saved_youtube_url, now_iso()),
                        )

        # v1.18.60: Plex API teardown for any plex_upload rows.
        # The sidecar unlink loop below silently no-ops for those
        # rows (Path('') / 'theme.mp3' isn't a real file) so
        # without this call PURGE would drop motif's DB tracking
        # but leave Plex's metadata-stored theme serving. Mirrors
        # the v1.18.36 SWITCH api→file teardown via the shared
        # _teardown_plex_api_artifacts_for_placements helper.
        # v1.22.42 (audit): the teardown does N plex.delete_theme round-trips
        # (sync). Called directly on the event loop it froze every concurrent
        # request during a PURGE. Off-load — the helper owns its own conn so it's
        # fully self-contained off-thread.
        api_deleted = await run_in_threadpool(
            _teardown_plex_api_artifacts_for_placements,
            db, settings, media_type, tmdb_id, placements,
        )
        # v1.22.75 (fake-success class): the count was computed then dropped
        # — Plex unreachable meant 0 deletions behind ok:true with only a
        # docker-log WARN. Surface the 0-for-plex_upload case loudly.
        _pu_total = sum(1 for p in placements
                        if (p["placement_kind"] or "") == "plex_upload")
        if _pu_total and api_deleted == 0:
            log_event(db, level="WARNING", component="api",
                      media_type=media_type, tmdb_id=tmdb_id,
                      message=(f"PURGE: Plex API teardown removed 0 artifacts"
                               f" for {_pu_total} plex_upload placement(s) — "
                               f"Plex may still serve the uploaded theme"),
                      detail={"plex_upload_placements": _pu_total})
        # Unlink every placement file across all sections.
        # plex_upload placements skip the unlink (media_folder=''
        # means Path('') / 'theme.mp3' = relative theme.mp3,
        # .is_file() returns False) — the v1.18.60 API teardown
        # above is what cleans those rows up.
        unlinked = 0
        affected_folders: list[str] = []
        themes_dir = settings.themes_dir

        # v0.51.13 (audit #12, class 12): offload BOTH unlink loops — they hit
        # the /data + themes mounts; a spun-down disk blocks each syscall for
        # seconds, serially across N placements, freezing the event loop for
        # every concurrent request (invisible to the v1.22.58 AST lint). Runs
        # BEFORE the tracking txn below, so no transaction spans the await.
        def _unlink_files() -> int:
            n = 0
            for pr in placements:
                if (pr["placement_kind"] or "") == "plex_upload":
                    # No sidecar to unlink — the file lives in Plex's
                    # metadata bundle; v1.18.60 teardown above handled it.
                    continue
                try:
                    p = Path(pr["media_folder"]) / "theme.mp3"
                    if p.is_file():
                        p.unlink()
                        n += 1
                    affected_folders.append(pr["media_folder"])
                except OSError as e:
                    log.warning("forget: could not unlink %s: %s",
                                pr["media_folder"], e)
            if themes_dir:
                for lr in locals_rows:
                    try:
                        p = themes_dir / lr["file_path"]
                        if p.is_file():
                            p.unlink()
                        # v1.14.57: see api_unmanage_item — same errno-
                        # aware logging upgrade so persistent permission
                        # / unexpected FS errors surface instead of being
                        # silently masked alongside ENOTEMPTY.
                        try:
                            parent = p.parent
                            if parent.is_dir() and not any(parent.iterdir()):
                                parent.rmdir()
                        except OSError as rmd_err:
                            import errno as _errno
                            if rmd_err.errno not in (_errno.ENOTEMPTY,
                                                      _errno.ENOENT):
                                log.warning(
                                    "forget: parent rmdir %s failed "
                                    "unexpectedly: %s", p.parent, rmd_err)
                    except OSError as e:
                        log.warning("forget: could not unlink canonical %s: %s",
                                    lr["file_path"], e)
            return n
        unlinked = await run_in_threadpool(_unlink_files)

        is_orphan = theme["upstream_source"] == "plex_orphan"
        with get_conn(db) as conn, transaction(conn):
            if section_id:
                # v1.12.77: scope DELETE to the row's section.
                # Sibling sections' placements + local_files
                # survive. Per-section override drops too. The
                # tracking-metadata drop and orphan-themes delete
                # only fire when this is the LAST section for the
                # title (no other local_files remaining), mirroring
                # the v1.12.73 UNMANAGE last-section logic.
                # v1.12.79: snapshot the URL ABOUT to be dropped so
                # the post-PURGE RESTORE button has something to
                # bring back. Reads the section's override (or
                # falls back to '' / themes); writes title-global
                # previous_youtube_url + previous_youtube_kind.
                # Last-section path below also keeps this snapshot
                # intact — _drop_motif_tracking deliberately
                # preserves previous_* per v1.12.64.
                # v1.12.102: on_purge=True so any prior previous_url
                # moves to the hidden slot — RESTORE brings the
                # just-purged URL back, REVERT after RESTORE walks
                # the chain to whatever was previous before this.
                _capture_previous_url(conn, media_type, tmdb_id,
                                      section_id=section_id,
                                      on_purge=True)
                # v1.18.73 (HIGH-B audit): cancel in-flight jobs
                # for this row before the destructive sweeps —
                # see api_unplace_item parallel block for full
                # rationale.
                _cancel_jobs_for_row(
                    conn, media_type=media_type, tmdb_id=tmdb_id,
                    section_id=section_id,
                )
                # v1.21.83: edition-scoped deletes — a sibling edition's
                # placement / local_file / override rows survive PURGE on
                # this one. last_section below still counts title-global
                # local_files so tracking only drops on the FINAL edition.
                conn.execute(
                    "DELETE FROM placements "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?"
                    + _ed_sql,
                    (media_type, tmdb_id, section_id, *_ed_args),
                )
                conn.execute(
                    "DELETE FROM local_files "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?"
                    + _ed_sql,
                    (media_type, tmdb_id, section_id, *_ed_args),
                )
                conn.execute(
                    "DELETE FROM user_overrides "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?"
                    + _ed_sql,
                    (media_type, tmdb_id, section_id, *_ed_args),
                )
                remaining = conn.execute(
                    "SELECT COUNT(*) AS n FROM local_files "
                    "WHERE media_type = ? AND tmdb_id = ?",
                    (media_type, tmdb_id),
                ).fetchone()
                last_section = remaining and remaining["n"] == 0
                if last_section:
                    # v1.22.23: spare sibling editions' decisions (see helper).
                    _drop_motif_tracking(
                        conn, media_type, tmdb_id,
                        acted_edition=_forget_edition if rating_key else None)
                    if is_orphan:
                        # v1.17.24: zombie themes instead of
                        # DROP — see api_unmanage_item parallel
                        # branch for full rationale. the user's
                        # screenshot showed PURGE on a U row
                        # captured the URL but RESTORE never
                        # surfaced because the FK ON DELETE SET
                        # NULL broke the previous_urls JOIN.
                        conn.execute(
                            "UPDATE themes "
                            "SET youtube_url = NULL, "
                            "    youtube_video_id = NULL "
                            "WHERE media_type = ? AND tmdb_id = ?",
                            (media_type, tmdb_id),
                        )
            else:
                # Legacy global PURGE path — destroys every section.
                # v1.22.76 (v1.18.73 class gap): the section branch above
                # cancels in-flight jobs; this global branch didn't — a
                # completing worker re-INSERTed tracking after the sweep.
                _cancel_jobs_for_row(
                    conn, media_type=media_type, tmdb_id=tmdb_id,
                )
                # v1.12.57: PURGE = full destruction. Drop motif's
                # tracking metadata (override URL, pending_updates,
                # previous-URL snapshot) so the row is a true clean
                # slate. Pre-fix a "CLEAR URL → PURGE" sequence left
                # the user_overrides row alive — the row showed src='-'
                # but the next download silently used the stale
                # override URL, classifying the row as U again.
                _drop_motif_tracking(conn, media_type, tmdb_id)
                if is_orphan:
                    # v1.17.24: zombie themes (see last-section
                    # branch above for full rationale).
                    conn.execute(
                        "UPDATE themes "
                        "SET youtube_url = NULL, "
                        "    youtube_video_id = NULL "
                        "WHERE media_type = ? AND tmdb_id = ?",
                        (media_type, tmdb_id),
                    )
                else:
                    conn.execute(
                        "DELETE FROM placements WHERE media_type = ? AND tmdb_id = ?",
                        (media_type, tmdb_id),
                    )
                    conn.execute(
                        "DELETE FROM local_files WHERE media_type = ? AND tmdb_id = ?",
                        (media_type, tmdb_id),
                    )
            # v1.12.1: clear pi.local_theme_file + has_theme by the
            # rating_key set we memo-ized BEFORE delete (see the
            # theme_id_pk_for_clear / rk_clear collection above).
            # Pre-fix the WHERE guid_tmdb=? clause silently missed
            # every orphan-backed row because the orphan's synthetic
            # negative tmdb_id never matches pi.guid_tmdb (which
            # holds Plex's real id, or NULL).
            if rk_clear:
                qmarks = ",".join("?" for _ in rk_clear)
                # v1.13.4: snapshot pre-purge has_theme so the inline
                # verify below can distinguish "Plex was the original
                # source (themerr-plex embed / Plex Pass cloud)" from
                # "motif was the only source". For motif-only sources,
                # skip inline verify entirely — Plex's metadata cache
                # can return 200 to /library/metadata/{rk}/theme for
                # several seconds after motif deleted the sidecar,
                # falsely confirming a phantom theme that the user-
                # facing XML already correctly shows as gone. Result:
                # SRC reverts to 'P' incorrectly, and the user sees a
                # ghost theme until the next plex_enum reconciles.
                # v1.13.36: ALSO snapshot the +P composite state
                # (has_theme=1 AND local_theme_file=0). Rows in that
                # state have a known-separate Plex theme (cloud / embed)
                # alongside motif's placement; PURGE'ing them shouldn't
                # bounce SRC to '-' — Plex's separate theme survives
                # the file deletion and SRC should snap to P right
                # away. We split the UPDATE so those rks keep
                # has_theme=1 + verified_ok=NULL (optimistic), while
                # the rest of rk_clear goes to the pessimistic stamp
                # below. plex_enum reconciles either way on its next
                # pass.
                pre_state: dict[str, dict] = {
                    r["rating_key"]: {
                        "has_theme": int(r["has_theme"] or 0),
                        "local_theme_file": int(r["local_theme_file"] or 0),
                        "verified_ok": r["plex_theme_verified_ok"],
                        "plex_independent_theme": r["plex_independent_theme"],
                    }
                    for r in conn.execute(
                        f"SELECT rating_key, has_theme, local_theme_file, "
                        f"       plex_theme_verified_ok, "
                        f"       plex_independent_theme "
                        f"FROM plex_items WHERE rating_key IN ({qmarks})",
                        tuple(rk_clear),
                    ).fetchall()
                }
                pre_has_theme = {
                    rk: s["has_theme"] for rk, s in pre_state.items()
                }
                # v1.13.36: split rk_clear into "had Plex's own theme
                # (cloud / embed) alongside motif" vs "motif was the
                # sole source". v1.13.38: the persisted
                # plex_independent_theme flag is now the authoritative
                # signal — when set to 1 motif KNOWS Plex serves a
                # separate theme (observed pre-place by plex_enum or
                # confirmed by a previous HEAD probe). Fall back to
                # the v1.13.36 heuristic (has_theme=1 AND
                # local_theme_file=0) when the flag is NULL/unknown
                # so older rows still get the optimistic-keep before
                # plex_enum runs once.
                def _had_plex_independent(rk: str) -> bool:
                    s = pre_state.get(rk, {})
                    if s.get("plex_independent_theme") == 1:
                        return True
                    if s.get("plex_independent_theme") == 0:
                        return False
                    # Unknown — heuristic fallback.
                    return (s.get("has_theme") == 1
                            and s.get("local_theme_file") == 0)
                # v1.14.27: only flag-flip rks where motif actually
                # unlinked a file (= rks in rk_from_placement). Pre-fix
                # PURGE on an M row (motif doesn't own the sidecar, no
                # placement record) ran with placements=[] so no file
                # got deleted, but rk_clear still picked up the rk via
                # path 1 (theme_id) or path 3 (guid_tmdb). The blanket
                # UPDATE then set local_theme_file=0 even though the
                # file at the Plex folder was still there — STATE
                # MISMATCH (the chip flipped M→P while the file was
                # untouched). the user's repro: PURGE on M row, chip
                # flips P, but the theme.mp3 is still on disk.
                # Now: rks reached only via theme_id / guid_tmdb (no
                # placement we deleted) get NO flag flip — their
                # local_theme_file + has_theme stay as-observed.
                _rks_we_actually_touched = rk_clear & rk_from_placement
                rk_keep_p = [
                    rk for rk in _rks_we_actually_touched
                    if _had_plex_independent(rk)
                ]
                rk_zero = [
                    rk for rk in _rks_we_actually_touched
                    if rk not in rk_keep_p
                ]
                # v1.20.67: PU rks are never in _rks_we_actually_touched
                # (they can't enter rk_from_placement), so the keep_p/zero
                # split misses them. Force them to zero so the transaction
                # UPDATE clears has_theme=0/verified_ok=0 even when Plex is
                # disabled (no inline-verify) — PURGE means destroy. They
                # are also skipped in the verify loop so a stale-200 probe
                # can't re-raise them. rk_keep_p is deliberately untouched:
                # its has_theme=1+local_theme_file=0 heuristic would
                # mis-keep a PU row as +P.
                for _pu_rk in plex_upload_rks:
                    if _pu_rk not in rk_zero:
                        rk_zero.append(_pu_rk)
                if rk_keep_p:
                    qm_keep = ",".join("?" for _ in rk_keep_p)
                    # Sidecar gone (we just deleted it) but Plex's
                    # separate theme stays. has_theme stays 1;
                    # verified_ok back to NULL (untested) — SRC SQL's
                    # COALESCE renders P. plex_enum's HEAD verify
                    # confirms within seconds.
                    conn.execute(
                        f"UPDATE plex_items SET local_theme_file = 0, "
                        f"                      plex_theme_verified_ok = NULL "
                        f"WHERE rating_key IN ({qm_keep})",
                        tuple(rk_keep_p),
                    )
                if rk_zero:
                    qm_zero = ",".join("?" for _ in rk_zero)
                    conn.execute(
                        f"UPDATE plex_items SET local_theme_file = 0, "
                        f"                      has_theme = 0, "
                        # v1.13.4: also stamp verified_ok=0 so the optimistic
                        # COALESCE in _SRC_LETTER_SQL (which treats NULL as
                        # "trust the claim") doesn't trip on a stale NULL
                        # in the brief window before inline-verify runs (or
                        # at all when verify is skipped per the snapshot
                        # logic).
                        f"                      plex_theme_verified_ok = 0 "
                        f"WHERE rating_key IN ({qm_zero})",
                        tuple(rk_zero),
                    )
            else:
                pre_has_theme = {}
        # v1.10.28: skip the section enum (it would re-fetch has_theme
        # from Plex's stale cache and bring back a phantom P badge);
        # trigger a per-item refresh instead so Plex updates its cache.
        try:
            # v1.22.69 (audit round 2): off the event loop — the helper
            # opens a PlexClient and fires one refresh round-trip per
            # matching plex_items row (title-wide); the sync call froze
            # every concurrent request while Plex was slow. The helper
            # indirection evaded the v1.22.58 lint (now covered via
            # BLOCKING_FUNCS).
            await run_in_threadpool(
                _trigger_plex_item_refresh, media_type, tmdb_id)
        except Exception as e:
            log.debug("plex item refresh skipped: %s", e)

        # v1.12.114: inline-verify Plex's theme claim for each affected
        # rating_key. Pre-fix the rk_clear UPDATE above set
        # has_theme=0 + local_theme_file=0, so SRC dropped to '-'
        # immediately — accurate when Plex has nothing to fall back
        # on, but WRONG when motif's theme was layered over a
        # pre-existing themerr-plex embed (or Plex Pass cloud TV
        # theme). For those rows the embed survives in Plex's DB
        # independently of motif's sidecar, so SRC should snap back
        # to P the moment motif's file is gone. Inline HEAD probe
        # here lets motif know Plex's current view at the response
        # boundary instead of waiting for the next plex_enum:
        #   - HEAD 200 → Plex still serves a theme (embed/cloud) →
        #     pi.has_theme=1, plex_theme_verified_ok=1 → SRC=P
        #   - HEAD 404 → Plex has nothing → has_theme stays 0,
        #     verified_ok=0 → SRC='-' (correct already)
        #   - transient (None) → leave verified_ok=NULL → optimistic;
        #     v1.12.113's TTL re-verifies later
        if rk_clear and settings.plex_enabled and settings.plex_token:
            # v1.12.116: per-row try/except so a single rating_key's
            # verify failure (network blip, DB lock, transient 5xx)
            # doesn't abort verification for the remaining rks. Also
            # reuses one DB connection across all UPDATEs in the
            # batch instead of opening per-row. Pre-fix the outer
            # try/except caught the first exception and bailed,
            # leaving subsequent rks unverified for a multi-section
            # PURGE.
            try:
                from ..core.plex import PlexClient, PlexConfig
                cfg = PlexConfig(
                    url=settings.plex_url, token=settings.plex_token,
                    movie_section=settings.plex_movie_section,
                    tv_section=settings.plex_tv_section, enabled=True,
                )
                with PlexClient(cfg, plus_mode=settings.plus_equiv_mode) as plex, \
                        get_conn(db) as conn:  # type: ignore[arg-type]
                    for rk in rk_clear:
                        # v1.13.4: only inline-verify rks that had
                        # has_theme=1 BEFORE purge — those are the ones
                        # where Plex might have an independent embed
                        # (themerr-plex / Plex Pass cloud) that should
                        # survive the file deletion. For rks that had
                        # has_theme=0, motif was the sole source; the
                        # post-purge state is definitively '-' and an
                        # inline verify against Plex's cache risks a
                        # false 200. Skip them.
                        if not pre_has_theme.get(rk, 0):
                            continue
                        # v1.13.21: also skip rks where motif had a
                        # placement (path 2 collection). pre_has_theme
                        # alone wasn't enough on edition siblings: 4K
                        # rows that had motif's sidecar showed
                        # has_theme=1 (Plex saw the file) AND landed
                        # in rk_from_placement, so the v1.13.4 gate let
                        # them through and the HEAD probe restored
                        # has_theme=1 against Plex's stale cache.
                        # Tracking placement provenance separately
                        # makes the rule explicit: if motif owned the
                        # file we just deleted, don't trust Plex's
                        # next-second view of /theme — wait for the
                        # background plex_enum to reconcile.
                        # v1.20.67: PU rks were already zeroed in the
                        # transaction above; skip the stale-200 HEAD probe
                        # so it can't re-raise a phantom P. (A PU rk can't
                        # be in rk_from_placement — that's the root bug.)
                        if rk in plex_upload_rks:
                            continue
                        if rk in rk_from_placement:
                            continue
                        try:
                            # v1.22.58: off the event loop (missed v1.21.20-
                            # class block — same inline-verify shape as the
                            # api_unplace_item fix this tag).
                            result = await run_in_threadpool(
                                plex.verify_theme_claim, rk)
                            if result is None:
                                continue
                            # v1.13.38: also update the persisted
                            # +P composite signal. After PURGE the
                            # sidecar is gone, so HEAD's verdict is
                            # the definitive answer for "Plex serves
                            # an independent theme" — write it to
                            # plex_independent_theme so the next
                            # render reads the truth instead of
                            # a stale observation.
                            conn.execute(
                                "UPDATE plex_items SET "
                                "  has_theme = ?, "
                                "  plex_theme_verified_at = ?, "
                                "  plex_theme_verified_ok = ?, "
                                "  plex_independent_theme = ? "
                                "WHERE rating_key = ?",
                                (1 if result else 0, now_iso(),
                                 1 if result else 0,
                                 1 if result else 0, rk),
                            )
                        except Exception as e:
                            # v1.13.50: bumped from debug to warning
                            # so production logs (default INFO) catch
                            # network blips during the verify. The
                            # continue still preserves best-effort
                            # behavior — one rk failing doesn't kill
                            # the loop.
                            log.warning(
                                "PURGE inline verify rk=%s skipped: %s",
                                rk, e)
                            continue
            except Exception as e:
                # v1.13.50: log.exception so the outer skip carries
                # a stack trace — the inner try/except handles the
                # common per-rk case; this branch only triggers on
                # something genuinely unexpected (e.g. PlexClient
                # init failure), worth a full trace in the log.
                log.exception("PURGE inline verify skipped: %s", e)

        with get_conn(db) as conn:
            _record_audit(
                conn, actor=request.state.user, action="purge",
                media_type=media_type, tmdb_id=tmdb_id,
                section_id=section_id,
                details={"orphan_dropped": is_orphan,
                         "placements_unlinked": unlinked,
                         "placements_total": len(placements),
                         # v1.22.75: was computed then dropped (fake-success)
                         "plex_api_deleted": api_deleted},
            )
        log_event(db, level="INFO", component="api",
                  media_type=media_type, tmdb_id=tmdb_id,
                  section_id=section_id,
                  message=f"Forget by {request.state.user}",
                  detail={"title": theme["title"],
                          "orphan_dropped": is_orphan,
                          "placements_unlinked": unlinked,
                          "placements_total": len(placements),
                          "plex_api_deleted": api_deleted})
        # v1.17.4: theme_deleted notification (per-row, OFF by default).
        # FORGET is more destructive than UNMANAGE — it unlinks every
        # placement file from Plex's folders + drops the orphan theme
        # row. Same event kind as UNMANAGE since the user-visible
        # effect (Plex stops serving the theme) is the same.
        # v1.17.12: rich body via notify_content.
        # v1.17.16: uses pre-op _notify_ctx (orphan-row drop nukes
        # post-op enrichment — the user's "movie/-26" screenshot).
        try:
            from ..core import notify as _notify
            # v1.17.24: orphan rows are now zombie'd (themes row
            # preserved with NULL URLs) instead of dropped — keeps
            # the previous_urls JOIN key alive so RESTORE surfaces.
            # Notification copy reflects the new reality: "RESTORE
            # available" tells the user the recovery path exists.
            # v1.23.8: placement-kind-aware note. The old copy only
            # surfaced the SIDECAR unlink counter, so an upload-
            # placed row always read "0 placement(s) unlinked" even
            # though its theme WAS removed from Plex via the API
            # (the user: "wondering what the 0 placement(s) unlinked
            # from Plex means" — his row was plex_upload, torn down
            # by the v1.18.60 API path, counted in api_deleted).
            _note_parts = []
            if api_deleted:
                _note_parts.append(
                    f"{api_deleted} Plex upload(s) removed")
            if unlinked:
                _note_parts.append(
                    f"{unlinked} placement(s) unlinked from Plex")
            if not _note_parts:
                _note_parts.append("no placements to remove")
            extra = (
                " · ".join(_note_parts) +
                (" · RESTORE available" if is_orphan
                 else " · TDB tracking preserved")
            )
            _notify.dispatch(
                db, settings.cfg.notifications,
                event_kind="theme_deleted",
                title=_nc.format_theme_deleted_title(
                    _notify_ctx, action="forgotten"),
                body=_nc.format_theme_deleted_body(
                    _notify_ctx, action="forgotten",
                    actor=request.state.user,
                    extra_note=extra,
                ),
                body_format="markdown",
                # v1.23.75: FB-sourced themes attach their thumb (v1.22.94).
                attach_url=_nc.attachment_thumb_url(_notify_ctx),
            )
        except Exception as e:
            log.debug("notify dispatch (theme_deleted/forget) "
                      "suppressed: %s", e)
        return {"ok": True, "orphan_dropped": is_orphan,
                "placements_unlinked": unlinked,
                # v1.22.75: Plex API teardown count (0 + plex_upload rows
                # present = Plex may still serve the theme; WARNING logged).
                "plex_api_deleted": api_deleted}

    @app.delete("/api/items/{media_type}/{tmdb_id}", status_code=204)
    async def api_delete_item(
        request: Request, media_type: MediaType, tmdb_id: int,
        db: Path = Depends(get_db_path),
    ):
        """Delete a theme row + all FK'd children + on-disk files. Restricted
        to plex_orphan rows: real ThemerrDB rows would just come back on the
        next sync, so deleting them is a footgun."""
        _require_admin(request)
        # v1.17.16: pre-op enrichment capture. DELETE always drops the
        # themes row + every FK'd child, so post-op enrich_item finds
        # nothing — the user's "movie/-26" screenshot was actually the
        # FORGET path, but DELETE has the same risk.
        from ..core import notify_content as _nc
        _notify_ctx = _nc.enrich_item(
            db, media_type=media_type, tmdb_id=tmdb_id,
        )
        with get_conn(db) as conn:
            theme = conn.execute(
                "SELECT upstream_source, title FROM themes "
                "WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            if theme is None:
                raise HTTPException(status_code=404, detail="theme not found")
            if theme["upstream_source"] != "plex_orphan":
                raise HTTPException(
                    status_code=400,
                    detail="only plex_orphan rows can be deleted; real ThemerrDB rows "
                           "would be re-created on the next sync",
                )
            # Collect files to unlink BEFORE we drop the rows.
            # v1.18.60: also read section_id so the Plex API teardown
            # below can scope its rk lookups per section. Mirrors
            # the v1.18.60 fix in api_forget_item — same gap, same
            # shape.
            # v1.23.65 (audit #9): + edition_key so the helper resolves each
            # plex_upload placement's rk by its own edition (DELETE nukes the
            # whole title, so every edition's placement is here — each must tear
            # down ITS OWN rk, not an arbitrary sibling's).
            placement_rows = conn.execute(
                "SELECT media_folder, placement_kind, section_id, edition_key "
                "FROM placements "
                "WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchall()
            # v1.11.0: per-section local_files — fetch all so we unlink
            # every staging copy. Pre-fix only fetched the first row,
            # leaking on-disk files in sibling sections after FK CASCADE
            # dropped the DB rows.
            local_rows = conn.execute(
                "SELECT file_path FROM local_files "
                "WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchall()

        # v1.18.60: Plex API teardown for plex_upload rows BEFORE
        # the sidecar unlink loop. Same shape as the v1.18.60
        # api_forget_item fix — DELETE on a plex_upload row used
        # to drop the DB tracking but leave Plex's API entry
        # serving the theme.
        # v1.22.42 (audit): off-load the sync per-rk delete_theme teardown so a
        # DELETE doesn't freeze the event loop. Helper owns its own conn.
        api_deleted = await run_in_threadpool(
            _teardown_plex_api_artifacts_for_placements,
            db, settings, media_type, tmdb_id, placement_rows,
        )
        # v1.22.75: surface the 0-for-plex_upload fake-success (see PURGE).
        _pu_total = sum(1 for p in placement_rows
                        if (p["placement_kind"] or "") == "plex_upload")
        if _pu_total and api_deleted == 0:
            log_event(db, level="WARNING", component="api",
                      media_type=media_type, tmdb_id=tmdb_id,
                      message=(f"DELETE: Plex API teardown removed 0 artifacts"
                               f" for {_pu_total} plex_upload placement(s) — "
                               f"Plex may still serve the uploaded theme"),
                      detail={"plex_upload_placements": _pu_total})
        # Unlink placement files (hardlinks have independent inodes; deleting
        # the canonical doesn't remove these). Best-effort; missing files are OK.
        # plex_upload rows skip the unlink — no sidecar to remove,
        # the v1.18.60 teardown above handled them.
        # v0.51.13 (audit #12, class 12): offload BOTH unlink loops — they hit
        # the /data + themes mounts; a spun-down disk blocks each syscall,
        # serially, freezing the event loop (invisible to the v1.22.58 AST
        # lint). Runs BEFORE the cascade txn below, so nothing spans the await.
        themes_dir = settings.themes_dir

        def _unlink_files() -> int:
            n = 0
            for pr in placement_rows:
                if (pr["placement_kind"] or "") == "plex_upload":
                    continue  # no sidecar; v1.18.60 teardown handled it
                try:
                    p = Path(pr["media_folder"]) / "theme.mp3"
                    if p.is_file():
                        p.unlink()
                        n += 1
                except OSError as e:
                    log.warning("Could not unlink placement %s: %s", pr["media_folder"], e)
            # Unlink every per-section canonical.
            if themes_dir:
                for lr in local_rows:
                    try:
                        p = themes_dir / lr["file_path"]
                        if p.is_file():
                            p.unlink()
                        try:
                            parent = p.parent
                            if parent.is_dir() and not any(parent.iterdir()):
                                parent.rmdir()
                        except OSError as e:
                            # v1.22.31 (audit): best-effort empty-dir cleanup — a
                            # leftover empty staging dir is harmless, but log the
                            # swallow so it's auditable (class-9, not bare pass).
                            log.debug("delete: empty-parent rmdir skipped for "
                                      "%s: %s", p.parent, e)
                    except OSError as e:
                        log.warning("Could not unlink canonical %s: %s",
                                    lr["file_path"], e)
            return n
        unlinked = await run_in_threadpool(_unlink_files)

        # Drop the theme row; FK ON DELETE CASCADE handles local_files,
        # placements, pending_updates, user_overrides in one transaction.
        # v1.12.1: collect every plex_items.rating_key pointing at
        # this theme BEFORE the delete cascade fires, then clear the
        # post-delete flags by rating_key. Same reasoning as the
        # forget endpoint fix — guid_tmdb-keyed clears miss
        # synthetic-negative orphan tmdb_ids entirely.
        # v0.51.48: else media_type (was "movie") so DELETE on a themed
        # collection clears its plex_items rows (media_type='collection'),
        # not a phantom 'movie' lookup that matches nothing.
        plex_mt = "show" if media_type == "tv" else media_type
        placement_folders = [pr["media_folder"] for pr in placement_rows]
        rk_clear: set[str] = set()
        with get_conn(db) as conn, transaction(conn):
            theme_id_pk_for_clear = conn.execute(
                "SELECT id FROM themes WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            theme_id_pk_for_clear = (
                theme_id_pk_for_clear["id"] if theme_id_pk_for_clear else None
            )
            if theme_id_pk_for_clear is not None:
                for r in conn.execute(
                    "SELECT rating_key FROM plex_items WHERE theme_id = ?",
                    (theme_id_pk_for_clear,),
                ).fetchall():
                    rk_clear.add(r["rating_key"])
            if placement_folders:
                qmarks = ",".join("?" for _ in placement_folders)
                for r in conn.execute(
                    f"SELECT rating_key FROM plex_items "
                    f"WHERE folder_path IN ({qmarks}) AND media_type = ?",
                    (*placement_folders, plex_mt),
                ).fetchall():
                    rk_clear.add(r["rating_key"])
            for r in conn.execute(
                "SELECT rating_key FROM plex_items "
                "WHERE guid_tmdb = ? AND media_type = ?",
                (tmdb_id, plex_mt),
            ).fetchall():
                rk_clear.add(r["rating_key"])

            # v1.12.57: drop motif's tracking metadata before
            # killing the themes row. FK CASCADE on themes handles
            # placements / local_files / pending_updates, but
            # user_overrides has no FK so without this explicit
            # delete the override survives the orphan-themes
            # destruction and silently re-applies on next adopt.
            _drop_motif_tracking(conn, media_type, tmdb_id)
            # v1.18.73 (HIGH-B audit): cancel in-flight jobs for
            # this row BEFORE the FK-cascade drops the themes row.
            # A place/download/refresh job mid-transaction against
            # the row being deleted would otherwise observe partial
            # destruction (placements gone via cascade, themes
            # gone, local_files gone) and either crash on a NULL
            # column or, worse, re-create the row's tracking via
            # an UPSERT. Same pattern as api_unplace_item and
            # api_forget_item.
            _cancel_jobs_for_row(
                conn, media_type=media_type, tmdb_id=tmdb_id,
                section_id=None,
            )
            conn.execute(
                "DELETE FROM themes WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            )
            if rk_clear:
                qmarks = ",".join("?" for _ in rk_clear)
                conn.execute(
                    f"UPDATE plex_items SET local_theme_file = 0, "
                    f"                      has_theme = 0 "
                    f"WHERE rating_key IN ({qmarks})",
                    tuple(rk_clear),
                )

        log_event(db, level="INFO", component="api",
                  media_type=media_type, tmdb_id=tmdb_id,
                  message=f"Orphan deleted by {request.state.user}",
                  detail={"title": theme["title"],
                          "placements_unlinked": unlinked,
                          "placements_total": len(placement_rows),
                          # v1.22.75: was computed then dropped
                          "plex_api_deleted": api_deleted})
        # v1.17.4: theme_deleted notification (per-row, OFF by default).
        # DELETE is the most destructive path — drops the theme row,
        # all FK'd children, all files. Restricted to plex_orphan
        # rows server-side so it can't be used on real ThemerrDB
        # data; per-row notification still useful for audit-trail.
        # v1.17.12: rich body via notify_content.
        # v1.17.16: uses pre-op _notify_ctx (DELETE drops everything,
        # so post-op enrichment is empty).
        try:
            from ..core import notify as _notify
            extra = (
                f"{unlinked}/{len(placement_rows)} placement(s) "
                f"unlinked · theme row + all children dropped"
            )
            _notify.dispatch(
                db, settings.cfg.notifications,
                event_kind="theme_deleted",
                title=_nc.format_theme_deleted_title(
                    _notify_ctx, action="deleted"),
                body=_nc.format_theme_deleted_body(
                    _notify_ctx, action="deleted",
                    actor=request.state.user,
                    extra_note=extra,
                ),
                body_format="markdown",
                # v1.23.75: FB-sourced themes attach their thumb (v1.22.94).
                attach_url=_nc.attachment_thumb_url(_notify_ctx),
            )
        except Exception as e:
            log.debug("notify dispatch (theme_deleted/delete) "
                      "suppressed: %s", e)
        return Response(status_code=204)

    @app.post("/api/items/{media_type}/{tmdb_id}/clear-url")
    async def api_clear_url_override(
        request: Request, media_type: MediaType, tmdb_id: int,
        section_id: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        """v1.12.37 (revised per user feedback): drop the captured
        PREVIOUS URL on a row so REVERT/RESTORE becomes unavailable.
        The current canonical and user_overrides are untouched — the
        playing theme keeps playing.

        v1.12.86: per-section. With section_id provided, drops only
        that section's previous_urls row (the '' fallback row, if any,
        survives so other sections relying on it stay intact). Without
        section_id, drops every previous_urls row for the title — same
        as the legacy "clear themes.previous_youtube_url" semantic.

        Returns 409 if no matching previous URL is captured.
        """
        _require_admin(request)
        # v1.18.21: wrap the two destructive operations
        # (_clear_previous_url DELETE + _maybe_evict_empty_orphan
        # DELETE) in a single transaction. Pre-fix they ran under
        # autocommit (get_conn is isolation_level=None), so if the
        # themes DELETE inside the evict path raised mid-flight,
        # the previous_urls row was already gone → no REVERT/
        # RESTORE recovery + a half-cleared state. Explicit
        # transaction guarantees both succeed or both rollback.
        with get_conn(db) as conn, transaction(conn):
            # v1.12.117: figure out which previous_urls row is actually
            # showing. _load_previous_url tries section-specific then
            # falls back to ''. Pre-fix CLEAR URL deleted only the
            # section_id row even when the visible previous URL came
            # from the '' fallback (legacy pre-v1.12.105 captures from
            # other sections), so DELETE matched 0 rows and the URL
            # stayed visible — a silent no-op.
            section_target = section_id if section_id is not None else ""
            sec_row = None
            if section_id is not None:
                sec_row = conn.execute(
                    "SELECT youtube_url FROM previous_urls "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?",
                    (media_type, tmdb_id, section_id),
                ).fetchone()
            if sec_row is None:
                # No section-specific row — the visible previous URL is
                # from the '' fallback (or there's nothing). Target ''.
                global_row = conn.execute(
                    "SELECT youtube_url FROM previous_urls "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ''",
                    (media_type, tmdb_id),
                ).fetchone()
                if global_row is None:
                    raise HTTPException(
                        status_code=409,
                        detail="no captured previous URL to clear",
                    )
                old_url = global_row["youtube_url"]
                section_target = ""
            else:
                old_url = sec_row["youtube_url"]
            _clear_previous_url(
                conn, media_type, tmdb_id, section_id=section_target,
            )
            _record_audit(
                conn, actor=request.state.user, action="clear_previous_url",
                media_type=media_type, tmdb_id=tmdb_id,
                section_id=section_id,
                details={"old_url": old_url,
                         "cleared_from_section": section_target},
            )
            # v1.18.15: auto-evict zombie orphan rows. The prior
            # DELETE button (api_delete_item) was the only way to
            # remove a fully-empty orphan themes row; with that
            # button removed in v1.18.15, CLEAR URL becomes the
            # composition completion step: PURGE drops the files
            # + override + captures previous URL; CLEAR URL drops
            # the previous URL; if nothing else remains across
            # any section the orphan row gets dropped + cascades.
            # Real TDB rows are never evicted (next sync would
            # just re-create them).
            # v1.18.21: now runs inside the same transaction as
            # _clear_previous_url so a raise here rolls back the
            # previous_urls DELETE too.
            zombie_evicted = _maybe_evict_empty_orphan(
                conn, media_type, tmdb_id,
            )
        # v1.13.3: pass section_id so the event lands on the calling
        # section's HISTORY only — pre-fix the NULL section_id matched
        # every section's history view (NULL is the cross-section
        # scope by design), so CLEAR URL on standard surfaced on the
        # 4K card's HISTORY too. Mirrors the per-section semantic the
        # ack-failure / accept-update / decline-update handlers use.
        log_event(db, level="INFO", component="api",
                  media_type=media_type, tmdb_id=tmdb_id,
                  section_id=section_target,
                  message=f"Previous URL cleared by {request.state.user}")
        if zombie_evicted:
            log_event(db, level="INFO", component="api",
                      media_type=media_type, tmdb_id=tmdb_id,
                      message=(
                          f"Zombie orphan auto-evicted after CLEAR URL "
                          f"by {request.state.user}"
                      ))
        return {"ok": True, "zombie_evicted": zombie_evicted}

    @app.post("/api/items/{media_type}/{tmdb_id}/intent")
    async def api_set_override_intent(
        request: Request, media_type: MediaType, tmdb_id: int,
        section_id: str | None = Query(None),
        # v1.21.88: rating_key scopes PROMOTE TO ACTIVE / MARK AS BACKUP to
        # ONE edition — editions share a section, so section scope alone
        # flips a sibling edition's intent + force-places it.
        rating_key: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        """v1.18.77: flip a user_override row's intent between
        'backup' and 'replace'.

        Body: `{"intent": "backup" | "replace"}`

        Side-effects per intent transition:
          backup → replace:
            cancel any pending place jobs (defensive — there
            shouldn't be one for a backup row), enqueue a
            forced place job so motif's URL deploys over Plex's
            theme. This is the "PROMOTE TO ACTIVE" button's
            backend.

          replace → backup:
            no new jobs queued. If a place job is currently
            running it completes as designed (we don't yank
            it mid-flight). The row's NEXT post-download flow
            will respect the new 'backup' intent. This is the
            "MARK AS BACKUP" button's backend.

        409 if no user_override exists for the row + section.
        """
        _require_admin(request)
        body = {}
        try:
            body = await request.json()
        except Exception as e:  # noqa: BLE001
            log.debug(
                "api_set_override_intent: body parse failed: %s", e,
            )
        new_intent = (body or {}).get("intent")
        if new_intent not in ("backup", "replace"):
            raise HTTPException(
                status_code=400,
                detail="intent must be 'backup' or 'replace'",
            )
        section = section_id if section_id is not None else ""
        with get_conn(db) as conn, transaction(conn):
            # v1.21.88: resolve the clicked edition; _ed_sql/_ed_args narrow
            # every per-edition read/write below ('' / legacy when no rk).
            _intent_edition = (edition_key_for_rating_key(conn, rating_key)
                               if rating_key else "")
            _ed_sql = " AND edition_key = ?" if rating_key else ""
            _ed_args = (_intent_edition,) if rating_key else ()
            # Try per-section first, then '' global fallback.
            existing = conn.execute(
                "SELECT youtube_url, intent FROM user_overrides "
                "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?"
                + _ed_sql,
                (media_type, tmdb_id, section, *_ed_args),
            ).fetchone()
            if existing is None and section:
                existing = conn.execute(
                    "SELECT youtube_url, intent FROM user_overrides "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ''"
                    + _ed_sql,
                    (media_type, tmdb_id, *_ed_args),
                ).fetchone()
                if existing is not None:
                    section = ""  # operate on the global row
            if existing is None:
                # v1.19.35: no-override + BK-state branch. After
                # v1.19.32 ACCEPT UPDATE on a P-row, the user_overrides
                # row is DELETEd but the local_files row sits with
                # last_place_attempt_reason='backup_only'. The user
                # sees the v1.19.35-synthesized BACKUP READY banner +
                # PROMOTE TO ACTIVE button. Clicking PROMOTE must
                # promote the BK state without a real override to
                # flip: cancel pending place jobs + enqueue
                # force-place. Only the backup→replace direction is
                # meaningful here (you can't "MARK AS BACKUP" a row
                # that has no override to mark).
                if new_intent != "replace":
                    raise HTTPException(
                        status_code=409,
                        detail=(
                            "no user_override to flip intent on; "
                            "MARK AS BACKUP requires an existing "
                            "override"
                        ),
                    )
                section_for_bk = section_id or ""
                # v1.19.44: widened to also fetch source_kind so the
                # plex_cloud branch below can dispatch to the
                # v1.18.36 re-upload trick instead of the default
                # hardlink-sidecar place path. Pre-fix this SELECT
                # was `SELECT 1 FROM local_files`; the v1.19.43
                # tooltip claimed "re-upload trick" but the actual
                # path enqueued a vanilla place job which the
                # worker routed via default_placement_method
                # (typically 'file' → hardlink). Tooltip lied.
                # v1.19.54: also fetch source_video_id (stores the
                # SHA-1 the v1.19.42 walker captured at backup time)
                # so the drift check below can compare against
                # Plex's current selected entry SHA before
                # re-uploading.
                bk_local = conn.execute(
                    "SELECT source_kind, file_path, source_video_id "
                    "FROM local_files "
                    "WHERE media_type = ? AND tmdb_id = ? "
                    "  AND section_id = ? "
                    "  AND last_place_attempt_reason = 'backup_only' "
                    + _ed_sql +
                    " LIMIT 1",
                    (media_type, tmdb_id, section_for_bk, *_ed_args),
                ).fetchone()
                if not bk_local:
                    raise HTTPException(
                        status_code=409,
                        detail=(
                            "no user_override and no backup-only "
                            "local_files row — nothing to promote"
                        ),
                    )
                # Cancel any pending place jobs (defensive).
                # v1.22.75: edition-scoped (mirror the v1.21.88 cancel in
                # the with-override branch) — pre-fix this title-wide
                # cancel killed sibling editions'/sections' legitimately
                # queued place jobs.
                conn.execute(
                    """UPDATE jobs SET status = 'cancelled',
                                       finished_at = ?
                       WHERE job_type = 'place'
                         AND media_type = ? AND tmdb_id = ?
                         AND COALESCE(CASE WHEN json_valid(payload)
                             THEN json_extract(payload, '$.edition_key') END, '')
                             = ?
                         AND status IN ('pending', 'running')""",
                    (now_iso(), media_type, tmdb_id, _intent_edition),
                )
                # v1.19.44: plex_cloud rows route through the
                # v1.18.36 re-upload trick (synchronous upload via
                # /library/metadata/{rk}/themes) instead of the
                # default place-job → hardlink-sidecar path. This
                # matches the v1.19.43 PROMOTE TO ACTIVE tooltip
                # promise. For non-plex_cloud BK rows (themerrdb /
                # url / upload source_kind), the existing
                # enqueue-place-job path is correct — the user
                # explicitly chose KEEP AS BACKUP, and that flow
                # has always written sidecars on PROMOTE.
                bk_source_kind = (
                    bk_local["source_kind"] if bk_local else None
                )
                if bk_source_kind == "plex_cloud":
                    # Need the plex_items rk to know which row to
                    # upload to. Use guid_tmdb match scoped by
                    # section_id.
                    rk_row = conn.execute(
                        "SELECT rating_key FROM plex_items "
                        " WHERE guid_tmdb = ? "
                        "   AND section_id = ? "
                        "   AND ((? = 'tv' AND media_type = 'show') "
                        "        OR media_type = ?) "
                        + _ed_sql +
                        " LIMIT 1",
                        (tmdb_id, section_for_bk,
                         media_type, media_type, *_ed_args),
                    ).fetchone()
                    if not rk_row:
                        raise HTTPException(
                            status_code=409,
                            detail=(
                                "plex_cloud BK row has no plex_items "
                                "rating_key — Plex re-enumeration "
                                "needed before PROMOTE can re-upload"
                            ),
                        )
                    rk = rk_row["rating_key"]
                    # Read the staged bytes from disk. local_files.
                    # file_path is RELATIVE to themes_dir (see
                    # CLAUDE.md "File-path conventions").
                    from pathlib import Path as _Path
                    abs_path = (
                        _Path(settings.themes_dir) / bk_local["file_path"]
                    )
                    if not abs_path.exists():
                        raise HTTPException(
                            status_code=409,
                            detail=(
                                f"plex_cloud backup bytes missing on "
                                f"disk at {bk_local['file_path']!r} — "
                                f"re-run the v1.19.42 walker to "
                                f"re-stage"
                            ),
                        )
                    # v1.19.54: SHA-drift defense. Between motif's
                    # backup time and the user's PROMOTE click,
                    # Plex's cloud catalog may have updated the
                    # row's selected metadata entry to a different
                    # SHA-1 (Plex's cloud-catalog rotation, catalog
                    # provider switch, etc.). Without this check,
                    # the v1.18.36 re-upload trick would deploy
                    # motif's STALE bytes — content-dedup makes
                    # Plex select sha=A even though sha=B was just
                    # serving. The user clicks PROMOTE TO ACTIVE
                    # expecting "use my backup" and gets "ah, but
                    # actually my backup is from before Plex's
                    # last change — you're getting older content."
                    #
                    # Defense: probe Plex's current /themes,
                    # compare its selected entry's SHA against the
                    # SHA motif stored at backup time
                    # (source_video_id). On drift, return 409 with
                    # diagnostic so the client can confirm-and-retry
                    # with force_stale=true. The user gets the
                    # informed choice.
                    backup_sha = (
                        bk_local["source_video_id"] or ""
                    ).lower()
                    force_stale = bool(
                        (body or {}).get("force_stale", False)
                    )
                    from ..core.plex import PlexClient, PlexConfig
                    cfg = PlexConfig(
                        url=settings.plex_url,
                        token=settings.plex_token,
                        movie_section=settings.plex_movie_section,
                        tv_section=settings.plex_tv_section,
                        enabled=True,
                    )
                    if backup_sha and not force_stale:
                        with PlexClient(
                            cfg, plus_mode=settings.plus_equiv_mode,
                        ) as plex_probe:
                            # v1.22.42 (audit): the get_themes round-trip (up to
                            # 30s) ran on the event loop INSIDE this endpoint's
                            # BEGIN IMMEDIATE — it froze every concurrent request.
                            # Off-load to a thread so the loop keeps serving.
                            # (httpx.Client is thread-safe.) The write lock stays
                            # held across the await; the worker retries on lock
                            # (class 8) — acceptable for this rare manual path.
                            themes_resp = await run_in_threadpool(
                                plex_probe.get_themes, rating_key=rk,
                            )
                        current_sha = None
                        if themes_resp.get("ok"):
                            mc = (
                                (themes_resp.get("body") or {})
                                .get("MediaContainer") or {}
                            )
                            metadata_list = mc.get("Metadata") or []
                            from ..core.cloud_theme_backup import (
                                _sha1_from_entry_uri,
                            )
                            for entry in metadata_list:
                                if not isinstance(entry, dict):
                                    continue
                                if entry.get("selected") is not True:
                                    continue
                                uri = entry.get("ratingKey") or ""
                                if (isinstance(uri, str)
                                        and uri.startswith("metadata://")):
                                    current_sha = _sha1_from_entry_uri(uri)
                                break
                        if (current_sha and backup_sha
                                and current_sha != backup_sha):
                            # Drift detected — surface for the user.
                            log_event(
                                db, level="INFO", component="api",
                                media_type=media_type,
                                tmdb_id=tmdb_id,
                                section_id=section_for_bk,
                                message=(
                                    f"PROMOTE TO ACTIVE blocked "
                                    f"(sha_drift): backup_sha="
                                    f"{backup_sha[:12]} vs "
                                    f"current_plex_sha="
                                    f"{current_sha[:12]} on "
                                    f"rk={rk}"
                                ),
                            )
                            raise HTTPException(
                                status_code=409,
                                detail={
                                    "error": "sha_drift",
                                    "message": (
                                        "Plex's currently-served "
                                        "cloud theme SHA differs "
                                        "from motif's staged backup. "
                                        "Promoting would deploy "
                                        "stale content."
                                    ),
                                    "rk": rk,
                                    "backup_sha": backup_sha,
                                    "current_plex_sha": current_sha,
                                },
                            )
                    # v1.22.42 (audit): the 50MB read + the upload round-trip
                    # both ran on the event loop inside the txn. Off-load both so
                    # concurrent requests aren't frozen during the PROMOTE.
                    audio_bytes = await run_in_threadpool(abs_path.read_bytes)
                    with PlexClient(
                        cfg, plus_mode=settings.plus_equiv_mode,
                    ) as plex:
                        upload_ok, upload_status, upload_body = (
                            await run_in_threadpool(
                                plex.upload_collection_theme,
                                rating_key=rk,
                                audio_bytes=audio_bytes,
                            )
                        )
                    if not upload_ok:
                        log_event(
                            db, level="WARNING", component="api",
                            media_type=media_type, tmdb_id=tmdb_id,
                            section_id=section_for_bk,
                            message=(
                                f"PROMOTE TO ACTIVE (plex_cloud) "
                                f"re-upload failed: HTTP "
                                f"{upload_status} — {upload_body!r}"
                            ),
                        )
                        raise HTTPException(
                            status_code=502,
                            detail=(
                                f"re-upload to Plex failed "
                                f"(HTTP {upload_status}). Check the "
                                f"LOGS tab for details."
                            ),
                        )
                    # Stamp a plex_upload placement so the row's
                    # SRC pill flips off the P state + the LINK
                    # axis reflects the new motif-owned state.
                    theme_row = conn.execute(
                        "SELECT id FROM themes "
                        " WHERE media_type = ? AND tmdb_id = ?",
                        (media_type, tmdb_id),
                    ).fetchone()
                    theme_id = (
                        theme_row["id"] if theme_row else None
                    )
                    if theme_id is not None:
                        conn.execute(
                            """INSERT INTO placements
                                 (theme_id, media_type, tmdb_id,
                                  section_id, edition_key, plex_rating_key,
                                  placement_kind, media_folder,
                                  placed_at, plex_refreshed)
                               VALUES (?, ?, ?, ?, ?, ?,
                                       'plex_upload', '',
                                       ?, 1)
                               ON CONFLICT(media_type, tmdb_id,
                                           section_id, media_folder,
                                           edition_key)
                               DO UPDATE SET
                                 placement_kind = excluded.placement_kind,
                                 plex_rating_key = excluded.plex_rating_key,
                                 placed_at = excluded.placed_at,
                                 plex_refreshed = excluded.plex_refreshed""",
                            (theme_id, media_type, tmdb_id,
                             section_for_bk, _intent_edition, rk, now_iso()),
                        )
                    # Clear the backup_only marker so the row
                    # surfaces as PU (placed) rather than B (backup).
                    conn.execute(
                        "UPDATE local_files "
                        "   SET last_place_attempt_reason = NULL, "
                        "       last_place_attempt_at = ? "
                        " WHERE media_type = ? AND tmdb_id = ? "
                        "   AND section_id = ?"
                        + _ed_sql,
                        (now_iso(), media_type, tmdb_id,
                         section_for_bk, *_ed_args),
                    )
                    _record_audit(
                        conn, actor=request.state.user,
                        action="set_intent",
                        media_type=media_type, tmdb_id=tmdb_id,
                        section_id=section_for_bk,
                        details={
                            "from": "backup_no_override",
                            "to": new_intent,
                            "via": "plex_cloud_reupload",
                            "rk": rk,
                        },
                    )
                    log_event(
                        db, level="INFO", component="api",
                        media_type=media_type, tmdb_id=tmdb_id,
                        section_id=section_for_bk,
                        message=(
                            f"PROMOTE TO ACTIVE (plex_cloud) "
                            f"via v1.18.36 re-upload trick "
                            f"on rk={rk} by {request.state.user}"
                        ),
                    )
                    return {
                        "ok": True,
                        "intent": new_intent,
                        "changed": True,
                        "bk_no_override": True,
                        "via": "plex_cloud_reupload",
                    }
                place_payload = {
                    "force": True,
                    "force_place": True,
                    "reason": "promote_bk_no_override",
                }
                # v1.21.88: target the place at THIS edition's folder.
                if _intent_edition:
                    place_payload["edition_key"] = _intent_edition
                conn.execute(
                    """INSERT INTO jobs
                         (job_type, media_type, tmdb_id, section_id,
                          payload, status, created_at, next_run_at)
                       VALUES ('place', ?, ?, ?, ?,
                               'pending', ?, ?)""",
                    (media_type, tmdb_id, section_for_bk,
                     json.dumps(place_payload),
                     now_iso(), now_iso()),
                )
                _record_audit(
                    conn, actor=request.state.user,
                    action="set_intent",
                    media_type=media_type, tmdb_id=tmdb_id,
                    section_id=section_for_bk,
                    details={
                        "from": "backup_no_override",
                        "to": new_intent,
                    },
                )
                log_event(
                    db, level="INFO", component="api",
                    media_type=media_type, tmdb_id=tmdb_id,
                    section_id=section_for_bk,
                    message=(
                        f"PROMOTE TO ACTIVE on BK row (no override) "
                        f"by {request.state.user}"
                    ),
                )
                return {
                    "ok": True,
                    "intent": new_intent,
                    "changed": True,
                    "bk_no_override": True,
                }
            prior_intent = existing["intent"]
            if prior_intent == new_intent:
                return {
                    "ok": True,
                    "intent": new_intent,
                    "changed": False,
                }
            conn.execute(
                "UPDATE user_overrides SET intent = ? "
                "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?"
                + _ed_sql,
                (new_intent, media_type, tmdb_id, section, *_ed_args),
            )
            _record_audit(
                conn, actor=request.state.user,
                action="set_intent",
                media_type=media_type, tmdb_id=tmdb_id,
                section_id=section,
                details={
                    "from": prior_intent, "to": new_intent,
                },
            )
            # On backup → replace, enqueue a forced place job for
            # every section where motif has staged content. The
            # worker will overwrite Plex's theme.
            if new_intent == "replace":
                # Cancel any in-flight place jobs first (defensive
                # — a backup-intent row shouldn't have queued
                # placements, but rare race conditions could leave
                # one stuck).
                # v1.21.88: edition-scope the cancel (payload edition_key, v74
                # guard) so a sibling edition's queued place isn't cancelled.
                conn.execute(
                    """UPDATE jobs SET status = 'cancelled',
                                       finished_at = ?
                       WHERE job_type = 'place'
                         AND media_type = ? AND tmdb_id = ?
                         AND COALESCE(CASE WHEN json_valid(payload)
                             THEN json_extract(payload, '$.edition_key') END, '')
                             = ?
                         AND status IN ('pending', 'running')""",
                    (now_iso(), media_type, tmdb_id, _intent_edition),
                )
                # Enqueue a force-place job per section that has
                # local_files staged. Mirrors api_manual_url's
                # is_p_row force_place=True branch.
                # v1.21.88: scoped to THIS edition's staged local_files.
                staged_sections = conn.execute(
                    "SELECT DISTINCT section_id FROM local_files "
                    "WHERE media_type = ? AND tmdb_id = ?"
                    + _ed_sql,
                    (media_type, tmdb_id, *_ed_args),
                ).fetchall()
                place_payload = {
                    "force": True,
                    "force_place": True,
                    "reason": "promote_backup_to_active",
                }
                # v1.21.88: target the place at THIS edition's folder.
                if _intent_edition:
                    place_payload["edition_key"] = _intent_edition
                for s in staged_sections:
                    conn.execute(
                        """INSERT INTO jobs
                             (job_type, media_type, tmdb_id, section_id,
                              payload, status, created_at, next_run_at)
                           VALUES ('place', ?, ?, ?, ?,
                                   'pending', ?, ?)""",
                        (media_type, tmdb_id, s["section_id"],
                         json.dumps(place_payload),
                         now_iso(), now_iso()),
                    )
        log_event(
            db, level="INFO", component="api",
            media_type=media_type, tmdb_id=tmdb_id,
            section_id=section,
            message=(
                f"Override intent changed: {prior_intent} → "
                f"{new_intent} by {request.state.user}"
            ),
            detail={"from": prior_intent, "to": new_intent},
        )
        return {
            "ok": True,
            "intent": new_intent,
            "changed": True,
            "from": prior_intent,
        }

    @app.post("/api/items/{media_type}/{tmdb_id}/revert")
    async def api_revert_to_themerrdb(
        request: Request, media_type: MediaType, tmdb_id: int,
        # v1.12.47: optional section_id scopes the re-download +
        # placement to one section (mirrors the v1.12.46
        # ACCEPT UPDATE flow). Without it, the download fans
        # out to every section that owns the title — wrong
        # when only one library/edition is being reverted.
        section_id: str | None = Query(None),
        # v1.21.73: optional rating_key scopes the override restore/drop +
        # the accepted-pending_update reset to ONE edition. None = legacy
        # (section-only / un-scoped) behavior.
        rating_key: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        """REVERT the row's canonical URL one step back to the
        captured previous URL for this section.

        v1.12.37: generalized one-step undo. The snapshot is
        populated by any handler that changes the canonical URL
        (ACCEPT UPDATE, SET URL, UPLOAD MP3, REPLACE TDB,
        PURGE/UNMANAGE pre-drop).

        Resolves which restoration path to apply based on the
        snapshot's kind:
          'user'      → INSERT user_overrides with previous URL
                        (row goes back to U, blue TDB ↑ pill
                        returns if there's a pending update).
          'themerrdb' → DELETE user_overrides (worker uses
                        themes.youtube_url which is the upstream
                        URL; row goes to T).

        Either way, swaps the new "current → previous" URL pair
        atomically so REVERT is fully round-trippable: clicking
        REVERT twice returns the row to its pre-first-revert
        state. Returns 409 if no previous URL is captured.

        v1.12.86: reads/writes the per-section previous_urls table
        instead of the title-global themes.previous_youtube_url
        columns. RESTORE on section A no longer disturbs section B.
        """
        _require_admin(request)
        with get_conn(db) as conn, transaction(conn):
            theme_row = conn.execute(
                "SELECT youtube_url FROM themes "
                "WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            if theme_row is None:
                raise HTTPException(status_code=404, detail="not in database")
            # v1.21.73: the clicked edition (None = no rk → legacy). The
            # previous_urls snapshot stays per-section (3-col PK, not widened),
            # but the override write/drop + the pending_update reset below
            # narrow to this edition when known.
            _rev_edition = (
                edition_key_for_rating_key(conn, rating_key)
                if rating_key else None)
            snapshot = _load_previous_url(
                conn, media_type, tmdb_id, section_id=section_id,
            )
            if snapshot is None:
                raise HTTPException(
                    status_code=409,
                    detail="nothing to revert — no previous URL captured for this row",
                )
            prev_url = snapshot["youtube_url"]
            prev_kind = snapshot["kind"]

            # Snapshot what's currently in the canonical so REVERT
            # is a swap, not a one-way pop. Capturing here also
            # means a second REVERT call cleanly round-trips.
            # v1.12.79: prefer the section-specific override row
            # so a per-section revert round-trips against the
            # section's URL rather than picking up a sibling
            # section's override by accident. Falls back to the
            # '' global row, then to themes.youtube_url.
            ovr_section = section_id or ""
            # v1.21.73: round-trip against THIS edition's override first
            # (then the shared '' edition, then the '' global section).
            # v1.22.62 (audit round 2 #3): all four SELECTs include
            # `intent` — the v1.19.36 prior_intent rollback stamp below
            # reads ovr["intent"] behind a `"intent" in ovr.keys()` guard
            # that was ALWAYS False against youtube_url-only rows, so a
            # terminally-failed REVERT download restored a backup-intent
            # override as intent='replace' (mirrors the ACCEPT fix).
            ovr = None
            if _rev_edition is not None:
                ovr = conn.execute(
                    "SELECT youtube_url, intent FROM user_overrides "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ? "
                    "  AND edition_key = ?",
                    (media_type, tmdb_id, ovr_section, _rev_edition),
                ).fetchone()
                if (ovr is None or not ovr["youtube_url"]) and _rev_edition:
                    ovr = conn.execute(
                        "SELECT youtube_url, intent FROM user_overrides "
                        "WHERE media_type = ? AND tmdb_id = ? AND section_id = ? "
                        "  AND edition_key = ''",
                        (media_type, tmdb_id, ovr_section),
                    ).fetchone()
            else:
                ovr = conn.execute(
                    "SELECT youtube_url, intent FROM user_overrides "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?",
                    (media_type, tmdb_id, ovr_section),
                ).fetchone()
            if ovr is None or not ovr["youtube_url"]:
                ovr = conn.execute(
                    "SELECT youtube_url, intent FROM user_overrides "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ''",
                    (media_type, tmdb_id),
                ).fetchone()
            if ovr and ovr["youtube_url"]:
                new_prev_url = ovr["youtube_url"]
                new_prev_kind = "user"
            else:
                new_prev_url = theme_row["youtube_url"]
                new_prev_kind = "themerrdb" if new_prev_url else None

            # Apply the previous URL based on its kind.
            # v1.12.39: provenance flip happens lazily, on the
            # worker's download completion (worker.py writes
            # provenance + source_kind from the CURRENT presence
            # of a user override). Pre-fix this handler eagerly
            # flipped local_files + placements provenance, so the
            # SRC badge transitioned to its target value the
            # instant REVERT was clicked — even though the
            # canonical was still the OLD theme until the
            # download landed. Now the SRC badge stays on its
            # current value (T after a previous accept; U after a
            # previous SET URL) until the new canonical is in
            # place, matching the user's mental model: "the row's
            # SRC describes what's actually playing".
            if prev_kind == "user":
                # v1.12.72: scope to the row's section_id when
                # provided. Without a section the legacy '' global
                # row gets restored, matching pre-migration behavior.
                # v1.19.35: when the row is currently P (Plex
                # serves), the restored override must carry
                # intent='backup' to match the actual state — the
                # v1.19.33 P-row REVERT branch lands the row in
                # BK mode (no placement, Plex serves, motif holds
                # the file). Defaulting to schema's 'replace'
                # would lie about the row's state and put a
                # MARK AS BACKUP button on the recovery card
                # instead of the correct PROMOTE TO ACTIVE.
                ovr_section = section_id or ""
                restored_intent = (
                    "backup" if section_id
                    and _is_p_row_for_section(
                        conn, media_type=media_type,
                        tmdb_id=tmdb_id, section_id=section_id,
                        edition_key=_rev_edition or "",
                    )
                    else "replace"
                )
                conn.execute(
                    """INSERT INTO user_overrides
                         (media_type, tmdb_id, youtube_url,
                          set_at, set_by, note, section_id,
                          edition_key, intent)
                       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                       ON CONFLICT(media_type, tmdb_id, section_id, edition_key) DO UPDATE SET
                           youtube_url = excluded.youtube_url,
                           set_at = excluded.set_at,
                           set_by = excluded.set_by,
                           note = excluded.note,
                           intent = excluded.intent""",
                    (media_type, tmdb_id, prev_url, now_iso(),
                     request.state.principal.username,
                     "restored via REVERT", ovr_section,
                     _rev_edition or "", restored_intent),
                )
                # If a pending_update was previously accepted on
                # this row, reset it so the blue TDB ↑ pill
                # returns — user is back in the pre-accept state.
                # v1.21.73: scope the reset to this section + edition.
                # Pre-fix the UPDATE matched (mt, tmdb, decision='accepted')
                # ONLY — so REVERT on one edition (or section) reset EVERY
                # edition's/section's accepted decision, resurrecting their
                # !UPD pills. section_id/edition_key added when known;
                # legacy callers (no section/rk) keep the title-wide reset.
                _rev_pu_extra = ""
                _rev_pu_params = [media_type, tmdb_id]
                if section_id is not None:
                    _rev_pu_extra += " AND section_id = ?"
                    _rev_pu_params.append(section_id)
                if _rev_edition is not None:
                    _rev_pu_extra += " AND edition_key = ?"
                    _rev_pu_params.append(_rev_edition)
                conn.execute(
                    """UPDATE pending_updates SET
                         decision = 'pending',
                         decision_at = NULL,
                         decision_by = NULL,
                         replaced_user_url = NULL
                       WHERE media_type = ? AND tmdb_id = ?
                         AND decision = 'accepted'""" + _rev_pu_extra,
                    tuple(_rev_pu_params),
                )
            else:  # 'themerrdb'
                # Drop user_overrides so the worker uses
                # themes.youtube_url on download. If the previous
                # URL no longer matches themes.youtube_url (TDB
                # has changed since the snapshot), the worker
                # will download the current TDB URL — close
                # enough for a one-step undo.
                # v1.12.72: scope to the row's section. Sibling
                # sections' overrides survive (they may have their
                # own per-edition URL the user wants to keep).
                # When called without section_id (legacy / orphan
                # paths), drops only the '' global row.
                # v1.21.73: drop only THIS edition's override when known, so
                # reverting one edition to TDB doesn't strip a sibling
                # edition's URL in the same section.
                ovr_section = section_id or ""
                if _rev_edition is not None:
                    conn.execute(
                        "DELETE FROM user_overrides "
                        "WHERE media_type = ? AND tmdb_id = ? "
                        "  AND section_id = ? AND edition_key = ?",
                        (media_type, tmdb_id, ovr_section, _rev_edition),
                    )
                else:
                    conn.execute(
                        "DELETE FROM user_overrides "
                        "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?",
                        (media_type, tmdb_id, ovr_section),
                    )

            # Swap the previous_urls snapshot to point at what was
            # current before this revert — REVERT becomes
            # round-trippable. v1.12.86: per-section write (was a
            # title-global update on themes columns).
            # v1.12.102: when the snapshot we just consumed has a
            # hidden_* slot (PURGE/UNMANAGE pre-loaded it with the
            # URL that was previous BEFORE the destructive action),
            # promote hidden_* to previous_url instead of swapping.
            # This is the post-RESTORE step: previous_url goes back
            # to whatever was previous before the user purged, so a
            # subsequent REVERT continues the chain. The hidden slot
            # is consumed (cleared) since the round-trip is complete.
            target_section = section_id if section_id is not None else ""
            hidden_url = snapshot["hidden_url"] if snapshot else None
            hidden_kind = snapshot["hidden_kind"] if snapshot else None
            if hidden_url and hidden_kind:
                conn.execute(
                    """INSERT INTO previous_urls
                         (media_type, tmdb_id, section_id, youtube_url,
                          kind, captured_at,
                          hidden_url, hidden_kind, hidden_captured_at)
                       VALUES (?, ?, ?, ?, ?, ?, NULL, NULL, NULL)
                       ON CONFLICT(media_type, tmdb_id, section_id) DO UPDATE SET
                           youtube_url = excluded.youtube_url,
                           kind = excluded.kind,
                           captured_at = excluded.captured_at,
                           hidden_url = NULL,
                           hidden_kind = NULL,
                           hidden_captured_at = NULL""",
                    (media_type, tmdb_id, target_section,
                     hidden_url, hidden_kind, now_iso()),
                )
            elif new_prev_url and new_prev_kind:
                conn.execute(
                    """INSERT INTO previous_urls
                         (media_type, tmdb_id, section_id, youtube_url,
                          kind, captured_at,
                          hidden_url, hidden_kind, hidden_captured_at)
                       VALUES (?, ?, ?, ?, ?, ?, NULL, NULL, NULL)
                       ON CONFLICT(media_type, tmdb_id, section_id) DO UPDATE SET
                           youtube_url = excluded.youtube_url,
                           kind = excluded.kind,
                           captured_at = excluded.captured_at,
                           hidden_url = NULL,
                           hidden_kind = NULL,
                           hidden_captured_at = NULL""",
                    (media_type, tmdb_id, target_section,
                     new_prev_url, new_prev_kind, now_iso()),
                )
            else:
                _clear_previous_url(
                    conn, media_type, tmdb_id, section_id=section_id,
                )
            # v1.13.74: do NOT clear failure_kind here. Pre-fix this
            # unconditional clear caused a red `TDB ✗` pill to flip
            # green when the user did REVERT to escape a failed
            # REPLACE-W-TDB attempt — the TDB URL was still dead but
            # the failure flag got wiped, lying to the user. The
            # subsequent download enqueued below now manages
            # failure_kind correctly: a successful TDB-URL download
            # clears it (worker._record_local_file scoped to
            # source_kind='themerrdb' in the same release), a
            # user-URL success leaves it alone, a fresh failure
            # overwrites it. REVERT itself shouldn't pre-judge the
            # outcome.
            # Cancel any in-flight download (would otherwise pick
            # up the stale URL), then enqueue a fresh one.
            # v1.22.7 (code-review): scope the cancel to THIS row's section +
            # edition, mirroring the re-download (v1.21.82) and SET URL
            # (v1.22.1) cancels. Pre-fix it was title-wide (media_type+tmdb_id)
            # while the _enqueue_download below is per-edition+section
            # (edition_key=_rev_edition, only_section_id) — a REVERT on one
            # edition silently flipped a sibling edition's (or sibling
            # section's) pending download to 'cancelled'. jobs has no
            # edition_key column; read it off the payload (json_valid guard).
            if section_id:
                conn.execute(
                    """UPDATE jobs SET status = 'cancelled', finished_at = ?
                       WHERE job_type = 'download' AND media_type = ? AND tmdb_id = ?
                         AND section_id = ?
                         AND COALESCE(CASE WHEN json_valid(payload)
                             THEN json_extract(payload, '$.edition_key') END, '') = ?
                         AND status IN ('pending', 'failed')""",
                    (now_iso(), media_type, tmdb_id, section_id, _rev_edition or ""),
                )
            else:
                conn.execute(
                    """UPDATE jobs SET status = 'cancelled', finished_at = ?
                       WHERE job_type = 'download' AND media_type = ? AND tmdb_id = ?
                         AND COALESCE(CASE WHEN json_valid(payload)
                             THEN json_extract(payload, '$.edition_key') END, '') = ?
                         AND status IN ('pending', 'failed')""",
                    (now_iso(), media_type, tmdb_id, _rev_edition or ""),
                )
            # v1.12.47: REVERT now passes force_place=True +
            # only_section_id (when provided) — mirrors the
            # v1.12.43 ACCEPT UPDATE fix. Pre-fix the place job
            # ran but skipped with status "plex_has_theme"
            # because the existing post-accept theme.mp3 was
            # there; the new (reverted-to) URL got downloaded
            # into canonical but never replaced the placement,
            # so Plex kept playing the post-accept theme.
            from ..core.sync import _enqueue_download
            # v1.12.114: rollback recipe restores the pre-REVERT state
            # if the download fails terminally. Without this, REVERT
            # consumes the previous_urls chain + replaces/deletes the
            # override eagerly — a download failure would leave the
            # row in a half-applied state with no easy recovery.
            prior_prev_row = {
                "youtube_url": snapshot["youtube_url"],
                "kind": snapshot["kind"],
                "captured_at": snapshot["captured_at"],
                "hidden_url": snapshot["hidden_url"],
                "hidden_kind": snapshot["hidden_kind"],
                "hidden_captured_at": snapshot["hidden_captured_at"],
            } if snapshot else None
            prior_override_url = (ovr["youtube_url"]
                                  if ovr and ovr["youtube_url"] else None)
            # v1.19.36: stamp prior_intent so the worker rollback
            # restores the intent column too (mirrors the
            # ACCEPT UPDATE rollback fix above).
            prior_intent = (
                ovr["intent"]
                if ovr and "intent" in ovr.keys()
                else "replace"
            )
            rollback = {
                "kind": "revert",
                "prior_override_url": prior_override_url,
                "prior_previous_url_row": prior_prev_row,
                "prior_intent": prior_intent,
                # v1.22.21 (edition audit): restore/clear the override on THIS
                # edition on a terminal REVERT-download failure, not the '' row.
                "edition_key": _rev_edition or "",
            }
            # v1.19.33: REVERT P-row branch. The legacy v1.12.47
            # force_place=True path steals Plex's serving slot when
            # the row is currently SRC=P — same Bleach-shape repro
            # v1.19.32 fixed for ACCEPT UPDATE. Symptom: user reverts
            # a P+backup ACCEPT, gets force-placed via plex_upload,
            # row flips P → U / T.
            #
            # On a P-row REVERT, enqueue with auto_place=False + a
            # distinct reason so the worker's backup_only stamp
            # fires (BK badge surfaces + retry sweep skips). When
            # section_id is omitted (legacy / orphan paths) we keep
            # the historic force_place semantics — those callers
            # don't have per-row P context.
            revert_is_p_row = False
            if section_id:
                revert_is_p_row = _is_p_row_for_section(
                    conn, media_type=media_type,
                    tmdb_id=tmdb_id, section_id=section_id,
                    edition_key=_rev_edition or "",
                )
            if revert_is_p_row:
                _enqueue_download(
                    conn, media_type=media_type, tmdb_id=tmdb_id,
                    reason=f"revert_to_{prev_kind}_url_p_backup",
                    auto_place=False,
                    only_section_id=section_id,
                    rollback=rollback,
                    edition_key=_rev_edition or "",
                )
            else:
                _enqueue_download(
                    conn, media_type=media_type, tmdb_id=tmdb_id,
                    reason=f"revert_to_{prev_kind}_url",
                    auto_place=True,
                    force_place=True,
                    only_section_id=section_id,
                    rollback=rollback,
                    edition_key=_rev_edition or "",
                )
            _record_audit(
                conn, actor=request.state.user, action="revert",
                media_type=media_type, tmdb_id=tmdb_id,
                section_id=section_id,
                details={
                    "restored_url": prev_url,
                    "restored_kind": prev_kind,
                    "new_previous_url": new_prev_url,
                    "new_previous_kind": new_prev_kind,
                    "p_row_backup": revert_is_p_row,
                },
            )
        # v1.19.34: surface the v1.19.33 P-row branch in HISTORY so
        # the timeline explains why no place job ran when REVERT
        # landed on a SRC=P row.
        revert_branch_note = (
            " (P-row — downloaded as backup; Plex keeps serving)"
            if revert_is_p_row else ""
        )
        log_event(db, level="INFO", component="api",
                  media_type=media_type, tmdb_id=tmdb_id,
                  section_id=section_id,
                  message=(f"REVERT to {prev_kind} URL by "
                           f"{request.state.user}"
                           f"{revert_branch_note}"))
        return {"ok": True}

    @app.get("/api/items/{media_type}/{tmdb_id}/audit")
    async def api_item_audit(
        media_type: MediaType, tmdb_id: int,
        section_id: str | None = Query(None),
        limit: int = Query(50, ge=1, le=500),
        db: Path = Depends(get_db_path),
    ):
        """v1.12.80: audit_events for a single row, newest first.
        Powers the INFO card's // PROVENANCE section so users can
        see "who changed this row, when, and what was the URL
        before" months after the fact — distinct from the rolling
        events log which gets rotated.

        v1.12.81: section_id filter. When the INFO card is opened
        on a 4K row the user expects PROVENANCE to show actions
        taken against that section — pre-fix the unfiltered query
        returned every audit row for the title, so the standard
        and 4K cards rendered identical timelines and the user
        couldn't tell which section's history they were looking
        at. The filter keeps title-global rows (section_id IS NULL
        — e.g., ADOPT which spans every section) visible alongside
        the section-specific ones, so cross-section context isn't
        lost."""
        with get_conn(db) as conn:
            if section_id is not None:
                rows = conn.execute(
                    """SELECT id, occurred_at, actor, action, section_id, details
                         FROM audit_events
                        WHERE media_type = ? AND tmdb_id = ?
                          AND (section_id = ? OR section_id IS NULL)
                        ORDER BY occurred_at DESC, id DESC
                        LIMIT ?""",
                    (media_type, tmdb_id, section_id, limit),
                ).fetchall()
            else:
                rows = conn.execute(
                    """SELECT id, occurred_at, actor, action, section_id, details
                         FROM audit_events
                        WHERE media_type = ? AND tmdb_id = ?
                        ORDER BY occurred_at DESC, id DESC
                        LIMIT ?""",
                    (media_type, tmdb_id, limit),
                ).fetchall()
        out = []
        for r in rows:
            details = None
            if r["details"]:
                try:
                    details = json.loads(r["details"])
                except (ValueError, TypeError):
                    details = None
            out.append({
                "id": r["id"],
                "occurred_at": r["occurred_at"],
                "actor": r["actor"],
                "action": r["action"],
                "section_id": r["section_id"],
                "details": details,
            })
        return {"events": out}

    @app.delete("/api/items/{media_type}/{tmdb_id}/audit")
    async def api_item_audit_clear(
        request: Request, media_type: MediaType, tmdb_id: int,
        section_id: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        """v1.12.83: clear audit_events for a single row. Useful while
        testing — repeated SET URL / ACCEPT UPDATE / PURGE cycles can
        bloat PROVENANCE to dozens of entries that are only meaningful
        to the testing session. Admin-only.

        Honors the same section_id filter as the GET so the user can
        clear just one section's row without nuking title-global
        entries (NULL section_id, e.g. ADOPT). Without section_id
        every audit row for the (media_type, tmdb_id) tuple is
        deleted.
        """
        _require_admin(request)
        with get_conn(db) as conn, transaction(conn):
            if section_id is not None:
                # v1.22.75: section-scoped ONLY. The `OR section_id IS NULL`
                # half deleted title-global rows (ADOPT etc.) — the exact
                # thing the docstring promises to preserve. The GET includes
                # NULL rows for DISPLAY; copying that predicate into the
                # DELETE was the bug. Mirrors api_item_events_clear.
                cur = conn.execute(
                    """DELETE FROM audit_events
                        WHERE media_type = ? AND tmdb_id = ?
                          AND section_id = ?""",
                    (media_type, tmdb_id, section_id),
                )
            else:
                cur = conn.execute(
                    "DELETE FROM audit_events "
                    "WHERE media_type = ? AND tmdb_id = ?",
                    (media_type, tmdb_id),
                )
        return {"ok": True, "deleted": cur.rowcount}

    @app.delete("/api/items/{media_type}/{tmdb_id}/events")
    async def api_item_events_clear(
        request: Request, media_type: MediaType, tmdb_id: int,
        # v1.12.119: section_id scopes the clear to one section's events.
        # Pre-fix the DELETE was title-wide, so clicking CLEAR on the
        # standard's INFO card also wiped the 4K's history (different
        # libraries / editions despite same tmdb_id). Each section's
        # INFO card now owns its own history. Title-wide events
        # (section_id IS NULL — sync runs, scans, etc.) survive a
        # per-section clear; legacy callers without section_id keep
        # the original title-wide semantic.
        section_id: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        """v1.12.83: clear the rolling events log entries for a row
        (drives the INFO card's // HISTORY section). v1.12.119:
        per-section by default (events.section_id added in schema v29);
        omit section_id query param for the legacy title-wide clear.
        Admin-only."""
        _require_admin(request)
        with get_conn(db) as conn, transaction(conn):
            if section_id is not None:
                # Delete only this section's events. Title-wide events
                # (section_id IS NULL) survive — they're shared signal
                # like sync runs and scans.
                cur = conn.execute(
                    "DELETE FROM events "
                    "WHERE media_type = ? AND tmdb_id = ? "
                    "  AND section_id = ?",
                    (media_type, tmdb_id, section_id),
                )
            else:
                cur = conn.execute(
                    "DELETE FROM events "
                    "WHERE media_type = ? AND tmdb_id = ?",
                    (media_type, tmdb_id),
                )
        return {"ok": True, "deleted": cur.rowcount,
                "scope": "section" if section_id is not None else "title"}

    @app.get("/api/items/{media_type}/{tmdb_id}/theme.mp3")
    async def api_item_theme_audio(
        request: Request, media_type: MediaType, tmdb_id: int,
        section_id: str | None = Query(None),
        # v1.21.90: rating_key picks THIS edition's canonical — pre-fix the
        # INFO-card player served an arbitrary edition's file (the first
        # local_files row for the section), so a multi-edition title played
        # the wrong edition's theme (the user: Sam edition played the old T song).
        rating_key: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        """v1.12.90: stream the canonical theme.mp3 for in-browser
        audio playback from the INFO card. Resolves the file via
        local_files (per-section when section_id is provided, falling
        back to any-section). FastAPI's FileResponse handles range
        requests so the <audio> element can seek without re-fetching
        the whole file.

        Auth-required like every other /api/items/* endpoint. Returns
        404 when the row has no canonical recorded, and 410 when the
        DB has a file_path but the file isn't actually on disk
        (canonical_missing / dlBroken state).
        """
        _require_admin(request)
        with get_conn(db) as conn:
            # v1.21.90: when the click carries a rating_key, serve THIS
            # edition's canonical (prefer the edition row, fall back to the
            # shared '' row). Absent rating_key -> legacy section-only.
            _th_edition = (edition_key_for_rating_key(conn, rating_key)
                           if rating_key else None)
            if section_id is not None and _th_edition is not None:
                row = conn.execute(
                    "SELECT file_path FROM local_files "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ? "
                    "  AND edition_key IN (?, '') "
                    "ORDER BY (edition_key = ?) DESC LIMIT 1",
                    (media_type, tmdb_id, section_id, _th_edition, _th_edition),
                ).fetchone()
            elif section_id is not None:
                row = conn.execute(
                    "SELECT file_path FROM local_files "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?",
                    (media_type, tmdb_id, section_id),
                ).fetchone()
            else:
                row = conn.execute(
                    "SELECT file_path FROM local_files "
                    "WHERE media_type = ? AND tmdb_id = ? "
                    "ORDER BY section_id LIMIT 1",
                    (media_type, tmdb_id),
                ).fetchone()
        if row is None or not row["file_path"]:
            raise HTTPException(status_code=404, detail="no canonical recorded for this row")
        if not settings.is_paths_ready():
            raise HTTPException(status_code=503, detail="themes_dir not configured")
        full = settings.themes_dir / row["file_path"]
        try:
            full = full.resolve()
            themes_root = settings.themes_dir.resolve()
        except OSError as e:
            raise HTTPException(status_code=500, detail=f"path resolution failed: {e}")
        # Reject path-traversal attempts — full must live under themes_dir.
        if themes_root not in full.parents and full != themes_root:
            raise HTTPException(status_code=400, detail="resolved path escapes themes_dir")
        if not full.is_file():
            # v1.15.126: detailed diagnostic — pre-fix the 410
            # just said "canonical recorded but missing on disk"
            # without any hint about WHY. the user's Watchmen case
            # hit this 410 even though the file was visible in
            # Unraid's file manager AT THE SAME PATH the UI
            # displays. The mismatch sits somewhere between the
            # UI's stringified `settings.themes_dir / file_path`
            # (no resolve, no stat) and the endpoint's resolved
            # + stat'd `full`. Log every step so the next 410
            # report comes with actionable forensics.
            try:
                parent = full.parent
                parent_exists = parent.exists()
                parent_is_dir = parent.is_dir() if parent_exists else False
                # List parent siblings (cheap on dirs with <100 entries;
                # capped just in case) so case-mismatch / encoding
                # issues surface.
                try:
                    sibling_names = sorted(
                        p.name for p in parent.iterdir()
                    )[:20] if parent_is_dir else []
                except OSError as e:
                    sibling_names = [f"<iterdir failed: {e}>"]
            except OSError as e:
                parent_exists = False
                parent_is_dir = False
                sibling_names = [f"<parent stat failed: {e}>"]
            log.warning(
                "theme.mp3 dlBroken — db row points to a path that "
                "doesn't resolve to a regular file. media_type=%s "
                "tmdb_id=%s section_id=%s | "
                "themes_dir=%s | file_path=%r | "
                "resolved_full=%s | full.exists=%s | "
                "parent=%s | parent.exists=%s | parent.is_dir=%s | "
                "parent_contents=%r",
                media_type, tmdb_id, section_id,
                settings.themes_dir, row["file_path"],
                full, full.exists(),
                parent, parent_exists, parent_is_dir,
                sibling_names,
            )
            raise HTTPException(
                status_code=410,
                detail="canonical recorded but missing on disk (dlBroken)",
            )
        # v1.15.123: sniff the actual file format. yt-dlp + ffmpeg
        # SHOULD produce a real MP3 for both YouTube and SoundCloud
        # sources, but the user reported a SoundCloud-source theme
        # whose <audio> element rendered 0:00 / 0:00 (browser
        # couldn't decode). If the postprocessor silently left an
        # opus/m4a/webm container with an .mp3 filename, serving
        # `audio/mpeg` Content-Type tells the browser to decode as
        # MP3 — which fails for non-MP3 bytes.
        #
        # Read the first 12 bytes to detect actual format:
        #   ID3 / 0xFF 0xFB (or FA/F3) — real MP3 → audio/mpeg
        #   OggS                         — Ogg/Opus → audio/ogg
        #   fLaC                         — FLAC     → audio/flac
        #   ftyp                         — MP4/M4A  → audio/mp4
        # Default falls back to audio/mpeg so existing-working
        # files keep working.
        media_type_header = "audio/mpeg"
        try:
            with full.open("rb") as fh:
                head = fh.read(12)
            if head.startswith(b"OggS"):
                media_type_header = "audio/ogg"
            elif head.startswith(b"fLaC"):
                media_type_header = "audio/flac"
            elif len(head) >= 8 and head[4:8] == b"ftyp":
                media_type_header = "audio/mp4"
            elif head.startswith(b"ID3") or (
                len(head) >= 2 and head[0] == 0xFF
                and head[1] in (0xFB, 0xFA, 0xF3, 0xE3)
            ):
                media_type_header = "audio/mpeg"
            else:
                # Unknown header — log + fall through to audio/mpeg.
                # The operator can grep this line + run `file` on
                # the path to diagnose.
                log.warning(
                    "theme.mp3 has unrecognized header for "
                    "%s/%s section=%s path=%s head=%r — "
                    "serving as audio/mpeg by default",
                    media_type, tmdb_id, section_id, full, head,
                )
        except OSError as e:
            log.warning(
                "theme.mp3 header sniff failed for %s/%s: %s",
                media_type, tmdb_id, e,
            )
        return FileResponse(full, media_type=media_type_header,
                            headers={"Cache-Control": "no-store"})

    @app.get("/api/items/{media_type}/{tmdb_id}/recovery-options")
    async def api_recovery_options(
        media_type: MediaType, tmdb_id: int,
        section_id: str | None = None,
        # v1.22.71: the clicked row's rk pins the representative-rk
        # resolution below to THIS edition/section.
        rating_key: str | None = None,
        db: Path = Depends(get_db_path),
    ):
        """v1.12.71: structured recovery checklist for a failed row.

        Returns a list of options ranked by likelihood of fixing the
        specific failure_kind, each with a label, tooltip, action
        keyword that the frontend can map to existing handlers, and
        a tone color to match motif's source palette. The ordering
        reflects "try this first" — e.g., for VIDEO_PRIVATE the
        most-likely fix is SET URL (find a different YouTube source);
        ACK FAILURE is always last because it dismisses without
        fixing.

        Powers the INFO card's // TRY THIS NEXT section so the user
        gets concrete next steps for each failure kind instead of
        the generic "Recover via SET URL, UPLOAD MP3, or drop a
        sidecar and ADOPT" copy that previously lived in the row's
        tdb-pill tooltip.
        """
        with get_conn(db) as conn:
            # v1.19.40: SELECT widened to include youtube_url so the
            # v1.19.35 synthesized BK-state override carries a real
            # URL (was always None — themes.youtube_url wasn't
            # fetched). Audit finding #9 from the post-v1.19.32
            # deep audit pass — the synthetic override at line ~16230
            # read `row["youtube_url"]` with a graceful fallback
            # that always fell back. Fix lets a future JS consumer
            # display the staged URL alongside the BACKUP READY
            # banner if needed.
            row = conn.execute(
                "SELECT failure_kind, failure_message, failure_acked_at, "
                "       upstream_source, youtube_url FROM themes "
                "WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            if row is None:
                raise HTTPException(status_code=404, detail="theme not found")
            # v1.13.54: per-section ack lookup. When the caller
            # passes section_id (info card always does for v1.13.34+),
            # an entry in section_failure_acks for THIS section
            # counts as acked even if the title-global flag is
            # still NULL. Mirrors the library SQL's
            # `COALESCE(sfa.acked_at, t.failure_acked_at)` derivation.
            section_acked_at = None
            if section_id:
                sa_row = conn.execute(
                    "SELECT acked_at FROM section_failure_acks "
                    "WHERE media_type = ? AND tmdb_id = ? AND section_id = ?",
                    (media_type, tmdb_id, section_id),
                ).fetchone()
                if sa_row:
                    section_acked_at = sa_row["acked_at"]
            effective_acked_at = section_acked_at or row["failure_acked_at"]
            # v1.12.71: resolve a representative rating_key so the
            # recovery buttons that need one (SET URL, UPLOAD MP3)
            # can wire up via the existing per-rating_key endpoints.
            # Picks the first plex_items row matching this title;
            # NULL if the row isn't currently in any Plex section
            # (e.g., after the Plex section was removed).
            # v0.51.47 (info-card audit): `else media_type` (was `else "movie"`) so a
            # COLLECTION maps to plex_items.media_type='collection', not 'movie' —
            # the wrong map made all three rk-pick queries (incl. the clicked-rk one)
            # miss a collection's row, so rating_key came back None and the
            # SET URL / UPLOAD MP3 recovery buttons couldn't wire up. Matches api_item.
            plex_mt = "show" if media_type == "tv" else media_type
            # v1.22.71: honor the clicked row's rk (validated against this
            # title), then a section-scoped pick. Pre-fix the unscoped
            # LIMIT 1 could hand SET URL / UPLOAD MP3 a sibling section's
            # (or edition's) rating_key on multi-section titles.
            rk_row = None
            if rating_key:
                rk_row = conn.execute(
                    "SELECT rating_key FROM plex_items "
                    "WHERE rating_key = ? AND guid_tmdb = ? "
                    "  AND media_type = ?",
                    (rating_key, tmdb_id, plex_mt),
                ).fetchone()
            if rk_row is None and section_id:
                rk_row = conn.execute(
                    "SELECT rating_key FROM plex_items "
                    "WHERE guid_tmdb = ? AND media_type = ? "
                    "  AND section_id = ? "
                    "LIMIT 1",
                    (tmdb_id, plex_mt, section_id),
                ).fetchone()
            if rk_row is None:
                rk_row = conn.execute(
                    "SELECT rating_key FROM plex_items "
                    "WHERE guid_tmdb = ? AND media_type = ? "
                    "LIMIT 1",
                    (tmdb_id, plex_mt),
                ).fetchone()
            rating_key = rk_row["rating_key"] if rk_row else None
            # v1.13.33: detect "locally resolved" state — the TDB URL is
            # dead but the user has worked around it with a local source
            # (ADOPT / SET URL / UPLOAD MP3) and motif's canonical is
            # in place. The recovery section should reflect that the
            # row is no longer broken from the user's perspective: no
            # need to push more recovery actions, just acknowledge the
            # workaround and note that a future TDB sync that revives
            # the URL will surface a UPDATE pill.
            # v1.13.35: when the caller passes section_id (info card
            # always does for v1.13.34+), pin the local_files lookup
            # to that section. Pre-fix the lookup was title-global
            # (just media_type + tmdb_id), so a 4K-only adopt on a
            # multi-section title incorrectly flipped the standard
            # section's info card to RESOLVED VIA ADOPT — same v18
            # cross-section bleed class the schema redesign was meant
            # to close. Falls back to the title-global lookup when
            # section_id is omitted (legacy callers / unscoped views)
            # since refusing to resolve is worse than maybe-cross-
            # section in that case.
            if section_id:
                # v1.24.17 (edition sweep #4): scope to the CLICKED edition.
                # Pre-fix the section-only LIMIT 1 returned an arbitrary sibling
                # on a multi-edition title, so 'RESOLVED VIA {source}' could show
                # the wrong edition's source_kind — or mark the row resolved when
                # the clicked edition isn't, hiding its recovery actions. Mirrors
                # the audio endpoint (v1.21.90) / api_item (v1.21.68): prefer the
                # edition's own row, fall back to the shared '' standard row.
                _rec_edition = (edition_key_for_rating_key(conn, rating_key)
                                if rating_key else None)
                if _rec_edition is not None:
                    local = conn.execute(
                        "SELECT source_kind, file_path FROM local_files "
                        "WHERE media_type = ? AND tmdb_id = ? "
                        "  AND section_id = ? "
                        "  AND edition_key IN (?, '') "
                        "  AND file_path IS NOT NULL "
                        "ORDER BY (edition_key = ?) DESC LIMIT 1",
                        (media_type, tmdb_id, section_id,
                         _rec_edition, _rec_edition),
                    ).fetchone()
                else:
                    local = conn.execute(
                        "SELECT source_kind, file_path FROM local_files "
                        "WHERE media_type = ? AND tmdb_id = ? "
                        "  AND section_id = ? "
                        "  AND file_path IS NOT NULL "
                        "LIMIT 1",
                        (media_type, tmdb_id, section_id),
                    ).fetchone()
            else:
                local = conn.execute(
                    "SELECT source_kind, file_path FROM local_files "
                    "WHERE media_type = ? AND tmdb_id = ? "
                    "  AND file_path IS NOT NULL "
                    "LIMIT 1",
                    (media_type, tmdb_id),
                ).fetchone()
            local_source = local["source_kind"] if local else None
            locally_resolved = bool(
                local
                and local_source in ("adopt", "url", "upload")
            )
            # v1.18.81: surface user_overrides on the recovery-options
            # response. v1.18.77 added the intent column + v1.18.78
            # added frontend branches that key on `data.override.intent
            # === 'backup'` to swap the section title to "✓ BACKUP READY
            # — DEFERRING TO PLEX" and render // PROMOTE TO ACTIVE.
            # But api_recovery_options never returned `override` — the
            # frontend was reading an always-undefined field. The
            # banner + button never appeared on real installs despite
            # the DB writes being correct. Class-9 contract-drift: the
            # v1.18.78 test asserted the JS conditional's source-text
            # shape without exercising the actual data plumbing
            # through this endpoint. Section-scoped lookup mirrors
            # api_item:11772-11796 — per-section first, '' global
            # fallback. The any-section LIMIT 1 fallback survives
            # only when section_id is omitted.
            ovr = None
            if section_id:
                ovr = conn.execute(
                    "SELECT * FROM user_overrides "
                    "WHERE media_type = ? AND tmdb_id = ? "
                    "  AND section_id = ?",
                    (media_type, tmdb_id, section_id),
                ).fetchone()
                if ovr is None:
                    ovr = conn.execute(
                        "SELECT * FROM user_overrides "
                        "WHERE media_type = ? AND tmdb_id = ? "
                        "  AND section_id = ''",
                        (media_type, tmdb_id),
                    ).fetchone()
            else:
                ovr = conn.execute(
                    "SELECT * FROM user_overrides "
                    "WHERE media_type = ? AND tmdb_id = ? "
                    "  AND section_id = ''",
                    (media_type, tmdb_id),
                ).fetchone()
                if ovr is None:
                    ovr = conn.execute(
                        "SELECT * FROM user_overrides "
                        "WHERE media_type = ? AND tmdb_id = ? "
                        "ORDER BY section_id LIMIT 1",
                        (media_type, tmdb_id),
                    ).fetchone()
            # v1.13.44: detect smart TRY NEXT options for failed-
            # download rows where motif has no canonical but Plex
            # has something we can lean on. Two cases:
            #   M-available: a theme.mp3 sits at the Plex folder
            #     that motif didn't place — adoptable in one click.
            #   P-available: Plex serves an independent theme
            #     (cloud / themerr-plex embed) per the v1.13.38
            #     plex_independent_theme column — purging motif's
            #     tracking lets Plex's theme keep playing.
            # Both options ack the failure as part of the action so
            # the user doesn't have to chase a separate ACK button.
            m_available = False
            p_available = False
            # v1.19.7: initialize `state` to None up-front so the
            # later `if state:` check at the motif_has_content block
            # below resolves cleanly when rating_key is None (theme
            # has no plex_items row — e.g., post-section-removal or
            # un-discovered title). Pre-fix the inner assignment
            # only fired inside `if rating_key:`, so the outer
            # reference raised UnboundLocalError → /api/recovery-
            # options returned 500 for any rk-less theme. Crash
            # observed in the user's 2026-05-24 docker logs:
            # `UnboundLocalError: cannot access local variable
            # 'state' where it is not associated with a value`.
            state = None
            if rating_key:
                state = conn.execute(
                    "SELECT pi.local_theme_file, pi.plex_independent_theme, "
                    "       pi.section_id "
                    "FROM plex_items pi WHERE pi.rating_key = ?",
                    (rating_key,),
                ).fetchone()
                if state:
                    if state["local_theme_file"] == 1:
                        # Sidecar exists at the Plex folder. M is
                        # only meaningful when motif DIDN'T place it
                        # — otherwise this is just our own file and
                        # there's nothing to adopt. Check placements.
                        # v1.14.32: switched from `WHERE plex_rating_key
                        # = ?` to the placements PK (media_type,
                        # tmdb_id, section_id). The plex_rating_key
                        # column is set ONLY by the place worker
                        # (worker.py:1554) and stays NULL on rows
                        # adopted via /adopt-sidecar. Pre-fix, an
                        # already-adopted row's placement existed but
                        # was invisible to this query → m_available
                        # stayed True → ADOPT + LET PLEX SERVE option
                        # appeared on rows where there's nothing
                        # left to adopt. the user's repro: an A-row
                        # showing both LET PLEX SERVE and ADOPT + LET
                        # PLEX SERVE in TRY THIS NEXT.
                        pi_section = state["section_id"]
                        placement = conn.execute(
                            "SELECT 1 FROM placements "
                            "WHERE media_type = ? AND tmdb_id = ? "
                            "  AND section_id = ?",
                            (media_type, tmdb_id, pi_section),
                        ).fetchone()
                        m_available = placement is None
                    p_available = (state["plex_independent_theme"] == 1)
            # v1.13.74: surface REVERT TO USER URL as a recovery
            # option when a previous_url snapshot of kind='url'
            # exists (the user had a working user URL before they
            # did REPLACE-W-TDB / SET URL-to-TDB). One click brings
            # back the known-good URL — strictly less work than
            # SET URL again. Skipped when no per-section snapshot
            # is available (legacy state, or no prior override).
            prev_row = _load_previous_url(
                conn, media_type, tmdb_id, section_id=section_id,
            )
            # previous_urls.kind is constrained to ('user','themerrdb')
            # — note: 'user' (the override SOURCE), NOT 'url' (the
            # local_files.source_kind value). Easy to confuse since
            # the row pill is U.
            revert_to_user_available = bool(
                prev_row and prev_row["kind"] == "user"
                and prev_row["youtube_url"]
            )
            revert_target_url = (
                prev_row["youtube_url"] if revert_to_user_available else None
            )
            # v1.14.61: deleted the v1.14.42/v1.14.44 `is_lps` +
            # `motif_has_placement` derivation. Both variables
            # were consumed only by the v1.14.40 no-fail branch
            # of TRY THIS NEXT, which v1.14.47 emptied — leaving
            # the per-section `placements` SELECT here as a
            # pure-dead-provision SQL roundtrip on every INFO-card
            # open. Audit follow-up after v1.14.59 caught it; the
            # v1.14.55 M5 dropped finding had verified the
            # no-consumption side but didn't delete the dead
            # producer. The `_row_matches_pl` is_lps at
            # api.py:2028 is a separate per-row computation
            # unrelated to this function.
        # v1.14.40: is_orphan moved up from the failure-recipe block
        # (used to live just before `recipes:`) so the v1.14.40 LPS
        # branch can read it for the RE-DOWNLOAD FROM TDB gating.
        # The failure-recipe block below still references the same
        # variable.
        is_orphan = row["upstream_source"] == "plex_orphan"
        kind = row["failure_kind"]
        if not kind:
            # v1.14.47: TRY THIS NEXT becomes failure-only. Per
            # the user's UX principle: "TRY THIS NEXT is for error
            # states where the user needs context; intentional /
            # optional actions belong in the SOURCE menu". For
            # non-failure rows the section now disappears entirely
            # (hydrateRecoveryOptions removes it when options is
            # empty).
            #
            # All non-failure actions previously surfaced here have
            # SOURCE-menu equivalents:
            #   • LET PLEX SERVE → SOURCE menu (v1.14.47)
            #   • ADOPT + LET PLEX SERVE → SOURCE menu (v1.14.47)
            #   • DOWNLOAD TDB BACKUP → SOURCE menu (v1.14.45)
            #   • PUSH MOTIF'S THEME → PLACE menu's PUSH TO PLEX
            #     (gated `themed && downloaded && !placed && !
            #     dlBroken` which IS the LPS state)
            #   • REVERT TO USER URL → SOURCE menu UNDO section
            #   • RE-DOWNLOAD FROM TDB → SOURCE menu (gate
            #     relaxed in v1.14.47 to allow LPS rows)
            #
            # The pre-v1.14.47 option-building block (v1.13.47 +
            # v1.14.27 + v1.14.40 + v1.14.45 layers) is intact in
            # git history (last seen in v1.14.46) for archaeology.
            # The is_lps / motif_has_placement / m_available /
            # p_available derivations above stay in scope for
            # potential future use; not removed because the
            # response shape still references them implicitly via
            # rating_key resolution.
            # v1.19.35: BK-state detection. After v1.19.32 ACCEPT
            # UPDATE on a P-row OR v1.19.33 REVERT on a P-row, the
            # row's failure_kind is cleared but it sits in a
            # backup-only state (local_files row with
            # last_place_attempt_reason='backup_only', no placement,
            # Plex serves its own theme). The v1.18.77 BACKUP READY
            # banner + PROMOTE TO ACTIVE button need to surface so
            # the user can deploy the backup. Pre-fix this whole
            # branch returned options=[] with no override hint, the
            # JS removed the recovery section, and PROMOTE was
            # unreachable from the info card (the row's PLACE menu
            # still had PUSH TO PLEX but the v1.18.77 banner UX
            # was inconsistent — fixed audit finding #8).
            # The outer `with get_conn(db) as conn:` block has
            # closed by here (it ends a few lines above at indent
            # column 8). Open a fresh read connection for the BK
            # probe so we don't ProgrammingError on a closed handle.
            section_for_bk = section_id or ""
            with get_conn(db) as bk_conn:
                bk_local = bk_conn.execute(
                    "SELECT file_path, source_kind, source_video_id "
                    "FROM local_files "
                    "WHERE media_type = ? AND tmdb_id = ? "
                    "  AND section_id = ? "
                    "  AND last_place_attempt_reason = 'backup_only'",
                    (media_type, tmdb_id, section_for_bk),
                ).fetchone()
                bk_placement_exists = bk_conn.execute(
                    "SELECT 1 FROM placements "
                    "WHERE media_type = ? AND tmdb_id = ? "
                    "  AND section_id = ? LIMIT 1",
                    (media_type, tmdb_id, section_for_bk),
                ).fetchone() is not None
            is_bk_state = bool(bk_local) and not bk_placement_exists
            # Synthesize override.intent='backup' so the JS branches
            # fire. Carry through the real user_overrides row if one
            # exists (REVERT-restored P-row case); else fabricate a
            # minimal shape using the themes.youtube_url anchor
            # (ACCEPT UPDATE P-row case, where user_overrides was
            # DELETEd by the accept handler).
            # v1.19.40: `synthetic: True` marker has a JS consumer
            # since v1.19.39 — app.js hydrateRecoveryOptions reads
            # `data.override.synthetic` to branch the PROMOTE TO
            # ACTIVE tooltip ("force-place its downloaded copy"
            # vs "force-place your URL"). Pre-v1.19.39 the marker
            # was dead documentation; now it's load-bearing.
            bk_override = None
            if is_bk_state:
                if ovr:
                    bk_override = dict(ovr)
                    bk_override["intent"] = "backup"
                    # v1.19.43: source_kind passthrough on the
                    # carry-through branch too — user_overrides has
                    # no source_kind column, so we lift it from
                    # bk_local where the BK signal lives. The JS
                    # PROMOTE tooltip needs this regardless of
                    # whether the row's override was real or
                    # synthesized.
                    bk_override["source_kind"] = bk_local["source_kind"]
                else:
                    bk_override = {
                        "media_type": media_type,
                        "tmdb_id": tmdb_id,
                        "section_id": section_for_bk,
                        # v1.19.40: themes SELECT widened (see above)
                        # so this now resolves to a real URL instead
                        # of always None.
                        "youtube_url": (
                            row["youtube_url"]
                            if "youtube_url" in row.keys() else None
                        ),
                        "intent": "backup",
                        "synthetic": True,
                        # v1.19.43: source_kind passthrough so the
                        # JS PROMOTE TO ACTIVE tooltip can branch on
                        # 'plex_cloud' and emit the v1.18.36
                        # re-upload-trick-specific phrasing. Without
                        # this the cloud-backup row would inherit
                        # the generic "force-place its downloaded
                        # copy" tooltip — accurate but doesn't
                        # surface the round-trip detail users will
                        # ask about ("how does motif put it back?").
                        "source_kind": (
                            bk_local["source_kind"]
                            if bk_local is not None else None
                        ),
                    }
            return {"failure_kind": None,
                    # v1.13.50: keep failure_message in the shape
                    # so consumers (frontend + future tests) don't
                    # see undefined for one branch and a string
                    # for the other.
                    "failure_message": None,
                    # v1.14.47: empty by design — see comment block above.
                    "options": [],
                    "human": None, "needs_manual_override": False,
                    "resolved": False, "resolved_via": None,
                    "rating_key": rating_key,
                    "acked": False,
                    # v1.19.35: override + backup_state hint for the
                    # JS to render the v1.18.77 banner + PROMOTE
                    # TO ACTIVE button on BK rows even without a
                    # failure_kind to anchor the section.
                    "override": bk_override,
                    "backup_state": is_bk_state,
                    # v1.19.35: theme (mt, tmdb) so the JS PROMOTE
                    # button's data-mt/data-id don't fall back to
                    # the always-undefined `data.theme` shape (the
                    # v1.18.77 phantom-fix sub-pattern bug). Pass
                    # them through deliberately rather than relying
                    # on the JS to read from function parameters
                    # (those agree but redundancy is safer here).
                    "theme": {
                        "media_type": media_type,
                        "tmdb_id": tmdb_id,
                    }}
        # Static recipe per FailureKind. Each entry is (action,
        # label, tooltip, priority, tone). Frontend renders these
        # as buttons that call into the existing per-action
        # handlers — `action` is the same string as the SOURCE menu
        # data-act attribute so the click dispatch is shared.
        cookies_present = bool(
            settings.cookies_file and settings.cookies_file.is_file()
        )
        # v1.14.40: is_orphan moved up above the no-fail branch so
        # the LPS RE-DOWNLOAD FROM TDB gate can read it. See marker
        # at the start of `if not kind:`.
        # v1.15.24: MARK ALIVE recovery option — operator-asserted
        # "URL works in browser, override yt-dlp's verdict". Same
        # priority slot (8) across recipes so the position in the
        # TRY THIS NEXT card stays consistent: just above ACK
        # FAILURE (which acknowledges-without-clearing). Tone
        # "cookies" (yellow) reads as operator override / config
        # style, distinct from danger-red ACK. the user's
        # KWXXC228g24 case: row stuck as video_removed from a
        # prior probe that misclassified an anti-bot response;
        # current probes return UNKNOWN (correctly indeterminate)
        # so REPROBE FAILURES never clears it. MARK ALIVE is the
        # explicit "trust me, I checked" override path.
        _MARK_ALIVE_OPT = {
            "action": "mark-alive", "label": "MARK URL ALIVE",
            "tooltip": (
                "Verified in a browser? Clear the failure flag "
                "(overrides yt-dlp's verdict). Use when the row is "
                "stuck on a stale failure_kind from a prior anti-"
                "bot misclassification."
            ),
            # v1.15.34: tone changed from "cookies" (yellow) to
            # "magenta". the user: yellow grouped MARK ALIVE
            # visually with FIX COOKIES (also yellow), but the
            # two actions have very different semantics — FIX
            # COOKIES is a config repair, MARK ALIVE is an
            # operator override that can mask a real dead URL.
            # Magenta separates them so muscle-memory clicks on
            # one don't accidentally fire the other.
            "priority": 8, "tone": "magenta",
            "interactive": True,
        }
        recipes: dict[str, list[dict]] = {
            "cookies_expired": [
                # v1.15.17: FIX COOKIES is now an actionable button
                # (interactive=True, action="fix-cookies-link") that
                # navigates to /settings#paths where the cookies.txt
                # field + // TEST COOKIES button live. Pre-fix this
                # was an info tile (interactive=False) — visually
                # styled but not clickable, requiring the operator
                # to manually navigate. Tone "cookies" (yellow)
                # matches the row pill + topbar chip + STATUS filter.
                {"action": "fix-cookies-link", "label": "FIX COOKIES",
                 "tooltip": "Drop a cookies.txt at /config and run // TEST COOKIES (Settings → PATHS).",
                 "priority": 1, "tone": "cookies",
                 "interactive": True},
                {"action": "redl", "label": "RE-DOWNLOAD",
                 "tooltip": "Retry with the current cookies file.",
                 "priority": 2, "tone": "themerrdb",
                 "interactive": True,
                 "disabled": not cookies_present,
                 "disabled_reason": "no cookies.txt at the configured path"},
                {"action": "manual-url", "label": "SET URL",
                 "tooltip": "Provide a non-cookie-walled YouTube URL.",
                 "priority": 3, "tone": "user",
                 "interactive": True},
                {"action": "upload-theme", "label": "UPLOAD MP3",
                 "tooltip": "Skip YouTube — upload your own MP3 file.",
                 "priority": 4, "tone": "user",
                 "interactive": True},
                # v1.15.17: ACK FAILURE in cookies tone (yellow)
                # rather than the danger-red used by dead-URL kinds.
                # Cookies-needed isn't a permanent loss — acking
                # just dismisses the count signal until the next
                # probe / download tries again. Distinct color
                # reinforces "this is a config issue, not a broken
                # URL." the user v1.15.16 planning: "ack failure with
                # the color of the cookies issue since it's not the
                # same kind of failure".
                {"action": "clear-failure", "label": "ACK FAILURE",
                 "tooltip": "Dismiss from the COOKIES count. Re-fires on next failure.",
                 "priority": 9, "tone": "cookies",
                 "interactive": True},
            ],
            "video_private": [
                {"action": "manual-url", "label": "SET URL",
                 "tooltip": "Provide a different YouTube URL — the original is private.",
                 "priority": 1, "tone": "user",
                 "interactive": True},
                {"action": "upload-theme", "label": "UPLOAD MP3",
                 "tooltip": "Upload your own MP3 file.",
                 "priority": 2, "tone": "user",
                 "interactive": True},
                _MARK_ALIVE_OPT,  # v1.15.24
                {"action": "clear-failure", "label": "ACK FAILURE",
                 "tooltip": "Dismiss from the FAIL count. TDB ✗ pill stays.",
                 "priority": 9, "tone": "danger",
                 "interactive": True},
            ],
            "video_removed": [
                {"action": "manual-url", "label": "SET URL",
                 "tooltip": "Provide a different YouTube URL — the original was removed.",
                 "priority": 1, "tone": "user",
                 "interactive": True},
                {"action": "upload-theme", "label": "UPLOAD MP3",
                 "tooltip": "Upload your own MP3 file.",
                 "priority": 2, "tone": "user",
                 "interactive": True},
                _MARK_ALIVE_OPT,  # v1.15.24 — the user's KWXXC228g24 case
                {"action": "clear-failure", "label": "ACK FAILURE",
                 "tooltip": "Dismiss from the FAIL count. TDB ✗ pill stays.",
                 "priority": 9, "tone": "danger",
                 "interactive": True},
            ],
            "video_age_restricted": [
                {"action": "info", "label": "DROP cookies.txt",
                 "tooltip": "Drop an age-verified cookies.txt so yt-dlp can sign in.",
                 "priority": 1, "tone": "info",
                 "interactive": False},
                {"action": "manual-url", "label": "SET URL",
                 "tooltip": "Provide a non-age-restricted YouTube alternative.",
                 "priority": 2, "tone": "user",
                 "interactive": True},
                {"action": "upload-theme", "label": "UPLOAD MP3",
                 "tooltip": "Skip YouTube — upload your own MP3 file.",
                 "priority": 3, "tone": "user",
                 "interactive": True},
            ],
            "geo_blocked": [
                {"action": "manual-url", "label": "SET URL",
                 "tooltip": "Provide a YouTube URL that's available in your region.",
                 "priority": 1, "tone": "user",
                 "interactive": True},
                {"action": "upload-theme", "label": "UPLOAD MP3",
                 "tooltip": "Skip YouTube — upload your own MP3 file.",
                 "priority": 2, "tone": "user",
                 "interactive": True},
                {"action": "clear-failure", "label": "ACK FAILURE",
                 "tooltip": "Dismiss from the FAIL count. TDB ✗ pill stays.",
                 "priority": 9, "tone": "danger",
                 "interactive": True},
            ],
            "network_error": [
                {"action": "redl", "label": "RE-DOWNLOAD",
                 "tooltip": "Retry — network errors are usually transient.",
                 "priority": 1, "tone": "themerrdb",
                 "interactive": True},
                {"action": "manual-url", "label": "SET URL",
                 "tooltip": "If retries keep failing, the URL may be dead — try a different one.",
                 "priority": 2, "tone": "user",
                 "interactive": True},
                _MARK_ALIVE_OPT,  # v1.15.24
                {"action": "clear-failure", "label": "ACK FAILURE",
                 "tooltip": "Dismiss from the FAIL count. Re-fires on next failure.",
                 "priority": 9, "tone": "info",
                 "interactive": True},
            ],
            "unknown": [
                {"action": "redl", "label": "RE-DOWNLOAD",
                 "tooltip": "Retry — unknown errors are sometimes transient.",
                 "priority": 1, "tone": "themerrdb",
                 "interactive": True},
                {"action": "manual-url", "label": "SET URL",
                 "tooltip": "Provide a different YouTube URL.",
                 "priority": 2, "tone": "user",
                 "interactive": True},
                {"action": "upload-theme", "label": "UPLOAD MP3",
                 "tooltip": "Upload your own MP3 file.",
                 "priority": 3, "tone": "user",
                 "interactive": True},
                _MARK_ALIVE_OPT,  # v1.15.24 — common case for anti-bot misclassifications
                {"action": "info", "label": "CHECK LOGS",
                 "tooltip": "Check LOGS for the raw yt-dlp error.",
                 "priority": 4, "tone": "info",
                 "interactive": False},
                {"action": "clear-failure", "label": "ACK FAILURE",
                 "tooltip": "Dismiss from the FAIL count.",
                 "priority": 9, "tone": "info",
                 "interactive": True},
            ],
        }
        humans = {
            "cookies_expired": "YouTube cookies missing or expired",
            "video_private": "Video is private",
            "video_removed": "Video was removed or deleted",
            "video_age_restricted": "Video is age-restricted",
            "geo_blocked": "Video is geo-blocked from your region",
            "network_error": "Network error reaching YouTube",
            "unknown": "Unknown error",
        }
        # v1.13.44: inject smart TRY NEXT actions for non-transient
        # failures where motif has a viable workaround on the Plex
        # side. We only add them for failures where the original
        # download isn't going to recover (network_error stays the
        # retry path — adopt/purge would mask a transient blip);
        # adopting an existing sidecar or letting Plex's own theme
        # serve are real fixes for video_removed / video_private /
        # video_age_restricted / geo_blocked. Both actions ack the
        # failure server-side as part of the dispatch so the user
        # gets a single-click resolution.
        SMART_KINDS = {"video_removed", "video_private",
                       "video_age_restricted", "geo_blocked", "unknown"}
        # v1.15.86: ADOPT EXISTING THEME is lifted out of the
        # not-acked gate. Pre-fix the smart-extras block (REVERT
        # / ADOPT / LET PLEX SERVE) was gated entirely on
        # `not effective_acked_at` — once the user acked the
        # failure, the recovery section showed only the static
        # recipe options (SET URL / UPLOAD MP3 / MARK URL ALIVE)
        # with the smart actions hidden. But ADOPT is a purely
        # additive recovery: it claims an existing sidecar
        # (M-row → A-row), it doesn't depend on the failure
        # alarm being live. the user on a M+failed-TDB+acked row:
        # "in the case of a movie that is a M row but also a
        # failed TDB red pill the options in the info card should
        # be to adopt as well, let's have the be the first
        # option and the normal adopt blue."
        # REVERT and LET PLEX SERVE stay gated on not-acked
        # because they actively transition the row's state
        # (REVERT switches to the saved user URL; LET PLEX SERVE
        # purges motif's tracking). ADOPT is the only purely
        # additive smart action — it's safe to surface always.
        if kind in SMART_KINDS and m_available:
            adopt_opt = {
                "action": "adopt-and-ack",
                "label": "ADOPT EXISTING THEME",
                # v1.13.59: tooltip pass — keep it short.
                "tooltip": (
                    "Adopt the theme.mp3 already at this "
                    "folder. Acks the failure too."
                ),
                "priority": 0,
                # v1.13.47: tone='adopt' matches the SOURCE-menu
                # ADOPT button (cyan) so the same logical action
                # reads identically across surfaces. Pre-fix
                # tone='user' rendered purple and made it look
                # like a different operation from the row-menu
                # ADOPT.
                "tone": "adopt",
                "interactive": True,
            }
        else:
            adopt_opt = None
        if kind in SMART_KINDS and not effective_acked_at:
            extra: list[dict] = []
            # v1.13.74: REVERT TO USER URL is the cheapest fix when a
            # previous_url snapshot of kind='url' exists — the user
            # already has a known-good URL stored from before the
            # REPLACE-W-TDB / SET URL-to-TDB attempt. Priority 0 so
            # it sorts ahead of SET URL / UPLOAD MP3 / smart TRY NEXT
            # extras. tone='user' matches the U source pill the
            # action restores. Truncated URL preview goes in the
            # tooltip so the user sees what they're reverting to
            # before clicking.
            if revert_to_user_available:
                preview = (revert_target_url[:60] + "…"
                           if len(revert_target_url) > 60
                           else revert_target_url)
                extra.append({
                    "action": "revert",
                    "label": "REVERT TO USER URL",
                    "tooltip": (
                        f"Restore your previous user URL ({preview}) "
                        "and re-download. One click — the URL is "
                        "already saved."
                    ),
                    "priority": 0,
                    "tone": "user",
                    "interactive": True,
                })
            # v1.15.86: ADOPT moved out of this gate to its own
            # always-injected block above. The append here is the
            # not-acked path; the post-gate prepend covers the
            # acked path.
            if adopt_opt is not None:
                extra.append(adopt_opt)
                adopt_opt = None
            # v1.15.5: gate LET PLEX SERVE on motif having something
            # to drop. Pre-fix the option appeared on pure-P rows
            # with no motif content (DL=off, PL=off) — the action
            # would just ack the failure since there's no canonical
            # or placement to purge, but the LABEL "LET PLEX SERVE"
            # implied a Plex transition that wasn't happening (Plex
            # was already serving). the user: "let plex server is an
            # option which doesn't make sense here since its already
            # a P row and let plex server would try to download the
            # themerrdb url and have a downloaded copy but let plex
            # server it's theme which is impossible on a failed url
            # or red tdb pill."
            #
            # The gate: only offer LET PLEX SERVE when motif owns
            # something (local_files or placements row in this
            # section). For pure-P rows the user gets ACK FAILURE
            # alone — semantically accurate (TDB URL is dead, Plex
            # already serves, just dismiss the failure flag).
            #
            # Uses a fresh `with get_conn(db) as conn:` block since
            # the outer one (used for the state + prev_row loads
            # above) has exited by the time we get here.
            motif_has_content = False
            if state:
                with get_conn(db) as motif_conn:
                    motif_state = motif_conn.execute(
                        "SELECT 1 FROM local_files "
                        "WHERE media_type = ? AND tmdb_id = ? "
                        "  AND section_id = ? "
                        "UNION ALL "
                        "SELECT 1 FROM placements "
                        "WHERE media_type = ? AND tmdb_id = ? "
                        "  AND section_id = ? "
                        "LIMIT 1",
                        (media_type, tmdb_id, state["section_id"],
                         media_type, tmdb_id, state["section_id"]),
                    ).fetchone()
                motif_has_content = motif_state is not None
            if p_available and motif_has_content:
                extra.append({
                    "action": "purge-and-ack",
                    "label": "LET PLEX SERVE",
                    # v1.13.59: tooltip pass — keep it short.
                    "tooltip": (
                        "Plex has its own track. Drop motif's "
                        "tracking + ack the failure; Plex keeps "
                        "playing."
                    ),
                    "priority": 0,
                    # v1.14.26: tone amber to match the Plex
                    # chip color the row transitions toward.
                    # See no_fail_options branch above.
                    "tone": "plex",
                    "interactive": True,
                })
            recipes[kind] = extra + recipes.get(kind, recipes["unknown"])
        # v1.15.86: acked-state ADOPT injection. The not-acked
        # branch above appended adopt_opt to `extra` and cleared
        # the variable. If we're on the acked path and adopt_opt
        # is still set, prepend it directly to the recipe list so
        # ADOPT EXISTING THEME shows even after the failure was
        # dismissed. the user's M+failed-TDB+acked scenario:
        # acking the failure shouldn't hide a still-valid recovery
        # opportunity (the sidecar at the Plex folder doesn't
        # disappear when the user clicks ACK).
        if adopt_opt is not None:
            recipes[kind] = [adopt_opt] + recipes.get(
                kind, recipes["unknown"])
        options = sorted(recipes.get(kind, recipes["unknown"]),
                         key=lambda o: o["priority"])
        # Orphans don't have a TDB record so RE-DOWNLOAD against
        # themes.youtube_url is meaningless. Filter it out for
        # plex_orphan rows so the user isn't pointed at a dead path.
        if is_orphan:
            options = [o for o in options if o["action"] != "redl"]
        # v1.12.88: filter ACK FAILURE out of the options when the
        # row is already acked. The user explicitly wants the recovery
        # context (failure kind + resolution paths like SET URL /
        # UPLOAD MP3) to remain visible after acking, but the ACK
        # button itself becomes redundant — the alarm is already
        # dismissed. Pre-fix clicking ACK closed the dialog and
        # required reopening to see the same recovery options.
        # v1.13.54: section ack also suppresses ACK FAILURE option.
        if effective_acked_at:
            options = [o for o in options if o["action"] != "clear-failure"]
        # v1.13.33: when the row is locally-resolved (TDB URL is dead
        # but the user has a working local source), drop the recovery
        # paths that would replace what's already working. Keep only
        # ACK FAILURE (when not yet acked) and add a non-interactive
        # tile that names the working source so the user sees clearly
        # "this row is fine, TDB just doesn't track it anymore."
        if locally_resolved:
            kept: list[dict] = []
            if not effective_acked_at:
                # ACK FAILURE remains useful — it dismisses the row
                # from the topbar FAIL counter. Surface it.
                ack = next((o for o in options
                            if o.get("action") == "clear-failure"), None)
                if ack:
                    kept.append(ack)
            # v1.14.18: tone now matches the SRC chip color of the
            # local source. Pre-fix every RESOLVED VIA banner used
            # `tone: 'user'` (violet) regardless of source — so an
            # adopted sidecar resolution showed in violet even
            # though the row's SRC chip is blue (A). Mapping:
            #   url    → user (violet, matches U chip)
            #   upload → user (violet, matches U chip — uploads
            #            land in local_files with source_kind='upload'
            #            and render as U per _SRC_LETTER_SQL)
            #   adopt  → adopt (blue, matches A chip)
            # Pulled from local_source which is the source_kind on
            # the local_files row driving the resolution.
            tone = "adopt" if local_source == "adopt" else "user"
            options = [
                {"action": "info",
                 "label": f"// RESOLVED VIA {local_source.upper()}",
                 # v1.13.59: tooltip pass — keep it short.
                 "tooltip": (
                     f"Playing your {local_source} copy. TDB URL "
                     "is dead — if it revives you'll see a TDB↑ pill."
                 ),
                 "priority": 1, "tone": tone,
                 "interactive": False},
                *kept,
            ]
        # v1.15.74: surface a separate `plex_resolved` flag for the
        # P-row-with-failed-TDB case. the user: "on rows that have
        # failed tbd red pill but have a theme being provided by
        # plex or +P Let's change the try this in the info card
        # since if the row is P but a failed red pill tdb you don't
        # really have to try anything next it would be optional."
        # Distinct from `resolved` (which means motif has a local
        # source) so the frontend can swap the section title to
        # "OPTIONAL UPGRADES" while keeping the option buttons
        # available (the user can still SET URL / FIX COOKIES /
        # etc. if they want a motif-managed theme).
        plex_resolved = bool(p_available and not locally_resolved)
        return {
            "failure_kind": kind,
            "failure_message": row["failure_message"],
            "human": humans.get(kind, kind),
            "needs_manual_override": kind in (
                "video_private", "video_removed",
                "video_age_restricted", "geo_blocked",
            ),
            "acked": bool(effective_acked_at),
            "rating_key": rating_key,
            # v1.13.33: locally_resolved + resolved_via let the
            # frontend re-skin the section header and suppress the
            # dead-URL preview at the top of the info card.
            "resolved": locally_resolved,
            "resolved_via": local_source if locally_resolved else None,
            "plex_resolved": plex_resolved,
            # v1.18.81: surface the section-scoped override so the
            # frontend's `data.override.intent === 'backup'` branches
            # actually have data to act on. Pre-v1.18.81 this was
            # always undefined → the BACKUP banner + PROMOTE TO ACTIVE
            # button never rendered, regardless of what user_overrides.
            # intent held. See the SELECT block above for full framing.
            "override": dict(ovr) if ovr else None,
            # v1.19.35: theme so the JS PROMOTE/MARK buttons get
            # real data-mt + data-id. Pre-fix the JS read
            # `data.theme?.media_type` which was never populated by
            # this endpoint → buttons got empty data attrs → click
            # 422'd on the /intent endpoint. The v1.18.77 cascade's
            # phantom-fix sub-pattern (v1.18.81 fixed the override
            # surface but the data.theme reference was an
            # adjacent silent bug — only behavioral testing finds
            # this class).
            "theme": {
                "media_type": media_type,
                "tmdb_id": tmdb_id,
            },
            "options": options,
        }

    @app.post("/api/items/{media_type}/{tmdb_id}/clear-failure")
    async def api_clear_failure(
        request: Request, media_type: MediaType, tmdb_id: int,
        section_id: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        """v1.10.50: acknowledge a failure without pretending it's gone.

        Sets themes.failure_acked_at = now() — the ! glyph and the
        FAILURES filter exclude the row, but the TDB pill keeps its
        red 'TDB ✗' (or amber 'TDB ⚠') so the user knows the
        upstream URL is still broken. failure_kind is preserved.

        The underlying URL stays dead until the next sync probe
        finds an updated one or the user provides a manual override.
        Future probes / downloads that produce a *different*
        failure_kind clear failure_acked_at so the user gets
        re-alerted on the new condition.

        v1.13.54: optional section_id scopes the ack to a single
        section. Pre-fix the chained `adopt-and-ack` /
        `purge-and-ack` flows fired this without a section_id and
        cleared the title-global flag — bleeding the dismissal
        across every section that owns the title. With section_id,
        the ack lands in `section_failure_acks` only; the global
        themes.failure_acked_at stays NULL until ALL sections that
        own the title have been individually acked. Without
        section_id (legacy callers / bulk path), the global flag
        is set as before.
        """
        _require_admin(request)
        with get_conn(db) as conn, transaction(conn):
            row = conn.execute(
                "SELECT failure_kind, failure_acked_at, title FROM themes "
                "WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            if row is None:
                raise HTTPException(status_code=404, detail="theme not found")
            if row["failure_kind"] is None:
                return {"ok": True, "no_op": True,
                        "note": "no failure to acknowledge"}
            if section_id:
                # v1.13.54: per-section ack. Insert / replace into
                # section_failure_acks. After the write, check
                # whether every section that owns this title has
                # been acked — if so, also stamp the title-global
                # flag so legacy reads (FAIL count, library SQL
                # paths that haven't been threaded for sections)
                # behave correctly.
                conn.execute(
                    """INSERT INTO section_failure_acks
                       (media_type, tmdb_id, section_id, acked_at, acked_by)
                       VALUES (?, ?, ?, ?, ?)
                       ON CONFLICT(media_type, tmdb_id, section_id) DO UPDATE SET
                           acked_at = excluded.acked_at,
                           acked_by = excluded.acked_by""",
                    (media_type, tmdb_id, section_id, now_iso(),
                     request.state.principal.username),
                )
                # Determine the set of sections owning this title.
                # Use plex_items as the authoritative answer (a row
                # exists per section). If plex_items is empty (e.g.
                # row hasn't been enumerated), fall back to
                # local_files / placements.
                # v0.51.48: else media_type (was "movie") so a collection's
                # owner-sections resolve from plex_items (media_type=
                # 'collection'), not an empty 'movie' set that skips the
                # title-global ack rollup.
                plex_mt = "show" if media_type == "tv" else media_type
                owner_sections = {
                    r["section_id"] for r in conn.execute(
                        "SELECT DISTINCT section_id FROM plex_items "
                        "WHERE media_type = ? AND guid_tmdb = ? "
                        "  AND section_id IS NOT NULL "
                        "  AND section_id != ''",
                        (plex_mt, str(tmdb_id)),
                    ).fetchall()
                }
                if not owner_sections:
                    owner_sections = {
                        r["section_id"] for r in conn.execute(
                            "SELECT DISTINCT section_id FROM local_files "
                            "WHERE media_type = ? AND tmdb_id = ?",
                            (media_type, tmdb_id),
                        ).fetchall()
                    }
                acked_sections = {
                    r["section_id"] for r in conn.execute(
                        "SELECT section_id FROM section_failure_acks "
                        "WHERE media_type = ? AND tmdb_id = ?",
                        (media_type, tmdb_id),
                    ).fetchall()
                }
                if owner_sections and owner_sections.issubset(acked_sections):
                    conn.execute(
                        "UPDATE themes SET failure_acked_at = ? "
                        "WHERE media_type = ? AND tmdb_id = ? "
                        "  AND failure_acked_at IS NULL",
                        (now_iso(), media_type, tmdb_id),
                    )
            else:
                # Legacy / bulk path — title-global ack only. Skip
                # the section_failure_acks write so the new table
                # only carries explicit per-section decisions.
                # v1.12.87: idempotent over the failure_acked_at flag —
                # always run the cancel sweep below even if the user has
                # ACKed before. Pre-fix the early no-op meant a second
                # ACK click after a stale-pending retry cycle produced
                # new failed jobs did NOT cancel them, so the topbar
                # stayed red. With the topbar now driven by themes (not
                # jobs) this is mostly belt-and-suspenders, but the
                # cleanup keeps the queue tidy and matches user intent
                # ("dismiss this and stop trying").
                conn.execute(
                    "UPDATE themes SET failure_acked_at = ? "
                    "WHERE media_type = ? AND tmdb_id = ? AND failure_acked_at IS NULL",
                    (now_iso(), media_type, tmdb_id),
                )
                # v1.13.81: bulk ack supersedes any earlier per-section
                # decisions on this title — drop orphan sfa rows so a
                # later themes.failure_acked_at clear (new failure
                # alert, future migration) doesn't resurrect stale
                # per-section dismissals as ghost acks. Audit P1 #3.
                conn.execute(
                    """DELETE FROM section_failure_acks
                       WHERE media_type = ? AND tmdb_id = ?""",
                    (media_type, tmdb_id),
                )
            # v1.12.74: also cancel the underlying failed download
            # job in the queue. Pre-fix the topbar dot stayed red
            # after ACK FAILURE because q.failed counted the
            # 'failed'-status job in jobs even though the row's
            # failure was dismissed. The user's intent in clicking
            # ACK is "I'm done with this failure" — that should
            # include the queued failed job that produced the
            # failure in the first place. Marking 'cancelled' (not
            # deleting) preserves the audit trail in LOGS.
            # v1.12.85: extend the cancel to status='pending' too.
            # Pre-fix a misclassified-as-transient failure (e.g.
            # "This video is not available" before .85 added the
            # pattern) cycled between pending → failed → pending via
            # the worker's backoff retry; ACK cleared the failed row
            # but the next retry put another in pending → failed,
            # so the topbar dot kept going red and the row's `!`
            # glyph kept reappearing. Cancelling pending too breaks
            # the cycle. Running jobs are left alone (cancel_requested
            # via /jobs/{id}/cancel is the cooperative path for those).
            conn.execute(
                """UPDATE jobs SET status = 'cancelled', finished_at = ?
                   WHERE job_type = 'download'
                     AND media_type = ? AND tmdb_id = ?
                     AND status IN ('pending', 'failed')""",
                (now_iso(), media_type, tmdb_id),
            )
            _record_audit(
                conn, actor=request.state.principal.username,
                action="ack_failure",
                media_type=media_type, tmdb_id=tmdb_id,
                section_id=section_id,
                details={"failure_kind": row["failure_kind"],
                         "scope": "section" if section_id else "title"},
            )
        log_event(db, level="INFO", component="api",
                  media_type=media_type, tmdb_id=tmdb_id,
                  section_id=section_id,
                  message=f"Failure acknowledged on '{row['title']}' "
                          f"by {request.state.principal.username}"
                          + (f" (section {section_id})" if section_id else ""),
                  detail={"failure_kind": row["failure_kind"]})
        return {"ok": True, "title": row["title"],
                "acked_kind": row["failure_kind"],
                "scope": "section" if section_id else "title"}

    @app.post("/api/items/{media_type}/{tmdb_id}/mark-alive")
    async def api_mark_alive(
        request: Request, media_type: MediaType, tmdb_id: int,
        db: Path = Depends(get_db_path),
    ):
        """v1.15.24: operator-asserted "URL is alive, override yt-dlp".

        the user: KWXXC228g24 (Rubble & Crew theme) shown as
        `failure_kind=video_removed` from a prior probe that
        misclassified a YouTube anti-bot response. Current probes
        return UNKNOWN/indeterminate (correctly — yt-dlp can't
        confirm alive without sometimes hitting anti-bot). The
        URL plays fine in a browser. Operator had no way to clear
        the stuck failure_kind — REPROBE FAILURES kept seeing
        UNKNOWN, single-row probe likewise. Stuck row.

        This endpoint is the explicit "trust me, I checked"
        override. Mirrors the alive-clear write block in
        api_probe_tdb (v1.14.49) — themes-level clear + DELETE
        from section_failure_acks so the FAIL count and ATTN
        axis stop lying about resolved state.

        Different from /clear-failure (ACK FAILURE) which
        ACKNOWLEDGES the failure (failure_acked_at = now) but
        keeps failure_kind set + the row's red TDB ✗ pill. ACK
        is "I'm aware, dismiss the count signal." MARK ALIVE is
        "the URL works, override the wrong classification."
        """
        _require_admin(request)
        def _mark_sync():
            with get_conn(db) as conn:
                row = conn.execute(
                    "SELECT failure_kind, title FROM themes "
                    "WHERE media_type = ? AND tmdb_id = ?",
                    (media_type, tmdb_id),
                ).fetchone()
                if row is None:
                    return {"_status": 404, "detail": "theme not found"}
                if row["failure_kind"] is None:
                    return {"ok": True, "no_op": True,
                            "title": row["title"],
                            "note": "row has no failure to clear"}
                # Same write block as api_probe_tdb's alive branch.
                # Title-global failure_kind + failure_acked_at clear,
                # then DELETE per-section sfa rows so the FAIL pill
                # + ATTN axis stop suppressing affected sections.
                with transaction(conn):
                    conn.execute(
                        """UPDATE themes
                              SET failure_kind = NULL,
                                  failure_message = NULL,
                                  failure_at = NULL,
                                  failure_acked_at = NULL
                            WHERE media_type = ?
                              AND tmdb_id = ?""",
                        (media_type, tmdb_id),
                    )
                    conn.execute(
                        """DELETE FROM section_failure_acks
                           WHERE media_type = ? AND tmdb_id = ?""",
                        (media_type, tmdb_id),
                    )
                    _record_audit(
                        conn,
                        actor=request.state.principal.username,
                        action="mark_alive",
                        media_type=media_type, tmdb_id=tmdb_id,
                        details={"prior_failure_kind": row["failure_kind"]},
                    )
                return {"ok": True, "title": row["title"],
                        "cleared_kind": row["failure_kind"]}
        out = await run_in_threadpool(_mark_sync)
        if "_status" in out:
            raise HTTPException(status_code=out["_status"], detail=out["detail"])
        if not out.get("no_op"):
            log_event(
                db, level="INFO", component="api",
                media_type=media_type, tmdb_id=tmdb_id,
                message=(
                    f"URL marked alive on '{out['title']}' "
                    f"by {request.state.principal.username} "
                    f"(was: {out['cleared_kind']})"
                ),
                detail={"prior_failure_kind": out["cleared_kind"]},
            )
        return out

    @app.post("/api/items/{media_type}/{tmdb_id}/ack-drop")
    async def api_ack_drop(
        request: Request, media_type: MediaType, tmdb_id: int,
        db: Path = Depends(get_db_path),
    ):
        """v1.13.1 (Phase C): clear themes.tdb_dropped_at without
        deleting the row. The local theme + placement stay as-is; the
        gray TDB◌ pill goes away; the topbar DROP badge decrements.
        Mirrors clear-failure's "I dealt with it" semantic.

        If TDB later re-publishes the item, normal sync upserts will
        also clear this flag automatically — ACK DROP is the manual
        path for users who don't want to wait."""
        _require_admin(request)
        with get_conn(db) as conn:
            row = conn.execute(
                "SELECT tdb_dropped_at, title FROM themes "
                "WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            if row is None:
                raise HTTPException(status_code=404, detail="theme not found")
            if row["tdb_dropped_at"] is None:
                return {"ok": True, "no_op": True,
                        "note": "no drop to acknowledge"}
            conn.execute(
                "UPDATE themes SET tdb_dropped_at = NULL "
                "WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            )
        log_event(db, level="INFO", component="api",
                  media_type=media_type, tmdb_id=tmdb_id,
                  message=f"TDB drop acknowledged on {row['title']!r} "
                          f"by {request.state.principal.username}")
        return {"ok": True, "title": row["title"]}

    @app.post("/api/items/{media_type}/{tmdb_id}/convert-to-manual")
    async def api_convert_to_manual(
        request: Request, media_type: MediaType, tmdb_id: int,
        section_id: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        """v1.13.1 (Phase C): take ownership of a dropped item by
        promoting its current themes.youtube_url into user_overrides
        — same shape SET URL produces. Result: SRC reclassifies from
        T → U (user's URL is now authoritative), tdb_dropped_at
        clears, and future syncs leave the row alone.

        section_id (optional) scopes the override to one section, like
        SET URL. When omitted, writes the global '' override row.
        """
        _require_admin(request)
        with get_conn(db) as conn, transaction(conn):
            row = conn.execute(
                "SELECT youtube_url, tdb_dropped_at, title FROM themes "
                "WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            if row is None:
                raise HTTPException(status_code=404, detail="theme not found")
            if not row["youtube_url"]:
                raise HTTPException(
                    status_code=400,
                    detail="theme has no youtube_url to promote",
                )
            target_section = section_id or ""
            now = now_iso()
            conn.execute(
                """INSERT INTO user_overrides
                       (media_type, tmdb_id, youtube_url,
                        set_at, set_by, note, section_id)
                   VALUES (?, ?, ?, ?, ?, ?, ?)
                   ON CONFLICT(media_type, tmdb_id, section_id, edition_key) DO UPDATE
                   SET youtube_url = excluded.youtube_url,
                       set_at      = excluded.set_at,
                       set_by      = excluded.set_by,
                       note        = excluded.note""",
                (media_type, tmdb_id, row["youtube_url"],
                 now, request.state.principal.username,
                 "promoted via CONVERT TO MANUAL after TDB drop",
                 target_section),
            )
            # Clear the drop flag — the row is now self-managed and
            # not subject to TDB drop tracking.
            conn.execute(
                "UPDATE themes SET tdb_dropped_at = NULL "
                "WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            )
        log_event(db, level="INFO", component="api",
                  media_type=media_type, tmdb_id=tmdb_id,
                  section_id=target_section or None,
                  message=f"Converted dropped {row['title']!r} to manual "
                          f"by {request.state.principal.username}")
        return {"ok": True, "title": row["title"],
                "section_id": target_section, "url": row["youtube_url"]}

    @app.post("/api/items/{media_type}/{tmdb_id}/redownload")
    async def api_redownload(
        request: Request, media_type: MediaType, tmdb_id: int,
        # v1.12.73: optional section_id scopes the re-download +
        # placement to one section. Without it, the download fans
        # out to every section that owns the title — wrong when
        # the user clicks DOWNLOAD/RE-DOWNLOAD TDB on a specific
        # row (4K vs standard) and only wants that one section
        # affected. Mirrors the v1.12.46 ACCEPT UPDATE / v1.12.47
        # REVERT scoping; per-section overrides (v1.12.72) need
        # this too so a per-edition theme isn't accidentally
        # re-downloaded into sibling sections that have their own
        # different URLs.
        section_id: str | None = Query(None),
        # v1.21.62 (C2c): scope the re-download to THIS edition's folder.
        rating_key: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        _require_admin(request)
        with get_conn(db) as conn, transaction(conn):
            _redl_edition = (edition_key_for_rating_key(conn, rating_key)
                             if rating_key else "")
            row = conn.execute(
                "SELECT title FROM themes WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            if row is None:
                raise HTTPException(status_code=404, detail="not in database")
            # Cancel any pending download for this item, then enqueue a fresh one.
            # v1.12.73: when section_id is provided, only cancel
            # jobs in that section so sibling-section downloads
            # the user isn't replacing keep running.
            # v1.21.82: ALSO scope to the resolved edition (matching the
            # _enqueue_download below) so re-downloading Extended doesn't
            # cancel a sibling edition's queued download in the same section.
            # jobs has no edition_key column — read it off the payload (v74
            # json_valid guard); a standard ('' ) job omits it -> COALESCE ''.
            if section_id:
                conn.execute(
                    """UPDATE jobs SET status = 'cancelled', finished_at = ?
                       WHERE job_type = 'download' AND media_type = ? AND tmdb_id = ?
                         AND section_id = ?
                         AND COALESCE(CASE WHEN json_valid(payload)
                             THEN json_extract(payload, '$.edition_key') END, '') = ?
                         AND status IN ('pending', 'failed')""",
                    (now_iso(), media_type, tmdb_id, section_id, _redl_edition),
                )
            else:
                conn.execute(
                    """UPDATE jobs SET status = 'cancelled', finished_at = ?
                       WHERE job_type = 'download' AND media_type = ? AND tmdb_id = ?
                         AND COALESCE(CASE WHEN json_valid(payload)
                             THEN json_extract(payload, '$.edition_key') END, '') = ?
                         AND status IN ('pending', 'failed')""",
                    (now_iso(), media_type, tmdb_id, _redl_edition),
                )
            # v1.12.47: RE-DOWNLOAD TDB / DOWNLOAD TDB (this
            # endpoint backs both labels) needs force_place=True
            # so the place job overwrites the existing
            # placement file. Pre-fix the place worker hit
            # skip_if_plex_has_theme and the new canonical
            # never reached Plex's folder — same Plex-cache bug
            # the v1.12.43 ACCEPT UPDATE fix solved.
            from ..core.sync import _enqueue_download
            n = _enqueue_download(
                conn, media_type=media_type, tmdb_id=tmdb_id,
                reason="manual",
                auto_place=True,
                force_place=True,
                only_section_id=section_id,
                edition_key=_redl_edition,
            )
            _record_audit(
                conn, actor=request.state.user, action="redownload",
                media_type=media_type, tmdb_id=tmdb_id,
                section_id=section_id,
                details={"sections_enqueued": n},
            )
        log_event(db, level="INFO", component="api",
                  media_type=media_type, tmdb_id=tmdb_id,
                  section_id=section_id,
                  message=f"Manual re-download requested by {request.state.user} "
                          f"({n} sections{', scoped to ' + section_id if section_id else ''})")
        return {"ok": True, "enqueued_sections": n}

    # v1.14.45: DOWNLOAD TDB BACKUP — sibling of /redownload but
    # WITHOUT auto-place. Use case: a pure-P row (Plex serves
    # its own theme, motif owns nothing) where the user wants a
    # local backup of TDB's theme without disturbing Plex's
    # serving copy. End state: motif has the canonical (DL=on),
    # no placement (PL=gray), LINK chip flips to PS because
    # plex_independent_theme=1 for the row + has-canonical + no
    # placement = the LPS state predicate. Same end-state visual
    # as the post-LET-PLEX-SERVE flow but reached via download
    # instead of unplace.
    #
    # Differs from /redownload in two ways:
    #   1. auto_place=False (the download lands a canonical;
    #      worker doesn't chain a place job)
    #   2. force_place=False (no need — there's no placement
    #      to overwrite)
    #
    # the user's design intent: "have a ThemerDB backup file in
    # downloads but also allow plex to have a theme, only would
    # be for options that are also in ThemerrDB."
    @app.post("/api/items/{media_type}/{tmdb_id}/download-backup")
    async def api_download_backup(
        request: Request, media_type: MediaType, tmdb_id: int,
        # v1.14.45: section_id required in practice — the action
        # is per-row from the library / INFO card. Optional here
        # for symmetry with /redownload + the legacy fan-out
        # behavior the helper supports.
        section_id: str | None = Query(None),
        # v1.21.62 (C2c): scope the backup download to THIS edition.
        rating_key: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        _require_admin(request)
        with get_conn(db) as conn, transaction(conn):
            _bk_edition = (edition_key_for_rating_key(conn, rating_key)
                           if rating_key else "")
            row = conn.execute(
                "SELECT title, upstream_source, youtube_url "
                "FROM themes WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            if row is None:
                raise HTTPException(status_code=404, detail="not in database")
            # v1.14.45: gate on TDB-tracked + URL set. plex_orphan
            # rows have no TDB to back up; rows with no URL can't
            # download. Fail clearly rather than enqueueing a
            # job that immediately fails.
            if row["upstream_source"] == "plex_orphan":
                raise HTTPException(
                    status_code=409,
                    detail="row is not TDB-tracked (plex_orphan); no TDB URL to back up",
                )
            if not row["youtube_url"]:
                raise HTTPException(
                    status_code=409,
                    detail="row has no TDB URL to back up",
                )
            # Cancel any pending download for this scope (mirror
            # the /redownload pattern — don't let a stale
            # download race the backup job).
            # v1.21.82: edition-scoped (matching the edition-keyed enqueue
            # below) so a backup of one edition doesn't cancel a sibling's
            # queued download. payload-derived edition_key (v74 guard).
            if section_id:
                conn.execute(
                    """UPDATE jobs SET status = 'cancelled', finished_at = ?
                       WHERE job_type = 'download' AND media_type = ? AND tmdb_id = ?
                         AND section_id = ?
                         AND COALESCE(CASE WHEN json_valid(payload)
                             THEN json_extract(payload, '$.edition_key') END, '') = ?
                         AND status IN ('pending', 'failed')""",
                    (now_iso(), media_type, tmdb_id, section_id, _bk_edition),
                )
            else:
                conn.execute(
                    """UPDATE jobs SET status = 'cancelled', finished_at = ?
                       WHERE job_type = 'download' AND media_type = ? AND tmdb_id = ?
                         AND COALESCE(CASE WHEN json_valid(payload)
                             THEN json_extract(payload, '$.edition_key') END, '') = ?
                         AND status IN ('pending', 'failed')""",
                    (now_iso(), media_type, tmdb_id, _bk_edition),
                )
            from ..core.sync import _enqueue_download
            n = _enqueue_download(
                conn, media_type=media_type, tmdb_id=tmdb_id,
                reason="manual_backup",
                # v1.14.45: the load-bearing pair — no auto-place,
                # no force-place. Worker downloads the canonical
                # only.
                auto_place=False,
                force_place=False,
                only_section_id=section_id,
                edition_key=_bk_edition,
            )
            _record_audit(
                conn, actor=request.state.user, action="download_backup",
                media_type=media_type, tmdb_id=tmdb_id,
                section_id=section_id,
                details={"sections_enqueued": n},
            )
            # v1.20.10: the blue !UPD pill is no longer cleared here. The
            # worker resolves the pending new_theme_available update on
            # DOWNLOAD SUCCESS (core.sync.resolve_new_theme_pending_update,
            # called from _record_local_file) so the pill reflects whether
            # motif actually holds the theme — a failed backup leaves it up.
        log_event(db, level="INFO", component="api",
                  media_type=media_type, tmdb_id=tmdb_id,
                  section_id=section_id,
                  message=(f"TDB backup download requested by "
                           f"{request.state.user} ({n} sections"
                           f"{', scoped to ' + section_id if section_id else ''})"))
        return {"ok": True, "enqueued_sections": n}

    @app.post("/api/items/{media_type}/{tmdb_id}/override")
    async def api_override(
        request: Request, media_type: MediaType, tmdb_id: int,
        db: Path = Depends(get_db_path),
    ):
        """Set or replace a manual YouTube URL override for one theme.

        Accepts either JSON body {"youtube_url": "...", "note": "..."} or
        legacy form-encoded fields (youtube_url, note). Side effects:
          - upsert into user_overrides
          - clear failure_kind / failure_message / failure_at on themes
            (we're overriding the broken upstream)
          - enqueue a download job; worker prefers user_overrides
        """
        _require_admin(request)
        # Accept JSON or form
        youtube_url: str = ""
        note: str = ""
        ctype = (request.headers.get("content-type") or "").lower()
        if "application/json" in ctype:
            try:
                body = await request.json()
            except Exception:
                raise HTTPException(status_code=400, detail="invalid JSON body")
            if not isinstance(body, dict):
                raise HTTPException(status_code=400, detail="body must be a JSON object")
            youtube_url = str(body.get("youtube_url") or "")
            note = str(body.get("note") or "")
        else:
            form = await request.form()
            youtube_url = str(form.get("youtube_url") or "")
            note = str(form.get("note") or "")
        if not youtube_url:
            raise HTTPException(status_code=400, detail="youtube_url is required")
        # v1.14.9: route canonicalization by source — same fix as
        # api_manual_url above. Pre-fix the SC URL got wrapped as
        # youtube.com/watch?v=sc-... and download failed at the YT
        # extractor. See api.py:6710 for the full root-cause writeup.
        src = url_source(youtube_url)
        if src == "unknown":
            raise HTTPException(
                status_code=400,
                detail="URL must be a YouTube or SoundCloud link",
            )
        vid = extract_video_id(youtube_url)
        if not vid:
            raise HTTPException(status_code=400, detail="could not parse URL")
        if src == "youtube":
            canonical = f"https://www.youtube.com/watch?v={vid}"
        else:
            canonical = youtube_url
        with get_conn(db) as conn, transaction(conn):
            row = conn.execute(
                "SELECT 1 FROM themes WHERE media_type = ? AND tmdb_id = ?",
                (media_type, tmdb_id),
            ).fetchone()
            if row is None:
                raise HTTPException(status_code=404, detail="theme not in database")
            # v1.12.72: api_override has no rating_key/section_id
            # context — it's the global "override URL for this title"
            # path used by the failure dialog. Writes the '' (global)
            # row so the worker uses this URL for any section that
            # doesn't have its own per-section override.
            conn.execute(
                """INSERT INTO user_overrides (media_type, tmdb_id, youtube_url,
                                               set_at, set_by, note,
                                               section_id)
                   VALUES (?, ?, ?, ?, ?, ?, '')
                   ON CONFLICT(media_type, tmdb_id, section_id, edition_key) DO UPDATE SET
                       youtube_url = excluded.youtube_url,
                       set_at = excluded.set_at,
                       set_by = excluded.set_by,
                       note = excluded.note""",
                (media_type, tmdb_id, canonical, now_iso(), request.state.user, note),
            )
            # v1.13.74: do NOT clear failure_kind on SET URL. The
            # user is providing a different (presumably working) URL
            # to route around a broken TDB URL — the TDB URL itself
            # is still broken. Pre-fix this clear wiped the TDB-
            # failure flag, flipping the red `TDB ✗` pill green even
            # though TDB was unchanged. The subsequent download for
            # the override URL has source_kind='url', so the worker's
            # success path (now scoped to source_kind='themerrdb' in
            # the same release) won't clear it either. The TDB pill
            # stays honest until the user actually re-tests TDB via
            # RE-DL TDB / REPLACE TDB.
            # Cancel any in-flight download for this item, then enqueue
            # one fresh per-section download via _enqueue_download.
            conn.execute(
                """UPDATE jobs SET status = 'cancelled', finished_at = ?
                   WHERE job_type = 'download' AND media_type = ? AND tmdb_id = ?
                     AND status IN ('pending', 'failed')""",
                (now_iso(), media_type, tmdb_id),
            )
            # v1.12.47: SET URL via the /override dialog needs
            # force_place=True so the new URL's download
            # overwrites whatever theme.mp3 is currently in the
            # Plex folder. User intent is "use this URL" — the
            # placement should reflect it. Pre-fix the place
            # worker hit skip_if_plex_has_theme on rows that
            # already had a theme cached, so the override URL
            # downloaded into canonical but Plex kept playing
            # the old theme.
            from ..core.sync import _enqueue_download
            _n_enq = _enqueue_download(
                conn, media_type=media_type, tmdb_id=tmdb_id,
                reason="override",
                auto_place=True,
                force_place=True,
            )
            _record_audit(
                conn, actor=request.state.user, action="set_url",
                media_type=media_type, tmdb_id=tmdb_id,
                section_id="",
                details={"new_url": canonical, "note": note,
                         "via": "override_dialog"},
            )
        # v1.22.43 (audit): surface a 0-enqueue. Pre-fix _enqueue_download's
        # count was dropped and the endpoint returned ok:True unconditionally —
        # so SET URL on an item no included Plex section owns saved the override
        # but queued NO download, behind a green success toast (fake-success,
        # mirror of the v1.22.16 ACCEPT UPDATE #5 fix). The override stays saved;
        # the warning + the returned count tell the caller nothing downloaded.
        if _n_enq == 0:
            log.warning(
                "SET URL for %s/%s queued NO download — no included Plex "
                "section owns this item; the override is saved but no theme "
                "was fetched. Use DOWNLOAD TDB or re-check the item's section.",
                media_type, tmdb_id)
        log_event(db, level="INFO", component="api",
                  media_type=media_type, tmdb_id=tmdb_id,
                  message=f"Override set by {request.state.user}: {canonical}",
                  detail={"note": note} if note else None)
        return {"ok": True, "youtube_url": canonical,
                "enqueued_sections": _n_enq}

    @app.delete("/api/items/{media_type}/{tmdb_id}/override")
    async def api_clear_override(
        request: Request, media_type: MediaType, tmdb_id: int,
        # v1.15.94: optional section_id scopes the clear to one
        # section. Without it, every section's override gets
        # deleted at once (legacy fan-out semantics — kept for
        # callers without per-section context). Mirrors the
        # v1.12.72 / v1.13.54 scoping pattern used by every
        # other override-touching endpoint (api_set_override,
        # api_unmanage_item, api_accept_update, etc.). Pre-fix
        # this endpoint was the lone outlier — CLEAR URL on a
        # multi-section row's 4K edition would silently delete
        # the standard edition's per-section override too.
        section_id: str | None = Query(None),
        # v1.21.89: rating_key scopes CLEAR URL to ONE edition — editions
        # share a section, so section scope alone deletes a sibling edition's
        # override (same class as the v1.21.83/.84 data-loss fixes).
        rating_key: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        _require_admin(request)
        # v1.15.94: single SELECT + single DELETE, with the section
        # filter appended dynamically. Avoids duplicating the SQL
        # in if/else branches (which trips v1.15.37's multi-write
        # static analyzer at the same time it makes the code more
        # repetitive).
        if section_id is not None:
            where_extra = " AND section_id = ?"
            args = (media_type, tmdb_id, section_id)
        else:
            where_extra = ""
            args = (media_type, tmdb_id)
        # v1.22.31 (audit): wrap the SELECT + DELETE + audit-loop in one
        # transaction. Pre-fix get_conn is autocommit (isolation_level=None),
        # so the DELETE committed independently of the audit INSERTs — if an
        # audit write raised mid-loop the override was already gone with an
        # incomplete audit trail. Atomic now: all-or-nothing.
        with get_conn(db) as conn, transaction(conn):
            # v1.21.89: narrow the SELECT + DELETE to the clicked edition.
            if rating_key:
                where_extra += " AND edition_key = ?"
                args = (*args, edition_key_for_rating_key(conn, rating_key))
            prior = conn.execute(
                f"SELECT youtube_url, section_id FROM user_overrides "
                f"WHERE media_type = ? AND tmdb_id = ?{where_extra}",
                args,
            ).fetchall()
            conn.execute(
                f"DELETE FROM user_overrides "
                f"WHERE media_type = ? AND tmdb_id = ?{where_extra}",
                args,
            )
            for r in prior:
                _record_audit(
                    conn, actor=request.state.user, action="clear_override",
                    media_type=media_type, tmdb_id=tmdb_id,
                    section_id=r["section_id"],
                    details={"old_url": r["youtube_url"]},
                )
        log_event(db, level="INFO", component="api",
                  media_type=media_type, tmdb_id=tmdb_id,
                  section_id=section_id,
                  message=f"Override cleared by {request.state.user}")
        return {"ok": True}

    # --- JSON: jobs / events ---

    @app.get("/api/jobs")
    async def api_jobs(
        # v1.14.54: pattern-validated status (was bare `str`).
        # Pre-fix `?status=garbage` returned `{"jobs": []}` instead
        # of a 400 — silent empty result on hand-typed URLs / API
        # consumer typos. No SQL-injection risk (parameterized) but
        # the contract was wrong. AUDIT_API.md M8.
        status: str = Query("all", pattern=r"^(all|pending|running|done|failed|cancelled)$"),
        limit: int = Query(100, ge=1, le=500),
        db: Path = Depends(get_db_path),
    ):
        # v1.18.95: synthesize op_progress rows into the JOBS panel.
        # the user's repro: BULK PROBE TDB ran for 16+ minutes
        # (visible in the LIVE OPS drawer's 330/5,332 progress
        # bar) but the /logs JOBS panel said "no jobs in the
        # queue" the entire time — bulk_probe_tdb writes to
        # op_progress, not jobs, so the panel was structurally
        # blind to it. Same gap for bulk_lps, tvdb_bridge,
        # reprobe_plex_themes (all op_progress-only kinds; the
        # other two — tdb_sync, plex_enum — have BOTH op_progress
        # AND jobs rows, so they already showed up).
        #
        # Approach: union op_progress rows into the response as
        # synthetic job dicts so the panel becomes self-contained.
        # Synthetic id format: 'op:<op_id>' (string). CANCEL goes
        # through the LIVE OPS drawer (the front-end skips the
        # CANCEL button on rows with is_op_progress=True since
        # the existing /api/jobs/{id}/cancel endpoint expects an
        # int job_id). Sorted FIRST so live activity is most
        # prominent.
        with get_conn(db) as conn:
            if status == "all":
                rows = conn.execute(
                    "SELECT * FROM jobs ORDER BY id DESC LIMIT ?", (limit,),
                ).fetchall()
            else:
                rows = conn.execute(
                    "SELECT * FROM jobs WHERE status = ? ORDER BY id DESC LIMIT ?",
                    (status, limit),
                ).fetchall()
            # v1.18.95: op_progress status filter. The /api/jobs
            # status query pattern (all|pending|running|done|failed|
            # cancelled) maps cleanly to op_progress.status with
            # one exception: 'cancelling' is op_progress-only and
            # operationally still running, so we surface it under
            # the 'running' filter to match user intent.
            if status == "all":
                op_status_clause = ""
                op_status_params: list = []
            elif status == "running":
                op_status_clause = " WHERE status IN ('running', 'cancelling')"
                op_status_params = []
            else:
                op_status_clause = " WHERE status = ?"
                op_status_params = [status]
            op_rows = conn.execute(
                "SELECT op_id, kind, status, started_at, finished_at, "
                "       stage, stage_label, stage_current, stage_total, "
                "       processed_total, error_count, detail_json "
                f"FROM op_progress{op_status_clause} "
                "ORDER BY started_at DESC LIMIT ?",
                (*op_status_params, limit),
            ).fetchall()
        # Translate op_progress rows into the same dict shape the
        # frontend expects from jobs. Activity line summarises
        # stage label + progress counters + the most recent
        # activity from detail_json (rolling 5-entry list).
        synthesized: list[dict] = []
        for op in op_rows:
            activity = ""
            try:
                detail = json.loads(op["detail_json"] or "{}")
                acts = detail.get("activity") or []
                if isinstance(acts, list) and acts:
                    # Latest entry is last in the rolling list.
                    last = acts[-1]
                    if isinstance(last, dict):
                        activity = str(last.get("message") or "")
                    else:
                        activity = str(last)
            except (TypeError, ValueError):
                activity = ""
            label = op["stage_label"] or op["kind"]
            cur, total = op["stage_current"] or 0, op["stage_total"] or 0
            if total > 0:
                pct = (cur * 100.0) / total
                progress = f" — {cur:,}/{total:,} ({pct:.0f}%)"
            elif cur > 0:
                progress = f" — {cur:,} processed"
            else:
                progress = ""
            summary = f"{label}{progress}"
            if activity:
                summary = f"{summary} — {activity}"
            synthesized.append({
                "id": f"op:{op['op_id']}",
                "job_type": op["kind"],
                "media_type": None,
                "tmdb_id": None,
                "section_id": None,
                "status": (
                    "running" if op["status"] == "cancelling"
                    else op["status"]
                ),
                "attempts": None,
                "max_attempts": None,
                "created_at": op["started_at"],
                "started_at": op["started_at"],
                "finished_at": op["finished_at"],
                "next_run_at": None,
                "last_error": summary,
                "payload": None,
                "cancel_requested": 1 if op["status"] == "cancelling" else 0,
                "acked_at": None,
                "is_op_progress": True,
            })
        # v1.19.47: partition synthesized rows so only LIVE ops
        # pin to the top. Pre-fix the v1.18.95 design said
        # "Synthetic rows go FIRST so live activity is most
        # visible" — true for RUNNING ops, but the same code
        # path pinned TERMINAL (done/failed/cancelled) ops too.
        # the user's repro: the /logs page showed
        #   op:cloud-themes-backup (failed, minutes ago)
        #   op:tdb_sync (done, 9am hours ago)
        #   op:plex_enum (done, hours ago)
        #   2998 place (done, minutes ago)
        # — stale tdb_sync and plex_enum pinned above recent
        # real jobs, even though they finished hours earlier.
        # Fix: split active (running/pending/cancelling) from
        # terminal; pin active, merge terminal with real jobs
        # sorted by finished_at DESC (chronological recency).
        ACTIVE_STATUSES = {"running", "pending", "cancelling"}
        active_synth = [
            s for s in synthesized
            if s["status"] in ACTIVE_STATUSES
        ]
        terminal_synth = [
            s for s in synthesized
            if s["status"] not in ACTIVE_STATUSES
        ]
        real_jobs = [dict(r) for r in rows]

        def _sort_key(j: dict) -> str:
            # Effective timestamp: finished_at > started_at >
            # created_at. ISO-8601 strings sort lexically =
            # chronologically. Empty string for missing keeps
            # null-handled rows at the bottom.
            return (
                j.get("finished_at")
                or j.get("started_at")
                or j.get("created_at")
                or ""
            )

        # Merge terminal-synth + real jobs sorted by recency.
        # Real jobs already came in id DESC order (effectively
        # chronological for autoincrement), but mixing in op
        # rows needs an explicit timestamp key.
        merged = sorted(
            terminal_synth + real_jobs,
            key=_sort_key, reverse=True,
        )
        # Active ops still pin to the top — that part of the
        # v1.18.95 design is correct (a running op should be
        # visible regardless of how many recent jobs follow).
        combined = (active_synth + merged)[:limit]
        return {"jobs": combined}

    @app.post("/api/jobs/{job_id}/cancel")
    async def api_cancel_job(
        request: Request, job_id: int,
        force: bool = Query(False),
        db: Path = Depends(get_db_path),
    ):
        """v1.11.36: cooperative job cancellation.

        - Pending jobs flip to status='cancelled' immediately (the
          worker's pre-dispatch cancel-check or this endpoint catches
          them before they ever run).
        - Running jobs get cancel_requested=1; the worker handler
          notices on the next safe yield (between sync batches /
          plex_enum sections / scan iterations / etc.) and bails out.
        - Already-finished jobs (done / failed / cancelled) return 409.

        v1.11.53: ?force=true escalates to a hard cancel — the row
        flips straight to status='cancelled' regardless of the
        cooperative path. Used when the worker thread has wedged
        (DB lock contention, stuck on a Plex API call, etc.) and
        the cancel_requested flag never gets read. The UI surfaces
        a × FORCE button on rows already marked cancelling so the
        user has a one-click escape from a stuck-cancelling job.
        """
        _require_admin(request)
        with get_conn(db) as conn, transaction(conn):
            # v0.51.11: select the full row so a cancelled ACCEPT/REVERT download
            # can have its rollback recipe applied after the txn (round-4 audit
            # HIGH — cancel used to skip the recipe, stranding the half-applied
            # override/decision state).
            row = conn.execute(
                "SELECT id, status, cancel_requested, payload, media_type, "
                "tmdb_id, section_id FROM jobs WHERE id = ?",
                (job_id,),
            ).fetchone()
            if row is None:
                raise HTTPException(status_code=404, detail="job not found")
            status_now = row["status"]
            if status_now == "pending":
                conn.execute(
                    "UPDATE jobs SET status = 'cancelled', "
                    "                finished_at = ?, "
                    "                last_error = 'cancelled by user', "
                    "                cancel_requested = 0 "
                    "WHERE id = ?",
                    (now_iso(), job_id),
                )
                outcome = "cancelled"
            elif status_now == "running":
                if force:
                    conn.execute(
                        "UPDATE jobs SET status = 'cancelled', "
                        "                finished_at = ?, "
                        "                last_error = 'force-cancelled by user', "
                        "                cancel_requested = 0 "
                        "WHERE id = ?",
                        (now_iso(), job_id),
                    )
                    outcome = "force_cancelled"
                else:
                    conn.execute(
                        "UPDATE jobs SET cancel_requested = 1 WHERE id = ?",
                        (job_id,),
                    )
                    outcome = "cancel_requested"
            else:
                raise HTTPException(
                    status_code=409,
                    detail=f"job is already in terminal state '{status_now}'",
                )
        # v0.51.11: outside the txn (apply_job_rollback opens its own conn) —
        # undo the ACCEPT/REVERT destructive prep for a job cancelled into a
        # terminal state. No-op (no conn opened) for jobs carrying no recipe.
        # 'cancel_requested' (running, no force) is left to the worker's own
        # _JobCancelled rollback so we don't double-run mid-flight.
        if outcome in ("cancelled", "force_cancelled"):
            from ..core.worker import apply_job_rollback
            apply_job_rollback(db, row, "cancelled by user")
        log_event(db, level="INFO", component="api",
                  message=f"Job {job_id} cancellation requested by "
                          f"{request.state.principal.username}",
                  detail={"prev_status": status_now, "outcome": outcome,
                          "force": bool(force)})
        return {"ok": True, "outcome": outcome, "prev_status": status_now}

    # v1.20.32: bulk-cancelable per-row job types. The synthetic queue
    # cards in the ops drawer (download_queue, place_queue, …) all map to
    # one of these via `kind.replace('_queue','')`. sync / plex_enum are
    # excluded — they're singletons with their own op_progress cancel.
    _BULK_CANCELABLE_JOB_TYPES = frozenset(
        {"download", "place", "scan", "refresh", "relink", "adopt"})

    @app.post("/api/jobs/cancel-pending")
    async def api_cancel_pending_jobs(
        request: Request,
        job_type: str = Query(...),
        db: Path = Depends(get_db_path),
    ):
        """v1.20.32: bulk-cancel every PENDING job of one type — the
        queue-drain escape hatch the user asked for on long bulk download
        runs ("cancel all the pending jobs still remaining at once").

        Only PENDING rows flip to cancelled; the one job currently
        RUNNING finishes on its own (use the per-job CANCEL via /queue
        for that). Pending jobs that the worker hasn't claimed yet are
        also caught by its pre-dispatch cancel-check, so there's no race
        where a just-claimed row slips through as 'running'."""
        _require_admin(request)
        if job_type not in _BULK_CANCELABLE_JOB_TYPES:
            raise HTTPException(
                status_code=400,
                detail=(f"job_type must be one of "
                        f"{sorted(_BULK_CANCELABLE_JOB_TYPES)}"),
            )
        with get_conn(db) as conn, transaction(conn):
            # v0.51.11: capture the rows BEFORE flipping so cancelled ACCEPT/REVERT
            # downloads can have their rollback recipe applied after the txn
            # (round-4 audit HIGH — bulk cancel skipped the recipe too).
            rollback_rows = conn.execute(
                "SELECT id, payload, media_type, tmdb_id, section_id FROM jobs "
                "WHERE status = 'pending' AND job_type = ?",
                (job_type,),
            ).fetchall() if job_type == "download" else []
            cur = conn.execute(
                "UPDATE jobs SET status = 'cancelled', "
                "                finished_at = ?, "
                "                last_error = 'bulk-cancelled by user', "
                "                cancel_requested = 0 "
                "WHERE status = 'pending' AND job_type = ?",
                (now_iso(), job_type),
            )
            n = cur.rowcount
        # v0.51.11: outside the txn — undo each cancelled ACCEPT/REVERT prep
        # (no-op / no conn opened for the recipe-less majority).
        if rollback_rows:
            from ..core.worker import apply_job_rollback
            for r in rollback_rows:
                apply_job_rollback(db, r, "bulk-cancelled by user")
        log_event(db, level="INFO", component="api",
                  message=(f"Bulk-cancelled {n} pending {job_type} "
                           f"job(s) by {request.state.principal.username}"),
                  detail={"job_type": job_type, "cancelled": n})
        return {"ok": True, "cancelled": n, "job_type": job_type}

    @app.post("/api/jobs/{job_id}/ack-failure")
    async def api_ack_job_failure(
        request: Request, job_id: int,
        db: Path = Depends(get_db_path),
    ):
        """v1.15.60: single-job ack from the /queue FAILED list.
        Mirrors the /api/jobs/clear-failed bulk endpoint's
        intent (stamp jobs.acked_at so the row flips green)
        but also acks the theme's failure_kind so the topbar
        FAIL pill drops on the same click.

        Pre-fix v1.15.54's per-job ACK button POSTed to
        /api/items/{mt}/{id}/clear-failure (theme-level only).
        That cleared the theme but left jobs.acked_at NULL, so
        the job row stayed red 'failed' in /queue — the user:
        'clicking htem actually doesn't do anything currently.'
        The fix routes through a single endpoint that updates
        BOTH surfaces atomically + writes one audit-event with
        the job's media_type/tmdb_id for traceability.
        """
        _require_admin(request)
        with get_conn(db) as conn, transaction(conn):
            job = conn.execute(
                "SELECT status, acked_at, media_type, tmdb_id "
                "FROM jobs WHERE id = ?",
                (job_id,),
            ).fetchone()
            if job is None:
                raise HTTPException(status_code=404, detail="job not found")
            if job["status"] != "failed":
                raise HTTPException(
                    status_code=409,
                    detail=f"job status is '{job['status']}', not 'failed'",
                )
            # (1) stamp jobs.acked_at — drives the green
            # 'failed (acknowledged)' row tone in /queue (v1.12.12).
            if job["acked_at"] is None:
                conn.execute(
                    "UPDATE jobs SET acked_at = ? WHERE id = ?",
                    (now_iso(), job_id),
                )
            # (2) ack the theme if we have a row binding —
            # drops the topbar FAIL pill via the unacked_failures
            # count. Sync/enum jobs without media_type/tmdb_id
            # skip this step (no theme to ack).
            theme_acked = False
            if job["media_type"] and job["tmdb_id"] is not None:
                theme = conn.execute(
                    "SELECT failure_kind, failure_acked_at FROM themes "
                    "WHERE media_type = ? AND tmdb_id = ?",
                    (job["media_type"], job["tmdb_id"]),
                ).fetchone()
                if theme and theme["failure_kind"] is not None \
                        and theme["failure_acked_at"] is None:
                    conn.execute(
                        "UPDATE themes SET failure_acked_at = ? "
                        "WHERE media_type = ? AND tmdb_id = ?",
                        (now_iso(), job["media_type"], job["tmdb_id"]),
                    )
                    theme_acked = True
        log_event(
            db, level="INFO", component="api",
            message=(
                f"Acknowledged job {job_id} by "
                f"{request.state.principal.username}"
            ),
            detail={"job_id": job_id, "theme_acked": theme_acked},
        )
        return {"ok": True, "theme_acked": theme_acked}

    @app.post("/api/jobs/clear-failed")
    async def api_clear_failed_jobs(
        request: Request, db: Path = Depends(get_db_path),
    ):
        """v1.11.73 / v1.12.12: acknowledge every unacked failed
        job. Pre-1.12.12 this hard-deleted the rows, throwing away
        the historical record of what failed. Now it stamps
        jobs.acked_at so the row stays put — renders in green
        ('ACKNOWLEDGED'), drops out of the topbar failure count,
        but stays filterable / sortable for later review.
        """
        _require_admin(request)
        with get_conn(db) as conn:
            cur = conn.execute(
                "UPDATE jobs SET acked_at = ? "
                "WHERE status = 'failed' AND acked_at IS NULL",
                (now_iso(),),
            )
            cleared = cur.rowcount or 0
        log_event(db, level="INFO", component="api",
                  message=f"Acknowledged {cleared} failed job(s) by "
                          f"{request.state.principal.username}",
                  detail={"acknowledged": cleared})
        return {"ok": True, "acknowledged": cleared}

    @app.get("/api/events")
    async def api_events(
        request: Request,
        limit: int = Query(200, ge=1, le=1000),
        component: str = Query(""),
        level: str = Query(""),
        since: int = Query(0, ge=0, le=30 * 86400),
        db: Path = Depends(get_db_path),
    ):
        # v1.14.56: gate on _require_admin. Pre-fix the endpoint
        # was unauthenticated; with forward-auth disabled (the
        # local-bcrypt path) any browser session that landed on
        # /api/events could read the raw events table — including
        # failure_message strings that may carry yt-dlp output
        # with cookie-walled URLs / IDs / partial tokens that
        # weren't scrubbed at log time. AUDIT_API.md L5.
        _require_admin(request)
        sql = "SELECT * FROM events"
        clauses = []
        params: list = []
        if component:
            clauses.append("component = ?"); params.append(component)
        if level:
            clauses.append("level = ?"); params.append(level.upper())
        # v1.15.41: ?since=<seconds> filter so the queue's SINCE chip
        # row can answer "which events landed in the last hour/day/week"
        # — the user's complaint was that the dashboard tells you the
        # count but you have to scroll to find the rows. Cap at 30d
        # so a malformed deep-link can't ask SQLite for an open-ended
        # scan of the full events table.
        if since > 0:
            clauses.append("ts >= datetime('now', ?)")
            params.append(f"-{int(since)} seconds")
        if clauses:
            sql += " WHERE " + " AND ".join(clauses)
        sql += " ORDER BY id DESC LIMIT ?"
        params.append(limit)
        with get_conn(db) as conn:
            rows = conn.execute(sql, params).fetchall()
        return {"events": [dict(r) for r in rows]}

