    # v1.22.53 (the user: "the 8 collisions — should we fix?"): read-only detail
    # on each collision the de-orphan walker skipped (an orphan whose imdb
    # resolves to a tmdb where a theme already exists = TWO theme records for
    # one title). Reports what each record holds + which one the library row
    # links to, so a merge decision is made from data. NO data changes.
    @app.get("/api/admin/diagnostics/orphan-collisions")
    async def api_admin_orphan_collision_diagnostics(
        request: Request, db: Path = Depends(get_db_path),
    ):
        _require_admin(request)

        def _run():
            from ..config import Settings
            from ..core.deorphan import _resolve_real_tmdb
            from ..core.tmdb import TMDBClient
            settings = Settings()
            if not settings.tmdb_api_key:
                return {"ok": False, "error": "TMDB API key not configured."}
            tmdb = TMDBClient(settings.tmdb_api_key, db)
            _CHILD_TABLES = ("local_files", "placements", "user_overrides",
                             "pending_updates", "previous_urls")

            def _children(conn, mt, tid):
                return {
                    tbl: conn.execute(
                        f"SELECT COUNT(*) FROM {tbl} "
                        f"WHERE media_type = ? AND tmdb_id = ?",
                        (mt, tid)).fetchone()[0]
                    for tbl in _CHILD_TABLES
                }

            out = []
            with get_conn(db) as conn:
                orphans = conn.execute(
                    "SELECT id, media_type, tmdb_id, imdb_id, title, year "
                    "FROM themes WHERE upstream_source = 'plex_orphan' "
                    "  AND tmdb_id < 0 AND imdb_id IS NOT NULL "
                    "  AND imdb_id != '' ORDER BY id").fetchall()
                for o in orphans:
                    try:
                        real = _resolve_real_tmdb(
                            tmdb, o["imdb_id"], o["media_type"])
                    except Exception:  # noqa: BLE001
                        real = None
                    if real is None:
                        continue
                    target = conn.execute(
                        "SELECT id, title, upstream_source FROM themes "
                        "WHERE media_type = ? AND tmdb_id = ? LIMIT 1",
                        (o["media_type"], real)).fetchone()
                    if target is None:
                        continue  # would re-key cleanly — not a collision
                    o_kids = _children(conn, o["media_type"], o["tmdb_id"])
                    t_kids = _children(conn, o["media_type"], real)
                    link_orphan = conn.execute(
                        "SELECT COUNT(*) FROM plex_items WHERE theme_id = ?",
                        (o["id"],)).fetchone()[0]
                    link_target = conn.execute(
                        "SELECT COUNT(*) FROM plex_items WHERE theme_id = ?",
                        (target["id"],)).fetchone()[0]
                    o_total = sum(o_kids.values())
                    if o_total == 0 and link_orphan == 0:
                        hint = ("empty duplicate — holds nothing, no library "
                                "row points at it; safe to delete")
                    elif link_target > 0 and o_total > 0:
                        hint = ("SPLIT TRACKING — the library row follows the "
                                "target record while your manual theme's "
                                "tracking sits on the duplicate (invisible to "
                                "the row)")
                    elif link_orphan > 0:
                        hint = ("library row still follows the duplicate — "
                                "the target record's TDB tracking is what's "
                                "invisible")
                    else:
                        hint = "no library row linked to either record"
                    out.append({
                        "title": o["title"], "year": o["year"],
                        "media_type": o["media_type"], "imdb": o["imdb_id"],
                        "orphan_tmdb": o["tmdb_id"], "target_tmdb": real,
                        "target_kind": (
                            "rekeyed orphan twin"
                            if target["upstream_source"] == "plex_orphan"
                            else "real themerrdb record"),
                        "orphan_children": o_kids,
                        "target_children": t_kids,
                        "library_rows_on_orphan": link_orphan,
                        "library_rows_on_target": link_target,
                        "hint": hint,
                    })
            return {"ok": True, "collisions": out, "count": len(out)}

        return await run_in_threadpool(_run)

    @app.get("/api/admin/probe-themes")
    async def api_admin_probe_themes(
        request: Request,
        rk: list[str] = Query(default_factory=list),
    ):
        """v1.18.31: read-only probe of `/library/metadata/{rk}/themes`.
        the user's safety question on the LET PLEX SERVE path for
        T+P rows whose +P came from the now-defunct themerr-plex
        plugin: does Plex still have the old plugin's persisted
        theme entries, and would motif's `DELETE /library/
        metadata/{rk}/themes` (which has no theme-id selectivity)
        wipe them alongside motif's own upload?

        themerr-plex stored its themes via the SAME api endpoint
        motif uses (`item.uploadTheme()` → `POST /library/
        metadata/{rk}/themes`) so the bytes survived the plugin's
        removal in Plex's Uploads/themes/ directory. But the
        plugin's own remove path was a `shutil.rmtree` of that
        whole directory — strongly suggesting Plex's HTTP DELETE
        has no theme-id selectivity either. Probing GET .../themes
        for a few known-state rks tells us empirically how many
        entries exist and who owns them, which is the prereq for
        deciding the v1.18.32+ safety direction (warn / backup /
        targeted-delete / leave-as-is).

        Diagnostic-only. Not wired to any UI; hit it directly:
        `GET /api/admin/probe-themes?rk=12345&rk=67890`.
        Capped at 10 rks per call so a stray repeat doesn't
        hammer the Plex API.
        """
        _require_admin(request)
        if not rk:
            raise HTTPException(
                status_code=400,
                detail="provide ?rk=<rating_key> at least once",
            )
        if len(rk) > 10:
            raise HTTPException(
                status_code=400,
                detail="cap is 10 rks per call (DoS guard)",
            )
        if not settings.plex_enabled or not settings.plex_token:
            raise HTTPException(
                status_code=503,
                detail="Plex disabled or token missing",
            )
        from ..core.plex import PlexClient, PlexConfig
        cfg = PlexConfig(
            url=settings.plex_url, token=settings.plex_token,
            movie_section=settings.plex_movie_section,
            tv_section=settings.plex_tv_section, enabled=True,
        )
        # v1.22.31 (audit): up to 10 SYNCHRONOUS Plex HTTP calls — run them
        # off the event loop. Pre-fix the whole loop (each call up to the 10s
        # client timeout → ~100s worst case) blocked the async loop, freezing
        # every other request for the duration (the v1.21.20 block class).
        def _probe() -> dict[str, dict]:
            out: dict[str, dict] = {}
            with PlexClient(cfg, plus_mode=settings.plus_equiv_mode) as plex:
                for rating_key in rk:
                    out[rating_key] = plex.get_themes(rating_key=rating_key)
            return out
        results = await run_in_threadpool(_probe)
        return {
            "ok": True,
            "probed_at": now_iso(),
            "endpoint": "/library/metadata/{rk}/themes (GET)",
            "results": results,
        }

    @app.post("/api/admin/probe-targeted-delete")
    async def api_admin_probe_targeted_delete(
        request: Request,
        item_rk: str = Query(...),
        theme_rk: str = Query(...),
        shape: str = Query(default="query"),
    ):
        """v1.18.32: probe whether Plex supports targeted DELETE
        of a specific theme entry. v1.18.31's GET probe revealed
        each theme entry carries its own ratingKey (`upload://
        themes/<hash>` or `metadata://themes/<hash>`); v1.18.32
        tests whether Plex's HTTP DELETE accepts that ratingKey
        as a selector.

        Why this matters: motif's current `delete_theme` hits
        DELETE /library/metadata/{rk}/themes with no selectivity
        — likely wipes EVERY theme on the item (themerr-plex
        leftovers, Plex's own metadata theme, motif's own
        upload, all gone). If Plex supports targeted DELETE we
        can rewrite LET PLEX SERVE + SWITCH cleanups to only
        remove motif's specific upload.

        Shapes (one per call; operator can iterate):

          - `singular_delete` — DELETE /library/metadata/{rk}/theme
                                (SINGULAR — python-plexapi attested
                                 in v1.18.33; theme_rk is ignored,
                                 deletes the CURRENTLY-SERVING theme
                                 association rather than a specific
                                 entry)
          - `query`        — DELETE .../themes?url=<encoded> (v1.18.32 → 404)
          - `subpath`      — DELETE .../themes/<encoded>     (v1.18.32 → 404)
          - `put_unselect` — PUT .../themes?url=<encoded>&unset=1 (v1.18.32 → 404)

        Returns the attempt details PLUS a fresh enumeration of
        the item's themes so the operator can see whether the
        target entry actually disappeared (or, for
        singular_delete, whether the selected flag flipped).

        POST (not GET) so a stray bookmark can't trigger a
        DELETE; admin-gated. The endpoint DOES delete on
        success — for plural shapes only point it at theme
        entries you're willing to lose; for singular_delete
        it removes the currently-serving theme association
        (the underlying entries in the /themes collection
        should remain per python-plexapi's docs).
        """
        _require_admin(request)
        if shape not in (
            "query", "subpath", "put_unselect", "singular_delete",
        ):
            raise HTTPException(
                status_code=400,
                detail=(
                    "shape must be one of: query, subpath, "
                    "put_unselect, singular_delete"
                ),
            )
        if not settings.plex_enabled or not settings.plex_token:
            raise HTTPException(
                status_code=503,
                detail="Plex disabled or token missing",
            )
        from ..core.plex import PlexClient, PlexConfig
        cfg = PlexConfig(
            url=settings.plex_url, token=settings.plex_token,
            movie_section=settings.plex_movie_section,
            tv_section=settings.plex_tv_section, enabled=True,
        )
        # v1.22.58: run the 3 synchronous Plex round-trips (pre-probe +
        # delete attempt + post-probe) OFF the event loop — the v1.21.20 /
        # v1.22.57 block class. Caught by the new async-handler lint
        # (test_v1_22_58_async_no_blocking_calls).
        def _run():
            with PlexClient(cfg, plus_mode=settings.plus_equiv_mode) as plex:
                pre = plex.get_themes(rating_key=item_rk)
                attempt = plex.try_targeted_delete_theme(
                    item_rating_key=item_rk,
                    theme_rating_key=theme_rk,
                    shape=shape,
                )
                post = plex.get_themes(rating_key=item_rk)
            return pre, attempt, post
        pre, attempt, post = await run_in_threadpool(_run)
        return {
            "ok": True,
            "probed_at": now_iso(),
            "item_rk": item_rk,
            "theme_rk": theme_rk,
            "shape": shape,
            "pre_themes": pre,
            "attempt": attempt,
            "post_themes": post,
        }

    @app.post("/api/admin/probe-set-theme")
    async def api_admin_probe_set_theme(
        request: Request,
        item_rk: str = Query(...),
        theme_rk: str = Query(...),
        method: str = Query(default="post"),
    ):
        """v1.18.34: probe whether POST/PUT singular `/theme?url=...`
        can select a specific theme entry as the row's active
        theme. Plex Web doesn't expose a theme picker UI (per
        the user's screenshot of the item edit dialog), so the LET
        PLEX SERVE flow can't rely on the user manually picking
        a fallback theme after motif withdraws. If POST select
        works, motif can directly select a non-motif entry
        (preferring `metadata://...` over leftover `upload://...`)
        and the row keeps serving a theme without user
        intervention.

        OpenAPI says: "Set an item's artwork, theme, etc." for
        the singular endpoint. python-plexapi's `setTheme()`
        raises NotImplementedError so they never wrapped it.

        Methods (one per call; both should work per spec):
          - `post` → POST /library/metadata/{rk}/theme?url=<theme_rk>
          - `put`  → PUT  /library/metadata/{rk}/theme?url=<theme_rk>

        Wrap pre-probe → attempt → post-probe in one response so
        the operator can see the selection delta in one shot.

        POST-only on motif's side so a stray bookmark can't
        accidentally re-select. Admin-gated.

        Recovery if the wrong entry gets selected: just call
        DELETE singular (clears selection) or RE-PUSH motif's
        theme (auto-selects motif's upload again).
        """
        _require_admin(request)
        if method not in ("post", "put"):
            raise HTTPException(
                status_code=400,
                detail="method must be one of: post, put",
            )
        if not settings.plex_enabled or not settings.plex_token:
            raise HTTPException(
                status_code=503,
                detail="Plex disabled or token missing",
            )
        from ..core.plex import PlexClient, PlexConfig
        cfg = PlexConfig(
            url=settings.plex_url, token=settings.plex_token,
            movie_section=settings.plex_movie_section,
            tv_section=settings.plex_tv_section, enabled=True,
        )
        # v1.22.58: off the event loop (pre-probe + set attempt + post-probe).
        def _run():
            with PlexClient(cfg, plus_mode=settings.plus_equiv_mode) as plex:
                pre = plex.get_themes(rating_key=item_rk)
                attempt = plex.try_set_active_theme(
                    item_rating_key=item_rk,
                    theme_rating_key=theme_rk,
                    method=method,
                )
                post = plex.get_themes(rating_key=item_rk)
            return pre, attempt, post
        pre, attempt, post = await run_in_threadpool(_run)
        return {
            "ok": True,
            "probed_at": now_iso(),
            "item_rk": item_rk,
            "theme_rk": theme_rk,
            "method": method,
            "pre_themes": pre,
            "attempt": attempt,
            "post_themes": post,
        }

    @app.post("/api/admin/probe-reupload-theme")
    async def api_admin_probe_reupload_theme(
        request: Request,
        item_rk: str = Query(...),
        theme_rk: str = Query(...),
    ):
        """v1.18.35: probe the re-upload trick — the only viable
        LPS fallback path after v1.18.34 confirmed Plex has no
        native "select existing entry" API.

        The trick: fetch an existing theme entry's audio bytes,
        re-upload them. Plex content-dedupes, so the same SHA-1
        re-uses the existing entry and marks it `selected: true`.
        Net effect: motif can "select" any existing entry by
        proxy of re-uploading its bytes.

        Workflow:
          1. Pre-probe GET /themes — baseline state
          2. Fetch bytes from /library/metadata/{rk}/file?url=<theme_rk>
          3. POST those bytes to /library/metadata/{rk}/themes
          4. Post-probe GET /themes — see selection delta

        If post_themes shows the target entry now `selected: true`,
        the re-upload trick works and v1.18.36's LPS flow becomes:
        DELETE singular → re-upload first non-motif entry.

        POST-only, admin-gated. Bandwidth: ~1MB round-trip per
        call (one fetch + one upload). The "delete" comparison
        here is non-destructive — this only re-uploads, doesn't
        remove anything. Safe to run on any rk + theme combo
        that has at least one existing entry.
        """
        _require_admin(request)
        if not settings.plex_enabled or not settings.plex_token:
            raise HTTPException(
                status_code=503,
                detail="Plex disabled or token missing",
            )
        from ..core.plex import PlexClient, PlexConfig
        cfg = PlexConfig(
            url=settings.plex_url, token=settings.plex_token,
            movie_section=settings.plex_movie_section,
            tv_section=settings.plex_tv_section, enabled=True,
        )
        # v1.22.58: off the event loop (pre-probe + reupload + post-probe).
        def _run():
            with PlexClient(cfg, plus_mode=settings.plus_equiv_mode) as plex:
                pre = plex.get_themes(rating_key=item_rk)
                attempt = plex.try_reupload_existing_theme(
                    item_rating_key=item_rk,
                    theme_rating_key=theme_rk,
                )
                post = plex.get_themes(rating_key=item_rk)
            return pre, attempt, post
        pre, attempt, post = await run_in_threadpool(_run)
        return {
            "ok": True,
            "probed_at": now_iso(),
            "item_rk": item_rk,
            "theme_rk": theme_rk,
            "pre_themes": pre,
            "attempt": attempt,
            "post_themes": post,
        }

    # v1.18.87: compact-mode post-processor. Mutates `resolved` in
    # place to strip heavy fields: hex bytes truncated to 32 chars
    # (~10 bytes — magic-byte ID only), headers filtered to the
    # diagnostic-essential whitelist, themes_response body summarised.
    # The full output trips chat-paste safety filters at ~30KB; the
    # compact form runs ~10x smaller.
    _COMPACT_HEADER_KEYS = {
        "content-type", "content-length", "location",
        "accept-ranges", "content-range",
    }
    _COMPACT_HEX_CHARS = 32  # ~10 bytes — enough for ID3/JSON/HTML magic

    def _compact_probe_result(resolved: list) -> None:
        for r in resolved:
            if not r.get("matched"):
                continue
            # Summarise the /themes response — keep entry count +
            # Metadata items only, drop the wrapper bulk.
            themes = r.get("themes_response") or {}
            body = themes.get("body") if isinstance(themes, dict) else None
            if isinstance(body, dict):
                container = body.get("MediaContainer") or {}
                metadata = container.get("Metadata") or []
                r["themes_response"] = {
                    "ok": themes.get("ok"),
                    "http_status": themes.get("http_status"),
                    "metadata_count": (
                        len(metadata)
                        if isinstance(metadata, list) else 0
                    ),
                }
            # Compact each per-entry probe result.
            for ep in r.get("entries_probe") or []:
                bp = ep.get("bytes_probe")
                if not isinstance(bp, dict):
                    continue
                # Filter headers to the whitelist.
                hdrs = bp.get("headers") or {}
                if isinstance(hdrs, dict):
                    bp["headers"] = {
                        k: v for k, v in hdrs.items()
                        if k.lower() in _COMPACT_HEADER_KEYS
                    }
                # Truncate hex preview.
                hex_str = bp.get("body_preview_hex")
                if isinstance(hex_str, str):
                    bp["body_preview_hex"] = hex_str[:_COMPACT_HEX_CHARS]

    @app.post("/api/admin/probe-plex-themes")
    async def api_admin_probe_plex_themes(
        request: Request,
        db: Path = Depends(get_db_path),
    ):
        """v1.18.85: characterise Plex's theme API surface across
        the four P sub-flavors so we know whether cloud themes
        (Plex Pass) return downloadable bytes via the same
        `/library/metadata/{rk}/file?url=<entry-rk>` path that
        themerr-plex + user-upload entries do.

        Why: motif can already re-create themerr-plex themes
        (TDB URL is known) + user-upload themes (user has the
        source) + sidecar themes (file on disk). The ONE case
        where Plex is the sole holder of the bytes is Plex Pass
        cloud themes — and that's the case where motif has no
        recovery path if Plex Pass lapses or the catalog
        changes. Before designing a "backup cloud themes"
        feature, we need to know empirically what the API
        returns for cloud entries vs the known-good entry
        shapes.

        Title-based search: caller passes title fragments;
        endpoint resolves each to a rating_key via the local
        plex_items table (LIKE match, ORDER BY exact match
        preference, LIMIT 1). Avoids hitting Plex's search API
        and keeps the probe deterministic — same fragment always
        resolves to the same rk.

        For each resolved rk:
          1. GET /library/metadata/{rk}/themes — dump full JSON
          2. For each entry in the response's Metadata list:
             - Extract `ratingKey` (the upload://themes/<sha1>
               style URI)
             - Call probe_theme_entry_bytes — Range-GET 4096
               bytes, capture status + all headers + content-
               type + body_preview_hex

        Read-only. Cap at 8 titles per call so a stray repeat
        doesn't hammer Plex. Admin-gated.
        """
        _require_admin(request)
        try:
            body = await request.json()
        except Exception:
            raise HTTPException(
                status_code=400,
                detail="invalid JSON body",
            )
        titles = (body or {}).get("titles") or []
        # v1.18.87: compact-mode toggle. The full probe output's
        # body_preview_hex (4KB per entry) + every response header
        # produced ~30KB+ JSON dumps that tripped chat-paste safety
        # filters (long opaque hex blobs + URL headers can look
        # suspicious to automated filters). Compact mode truncates
        # hex to 32 chars (~10 bytes — enough for magic-byte ID:
        # `49 44 33` for MP3, `7b 22` for JSON `{"`, etc.) and
        # keeps only the diagnostic-essential headers (content-type,
        # content-length, location, accept-ranges). Drops the raw
        # themes_response.body MediaContainer wrapper too — only
        # the per-entry shape matters for characterisation.
        # Default True so the chat-paste use case works out-of-box;
        # opt-out via {"compact": false} when full bytes are needed
        # locally (e.g. saving to a file for hex-editor inspection).
        compact = bool((body or {}).get("compact", True))
        if not isinstance(titles, list) or not titles:
            raise HTTPException(
                status_code=400,
                detail="titles[] required (list of title fragments)",
            )
        if len(titles) > 8:
            raise HTTPException(
                status_code=400,
                detail="cap is 8 titles per call (DoS guard)",
            )
        if not settings.plex_enabled or not settings.plex_token:
            raise HTTPException(
                status_code=503,
                detail="Plex disabled or token missing",
            )
        # Resolve each title fragment → rating_key via plex_items.
        # ORDER BY exact-title-match-first so a fragment that
        # exactly equals an existing title beats a partial match
        # (e.g. "Inception" picks the movie, not "Inception
        # Anomaly").
        resolved = []
        with get_conn(db) as conn:
            for title_frag in titles:
                tf = str(title_frag or "").strip()
                if not tf:
                    resolved.append({
                        "query": title_frag,
                        "matched": None,
                        "reason": "empty fragment",
                    })
                    continue
                like = f"%{tf}%"
                row = conn.execute(
                    "SELECT rating_key, title, year, section_id, "
                    "       media_type "
                    "  FROM plex_items "
                    " WHERE title LIKE ? "
                    " ORDER BY (LOWER(title) = LOWER(?)) DESC, "
                    "          LENGTH(title) ASC, title ASC "
                    " LIMIT 1",
                    (like, tf),
                ).fetchone()
                if row is None:
                    resolved.append({
                        "query": title_frag,
                        "matched": None,
                        "reason": "no plex_items row matches",
                    })
                    continue
                resolved.append({
                    "query": title_frag,
                    "matched": {
                        "rating_key": row["rating_key"],
                        "title": row["title"],
                        "year": row["year"],
                        "section_id": row["section_id"],
                        "media_type": row["media_type"],
                    },
                })
        # Hit Plex for each resolved rk — v1.22.57: OFF the event loop +
        # in PARALLEL. Pre-fix this ran the synchronous Plex HTTP round-
        # trips (GET /themes + a 4KB Range-GET per theme entry) directly
        # inside the async handler AND serially, so up to 8 titles ×
        # several blocking calls each FROZE the whole app for the probe's
        # duration (the v1.21.20 / v1.22.31 event-loop-block class — the
        # sibling api_admin_probe_themes got run_in_threadpool but this
        # title-fragment probe was missed) and each added title fragment
        # cost linearly more wall-clock (the user: "very slow … slower as
        # the list increases"). Now: a PlexClient pool (httpx.Client isn't
        # thread-safe for concurrent reuse → one per worker, mirrors
        # _reprobe_plex_themes_run) + a ThreadPoolExecutor so every
        # matched title probes concurrently. Safe: read-only, local Plex
        # server, capped at 8.
        from concurrent.futures import ThreadPoolExecutor
        from ..core.plex import PlexClient, PlexConfig
        cfg = PlexConfig(
            url=settings.plex_url, token=settings.plex_token,
            movie_section=settings.plex_movie_section,
            tv_section=settings.plex_tv_section, enabled=True,
        )
        matched = [r for r in resolved if r.get("matched") is not None]

        def _probe_one_title(plex, r):
            rk = r["matched"]["rating_key"]
            themes_resp = plex.get_themes(rating_key=rk)
            r["themes_response"] = themes_resp
            # Plex returns MediaContainer.Metadata as a list of entry
            # objs; each entry's `ratingKey` (the upload://themes/<sha1>
            # URI) is what we Range-GET via /file?url=<entry-rk>.
            entries_probe = []
            container = (
                (themes_resp.get("body") or {})
                .get("MediaContainer") or {}
            ) if isinstance(themes_resp.get("body"), dict) else {}
            for entry in (container.get("Metadata") or []):
                if not isinstance(entry, dict):
                    continue
                entry_rk = entry.get("ratingKey")
                if not entry_rk:
                    entries_probe.append({
                        "entry": entry,
                        "bytes_probe": {
                            "skipped": True,
                            "reason": "entry has no ratingKey",
                        },
                    })
                    continue
                bytes_probe = plex.probe_theme_entry_bytes(
                    item_rating_key=rk,
                    entry_uri=entry_rk,
                    range_bytes=4096,
                )
                # Derive the URI scheme (upload / metadata / cloud) so
                # the caller can group entries without re-parsing.
                scheme = None
                if isinstance(entry_rk, str) and "://" in entry_rk:
                    scheme = entry_rk.split("://", 1)[0]
                entries_probe.append({
                    "entry": entry,
                    "entry_rk": entry_rk,
                    "scheme": scheme,
                    "bytes_probe": bytes_probe,
                })
            r["entries_probe"] = entries_probe

        def _probe_all():
            if not matched:
                return
            n_workers = min(PROBE_MAX_WORKERS, len(matched))
            # v1.22.82: per-thread clients via threading.local — the
            # index round-robin shared a client across threads whenever
            # completion order diverged (see _reprobe_plex_themes_run).
            import threading as _threading
            _ppt_tl = _threading.local()
            clients: list[PlexClient] = []
            _ppt_lock = _threading.Lock()

            def _ppt_client() -> PlexClient:
                c = getattr(_ppt_tl, "client", None)
                if c is None:
                    c = PlexClient(
                        cfg, plus_mode=settings.plus_equiv_mode)
                    _ppt_tl.client = c
                    with _ppt_lock:
                        clients.append(c)
                return c

            # v1.22.89: one title's Plex error no longer re-raises out
            # of the futs drain and 500s the whole probe with every
            # OTHER title's finished work discarded — stamp the failure
            # on ITS row and keep the partial results.
            def _probe_one_safe(r):
                try:
                    _probe_one_title(_ppt_client(), r)
                except Exception as e:
                    log.warning(
                        "PROBE PLEX THEMES: probe failed for rk=%s: %s",
                        (r.get("matched") or {}).get("rating_key"), e)
                    r["probe_error"] = str(e)

            try:
                with ThreadPoolExecutor(max_workers=n_workers) as pool:
                    futs = [
                        pool.submit(_probe_one_safe, r) for r in matched
                    ]
                    for f in futs:
                        f.result()
            finally:
                for c in clients:
                    try:
                        c.close()
                    except Exception as e:
                        log.debug(
                            "PROBE PLEX THEMES: client close failed: %s", e)

        await run_in_threadpool(_probe_all)
        if compact:
            _compact_probe_result(resolved)
        return {
            "ok": True,
            "compact": compact,
            "probed_at": now_iso(),
            "endpoint": (
                "GET /library/metadata/{rk}/themes + "
                "GET /library/metadata/{rk}/file?url=<entry-rk>"
            ),
            "results": resolved,
        }

    @app.post("/api/admin/test-trigger-theme-lost")
    async def api_admin_test_trigger_theme_lost(
        request: Request,
        db: Path = Depends(get_db_path),
    ):
        """v1.19.41: dev-only synthesizer for the v1.18.90 reaper
        dispatch loop. Lets the operator validate the four-way
        notification split (backup_ready / sidecar_available /
        no_fallback) against ANY real row without waiting for a
        genuine Plex theme loss.

        Body: `{"rk": <rating_key>, "force_state":
        "backup" | "sidecar" | "none" | "auto"}`

        - `auto` (default): classify the row's CURRENT state via
          the same tier logic the reaper uses, fire the matching
          notification.
        - `backup`: force the tier-1 path (theme_lost_backup_ready).
          Requires the row to have either user_overrides.intent=
          'backup' OR a local_files row with source_kind=
          'plex_cloud'; otherwise 409.
        - `sidecar`: force the tier-2 path
          (theme_lost_sidecar_available). Requires sidecar
          detected on disk OR plex_items.local_theme_file=1 for
          the row's tmdb_id.
        - `none`: force the tier-4 path (plex_theme_lost / no
          fallback). Always works — synthesizes the "no backup
          configured" body against the row's title.

        Admin-gated. BYPASSES the 24h dedupe (so you can test
        repeatedly during validation). Does NOT delete the
        plex_items row — pure read-only-plus-notify.
        """
        _require_admin(request)
        try:
            body = await request.json()
        except Exception:
            raise HTTPException(
                status_code=400,
                detail="invalid JSON body",
            )
        rk = str((body or {}).get("rk") or "").strip()
        force_state = (
            (body or {}).get("force_state") or "auto"
        ).strip().lower()
        if not rk:
            raise HTTPException(
                status_code=400,
                detail="rk required (plex_items.rating_key)",
            )
        if force_state not in (
            "auto", "backup", "sidecar", "none",
        ):
            raise HTTPException(
                status_code=400,
                detail=(
                    "force_state must be one of: auto, backup, "
                    "sidecar, none"
                ),
            )
        if not settings.plex_enabled:
            raise HTTPException(
                status_code=503,
                detail="Plex disabled — notify config also needs Plex context",
            )
        # Look up the row.
        with get_conn(db) as conn:
            row = conn.execute(
                "SELECT pi.rating_key, pi.title, pi.guid_tmdb, "
                "       pi.media_type, pi.section_id, pi.theme_id, "
                "       pi.folder_path "
                "  FROM plex_items pi "
                " WHERE pi.rating_key = ?",
                (rk,),
            ).fetchone()
            if row is None:
                raise HTTPException(
                    status_code=404,
                    detail=f"no plex_items row for rk={rk!r}",
                )
            # Compute (mt, tmdb_id) — mirror the v1.19.41 Bug A
            # widening (guid_tmdb fallback to theme_id resolve).
            _row_mt = _motif_media_type(row["media_type"])
            _row_tmdb = row["guid_tmdb"]
            if _row_tmdb is None and row["theme_id"] is not None:
                _resolved = conn.execute(
                    "SELECT tmdb_id FROM themes WHERE id = ?",
                    (row["theme_id"],),
                ).fetchone()
                if _resolved is not None:
                    _row_tmdb = _resolved["tmdb_id"]
            if _row_tmdb is None:
                raise HTTPException(
                    status_code=409,
                    detail=(
                        f"row rk={rk!r} has no tmdb_id "
                        "(neither guid_tmdb nor theme_id→themes "
                        "resolves) — can't synthesize the dispatch"
                    ),
                )
            # If force_state requires a specific signal, verify
            # it's present BEFORE firing.
            if force_state in ("backup", "auto"):
                backup_signal = conn.execute(
                    "SELECT 'user_url_backup' AS src "
                    "  FROM user_overrides "
                    " WHERE media_type = ? AND tmdb_id = ? "
                    "   AND intent = 'backup' "
                    "UNION ALL "
                    "SELECT 'plex_cloud_backup' AS src "
                    "  FROM local_files "
                    " WHERE media_type = ? AND tmdb_id = ? "
                    "   AND source_kind = 'plex_cloud' "
                    "LIMIT 1",
                    (
                        _row_mt, _row_tmdb,
                        _row_mt, _row_tmdb,
                    ),
                ).fetchone()
            else:
                backup_signal = None
            if force_state in ("sidecar", "auto"):
                sidecar_db = conn.execute(
                    "SELECT 1 FROM plex_items "
                    " WHERE guid_tmdb = ? "
                    "   AND CASE media_type WHEN 'show' "
                    "         THEN 'tv' "
                    "         ELSE media_type END = ? "
                    "   AND local_theme_file = 1 "
                    "LIMIT 1",
                    (_row_tmdb, _row_mt),
                ).fetchone()
                sidecar_fs = False
                _folder_path = row["folder_path"]
                if _folder_path:
                    try:
                        sidecar_fs = (
                            Path(_folder_path) / "theme.mp3"
                        ).exists()
                    except OSError as _fe:
                        # v1.21.8 (audit LOW): breadcrumb the swallow —
                        # mirrors the identical sidecar-fs probe at
                        # plex_enum.py (v1.19.41) which logs.debug.
                        log.debug(
                            "test-trigger: sidecar-fs check raised for "
                            "%s: %s", _folder_path, _fe)
                sidecar_present = bool(sidecar_db) or sidecar_fs
            else:
                sidecar_present = False
        # Pick tier from force_state.
        if force_state == "backup":
            if backup_signal is None:
                raise HTTPException(
                    status_code=409,
                    detail=(
                        "force_state=backup requires an existing "
                        "user_overrides.intent='backup' OR "
                        "local_files.source_kind='plex_cloud' row"
                    ),
                )
            tier = "backup_ready"
            backup_source = backup_signal["src"]
        elif force_state == "sidecar":
            if not sidecar_present:
                raise HTTPException(
                    status_code=409,
                    detail=(
                        "force_state=sidecar requires "
                        "plex_items.local_theme_file=1 OR a "
                        "theme.mp3 file at the row's folder_path"
                    ),
                )
            tier = "sidecar_available"
            backup_source = None
        elif force_state == "none":
            tier = "no_fallback"
            backup_source = None
        else:  # auto
            if backup_signal is not None:
                tier = "backup_ready"
                backup_source = backup_signal["src"]
            elif sidecar_present:
                tier = "sidecar_available"
                backup_source = None
            else:
                tier = "no_fallback"
                backup_source = None
        # Dispatch — bypasses dedupe (test-only).
        from ..core import notify as _notify
        from ..core import notify_content as _nc
        try:
            _ctx = _nc.enrich_item(
                db,
                media_type=_row_mt, tmdb_id=_row_tmdb,
                section_id=row["section_id"],
                # v0.51.123: mirror the live plex_enum dispatch — a TDB-less
                # lost row has no `themes` title, so pass plex_items.title so
                # the test-trigger subject names the row like production does.
                fallback_title=row["title"] or "",
            )
            if tier == "backup_ready":
                _event_kind = "theme_lost_backup_ready"
                _title = _nc.format_theme_lost_backup_ready_title(_ctx)
                _body = _nc.format_theme_lost_backup_ready_body(
                    _ctx,
                    backup_source=backup_source,
                    sidecar_present=sidecar_present,
                )
            elif tier == "sidecar_available":
                _event_kind = "theme_lost_sidecar_available"
                _title = _nc.format_theme_lost_sidecar_available_title(
                    _ctx
                )
                _body = _nc.format_theme_lost_sidecar_available_body(
                    _ctx
                )
            else:
                _event_kind = "plex_theme_lost"
                _title = _nc.format_plex_theme_lost_title(_ctx)
                _body = _nc.format_plex_theme_lost_body(_ctx)
            _notify.dispatch(
                db,
                settings.cfg.notifications,
                event_kind=_event_kind,
                title=_title,
                body=_body,
                body_format="markdown",
                # v1.23.75: mirror prod's FB-thumb attachment so the test-
                # trigger preview matches the real reaper dispatch.
                attach_url=_nc.attachment_thumb_url(_ctx),
            )
        except Exception as exc:  # noqa: BLE001
            raise HTTPException(
                status_code=502,
                detail=(
                    f"notify dispatch failed: "
                    f"{type(exc).__name__}: {exc}"
                ),
            )
        log_event(
            db, level="INFO", component="api",
            media_type=_row_mt, tmdb_id=_row_tmdb,
            section_id=row["section_id"],
            message=(
                f"test-trigger-theme-lost fired by "
                f"{request.state.principal.username}: tier={tier} "
                f"rk={rk!r} title={row['title']!r}"
            ),
        )
        return {
            "ok": True,
            "rk": rk,
            "title": row["title"],
            "media_type": _row_mt,
            "tmdb_id": _row_tmdb,
            "tier": tier,
            "event_kind": _event_kind,
            "force_state": force_state,
            "backup_source": backup_source,
            "sidecar_present": sidecar_present,
        }

    @app.post("/api/admin/cloud-themes-backup-dry-run")
    async def api_admin_cloud_themes_backup_dry_run(
        request: Request,
        db: Path = Depends(get_db_path),
    ):
        """v1.19.42: read-only walk that classifies every
        plex_items.has_theme=1 P-row against Plex's /themes
        endpoint and returns the C1 target set (rows where
        Plex's cloud catalog is the SOLE source of the bytes).

        Body (optional): `{"only_anime": true}` to scope the
        walk to anime sections (100% C1 hit rate per the
        2026-05-26 probe — best ROI cohort).

        Returns: `{ok, c1_count, c1_rows: [...], total_bytes_est,
                  anime_subset_count}`. The `total_bytes_est` is
        best-effort (uses an average from the probe — actual
        download size lands per-row when the run endpoint fires).

        Resumable: shares the runtime_settings cursor with the
        run endpoint. A dry-run followed by a run picks up at
        the cursor — DOES NOT re-walk the catalog.
        """
        _require_admin(request)
        if not settings.plex_enabled or not settings.plex_token:
            raise HTTPException(
                status_code=503,
                detail="Plex disabled or token missing",
            )
        # v1.19.44: fail-fast on malformed JSON. Pre-fix bare
        # `except: body = {}` would silently run the FULL ~3,883-
        # row catalog walk when the operator meant to scope.
        # Dry-run is read-only so over-scope is only Plex API
        # hits + time, but the symmetric pattern is in the run
        # endpoint below which has write side-effects — keep
        # both consistent. Class-9 silent-data-overscope sub-pattern.
        # Tolerate empty body (no JSON at all) as the documented
        # "walk everything" sentinel; only reject malformed JSON
        # that DID arrive.
        body: dict = {}
        try:
            raw = await request.body()
            if raw:
                body = await request.json()
        except Exception as _e:
            raise HTTPException(
                status_code=400,
                detail=(
                    f"malformed JSON body: {type(_e).__name__}: "
                    f"{_e}"
                ),
            )
        only_anime = bool((body or {}).get("only_anime", False))
        from ..core.plex import PlexClient, PlexConfig
        from ..core.cloud_theme_backup import identify_c1_rows
        cfg = PlexConfig(
            url=settings.plex_url, token=settings.plex_token,
            movie_section=settings.plex_movie_section,
            tv_section=settings.plex_tv_section, enabled=True,
        )
        # v1.21.20: same event-loop-block fix as orphan-scan. identify_c1_rows
        # walks has_theme=1 rows hitting Plex /themes per row AND holds a DB
        # conn open for the whole (potentially minutes-long) walk — running it
        # inline froze the UI. Offload the entire blocking block.
        def _run_dry_run():
            with PlexClient(
                cfg, plus_mode=settings.plus_equiv_mode,
            ) as plex, get_conn(db) as conn:
                return identify_c1_rows(
                    conn, plex, only_anime=only_anime,
                    use_cursor=False,
                )
        targets = await run_in_threadpool(_run_dry_run)
        # v1.19.42: ~2.2 MB mean per the 2026-05-26 probe (n=8
        # successful fetches, range 255KB - 8.6MB). Best-effort
        # estimate — actual size lands per-row when run fires.
        avg_mb = 2.2
        total_bytes_est = int(len(targets) * avg_mb * 1024 * 1024)
        return {
            "ok": True,
            "c1_count": len(targets),
            "c1_rows": targets,
            "total_bytes_est": total_bytes_est,
            "only_anime": only_anime,
        }

    @app.post("/api/admin/cloud-themes-backup-run")
    async def api_admin_cloud_themes_backup_run(
        request: Request,
        db: Path = Depends(get_db_path),
    ):
        """v1.19.42 / v1.19.45: kick off a background cloud-themes-
        backup walk + download. Returns immediately with the op_id;
        progress surfaces in the ops drawer + topbar mini-bar.

        Body (optional):
          - `{"rks": [<rk>, ...]}` to scope to specific rows
            (bulk-bar selection or single-row SOURCE menu).
          - `{"only_anime": true}` to scope to anime sections.
          - Empty body: walk the full P-row catalog.

        Per-row audit + log_event happen inside the worker thread.
        Idempotent on retry — ON CONFLICT updates the existing
        local_files row.

        v1.19.45: converted from sync-inline (which blocked the
        FastAPI event loop for the full 13min+ walk + downloads;
        the user's repro: clicked BACKUP THIS THEME → entire UI
        locked up → browser timed out with "Failed to fetch")
        to the acquire-then-spawn-thread pattern bulk_lps /
        bulk_probe_tdb / tvdb_bridge already use.

        Returns: `{ok, op_id, scope}`. Poll
        /api/op-progress?op_id=cloud-themes-backup for status.
        """
        _require_admin(request)
        if not settings.plex_enabled or not settings.plex_token:
            raise HTTPException(
                status_code=503,
                detail="Plex disabled or token missing",
            )
        # v1.19.44: fail-fast on malformed JSON BEFORE the
        # themes_dir gate. Pre-fix bare `except: body = {}` would
        # silently run the FULL ~3,883-row catalog walk when the
        # operator meant to scope.
        body: dict = {}
        try:
            raw = await request.body()
            if raw:
                body = await request.json()
        except Exception as _e:
            raise HTTPException(
                status_code=400,
                detail=(
                    f"malformed JSON body: {type(_e).__name__}: "
                    f"{_e}"
                ),
            )
        if not settings.themes_dir:
            raise HTTPException(
                status_code=503,
                detail="themes_dir not configured — visit /settings",
            )
        rks_scope = (body or {}).get("rks") or None
        only_anime = bool((body or {}).get("only_anime", False))
        # v1.19.62: allow_existing_local enables the SOURCE-menu
        # DOWNLOAD PLEX BACKUP action on PS-with-DL rows (Plex
        # serves, motif has a non-plex_cloud canonical). The
        # walker drops its NOT-EXISTS-local_files filter so PS rows
        # become C1 candidates; the writer's ON CONFLICT clause
        # REPLACES the existing local_files row with the plex_cloud
        # bytes. Rows already source_kind='plex_cloud' are filtered
        # out (no-op). the user's "86 EIGHTY-SIX" repro extended this
        # action to PS-with-TDB rows.
        allow_existing_local = bool(
            (body or {}).get("allow_existing_local", False))
        # v1.20.18: force capture — stage WHATEVER Plex is currently
        # serving for the row (the selected /themes entry, any scheme,
        # incl upload://), not just a cloud metadata:// entry. Invoked
        # by the SOURCE-menu confirm-retry after a strict run found no
        # C1 target. Implies allow_existing_local (we're swapping an
        # existing TB/UB backup). The backup_cloud_theme sha256 dedup
        # guard skips the swap when the served bytes are identical to
        # the existing canonical (Plex echoing motif's own upload).
        force = bool((body or {}).get("force", False))
        if force:
            allow_existing_local = True
        if rks_scope is not None:
            if not isinstance(rks_scope, list):
                raise HTTPException(
                    status_code=400,
                    detail="rks must be a list of rating_keys",
                )
            rks_scope = [str(rk) for rk in rks_scope if rk]
        # v1.19.45: acquire the op_progress slot atomically so
        # concurrent clicks 409 instead of double-walking.
        from ..core import progress as op_progress
        OP_ID = "cloud-themes-backup"
        acquired = op_progress.try_acquire(
            db, op_id=OP_ID, kind="cloud_themes_backup",
        )
        if not acquired:
            raise HTTPException(
                status_code=409,
                detail=(
                    "another cloud-themes-backup run is already "
                    "in flight — wait for it to complete or cancel "
                    "via the ops drawer"
                ),
            )
        actor = request.state.principal.username
        log_event(
            db, level="INFO", component="api",
            message=(
                f"CLOUD THEMES BACKUP started by {actor} "
                f"(scope={'rks=' + str(len(rks_scope)) if rks_scope else 'all'}, "
                f"only_anime={only_anime}, "
                f"allow_existing_local={allow_existing_local}, "
                f"force={force})"
            ),
        )
        import threading
        t = threading.Thread(
            target=_cloud_themes_backup_run,
            args=(db, settings),
            kwargs={
                "rks_scope": rks_scope,
                "only_anime": only_anime,
                "actor": actor,
                "allow_existing_local": allow_existing_local,
                "force": force,
            },
            name="cloud-themes-backup",
            daemon=True,
        )
        t.start()
        return {
            "ok": True,
            "op_id": OP_ID,
            "scope": {
                "rks": rks_scope,
                "only_anime": only_anime,
            },
        }

    # v1.23.15: on-disk database backups. the user: "create a new
    # settings feature to backup the database." A consistent snapshot
    # of motif.db (VACUUM INTO, see db_backup.py) written to
    # /config/backups; the // DATABASE settings card creates, lists,
    # downloads + deletes them.
    @app.post("/api/admin/database-backup")
    async def api_admin_database_backup_create(request: Request):
        """Create a fresh VACUUM INTO snapshot of motif.db. Offloaded
        to a thread (VACUUM holds a read txn + writes the whole DB —
        seconds on a large DB; blocking the event loop would freeze
        every concurrent request, class-12)."""
        _require_admin(request)
        # UTC stamp minted here so db_backup stays clock-free (testable).
        from datetime import datetime, timezone
        stamp = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")
        try:
            bf = await run_in_threadpool(
                db_backup.create_backup,
                settings.db_path, settings.config_dir, now_stamp=stamp,
            )
        except FileExistsError:
            raise HTTPException(
                status_code=409,
                detail="a backup for this second already exists — retry",
            )
        except FileNotFoundError as e:
            raise HTTPException(status_code=503, detail=str(e))
        log_event(
            settings.db_path, level="info", component="backup",
            message=f"Database backup created: {bf.name}",
            detail={"name": bf.name, "size": bf.size},
        )
        return {
            "ok": True,
            "backup": {
                "name": bf.name, "size": bf.size,
                "created_at": bf.created_at,
            },
        }

    @app.get("/api/admin/database-backups")
    async def api_admin_database_backups_list(request: Request):
        """List existing backups (newest first) + the dir they live
        in. FS work is a cheap iterdir+stat but offload anyway to
        keep the event loop clean."""
        _require_admin(request)
        backups = await run_in_threadpool(
            db_backup.list_backups, settings.config_dir,
        )
        return {
            "ok": True,
            "dir": str(db_backup.backups_dir(settings.config_dir)),
            "backups": [
                {"name": b.name, "size": b.size, "created_at": b.created_at}
                for b in backups
            ],
        }

    @app.get("/api/admin/database-backup/download/{name}")
    async def api_admin_database_backup_download(request: Request, name: str):
        """Stream one backup file. resolve_backup re-validates the
        name against the motif-<ts>.db pattern, so a crafted path
        can't escape the backups dir or address an arbitrary file."""
        _require_admin(request)
        path = db_backup.resolve_backup(settings.config_dir, name)
        if path is None:
            raise HTTPException(status_code=404, detail="backup not found")
        return FileResponse(
            path, media_type="application/octet-stream",
            filename=name,
            headers={"Cache-Control": "no-store"},
        )

