    async def api_admin_database_backup_delete(request: Request):
        """Delete one backup by name (body: {"name": "motif-...db"})."""
        _require_admin(request)
        try:
            body = await request.json()
        except Exception:
            raise HTTPException(status_code=400, detail="invalid JSON body")
        name = (body or {}).get("name") or ""
        try:
            deleted = await run_in_threadpool(
                db_backup.delete_backup, settings.config_dir, name,
            )
        except ValueError:
            raise HTTPException(status_code=400, detail="invalid backup name")
        if not deleted:
            raise HTTPException(status_code=404, detail="backup not found")
        log_event(
            settings.db_path, level="info", component="backup",
            message=f"Database backup deleted: {name}",
            detail={"name": name},
        )
        return {"ok": True, "deleted": name}

    # v1.23.17: database RESTORE. A restore STAGES the chosen snapshot;
    # the actual swap happens at the next boot (db_backup.
    # apply_pending_restore in main.py) — clean, with no open FDs and
    # the current db safety-copied first. So every restore endpoint
    # returns restart_required=True.
    def _stage_restore_response(check):
        return {
            "ok": True,
            "restart_required": True,
            "schema_version": check.schema_version,
            "message": ("Restore staged. Restart the motif container to "
                        "apply it — the current database is backed up "
                        "automatically just before the swap."),
        }

    @app.post("/api/admin/database-restore")
    async def api_admin_database_restore_from_backup(request: Request):
        """Stage a restore from an EXISTING server-side snapshot
        (body: {"name": "motif-...db"})."""
        _require_admin(request)
        try:
            body = await request.json()
        except Exception:
            raise HTTPException(status_code=400, detail="invalid JSON body")
        name = (body or {}).get("name") or ""
        src = db_backup.resolve_backup(settings.config_dir, name)
        if src is None:
            raise HTTPException(status_code=404, detail="backup not found")
        try:
            check = await run_in_threadpool(
                db_backup.stage_restore, settings.db_path, src)
        except ValueError as e:
            raise HTTPException(status_code=422, detail=str(e))
        log_event(
            settings.db_path, level="warning", component="backup",
            message=f"Database restore staged from {name} "
                    f"(schema v{check.schema_version}); applies on restart",
            detail={"name": name, "schema_version": check.schema_version},
        )
        return _stage_restore_response(check)

    @app.post("/api/admin/database-restore/upload")
    async def api_admin_database_restore_upload(request: Request):
        """Stage a restore from an UPLOADED .db file (multipart 'file').
        For disaster recovery — restoring an off-box copy."""
        _require_admin(request)
        form = await request.form()
        upload = form.get("file")
        if upload is None or not hasattr(upload, "read"):
            raise HTTPException(status_code=400,
                                detail="multipart 'file' required")
        # v1.23.18 (code review): read in chunks with a running cap so
        # an oversized upload is rejected BEFORE it's fully resident.
        # Pre-fix `data = await upload.read()` materialized the entire
        # body (multi-GB) in RAM and only THEN checked the 500 MiB cap —
        # the cap couldn't prevent the OOM it was written to prevent.
        _CAP = 500 * 1024 * 1024
        _buf = bytearray()
        while True:
            chunk = await upload.read(4 * 1024 * 1024)
            if not chunk:
                break
            _buf += chunk
            if len(_buf) > _CAP:
                raise HTTPException(status_code=413, detail="file > 500 MiB")
        data = bytes(_buf)
        if not data:
            raise HTTPException(status_code=400, detail="empty file")

        def _stage_uploaded() -> "db_backup.RestoreCheck":
            import os
            import tempfile as _tf
            fd, tmp = _tf.mkstemp(prefix=".restore-upload.", suffix=".db",
                                  dir=str(settings.config_dir))
            try:
                with os.fdopen(fd, "wb") as f:
                    f.write(data)
                return db_backup.stage_restore(settings.db_path, Path(tmp))
            finally:
                try: os.unlink(tmp)
                except OSError: pass

        try:
            check = await run_in_threadpool(_stage_uploaded)
        except ValueError as e:
            raise HTTPException(status_code=422, detail=str(e))
        log_event(
            settings.db_path, level="warning", component="backup",
            message=f"Database restore staged from upload "
                    f"(schema v{check.schema_version}); applies on restart",
            detail={"schema_version": check.schema_version},
        )
        return _stage_restore_response(check)

