    @app.get("/api/admin/edition-diagnostics")
    async def api_admin_edition_diagnostics(
        request: Request,
        db: Path = Depends(get_db_path),
    ):
        """v1.21.96 (Phase 0): read-only characterization of every
        multi-edition title so we can pick the per-edition theme
        independence architecture from real on-disk data, not guesses.

        For each (guid_tmdb, media_type, section_id) with >1 distinct
        edition_key in plex_items, report: each rk's folder_path +
        edition_key + theme state; whether the editions live in DISTINCT
        {edition-X} folders or SHARE one physical folder; the on-disk
        theme.mp3 size (flagged over Plex's ~10MB upload ceiling); the
        current placements/local_files edition_keys; and whether the
        placement/local_files are mis-keyed at '' while plex_items is
        tagged (the Watchmen/Godzilla shape).

        Read-only. FS stats run off the event loop (the v1.21.20 pattern)
        because folder_path/theme.mp3 live on the /data mount.
        """
        _require_admin(request)
        # ~Plex theme-upload ceiling: uploads over this 500 (LotR 10.2MB,
        # Watchmen 15.3MB) → per-rk uploads can't theme those editions.
        ceiling = 10 * 1024 * 1024

        def _run():
            from ..core.editions import edition_label_for_folder
            out: list[dict] = []
            with get_conn(db) as conn:
                titles = conn.execute(
                    "SELECT guid_tmdb, media_type, section_id, "
                    "       COUNT(DISTINCT edition_key) AS n_ed "
                    "FROM plex_items WHERE guid_tmdb IS NOT NULL "
                    "GROUP BY guid_tmdb, media_type, section_id "
                    "HAVING COUNT(DISTINCT edition_key) > 1 "
                    "ORDER BY guid_tmdb",
                ).fetchall()
                for t in titles:
                    gt, mt, sid = t["guid_tmdb"], t["media_type"], t["section_id"]
                    items = conn.execute(
                        "SELECT rating_key, edition_key, folder_path, has_theme, "
                        "       local_theme_file, plex_theme_verified_ok, "
                        "       title, year FROM plex_items "
                        "WHERE guid_tmdb=? AND media_type=? AND section_id=? "
                        "ORDER BY edition_key", (gt, mt, sid),
                    ).fetchall()
                    folders = [(it["folder_path"] or "") for it in items]
                    non_empty = [f for f in folders if f]
                    has_dup = len(set(non_empty)) < len(non_empty)
                    all_unique = (len(non_empty) == len(items)
                                  and len(set(non_empty)) == len(items))
                    verdict = ("shared-folder" if has_dup
                               else "distinct-folders" if all_unique
                               else "mixed")
                    rks: list[dict] = []
                    max_theme = 0
                    for it in items:
                        fp = it["folder_path"] or ""
                        present = False
                        size = None
                        folder_exists = False
                        stat_error = None
                        if fp:
                            try:
                                folder_exists = Path(fp).is_dir()
                                tp = Path(fp) / "theme.mp3"
                                if tp.is_file():
                                    present = True
                                    size = tp.stat().st_size
                                    max_theme = max(max_theme, size)
                            except OSError as _e:
                                # v1.22.0 (line-close audit): don't swallow —
                                # a permission/mount error must be distinguishable
                                # from "no theme" in a diagnostic whose whole job
                                # is reading on-disk truth.
                                stat_error = str(_e)
                                log.debug("edition-diag: stat failed for %s: %s",
                                          fp, _e)
                        rks.append({
                            "rating_key": it["rating_key"],
                            "edition_key": it["edition_key"],
                            "edition_label": edition_label_for_folder(fp),
                            "folder_path": fp,
                            "folder_exists": folder_exists,
                            "has_theme": bool(it["has_theme"]),
                            "verified_ok": it["plex_theme_verified_ok"],
                            "local_theme_file": bool(it["local_theme_file"]),
                            "theme_mp3_present": present,
                            "theme_mp3_size": size,
                            "stat_error": stat_error,
                        })
                    placements = [dict(r) for r in conn.execute(
                        "SELECT edition_key, media_folder, placement_kind "
                        "FROM placements WHERE media_type=? AND tmdb_id=? "
                        "AND section_id=? ORDER BY edition_key",
                        (mt, gt, sid))]
                    local_files = [dict(r) for r in conn.execute(
                        "SELECT edition_key, file_path, file_size, source_kind "
                        "FROM local_files WHERE media_type=? AND tmdb_id=? "
                        "AND section_id=? ORDER BY edition_key",
                        (mt, gt, sid))]
                    pi_eds = {it["edition_key"] for it in items}
                    p_eds = {p["edition_key"] for p in placements}
                    lf_eds = {lf["edition_key"] for lf in local_files}
                    # mis-keyed: a placement/local_files sits at '' but no
                    # plex_items edition IS '' (all editions tagged) — the
                    # historical shared-'' row the per-edition arc must re-key.
                    miskey = ("" not in pi_eds
                              and ("" in p_eds or "" in lf_eds))
                    rec = {
                        "guid_tmdb": gt, "media_type": mt, "section_id": sid,
                        "title": items[0]["title"], "year": items[0]["year"],
                        "edition_count": t["n_ed"],
                        "folder_verdict": verdict,
                        "theme_over_ceiling": max_theme > ceiling,
                        "max_theme_mp3_size": max_theme or None,
                        "empty_edition_miskey": miskey,
                        "editions": rks,
                        "placements": placements,
                        "local_files": local_files,
                    }
                    out.append(rec)
                    log_event(
                        db, level="INFO", component="edition_diag",
                        media_type=mt, tmdb_id=gt, section_id=sid,
                        message=(f"edition-diag {items[0]['title']}: {verdict}, "
                                 f"{t['n_ed']} editions, miskey={miskey}, "
                                 f"over_ceiling={max_theme > ceiling}"),
                    )
            summary = {
                "multi_edition_titles": len(out),
                "distinct_folder_titles": sum(
                    1 for r in out if r["folder_verdict"] == "distinct-folders"),
                "shared_folder_titles": sum(
                    1 for r in out if r["folder_verdict"] == "shared-folder"),
                "mixed_titles": sum(
                    1 for r in out if r["folder_verdict"] == "mixed"),
                "empty_miskey_titles": sum(
                    1 for r in out if r["empty_edition_miskey"]),
                "shared_folder_over_ceiling": sum(
                    1 for r in out if r["folder_verdict"] == "shared-folder"
                    and r["theme_over_ceiling"]),
            }
            return {"ok": True, "ceiling_bytes": ceiling,
                    "summary": summary, "titles": out}

        return await run_in_threadpool(_run)

    @app.post("/api/admin/orphan-scan/start")
    async def api_admin_orphan_scan_start(
        request: Request, db: Path = Depends(get_db_path),
    ):
        """v1.21.24: kick off the orphan scan as a page-scoped background op.
        Returns immediately; the orphans page polls
        /api/admin/orphan-scan/status for live progress + findings.

        Converted from the old synchronous GET (v1.18.37), which ran the
        whole per-row Plex /themes walk inside the request — so it showed no
        progress, and the browser aborted it (losing the result) the moment
        you navigated away. The work now runs in a daemon thread independent
        of the request/tab. Read-only diagnostic; no mutations."""
        _require_admin(request)
        if not settings.plex_enabled or not settings.plex_token:
            raise HTTPException(
                status_code=503, detail="Plex disabled or token missing")
        with _ORPHAN_SCAN_LOCK:
            if _ORPHAN_SCAN_STATE.get("status") == "running":
                return {"ok": True, "started": False, "already_running": True}
            _ORPHAN_SCAN_STATE.clear()
            _ORPHAN_SCAN_STATE.update(
                status="running", done=0, total=0, findings=None,
                summary=None, scanned_at=None, error=None,
            )
        t = threading.Thread(
            target=_orphan_scan_run, args=(settings, db),
            name="orphan-scan", daemon=True,
        )
        t.start()
        return {"ok": True, "started": True}

    @app.get("/api/admin/orphan-scan/status")
    async def api_admin_orphan_scan_status(request: Request):
        """v1.21.24: current orphan-scan state for the orphans page poll +
        on-load restore. `findings` + `summary` are populated only when
        status=='done' (so the running-poll stays light)."""
        _require_admin(request)
        with _ORPHAN_SCAN_LOCK:
            return dict(_ORPHAN_SCAN_STATE)

