    @app.post("/api/admin/mp3gain-probe")
    async def api_admin_mp3gain_probe(
        request: Request, db: Path = Depends(get_db_path),
    ):
        """v0.51.164: characterize mp3gain before Phase-1 normalization is built on it.
        Picks one measured local-bytes theme, and (on a THROWAWAY COPY, never the real
        file) proves apply→undo restores the AUDIO bit-exactly. v0.51.165: the criterion is
        decoded PCM, not whole-file bytes — mp3gain appends an APE undo tag so the file
        always differs even when the samples are restored. Read-only wrt every real theme.
        Off-loaded to a thread (subprocess + decode/hash would block the event loop —
        CLAUDE.md class-12)."""
        _require_admin(request)
        from ..core.loudness_apply import probe_mp3gain
        from ..core.db import get_conn

        def _run():
            with get_conn(db) as conn:
                row = conn.execute(
                    "SELECT file_path FROM local_files "
                    "WHERE loudness_i IS NOT NULL AND file_path IS NOT NULL "
                    "  AND file_path != '' ORDER BY tmdb_id LIMIT 1"
                ).fetchone()
            if row is None:
                return {"ok": False, "error": "no measured theme to probe — run the "
                        "LOUDNESS AUDIT first"}
            fp = Path(row["file_path"])
            # v0.51.169: themes_dir is None until configured (config.py: "None if not yet
            # set on first run") — joining it would TypeError into a 500.
            if not fp.is_absolute() and settings.themes_dir is None:
                return {"ok": False, "error": "themes_dir is not configured — set it in "
                        "Settings first"}
            theme = fp if fp.is_absolute() else (settings.themes_dir / row["file_path"])
            return probe_mp3gain(theme)

        return await run_in_threadpool(_run)

    @app.post("/api/admin/loudness/normalize-one")
    async def api_admin_loudness_normalize_one(
        request: Request, db: Path = Depends(get_db_path),
    ):
        """v0.51.168: normalize ONE canonical theme toward the target LUFS via mp3gain —
        the FIRST tag that mutates a theme (proven bit-exact-reversible by // PROBE
        MP3GAIN). Reads the row, applies gain, RE-MEASURES, and stamps the edition-scoped
        local_files PK. With no body it auto-picks the loudest measured, un-normalized,
        HARDLINK-placed row: a hardlink shares the canonical inode with the Plex sidecar,
        so Plex plays the normalized theme immediately + undo is fully live (the honest
        'audition'). A body may name a specific row. Fully reversible via undo-one.
        Threadpool (subprocess + hash + re-measure block the loop — class-12)."""
        _require_admin(request)
        from ..core.loudness_apply import normalize_file
        from ..core.db import get_conn
        from ..core.events import now_iso

        try:
            body = await request.json()
        except Exception:  # noqa: BLE001 — auto-pick allows an empty body
            body = {}
        if not isinstance(body, dict):
            body = {}   # v0.51.169: a list/str body would AttributeError on .get → 500
        try:
            target = float(body.get("target")) if body.get("target") is not None else -18.0
        except (TypeError, ValueError):
            target = -18.0
        target = max(-31.0, min(-6.0, target))   # clamp to a sane hover band
        want_mt = body.get("media_type")
        want_id = body.get("tmdb_id")

        def _run():
            with get_conn(db) as conn:
                cols = ("lf.media_type, lf.tmdb_id, lf.section_id, lf.edition_key, "
                        "lf.file_path, lf.file_sha256, lf.loudness_measured_sha256, "
                        "lf.loudness_i, lf.loudness_tp, lf.norm_state, t.title, t.year")
                if want_id is not None and want_mt:
                    row = conn.execute(
                        f"SELECT {cols} FROM local_files lf "
                        "LEFT JOIN themes t ON t.media_type=lf.media_type AND t.tmdb_id=lf.tmdb_id "
                        "WHERE lf.media_type=? AND lf.tmdb_id=? AND lf.section_id=? "
                        "  AND lf.edition_key=?",
                        (want_mt, want_id, body.get("section_id") or "",
                         body.get("edition_key") or ""),
                    ).fetchone()
                else:
                    # auto-pick: loudest measured, RAW, HARDLINK-placed row whose
                    # measurement is CURRENT for its bytes. v0.51.169: the
                    # loudness_measured_sha256 = file_sha256 key is the same staleness
                    # test rows_needing_measure uses — dropping it here let a re-download
                    # since the audit drive the gain off a stale loudness.
                    row = conn.execute(
                        f"SELECT {cols} FROM local_files lf "
                        "JOIN placements p ON p.media_type=lf.media_type "
                        "  AND p.tmdb_id=lf.tmdb_id AND p.section_id=lf.section_id "
                        "  AND p.edition_key=lf.edition_key AND p.placement_kind='hardlink' "
                        "LEFT JOIN themes t ON t.media_type=lf.media_type AND t.tmdb_id=lf.tmdb_id "
                        "WHERE lf.loudness_i IS NOT NULL AND lf.loudness_i > -1e30 "
                        "  AND lf.norm_state IS NULL "
                        "  AND lf.file_sha256 IS NOT NULL "
                        "  AND lf.loudness_measured_sha256 = lf.file_sha256 "
                        # v0.51.177: don't audition a theme we can't propagate. The first
                        # real audition picked the loudest row — which was 10.5MB, over
                        # Plex's upload ceiling — so it was a dead end before it started.
                        "  AND lf.file_size IS NOT NULL "
                        "  AND lf.file_size <= " + str(THEME_UPLOAD_CEILING_BYTES) + " "
                        "ORDER BY lf.loudness_i DESC LIMIT 1",
                    ).fetchone()
                if row is None:
                    return {"ok": False, "error": "no eligible theme to normalize — needs a "
                            "measured (current) hardlink-placed raw row; run the LOUDNESS "
                            "AUDIT first"}
                if row["loudness_i"] is None:
                    return {"ok": False, "error": "target row has no loudness measurement"}
                if row["norm_state"] == "normalized":
                    return {"ok": False, "error": "already normalized — undo it first"}
                # v0.51.169: same staleness gate for a body-named row (the auto-pick does
                # it in SQL). A measurement taken at different bytes yields the wrong gain.
                if (row["file_sha256"] is None
                        or row["loudness_measured_sha256"] != row["file_sha256"]):
                    return {"ok": False, "error": "loudness measurement is stale for the "
                            "current bytes — re-run the LOUDNESS AUDIT first"}
                fp = Path(row["file_path"])
                # v0.51.169: themes_dir is None until configured — guard the join (500).
                if not fp.is_absolute() and settings.themes_dir is None:
                    return {"ok": False, "error": "themes_dir is not configured — set it "
                            "in Settings first"}
                theme = fp if fp.is_absolute() else (settings.themes_dir / row["file_path"])

            # expect_sha: refuse if the bytes on disk aren't the ones we measured (the
            # DB row could have been stamped before an out-of-band replace).
            res = normalize_file(theme, target, row["loudness_i"], row["loudness_tp"],
                                 expect_sha=row["file_sha256"])
            if not res["ok"]:
                return {"ok": False, "error": res.get("error") or "normalize failed",
                        "title": row["title"]}
            if res["changed"]:
                # loudness cols reflect the re-measure; if it failed (None), NULL the
                # measured_sha too so the audit re-measures rather than trusting a gap.
                measured_sha = res["new_sha"] if res["new_i"] is not None else None
                ts = now_iso()   # v0.51.169: one instant for one operation
                measured_at = ts if res["new_i"] is not None else None
                with get_conn(db) as wconn:
                    # v0.51.169: `AND norm_state IS NULL` makes the WRITE the guard, not
                    # the earlier read on a since-closed connection. If two normalizes
                    # race, only the first stamps norm_orig_sha256 — so it keeps the TRUE
                    # pre-normalize sha and undo still verifies bit-exact (mp3gain's undo
                    # tag accumulates, so -u reverses BOTH applications).
                    cur = wconn.execute(
                        "UPDATE local_files SET loudness_i=?, loudness_tp=?, loudness_lra=?, "
                        "  loudness_measured_at=?, loudness_measured_sha256=?, file_sha256=?, "
                        "  norm_state='normalized', norm_gain_db=?, norm_target=?, norm_at=?, "
                        "  norm_orig_sha256=?, norm_orig_pcm_sha256=? "
                        "WHERE media_type=? AND tmdb_id=? AND section_id=? AND edition_key=? "
                        "  AND norm_state IS NULL",
                        (res["new_i"], res["new_tp"], res["new_lra"], measured_at,
                         measured_sha, res["new_sha"], res["applied_db"], target, ts,
                         res["old_sha"], res["old_pcm_sha"],
                         row["media_type"], row["tmdb_id"],
                         row["section_id"], row["edition_key"]),
                    )
                    wconn.commit()
                    if cur.rowcount == 0:
                        # another normalize claimed this row while ours was in flight —
                        # say so instead of reporting a success whose numbers are wrong.
                        log.warning("loudness normalize: lost the race on %s/%s — the row "
                                    "was already normalized; gain was applied twice and "
                                    "should be undone", row["media_type"], row["tmdb_id"])
                        return {"ok": False, "changed": True, "title": row["title"],
                                "error": "another normalize won the race for this theme — "
                                         "it may now be double-adjusted; press // UNDO"}
            return {
                "ok": True, "changed": res["changed"], "note": res.get("note"),
                "title": row["title"] or f'{row["media_type"]}/{row["tmdb_id"]}',
                "year": row["year"], "target": target, "steps": res["steps"],
                "applied_db": res["applied_db"],
                "before": {"loudness_i": row["loudness_i"], "true_peak": row["loudness_tp"]},
                "after": {"loudness_i": res["new_i"], "true_peak": res["new_tp"]},
                "row": {"media_type": row["media_type"], "tmdb_id": row["tmdb_id"],
                        "section_id": row["section_id"], "edition_key": row["edition_key"]},
            }

        return await run_in_threadpool(_run)

    @app.get("/api/admin/loudness/normalized")
    async def api_admin_loudness_normalized(
        request: Request, db: Path = Depends(get_db_path),
    ):
        """v0.51.169: the currently-normalized theme (most recent), so // AUDITION
        NORMALIZE can re-arm its // UNDO after a page reload. Pre-fix the undo target
        lived only in a JS variable, so reloading the page stranded a normalized theme
        with no UI path back — which breaks the audition's whole promise. Pure read."""
        _require_admin(request)
        from ..core.db import get_conn

        def _run():
            with get_conn(db) as conn:
                row = conn.execute(
                    "SELECT lf.media_type, lf.tmdb_id, lf.section_id, lf.edition_key, "
                    "  lf.norm_gain_db, lf.norm_target, lf.norm_at, lf.loudness_i, "
                    "  t.title FROM local_files lf "
                    "LEFT JOIN themes t ON t.media_type=lf.media_type AND t.tmdb_id=lf.tmdb_id "
                    "WHERE lf.norm_state = 'normalized' "
                    "ORDER BY lf.norm_at DESC LIMIT 1"
                ).fetchone()
                total = conn.execute(
                    "SELECT COUNT(*) FROM local_files WHERE norm_state = 'normalized'"
                ).fetchone()[0]
            if row is None:
                return {"normalized": None, "count": 0}
            return {
                "count": total,
                "normalized": {
                    "title": row["title"] or f'{row["media_type"]}/{row["tmdb_id"]}',
                    "loudness_i": row["loudness_i"], "norm_gain_db": row["norm_gain_db"],
                    "norm_target": row["norm_target"], "norm_at": row["norm_at"],
                    "row": {"media_type": row["media_type"], "tmdb_id": row["tmdb_id"],
                            "section_id": row["section_id"],
                            "edition_key": row["edition_key"]},
                },
            }

        return await run_in_threadpool(_run)

    @app.post("/api/admin/loudness/plex-serving")
    async def api_admin_loudness_plex_serving(
        request: Request, db: Path = Depends(get_db_path),
    ):
        """v0.51.171: MEASURE what Plex is actually serving for a normalized theme, instead
        of judging by ear.

        v0.51.168's audition claimed "hardlink → Plex plays the normalized theme
        immediately". The inode reasoning is right but the premise may not be: Plex's Local
        Media Assets agent INGESTS theme.mp3 into its own metadata store at scan time (hence
        metadata://themes/<sha1> entries keyed by CONTENT hash), so mutating the sidecar
        likely does NOT change what Plex plays until a refresh re-runs the agent. The
        operator normalized -13.5 dB and heard no difference — that assumption was never
        verified, so verify it: pull the bytes Plex serves, measure them with ffmpeg, and
        compare against the canonical's stored loudness. Read-only wrt Plex and the theme.

        Threadpool: HTTP + decode + measure all block (class-12)."""
        _require_admin(request)
        from ..core.db import get_conn
        from ..core.loudness import measure_loudness

        try:
            body = await request.json()
        except Exception:  # noqa: BLE001 — defaults to the normalized row
            body = {}
        if not isinstance(body, dict):
            body = {}

        def _run():
            with get_conn(db) as conn:
                if body.get("tmdb_id") is not None and body.get("media_type"):
                    row = conn.execute(
                        "SELECT media_type, tmdb_id, section_id, edition_key, loudness_i, "
                        "  norm_state, norm_gain_db FROM local_files "
                        "WHERE media_type=? AND tmdb_id=? AND section_id=? AND edition_key=?",
                        (body["media_type"], body["tmdb_id"],
                         body.get("section_id") or "", body.get("edition_key") or ""),
                    ).fetchone()
                else:
                    row = conn.execute(
                        "SELECT media_type, tmdb_id, section_id, edition_key, loudness_i, "
                        "  norm_state, norm_gain_db FROM local_files "
                        "WHERE norm_state='normalized' ORDER BY norm_at DESC LIMIT 1"
                    ).fetchone()
                if row is None:
                    return {"ok": False, "error": "no normalized theme to check — "
                            "normalize one first"}
                # edition-scoped: the rating_key(s) for THIS edition only.
                # plex_items stores PLEX's media_type ('show'), local_files stores motif's
                # ('tv') — the same _PLEX_MT_MAP translation CLAUDE.md documents. Querying
                # with the raw local_files value silently matches nothing on every tv row.
                plex_mt = {"tv": "show", "collection": "collection"}.get(
                    row["media_type"], "movie")
                rks = [r["rating_key"] for r in conn.execute(
                    "SELECT rating_key FROM plex_items "
                    "WHERE media_type=? AND guid_tmdb=? AND section_id=? "
                    "  AND COALESCE(edition_key,'')=?",
                    (plex_mt, row["tmdb_id"], row["section_id"],
                     row["edition_key"] or ""),
                ).fetchall()]
            if not rks:
                return {"ok": False, "error": "no plex_items row for this theme — "
                        "run REFRESH PLEX first"}

            return _measure_plex_serving(settings, rk=str(rks[0]),
                                         canonical_i=row["loudness_i"],
                                         norm_gain_db=row["norm_gain_db"])

        return await run_in_threadpool(_run)

    @app.post("/api/admin/loudness/plex-reread")
    async def api_admin_loudness_plex_reread(
        request: Request, db: Path = Depends(get_db_path),
    ):
        """v0.51.173: can a Plex metadata REFRESH make Plex re-read a normalized sidecar?

        // WHAT IS PLEX SERVING? proved the gap on the real library (canonical -18.7,
        Plex still serving -5.15) — Plex plays its ingested copy, not the file. The
        remaining unknown is how to propagate. Two candidates:
          - REFRESH (this): re-run Local Media Assets so it re-ingests the changed
            sidecar. Native — keeps the row a sidecar row. UNPROVEN.
          - RE-UPLOAD: POST the normalized bytes to /themes. Plex content-dedupes by
            SHA-1 and auto-selects (PROVEN — v1.18.35 probe / v1.18.36 production), but
            it turns the entry into an upload:// one, changing the row's nature.

        Try the native one first and MEASURE the outcome rather than assume it — the
        assumption is what cost three tags. Refresh is async, so poll the measurement a
        few times before calling it. Threadpool (class-12); mutates nothing but Plex's
        own metadata."""
        _require_admin(request)
        from ..core.db import get_conn
        import time as _t   # module-local, matching the file's existing pattern

        def _run():
            with get_conn(db) as conn:
                row = conn.execute(
                    "SELECT media_type, tmdb_id, section_id, edition_key, loudness_i, "
                    "  norm_gain_db FROM local_files "
                    "WHERE norm_state='normalized' ORDER BY norm_at DESC LIMIT 1"
                ).fetchone()
                if row is None:
                    return {"ok": False, "error": "no normalized theme to check — "
                            "normalize one first"}
                plex_mt = {"tv": "show", "collection": "collection"}.get(
                    row["media_type"], "movie")
                rk_row = conn.execute(
                    "SELECT rating_key FROM plex_items "
                    "WHERE media_type=? AND guid_tmdb=? AND section_id=? "
                    "  AND COALESCE(edition_key,'')=? LIMIT 1",
                    (plex_mt, row["tmdb_id"], row["section_id"],
                     row["edition_key"] or ""),
                ).fetchone()
            if rk_row is None:
                return {"ok": False, "error": "no plex_items row for this theme"}
            rk = str(rk_row["rating_key"])

            before = _measure_plex_serving(settings, rk=rk,
                                           canonical_i=row["loudness_i"],
                                           norm_gain_db=row["norm_gain_db"])
            if before.get("serving_normalized"):
                return {"ok": True, "already_current": True, "refreshed": False,
                        "after": before,
                        "verdict": "Plex was already serving the normalized theme — "
                                   "nothing to do"}

            if not settings.plex_url or not settings.plex_token:
                return {"ok": False, "error": "Plex is not configured"}
            cfg = PlexConfig(
                url=settings.plex_url, token=settings.plex_token,
                movie_section=settings.plex_movie_section,
                tv_section=settings.plex_tv_section, enabled=True,
            )
            with PlexClient(cfg, plus_mode=settings.plus_equiv_mode) as plex:
                refreshed = plex.refresh(rk)

            # Plex's refresh is async — the agent re-scans in its own time. Poll the
            # MEASUREMENT rather than sleeping once and guessing.
            after = before
            for _ in range(_REREAD_POLLS):
                _t.sleep(_REREAD_POLL_S)
                after = _measure_plex_serving(settings, rk=rk,
                                              canonical_i=row["loudness_i"],
                                              norm_gain_db=row["norm_gain_db"])
                if after.get("serving_normalized"):
                    break

            worked = bool(after.get("serving_normalized"))
            if not worked:
                log.warning("loudness: a Plex refresh did NOT make rk=%s re-read the "
                            "normalized sidecar (Plex still at %s LUFS vs canonical %s) "
                            "— the re-upload path is the remaining candidate",
                            rk, after.get("plex_loudness_i"), row["loudness_i"])
            return {
                "ok": True, "already_current": False, "refreshed": refreshed,
                "waited_s": _REREAD_POLLS * _REREAD_POLL_S,
                "before_plex_loudness_i": before.get("plex_loudness_i"),
                "after": after,
                "refresh_propagates": worked,
                "verdict": ("a Plex refresh DID make it re-read the sidecar — refresh is "
                            "the propagation step"
                            if worked else
                            "a Plex refresh did NOT make it re-read the sidecar (it may "
                            "still be scanning; re-check // WHAT IS PLEX SERVING?). If it "
                            "stays put, re-upload is the remaining path"),
            }

        return await run_in_threadpool(_run)

    @app.post("/api/admin/loudness/plex-push")
    async def api_admin_loudness_plex_push(
        request: Request, db: Path = Depends(get_db_path),
    ):
        """v0.51.174: push the NORMALIZED canonical bytes to Plex, then re-measure.

        A `refresh?force=1` (+ /analyze fallback) provably does NOT propagate a CHANGED
        theme: measured on the real library, Plex sat at -5.15 LUFS against a -18.7
        canonical, same metadata://themes/<sha1> entry, minutes after the refresh. Plex's
        agent ADDS local assets it doesn't have (its own docs say "Added local media
        assets"); it won't replace a theme entry it already holds. So the sidecar is a
        dead letter for updates, and the only remaining path is the PROVEN one:

        POST the bytes to /library/metadata/{rk}/themes. Plex content-dedupes by SHA-1 —
        NEW bytes make a new entry and select it (v1.18.35 probe / v1.18.36 production).
        This also gives undo for free: re-uploading the ORIGINAL bytes hashes back to the
        EXISTING metadata:// entry, so Plex re-selects it rather than accumulating junk.

        Cost: the entry becomes upload://, so Plex-side flavour changes (motif's SRC axis
        is unaffected — it reads local_files/placements, not Plex's entry kind). Still a
        probe, not the production wiring: it MEASURES the outcome so the bulk design rests
        on a fact. Threadpool (class-12)."""
        _require_admin(request)
        from ..core.db import get_conn
        import time as _t

        def _run():
            with get_conn(db) as conn:
                row = conn.execute(
                    "SELECT media_type, tmdb_id, section_id, edition_key, file_path, "
                    "  loudness_i, norm_state, norm_gain_db FROM local_files "
                    "WHERE norm_state='normalized' ORDER BY norm_at DESC LIMIT 1"
                ).fetchone()
                if row is None:
                    return {"ok": False, "error": "no normalized theme to push — "
                            "normalize one first"}
                plex_mt = {"tv": "show", "collection": "collection"}.get(
                    row["media_type"], "movie")
                rk_row = conn.execute(
                    "SELECT rating_key FROM plex_items "
                    "WHERE media_type=? AND guid_tmdb=? AND section_id=? "
                    "  AND COALESCE(edition_key,'')=? LIMIT 1",
                    (plex_mt, row["tmdb_id"], row["section_id"],
                     row["edition_key"] or ""),
                ).fetchone()
                if rk_row is None:
                    return {"ok": False, "error": "no plex_items row for this theme"}
                fp = Path(row["file_path"])
                if not fp.is_absolute() and settings.themes_dir is None:
                    return {"ok": False, "error": "themes_dir is not configured"}
                theme = fp if fp.is_absolute() else (settings.themes_dir / row["file_path"])
            rk = str(rk_row["rating_key"])
            if not theme.is_file():
                return {"ok": False, "error": f"canonical file missing: {theme}"}
            audio = theme.read_bytes()
            # v0.51.175: report the SIZE on every path. v0.51.174 only reported bytes_sent
            # on success, so a real 500 arrived with the one number that diagnoses it
            # missing — Plex 500s on a theme POST over ~10MB (known since v1.21.99).
            size = len(audio)
            over_ceiling = size > THEME_UPLOAD_CEILING_BYTES
            if over_ceiling:
                return {
                    "ok": False, "rating_key": rk, "uploaded": False,
                    "bytes_sent": size, "ceiling_bytes": THEME_UPLOAD_CEILING_BYTES,
                    "over_ceiling": True,
                    "error": f"this theme is {size / 1048576:.1f}MB — over Plex's "
                             f"~{THEME_UPLOAD_CEILING_BYTES // 1048576}MB theme-upload "
                             f"ceiling, which Plex answers with HTTP 500. Re-upload "
                             f"cannot propagate a theme this large.",
                }

            if not settings.plex_url or not settings.plex_token:
                return {"ok": False, "error": "Plex is not configured"}
            cfg = PlexConfig(
                url=settings.plex_url, token=settings.plex_token,
                movie_section=settings.plex_movie_section,
                tv_section=settings.plex_tv_section, enabled=True,
            )
            before = _measure_plex_serving(settings, rk=rk,
                                           canonical_i=row["loudness_i"],
                                           norm_gain_db=row["norm_gain_db"])
            with PlexClient(cfg, plus_mode=settings.plus_equiv_mode) as plex:
                ok, status, body = plex.upload_theme(rating_key=rk, audio_bytes=audio)
            if not ok:
                return {"ok": False, "rating_key": rk, "uploaded": False,
                        "http_status": status, "bytes_sent": size,
                        "ceiling_bytes": THEME_UPLOAD_CEILING_BYTES,
                        "over_ceiling": False,
                        "error": f"Plex rejected the upload (HTTP {status}) at "
                                 f"{size / 1048576:.1f}MB — UNDER the "
                                 f"~{THEME_UPLOAD_CEILING_BYTES // 1048576}MB ceiling, so "
                                 f"this is not the size cap: {(body or '')[:200]}"}

            # Plex ingests the upload asynchronously — poll the MEASUREMENT, never trust
            # the 2xx (a POST that 200s while Plex keeps serving the old entry is the
            # fake-success this whole arc has been about).
            after = before
            for _ in range(_REREAD_POLLS):
                _t.sleep(_REREAD_POLL_S)
                after = _measure_plex_serving(settings, rk=rk,
                                              canonical_i=row["loudness_i"],
                                              norm_gain_db=row["norm_gain_db"])
                if after.get("serving_normalized"):
                    break

            worked = bool(after.get("serving_normalized"))
            if not worked:
                log.warning("loudness: re-upload did NOT make rk=%s serve the normalized "
                            "theme (Plex still %s vs canonical %s) — no propagation path "
                            "left; bulk must not proceed", rk,
                            after.get("plex_loudness_i"), row["loudness_i"])
            return {
                "ok": True, "rating_key": rk, "uploaded": True, "http_status": status,
                "bytes_sent": size, "ceiling_bytes": THEME_UPLOAD_CEILING_BYTES,
                "over_ceiling": False,
                "waited_s": _REREAD_POLLS * _REREAD_POLL_S,
                "before_plex_loudness_i": before.get("plex_loudness_i"),
                "before_entry_uri": before.get("entry_uri"),
                "after": after,
                "upload_propagates": worked,
                "verdict": ("re-upload WORKS — Plex now serves the normalized theme. This "
                            "is the propagation step for per-item + bulk."
                            if worked else
                            "re-upload did NOT flip Plex either (it may still be "
                            "ingesting — re-check // WHAT IS PLEX SERVING?). If it stays "
                            "put, there is no propagation path and bulk must not proceed."),
            }

        return await run_in_threadpool(_run)

    @app.post("/api/admin/loudness/theme-lock-probe")
    async def api_admin_loudness_theme_lock_probe(
        request: Request, db: Path = Depends(get_db_path),
    ):
        """v0.51.178: is Plex's `theme` field LOCKED, and does an unlock actually work?

        The open question. v0.51.173 measured a refresh failing to re-read a changed
        sidecar. v0.51.177 then concluded the lock was not the cause — off an unlock PUT
        that returned 200. But a 200 is not evidence the flag moved: that unlock uses the
        metadata-endpoint shape, while Plex's field-lock API conventionally goes through
        the SECTION endpoint with type= + id=, so it may have been a silent no-op. If it
        WAS, then the theme field was locked the whole time, the lock explains the dead
        refresh, and unlock+refresh is an untested, ceiling-free path to all 2,821 themes.
        Reporting a probe off a status code is the mistake this arc keeps repeating — so
        this reads the flag instead.

        Two rows, because they answer different halves:
          - CONTROL: a row motif has never normalized or uploaded to. Its lock state is
            the NATURAL state of a sidecar-ingested theme — i.e. what was true when
            v0.51.173's refresh ran. This is the one that decides the question.
          - AUDITION: the normalized row. Contaminated (v0.51.177 deleted, "unlocked" and
            pushed it), so it can't answer the natural-state question — but it's the
            subject for the shape test.

        The shape test flips the flag, RE-READS to see if it actually moved, then flips it
        back and re-reads again to confirm the restore. Self-restoring: the probe leaves
        the field as it found it. Read-only wrt the theme bytes and Plex's selection —
        nothing here can strand an item the way delete+re-detect did. Threadpool
        (class-12)."""
        _require_admin(request)
        from ..core.db import get_conn

        # Plex's section endpoint keys the lock by item type, not by media_type string.
        plex_type_of = {"movie": 1, "show": 2, "collection": 18}

        def _run():
            with get_conn(db) as conn:
                audition = conn.execute(
                    "SELECT media_type, tmdb_id, section_id, edition_key FROM local_files "
                    "WHERE norm_state='normalized' ORDER BY norm_at DESC LIMIT 1"
                ).fetchone()
                # v0.51.179: SAMPLE untouched hardlink-placed rows, resolving the
                # rating_key IN SQL. v0.51.178 took ONE candidate (ORDER BY tmdb_id
                # LIMIT 1) and gave up if it had no plex_items row — which on a real
                # library is guaranteed to fail: synthetic orphan ids are NEGATIVE
                # (adopt.py mints `MIN(tmdb_id) - 1`), so the lowest tmdb_id row is
                # always an orphan, and an orphan by definition has no Plex row. The
                # control never had a chance. Resolve in the JOIN and take several, so
                # one odd row can't decide the question either.
                controls = conn.execute(
                    "SELECT lf.media_type, lf.tmdb_id, lf.section_id, lf.edition_key, "
                    "       pi.rating_key, pi.title "
                    "FROM local_files lf "
                    "JOIN placements p "
                    "  ON p.media_type=lf.media_type AND p.tmdb_id=lf.tmdb_id "
                    " AND p.section_id=lf.section_id "
                    " AND COALESCE(p.edition_key,'')=COALESCE(lf.edition_key,'') "
                    " AND p.placement_kind='hardlink' "
                    "JOIN plex_items pi "
                    "  ON pi.media_type = CASE lf.media_type WHEN 'tv' THEN 'show' "
                    "       WHEN 'collection' THEN 'collection' ELSE 'movie' END "
                    " AND pi.guid_tmdb = lf.tmdb_id AND pi.section_id = lf.section_id "
                    " AND COALESCE(pi.edition_key,'') = COALESCE(lf.edition_key,'') "
                    "WHERE lf.norm_state IS NULL AND lf.tmdb_id > 0 "
                    "ORDER BY lf.tmdb_id LIMIT ?", (_CONTROL_SAMPLE,)
                ).fetchall()
                # v0.51.179: v0.51.178's one error message covered two different causes
                # ("no such rows" vs "rows existed but none resolved"), so it could not
                # say which had happened. Count them apart.
                candidate_rows = conn.execute(
                    "SELECT COUNT(*) c FROM local_files lf JOIN placements p "
                    "  ON p.media_type=lf.media_type AND p.tmdb_id=lf.tmdb_id "
                    " AND p.section_id=lf.section_id "
                    " AND COALESCE(p.edition_key,'')=COALESCE(lf.edition_key,'') "
                    " AND p.placement_kind='hardlink' "
                    "WHERE lf.norm_state IS NULL AND lf.tmdb_id > 0"
                ).fetchone()["c"]

                def _rk(row):
                    if row is None:
                        return None
                    plex_mt = {"tv": "show", "collection": "collection"}.get(
                        row["media_type"], "movie")
                    got = conn.execute(
                        "SELECT rating_key FROM plex_items "
                        "WHERE media_type=? AND guid_tmdb=? AND section_id=? "
                        "  AND COALESCE(edition_key,'')=? LIMIT 1",
                        (plex_mt, row["tmdb_id"], row["section_id"],
                         row["edition_key"] or ""),
                    ).fetchone()
                    return (str(got["rating_key"]), plex_mt) if got else (None, plex_mt)

                audition_rk, audition_mt = _rk(audition) if audition else (None, None)

            if not settings.plex_url or not settings.plex_token:
                return {"ok": False, "error": "Plex is not configured"}
            cfg = PlexConfig(
                url=settings.plex_url, token=settings.plex_token,
                movie_section=settings.plex_movie_section,
                tv_section=settings.plex_tv_section, enabled=True,
            )

            out: dict = {"ok": True}
            with PlexClient(cfg, plus_mode=settings.plus_equiv_mode) as plex:
                # ── the control: the natural lock state of untouched sidecar rows
                rows = []
                for cr in controls:
                    rk = str(cr["rating_key"])
                    locks = plex.get_field_locks(rating_key=rk)
                    got = plex.get_themes(rating_key=rk)
                    b = got.get("body")
                    meta = ((b.get("MediaContainer") or {}).get("Metadata") or []) \
                        if isinstance(b, dict) else []
                    sel = next((m for m in meta if m.get("selected")), None)
                    entry = str(sel.get("ratingKey") or sel.get("key")) if sel else None
                    rows.append({
                        "rating_key": rk, "tmdb_id": cr["tmdb_id"],
                        "media_type": cr["media_type"], "title": cr["title"],
                        "theme_locked": locks["theme_locked"],
                        "locked_fields": locks["locked_fields"],
                        "read_error": locks["error"],
                        # a metadata:// entry is what proves this row really is
                        # sidecar-ingested and not something motif already uploaded to —
                        # an upload:// row's lock says nothing about the natural state.
                        "selected_entry": entry,
                        "is_sidecar_entry": bool(entry and entry.startswith("metadata://")),
                    })
                sidecar = [r for r in rows
                           if r["is_sidecar_entry"] and r["theme_locked"] is not None]
                locked_n = sum(1 for r in sidecar if r["theme_locked"])
                out["control"] = {
                    "candidate_rows": candidate_rows, "sampled": len(rows), "rows": rows,
                    "sidecar_rows_read": len(sidecar), "sidecar_rows_locked": locked_n,
                    # None when nothing readable — an unread flag decides nothing.
                    # Conservative: ANY locked sidecar row keeps the lock alive as an
                    # explanation rather than closing the door early.
                    "theme_locked": (None if not sidecar else locked_n > 0),
                }
                if not rows:
                    out["control"]["error"] = (
                        "no untouched hardlink-placed row resolved to a plex_items "
                        "rating_key" if candidate_rows else
                        "no untouched hardlink-placed rows exist at all")

                # ── the audition row + the shape test
                if not audition_rk:
                    out["audition"] = {"error": "no normalized theme — normalize one "
                                                "first to run the shape test"}
                    out["verdict"] = _lock_verdict(out["control"].get("theme_locked"),
                                                   None)
                    return out

                before = plex.get_field_locks(rating_key=audition_rk)
                out["audition"] = {
                    "rating_key": audition_rk,
                    "theme_locked": before["theme_locked"],
                    "locked_fields": before["locked_fields"],
                    "read_error": before["error"],
                    "note": "contaminated by v0.51.177 (deleted + unlocked + pushed) — "
                            "the CONTROL row is what answers the natural-state question",
                }
                original = before["theme_locked"]
                if original is None:
                    out["shape_test"] = {"error": "could not read the flag, so nothing "
                                                  "here could be verified — no shape test"}
                    out["verdict"] = _lock_verdict(out["control"].get("theme_locked"),
                                                   None)
                    return out

                want = not original
                tried, working = [], None
                for shape in ("metadata", "section"):
                    status = plex.set_theme_field_lock(
                        rating_key=audition_rk, locked=want, shape=shape,
                        section_id=audition["section_id"],
                        plex_type=plex_type_of.get(audition_mt),
                    )
                    after = plex.get_field_locks(rating_key=audition_rk)["theme_locked"]
                    moved = after is not None and after == want
                    tried.append({"shape": shape, "http_status": status,
                                  "flag_after": after, "flag_moved": moved})
                    if moved:
                        working = shape
                        break

                # restore with whatever actually worked; leaving the operator's field
                # flipped is a side effect nobody asked for.
                restored = None
                if working:
                    plex.set_theme_field_lock(
                        rating_key=audition_rk, locked=original, shape=working,
                        section_id=audition["section_id"],
                        plex_type=plex_type_of.get(audition_mt),
                    )
                    restored = plex.get_field_locks(
                        rating_key=audition_rk)["theme_locked"]
                    if restored != original:
                        log.warning("theme-lock-probe: rk=%s could NOT be restored to "
                                    "locked=%s (now %s) — the probe changed Plex state "
                                    "it could not put back", audition_rk, original,
                                    restored)

                out["shape_test"] = {
                    "original_locked": original, "flipped_to": want,
                    "tried": tried, "working_shape": working,
                    "restored_locked": restored,
                    "restored_ok": (restored == original) if working else True,
                }
                if working is None:
                    log.warning("theme-lock-probe: NEITHER unlock shape moved the theme "
                                "flag on rk=%s (statuses %s) — v0.51.177's unlock was a "
                                "silent no-op and its 200 meant nothing", audition_rk,
                                [t["http_status"] for t in tried])
                out["verdict"] = _lock_verdict(out["control"].get("theme_locked"), working)
            return out

        return await run_in_threadpool(_run)

    @app.post("/api/admin/loudness/plex-redetect")
    async def api_admin_loudness_plex_redetect(
        request: Request, db: Path = Depends(get_db_path),
    ):
        """v0.51.177: the only CEILING-FREE propagation candidate — make Plex treat the
        changed sidecar as NEW so Local Media Assets ingests it again.

        Where this sits: refresh alone is measured dead (v0.51.173). Re-upload works but
        Plex 500s over ~10MB, which is 82 of this library's 2,821 themes (v0.51.176). If
        this path works it beats re-upload everywhere: all 2,821 covered, zero bandwidth,
        and the entry stays metadata:// instead of flipping to upload://.

        The chain, and every link's status:
          1. DELETE singular /theme  — clears the active selection (PROVEN, v1.18.33).
          2. UNLOCK theme.locked=0   — the DELETE also LOCKS the field (documented in
             delete_collection_theme). A locked field is exactly what stops an agent from
             writing it, so without this the refresh could never work. UNPROVEN.
          3. refresh?force=1         — re-run Local Media Assets. It ingests assets it
             LACKS, and after step 1 it lacks one. UNPROVEN in this combination.
          4. RE-MEASURE what Plex serves — the verdict. Never the status codes.

        SAFETY: only picks an UNDER-ceiling row, so if this strands Plex (serving its own
        cloud theme, or nothing) // PUSH NORMALIZED TO PLEX is available as recovery. The
        canonical file is never touched. Threadpool (class-12)."""
        _require_admin(request)
        from ..core.db import get_conn
        import time as _t

        def _run():
            with get_conn(db) as conn:
                row = conn.execute(
                    "SELECT media_type, tmdb_id, section_id, edition_key, loudness_i, "
                    "  norm_state, norm_gain_db, file_size FROM local_files "
                    "WHERE norm_state='normalized' ORDER BY norm_at DESC LIMIT 1"
                ).fetchone()
                if row is None:
                    return {"ok": False, "error": "no normalized theme to test — "
                            "normalize one first"}
                plex_mt = {"tv": "show", "collection": "collection"}.get(
                    row["media_type"], "movie")
                rk_row = conn.execute(
                    "SELECT rating_key FROM plex_items "
                    "WHERE media_type=? AND guid_tmdb=? AND section_id=? "
                    "  AND COALESCE(edition_key,'')=? LIMIT 1",
                    (plex_mt, row["tmdb_id"], row["section_id"],
                     row["edition_key"] or ""),
                ).fetchone()
            if rk_row is None:
                return {"ok": False, "error": "no plex_items row for this theme"}
            rk = str(rk_row["rating_key"])

            # refuse to gamble on a row we couldn't recover: re-upload is the only undo
            # for a stranded selection, and it can't carry an over-ceiling theme.
            size = row["file_size"]
            if size is not None and size > THEME_UPLOAD_CEILING_BYTES:
                return {"ok": False, "rating_key": rk, "bytes": size,
                        "error": f"this theme is {size / 1048576:.1f}MB — OVER the upload "
                                 f"ceiling, so re-upload could not recover a stranded "
                                 f"selection. Test this path on an under-ceiling theme."}

            if not settings.plex_url or not settings.plex_token:
                return {"ok": False, "error": "Plex is not configured"}
            cfg = PlexConfig(
                url=settings.plex_url, token=settings.plex_token,
                movie_section=settings.plex_movie_section,
                tv_section=settings.plex_tv_section, enabled=True,
            )
            before = _measure_plex_serving(settings, rk=rk,
                                           canonical_i=row["loudness_i"],
                                           norm_gain_db=row["norm_gain_db"])
            if before.get("serving_normalized"):
                return {"ok": True, "already_current": True, "after": before,
                        "verdict": "Plex was already serving the normalized theme — "
                                   "nothing to do"}

            # the DELETE leaves the collection's entries in place and only clears the
            # `selected` flag (v1.18.33). _measure_plex_serving falls back to meta[0]
            # when nothing is selected, so its number alone can't tell "re-ingested and
            # selected" from "nothing selected, here's entry 0" — and entry 0 could be a
            # NEW un-selected re-ingest, which would read as a false success. Measure the
            # selection state directly rather than inferring it from the loudness.
            def _selection():
                with PlexClient(cfg, plus_mode=settings.plus_equiv_mode) as p:
                    got = p.get_themes(rating_key=rk)
                if not got.get("ok"):
                    return None, 0
                b = got.get("body")
                meta = ((b.get("MediaContainer") or {}).get("Metadata") or []) \
                    if isinstance(b, dict) else []
                sel = next((m for m in meta if m.get("selected")), None)
                return (str(sel.get("ratingKey") or sel.get("key")) if sel else None,
                        len(meta))

            entry_before, _ = _selection()
            with PlexClient(cfg, plus_mode=settings.plus_equiv_mode) as plex:
                deleted = plex.delete_theme(rating_key=rk)
                # the DELETE locks theme; an agent won't write a locked field.
                unlock_status = plex.set_theme_field_lock(rating_key=rk, locked=False)
                refreshed = plex.refresh(rk)

            after = before
            entry_after, entries_after = _selection()
            for _ in range(_REREAD_POLLS):
                _t.sleep(_REREAD_POLL_S)
                entry_after, entries_after = _selection()
                if entry_after is None:
                    continue          # nothing selected yet — the scan hasn't landed
                after = _measure_plex_serving(settings, rk=rk,
                                              canonical_i=row["loudness_i"],
                                              norm_gain_db=row["norm_gain_db"])
                if after.get("serving_normalized"):
                    break

            # both halves required: a selected entry AND it measures as the canonical.
            worked = bool(entry_after) and bool(after.get("serving_normalized"))
            stranded = entry_after is None
            if not worked:
                log.warning("loudness: delete+re-detect did NOT make rk=%s serve the "
                            "normalized sidecar (deleted=%s unlock=%s refreshed=%s; "
                            "selected entry %s; Plex now %s vs canonical %s). Recover "
                            "with // PUSH NORMALIZED TO PLEX%s", rk, deleted,
                            unlock_status, refreshed, entry_after,
                            after.get("plex_loudness_i"), row["loudness_i"],
                            " — NOTHING is selected, this item has no theme right now"
                            if stranded else ".")
            return {
                "ok": True, "already_current": False, "rating_key": rk,
                "deleted_association": deleted,
                "unlock_http_status": unlock_status,
                "refreshed": refreshed,
                "waited_s": _REREAD_POLLS * _REREAD_POLL_S,
                "before_plex_loudness_i": before.get("plex_loudness_i"),
                "selected_entry_before": entry_before,
                "selected_entry_after": entry_after,
                "entries_after": entries_after,
                "after": after,
                "redetect_propagates": worked,
                "plex_has_no_theme_now": stranded,
                "verdict": ("delete + re-detect WORKS — Plex re-ingested the normalized "
                            "sidecar. This is the propagation step: no ceiling, no "
                            "upload, all 2,821 themes reachable."
                            if worked else
                            ("delete + re-detect left this item with NO theme selected "
                             "— Plex did not re-ingest the sidecar. Recover now with "
                             "// PUSH NORMALIZED TO PLEX."
                             if stranded else
                             "delete + re-detect did NOT make Plex serve the normalized "
                             "sidecar (it may still be scanning — re-check // WHAT IS "
                             "PLEX SERVING?). If it stays put, re-upload is the "
                             "mechanism for the 2,739 under-ceiling themes.")),
            }

        return await run_in_threadpool(_run)

    @app.post("/api/admin/loudness/undo-one")
    async def api_admin_loudness_undo_one(
        request: Request, db: Path = Depends(get_db_path),
    ):
        """v0.51.168: reverse a per-item normalize via the MP3GAIN_UNDO tag (mp3gain -u)
        and re-measure. Verifies the restore is bit-exact against the pre-normalize
        sha (norm_orig_sha256). Edition-scoped; the body echoes the row identity from
        normalize-one. Threadpool (class-12)."""
        _require_admin(request)
        from ..core.loudness_apply import undo_file
        from ..core.db import get_conn
        from ..core.events import now_iso

        try:
            body = await request.json()
        except Exception:  # noqa: BLE001
            body = {}
        if not isinstance(body, dict):
            body = {}   # v0.51.169: a list/str body would AttributeError on .get → 500
        want_mt = body.get("media_type")
        want_id = body.get("tmdb_id")
        if not (want_mt and want_id is not None):
            return {"ok": False, "error": "row identity (media_type, tmdb_id, section_id, "
                    "edition_key) is required to undo"}
        sec = body.get("section_id") or ""
        edn = body.get("edition_key") or ""

        def _run():
            with get_conn(db) as conn:
                row = conn.execute(
                    "SELECT lf.media_type, lf.tmdb_id, lf.section_id, lf.edition_key, "
                    "  lf.file_path, lf.norm_state, lf.norm_orig_sha256, "
                    "  lf.norm_orig_pcm_sha256, t.title "
                    "FROM local_files lf "
                    "LEFT JOIN themes t ON t.media_type=lf.media_type AND t.tmdb_id=lf.tmdb_id "
                    "WHERE lf.media_type=? AND lf.tmdb_id=? AND lf.section_id=? "
                    "  AND lf.edition_key=?",
                    (want_mt, want_id, sec, edn),
                ).fetchone()
                if row is None:
                    return {"ok": False, "error": "row not found"}
                if row["norm_state"] != "normalized":
                    return {"ok": False, "error": "row is not normalized — nothing to undo"}
                fp = Path(row["file_path"])
                # v0.51.169: themes_dir is None until configured — guard the join (500).
                if not fp.is_absolute() and settings.themes_dir is None:
                    return {"ok": False, "error": "themes_dir is not configured — set it "
                            "in Settings first"}
                theme = fp if fp.is_absolute() else (settings.themes_dir / row["file_path"])
                expect = row["norm_orig_sha256"]
                expect_pcm = row["norm_orig_pcm_sha256"]

            res = undo_file(theme, expect_sha=expect, expect_pcm_sha=expect_pcm)
            if not res["ok"]:
                return {"ok": False, "error": res.get("error") or "undo failed",
                        "title": row["title"]}
            measured_sha = res["new_sha"] if res["new_i"] is not None else None
            measured_at = now_iso() if res["new_i"] is not None else None
            with get_conn(db) as wconn:
                wconn.execute(
                    "UPDATE local_files SET loudness_i=?, loudness_tp=?, loudness_lra=?, "
                    "  loudness_measured_at=?, loudness_measured_sha256=?, file_sha256=?, "
                    "  norm_state=NULL, norm_gain_db=NULL, norm_target=NULL, norm_at=NULL, "
                    "  norm_orig_sha256=NULL, norm_orig_pcm_sha256=NULL "
                    "WHERE media_type=? AND tmdb_id=? AND section_id=? AND edition_key=?",
                    (res["new_i"], res["new_tp"], res["new_lra"], measured_at, measured_sha,
                     res["new_sha"], row["media_type"], row["tmdb_id"],
                     row["section_id"], row["edition_key"]),
                )
                wconn.commit()
            # v0.51.170: audio_restored is the verdict; file_bit_exact is informational
            # (mp3gain's APE tag means a correct restore is NOT byte-identical).
            return {"ok": True, "audio_restored": res["audio_restored"],
                    "file_bit_exact": res["file_bit_exact"],
                    "title": row["title"] or f'{row["media_type"]}/{row["tmdb_id"]}',
                    "restored": {"loudness_i": res["new_i"], "true_peak": res["new_tp"]}}

        return await run_in_threadpool(_run)

    @app.post("/api/admin/orphan-scan/cleanup-dead-rk")
    async def api_admin_orphan_cleanup_dead_rk(
        request: Request,
        media_type: str = Query(...),
        tmdb_id: int = Query(...),
        section_id: str = Query(...),
        rating_key: str = Query(...),
        edition_key: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        """v0.50.11: drop a STALE plex_upload placement whose rating_key is dead
        — Plex removed + re-added the item under a new rk, so its /themes 404s
        and there's no live plex_items row for it (the user's LotR Collection,
        rk 579643: PLEX_FETCH_FAILED / HTTP 404, where PROBE can only ever
        re-404). Wired to the orphan dashboard's // CLEAN UP button.

        Conservative + Plex-non-mutating: re-verifies the rk is GENUINELY dead
        (no live plex_items row AND Plex's /themes still fails) before deleting,
        refusing with 409 if it came back. Touches ONLY motif's placement row —
        no Plex write, no canonical deletion — so re-placing fresh later (to the
        new rk) works. Off the event loop (class 12: the get_themes re-check)."""
        _require_admin(request)
        if not settings.plex_enabled or not settings.plex_token:
            raise HTTPException(
                status_code=503, detail="Plex disabled or token missing")

        def _cleanup():
            from ..core.plex import PlexClient, PlexConfig
            # The authoritative "this placement's theme is dead" signal is a
            # FAILED /themes — NOT plex_items presence. v0.50.13: dropped the
            # plex_items-liveness refusal. the user's LotR Collection (rk 579643)
            # still has a STALE plex_items row (enumerated once, the reaper never
            # pruned the collection) yet its /themes genuinely 404s — and the
            # v0.50.11 guard refused cleanup with HTTP 409 for exactly that row.
            # A placement claiming an uploaded theme that Plex's /themes 404s is
            # stale regardless of a lingering plex_items row; the live /themes
            # re-check below is the real gate (refuses only if it now serves).
            cfg = PlexConfig(
                url=settings.plex_url, token=settings.plex_token,
                movie_section=settings.plex_movie_section,
                tv_section=settings.plex_tv_section, enabled=True)
            with PlexClient(cfg, plus_mode=settings.plus_equiv_mode) as plex:
                resp = plex.get_themes(rating_key=str(rating_key))
            if resp.get("ok"):
                return {"ok": False, "detail": (
                    "Plex now serves that rating_key — re-probe instead of "
                    "cleaning up")}
            # v0.51.13 (audit #10): DEAD means a definitive 404 — a transport
            # error (get_themes returns ok=False with http_status=None on any
            # exception) or a 5xx must NOT fall through to the DELETE. A scan
            # taken while Plex restarts flags every plex_upload placement as
            # plex_fetch_failed, and pre-fix a CLEAN UP click during the outage
            # deleted LIVE placements' rows — the exact wrong-write the v0.50.11
            # guard was built to refuse.
            if resp.get("http_status") != 404:
                return {"ok": False, "detail": (
                    "Plex unreachable / indeterminate (http_status="
                    f"{resp.get('http_status')}) — not cleaning up; retry when "
                    "Plex is back")}
            # (c) Genuinely dead — drop ONLY the stale placement row(s).
            ek_sql = " AND COALESCE(edition_key, '') = ?" if edition_key is not None else ""
            params: list = [media_type, tmdb_id, section_id, str(rating_key)]
            if edition_key is not None:
                params.append(edition_key)
            with get_conn(db) as conn:
                cur = conn.execute(
                    "DELETE FROM placements WHERE media_type = ? AND tmdb_id = ? "
                    "AND section_id = ? AND plex_rating_key = ?" + ek_sql,
                    params)
                dropped = cur.rowcount
                conn.commit()
            return {"ok": True, "dropped": dropped}

        result = await run_in_threadpool(_cleanup)
        if not result.get("ok"):
            raise HTTPException(status_code=409, detail=result.get("detail"))
        try:
            log_event(
                db, level="info", component="orphan_scan",
                message=f"Dead-rk placement cleaned up (rk={rating_key})",
                detail={"media_type": media_type, "tmdb_id": tmdb_id,
                        "section_id": section_id, "rating_key": str(rating_key),
                        "dropped": result.get("dropped")})
        except Exception:
            pass
        return result

    @app.post("/api/admin/orphan-scan/item")
    async def api_admin_orphan_scan_item(
        request: Request,
        media_type: str = Query(...),
        tmdb_id: int = Query(...),
        section_id: str = Query(...),
        # v1.22.81: the finding's edition — without it a two-edition
        # plex_upload title's rows were indistinguishable (PROBE
        # patched the first match). None = legacy 3-tuple keying.
        edition_key: str | None = Query(None),
        db: Path = Depends(get_db_path),
    ):
        """v1.22.59: re-probe ONE plex_upload placement. The orphans page
        per-row // PROBE button (and the post-action row refresh) used to
        re-run the FULL library scan — the user: "the reprobe action makes
        it do a full rescan; is it possible that reprobe only checks the
        specific item being reprobed." This runs scan_one_placement (the
        extracted per-row body of the full scan — same classification)
        for just this row, off the event loop (class 12).

        Returns {ok, finding} — or {ok, finding: None, placement_gone:
        True} when the placement no longer exists (e.g. after PURGE or
        LET PLEX SERVE removed it), so the page can drop the row. Also
        patches the row into the cached _ORPHAN_SCAN_STATE findings so
        a page reload reflects the re-probe without a fresh full scan."""
        _require_admin(request)
        if not settings.plex_enabled or not settings.plex_token:
            raise HTTPException(
                status_code=503, detail="Plex disabled or token missing")

        def _probe_one():
            from ..core.orphan_scan import scan_one_placement, summarize
            from ..core.plex import PlexClient, PlexConfig
            _osk_sql = (" AND COALESCE(edition_key, '') = ?"
                        if edition_key is not None else "")
            _osk_args = ((edition_key,) if edition_key is not None
                         else ())
            with get_conn(db) as conn:
                exists = conn.execute(
                    "SELECT 1 FROM placements "
                    "WHERE placement_kind = 'plex_upload' "
                    "  AND media_type = ? AND tmdb_id = ? "
                    "  AND section_id = ?" + _osk_sql + " LIMIT 1",
                    (media_type, tmdb_id, section_id, *_osk_args),
                ).fetchone()
            if exists is None:
                return None
            cfg = PlexConfig(
                url=settings.plex_url, token=settings.plex_token,
                movie_section=settings.plex_movie_section,
                tv_section=settings.plex_tv_section, enabled=True,
            )
            with PlexClient(cfg, plus_mode=settings.plus_equiv_mode) as plex:
                finding = scan_one_placement(
                    db, plex, media_type, tmdb_id, section_id,
                    edition_key=edition_key,
                    themes_dir=settings.themes_dir,
                )
            # Patch the cached full-scan result in place so a reload of
            # the orphans page shows this row's fresh state. Only when a
            # completed scan is cached — never while one is running (the
            # worker thread owns findings then).
            with _ORPHAN_SCAN_LOCK:
                cached = _ORPHAN_SCAN_STATE
                if (cached.get("status") == "done"
                        and isinstance(cached.get("findings"), list)):
                    fl = cached["findings"]
                    for i, f in enumerate(fl):
                        if (f.get("media_type") == media_type
                                and f.get("tmdb_id") == tmdb_id
                                and f.get("section_id") == section_id
                                # v1.22.81: edition is identity.
                                and (edition_key is None
                                     or (f.get("edition_key") or "")
                                     == edition_key)):
                            fl[i] = finding
                            break
                    else:
                        fl.append(finding)
                    cached["summary"] = summarize(fl)
            return finding

        finding = await run_in_threadpool(_probe_one)
        if finding is None:
            # Placement gone (purged / unplaced since the scan) — tell
            # the page to drop the row; also drop it from the cache.
            def _drop_cached():
                from ..core.orphan_scan import summarize
                with _ORPHAN_SCAN_LOCK:
                    cached = _ORPHAN_SCAN_STATE
                    if (cached.get("status") == "done"
                            and isinstance(cached.get("findings"), list)):
                        cached["findings"] = [
                            f for f in cached["findings"]
                            if not (f.get("media_type") == media_type
                                    and f.get("tmdb_id") == tmdb_id
                                    and f.get("section_id") == section_id
                                    # v1.22.81: edition is identity.
                                    and (edition_key is None
                                         or (f.get("edition_key") or "")
                                         == edition_key))
                        ]
                        cached["summary"] = summarize(cached["findings"])
                        cached["total"] = len(cached["findings"])
            _drop_cached()
            return {"ok": True, "finding": None, "placement_gone": True}
        return {"ok": True, "finding": finding, "placement_gone": False}

    @app.post("/api/admin/placements/rekey-mislabeled")
    async def api_admin_rekey_mislabeled_placements(
        request: Request,
        # v1.24.4: dry-run by default. ?apply=true writes the re-keys.
        apply: bool = Query(False),
        db: Path = Depends(get_db_path),
    ):
        """v1.24.4: one-shot cleanup for plex_upload placements whose
        edition_key disagrees with the edition of their own plex_rating_key —
        the ''-as-falsy place-path residue the v1.24.3 orphan scan surfaced
        (Amadeus Director's Cut etc.: placement keyed '' but rk is a named cut).
        Re-labels each placement to the edition its rk genuinely belongs to
        (per plex_items). Tracking-only — never touches Plex or the on-disk
        theme, leaves the '' local_files row (the IN(edition,'') fallback
        bridges it), and skips re-keys whose target PK slot is occupied.

        Dry-run by default; POST ?apply=true to write. Off the event loop."""
        _require_admin(request)

        def _run():
            from ..core.orphan_scan import rekey_mislabeled_placements
            return rekey_mislabeled_placements(db, dry_run=not apply)

        # v1.24.5: a one-shot manual op deserves an actionable error, not an
        # opaque 500. The intra-batch dedup makes an IntegrityError unlikely,
        # but a concurrent worker write (TOCTOU on the clash check) or an
        # exhausted BEGIN IMMEDIATE retry can still surface — tell the operator
        # which so they know whether to retry.
        try:
            return await run_in_threadpool(_run)
        except sqlite3.IntegrityError as e:
            return {"ok": False,
                    "reason": f"placement PK collision during apply: {e}"}
        except sqlite3.OperationalError as e:
            return {"ok": False,
                    "reason": f"database busy — retry in a quiet window: {e}"}

    @app.get("/healthz")
    def healthz(request: Request):
        # v1.24.21: real liveness check so the Docker healthcheck means
        # something (was an unconditional 200). Sync def → FastAPI runs it in
        # the threadpool, so the blocking SQLite read is safe + exempt from the
        # async-no-blocking lint. Deliberately LIVENESS only: it does NOT ping
        # Plex (an external dep being down must not make Docker kill us).
        checks: dict[str, bool] = {}
        try:
            # v1.24.23: reuse get_conn (closes in finally + busy_timeout=30000)
            # instead of a raw sqlite3.connect(timeout=2.0) that leaked the
            # connection and could false-503 under a heavy-write window — the
            # exact flap a liveness probe must avoid.
            with get_conn(settings.db_path) as _c:
                _c.execute("SELECT 1")
            checks["db"] = True
        except Exception:  # noqa: BLE001 — any DB failure is unhealthy
            checks["db"] = False
        # Worker + scheduler liveness only when main.py wired them onto
        # app.state (skipped under TestClient, which builds create_app alone).
        wt = getattr(request.app.state, "worker_threads", None)
        if wt is not None:
            checks["worker"] = any(t.is_alive() for t in wt)
        sch = getattr(request.app.state, "scheduler", None)
        if sch is not None:
            checks["scheduler"] = bool(getattr(sch, "running", False))
        healthy = all(checks.values())
        return JSONResponse(
            {"status": "ok" if healthy else "degraded", "checks": checks},
            status_code=200 if healthy else 503,
        )

    return app
